```jac
"""Hiking trail: plain waypoints with no data, used purely as stops.

The trail is a chain of bare waypoints between a trailhead and a
summit. The waypoints carry no fields at all -- all the interesting
state (how many stops were made) lives on the hiker walker.
"""

node Waypoint { }

walker Hiker {
    has stops: int = 0;

    can start with Root entry {
        print("Leaving the trailhead");
        visit [-->];
    }

    can pass_through with Waypoint entry {
        self.stops += 1;
        print(f"Passed stop #{self.stops}");
        visit [-->];
    }

    can done with Waypoint exit {
        if self.stops >= 3 {
            print(f"Trail complete after {self.stops} waypoints");
        }
    }
}

with entry {
    root ++> Waypoint() ++> Waypoint() ++> Waypoint();
    root spawn Hiker();
}
```

jac_tests:
import io;
import from contextlib { redirect_stdout }

test "hiker counts stops and prints each one" {
    root ++> Waypoint() ++> Waypoint() ++> Waypoint() ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Leaving the trailhead" in out, f"missing trailhead line: {out!r}";
    assert "Passed stop #1" in out, f"missing stop #1: {out!r}";
    assert "Passed stop #2" in out, f"missing stop #2: {out!r}";
    assert "Passed stop #3" in out, f"missing stop #3: {out!r}";
    assert "Passed stop #4" in out, f"missing stop #4: {out!r}";
    assert "Trail complete after 4 waypoints" in out, f"missing completion: {out!r}";

    assert res.stops == 4, f"expected 4 stops, got {res.stops}";
}

test "hiker does not complete with fewer than three waypoints" {
    root ++> Waypoint() ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Leaving the trailhead" in out, f"missing trailhead line: {out!r}";
    assert "Passed stop #1" in out, f"missing stop #1: {out!r}";
    assert "Passed stop #2" in out, f"missing stop #2: {out!r}";
    assert "Trail complete" not in out, f"should not print completion: {out!r}";

    assert res.stops == 2, f"expected 2 stops, got {res.stops}";
}

test "hiker follows only the outgoing chain from each waypoint" {
    a = Waypoint();
    b = Waypoint();
    c = Waypoint();
    d = Waypoint();
    root ++> a ++> b ++> c ++> d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stops == 4, f"expected 4 stops, got {res.stops}";
    assert "Trail complete after 4 waypoints" in out, f"missing completion: {out!r}";
}

test "hiker stops immediately when there are no waypoints" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Leaving the trailhead" in out, f"missing trailhead line: {out!r}";
    assert "Passed stop" not in out, f"no stops should have been printed: {out!r}";
    assert "Trail complete" not in out, f"no completion expected: {out!r}";

    assert res.stops == 0, f"expected 0 stops, got {res.stops}";
}

test "completion threshold triggers at exactly three waypoints" {
    root ++> Waypoint() ++> Waypoint() ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stops == 3, f"expected 3 stops, got {res.stops}";
    assert "Trail complete after 3 waypoints" in out, f"missing threshold completion: {out!r}";
}

