```jac
"""Road network: edges that carry their own data.

Cities are nodes; roads are edges holding their length in km. A
courier walker travels by visiting the *edges* (not just the cities)
so each Road can add its toll to the courier's running cost.
"""

node City {
    has name: str = "";
}

edge Road {
    has km: float = 0.0;

    can charge_toll with Courier entry {
        visitor.cost += self.km * 0.25;
        print(f"Toll road segment: {self.km} km (+{self.km * 0.25:.2f})");
    }
}

walker Courier {
    has cost: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can travel with City entry {
        print(f"Arrived in {here.name}, total cost so far: {self.cost:.2f}");
        visit [edge -->];
    }
}

with entry {
    springfield = City(name="Springfield");
    rivertown = City(name="Rivertown");
    hillcrest = City(name="Hillcrest");

    root ++> springfield;
    springfield +>: Road(km=40.0) :+> rivertown;
    rivertown +>: Road(km=25.5) :+> hillcrest;

    c = root spawn Courier();
    print(f"Final delivery cost: {c.cost:.2f}");
}
```

jac_tests:
"""Tests for the road-network delivery-cost calculator.

Each test builds its own graph and spawns the Courier walker on it,
capturing stdout and inspecting the courier's accumulated `cost`.
"""

import io;
import from contextlib { redirect_stdout }

test "cost equals km times 0.25 summed across every road" {
    a = City(name="A");
    b = City(name="B");
    c_city = City(name="C");
    d = City(name="D");

    root ++> a;
    a +>: Road(km=40.0) :+> b;
    b +>: Road(km=25.5) :+> c_city;
    c_city +>: Road(km=10.0) :+> d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Courier();
    }

    expected = (40.0 + 25.5 + 10.0) * 0.25;
    assert abs(res.cost - expected) < 1e-9, f"got {res.cost}, want {expected}";
}

test "courier spawns from root and returns walker with cost field" {
    src = City(name="Source");
    dst = City(name="Dest");

    root ++> src;
    src +>: Road(km=20.0) :+> dst;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Courier();
    }

    out = buf.getvalue();
    assert "Final delivery cost" in out or "Arrived in" in out, f"no walker output: {out}";
    assert isinstance(res.cost, float), f"cost not float: {res.cost}";
    assert res.cost > 0.0, f"cost should be > 0 after traversing a road, got {res.cost}";
}

test "toll charge reflects each individual road length" {
    n1 = City(name="N1");
    n2 = City(name="N2");
    n3 = City(name="N3");

    root ++> n1;
    n1 +>: Road(km=8.0) :+> n2;
    n2 +>: Road(km=32.0) :+> n3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Courier();
    }

    out = buf.getvalue();
    assert "Toll road segment: 8.0 km (+2.00)" in out, f"missing 8km toll: {out}";
    assert "Toll road segment: 32.0 km (+8.00)" in out, f"missing 32km toll: {out}";
    assert abs(res.cost - 10.00) < 1e-9, f"got {res.cost}, want 10.00";
}

test "arrival message at each city shows running cost" {
    s1 = City(name="Stop1");
    s2 = City(name="Stop2");

    root ++> s1;
    s1 +>: Road(km=12.0) :+> s2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Courier();
    }

    out = buf.getvalue();
    assert "Arrived in Stop1" in out, f"no Stop1 arrival: {out}";
    assert "Arrived in Stop2" in out, f"no Stop2 arrival: {out}";
    assert "0.00" in out.split("Arrived in Stop1")[1].splitlines()[0], f"first arrival should show 0.00: {out}";
    assert abs(res.cost - 3.00) < 1e-9, f"got {res.cost}, want 3.00 for one 12km road";
}

test "cost is zero when walker spawns onto a node with no outgoing roads" {
    only = City(name="Only");

    root ++> only;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Courier();
    }

    assert abs(res.cost) < 1e-9, f"cost should be 0 with no roads, got {res.cost}";
}

