```jac
"""Weather station sweep: reporting readings back mid-traversal.

Each station reports its temperature as the walker passes through,
without ending the trip. Reports accumulate in order, so the main
block can read them back as a time series.
"""

node WeatherStation {
    has location: str = "";
    has temperature_c: float = 0.0;
}

walker Sweep {
    has day: str = "";

    can start with Root entry {
        print(f"Starting weather sweep for {self.day}");
        visit [-->];
    }

    can read with WeatherStation entry {
        report here.temperature_c;
        visit [-->];
    }
}

with entry {
    root ++> WeatherStation(location="Coast", temperature_c=18.5)
        ++> WeatherStation(location="Valley", temperature_c=24.0)
        ++> WeatherStation(location="Summit", temperature_c=9.5);

    result = root spawn Sweep(day="Tuesday");
    print(f"Readings on {result.reports}");
    lo = min(result.reports);
    hi = max(result.reports);
    print(f"Range across stations: {lo} to {hi} C");
}
```

jac_tests:
"""Test annex for the Weather Sweep program."""

import io;
import from contextlib { redirect_stdout }

test "sweep collects readings from each station in chain order" {
    root ++> WeatherStation(location="A", temperature_c=10.0)
        ++> WeatherStation(location="B", temperature_c=20.0)
        ++> WeatherStation(location="C", temperature_c=30.0);

    res = root spawn Sweep(day="Monday");
    assert res.reports == [10.0, 20.0, 30.0], f"got {res.reports}";
    assert min(res.reports) == 10.0, f"min should be 10.0, got {min(res.reports)}";
    assert max(res.reports) == 30.0, f"max should be 30.0, got {max(res.reports)}";
}

test "sweep keeps walker alive across stations and does not stop early" {
    # Chain of 3 stations; walker must traverse ALL of them.
    root ++> WeatherStation(location="Coast", temperature_c=18.5)
        ++> WeatherStation(location="Valley", temperature_c=24.0)
        ++> WeatherStation(location="Summit", temperature_c=9.5);

    res = root spawn Sweep(day="Tuesday");
    assert len(res.reports) == 3, f"expected 3 readings, got {len(res.reports)}";
    assert res.reports[0] == 18.5, f"first reading should be 18.5, got {res.reports[0]}";
    assert res.reports[1] == 24.0, f"second reading should be 24.0, got {res.reports[1]}";
    assert res.reports[2] == 9.5, f"third reading should be 9.5, got {res.reports[2]}";
}

test "sweep prints starting banner with the day label" {
    root ++> WeatherStation(location="X", temperature_c=15.0)
        ++> WeatherStation(location="Y", temperature_c=22.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Sweep(day="Friday");
    }
    out = buf.getvalue();
    assert "Starting weather sweep" in out, f"missing banner: {out}";
    assert "Friday" in out, f"day label missing from banner: {out}";
    assert res.reports == [15.0, 22.0], f"got {res.reports}";
}

test "sweep computes correct min and max across all stations" {
    root ++> WeatherStation(location="Cold", temperature_c=-5.0)
        ++> WeatherStation(location="Mild", temperature_c=12.3)
        ++> WeatherStation(location="Hot", temperature_c=40.5)
        ++> WeatherStation(location="Room", temperature_c=21.0);

    res = root spawn Sweep(day="Sunday");
    lo = min(res.reports);
    hi = max(res.reports);
    assert lo == -5.0, f"min should be -5.0, got {lo}";
    assert hi == 40.5, f"max should be 40.5, got {hi}";
    assert hi >= lo, f"max {hi} must be >= min {lo}";
}

