test "bidirectional edge is created with both directions in one statement" {
    ana = House(owner="Ana");
    leo = House(owner="Leo");
    root ++> ana;
    root ++> leo;
    ana <+: Buddy(since=2023) :+> leo;

    # The whole point of <+: ... :+> is that BOTH directions exist after
    # one statement. Forward traversal from either end must reach the other.
    assert len([ana -->]) == 1, "Ana should have exactly one outgoing Buddy";
    assert len([leo -->]) == 1, "Leo should have exactly one outgoing Buddy";
    assert leo in [ana ->:Buddy:->], "Ana must see Leo as a buddy";
    assert ana in [leo ->:Buddy:->], "Leo must see Ana as a buddy (bidirectional)";
}


test "greeter at Ana reaches Leo with forward traversal only" {
    ana = House(owner="Ana");
    leo = House(owner="Leo");
    root ++> ana;
    root ++> leo;
    ana <+: Buddy(since=2023) :+> leo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = ana spawn Greeter(who="Ana");
    }
    out = buf.getvalue();

    assert leo.owner in res.reports, (
        f"Ana-side greeter must reach Leo via forward edges; got reports {res.reports}"
    );
    assert "Ana waves hello to Leo's house" in out, (
        f"expected Ana->Leo greeting in stdout; got: {out}"
    );
    # The met list must have recorded every distinct house visited, exactly once.
    assert res.met == ["Ana", "Leo"], (
        f"met list should record each house once in arrival order; got {res.met}"
    );
}


test "greeter at Leo reaches Ana with forward traversal only" {
    ana = House(owner="Ana");
    leo = House(owner="Leo");
    root ++> ana;
    root ++> leo;
    ana <+: Buddy(since=2023) :+> leo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = leo spawn Greeter(who="Leo");
    }
    out = buf.getvalue();

    assert ana.owner in res.reports, (
        f"Leo-side greeter must reach Ana via forward edges; got reports {res.reports}"
    );
    assert "Leo waves hello to Ana's house" in out, (
        f"expected Leo->Ana greeting in stdout; got: {out}"
    );
    assert res.met == ["Leo", "Ana"], (
        f"met list should record each house once in arrival order; got {res.met}"
    );
}


test "greeter does not bounce back and forth across bidirectional edge" {
    ana = House(owner="Ana");
    leo = House(owner="Leo");
    root ++> ana;
    root ++> leo;
    ana <+: Buddy(since=2023) :+> leo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = ana spawn Greeter(who="Ana");
    }

    # Each house owner appears in reports at most once — no infinite ping-pong.
    assert res.reports.count("Ana") == 1, (
        f"Ana should be greeted exactly once (no bounce); got {res.reports}"
    );
    assert res.reports.count("Leo") == 1, (
        f"Leo should be greeted exactly once (no bounce); got {res.reports}"
    );
    # The greeting printed line for Leo should appear exactly once too.
    assert out_pe_count := buf.getvalue().count("Ana waves hello to Leo's house") == 1, (
        "Leo's greeting should print exactly once, proving no back-and-forth loop"
    );
}


test "greeter spawned on the wrong node type fires nothing" {
    ana = House(owner="Ana");
    leo = House(owner="Leo");
    root ++> ana;
    root ++> leo;
    ana <+: Buddy(since=2023) :+> leo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        # Root is not a House, so `can greet with House entry` never fires.
        res = root spawn Greeter(who="Root");
    }

    assert res.reports == [], (
        f"greeter spawned on Root should produce no reports; got {res.reports}"
    );
    assert buf.getvalue() == "", (
        "spawning on the wrong node type must produce no greetings"
    );
}

