"""Tests for the road-trip playlist: inline track creation + Player walker."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: Inline chain builds 3 tracks off root in one statement ----------
test "inline chain produces three tracks off root" {
    root ++> Track(title="Nightcall", artist="Kavinsky", seconds=258)
        ++> Track(title="Genesis", artist="Grimes", seconds=249)
        ++> Track(title="Midnight City", artist="M83", seconds=244);

    # Root has exactly ONE direct child -- `++>` is a chain, not a fan-out.
    assert len([root-->]) == 1, f"expected 1 direct child of root, got {len([root-->])}";

    # Walk the chain end-to-end and count Track nodes.
    cur = root;
    n = 0;
    while [cur-->] {
        n += 1;
        cur = [cur-->][0];
    }
    assert n == 3, f"expected 3 tracks along the chain, got {n}";
}

# ---------- Test 2: Player walker prints now-playing lines in order ----------
test "player prints three now-playing lines in chain order" {
    root ++> Track(title="Nightcall", artist="Kavinsky", seconds=258)
        ++> Track(title="Genesis", artist="Grimes", seconds=249)
        ++> Track(title="Midnight City", artist="M83", seconds=244);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    lines = out.splitlines();

    # Filter to lines that begin with the now-playing marker.
    play_lines = [ln for ln in lines if ln.startswith("Now playing:")];
    assert len(play_lines) == 3, f"expected 3 now-playing lines, got {len(play_lines)}: {lines}";

    # Each must mention the corresponding track, in chain order.
    assert "Nightcall" in play_lines[0], f"line 0 missing Nightcall: {play_lines[0]}";
    assert "Kavinsky" in play_lines[0], f"line 0 missing Kavinsky: {play_lines[0]}";
    assert "258" in play_lines[0], f"line 0 missing 258: {play_lines[0]}";

    assert "Genesis" in play_lines[1], f"line 1 missing Genesis: {play_lines[1]}";
    assert "Grimes" in play_lines[1], f"line 1 missing Grimes: {play_lines[1]}";
    assert "249" in play_lines[1], f"line 1 missing 249: {play_lines[1]}";

    assert "Midnight City" in play_lines[2], f"line 2 missing Midnight City: {play_lines[2]}";
    assert "M83" in play_lines[2], f"line 2 missing M83: {play_lines[2]}";
    assert "244" in play_lines[2], f"line 2 missing 244: {play_lines[2]}";

    # Walker's running total must equal the sum of the seconds.
    assert res.elapsed == 258 + 249 + 244, f"got elapsed={res.elapsed}";
}

# ---------- Test 3: Player prints the 'pressing play' opener and the runtime footer ----------
test "player prints opener and total runtime footer" {
    root ++> Track(title="Nightcall", artist="Kavinsky", seconds=258)
        ++> Track(title="Genesis", artist="Grimes", seconds=249)
        ++> Track(title="Midnight City", artist="M83", seconds=244);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # 258 + 249 + 244 = 751 seconds = 12m 31s
    assert "Pressing play..." in out, f"missing opener in output: {out}";
    assert "Total runtime so far: 12m 31s" in out, f"missing total runtime footer: {out}";

    assert res.elapsed == 751, f"got elapsed={res.elapsed}";
}

# ---------- Test 4: A single inline track works (degenerate chain) ----------
test "single inline track plays one line and reports its runtime" {
    root ++> Track(title="Solo", artist="OneArtist", seconds=125);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    play_lines = [ln for ln in out.splitlines() if ln.startswith("Now playing:")];
    assert len(play_lines) == 1, f"expected 1 now-playing line, got {len(play_lines)}: {out}";
    assert "Solo" in play_lines[0], f"missing Solo: {play_lines[0]}";
    assert "OneArtist" in play_lines[0], f"missing OneArtist: {play_lines[0]}";
    assert "125" in play_lines[0], f"missing 125: {play_lines[0]}";

    # 125s = 2m 5s
    assert "Total runtime so far: 2m 5s" in out, f"missing runtime footer: {out}";
    assert res.elapsed == 125, f"got elapsed={res.elapsed}";
}

