    mid1 +>: Route(hours=6.5, allows_frozen=False) :+> end1;

    children = [root -->];
    assert len(children) == 1, f"root should have 1 child, got {len(children)}";
    assert children[0].city == "Depot North", f"root child should be depot, got {children[0].city}";
    assert children[0].is_depot, "depot must be flagged as depot";

