    }
    out = buf.getvalue();

    assert "Scheduling CS-201" in out, f"CS-201 should be scheduled: {out}";
    assert "Scheduling CS-201L" in out, f"lab should be scheduled via Coreq: {out}";
    assert "CS-201 meets together with CS-201L" in out, f"forward Coreq from lecture to lab missing: {out}";
    assert "CS-201L meets together with CS-201" in out, f"reverse Coreq from lab to lecture missing: {out}";

    # Planner should total CS-201(3) + CS-201L(1) + CS-301(3) + CS-402(3) = 10.
    assert len(result.reports) == 1, f"expected 1 report, got {result.reports}";
    assert "10 credits" in result.reports[0], f"expected 10 credits, got {result.reports[0]}";
    assert result.total_credits == 10, f"expected 10 credits, got {result.total_credits}";
}

# ------------------------------------------------------------------
test "co-requisite edges are bidirectional" {
    cs101 = Course(code="CS-101", title="Intro to Programming");
    cs201 = Course(code="CS-201", title="Data Structures");
    lab = Course(code="CS-201L", title="Data Structures Lab", credits=1);
    cs301 = Course(code="CS-301", title="Algorithms");
    cs402 = Course(code="CS-402", title="Senior Capstone");

    root ++> cs101
        +>: PrereqOf(min_grade="B") :+> cs201
        +>: PrereqOf() :+> cs301
        +>: PrereqOf() :+> cs402;

    cs201 <+: Coreq() :+> lab;

    # <+:...:+> creates edges in both directions, so a forward lookup
    # from EITHER endpoint must find the partner.
    lab_partners = [lab ->:Coreq:->];
    lec_partners = [cs201 ->:Coreq:->];
    assert cs201 in lab_partners, f"lab should find lecture via Coreq (reverse): {lab_partners}";
    assert lab in lec_partners, f"lecture should find lab via Coreq (forward): {lec_partners}";
}

# ------------------------------------------------------------------
test "already-completed courses are skipped, not scheduled" {
    cs101 = Course(code="CS-101", title="Intro to Programming");
    cs201 = Course(code="CS-201", title="Data Structures");
    lab = Course(code="CS-201L", title="Data Structures Lab", credits=1);
    cs301 = Course(code="CS-301", title="Algorithms");
    cs402 = Course(code="CS-402", title="Senior Capstone");

    root ++> cs101
        +>: PrereqOf(min_grade="B") :+> cs201
        +>: PrereqOf() :+> cs301
        +>: PrereqOf() :+> cs402;

    cs201 <+: Coreq() :+> lab;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn DegreePlanner(
            student="Priya",
            completed=["CS-101"]
        );
    }
    out = buf.getvalue();

    assert "CS-101: already completed, skipped" in out, f"skip message missing: {out}";
    assert "Scheduling CS-101" not in out, f"CS-101 must NOT be scheduled: {out}";

    # CS-101 contributes 0 credits; remaining scheduled sum is 3+1+3+3 = 10.
    assert result.total_credits == 10, f"completed courses must not add credits, got {result.total_credits}";
    assert len(result.reports) == 1, f"planner should reach the capstone: {result.reports}";
}

# ------------------------------------------------------------------
test "disengage at capstone prevents further traversal" {
    cs101 = Course(code="CS-101", title="Intro to Programming");
    cs201 = Course(code="CS-201", title="Data Structures");
    lab = Course(code="CS-201L", title="Data Structures Lab", credits=1);
    cs301 = Course(code="CS-301", title="Algorithms");
    cs402 = Course(code="CS-402", title="Senior Capstone");

    root ++> cs101
        +>: PrereqOf(min_grade="B") :+> cs201
        +>: PrereqOf() :+> cs301
        +>: PrereqOf() :+> cs402;

    cs201 <+: Coreq() :+> lab;

    # Attach a downstream course that should never be visited.
    extra = Course(code="CS-999", title="Imaginary Course", credits=3);
    cs402 +>: PrereqOf() :+> extra;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn DegreePlanner(
            student="Priya",
            completed=["CS-101"]
        );
    }
    out = buf.getvalue();

    assert "Scheduling CS-402" in out, f"capstone must be scheduled: {out}";
    assert "CS-999" not in out, f"post-capstone course must not be visited: {out}";
    assert result.total_credits == 10, f"disengage must stop further credits, got {result.total_credits}";
    assert len(result.reports) == 1 and "Capstone reached" in result.reports[0], f"capstone report missing: {result.reports}";
