"""Test annex for the industrial sensor patrol program."""

import io;
import from contextlib { redirect_stdout }

test "union trigger fires for both sensor kinds" {
    root ++> Zone(zone_id="A");
    root ++> Zone(zone_id="B");

    rt = [root -->][?:Zone][0];
    rb = [root -->][?:Zone][1];

    rt ++> TemperatureSensor(unit_id="T-1", celsius=64.0);
    rt ++> SmokeSensor(unit_id="S-1", ppm=12.0);
    rb ++> TemperatureSensor(unit_id="T-2", celsius=91.5);
    rb ++> SmokeSensor(unit_id="S-2", ppm=77.0);

    buf = io.StringIO();
    monitor = SafetyMonitor();
    with redirect_stdout(buf) {
        res = root spawn monitor;
    }
    out = buf.getvalue();

    # Both zone sweeps should appear.
    assert "sweeping zone A" in out, f"missing zone A sweep: {out}";
    assert "sweeping zone B" in out, f"missing zone B sweep: {out}";

    # Both sensor kinds should be inspected (nominal readings printed).
    assert "nominal: T-1: temperature 64.0 C" in out, f"missing T-1 nominal: {out}";
    assert "nominal: S-1: smoke 12.0 ppm" in out, f"missing S-1 nominal: {out}";

    # Both alert kinds should be flagged via the union trigger.
    assert "[ALERT] T-2: temperature 91.5 C" in out, f"missing T-2 alert: {out}";
    assert "[ALERT] S-2: smoke 77.0 ppm" in out, f"missing S-2 alert: {out}";

    # Both alert readings must be collected by the same walker ability.
    assert len(res.alerts) == 2, f"expected 2 alerts, got {len(res.alerts)}: {res.alerts}";
    assert "T-2: temperature 91.5 C" in res.alerts, f"T-2 not in alerts: {res.alerts}";
    assert "S-2: smoke 77.0 ppm" in res.alerts, f"S-2 not in alerts: {res.alerts}";
}

test "temperature alert threshold is above 75 C" {
    root ++> Zone(zone_id="A");
    rt = [root -->][?:Zone][0];

    # Exactly at the threshold: NOT an alert (strictly greater than).
    rt ++> TemperatureSensor(unit_id="T-edge", celsius=75.0);
    # Just over: IS an alert.
    rt ++> TemperatureSensor(unit_id="T-over", celsius=75.1);
    # Just under: NOT an alert.
    rt ++> TemperatureSensor(unit_id="T-under", celsius=74.9);

    buf = io.StringIO();
    monitor = SafetyMonitor();
    with redirect_stdout(buf) {
        res = root spawn monitor;
    }
    out = buf.getvalue();

    assert "nominal: T-edge: temperature 75.0 C" in out, f"75.0 should be nominal: {out}";
    assert "nominal: T-under: temperature 74.9 C" in out, f"74.9 should be nominal: {out}";
    assert "[ALERT] T-over: temperature 75.1 C" in out, f"75.1 should alert: {out}";

    assert len(res.alerts) == 1, f"expected exactly 1 alert, got {len(res.alerts)}: {res.alerts}";
    assert "T-over: temperature 75.1 C" in res.alerts, f"wrong alert collected: {res.alerts}";
}

test "smoke alert threshold is above 50 ppm" {
    root ++> Zone(zone_id="B");
    rb = [root -->][?:Zone][0];

    # Boundary checks for the smoke threshold.
    rb ++> SmokeSensor(unit_id="S-edge", ppm=50.0);
    rb ++> SmokeSensor(unit_id="S-over", ppm=50.1);
    rb ++> SmokeSensor(unit_id="S-under", ppm=49.9);

    buf = io.StringIO();
    monitor = SafetyMonitor();
    with redirect_stdout(buf) {
        res = root spawn monitor;
    }
    out = buf.getvalue();

    assert "nominal: S-edge: smoke 50.0 ppm" in out, f"50.0 should be nominal: {out}";
    assert "nominal: S-under: smoke 49.9 ppm" in out, f"49.9 should be nominal: {out}";
    assert "[ALERT] S-over: smoke 50.1 ppm" in out, f"50.1 should alert: {out}";

    assert len(res.alerts) == 1, f"expected exactly 1 alert, got {len(res.alerts)}: {res.alerts}";
    assert "S-over: smoke 50.1 ppm" in res.alerts, f"wrong alert collected: {res.alerts}";
}

test "all nominal readings produce no alerts" {
    root ++> Zone(zone_id="A");
    rt = [root -->][?:Zone][0];

    rt ++> TemperatureSensor(unit_id="T-1", celsius=20.0);
    rt ++> TemperatureSensor(unit_id="T-2", celsius=75.0);
    rt ++> SmokeSensor(unit_id="S-1", ppm=5.0);
    rt ++> SmokeSensor(unit_id="S-2", ppm=50.0);

    buf = io.StringIO();
    monitor = SafetyMonitor();
    with redirect_stdout(buf) {
        res = root spawn monitor;
    }
    out = buf.getvalue();

    assert "nominal: T-1: temperature 20.0 C" in out, f"missing T-1 nominal: {out}";
    assert "nominal: T-2: temperature 75.0 C" in out, f"missing T-2 nominal: {out}";
    assert "nominal: S-1: smoke 5.0 ppm" in out, f"missing S-1 nominal: {out}";
    assert "nominal: S-2: smoke 50.0 ppm" in out, f"missing S-2 nominal: {out}";
    assert "[ALERT]" not in out, f"unexpected alert line: {out}";

    assert res.alerts == [], f"expected empty alert list, got {res.alerts}";
}

test "all alerting readings are collected and summarized" {
    root ++> Zone(zone_id="A");
    root ++> Zone(zone_id="B");
    rt = [root -->][?:Zone][0];
    rb = [root -->][?:Zone][1];

    rt ++> TemperatureSensor(unit_id="T-hot", celsius=120.0);
    rb ++> SmokeSensor(unit_id="S-smoky", ppm=300.0);
    rt ++> TemperatureSensor(unit_id="T-cold", celsius=10.0);

    buf = io.StringIO();
    monitor = SafetyMonitor();
    with redirect_stdout(buf) {
        res = root spawn monitor;
    }
    out = buf.getvalue();

    # Alert count must reflect every alert reading on the patrol.
    assert len(res.alerts) == 2, f"expected 2 alerts, got {len(res.alerts)}: {res.alerts}";
    assert "T-hot: temperature 120.0 C" in res.alerts, f"missing T-hot in alerts: {res.alerts}";
    assert "S-smoky: smoke 300.0 ppm" in res.alerts, f"missing S-smoky in alerts: {res.alerts}";

    # The summary line uses the same alerts list the walker accumulated.
    summary = f"patrol finished with {len(res.alerts)} alert(s): {res.alerts}";
    assert "[ALERT] T-hot: temperature 120.0 C" in out, f"missing T-hot alert line: {out}";
    assert "[ALERT] S-smoky: smoke 300.0 ppm" in out, f"missing S-smoky alert line: {out}";
    assert "nominal: T-cold: temperature 10.0 C" in out, f"missing T-cold nominal: {out}";

    # Sanity: summary text from the program entry would only be visible if the
    # walker printed it; the test just confirms the alerts list is the source
    # of truth for that count, matching the program's `len(watch.alerts)`.
    assert len(res.alerts) == 2, f"summary count mismatch: {summary}";
}

