"""Test annex for the Trip Planner program.

Builds fresh city graphs and spawns the Planner walker to verify it:
  - filters out hotels, keeping only attractions
  - applies a 4-star-and-up rating threshold
  - prints a final itinerary with the correct format
  - reports per-station counts of attractions vs top-rated
"""

import io;
import from contextlib { redirect_stdout }


test "filters out hotels and keeps only top-rated attractions" {
    central = Station(name="Central");
    grand = Hotel(name="Grand Hotel");
    museum = Attraction(name="City Museum", rating=4.7);
    cafe = Attraction(name="Street Cafe", rating=2.5);

    central +>: Walk() :+> grand;
    central +>: Walk() :+> museum;
    central +>: Walk() :+> cafe;
    root ++> central;

    buf = io.StringIO();
    pl = Planner();
    with redirect_stdout(buf) {
        res = root spawn pl;
    }
    out = buf.getvalue();

    assert len(res.itinerary) == 1, f"expected 1 top-rated stop, got {len(res.itinerary)}: {res.itinerary}";
    assert "City Museum" in res.itinerary[0], f"museum missing from itinerary: {res.itinerary}";
    assert "Grand Hotel" not in res.itinerary[0], f"hotel leaked into itinerary: {res.itinerary}";
    assert "Street Cafe" not in res.itinerary[0], f"low-rated attraction leaked in: {res.itinerary}";
    assert "(4.7 stars, reachable from Central)" in res.itinerary[0], f"format wrong: {res.itinerary[0]}";

    assert "Near Central: 2 attraction(s), 1 top-rated" in out, f"wrong per-station report: {out}";
    assert "-- Itinerary --" in out, f"missing itinerary header: {out}";
}


test "two stations each contribute only their 4+ attractions" {
    central = Station(name="Central");
    riverside = Station(name="Riverside");

    grand = Hotel(name="Grand Hotel");
    museum = Attraction(name="City Museum", rating=4.7);
    park = Attraction(name="Riverside Park", rating=3.9);
    tower = Attraction(name="Old Tower", rating=4.5);
    plaza = Attraction(name="Plaza", rating=4.0);

    central +>: Walk() :+> grand;
    central +>: Walk() :+> museum;
    central +>: Walk() :+> plaza;
    riverside +>: Walk() :+> park;
    riverside +>: Walk() :+> tower;
    root ++> central ++> riverside;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Planner();
    }
    out = buf.getvalue();

    # Top-rated (>= 4.0): City Museum, Old Tower, Plaza  ->  3 total
    assert len(res.itinerary) == 3, f"expected 3 stops, got {len(res.itinerary)}: {res.itinerary}";

    joined = " | ".join(res.itinerary);
    assert "City Museum" in joined, f"museum missing: {joined}";
    assert "Old Tower" in joined, f"tower missing: {joined}";
    assert "Plaza" in joined, f"plaza (rating=4.0) missing: {joined}";
    assert "Riverside Park" not in joined, f"3.9-star park leaked in: {joined}";
    assert "Grand Hotel" not in joined, f"hotel leaked in: {joined}";

    # Plaza is reachable from Central; Old Tower from Riverside
    assert any("reachable from Central" in s for s in res.itinerary), f"no Central reachability: {res.itinerary}";
    assert any("reachable from Riverside" in s for s in res.itinerary), f"no Riverside reachability: {res.itinerary}";

    assert "Near Central: 2 attraction(s), 2 top-rated" in out, f"Central report wrong: {out}";
    assert "Near Riverside: 2 attraction(s), 1 top-rated" in out, f"Riverside report wrong: {out}";
}


test "station with no attractions reports zero and contributes nothing" {
    lonely = Station(name="Lonely");
    grand = Hotel(name="Grand Hotel");
    inn = Hotel(name="Riverside Inn");
    lonely +>: Walk() :+> grand;
    lonely +>: Walk() :+> inn;
    root ++> lonely;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Planner();
    }
    out = buf.getvalue();

    assert len(res.itinerary) == 0, f"expected empty itinerary, got {res.itinerary}";
    assert "Near Lonely: 0 attraction(s), 0 top-rated" in out, f"empty-station report wrong: {out}";
    assert "-- Itinerary --" in out, f"itinerary header should still print: {out}";

    # Header printed but no body lines from itinerary
    after_header = out.split("-- Itinerary --", 1)[1].strip();
    assert after_header == "", f"expected blank itinerary body, got: {after_header!r}";
}


test "rating boundary 4.0 is included, anything below is excluded" {
    a = Station(name="A");
    top = Attraction(name="Top Spot", rating=5.0);
    borderline = Attraction(name="Borderline", rating=4.0);
    just_under = Attraction(name="Just Under", rating=3.99);
    way_low = Attraction(name="Way Low", rating=1.0);

    a +>: Walk() :+> top;
    a +>: Walk() :+> borderline;
    a +>: Walk() :+> just_under;
    a +>: Walk() :+> way_low;
    root ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Planner();
    }
    out = buf.getvalue();

    names = [s.split(" (")[0] for s in res.itinerary];
    assert "Top Spot" in names, f"5.0 missing: {names}";
    assert "Borderline" in names, f"4.0 should be included: {names}";
    assert "Just Under" not in names, f"3.99 should be excluded: {names}";
    assert "Way Low" not in names, f"1.0 should be excluded: {names}";
    assert len(res.itinerary) == 2, f"expected exactly 2 stops, got {len(res.itinerary)}: {names}";
    assert "Near A: 4 attraction(s), 2 top-rated" in out, f"counts wrong: {out}";
}


test "planner walker does not descend into hotel nodes" {
    hub = Station(name="Hub");
    grand = Hotel(name="Grand Hotel");
    museum = Attraction(name="City Museum", rating=4.7);

    hub +>: Walk() :+> grand;
    hub +>: Walk() :+> museum;
    # If the planner mistakenly visited the hotel and re-walked from it,
    # the count of attractions from this station could be inflated.
    grand +>: Walk() :+> museum;
    root ++> hub;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Planner();
    }
    out = buf.getvalue();

    # Exactly one stop must be recorded (museum from Hub). Re-walking from
    # the hotel would either duplicate the stop or change the per-station
    # counts, both of which would break these assertions.
    assert len(res.itinerary) == 1, f"hotel re-entry inflated itinerary: {res.itinerary}";
    assert "(4.7 stars, reachable from Hub)" in res.itinerary[0], f"wrong origin: {res.itinerary[0]}";
    assert "Near Hub: 1 attraction(s), 1 top-rated" in out, f"per-station count wrong: {out}";
}

