"""Test annex for the depot dispatch checker.

The program prints depot summaries and a final dispatch list.
Walker `spawn` returns None here, so all assertions go through stdout.
"""

import io;
import from contextlib { redirect_stdout }

def run_walker(graph_root) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        _ = graph_root spawn Dispatcher();
    }
    return buf.getvalue();
}

test "mixed depots show correct in-window counts" {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");

    market = Store(name="Market St");
    harbour = Store(name="Harbour Point");
    airport = Store(name="Airport Hub");

    north +>: Hauls(tonnes=1.2) :+> market;
    north +>: Hauls(tonnes=6.5) :+> harbour;
    south +>: Hauls(tonnes=3.0) :+> airport;
    south +>: Hauls(tonnes=11.0) :+> market;

    root ++> north ++> south;

    out = run_walker(root);

    # Per-depot summaries.
    assert "North Depot: 2 run(s) total, 1 within the 2-8 t window" in out,
        f"North summary wrong: {out!r}";
    assert "South Depot: 2 run(s) total, 1 within the 2-8 t window" in out,
        f"South summary wrong: {out!r}";

    # Exactly two qualifying routes are listed under the dispatch header.
    assert "-- Dispatch list --" in out, f"missing dispatch header: {out!r}";

    lines = out.splitlines();
    dispatch_header_idx = lines.index("-- Dispatch list --");
    dispatch_lines = lines[dispatch_header_idx + 1:];
    assert len(dispatch_lines) == 2,
        f"expected 2 dispatch entries, got {len(dispatch_lines)}: {dispatch_lines!r}";

    assert "North Depot -> Harbour Point" in out,
        f"missing North->Harbour dispatch: {out!r}";
    assert "South Depot -> Airport Hub" in out,
        f"missing South->Airport dispatch: {out!r}";

    # The out-of-window routes must NOT appear in the dispatch list.
    assert "Market St" not in out, f"too-light route leaked: {out!r}";
    assert "11.0" not in out, f"overweight route leaked: {out!r}";
}

