test "boundary weights 2.0 and 8.0 are included" {
    depot = Depot(name="Boundary Depot");
    low = Store(name="Low Store");
    high = Store(name="High Store");

    depot +>: Hauls(tonnes=2.0) :+> low;
    depot +>: Hauls(tonnes=8.0) :+> high;

    root ++> depot;

    out = run_walker(root);

    assert "Boundary Depot: 2 run(s) total, 2 within the 2-8 t window" in out,
        f"both boundary loads should be included: {out!r}";
    assert "Boundary Depot -> Low Store" in out,
        f"missing lower-bound dispatch: {out!r}";
    assert "Boundary Depot -> High Store" in out,
        f"missing upper-bound dispatch: {out!r}";
}

test "just-outside bounds are excluded" {
    depot = Depot(name="Edge Depot");
    just_low = Store(name="JustLow");
    just_high = Store(name="JustHigh");
    inside = Store(name="Inside");

    depot +>: Hauls(tonnes=1.9) :+> just_low;
    depot +>: Hauls(tonnes=8.1) :+> just_high;
    depot +>: Hauls(tonnes=4.0) :+> inside;

    root ++> depot;

    out = run_walker(root);

    assert "Edge Depot: 3 run(s) total, 1 within the 2-8 t window" in out,
        f"only the middle load is in-window: {out!r}";

    lines = out.splitlines();
    header_idx = lines.index("-- Dispatch list --");
    dispatch_lines = lines[header_idx + 1:];
    assert len(dispatch_lines) == 1,
        f"expected exactly one dispatch, got: {dispatch_lines!r}";
    assert "Edge Depot -> Inside" in dispatch_lines[0],
        f"wrong dispatch line: {dispatch_lines!r}";
}

