"""Tests for Scout: collaboration suggestions exactly two hops away,
excluding self and direct co-authors."""

import io;
import from contextlib { redirect_stdout }

def make_graph {
    ana = Researcher(name="Ana", field="robotics");
    ben = Researcher(name="Ben", field="vision");
    cyd = Researcher(name="Cyd", field="planning");
    dee = Researcher(name="Dee", field="control");
    eli = Researcher(name="Eli", field="learning");

    ana +>: CoAuthored() :+> ben;
    ben +>: CoAuthored() :+> cyd;
    ben +>: CoAuthored() :+> dee;
    cyd +>: CoAuthored() :+> eli;

    root ++> ana ++> ben ++> cyd;
    return (ana, ben, cyd, dee, eli);
}

test "Scout suggests Cyd to Ana (two hops via Ben)" {
    (ana, ben, cyd, dee, eli) = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
    }
    out = buf.getvalue();

    assert "-- Collaboration suggestions --" in out, f"missing header: {out}";
    assert "Ana could meet Cyd" in out, f"Ana->Cyd two-hop suggestion missing: {out}";
    assert "(planning)" in out, f"Cyd's field (planning) missing from suggestion: {out}";
}

test "Scout excludes Ana herself from her own suggestions" {
    (ana, ben, cyd, dee, eli) = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
    }
    out = buf.getvalue();

    # Walk Ana -> Ben -> Ana would put Ana in fofs; the
    # p.name != here.name guard must drop her.
    ana_lines = [l for l in out.splitlines() if "Ana" in l];
    for line in ana_lines {
        assert "could meet Ana " not in line, f"self must be excluded: {line}";
    }
}

test "Scout excludes direct co-authors from suggestions" {
    (ana, ben, cyd, dee, eli) = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
    }
    out = buf.getvalue();

    # Ana's direct co-author is Ben; Ben must NOT be suggested to Ana.
    for line in out.splitlines() {
        assert not ("Ana" in line and "could meet Ben " in line),
            f"direct co-author Ben must be excluded from Ana's suggestions: {line}";
    }

    # Ben's direct co-authors are Ana, Cyd, Dee; none should be suggested.
    ben_lines = [l for l in out.splitlines() if l.startswith("vision researcher Ben ")];
    for line in ben_lines {
        assert "could meet Ana " not in line, f"direct co-author Ana excluded: {line}";
        assert "could meet Cyd " not in line, f"direct co-author Cyd excluded: {line}";
        assert "could meet Dee " not in line, f"direct co-author Dee excluded: {line}";
    }
}

test "Scout reports exactly two-hop reachable nodes" {
    (ana, ben, cyd, dee, eli) = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
    }
    out = buf.getvalue();

    # From Ana: fofs = {Cyd, Dee} (Ben->Cyd, Ben->Dee). Ben excluded as direct.
    # Ana should produce exactly 2 suggestion lines.
    ana_suggestions = [
        l for l in out.splitlines()
        if l.startswith("robotics researcher Ana ")
    ];
    assert len(ana_suggestions) == 2, f"Ana should have 2 two-hop suggestions, got {len(ana_suggestions)}: {ana_suggestions}";
    assert any("could meet Cyd" in l for l in ana_suggestions), f"Cyd missing for Ana: {ana_suggestions}";
    assert any("could meet Dee" in l for l in ana_suggestions), f"Dee missing for Ana: {ana_suggestions}";

    # From Ben: fofs = {Ana, Eli} (Ana->Ben->Ana, Cyd->Eli). Direct {Ana,Cyd,Dee} excluded.
    # Ben should produce exactly 1 suggestion line: Eli.
    ben_suggestions = [
        l for l in out.splitlines()
        if l.startswith("vision researcher Ben ")
    ];
    assert len(ben_suggestions) == 1, f"Ben should have 1 suggestion (Eli), got {len(ben_suggestions)}: {ben_suggestions}";
    assert "could meet Eli" in ben_suggestions[0], f"Ben should meet Eli: {ben_suggestions[0]}";

    # From Cyd: fofs = {Ben} (Ben->Ana, Ben->Cyd->Ben). Direct {Ben,Eli} excluded.
    # Cyd should produce 0 suggestions.
    cyd_suggestions = [
        l for l in out.splitlines()
        if l.startswith("planning researcher Cyd ")
    ];
    assert len(cyd_suggestions) == 0, f"Cyd should have 0 suggestions, got {len(cyd_suggestions)}: {cyd_suggestions}";
}

test "Scout reports are deduped per researcher pair" {
    (ana, ben, cyd, dee, eli) = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Scout();
    }
    out = buf.getvalue();

    # Build a fresh graph with two parallel paths Ana-Ben-Cyd and Ana-Bob-Cyd,
    # but stick to declared symbols: reuse Ana/Ben/Cyd path only, plus add Dee
    # reachable two different ways from Ana via Ben to ensure dedup.
    # With the base graph, Ana reaches Cyd via one path, Dee via one path.
    # The dedup guarantee: each pair appears at most once across all lines.
    ana_to_lines = [l for l in out.splitlines() if "Ana" in l and "could meet" in l];
    targets = [l.split("could meet ")[1].split(" ")[0] for l in ana_to_lines if "Ana could meet" in l];
    assert len(targets) == len(set(targets)),
        f"each suggested person must appear once for Ana, got {targets}";
}

