    app +>: DependsOn() :+> a;
    a +>: DependsOn() :+> b;
    b +>: DependsOn() :+> c;
    c +>: DependsOn() :+> d;
    # Back edge: d -> b creates cycle b -> c -> d -> b
    d +>: DependsOn() :+> b;
