"""Tests for the CI scheduler walker."""

import io;
import from contextlib { redirect_stdout }

def make_graph {
    # Reset persistent root for isolation.
    for stale in [root -->][?:Task] {
        del stale;
    }

    setup = Task(name="setup", duration=5);
    compile_src = Task(name="compile", duration=20);
    gen_docs = Task(name="docs", duration=10);
    run_tests = Task(name="tests", duration=15);
    package = Task(name="package", duration=8);
    publish = Task(name="publish", duration=4);

    root ++> [
        setup,
        compile_src,
        gen_docs,
        run_tests,
        package,
        publish,
    ];

    # prerequisite --> dependent
    setup +>: Needs() :+> compile_src;
    compile_src +>: Needs() :+> gen_docs;
    compile_src +>: Needs() :+> run_tests;
    compile_src +>: Needs() :+> package;
    gen_docs +>: Needs() :+> package;
    package +>: Needs() :+> publish;
}

test "diamond dep orders compile before docs and tests, package after both" {
    make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();
    lines = out.strip().split("\n");

    # Compile must appear before docs and tests; both must appear before package.
    order = lines[-6:] if len(lines) >= 6 else lines;
    body = "\n".join(order);

    assert "1. setup" in body, f"setup should be first: {out}";
    compile_idx = body.find("compile");
    docs_idx = body.find("docs");
    tests_idx = body.find("tests");
    package_idx = body.find("package");
    publish_idx = body.find("publish");

    assert compile_idx != -1 and docs_idx != -1 and tests_idx != -1, f"missing tasks: {out}";
    assert compile_idx < docs_idx, f"compile must precede docs: {out}";
    assert compile_idx < tests_idx, f"compile must precede tests: {out}";
    assert docs_idx < package_idx and tests_idx < package_idx, f"package after both deps: {out}";
    assert package_idx < publish_idx, f"publish after package: {out}";
}

test "total duration sums all six tasks" {
    make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();

    expected_total = 5 + 20 + 10 + 15 + 8 + 4;
    assert f"{expected_total} min total" in out, f"expected total {expected_total} in: {out}";
}

test "every task scheduled exactly once, all six included" {
    make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();

    assert "6 of 6 tasks" in out, f"should schedule all six: {out}";
    for n in ["setup", "compile", "docs", "tests", "package", "publish"] {
        assert n in out, f"missing {n} in: {out}";
    }
}

test "no cycle in valid DAG -- no stuck message" {
    make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();

    assert "Dependency cycle" not in out, f"DAG should not be flagged cyclic: {out}";
}

test "cycle among remaining tasks is detected, not silent" {
    # Reset persistent root.
    for stale in [root -->][?:Task] {
        del stale;
    }

    a = Task(name="A", duration=3);
    b = Task(name="B", duration=4);
    c = Task(name="C", duration=5);

    root ++> [a, b, c];

    # Cycle: A needs B, B needs C, C needs A.
    a +>: Needs() :+> b;
    b +>: Needs() :+> c;
    c +>: Needs() :+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Scheduler();
    }
    out = buf.getvalue();

    assert "Dependency cycle among remaining tasks -- stuck." in out, f"should report cycle: {out}";
    assert "0 of 3 tasks" in out, f"no tasks should be scheduled in pure cycle: {out}";
}

