"""Tests for the Analyst walker answering multi-hop knowledge-graph queries."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a small knowledge graph and return the Person to investigate.
def build_graph {
    alice = Person(name="Alice");
    bob = Person(name="Bob");
    carol = Person(name="Carol");
    dave = Person(name="Dave");

    acme = Company(name="Acme Robotics");
    globex = Company(name="Globex AI");

    metropolis = City(name="Metropolis");
    gotham = City(name="Gotham");

    alice +>: WorksAt(since=2019) :+> acme;
    bob +>: WorksAt(since=2023) :+> acme;
    carol +>: WorksAt(since=2022) :+> acme;
    dave +>: WorksAt(since=2018) :+> globex;

    alice +>: LivesIn() :+> metropolis;
    bob +>: LivesIn() :+> gotham;
    carol +>: LivesIn() :+> metropolis;
    dave +>: LivesIn() :+> metropolis;

    acme +>: HqIn() :+> metropolis;
    globex +>: HqIn() :+> gotham;

    return alice;
}

test "Q1 reports where each same-company colleague lives" {
    alice = build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Analyst();
    }
    out = buf.getvalue();
    assert "Where do Alice's colleagues live?" in out, f"missing Q1 header: {out}";
    assert "Bob lives in Gotham" in out, f"missing Bob/Gotham line: {out}";
    assert "Carol lives in Metropolis" in out, f"missing Carol/Metropolis line: {out}";
    # Self must be excluded: no "Alice lives in ..." line.
    assert "Alice lives in" not in out, f"self should be excluded: {out}";
}

test "Q2 lists companies headquartered in the person's city" {
    alice = build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Analyst();
    }
    out = buf.getvalue();
    assert "Companies headquartered in Alice's city" in out, f"missing Q2 header: {out}";
    assert "Acme Robotics" in out, f"Acme should be HQ'd in Metropolis: {out}";
    # Globex is HQ'd in Gotham, NOT Metropolis -> must not appear.
    assert "Globex AI" not in out, f"Globex shouldn't appear in Alice's city: {out}";
}

test "Q3 filters colleagues by WorksAt.since edge attribute" {
    alice = build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Analyst();
    }
    out = buf.getvalue();
    assert "Colleagues who joined since 2022" in out, f"missing Q3 header: {out}";
    # Bob joined in 2023 and Carol in 2022: both pass the >= 2022 predicate.
    assert "  Bob" in out, f"Bob (since=2023) should be a newcomer: {out}";
    assert "  Carol" in out, f"Carol (since=2022) should be a newcomer: {out}";
    # Alice's own edge (since=2019) fails the predicate; self also excluded.
    assert "  Alice" not in out, f"Alice (since=2019) should be filtered out: {out}";
}

test "Q1 excludes coworkers from other companies" {
    # Dave works at Globex, not Acme, so investigating Alice must not mention him.
    alice = build_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Analyst();
    }
    out = buf.getvalue();
    assert "Dave" not in out, f"Dave is at Globex, not Alice's company: {out}";
}

test "graph shape: typed edges have the expected direction and labels" {
    alice = build_graph();
    # Alice -> WorksAt -> Acme (outgoing)
    alice_works = [alice ->:WorksAt:->];
    assert len(alice_works) == 1, f"Alice should have exactly one WorksAt edge, got {alice_works}";
    assert alice_works[0].name == "Acme Robotics", f"got {alice_works[0].name}";
    # Acme -> HqIn -> Metropolis (outgoing from Company to City)
    acme_hq = [alice_works[0] ->:HqIn:->];
    assert len(acme_hq) == 1, f"Acme should be HQ'd in exactly one city: {acme_hq}";
    assert acme_hq[0].name == "Metropolis", f"got {acme_hq[0].name}";
}

