"""Tests for PermissionResolver role-inheritance walker."""

import io;
import from contextlib { redirect_stdout }

test "admin sees all permissions sorted with diamond merged" {
    root ++> Role(title="viewer");
    root ++> Role(title="editor");
    root ++> Role(title="publisher");
    root ++> Role(title="admin");

    can_read = Permission(action="doc:read");
    can_comment = Permission(action="doc:comment");
    can_edit = Permission(action="doc:edit");
    can_publish = Permission(action="doc:publish");
    can_manage = Permission(action="user:manage");

    viewer = [root -->][?:Role][0];
    editor = [root -->][?:Role][1];
    publisher = [root -->][?:Role][2];
    admin = [root -->][?:Role][3];

    viewer +>: Grants() :+> can_read;
    editor +>: Grants() :+> can_comment;
    editor +>: Grants() :+> can_edit;
    publisher +>: Grants() :+> can_publish;
    admin +>: Grants() :+> can_manage;

    admin +>: InheritsFrom() :+> publisher;
    publisher +>: InheritsFrom() :+> editor;
    editor +>: InheritsFrom() :+> viewer;
    admin +>: InheritsFrom() :+> viewer;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = admin spawn PermissionResolver();
    }
    out = buf.getvalue();

    assert "Effective permissions for 'admin'" in out, f"missing header: {out!r}";
    assert "(4 roles consulted)" in out, f"diamond should not double-count viewer: {out!r}";

    sorted_lines = sorted(
        ["doc:read", "doc:comment", "doc:edit", "doc:publish", "user:manage"]
    );
    out_lines = [l.strip() for l in out.splitlines() if l.strip().startswith("- ")];
    collected = [l.replace("- ", "").strip() for l in out_lines];
    assert collected == sorted_lines, f"expected sorted union {sorted_lines}, got {collected}";
    assert len(collected) == 5, f"duplicates leaked: {collected}";
}

test "viewer only sees its own single permission" {
    root ++> Role(title="viewer");
    viewer = [root -->][?:Role][0];
    viewer +>: Grants() :+> Permission(action="doc:read");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = viewer spawn PermissionResolver();
    }
    out = buf.getvalue();

    assert "Effective permissions for 'viewer'" in out, f"missing header: {out!r}";
    assert "(1 roles consulted)" in out, f"only viewer itself: {out!r}";
    assert "- doc:read" in out, f"missing its permission: {out!r}";
    assert "doc:edit" not in out, f"leaked permission: {out!r}";
    assert "doc:publish" not in out, f"leaked permission: {out!r}";
}

test "editor inherits viewer's read plus own comment and edit" {
    root ++> Role(title="viewer");
    root ++> Role(title="editor");
    viewer = [root -->][?:Role][0];
    editor = [root -->][?:Role][1];

    viewer +>: Grants() :+> Permission(action="doc:read");
    editor +>: Grants() :+> Permission(action="doc:comment");
    editor +>: Grants() :+> Permission(action="doc:edit");
    editor +>: InheritsFrom() :+> viewer;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = editor spawn PermissionResolver();
    }
    out = buf.getvalue();

    assert "Effective permissions for 'editor'" in out, f"missing header: {out!r}";
    assert "(2 roles consulted)" in out, f"editor and viewer: {out!r}";

    out_perms = [
        l.replace("- ", "").strip()
        for l in out.splitlines()
        if l.strip().startswith("- ")
    ];
    assert out_perms == ["doc:comment", "doc:edit", "doc:read"], f"got {out_perms}";
}

test "walker effective list is deduplicated and sorted" {
    root ++> Role(title="viewer");
    root ++> Role(title="editor");
    root ++> Role(title="admin");
    viewer = [root -->][?:Role][0];
    editor = [root -->][?:Role][1];
    admin = [root -->][?:Role][2];

    viewer +>: Grants() :+> Permission(action="doc:read");
    editor +>: Grants() :+> Permission(action="doc:read");
    editor +>: Grants() :+> Permission(action="doc:comment");
    admin +>: Grants() :+> Permission(action="doc:edit");
    admin +>: InheritsFrom() :+> editor;
    editor +>: InheritsFrom() :+> viewer;
    admin +>: InheritsFrom() :+> viewer;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = admin spawn PermissionResolver();
    }
    out = buf.getvalue();

    out_perms = [
        l.replace("- ", "").strip()
        for l in out.splitlines()
        if l.strip().startswith("- ")
    ];
    assert out_perms == ["doc:comment", "doc:edit", "doc:read"], f"dedupe+sort failed: {out_perms}";
    assert len(out_perms) == 3, f"doc:read duplicated: {out_perms}";
}

test "role with no grants and no parents reports empty list" {
    root ++> Role(title="loner");
    loner = [root -->][?:Role][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = loner spawn PermissionResolver();
    }
    out = buf.getvalue();

    assert "Effective permissions for 'loner'" in out, f"missing header: {out!r}";
    assert "(1 roles consulted)" in out, f"only the starting role: {out!r}";
    perm_lines = [l for l in out.splitlines() if l.strip().startswith("- ")];
    assert perm_lines == [], f"loner should have no perms, got {perm_lines}";
}

