"""Tests for the GreedyCourier delivery router."""

import io;
import from contextlib { redirect_stdout }

def build_graph() -> City {
    depot = City(name="Depot");
    hub = City(name="Hub");
    port = City(name="Port");
    mine = City(name="Mine");
    farm = City(name="Farm");

    depot +>: Route(cost=4.5) :+> farm;
    depot +>: Route(cost=9.0) :+> hub;
    farm +>: Route(cost=2.5) :+> mine;
    mine +>: Route(cost=2.5) :+> hub;
    hub +>: Route(cost=2.0) :+> port;
    farm +>: Route(cost=8.5) :+> port;

    return depot;
}

test "greedy picks cheapest next hop not globally optimal path" {
    depot = build_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        depot spawn GreedyCourier(dest="Port");
    }
    out = buf.getvalue();

    # Greedy from Depot: 4.5 to Farm, 2.5 to Mine, 2.5 to Hub, 2.0 to Port = 11.5
    # Globally optimal would be Depot->Hub->Port = 11.0
    # Greedy route should be Depot -> Farm -> Mine -> Hub -> Port
    assert "Depot -> Farm -> Mine -> Hub -> Port" in out, f"wrong greedy route: {out}";
    assert "Total cost: 11.5" in out, f"expected total cost 11.5: {out}";
}

test "reports destination arrival" {
    depot = build_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        depot spawn GreedyCourier(dest="Port");
    }
    out = buf.getvalue();

    assert "Delivery route:" in out, f"missing route header: {out}";
    assert "Port" in out, f"destination not mentioned: {out}";
    assert "Total cost:" in out, f"missing total cost: {out}";
}

test "dead end reports failure" {
    depot = City(name="Depot");
    alone = City(name="Alone");
    depot +>: Route(cost=1.0) :+> alone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        depot spawn GreedyCourier(dest="Nowhere");
    }
    out = buf.getvalue();

    assert "Dead end" in out, f"missing dead-end message: {out}";
    assert "Alone" in out, f"dead-end city name missing: {out}";
    assert "Delivery route" not in out, f"should not report delivery: {out}";
}

test "arrives immediately when start equals destination" {
    depot = City(name="Depot");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        depot spawn GreedyCourier(dest="Depot");
    }
    out = buf.getvalue();

    assert "Delivery route: Depot" in out, f"expected immediate arrival: {out}";
    assert "Total cost: 0.0" in out, f"expected zero cost: {out}";
}

test "route printed even when greedy is suboptimal" {
    depot = build_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        depot spawn GreedyCourier(dest="Port");
    }
    out = buf.getvalue();

    # Greedy should NOT find the true cheapest path (11.0 via Hub directly)
    # It finds 11.5 via Farm/Mine -- demonstrating the heuristic is not optimal
    assert "Total cost: 11.5" in out, f"greedy cost wrong: {out}";
    # The point: a route IS still printed even though it's suboptimal
    assert "Delivery route:" in out, f"route should still be reported: {out}";
}

