}

def parse_totals(out) {
    sub = None;
    ship = None;
    total = None;
    for line in out.splitlines() {
        if "SUBTOTAL" in line {
            sub = float(line.split("$")[-1].strip());
        }
        elif "SHIPPING" in line {
            ship = float(line.split("$")[-1].strip());
        }
        elif "TOTAL" in line {
            total = float(line.split("$")[-1].strip());
        }
    }
    return (sub, ship, total);
}

