test "digital book ships free with no paper surcharge" {
    root ++> Cart(owner="Alex");
    c = [root -->][?:Cart][0];
    c +>: Contains(qty=2) :+> Book(
        sku="DK-1", unit_price=7.50,
        title="Byte Stories", author="L. Park", fmt="digital",
