    assert sub == 30.0, f"subtotal should be $30.00, got {sub}";
    assert total == 36.0, f"total should be $36.00, got {total}";
    assert "(paper)" in out, f"expected (paper) marker, got: {out}";
}

test "electronics adds flat handling fee regardless of qty" {
    root ++> Cart(owner="Cam");
    c = [root -->][?:Cart][0];
    c +>: Contains(qty=5) :+> Electronics(
