    out = buf.getvalue();

    # The runner should announce escape and print a valid path.
    assert "Escaped after exploring" in out, f"missing escape line: {out}";
    assert "Path: " in out, f"missing Path line: {out}";

    # Path must start at A1 and end at the exit (D4).
    assert out.startswith("Escaped after exploring"), f"unexpected prefix: {out}";
    line2 = out.strip().splitlines()[1];
    route_str = line2.split("Path: ", 1)[1];
    route = route_str.split(" -> ");
    assert route[0] == "A1", f"path should start at A1, got {route[0]}";
    assert route[-1] == "D4", f"path should end at D4, got {route[-1]}";
    # No '#' wall cells can appear in the route.
    assert "#" not in route, f"path contains wall cells: {route}";

    # The walker should have recorded the same cells in its path field.
    assert res.path == route, f"walker.path mismatch: {res.path} vs {route}";
}

test "runner marks every cell it visits as seen" {
    grid = {};
    labels = [
        ["A1", "A2", "#", "A4"],
        ["B1", "B2", "#", "B4"],
        ["C1", "C2", "C3", "C4"],
        ["D1", "#", "#", "D4"],
    ];
    for row in labels {
        for lab in row {
            if lab != "#" {
                grid[lab] = Cell(label=lab);
            }
        }
    }

    open_pairs = [
        ["A1", "A2"], ["A1", "B1"],
        ["A2", "B2"], ["B1", "C1"], ["B2", "C2"],
        ["A4", "B4"], ["B4", "C4"],
        ["C1", "D1"], ["C1", "C2"], ["C2", "C3"],
        ["C3", "C4"], ["C4", "D4"],
    ];
    start_cell = grid["A1"];
    exit_cell = grid["D4"];
    exit_cell.is_exit = True;

    for pair in open_pairs {
        cell_a = grid[pair[0]];
        cell_b = grid[pair[1]];
        cell_a +>: Corridor() :+> cell_b;
        cell_b +>: Corridor() :+> cell_a;
    }

    root ++> start_cell;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = start_cell spawn MazeRunner();
    }

    # Every cell the walker recorded as visited must be flagged seen.
    for lab in res.path {
        assert grid[lab].seen, f"{lab} was on path but not marked seen";
    }
    # explored counter should equal the unique cells visited.
    assert res.explored == len(res.path), (
        f"explored={res.explored} path_len={len(res.path)}"
    );
}

test "dead-end cells are never re-entered" {
    # Tiny maze with a dead-end branch: A1 -> A2 (dead end, only neighbor A1)
    # and A1 -> B1 -> C1 (exit). DFS from A1 must reach C1 without
    # revisiting A2 after popping back from it.
    a1 = Cell(label="A1");
    a2 = Cell(label="A2");
    b1 = Cell(label="B1");
    c1 = Cell(label="C1", is_exit=True);

    a1 +>: Corridor() :+> a2;
    a2 +>: Corridor() :+> a1;
    a1 +>: Corridor() :+> b1;
    b1 +>: Corridor() :+> a1;
    b1 +>: Corridor() :+> c1;
    c1 +>: Corridor() :+> b1;

    root ++> a1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = a1 spawn MazeRunner();
    }
    out = buf.getvalue();

    assert "Escaped after exploring" in out, f"missing escape: {out}";
    # explored must be exactly 4 (A1, A2, B1, C1) — no re-entry of A2.
    assert res.explored == 4, (
        f"expected 4 cells explored, got {res.explored}; path={res.path}"
    );
    # Dead end A2 should appear exactly once in the route.
    assert res.path.count("A2") == 1, f"A2 revisited: {res.path}";
    assert res.path[0] == "A1", f"start wrong: {res.path}";
    assert res.path[-1] == "C1", f"end wrong: {res.path}";
}

test "corridor edges are bidirectional between adjacent cells" {
    # Build a minimal two-cell maze to confirm edges connect both ways.
    a = Cell(label="A");
    b = Cell(label="B", is_exit=True);
    a +>: Corridor() :+> b;
    b +>: Corridor() :+> a;
    root ++> a;

    # A should have exactly one outgoing Corridor neighbor, namely B.
    neighbors_a = [a ->:Corridor:->];
    assert len(neighbors_a) == 1, f"A neighbors: {len(neighbors_a)}";
    assert neighbors_a[0].label == "B", f"A neighbor not B: {neighbors_a[0].label}";

    # And the reverse direction must hold too — corridors are two-way.
    neighbors_b = [b ->:Corridor:->];
    assert len(neighbors_b) == 1, f"B neighbors: {len(neighbors_b)}";
    assert neighbors_b[0].label == "A", f"B neighbor not A: {neighbors_b[0].label}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = a spawn MazeRunner();
    }
    out = buf.getvalue();
    assert "Escaped after exploring 2 cells!" in out, f"bad escape line: {out}";
    assert "Path: A -> B" in out, f"bad path line: {out}";
    assert res.explored == 2, f"explored={res.explored}";
    assert res.path == ["A", "B"], f"path={res.path}";
}

