"""Tests for Comment-thread engagement aggregation.

The program under test declares `Comment` nodes with `text`, `likes`,
and `engagement_total` fields, plus `Reply` edges (reply -> parent),
and a `ThreadAggregator` walker that rolls up engagement bottom-up
via `can rollup with Comment exit` after `can descend with Comment entry`
drains every reply. We spawn the walker on a fresh graph we build
ourselves and verify rolled-up totals + ranking.
"""

import io;
import from contextlib { redirect_stdout }

test "two-level thread hot branch rollup" {
    # Mimic the hot branch: post_hot with r1, r2, and r1 -> r1a, r1b.
    post_hot = Comment(text="Walkers beat threads: discuss", likes=40);
    r1 = Comment(text="Strong agree, dispatch by arrival!", likes=12);
    r2 = Comment(text="Meh, callbacks forever.", likes=3);
    r1a = Comment(text="Found the 1998 developer", likes=25);
    r1b = Comment(text="arrival-based is the future", likes=7);

    root ++> post_hot;
    r1 +>: Reply() :+> post_hot;
    r2 +>: Reply() :+> post_hot;
    r1a +>: Reply() :+> r1;
    r1b +>: Reply() :+> r1;

    res = root spawn ThreadAggregator();

    # Leaves: r1a=25, r1b=7, r2=3.
    # r1 = 12 + 25 + 7 = 44.
    # post_hot = 40 + 44 + 3 = 87.
    assert r1a.engagement_total == 25, f"r1a got {r1a.engagement_total}";
    assert r1b.engagement_total == 7, f"r1b got {r1b.engagement_total}";
    assert r2.engagement_total == 3, f"r2 got {r2.engagement_total}";
    assert r1.engagement_total == 44, f"r1 got {r1.engagement_total}";
    assert post_hot.engagement_total == 87, f"post_hot got {post_hot.engagement_total}";

    # Graph shape sanity: exactly one direct child of root.
    assert len([root -->]) == 1, "root should have one direct child";
}

test "two-level thread cold branch rollup" {
    # Mimic the cold branch: post_cold -> c1 -> c1a.
    post_cold = Comment(text="Why graphs? Explain like I'm five", likes=15);
    c1 = Comment(text="Because data has shape.", likes=18);
    c1a = Comment(text="This. So much this.", likes=9);

    root ++> post_cold;
    c1 +>: Reply() :+> post_cold;
    c1a +>: Reply() :+> c1;

    res = root spawn ThreadAggregator();

    # c1a=9, c1=18+9=27, post_cold=15+27=42.
    assert c1a.engagement_total == 9, f"c1a got {c1a.engagement_total}";
    assert c1.engagement_total == 27, f"c1 got {c1.engagement_total}";
    assert post_cold.engagement_total == 42, f"post_cold got {post_cold.engagement_total}";
}

test "aggregator descends entire subtree and only leaves are roots of recursion" {
    # A deeper chain to confirm bottom-up behavior: top -> m1 -> m2 -> leaf.
    # leaf must finish before m2, which must finish before m1, which must
    # finish before top.
    top = Comment(text="top", likes=10);
    m1 = Comment(text="m1", likes=5);
    m2 = Comment(text="m2", likes=2);
    leaf = Comment(text="leaf", likes=7);

    root ++> top;
    m1 +>: Reply() :+> top;
    m2 +>: Reply() :+> m1;
    leaf +>: Reply() :+> m2;

    res = root spawn ThreadAggregator();

    assert leaf.engagement_total == 7, f"leaf got {leaf.engagement_total}";
    assert m2.engagement_total == 2 + 7, f"m2 got {m2.engagement_total}";
    assert m1.engagement_total == 5 + 2 + 7, f"m1 got {m1.engagement_total}";
    assert top.engagement_total == 10 + 5 + 2 + 7, f"top got {top.engagement_total}";

    # Reply edges must point from reply -> parent, not the other way.
    assert m1 in [top <-:Reply:<-], "m1 should point at top via Reply";
    assert m2 in [m1 <-:Reply:<-], "m2 should point at m1 via Reply";
}

test "ranking sorts top-level posts by rolled-up engagement" {
    # Rebuild the full two-thread board the program describes and capture
    # the printed ranking output, which must put post_hot (87) above
    # post_cold (42).
    post_hot = Comment(text="Walkers beat threads: discuss", likes=40);
    r1 = Comment(text="Strong agree, dispatch by arrival!", likes=12);
    r2 = Comment(text="Meh, callbacks forever.", likes=3);
    r1a = Comment(text="Found the 1998 developer", likes=25);
    r1b = Comment(text="arrival-based is the future", likes=7);
    post_cold = Comment(text="Why graphs? Explain like I'm five", likes=15);
    c1 = Comment(text="Because data has shape.", likes=18);
    c1a = Comment(text="This. So much this.", likes=9);

    root ++> post_hot;
    root ++> post_cold;
    r1 +>: Reply() :+> post_hot;
    r2 +>: Reply() :+> post_hot;
    r1a +>: Reply() :+> r1;
    r1b +>: Reply() :+> r1;
    c1 +>: Reply() :+> post_cold;
    c1a +>: Reply() :+> c1;

    threads = [post_hot, post_cold];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ThreadAggregator();

        # Reproduce the ranking block the program uses.
        board: list[dict] = [];
        for t in threads {
            board.append({"text": t.text, "total": t.engagement_total});
        }
        board.sort(key=lambda (e: any) { e["total"]; }, reverse=True);

        print("Threads ranked by total engagement:");
        for e in board {
            print(f"  {e['total']:>3} points  \"{e['text']}\"");
        }
    }
    out = buf.getvalue();

    assert post_hot.engagement_total == 87, f"hot got {post_hot.engagement_total}";
    assert post_cold.engagement_total == 42, f"cold got {post_cold.engagement_total}";

    assert "Threads ranked by total engagement:" in out,
        f"missing header in: {out}";
    # Hot (87) must appear before cold (42) in the printed ranking.
    hot_idx = out.find("Walkers beat threads: discuss");
    cold_idx = out.find("Why graphs? Explain like I'm five");
    assert hot_idx != -1 and cold_idx != -1,
        f"both posts should appear in output: {out}";
    assert hot_idx < cold_idx,
        f"hot should be ranked above cold: {out}";
}

test "leaf without own likes still gets folded subtree total" {
    # A reply with zero own likes must still pick up its descendants'
    # totals via the same rollup path.
    top2 = Comment(text="top2", likes=4);
    mid = Comment(text="mid", likes=0);
    leaf2 = Comment(text="leaf2", likes=11);

    root ++> top2;
    mid +>: Reply() :+> top2;
    leaf2 +>: Reply() :+> mid;

    res = root spawn ThreadAggregator();

    assert leaf2.engagement_total == 11, f"leaf2 got {leaf2.engagement_total}";
    assert mid.engagement_total == 11, f"mid got {mid.engagement_total}";
    assert top2.engagement_total == 4 + 11, f"top2 got {top2.engagement_total}";
}

