"""Read the public feed off the shared root.

This is the reader half of my micro-blog. Any caller -- even anonymous
-- can walk the shared root's children because the shared root's access
level floors at CONNECT, so listing posts needs no auth at all. Only
posts whose authors armed a READ grant show real content to other users;
on a single-user CLI run everything is visible since root.shared is just
root.
"""

node Post {
    has text: str;
    has author: str;
}

edge Posted { }

walker:pub publish_post {
    has text: str;
    has author: str = "anon";

    can run with Root entry {
        fresh = root.shared +>: Posted() :+> Post(text=self.text, author=self.author);
        grant(fresh, level=AccessLevel.READ);
    }
}

walker:pub read_feed {
    can run with Root entry {
        # Traversal from the shared commons; order follows creation order.
        posts = [p for p in [root.shared ->:Posted:->][?:Post]];
        report [{"author": p.author, "text": p.text} for p in posts];
    }
}

with entry {
    root spawn publish_post(text="first!", author="ada");
    root spawn publish_post(text="second post", author="ben");
    root spawn publish_post(text="a quiet third", author="cy");

    result = root spawn read_feed();
    print(result.reports);
}
```

jac_tests:
"""Tests for the public-feed reader (and included publisher).

Covers the behaviors the problem specifies:
- Anyone (no auth) can list posts off the shared public graph.
- Posts come back in creation order.
- Authors arming READ grants controls visibility (multi-user semantics);
  on a single-user / `root.shared is root` run everything is visible.
"""

import io;
import from contextlib { redirect_stdout }

test "single-user run lists every published post in creation order" {
    root ++> Post(text="ignored-orphan", author="noise");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn publish_post(text="first!", author="ada");
        root spawn publish_post(text="second post", author="ben");
        root spawn publish_post(text="a quiet third", author="cy");
        res = root spawn read_feed();
    }
    out = buf.getvalue();

    # Anonymous reader -- no auth, no args -- still gets the full feed.
    feed = res.reports[0];
    assert len(feed) == 3, f"expected 3 posts, got {len(feed)}: {feed}";
    assert feed[0]["author"] == "ada", f"first author wrong: {feed[0]}";
    assert feed[0]["text"]   == "first!", f"first text wrong: {feed[0]}";
    assert feed[1]["author"] == "ben", f"second author wrong: {feed[1]}";
    assert feed[1]["text"]   == "second post", f"second text wrong: {feed[1]}";
    assert feed[2]["author"] == "cy", f"third author wrong: {feed[2]}";
    assert feed[2]["text"]   == "a quiet third", f"third text wrong: {feed[2]}";

    # The demo block prints the same list we just asserted on.
    assert "[OUT]" in out or "first!" in out, f"missing printed feed: {out}";
}

test "shared root is reachable without any auth arguments" {
    # read_feed declares no `has` fields -- the whole point is "any caller,
    # even anonymous". Spawning it with zero init args must succeed.
    root spawn publish_post(text="hello world", author="ada");

    res = root spawn read_feed();
    assert len(res.reports) == 1, f"anonymous read failed: {res.reports}";
    assert res.reports[0][0]["text"] == "hello world";
}

test "only Post nodes reachable via Posted edges are returned" {
    # Stray data on the graph (different edge type, or a non-Post node
    # attached the same way) must not leak into the public feed.
    root ++> Post(text="orphan-post", author="noise");

    root spawn publish_post(text="real one", author="ada");

    res = root spawn read_feed();
    feed = res.reports[0];
    authors = [row["author"] for row in feed];
    assert authors == ["ada"], (
        f"non-Posted / unreachable posts leaked into feed: {authors}"
    );
}

test "feed returns the author and text keys promised by the API" {
    root spawn publish_post(text="schema check", author="sam");
    res = root spawn read_feed();
    row = res.reports[0][0];
    assert "author" in row, f"feed row missing 'author': {row}";
    assert "text"   in row, f"feed row missing 'text': {row}";
    assert row["author"] == "sam";
    assert row["text"]   == "schema check";
}

test "publish_post defaults author to 'anon' when omitted" {
    # The walker declares `has author: str = "anon"` -- explicit behavior.
    root spawn publish_post(text="nameless thought");
    res = root spawn read_feed();
    feed = res.reports[0];
    assert len(feed) == 1, f"expected single post: {feed}";
    assert feed[0]["author"] == "anon", (
        f"default author not applied: {feed[0]}"
    );
    assert feed[0]["text"] == "nameless thought";
}

