"""Tests for conditional archetype policy on Report node."""

import io;
import from contextlib { redirect_stdout }


test "published report returns READ via archetype hook" {
    root ++> Report(title="Q3 numbers", body="up and to the right", published=True);
    published_report = [root -->][?:Report][0];
    assert published_report is not None, "published report must exist";
    assert published_report.published is True, "published flag must be True";
    level = published_report.__jac_access__();
    assert level == AccessLevel.READ, f"published must yield READ, got {level}";
}

test "draft report returns None from archetype hook" {
    root ++> Report(title="draft roadmap", body="half baked", published=False);
    draft = [root -->][?:Report][0];
    assert draft is not None, "draft report must exist";
    assert draft.published is False, "draft flag must be False";
    level = draft.__jac_access__();
    assert level is None, f"draft must yield None, got {level}";
}

test "share_draft grants READ to a specific draft" {
    root ++> Report(title="secret memo", body="classified", published=False);
    draft = [root -->][?:Report][0];
    rid = jid(draft);

    res = root spawn share_draft(report_id=rid);
    assert len(res.reports) == 1, f"share_draft should report once, got {res.reports}";
    assert res.reports[0]["shared"] == "secret memo", f"unexpected shared payload: {res.reports}";

    # Hook still returns None — the grant is what opens this draft.
    assert draft.__jac_access__() is None, "hook must still fall through for drafts";
}

test "publish_report flips flag and reports success" {
    root ++> Report(title="internal notes", body="TBD", published=False);
    draft = [root -->][?:Report][0];
    rid = jid(draft);

    res = root spawn publish_report(report_id=rid);
    assert len(res.reports) == 1, f"publish_report should report once, got {res.reports}";
    assert res.reports[0]["published"] == "internal notes", f"unexpected payload: {res.reports}";

    # Flag flipped → hook now returns READ directly.
    assert draft.published is True, "publish_report must set published = True";
    assert draft.__jac_access__() == AccessLevel.READ, "after publish, hook must return READ";
}

test "list_reports shows published flag state correctly" {
    buf = io.StringIO();
    root ++> Report(title="released", body="v1", published=True);
    root ++> Report(title="wip", body="soon", published=False);

    with redirect_stdout(buf) {
        res = root spawn list_reports();
    }
    out = buf.getvalue();
