"""Test annex for ex_99_blog_platform.jac."""

test "publish creates article on shared graph" {
    res = root spawn publish(title="Hello", body="world");
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    assert "published" in res.reports[0], f"missing 'published' key: {res.reports[0]}";

    # Verify on the shared graph
    arts = [root.shared ->:Published:->][?:Article];
    assert len(arts) == 1, f"expected 1 article on shared, got {len(arts)}";
    assert arts[0].title == "Hello", f"got title={arts[0].title}";
    assert arts[0].body == "world", f"got body={arts[0].body}";
}

test "read_feed lists published articles" {
    root spawn publish(title="A", body="aa");
    root spawn publish(title="B", body="bb");
    root spawn publish(title="C", body="cc");

    res = root spawn read_feed();
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    feed = res.reports[0];
    assert isinstance(feed, list), f"feed not a list: {feed}";
    assert len(feed) == 3, f"expected 3 articles, got {len(feed)}";
    titles = sorted([a["title"] for a in feed]);
    assert titles == ["A", "B", "C"], f"got titles={titles}";
}

test "leave_comment attaches to article" {
    pub_res = root spawn publish(title="Post", body="content");
    aid = pub_res.reports[0]["published"];

    c_res = root spawn leave_comment(article_id=aid, text="nice", author="alice");
    assert len(c_res.reports) == 1, f"expected 1 report, got {len(c_res.reports)}";
    assert "commented" in c_res.reports[0], f"missing 'commented': {c_res.reports[0]}";

    # Verify comment exists on the article
    arts = [root.shared ->:Published:->][?:Article];
    target = None;
    for a in arts {
        if jid(a) == aid {
            target = a;
        }
    }
    assert target is not None, "published article not found";
    comments = [target ->:Feedback:->];
    assert len(comments) == 1, f"expected 1 comment, got {len(comments)}";
    assert comments[0].text == "nice", f"got text={comments[0].text}";
    assert comments[0].author == "alice", f"got author={comments[0].author}";
}

test "draft is private to author root" {
    res = root spawn save_draft(title="secret", body="hidden");
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    assert "draft" in res.reports[0], f"missing 'draft': {res.reports[0]}";

    # Draft lives on author's own root, not shared
    drafts = [root -->][?:Draft];
    assert len(drafts) == 1, f"expected 1 draft on author root, got {len(drafts)}";
    assert drafts[0].title == "secret", f"got title={drafts[0].title}";

    shared_arts = [root.shared ->:Published:->][?:Article];
    assert len(shared_arts) == 0, f"draft should not be on shared graph, got {len(shared_arts)}";
}

test "publish_draft moves content to shared" {
    d_res = root spawn save_draft(title="WIP", body="soon");
    did = d_res.reports[0]["draft"];

    p_res = root spawn publish_draft(draft_id=did);
    assert len(p_res.reports) == 1, f"expected 1 report, got {len(p_res.reports)}";
    assert "went_live" in p_res.reports[0], f"missing 'went_live': {p_res.reports[0]}";

    # Article now on shared graph
    arts = [root.shared ->:Published:->][?:Article];
    assert len(arts) == 1, f"expected 1 article on shared, got {len(arts)}";
    found = arts[0];
    assert found.title == "WIP", f"got title={found.title}";
    assert found.body == "soon", f"got body={found.body}";

    # Original draft must be gone from the author's root
    remaining = [root -->][?:Draft];
    assert len(remaining) == 0, f"draft should be deleted, found {len(remaining)}";
}

test "delete_article cascades to comments" {
    # Set up: publish an article and add comments
    pub_res = root spawn publish(title="Doomed", body="bye");
    aid = pub_res.reports[0]["published"];
    root spawn leave_comment(article_id=aid, text="first", author="x");
    root spawn leave_comment(article_id=aid, text="second", author="y");

    # Pre-delete sanity: article exists with comments
    arts_before = [root.shared ->:Published:->][?:Article];
    assert len(arts_before) == 1, f"pre-delete article count={len(arts_before)}";
    target = arts_before[0];
    pre_comments = [target ->:Feedback:->];
    assert len(pre_comments) == 2, f"pre-delete comment count={len(pre_comments)}";

    # Delete it
    del_res = root spawn delete_article(article_id=aid);
    assert len(del_res.reports) == 1, f"expected 1 report, got {len(del_res.reports)}";
    assert "deleted" in del_res.reports[0], f"missing 'deleted': {del_res.reports[0]}";
    removed = del_res.reports[0]["deleted"];
    assert len(removed) == 3, f"expected 3 removed (article+2 comments), got {len(removed)}";

    # Post-delete: article gone, feed empty
    arts_after = [root.shared ->:Published:->][?:Article];
    assert len(arts_after) == 0, f"article should be deleted, found {len(arts_after)}";

    feed_res = root spawn read_feed();
    feed = feed_res.reports[0];
    assert len(feed) == 0, f"feed should be empty after delete, got {len(feed)}";
}

test "delete_article reports nothing when id not found" {
    root spawn publish(title="Survivor", body="kept");

    res = root spawn delete_article(article_id="nonexistent_id");
    # No article matched -> doomed stays empty -> purge skip
    # Should produce no "deleted" report
    for r in res.reports {
        assert "deleted" not in r, f"unexpected delete report: {r}";
    }

    # Survivor still there
    arts = [root.shared ->:Published:->][?:Article];
    assert len(arts) == 1, f"survivor article missing, got {len(arts)}";
    assert arts[0].title == "Survivor", f"got title={arts[0].title}";
}

test "read_article returns body and comments" {
    pub_res = root spawn publish(title="Topic", body="detail");
    aid = pub_res.reports[0]["published"];
    root spawn leave_comment(article_id=aid, text="reply", author="bob");

    res = root spawn read_article(article_id=aid);
    assert len(res.reports) == 1, f"expected 1 report, got {len(res.reports)}";
    article = res.reports[0];
    assert article.get("title") == "Topic", f"got title={article.get('title')}";
    assert article.get("body") == "detail", f"got body={article.get('body')}";
    comments = article.get("comments");
    assert comments is not None, f"missing comments key: {article}";
    assert len(comments) == 1, f"expected 1 comment, got {len(comments)}";
    assert comments[0]["author"] == "bob", f"got author={comments[0]['author']}";
    assert comments[0]["text"] == "reply", f"got text={comments[0]['text']}";
}

