"""Tiny dungeon crawler: chain rooms as nodes, hide treasure in one, hunter walks until found."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
    has danger_level: int = 0;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        outcome = "treasure found!" if here.has_treasure else "empty";
        print(f"Room {self.rooms_checked}: {here.name} (danger {here.danger_level}) -> {outcome}");
        if here.has_treasure {
            print(f"Search complete after {self.rooms_checked} rooms.");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance Hall", danger_level=1)
        ++> Room(name="Mossy Corridor", danger_level=2)
        ++> Room(name="Flooded Antechamber", danger_level=4)
        ++> Room(name="Bone Pit", danger_level=6)
        ++> Room(name="Sealed Vault", danger_level=8, has_treasure=True)
        ++> Room(name="Hidden Treasury", danger_level=5)
        ++> Room(name="Dragon's Hoard", danger_level=10);
    root spawn Hunter();
}
```

jac_tests:
"""Test annex for the dungeon crawler: Hunter must count rooms, stop at the vault, and never visit rooms past it."""

import io;
import from contextlib { redirect_stdout }

test "hunter counts rooms and stops at treasure" {
    root ++> Room(name="Entrance Hall", danger_level=1)
        ++> Room(name="Mossy Corridor", danger_level=2)
        ++> Room(name="Sealed Vault", danger_level=8, has_treasure=True)
        ++> Room(name="Hidden Treasury", danger_level=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Hunter enters the dungeon..." in out, f"missing entry banner: {out}";
    assert "Room 1: Entrance Hall (danger 1) -> empty" in out, f"missing room 1 line: {out}";
    assert "Room 2: Mossy Corridor (danger 2) -> empty" in out, f"missing room 2 line: {out}";
    assert "Room 3: Sealed Vault (danger 8) -> treasure found!" in out, f"missing vault line: {out}";
    assert "Hidden Treasury" not in out, f"hunter must NOT visit past the vault: {out}";
    assert "Search complete after 3 rooms." in out, f"missing summary line: {out}";
    assert res.rooms_checked == 3, f"rooms_checked should be 3, got {res.rooms_checked}";
}

test "hunter stops immediately if first room has treasure" {
    root ++> Room(name="Treasure Room", danger_level=3, has_treasure=True)
        ++> Room(name="Should Not Visit", danger_level=9);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Room 1: Treasure Room (danger 3) -> treasure found!" in out, f"missing treasure line: {out}";
    assert "Should Not Visit" not in out, f"hunter must stop at first treasure: {out}";
    assert "Search complete after 1 rooms." in out, f"missing summary line: {out}";
    assert res.rooms_checked == 1, f"rooms_checked should be 1, got {res.rooms_checked}";
}

test "hunter with no treasure-bearing room disengages after last room" {
    root ++> Room(name="A", danger_level=1)
        ++> Room(name="B", danger_level=2)
        ++> Room(name="C", danger_level=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Room 1: A (danger 1) -> empty" in out, f"missing room A: {out}";
    assert "Room 2: B (danger 2) -> empty" in out, f"missing room B: {out}";
    assert "Room 3: C (danger 3) -> empty" in out, f"missing room C: {out}";
    assert "Search complete" not in out, f"no summary when treasure never found: {out}";
    assert "treasure found!" not in out, f"no treasure-found line when none present: {out}";
    assert res.rooms_checked == 3, f"rooms_checked should be 3, got {res.rooms_checked}";
}

test "hunter with no outgoing edges after entry does not crash" {
    # Entry banner prints, then the [-->] else disengage path triggers
    # without ever entering an explore step.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Hunter enters the dungeon..." in out, f"entry banner must still print: {out}";
    assert "Room 1" not in out, f"no room lines when no rooms exist: {out}";
    assert res.rooms_checked == 0, f"rooms_checked should be 0, got {res.rooms_checked}";
}

