```jac
"""Mutual friendships in a neighborhood: houses are nodes connected by bidirectional buddy edges."""

node House {
    has name: str = "";
    has color: str = "";
}

edge Buddy {
    has since: int = 2024;
}

walker Greeter {
    has origin: str = "";
    has hops: int = 0;

    can start with House entry {
        self.hops = self.hops + 1;
        print(f"Greeter from {self.origin} arrived at {here.name} after {self.hops} hop(s)");
        if here.name != self.origin {
            print(f"  -> reached buddy {here.name} from {self.origin}!");
            disengage;
        }
        next_houses = [-->];
        visit next_houses else {
            print(f"  -> {self.origin} found no buddy");
            disengage;
        }
    }

    can land with Root entry {
        print(f"Greeter from {self.origin} ended at root with nowhere else to go");
        disengage;
    }
}

with entry {
    maple = House(name="Maple", color="red");
    oak = House(name="Oak", color="brown");
    elm = House(name="Elm", color="green");

    maple +>:Buddy(since=2010):+> oak;
    oak +>:Buddy(since=2010):+> maple;

    maple +>:Buddy(since=2015):+> elm;
    elm +>:Buddy(since=2015):+> maple;

    oak +>:Buddy(since=2018):+> elm;
    elm +>:Buddy(since=2018):+> oak;

    root ++> maple;
    root ++> oak;
    root ++> elm;

    maple spawn Greeter(origin="Maple");
    oak spawn Greeter(origin="Oak");
}
```

jac_tests:
"""Tests for the mutual-friendships neighborhood program."""

import io;
import from contextlib { redirect_stdout }

test "buddy edges are bidirectional between Maple and Oak" {
    maple = House(name="Maple", color="red");
    oak = House(name="Oak", color="brown");

    maple +>:Buddy(since=2010):+> oak;
    oak +>:Buddy(since=2010):+> maple;

    oak_buddies = [oak->:Buddy:->];
    maple_buddies = [maple->:Buddy:->];
    assert "Maple" in [b.name for b in oak_buddies], f"Oak should reach Maple via Buddy edge, got {oak_buddies}";
    assert "Oak" in [b.name for b in maple_buddies], f"Maple should reach Oak via Buddy edge, got {maple_buddies}";
}

test "Greeter from Maple reaches Oak via forward traversal" {
    root ++> House(name="Maple", color="red");
    root ++> House(name="Oak", color="brown");

    maple_node = [root-->][?:House][0];
    oak_node = [root-->][?:House][1];

    maple_node +>:Buddy(since=2010):+> oak_node;
    oak_node +>:Buddy(since=2010):+> maple_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = maple_node spawn Greeter(origin="Maple");
    }
    out = buf.getvalue();
    assert "Greeter from Maple arrived at Maple after 1 hop(s)" in out, f"missing arrival at origin: {out}";
    assert "Greeter from Maple arrived at Oak after 2 hop(s)" in out, f"missing arrival at Oak: {out}";
    assert "reached buddy Oak from Maple!" in out, f"missing buddy success marker: {out}";
    assert "found no buddy" not in out, f"should not report no buddy when Oak exists: {out}";
}

test "Greeter from Oak reaches Maple via forward traversal" {
    root ++> House(name="Maple", color="red");
    root ++> House(name="Oak", color="brown");

    maple_node = [root-->][?:House][0];
    oak_node = [root-->][?:House][1];

    maple_node +>:Buddy(since=2010):+> oak_node;
    oak_node +>:Buddy(since=2010):+> maple_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = oak_node spawn Greeter(origin="Oak");
    }
    out = buf.getvalue();
    assert "Greeter from Oak arrived at Oak after 1 hop(s)" in out, f"missing arrival at origin: {out}";
    assert "Greeter from Oak arrived at Maple after 2 hop(s)" in out, f"missing arrival at Maple: {out}";
    assert "reached buddy Maple from Oak!" in out, f"missing buddy success marker: {out}";
}

test "Greeter does not bounce back and forth forever" {
    root ++> House(name="Maple", color="red");
    root ++> House(name="Oak", color="brown");

    maple_node = [root-->][?:House][0];
    oak_node = [root-->][?:House][1];

    maple_node +>:Buddy(since=2010):+> oak_node;
    oak_node +>:Buddy(since=2010):+> maple_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = maple_node spawn Greeter(origin="Maple");
    }
    out = buf.getvalue();
    arrival_count = out.count("reached buddy");
    assert arrival_count == 1, f"expected exactly one buddy reached, got {arrival_count}: {out}";
    arrival_lines = [line for line in out.splitlines() if "arrived at" in line];
    assert len(arrival_lines) == 2, f"expected exactly 2 arrivals (origin + buddy), got {len(arrival_lines)}: {arrival_lines}";
}

test "single-statement bidirectional creation produces two Buddy edges" {
    root ++> House(name="Maple", color="red");
    root ++> House(name="Oak", color="brown");

    maple_node = [root-->][?:House][0];
    oak_node = [root-->][?:House][1];

    maple_node +>:Buddy(since=2010):+> oak_node;
    oak_node +>:Buddy(since=2010):+> maple_node;

    fwd = [maple_node->:Buddy:->];
    rev = [oak_node->:Buddy:->];
    assert len(fwd) == 1, f"Maple should have exactly one forward Buddy edge, got {len(fwd)}";
    assert len(rev) == 1, f"Oak should have exactly one forward Buddy edge back, got {len(rev)}";
    assert fwd[0].name == "Oak", f"Maple's buddy should be Oak, got {fwd[0].name}";
    assert rev[0].name == "Maple", f"Oak's buddy should be Maple, got {rev[0].name}";
}

