```jac
"""Warehouse simulation: track robot stops per robot and boxes packed per station."""

node Robot {
    has name: str = "";
    has stops: int = 0;
}

node Station {
    has label: str = "";
    has boxes_packed: int = 0;
    has serving: str = "";
}

node Announcement {
    has robot_name: str = "";
    has station_label: str = "";
}

walker Auditor {
    can start with Root entry {
        print("Auditing warehouse activity...");
        visit [-->];
    }

    can tally_robot with Robot entry {
        here.stops += 1;
        print(f"Robot {here.name} total stops: {here.stops}");
        visit [-->];
    }

    can tally_station with Station entry {
        here.boxes_packed += 1;
        print(f"Station {here.label} total boxes packed: {here.boxes_packed}");
        visit [-->];
    }

    can read_announcement with Announcement entry {
        print(f"Announcement: robot {here.robot_name} stopped at station {here.station_label}");
        visit [-->];
    }
}

with entry {
    root ++> Robot(name="R2-D2")
        ++> Robot(name="BB-8")
        ++> Robot(name="WALL-E")
        ++> Station(label="Pack-1", serving="R2-D2")
        ++> Station(label="Pack-2", serving="BB-8")
        ++> Station(label="Pack-3", serving="WALL-E")
        ++> Announcement(robot_name="R2-D2", station_label="Pack-1")
        ++> Announcement(robot_name="BB-8", station_label="Pack-2")
        ++> Announcement(robot_name="WALL-E", station_label="Pack-3");
    root spawn Auditor();
}
```

