"""Test annex for warehouse simulation."""

import io;
import from contextlib { redirect_stdout }

test "robot stops are counted" {
    r1 = Robot(name="R2-D2");
    r2 = Robot(name="BB-8");
    root ++> r1;
    root ++> r2;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();
    assert r1.stops == 1, f"expected R2-D2 stops=1, got {r1.stops}";
    assert r2.stops == 1, f"expected BB-8 stops=1, got {r2.stops}";
    assert "Robot R2-D2 total stops: 1" in out, f"missing R2-D2 log: {out}";
    assert "Robot BB-8 total stops: 1" in out, f"missing BB-8 log: {out}";
}

test "station boxes packed are counted" {
    s1 = Station(label="Pack-1", serving="R2-D2");
    s2 = Station(label="Pack-2", serving="BB-8");
    s3 = Station(label="Pack-3", serving="WALL-E");
    root ++> s1;
    root ++> s2;
    root ++> s3;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();
    assert s1.boxes_packed == 1, f"expected Pack-1 boxes=1, got {s1.boxes_packed}";
    assert s2.boxes_packed == 1, f"expected Pack-2 boxes=1, got {s2.boxes_packed}";
    assert s3.boxes_packed == 1, f"expected Pack-3 boxes=1, got {s3.boxes_packed}";
    assert "Station Pack-1 total boxes packed: 1" in out, f"missing Pack-1 log: {out}";
    assert "Station Pack-2 total boxes packed: 1" in out, f"missing Pack-2 log: {out}";
    assert "Station Pack-3 total boxes packed: 1" in out, f"missing Pack-3 log: {out}";
}

test "announcements log robot and station pair" {
    a1 = Announcement(robot_name="R2-D2", station_label="Pack-1");
    a2 = Announcement(robot_name="BB-8", station_label="Pack-2");
    a3 = Announcement(robot_name="WALL-E", station_label="Pack-3");
    root ++> a1;
    root ++> a2;
    root ++> a3;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();
    assert "Announcement: robot R2-D2 stopped at station Pack-1" in out, f"missing R2-D2/Pack-1: {out}";
    assert "Announcement: robot BB-8 stopped at station Pack-2" in out, f"missing BB-8/Pack-2: {out}";
    assert "Announcement: robot WALL-E stopped at station Pack-3" in out, f"missing WALL-E/Pack-3: {out}";
}

test "full three-station line tallies correctly" {
    r1 = Robot(name="R2-D2");
    r2 = Robot(name="BB-8");
    r3 = Robot(name="WALL-E");
    s1 = Station(label="Pack-1", serving="R2-D2");
    s2 = Station(label="Pack-2", serving="BB-8");
    s3 = Station(label="Pack-3", serving="WALL-E");
    a1 = Announcement(robot_name="R2-D2", station_label="Pack-1");
    a2 = Announcement(robot_name="BB-8", station_label="Pack-2");
    a3 = Announcement(robot_name="WALL-E", station_label="Pack-3");
    root ++> r1;
    root ++> r2;
    root ++> r3;
    root ++> s1;
    root ++> s2;
    root ++> s3;
    root ++> a1;
    root ++> a2;
    root ++> a3;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();
    # Each Robot and Station node is visited exactly once from Root via [-->]
    assert r1.stops == 1, f"expected R2-D2 stops=1, got {r1.stops}";
    assert r2.stops == 1, f"expected BB-8 stops=1, got {r2.stops}";
    assert r3.stops == 1, f"expected WALL-E stops=1, got {r3.stops}";
    assert s1.boxes_packed == 1, f"expected Pack-1 boxes=1, got {s1.boxes_packed}";
    assert s2.boxes_packed == 1, f"expected Pack-2 boxes=1, got {s2.boxes_packed}";
    assert s3.boxes_packed == 1, f"expected Pack-3 boxes=1, got {s3.boxes_packed}";
    # Station.serving field carries which robot is being served
    assert s1.serving == "R2-D2", f"expected Pack-1 serving R2-D2, got {s1.serving}";
    assert s2.serving == "BB-8", f"expected Pack-2 serving BB-8, got {s2.serving}";
    assert s3.serving == "WALL-E", f"expected Pack-3 serving WALL-E, got {s3.serving}";
    # Graph shape: Root has 9 direct children
    assert len([root-->]) == 9, f"expected 9 direct children, got {len([root-->])}";
    assert "Auditing warehouse activity..." in out, f"missing audit header: {out}";
}

test "duplicate visits accumulate counts" {
    # Spawn twice on same Root: second pass should increment counters.
    r1 = Robot(name="R2-D2");
    s1 = Station(label="Pack-1", serving="R2-D2");
    root ++> r1;
    root ++> s1;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
        root spawn Auditor();
    }
    out = buf.getvalue();
    assert r1.stops == 2, f"expected R2-D2 stops=2 after two spawns, got {r1.stops}";
    assert s1.boxes_packed == 2, f"expected Pack-1 boxes=2 after two spawns, got {s1.boxes_packed}";
    assert "Robot R2-D2 total stops: 2" in out, f"missing accumulated stop log: {out}";
    assert "Station Pack-1 total boxes packed: 2" in out, f"missing accumulated box log: {out}";
}

