```jac
"""Rental shop media audit: walk a shelf of books, DVDs, and unclassified reels, counting items that hit the default path."""

node Book {
    has title: str = "";
    has author: str = "";
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

node Reel {
    has title: str = "";
    has format: str = "";
    has available: bool = True;
}

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        print("=== Media Shelf Audit ===");
        visit [-->] else { disengage; }
    }

    can shelve_book with Book entry {
        self.total += 1;
        status = "IN" if here.available else "OUT";
        print(f"[BOOK][{status}] '{here.title}' by {here.author}");
        visit [-->];
    }

    can shelve_dvd with DVD entry {
        self.total += 1;
        status = "IN" if here.available else "OUT";
        print(f"[DVD][{status}] '{here.title}' ({here.runtime} min)");
        visit [-->];
    }

    can default_reel with Reel entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"[REEL][DEFAULT] '{here.title}' (format={here.format}) — unclassified, fell through to default");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="The Hobbit", author="Tolkien")
        ++> Book(title="Dune", author="Herbert", available=False)
        ++> DVD(title="Blade Runner", runtime=117)
        ++> DVD(title="Spirited Away", runtime=125, available=False)
        ++> Reel(title="Archive #07", format="16mm")
        ++> Book(title="Circe", author="Miller");
    root spawn Auditor();
}
```

