"""Delivery dispatch checker: model depots and routes, then audit which loads qualify."""

node Route {
    has name: str = "";
    has cargo_tonnes: float = 0.0;
}

node Depot {
    has title: str = "";
}

walker DispatchAuditor {
    can start with Root entry {
        print(f"Auditing depots for dispatchable routes");
        visit [-->];
    }

    can audit_depot with Depot entry {
        print(f"Depot: {here.title}");
        visit [-->];
    }

    can audit_route with Route entry {
        qualifies = here.cargo_tonnes >= 2.0 and here.cargo_tonnes <= 8.0;
        status = "DISPATCH" if qualifies else "HOLD";
        print(f"  [{status}] {here.name}: {here.cargo_tonnes} tonnes");
        visit [-->];
    }
}

with entry {
    depot_a = Depot(title="North Hub");
    depot_b = Depot(title="South Hub");

    root ++> depot_a
        ++> Route(name="N-1", cargo_tonnes=1.5)
        ++> Route(name="N-2", cargo_tonnes=3.0)
        ++> Route(name="N-3", cargo_tonnes=8.0)
        ++> Route(name="N-4", cargo_tonnes=10.2);

    root ++> depot_b
        ++> Route(name="S-1", cargo_tonnes=5.5)
        ++> Route(name="S-2", cargo_tonnes=2.0)
        ++> Route(name="S-3", cargo_tonnes=0.8);

    root spawn DispatchAuditor();
}
