"""Warehouse robot: follow a cell-by-cell movement plan that restricts rolling vs stair-climbing."""

node Cell {
    has title: str = "";
    has year: int = 0;
    has allow_roll: bool = True;
    has allow_climb: bool = False;
}

walker WarehouseRobot {
    has route_name: str = "A";
    has path_log: list[str] = [];

    can start with Root entry {
        print(f"Warehouse robot starting route {self.route_name}");
        visit [-->];
    }

    can scan with Cell entry {
        mode = "";
        if here.allow_roll and not here.allow_climb {
            mode = "roll";
        } elif here.allow_climb and not here.allow_roll {
            mode = "climb";
        } else {
            mode = "roll";
        }
        label = f"{here.title}: {mode}";
        self.path_log.append(label);
        print(f"Cell {here.title} ({here.year}) -> {mode}");
        visit [-->];
    }
}

with entry {
    root ++> Cell(title="Loading Dock", year=1, allow_roll=True, allow_climb=False)
        ++> Cell(title="Aisle 3", year=2, allow_roll=True, allow_climb=False)
        ++> Cell(title="Stairwell A", year=3, allow_roll=False, allow_climb=True)
        ++> Cell(title="Mezzanine", year=4, allow_roll=False, allow_climb=True);
    root spawn WarehouseRobot(route_name="Route-1");
}
