"""Micro-blog reader: walk the public post graph in creation order and print every entry."""

node Post {
    has title: str = "";
    has author: str = "";
    has body: str = "";
    has created: int = 0;
    has published: bool = False;
}

walker Publisher {
    can start with Root entry {
        print(f"Publisher online — pushing posts to the public commons floor");
        visit [-->];
    }

    can publish with Post entry {
        here.published = True;
        status = "LIVE" if here.published else "DRAFT";
        print(f"[{status}] {here.title} by {here.author} (seq={here.created})");
        visit [-->];
    }
}

walker Reader {
    has caller: str = "anonymous";

    can start with Root entry {
        print(f"Reader '{self.caller}' is browsing the commons floor");
        visit [-->];
    }

    can read with Post entry {
        label = "OPEN" if here.published else "LOCKED";
        print(f"[{label}] #{here.created} {here.title} — {here.author}: {here.body}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Post(title="Hello world", author="ada", body="first post on the commons", created=1, published=True)
        ++> Post(title="Graph notes", author="ada", body="nodes and walkers all the way down", created=2, published=True)
        ++> Post(title="Draft sketch", author="lin", body="thinking out loud", created=3, published=False)
        ++> Post(title="Sunset log", author="lin", body="orange light over the hill", created=4, published=True)
        ++> Post(title="Random thought", author="ada", body="why do we park in driveways", created=5, published=True);

    root spawn Publisher();
    print("---");
    root spawn Reader(caller="guest-7421");
}
