import io;
import from contextlib { redirect_stdout }

# ---------- Reader walks published posts in creation order ----------
test "reader walks published posts in creation order" {
    root ++> Post(title="Hello world", author="ada", body="first post on the commons", created=1, published=True)
        ++> Post(title="Graph notes", author="ada", body="nodes and walkers all the way down", created=2, published=True)
        ++> Post(title="Draft sketch", author="lin", body="thinking out loud", created=3, published=False)
        ++> Post(title="Sunset log", author="lin", body="orange light over the hill", created=4, published=True)
        ++> Post(title="Random thought", author="ada", body="why do we park in driveways", created=5, published=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Reader(caller="guest-7421");
    }
    out = buf.getvalue();

    assert "Reader 'guest-7421' is browsing the commons floor" in out, f"missing reader header: {out}";
    # 4 published posts => 4 OPEN markers; 1 draft => 1 LOCKED marker
    assert out.count("[OPEN]") == 4, f"expected 4 OPEN posts, got {out.count('[OPEN]')}: {out}";
    assert out.count("[LOCKED]") == 1, f"expected 1 LOCKED post, got {out.count('[LOCKED]')}: {out}";

    # Creation order: seq=1,2,3,4,5 must appear in that order.
    seq_positions = [out.find(f"#{seq} ") for seq in [1, 2, 3, 4, 5]];
    assert -1 not in seq_positions, f"missing some seq marker: {seq_positions} in {out}";
    assert seq_positions == sorted(seq_positions), f"posts not in creation order: {seq_positions} in {out}";

    # Draft (created=3) must be flagged LOCKED, and its body must still be printed.
    assert "[LOCKED] #3 Draft sketch" in out, f"draft not labelled LOCKED: {out}";
    assert "thinking out loud" in out, f"draft body missing: {out}";
}

