"""Weather sweep: model stations as nodes and walk them with a weather walker."""

node Station {
    has location: str = "";
    has temperature: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_temp: float = 999.0;
    has max_temp: float = -999.0;

    can start with Root entry {
        print("Starting weather sweep...");
        visit [-->] else { disengage; }
    }

    can record with Station entry {
        print(f"  {here.location}: {here.temperature} C");
        self.readings.append(here.temperature);
        self.min_temp = here.temperature if here.temperature < self.min_temp else self.min_temp;
        self.max_temp = here.temperature if here.temperature > self.max_temp else self.max_temp;
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Station(location="North Field", temperature=12.5)
        ++> Station(location="River Valley", temperature=18.2)
        ++> Station(location="Downtown", temperature=22.8)
        ++> Station(location="Harbor", temperature=15.0)
        ++> Station(location="Highland", temperature=8.3);
    root spawn WeatherSweep();
    w = WeatherSweep();
    print(f"Full readings: {w.readings}");
    print(f"Min: {w.min_temp} C");
    print(f"Max: {w.max_temp} C");
}
