"""Anonymous book poll for a reading-club site: seed options, record votes on counters, report tallies."""

node Book {
    has title: str = "";
    has author: str = "";
}

node Counter {
    has label: str = "";
    has votes: int = 0;
}

walker SeedOptions {
    can start with Root entry {
        print("Seeding poll options...");
        root ++> Book(title="The Hobbit", author="Tolkien")
            ++> Counter(label="The Hobbit", votes=0)
            ++> Book(title="Dune", author="Herbert")
            ++> Counter(label="Dune", votes=0)
            ++> Book(title="Neuromancer", author="Gibson")
            ++> Counter(label="Neuromancer", votes=0);
        visit [-->] else { disengage; }
    }

    can announce with Book entry {
        print(f"  Option: {here.title} by {here.author}");
        visit [-->];
    }

    can ready with Counter entry {
        print(f"  Counter ready: {here.label} = {here.votes}");
        visit [-->];
    }
}

walker CastVote {
    has choice: str = "";
    can cast with Book entry {
        if here.title == self.choice {
            print(f"Click! Voter picked '{here.title}'");
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can tally with Counter entry {
        if here.label == self.choice {
            here.votes = here.votes + 1;
            print(f"   -> Tally for '{here.label}' is now {here.votes}");
            disengage;
        } else {
            visit [-->];
        }
    }
}

walker ReportTallies {
    can start with Root entry {
        print("--- Final Tallies ---");
        visit [-->] else { disengage; }
    }

    can scan_book with Book entry {
        visit [-->];
    }

    can scan_count with Counter entry {
        bar = "#" * here.votes;
        print(f"{here.label:<12} {here.votes:>3}  {bar}");
        visit [-->];
    }
}

with entry {
    root spawn SeedOptions();

    print("");
    print("Simulating anonymous clicks...");
    root spawn CastVote(choice="The Hobbit");
    root spawn CastVote(choice="Dune");
    root spawn CastVote(choice="Dune");
    root spawn CastVote(choice="The Hobbit");
    root spawn CastVote(choice="Neuromancer");
    root spawn CastVote(choice="Dune");

    print("");
    root spawn ReportTallies();
}
