```jac
"""Tiny dungeon crawler.

Rooms are chained nodes; one special room (the vault) holds the treasure.
A Hunter walker inspects each room in order, counting how many it has seen,
and the moment it steps into the vault it disengages so that rooms past
the vault are never visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_inspected += 1;
        print(f"Inspecting room #{self.rooms_inspected}: {here.name}");
        if here.has_treasure {
            print(f"Treasure found in '{here.name}'! Search ends.");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Guardroom")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Hidden Alcove")
        ++> Room(name="Back Exit");

    hunter = Hunter();
    root spawn hunter;
    print(f"Total rooms inspected before disengage: {hunter.rooms_inspected}");
}
```

