"""Gallery security console: log every visitor, and record extra inspections for curators."""

node Room {
    has name: str = "";
    has generic_log: list[str] = [];
    has inspections: list[dict] = [];
}

walker Visitor {
    has visitor_name: str = "";
    has visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.generic_log.append(f"{self.visitor_name} entered {here.name}");
        self.visits += 1;
        visit [-->];
    }
}

# Curator inherits Visitor behaviour: same generic entry logging,
# plus an extra inspection record and a personal counter.
walker Curator(Visitor) {
    has inspections_made: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Room entry {
        here.generic_log.append(f"{self.visitor_name} entered {here.name}");
        here.inspections.append({"curator": self.visitor_name, "room": here.name});
        self.visits += 1;
        self.inspections_made += 1;
        visit [-->];
    }
}

with entry {
    gallery_a = Room(name="Gallery A");
    gallery_b = Room(name="Gallery B");
    root ++> gallery_a ++> gallery_b;

    tourist = Visitor(visitor_name="Tourist Tina");
    curator = Curator(visitor_name="Curator Carla");

    root spawn tourist;
    root spawn curator;

    print("=== Generic logs ===");
    for r in [gallery_a, gallery_b] {
        for line in r.generic_log {
            print(line);
        }
    }

    print("=== Curator inspections ===");
    for r in [gallery_a, gallery_b] {
