```jac
"""Restaurant kitchen line health-inspection walker.

Two inspectors tour the same line: a ``TempAuditor`` that flags any
station whose temperature exceeds 40 C as a violation, and a
``VisitLogger`` that records every station visit. Both walkers run
across every station in the kitchen.
"""

node Station {
    has title: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

walker TempAuditor {
    has violations: int = 0;
    has checked: int = 0;

    can start with Root entry {
        print("TempAuditor: beginning kitchen inspection");
        visit [-->];
    }

    can audit with Station entry {
        self.checked += 1;
        if here.is_violation() {
            self.violations += 1;
            print(f"  [VIOLATION] {here.title} at {here.temperature} C");
        } else {
            print(f"  [OK] {here.title} at {here.temperature} C");
        }
        visit [-->];
    }
}

walker VisitLogger {
    has log: list[str] = [];

    can start with Root entry {
        print("VisitLogger: beginning station log");
        visit [-->];
    }

    can record with Station entry {
        self.log.append(f"{here.title} ({here.temperature} C)");
        print(f"  logged {here.title}");
        visit [-->];
    }
}

with entry {
    root ++> Station(title="Grill", temperature=180.0)
        ++> Station(title="Fryer", temperature=160.0)
        ++> Station(title="Cold Prep", temperature=4.0);

    auditor = TempAuditor();
    root spawn auditor;

    logger = VisitLogger();
    root spawn logger;

    print(
        f"TempAuditor checked {auditor.checked} stations, "
        f"flagged {auditor.violations} violation(s)"
    );
    print(f"VisitLogger recorded {len(logger.log)} stop(s): {logger.log}");
}
```

