import io;
import from contextlib { redirect_stdout }

# ---------- TempAuditor: flags stations above 40 C ----------

test "TempAuditor flags only stations above 40 C" {
    root ++> Station(title="Grill", temperature=180.0)
           ++> Station(title="Fryer", temperature=160.0)
           ++> Station(title="Cold Prep", temperature=4.0);

    auditor = TempAuditor();
    with redirect_stdout(io.StringIO()) {
        res = root spawn auditor;
    }

    assert res.checked == 3, f"checked should count every station, got {res.checked}";
    assert res.violations == 2, f"only Grill & Fryer are above 40 C, got {res.violations}";
}

test "TempAuditor reports zero violations when all stations are safe" {
    root ++> Station(title="Cold Prep", temperature=4.0)
           ++> Station(title="Salad Bar", temperature=6.0)
           ++> Station(title="Dessert", temperature=10.0);

    auditor = TempAuditor();
    with redirect_stdout(io.StringIO()) {
        res = root spawn auditor;
    }

    assert res.checked == 3, f"every station must be checked, got {res.checked}";
    assert res.violations == 0, f"no station above 40 C, got {res.violations}";
}

test "TempAuditor boundary at exactly 40 C is not a violation" {
    root ++> Station(title="Edge", temperature=40.0)
           ++> Station(title="Over", temperature=40.1);

    auditor = TempAuditor();
    with redirect_stdout(io.StringIO()) {
        res = root spawn auditor;
    }

    assert res.checked == 2, f"both stations checked, got {res.checked}";
    assert res.violations == 1, f"only 40.1 C should be flagged, got {res.violations}";
}

# ---------- VisitLogger: logs every station ----------

test "VisitLogger records every station visited" {
    root ++> Station(title="Grill", temperature=180.0)
           ++> Station(title="Fryer", temperature=160.0)
           ++> Station(title="Cold Prep", temperature=4.0);

    logger = VisitLogger();
    with redirect_stdout(io.StringIO()) {
        res = root spawn logger;
    }

    assert len(res.log) == 3, f"expected one entry per station, got {len(res.log)}";
    assert any("Grill" in e for e in res.log), f"Grill missing from log: {res.log}";
    assert any("Fryer" in e for e in res.log), f"Fryer missing from log: {res.log}";
    assert any("Cold Prep" in e for e in res.log), f"Cold Prep missing from log: {res.log}";
}

# ---------- Combined: both inspectors run at every station ----------

test "TempAuditor and VisitLogger both traverse every station" {
    root ++> Station(title="Grill", temperature=180.0)
           ++> Station(title="Fryer", temperature=160.0)
           ++> Station(title="Cold Prep", temperature=4.0);

    auditor = TempAuditor();
    logger = VisitLogger();

    with redirect_stdout(io.StringIO()) {
        a = root spawn auditor;
        l = root spawn logger;
    }

    # TempAuditor: 3 checked, 2 violations (Grill & Fryer > 40 C).
    assert a.checked == 3, f"TempAuditor checked should be 3, got {a.checked}";
    assert a.violations == 2, f"TempAuditor violations should be 2, got {a.violations}";

    # VisitLogger: one log entry per station.
    assert len(l.log) == 3, f"VisitLogger log should have 3 entries, got {len(l.log)}";

    # Both inspectors must agree on coverage: 3 == 3.
    assert a.checked == len(l.log), (
        f"auditor checked {a.checked} stations but logger logged {len(l.log)}"
    );
}

