"""Depot reachability: a single walker anchors at the depot list, fans out
through every depot, collects every store in one pass, and flags the
stores whose stock has dropped below the 20-unit threshold."""

node Depot {
    has name: str = "";
}

node Store {
    has name: str = "";
    has stock: int = 0;
}

walker ReachScanner {
    has low_stock_threshold: int = 20;
    has visited_depots: list = [];

    can start with Root entry {
        print("Anchoring scan across all depots from the depot list...");
        visit [-->];
    }

    can scan_depot with Depot entry {
        if here.name not in self.visited_depots {
            self.visited_depots.append(here.name);
            print(f"Reached depot {here.name}");
        }
        visit [-->];
    }

    can inspect_store with Store entry {
        flagged = "FLAGGED" if here.stock < self.low_stock_threshold else "OK";
        print(f"  Store {here.name}: stock={here.stock} -> {flagged}");
        visit [-->];
    }
}

with entry {
    depot_a = Depot(name="Depot-A");
    depot_b = Depot(name="Depot-B");
    depot_c = Depot(name="Depot-C");

    depot_list = [depot_a, depot_b, depot_c];
    root ++> depot_list;

    depot_a ++> Store(name="S1", stock=80)
        ++> Store(name="S2", stock=15)
        ++> Store(name="S3", stock=45);

    depot_b ++> Store(name="S4", stock=10)
        ++> Store(name="S5", stock=120);

    depot_c ++> Store(name="S6", stock=18)
        ++> Store(name="S7", stock=55)
        ++> Store(name="S8", stock=5);

    root spawn ReachScanner(low_stock_threshold=20);
}
