import io;
import from contextlib { redirect_stdout }


test "floor route from root logs every leg until dead end" {
    a = Cell(code="A", floor_target="B");
    b = Cell(code="B", floor_target="C");
    c = Cell(code="C", floor_target="D", stair_target="M");
    m = Cell(code="M", floor_target="N");
    n = Cell(code="N");

    root ++> a +>:FloorEdge:+> b +>:FloorEdge:+> c;
    c +>:StairEdge:+> m +>:FloorEdge:+> n;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        Robot() spawn root;
    }
    out = buf.getvalue();

    assert "at cell A" in out, f"expected A log, got: {out}";
    assert "at cell B" in out, f"expected B log, got: {out}";
    assert "at cell C" in out, f"expected C log, got: {out}";
    assert "at cell M" in out, f"expected M log (stair climb), got: {out}";
    assert "at cell N" in out, f"expected N log, got: {out}";
    # From C the plan permits FloorEdge to D, but D was never linked in,
    # so out-of-C the only actually-connected leg is the StairEdge to M.
    # The robot must NOT visit a non-existent D.
    assert "at cell D" not in out, f"robot must not visit unlinked D, got: {out}";
}

test "robot starting at C takes the stair climb because only StairEdge is connected" {
    a = Cell(code="A", floor_target="B");
    b = Cell(code="B", floor_target="C");
    c = Cell(code="C", floor_target="D", stair_target="M");
    m = Cell(code="M", floor_target="N");
    n = Cell(code="N");

    root ++> a +>:FloorEdge:+> b +>:FloorEdge:+> c;
    c +>:StairEdge:+> m +>:FloorEdge:+> n;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        Robot() spawn c;
    }
    out = buf.getvalue();

    assert "at cell C" in out, f"should log C, got: {out}";
    assert "at cell M" in out, f"stair climb from C should reach M, got: {out}";
    assert "at cell N" in out, f"floor roll from M should reach N, got: {out}";
    # D is not in the graph; the robot must NOT hop onto it even though
    # the plan names D as a floor_target.
    assert "at cell D" not in out, f"must not visit unlinked D, got: {out}";
}

test "cell with no allowed edge makes the robot stop and report" {
    # A lone cell hanging off root: no FloorEdge, no StairEdge.
    alone = Cell(code="ALONE");
    root ++> alone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        Robot() spawn root;
    }
    out = buf.getvalue();

    assert "at cell ALONE" in out, f"should announce arrival at ALONE, got: {out}";
    assert "no allowed leg; stopping" in out, f"expected stop message, got: {out}";
}

test "plan preferring floor over stair when both legs exist" {
    # At BOTH-cells the plan permits a FloorEdge to C. We also wire a
    # StairEdge to S, but the robot must prefer the floor roll because
    # the walker checks FloorEdge first.
    bx = Cell(code="BX");
    cx = Cell(code="CX");
    sx = Cell(code="SX");

    root ++> bx +>:FloorEdge:+> cx;
    bx +>:StairEdge:+> sx;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        Robot() spawn root;
    }
    out = buf.getvalue();

    assert "at cell BX" in out, f"expected BX log, got: {out}";
    assert "at cell CX" in out, f"floor roll should reach CX, got: {out}";
    # Stair must NOT be taken when a FloorEdge is available.
    assert "at cell SX" not in out, f"must not climb stairs when floor allowed, got: {out}";
