"""Event-page guestbook: two HTTP-spawnable walkers (sign + read) that also run standalone."""

node Guestbook {
    has name: str = "Guestbook";
    has entries: list = [];
}

walker SignGuestbook {
    has guest_name: str = "Anonymous";
    has message: str = "";

    can start with Root entry {
        visit [-->];
    }

    can sign with Guestbook entry {
        new_entry = {"guest": self.guest_name, "message": self.message};
        here.entries.append(new_entry);
        report {"action": "signed", "guest": self.guest_name, "message": self.message};
    }
}

walker ReadGuestbook {
    has limit: int = 5;

    can start with Root entry {
        visit [-->];
    }

    can read with Guestbook entry {
        recent = here.entries[-self.limit:] if len(here.entries) > self.limit else list(here.entries);
        report {"action": "read", "count": len(recent), "entries": recent};
    }
}

with entry {
    book = Guestbook(name="Launch Party");
    root ++> book;

    signer = SignGuestbook(guest_name="Ada", message="Loved the keynote!");
    root spawn signer;
    report1 = signer.reports;
    print(f"Signed: {report1}");

    reader = ReadGuestbook(limit=3);
    root spawn reader;
    report2 = reader.reports;
    print(f"Read: {report2}");
}
