"""Vet clinic round: pets as nodes, a vet walker tallies patients and shots."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print("Vet starting the rounds...");
        visit [-->];
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            here.needs_vaccine = False;
            self.shots_given += 1;
            print(f"  Gave a vaccine to {here.name} the {here.species}.");
        } else {
            print(f"  Checked {here.name} the {here.species} - no vaccine needed.");
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mittens", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True)
        ++> Pet(name="Goldie", species="fish", needs_vaccine=False)
        ++> Pet(name="Buddy", species="dog", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\n--- Round summary ---");
    print(f"Patients seen: {len(vet.patients)} ({vet.patients})");
    print(f"Shots given:   {vet.shots_given}");
}
