"""Weather sweep: stations hold a location and a Celsius reading; a walker sweeps them, then we report the full list with min and max."""

node Station {
    has location: str = "";
    has celsius: float = 0.0;
}

walker Meteorologist {
    has readings: list[float] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Station entry {
        self.readings.append(here.celsius);
        print(f"{here.location}: {here.celsius}C");
        visit [-->];
    }
}

with entry {
    root ++> Station(location="Northfield", celsius=18.5)
        ++> Station(location="Riverside", celsius=22.0)
        ++> Station(location="Hilltop", celsius=15.3)
        ++> Station(location="Lakeside", celsius=27.8);

    sweep = Meteorologist();
    root spawn sweep;

    print("--- readings ---");
    for r in sweep.readings {
        print(f"{r}C");
    }
    print("--- summary ---");
    min_r = min(sweep.readings);
    max_r = max(sweep.readings);
    print(f"min: {min_r}C, max: {max_r}C");
}
