"""Dungeon crawler: chain of rooms, one holds treasure; a hunter walks until it finds the vault, then stops."""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has seen: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.seen += 1;
        if here.is_treasure {
            self.found = True;
            print(f"Treasure found in '{here.name}' after inspecting {self.seen} room(s). Hunt ends.");
            disengage;
        }
        print(f"Inspected '{here.name}' (no treasure).");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Armory")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Throne Room")
        ++> Room(name="Dungeon Pit");

    root spawn Hunter();
}
```

