node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has seen: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.seen += 1;
        if here.is_treasure {
            self.found = True;
            print(f"Treasure found in '{here.name}' after inspecting {self.seen} room(s). Hunt ends.");
            disengage;
        }
        print(f"Inspected '{here.name}' (no treasure).");
        visit [-->] else { disengage; }
    }
}


import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. Treasure at the very first room: Hunter should inspect exactly one room
#    and never step into any successor.
# ---------------------------------------------------------------------------
test "hunter stops immediately when first room is the vault" {
    root ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Hallway")
        ++> Room(name="Armory");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.found is True, f"expected hunter.found True, got {res.found}";
    assert res.seen == 1, f"expected exactly 1 room inspected, got {res.seen}";
    assert "Treasure found in 'Vault'" in out, f"missing vault announcement: {out}";
    assert "Inspected 'Hallway'" not in out, f"hunter must not enter Hallway: {out}";
    assert "Inspected 'Armory'" not in out, f"hunter must not enter Armory: {out}";
}

# ---------------------------------------------------------------------------
# 2. Treasure in the middle: Hunter visits the treasure room plus all rooms
#    strictly before it, but MUST NOT visit any room after the vault.
# ---------------------------------------------------------------------------
test "hunter never visits rooms past the vault" {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Throne Room")
        ++> Room(name="Dungeon Pit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.found is True, f"expected hunter.found True, got {res.found}";
    assert res.seen == 3, f"expected 3 rooms inspected (Entrance, Hallway, Vault), got {res.seen}";
    assert "Inspected 'Entrance'" in out, f"should inspect Entrance: {out}";
    assert "Inspected 'Hallway'" in out, f"should inspect Hallway: {out}";
    assert "Treasure found in 'Vault'" in out, f"missing vault announcement: {out}";
    # Hard guarantee from the spec: rooms past the vault must never be visited.
    assert "Throne Room" not in out, f"hunter must never reach Throne Room: {out}";
    assert "Dungeon Pit" not in out, f"hunter must never reach Dungeon Pit: {out}";
}

# ---------------------------------------------------------------------------
# 3. The default chain from the problem statement: treasure is in the Vault
#    (4th of 6 rooms). Verify exact inspected count and post-vault silence.
# ---------------------------------------------------------------------------
test "default chain: vault is the fourth room, six rooms total" {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Armory")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Throne Room")
        ++> Room(name="Dungeon Pit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.found is True, f"expected hunter.found True, got {res.found}";
    assert res.seen == 4, f"expected 4 inspections (Entrance, Hallway, Armory, Vault), got {res.seen}";
    assert "Hunter enters the dungeon..." in out, f"missing entry banner: {out}";
    assert "Treasure found in 'Vault'" in out, f"missing vault announcement: {out}";
    # Spec: terminate entire search immediately when treasure is found.
    assert "Inspected 'Throne Room'" not in out, f"must not inspect Throne Room: {out}";
    assert "Inspected 'Dungeon Pit'" not in out, f"must not inspect Dungeon Pit: {out}";
    assert "Throne Room" not in out, f"Throne Room must never appear in output: {out}";
    assert "Dungeon Pit" not in out, f"Dungeon Pit must never appear in output: {out}";
}

# ---------------------------------------------------------------------------
# 4. No treasure anywhere: Hunter walks the whole chain, never sets found.
# ---------------------------------------------------------------------------
test "hunter traverses entire chain when no treasure exists" {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Armory")
        ++> Room(name="Throne Room");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.found is False, f"expected hunter.found False, got {res.found}";
    assert res.seen == 4, f"expected all 4 rooms inspected, got {res.seen}";
    assert "Inspected 'Entrance'" in out, f"missing Entrance: {out}";
    assert "Inspected 'Hallway'" in out, f"missing Hallway: {out}";
    assert "Inspected 'Armory'" in out, f"missing Armory: {out}";
    assert "Inspected 'Throne Room'" in out, f"missing Throne Room: {out}";
    assert "Treasure found" not in out, f"no treasure announcement expected: {out}";
}

# ---------------------------------------------------------------------------
# 5. Single-room dungeon where the only room IS the treasure.
# ---------------------------------------------------------------------------
test "single-room dungeon that is itself the vault" {
    root ++> Room(name="OnlyVault", is_treasure=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.found is True, f"expected hunter.found True, got {res.found}";
    assert res.seen == 1, f"expected 1 inspection, got {res.seen}";
    assert "Treasure found in 'OnlyVault'" in out, f"missing vault announcement: {out}";
}

