"""Test annex for orchard irrigation tour."""

import io;
import from contextlib { redirect_stdout }

test "pump service logs and resets idle counter" {
    p = Pump(kind="pump", idle_hours=12);
    buf = io.StringIO();
    with redirect_stdout(buf) {
