    assert "12" in out, f"expected logged idle hours (12) in output: {out}";
    assert logged == 12, f"expected service to return 12, got {logged}";
    assert p.idle_hours == 0, f"expected idle_hours reset to 0, got {p.idle_hours}";
}

test "sprinkler service logs and resets idle counter" {
    s = Sprinkler(kind="sprinkler", idle_hours=7);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        logged = s.service();
    }
    out = buf.getvalue();
    assert "[sprinkler]" in out, f"missing sprinkler log marker: {out}";
    assert "7" in out, f"expected logged idle hours (7) in output: {out}";
    assert logged == 7, f"expected service to return 7, got {logged}";
    assert s.idle_hours == 0, f"expected idle_hours reset to 0, got {s.idle_hours}";
}

test "crew walks chain of mixed devices and totals idle hours" {
    root ++> Pump(kind="pump", idle_hours=12)
        ++> Sprinkler(kind="sprinkler", idle_hours=7)
        ++> Pump(kind="pump", idle_hours=3)
        ++> Sprinkler(kind="sprinkler", idle_hours=15);

    crew = MaintenanceCrew();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn crew;
    }
    out = buf.getvalue();

    assert "Crew entering the orchard" in out, f"missing crew entry log: {out}";
    assert "[pump]" in out, f"missing pump log marker: {out}";
    assert "[sprinkler]" in out, f"missing sprinkler log marker: {out}";
    assert out.count("[pump]") == 2, f"expected 2 pump service logs, got {out.count('[pump]')}: {out}";
    assert out.count("[sprinkler]") == 2, f"expected 2 sprinkler service logs, got {out.count('[sprinkler]')}: {out}";

    assert crew.devices_serviced == 4, f"expected 4 devices serviced, got {crew.devices_serviced}";
    assert crew.total_idle_hours == 37, f"expected 37 total idle hours (12+7+3+15), got {crew.total_idle_hours}";

    pumps = [root-->][?:Pump];
    sprinklers = [root-->][?:Sprinkler];
    for p in pumps {
        assert p.idle_hours == 0, f"pump idle_hours not reset, got {p.idle_hours}";
    }
    for s in sprinklers {
        assert s.idle_hours == 0, f"sprinkler idle_hours not reset, got {s.idle_hours}";
    }
}

test "union trigger fires on every device kind via single tour ability" {
    # Build separate single-device subtrees so we can isolate each kind's
