"""Tests for the pet-or-person friend recommender walker."""

import io;
import from contextlib { redirect_stdout}

test "alice filters minors and pets, keeps adult humans" {
    root ++> Profile(name="Alice", species="human", age=34);
    alice = [root -->][0];

    bob  = Profile(name="Bob",  species="human", age=29);
    teen = Profile(name="Cara", species="human", age=16);
    rex  = Profile(name="Rex",  species="pet",   age=7);

    alice +>:Friend:+> bob;
    alice +>:Friend:+> teen;
    alice +>:Friend:+> rex;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Recommender();
    }
    out = buf.getvalue();

    assert res.raw_seen == 3, f"raw neighbours should count every Friend edge: got {res.raw_seen}";
    assert res.kept == 1, f"only adult-human Bob should survive filter: got {res.kept}";
    assert "Alice" in out and "raw neighbours=3" in out, f"missing raw count line: {out}";
    assert "adult-human suggestions=1" in out, f"missing kept count line: {out}";
}

test "dana sees two adult humans among her neighbours" {
    root ++> Profile(name="Dana", species="human", age=42);
    dana = [root -->][0];

    bob   = Profile(name="Bob",   species="human", age=29);
    luna  = Profile(name="Luna",  species="pet",   age=3);
    alice = Profile(name="Alice", species="human", age=34);

    dana +>:Friend:+> bob;
    dana +>:Friend:+> luna;
    dana +>:Friend:+> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = dana spawn Recommender();
    }
    out = buf.getvalue();

    assert res.raw_seen == 3, f"raw neighbours should count every Friend edge: got {res.raw_seen}";
    assert res.kept == 2, f"Bob and Alice are both adult humans, must be kept: got {res.kept}";
    assert "Dana" in out and "raw neighbours=3" in out and "adult-human suggestions=2" in out, f"bad output: {out}";
}

test "person whose only friends are filtered out keeps zero suggestions" {
    root ++> Profile(name="Eve", species="human", age=50);
    eve = [root -->][0];

    teen = Profile(name="Teen", species="human", age=15);
    rex  = Profile(name="Rex",  species="pet",   age=8);
    luna = Profile(name="Luna", species="pet",   age=2);

    eve +>:Friend:+> teen;
    eve +>:Friend:+> rex;
    eve +>:Friend:+> luna;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = eve spawn Recommender();
    }
    out = buf.getvalue();

    assert res.raw_seen == 3, f"raw neighbours should still count filtered ones: got {res.raw_seen}";
    assert res.kept == 0, f"nothing adult-human here, kept must be 0: got {res.kept}";
    assert "raw neighbours=3" in out and "adult-human suggestions=0" in out, f"bad output: {out}";
}

test "person with no friends at all prints zeros" {
    root ++> Profile(name="Solo", species="human", age=40);
    solo = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = solo spawn Recommender();
    }
    out = buf.getvalue();

    assert res.raw_seen == 0, f"no friend edges means no raw neighbours: got {res.raw_seen}";
    assert res.kept == 0, f"no friend edges means no kept suggestions: got {res.kept}";
    assert "raw neighbours=0" in out and "adult-human suggestions=0" in out, f"bad output: {out}";
}

test "boundary age 18 is kept, age 17 is filtered" {
    root ++> Profile(name="Host", species="human", age=40);
    host = [root -->][0];

    boundary_adult = Profile(name="BoundaryAdult", species="human", age=18);
    boundary_minor = Profile(name="BoundaryMinor", species="human", age=17);

    host +>:Friend:+> boundary_adult;
    host +>:Friend:+> boundary_minor;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = host spawn Recommender();
    }
    out = buf.getvalue();

    assert res.raw_seen == 2, f"raw count must include the minor: got {res.raw_seen}";
    assert res.kept == 1, f"age 18 must survive the >= 18 filter: got {res.kept}";
    assert "raw neighbours=2" in out and "adult-human suggestions=1" in out, f"bad output: {out}";
}

