"""Moderation sweep over game accounts.

Members are audited normally, admins get a reputation boost, and the
welcome desk greets every bot regardless of which walker arrives.
"""

node Member {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reputation: int = 0;
}

node Admin {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reputation: int = 0;
}

node Bot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Moderator {
    can start with Root entry {
        print("Moderation sweep starting");
        visit [-->];
    }

    can audit with Member | Admin entry {
        if here.available {
            print(f"[OK] {here.title} ({here.year}) rep={here.reputation}");
        } else {
            print(f"[FLAG] {here.title} ({here.year}) rep={here.reputation}");
        }
        visit [-->];
    }
}

walker AdminBooster {
    can start with Root entry {
        print("Admin reputation boost pass");
        visit [-->];
    }

    can boost with Admin entry {
        old_rep = here.reputation;
        here.reputation = here.reputation + 5;
        print(f"[BOOST] {here.title}: {old_rep} -> {here.reputation}");
        visit [-->];
    }
}

walker BotGreeter {
    can start with Root entry {
        print("Bot greeter entering");
        visit [-->];
    }

    can greet with Bot entry {
        print(f"[GREET] Hello bot {here.title} ({here.year})");
        visit [-->];
    }
}

with entry {
    root ++> Member(title="alice", year=2019, available=True, reputation=42)
        ++> Admin(title="boss", year=2017, available=True, reputation=100)
        ++> Member(title="carol", year=2022, available=False, reputation=15)
        ++> Bot(title="helper-bot", year=2024)
        ++> Bot(title="scanner-bot", year=2023);

    root spawn Moderator();
    print("---");
    root spawn AdminBooster();
    print("---");
    root spawn BotGreeter();
}
