"""Test annex for the Delivery Route Dispatcher program."""

import io;
import from contextlib { redirect_stdout }

test "qualifying route returns True; out-of-range returns False" {
    root ++> Depot(location="TestDepot");
    dep = [root -->][0];

    # Same depot, different routes — exercise the qualifier directly.
    assert dep.qualifies(2.0) == True, "lower bound 2.0 should qualify";
    assert dep.qualifies(8.0) == True, "upper bound 8.0 should qualify";
    assert dep.qualifies(5.5) == True, "middle value should qualify";
    assert dep.qualifies(1.5) == False, "1.5 is below the minimum";
    assert dep.qualifies(9.0) == False, "9.0 is above the maximum";
    assert dep.qualifies(0.0) == False, "0.0 is below the minimum";
}

test "dispatcher counts exactly the routes in [2.0, 8.0] range" {
    # Build a known graph: 2 in-range routes + 2 out-of-range routes.
    depot = Depot(location="CountDepot");
    depot ++> Route(name="low", weight=1.5)
        ++> Route(name="ok1", weight=3.0)
        ++> Route(name="ok2", weight=8.0)
        ++> Route(name="high", weight=10.0);
    root ++> depot;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatcher();
    }

    assert res.dispatched_count == 2, f"expected 2 dispatched routes, got {res.dispatched_count}";
    out = buf.getvalue();
    assert "[DISPATCH] ok1 (3.0t)" in out, f"ok1 should be dispatched: {out}";
    assert "[DISPATCH] ok2 (8.0t)" in out, f"ok2 (8.0, boundary) should be dispatched: {out}";
    assert "[HOLD] low (1.5t)" in out, f"low should be held: {out}";
    assert "[HOLD] high (10.0t)" in out, f"high should be held: {out}";
}

test "boundary weights 2.0 and 8.0 are dispatched" {
    depot = Depot(location="BoundaryDepot");
    depot ++> Route(name="lower-bound", weight=2.0)
        ++> Route(name="upper-bound", weight=8.0);
    root ++> depot;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatcher();
    }

    assert res.dispatched_count == 2, f"both boundaries should dispatch, got {res.dispatched_count}";
    out = buf.getvalue();
    assert "DISPATCH" in out, f"expected DISPATCH marker in output: {out}";
    assert "HOLD" not in out, f"no HOLD expected for boundary values: {out}";
}

test "inspect_route disengages after a route leaf" {
    # A route with no outgoing edges must not cause errors; walker should
    # disengage cleanly and the per-route line must still be printed.
    depot = Depot(location="LeafDepot");
    depot ++> Route(name="solo", weight=4.0);
    root ++> depot;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatcher();
    }

    assert res.dispatched_count == 1, f"expected 1 dispatch on leaf route, got {res.dispatched_count}";
    out = buf.getvalue();
