    assert "hello: first post on the commons" in out, f"missing hello: {out!r}";
    assert "weather: sunny today" in out, f"missing weather: {out!r}";
    assert "goodnight: see you tomorrow" in out, f"missing goodnight: {out!r}";

    h_idx = out.index("hello: first post on the commons");
    w_idx = out.index("weather: sunny today");
    g_idx = out.index("goodnight: see you tomorrow");
    assert h_idx < w_idx < g_idx, f"order wrong: hello={h_idx} weather={w_idx} goodnight={g_idx}";
