"""Dungeon crawler: chain of room nodes, hunter searches for the treasure room."""

node Room {
    has name: str = "";
    has treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can search with Room entry {
        self.rooms_checked += 1;
        if here.treasure {
            print(f"Found treasure in '{here.name}' after checking {self.rooms_checked} room(s). Hunt over.");
            disengage;
        } else {
            print(f"Checked '{here.name}' — empty.");
            visit [-->];
        }
