"""Regression tests for the bug tracker 'connect and grab' form."""

import io;
import from contextlib { redirect_stdout }

test "walrus captures connected Ticket and fields are readable immediately" {
    root ++> (p := Project(name="BugBot"));

    p ++> (t1 := Ticket(title="Login crashes on Safari", priority="high"));
    p ++> (t2 := Ticket(title="Typo in footer", priority="low"));
    p ++> (t3 := Ticket(title="Race condition in queue", priority="critical", available=False));

    # Walrus must capture the very same node that got linked under `p`.
    tickets = [p -->];
    assert len(tickets) == 3, f"expected 3 tickets linked, got {len(tickets)}";
    assert t1 in tickets, "t1 not found under project p";
    assert t2 in tickets, "t2 not found under project p";
    assert t3 in tickets, "t3 not found under project p";

    # Fields must be readable off the captured node without any lookup.
    assert t1.title == "Login crashes on Safari", f"t1.title={t1.title}";
    assert t1.priority == "high", f"t1.priority={t1.priority}";
    assert t2.title == "Typo in footer", f"t2.title={t2.title}";
    assert t2.priority == "low", f"t2.priority={t2.priority}";
    assert t3.title == "Race condition in queue", f"t3.title={t3.title}";
    assert t3.priority == "critical", f"t3.priority={t3.priority}";
    assert t3.available == False, f"t3.available={t3.available}";

    # Capture survives an independent connection: still the same node.
    p ++> (t3_again := Ticket(title="Race condition in queue", priority="critical", available=False));
    assert t3_again in [p -->], "second walrus capture not linked";
}

test "auditor walks Root -> Project -> Ticket and prints OPEN/CLOSED status" {
    root ++> (p := Project(name="BugBot"));
    p ++> (t1 := Ticket(title="Login crashes on Safari", priority="high"));
    p ++> (t2 := Ticket(title="Typo in footer", priority="low"));
    p ++> (t3 := Ticket(title="Race condition in queue", priority="critical", available=False));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert "--- Project walk ---" in out, f"missing walk banner: {out}";
    assert "Project: BugBot" in out, f"missing project line: {out}";

    # OPEN ticket (available=True) and CLOSED ticket (available=False).
    assert "[OPEN] Login crashes on Safari (priority=high)" in out, f"missing t1 line: {out}";
    assert "[OPEN] Typo in footer (priority=low)" in out, f"missing t2 line: {out}";
    assert "[CLOSED] Race condition in queue (priority=critical)" in out, f"missing t3 line: {out}";

    # Status prefix must be deterministic and exclusive.
    assert "[OPEN]" in out, f"missing OPEN marker: {out}";
    assert "[CLOSED]" in out, f"missing CLOSED marker: {out}";
    assert "[OPEN] Race condition" not in out, "closed ticket wrongly labeled OPEN";
}

test "default values for Ticket are honored when walrus fields omitted" {
    root ++> (p := Project(name="Defaults"));

    # Only `title` provided — priority defaults to "low", available defaults to True.
    p ++> (t_default := Ticket(title="Default ticket"));
    assert t_default.title == "Default ticket", f"title={t_default.title}";
    assert t_default.priority == "low", f"priority default broken: {t_default.priority}";
    assert t_default.available == True, f"available default broken: {t_default.available}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();
    assert "[OPEN] Default ticket (priority=low)" in out, f"default audit line missing: {out}";
}

test "walrus-captured project and ticket are the same instance linked in the graph" {
    root ++> (p := Project(name="BugBot"));
    p ++> (t := Ticket(title="Unique", priority="high"));

    # `p` was captured via walrus off `root` and must be the very node under root.
    children_of_root = [root -->];
    assert p in children_of_root, "captured project p is not under root";

    # `t` was captured via walrus off `p` and must be the very node under p.
    children_of_p = [p -->];
    assert len(children_of_p) == 1, f"expected 1 ticket under p, got {len(children_of_p)}";
    assert t is children_of_p[0], "captured t is not the same instance linked under p";
}

