    # Strict > comparison: exactly 75.0 and 50.0 are NOT alerts
    assert "[nominal] Boundary-temp" in out, f"75.0 C should be nominal: {out}";
    assert "[nominal] Boundary-smoke" in out, f"50.0 ppm should be nominal: {out}";
    assert len(p.alerts) == 0, f"no alerts expected at threshold, got {p.alerts}";
}

test "mixed zone with both alert and nominal sensors reports correctly" {
    zone_mixed = Zone(name="Mixed");
    root ++> zone_mixed;
    zone_mixed ++> TempSensor(label="Hot", celsius=120.0);
    zone_mixed ++> SmokeSensor(label="Clean", ppm=0.0);

