"""Tests for the wildlife park feeding rounds program."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Zookeeper feeds every animal its species-appropriate meal and
# increments meals_delivered exactly once per animal.
# ---------------------------------------------------------------------------
test "zookeeper feeds species-appropriate meals" {
    root ++> InfoKiosk(kiosk_name="Gate A")
        ++> Lion(name="Leo")
        ++> Parrot(name="Polly")
        ++> Zebra(name="Zara");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        keeper = Zookeeper(badge="ZK-100");
        res = root spawn keeper;
    }
    out = buf.getvalue();

    # Every animal must report being fed.
    assert "[MEAT]   Leo the lion has been fed" in out, f"lion not fed: {out}";
    assert "[SEED]   Polly the parrot has been fed" in out, f"parrot not fed: {out}";
    assert "[FEED]   Zara the zebra has been fed" in out, f"zebra not fed: {out}";

    # Meal tags must be species-specific.
    assert "[MEAT]" in out, "lion should get MEAT";
    assert "[SEED]" in out, "parrot should get SEED";
    assert "[FEED]" in out, "zebra should get FEED";
    # Cross-feeding must NOT happen.
    assert "[MEAT]   Polly" not in out, "parrot got meat?";
    assert "[SEED]   Leo" not in out, "lion got seed?";
    assert "[FEED]   Leo" not in out, "lion got standard feed?";

    # Counter behavior.
    assert res.meals_delivered == 3, f"expected 3 meals, got {res.meals_delivered}";
}

# ---------------------------------------------------------------------------
# Test 2: Zookeeper traverses through the InfoKiosk on the way to the animals
# and the kiosk greets both Zookeepers and SchoolGroups.
# ---------------------------------------------------------------------------
test "kiosk greets both visitor types" {
    root ++> InfoKiosk(kiosk_name="Main Gate")
        ++> Lion(name="Leo");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        keeper = Zookeeper(badge="ZK-200");
        root spawn keeper;

        group = SchoolGroup(school_name="Sunnybrook");
        root spawn group;
    }
    out = buf.getvalue();

    # Greeting labels depend on visitor type.
    assert "Hello, Zookeeper!" in out, f"zookeeper not greeted: {out}";
    assert "Hello, School group!" in out, f"school group not greeted: {out}";
    assert "Main Gate" in out, f"kiosk_name missing: {out}";
}

# ---------------------------------------------------------------------------
# Test 3: SchoolGroup walks through the kiosk, watches every animal, and does
# NOT mutate any animal's `fed` flag.
# ---------------------------------------------------------------------------
test "school group only watches, never feeds" {
    lion = Lion(name="Leo");
    parrot = Parrot(name="Polly");
    zebra = Zebra(name="Zara");
    root ++> InfoKiosk(kiosk_name="Gate B") ++> lion ++> parrot ++> zebra;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        group = SchoolGroup(school_name="Riverside");
        res = root spawn group;
    }
    out = buf.getvalue();

    # Each animal must be observed exactly once.
    assert "[WATCH]  the kids observe Leo" in out, f"lion not watched: {out}";
    assert "[WATCH]  the kids observe Polly" in out, f"parrot not watched: {out}";
    assert "[WATCH]  the kids observe Zara" in out, f"zebra not watched: {out}";

    assert res.animals_watched == 3, f"expected 3 watched, got {res.animals_watched}";

    # Critical: school group must not feed anything.
    assert "[MEAT]" not in out, "school group fed meat";
    assert "[SEED]" not in out, "school group fed seed";
    assert "[FEED]" not in out, "school group fed standard feed";
    assert lion.fed is False, "lion got marked fed by school group";
    assert parrot.fed is False, "parrot got marked fed by school group";
    assert zebra.fed is False, "zebra got marked fed by school group";
}

# ---------------------------------------------------------------------------
# Test 4: After a Zookeeper visit, every animal's `fed` flag is True; the
# kiosk's greeting branch is type-dispatched (Zookeeper vs SchoolGroup).
# ---------------------------------------------------------------------------
test "animals are marked fed after zookeeper visit" {
    lion = Lion(name="Simba");
    parrot = Parrot(name="Kiwi");
    zebra = Zebra(name="Stripes");
    kiosk = InfoKiosk(kiosk_name="North Entry");
    root ++> kiosk ++> lion ++> parrot ++> zebra;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        keeper = Zookeeper(badge="ZK-300");
        res = root spawn keeper;
    }
    out = buf.getvalue();

    # All fed flags flipped.
    assert lion.fed is True, "lion not fed";
    assert parrot.fed is True, "parrot not fed";
    assert zebra.fed is True, "zebra not fed";

    # Counter matches number of animals.
    assert res.meals_delivered == 3, f"meals_delivered={res.meals_delivered}";

    # Kiosk greeting branch is Zookeeper-specific (not SchoolGroup).
    assert "Hello, Zookeeper!" in out, f"kiosk greeting missing: {out}";
    assert "Hello, School group!" not in out, f"wrong greeting fired: {out}";
}

