"""Data center clearance: technicians traverse rooms by clearance level."""

node Room {
    has name: str = "";
    has clearance: int = 1;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_visited: int = 0;
    has denied_room: str = "";

    can start with Root entry {
        print(f"Technician {self.name} (clearance {self.clearance}) starting walkthrough");
        visit [-->];
    }

    can approach with Room entry {
        if here.clearance <= self.clearance {
            self.rooms_visited += 1;
            print(f"  {self.name} granted access to {here.name} (needs {here.clearance})");
            visit [-->];
        } else {
            self.denied_room = here.name;
            print(f"  {self.name} DENIED at {here.name} (needs {here.clearance}, has {self.clearance})");
            disengage;
        }
    }
}

walker Corridor {
    can start with Root entry {
        visit [-->];
    }

    can lead with Room entry {
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Lobby", clearance=1)
        ++> Room(name="Server Farm A", clearance=2)
        ++> Room(name="Server Farm B", clearance=2)
        ++> Room(name="Crypto Vault", clearance=5)
        ++> Room(name="Backup Vault", clearance=4);

    junior = Technician(name="Alice", clearance=1);
    mid = Technician(name="Bob", clearance=3);
    senior = Technician(name="Carol", clearance=5);

    root spawn junior;
    print(f"  -> {junior.name} reached {junior.rooms_visited} rooms, denied at: {junior.denied_room or 'nowhere'}\n");

    root spawn mid;
    print(f"  -> {mid.name} reached {mid.rooms_visited} rooms, denied at: {mid.denied_room or 'nowhere'}\n");

    root spawn senior;
    print(f"  -> {senior.name} reached {senior.rooms_visited} rooms, denied at: {senior.denied_room or 'nowhere'}");
}
```

