"""Hiking trail: a chain of plain waypoints from trailhead to summit,
counted by a hiker walker that prints each stop and a completion line."""

node Waypoint {
    has stop_number: int = 0;
}

walker Hiker {
    has stops_made: int = 0;
    has goal: int = 3;

    can start with Root entry {
        print("Hiker sets off from the trailhead.");
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.stops_made += 1;
        here.stop_number = self.stops_made;
        print(f"Stop #{here.stop_number} reached.");
        if self.stops_made >= self.goal {
            print(f"Completed {self.stops_made} stops — trail finished!");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();
    root spawn Hiker(goal=3);
}
```

