"""Weather sweep: walker visits each station, reports temperatures, and prints min/max."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list = [];
    has index: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with Station entry {
        reading = f"{here.name} @ {here.location}: {here.celsius}C";
        print(reading);
        self.readings.append({"name": here.name, "location": here.location, "celsius": here.celsius});
        self.index += 1;
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North Ridge", location="North Hill", celsius=12.5)
        ++> Station(name="Valley Floor", location="Central Valley", celsius=18.2)
        ++> Station(name="South Pier", location="Coastline", celsius=15.0)
        ++> Station(name="East Mesa", location="Highlands", celsius=9.7);

    sweeper = WeatherSweep();
    root spawn sweeper;

    print("\n--- Full reading list ---");
    for r in sweeper.readings {
        print(f"{r['name']} @ {r['location']}: {r['celsius']}C");
    }

    temps = [r['celsius'] for r in sweeper.readings];
    min_t = min(temps);
    max_t = max(temps);
    print(f"\nMin: {min_t}C, Max: {max_t}C");
}
