"""Quiz grader walker: typed integer reports, average computed across quizzes."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has collected: list[int] = [];
    has total: int = 0;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.collected.append(here.score);
        self.total = self.total + here.score;
        self.count = self.count + 1;
        report here.score;
        visit [-->];
    }

    can summarize with Root entry {
        avg = 0;
        if self.count > 0 {
            avg = self.total // self.count;
        }
        print(f"Collected scores: {self.collected}");
        print(f"Class average: {avg}");
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Cara", score=95)
        ++> Quiz(student="Dan", score=61);

    grader = Grader();
    root spawn grader;
    grader spawn root;
}
