"""Gallery security console: log all visitors generically; curators trigger an extra official inspection with a per-curator count."""

node Room {
    has room_name: str = "";
    has log: list[str] = [];
}

walker Tourist {
    has visitor_name: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can wander with Room entry {
        here.log.append(f"visitor: {self.visitor_name}");
        print(f"[log] {self.visitor_name} entered {here.room_name}");
        visit [-->];
    }
}

walker Curator {
    has visitor_name: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can wander with Room entry {
        here.log.append(f"visitor: {self.visitor_name}");
        print(f"[log] {self.visitor_name} entered {here.room_name}");
        here.log.append(f"official inspection by {self.visitor_name}");
        self.inspections += 1;
        print(f"[inspection] {self.visitor_name} officially inspected {here.room_name}");
        visit [-->];
    }
}

with entry {
    room_a = Room(room_name="Gallery A");
    room_b = Room(room_name="Gallery B");
