    print(f"");
    print(f"tourist inspections logged: {tourist.inspections}");
    print(f"curator inspections logged: {curator.inspections}");
    print(f"");
    print(f"room A log: {room_a.log}");
    print(f"room B log: {room_b.log}");
}
