"""Data center clearance walk: rooms post required clearance, technicians
walk the corridor and are granted or denied per room. Denied technicians
disengage immediately and never reach deeper rooms."""

node ServerRoom {
    has room_name: str = "";
    has required_clearance: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can walk_corridor with ServerRoom entry {
        if self.clearance >= here.required_clearance {
            self.rooms_reached += 1;
            print(f"{self.name} GRANTED access to {here.room_name} "
                  f"(needs {here.required_clearance})");
            visit [-->] else { disengage; }
        } else {
            print(f"{self.name} DENIED access to {here.room_name} "
                  f"(needs {here.required_clearance}, has {self.clearance}) — walkthrough ends");
            disengage;
        }
    }
}

with entry {
    root ++> ServerRoom(room_name="Lobby", required_clearance=1)
        ++> ServerRoom(room_name="Operations", required_clearance=2)
        ++> ServerRoom(room_name="Vault", required_clearance=5)
        ++> ServerRoom(room_name="Archive", required_clearance=3);

    junior = Technician(name="Junior", clearance=1);
    senior = Technician(name="Senior", clearance=3);
    director = Technician(name="Director", clearance=5);

    root spawn junior;
    root spawn senior;
    root spawn director;

    print(f"Junior reached {junior.rooms_reached} rooms");
    print(f"Senior reached {senior.rooms_reached} rooms");
    print(f"Director reached {director.rooms_reached} rooms");
}
```

