"""Hiking trail: waypoints between trailhead and summit, walked by a hiker."""

node Waypoint {
    has stop_number: int = 0;
}

walker Hiker {
    has goal: int = 0;
    has passed: int = 0;

    can start with Root entry {
        visit [-->];
