    can hike with Waypoint entry {
        self.passed += 1;
        print(f"stop #{here.stop_number}: {self.passed} waypoint(s) passed");
        if self.passed >= self.goal {
            print(f"Trial complete: passed {self.passed} waypoints (goal was {self.goal})");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    goal = 4;
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4)
        ++> Waypoint(stop_number=5)
        ++> Waypoint(stop_number=6);
    root spawn Hiker(goal=goal);
}
