"""Tests for the Hiking trail / Hiker walker program."""

import io;
import from contextlib { redirect_stdout }

test "hiker reports each stop with running count" {
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4)
        ++> Waypoint(stop_number=5)
        ++> Waypoint(stop_number=6);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=4);
    }
    out = buf.getvalue();

    # Each waypoint should be announced with its stop number and the
    # running count of waypoints passed so far.
    assert "stop #1: 1 waypoint(s) passed" in out, f"missing stop #1 line: {out}";
    assert "stop #2: 2 waypoint(s) passed" in out, f"missing stop #2 line: {out}";
    assert "stop #3: 3 waypoint(s) passed" in out, f"missing stop #3 line: {out}";
    assert "stop #4: 4 waypoint(s) passed" in out, f"missing stop #4 line: {out}";
    # The walker should disengage once the goal is reached, so it must
    # NOT visit stops past the goal.
    assert "stop #5" not in out, f"hiker walked past its goal: {out}";
    assert "stop #6" not in out, f"hiker walked past its goal: {out}";
}

test "hiker prints the trial complete summary exactly at the goal" {
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=4);
    }
    out = buf.getvalue();

    assert "Trial complete: passed 4 waypoints (goal was 4)" in out, (
        f"missing completion line: {out}"
    );
    assert res.passed == 4, f"expected passed=4, got {res.passed}";
}

test "hiker walks a single waypoint chain with one stop" {
    root ++> Waypoint(stop_number=7);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=1);
    }
    out = buf.getvalue();

    assert "stop #7: 1 waypoint(s) passed" in out, f"missing single stop line: {out}";
    assert "Trial complete: passed 1 waypoints (goal was 1)" in out, (
        f"missing completion line: {out}"
    );
    assert res.passed == 1, f"expected passed=1, got {res.passed}";
}

test "hiker disengages early when goal is larger than the trail" {
    # Only two waypoints on the trail, but the goal asks for five.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=5);
    }
    out = buf.getvalue();

    # Both available waypoints must still be reported.
    assert "stop #1: 1 waypoint(s) passed" in out, f"missing stop #1: {out}";
    assert "stop #2: 2 waypoint(s) passed" in out, f"missing stop #2: {out}";
    # Goal is unreachable, so no completion summary should ever print.
    assert "Trial complete" not in out, (
        f"completion line printed even though goal was unreachable: {out}"
    );
    assert res.passed == 2, f"expected passed=2 (end of trail), got {res.passed}";
}

test "hiker visits waypoints in the chain order from the root" {
    root ++> Waypoint(stop_number=10)
        ++> Waypoint(stop_number=20)
        ++> Waypoint(stop_number=30);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=3);
    }
    out = buf.getvalue();

    # Stops must be announced in the order they appear along the trail.
    idx_10 = out.find("stop #10");
    idx_20 = out.find("stop #20");
    idx_30 = out.find("stop #30");
    assert idx_10 != -1, f"stop #10 missing: {out}";
    assert idx_20 != -1, f"stop #20 missing: {out}";
    assert idx_30 != -1, f"stop #30 missing: {out}";
    assert idx_10 < idx_20 < idx_30, (
        f"waypoints not visited in chain order: {out}"
    );
    assert res.passed == 3, f"expected passed=3, got {res.passed}";
}

