"""Order auditor: invalid orders are skipped (walk continues),
fraud-flagged orders halt the walk immediately. Each order prints
which branch fired."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor starting sweep");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[FRAUD HALT] {here.label} amount={here.amount} — disengaging");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] {here.label} amount={here.amount} — invalid, continuing");
            visit [-->];
        }
        print(f"[AUDIT] {here.label} amount={here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="ORD-1", amount=120.50, valid=True, fraud=False)
        ++> Order(label="ORD-2", amount=15.00, valid=False, fraud=False)
        ++> Order(label="ORD-3", amount=430.00, valid=True, fraud=False)
        ++> Order(label="ORD-4", amount=999.99, valid=True, fraud=True)
        ++> Order(label="ORD-5", amount=50.00, valid=True, fraud=False);
    root spawn OrderAuditor();
}
```

