    assert "[SKIP-INVALID] P-4" in out, f"P-4 should be skipped: {out}";
    assert "[AUDIT-OK] P-1" in out, f"P-1 should audit ok: {out}";
    assert "[AUDIT-OK] P-3" in out, f"P-3 should audit ok: {out}";
    assert "[AUDIT-OK] P-5" in out, f"P-5 should audit ok (skip must not halt): {out}";
    assert "HALT-FRAUD" not in out, f"no fraud here, must not halt: {out}";
    assert auditor.audited == 5, f"expected 5 audits (all 5 visited), got {auditor.audited}";
}

test "first-order fraud halts before any audit prints" {
    root ++> Order(label="X-1", amount=100.0, fraud=True)
        ++> Order(label="X-2", amount=200.0);

    auditor = OrderAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
