    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    skip_lines = [l for l in out.split("\n") if "SKIP-INVALID" in l];
    ok_lines = [l for l in out.split("\n") if "AUDIT-OK" in l];
    assert len(skip_lines) == 2, f"expected 2 SKIP lines, got {len(skip_lines)}: {out}";
    assert len(ok_lines) == 2, f"expected 2 OK lines, got {len(ok_lines)}: {out}";
    assert "[SKIP-INVALID] M-1" in out, f"M-1 skip missing: {out}";
    assert "[AUDIT-OK] M-2" in out, f"M-2 ok missing: {out}";
    assert "[SKIP-INVALID] M-3" in out, f"M-3 skip missing: {out}";
    assert "[AUDIT-OK] M-4" in out, f"M-4 ok missing (skip must not abort): {out}";
    assert "HALT-FRAUD" not in out, f"no fraud in this graph: {out}";
    assert auditor.audited == 4, f"expected 4 audits, got {auditor.audited}";
}

test "fraud after a skip still halts and skips do not advance counter prematurely" {
    root ++> Order(label="Z-1", amount=10.0, valid=False)
        ++> Order(label="Z-2", amount=20.0)
        ++> Order(label="Z-3", amount=30.0, fraud=True)
        ++> Order(label="Z-4", amount=40.0);

    auditor = OrderAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[SKIP-INVALID] Z-1" in out, f"Z-1 skip missing: {out}";
    assert "[AUDIT-OK] Z-2" in out, f"Z-2 ok missing: {out}";
    assert "[HALT-FRAUD] Z-3" in out, f"Z-3 fraud halt missing: {out}";
    assert "Z-4" not in out, f"must not reach Z-4 after fraud: {out}";
    # All three visited (skip + ok + fraud) count toward audited because
    # the increment happens before the if-checks in `audit`.
    assert auditor.audited == 3, f"expected 3 audits (skip counts too), got {auditor.audited}";
}

