"""City tourism model: stations connect to hotels and rated attractions.

A walker walks the city graph from the root, but only shortlists
attractions that meet a 4-star minimum. Hotels are silently ignored
because no ability fires for them.
"""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

walker Sightseer {
    has itinerary: list[str] = [];

    can start with Root entry {
        print("Planning city itinerary (4 stars or higher)...");
        visit [-->];
    }

    can hop with Station entry {
        print(f"Arrived at station: {here.name}");
        visit [-->];
    }

    can review with Attraction entry {
        if here.stars >= 4 {
            self.itinerary.append(f"{here.name} ({here.stars} stars)");
        }
        visit [-->];
    }

    can finish with Root entry {
        print("Final itinerary:");
        for stop in self.itinerary {
            print(f"  - {stop}");
        }
    }
}

with entry {
    central = Station(name="Central Station");
    riverside = Station(name="Riverside Station");
    root ++> central ++> riverside;

    central ++> Hotel(name="Budget Inn");
    central ++> Attraction(name="Old Museum", stars=3);
    central ++> Attraction(name="Sky Tower", stars=5);

    riverside ++> Hotel(name="Luxury Suites");
    riverside ++> Attraction(name="Riverfront Park", stars=4);
    riverside ++> Attraction(name="Backstreet Cafe", stars=2);

    root spawn Sightseer();
}
