    central = Station(name="Central Station");
    riverside = Station(name="Riverside Station");
    root ++> central ++> riverside;

    central ++> Hotel(name="Budget Inn");
    central ++> Attraction(name="Old Museum", stars=3);
    central ++> Attraction(name="Sky Tower", stars=5);

    riverside ++> Hotel(name="Luxury Suites");
    riverside ++> Attraction(name="Riverfront Park", stars=4);
    riverside ++> Attraction(name="Backstreet Cafe", stars=2);

    return central;
}

test "only attractions with 4+ stars appear in itinerary" {
    _ = build_city();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Sightseer();
    }
    out = buf.getvalue();
    it = res.itinerary;

    # Sky Tower (5) and Riverfront Park (4) qualify.
    assert "Sky Tower (5 stars)" in it, f"missing Sky Tower in {it}";
    assert "Riverfront Park (4 stars)" in it, f"missing Riverfront Park in {it}";

    # Sub-threshold attraction must be excluded.
    assert not any("Old Museum" in s for s in it), f"Old Museum leaked into {it}";
    assert not any("Backstreet Cafe" in s for s in it), f"Backstreet Cafe leaked into {it}";

    # No hotel should ever show up in the itinerary.
    assert not any("Budget Inn" in s for s in it), f"Budget Inn leaked into {it}";
    assert not any("Luxury Suites" in s for s in it), f"Luxury Suites leaked into {it}";

    # Exactly two qualified stops, no more, no less.
    assert len(it) == 2, f"expected 2 stops, got {len(it)}: {it}";
