with entry {
    t1 = Task(jid="t-001", title="Write spec");
    t2 = Task(jid="t-002", title="Ship delete");
    t3 = Task(jid="t-003", title="Celebrate");
    root ++> t1 ++> t2 ++> t3;

    print(f"Before: t1={t1.jid} t2={t2.jid} t3={t3.jid}");

    deleter = TaskDeleter(target_jid="t-002");
    root spawn deleter;

    print(f"After delete, t1 still here? {t1.jid}");
    print(f"After delete, t3 still here? {t3.jid}");
}
