    assert "N-101 badged into the General ward" in out, f"missing General badge line: {out}";
    assert nurse.shift_visits == 2, f"nurse should have visited 2 wards, got {nurse.shift_visits}";
}

test "doctor badges into ICU and General wards and visit count increments" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");
    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn doctor;
    }
    out = buf.getvalue();

    assert "D-55 badged into the ICU ward" in out, f"missing ICU badge line: {out}";
    assert "D-55 badged into the General ward" in out, f"missing General badge line: {out}";
    assert doctor.shift_visits == 2, f"doctor should have visited 2 wards, got {doctor.shift_visits}";
}

test "family visitor triggers no ward response and no visit count change" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");
    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn guest;
    }
    out = buf.getvalue();

    # FamilyVisitor has no `shift_visits` field declared, so verify silence:
    # no badge prints, no "family visitor" line from the demo (entry block
    # does not run under jac test), and the walker itself emits nothing.
    assert "badged into" not in out, f"family visitor should not trigger any badge print: {out}";
    assert "ICU" not in out, f"family visitor should not mention ICU: {out}";
    assert "General" not in out, f"family visitor should not mention General: {out}";
}

test "union trigger fires for Nurse OR Doctor in the same graph independently" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");
    nurse = Nurse(badge="N-7");
    doctor = Doctor(badge="D-9");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
        root spawn doctor;
    }
    out = buf.getvalue();

    assert "N-7 badged into the ICU ward" in out, f"missing nurse ICU: {out}";
    assert "N-7 badged into the General ward" in out, f"missing nurse General: {out}";
    assert "D-9 badged into the ICU ward" in out, f"missing doctor ICU: {out}";
    assert "D-9 badged into the General ward" in out, f"missing doctor General: {out}";
    assert nurse.shift_visits == 2, f"nurse shift_visits={nurse.shift_visits}";
    assert doctor.shift_visits == 2, f"doctor shift_visits={doctor.shift_visits}";

    # A ward reached by a union-triggered ability must NOT double-fire for a
    # single spawn: each staff member prints exactly one badge line per ward.
    assert out.count("N-7 badged into the ICU ward") == 1, f"nurse ICU printed multiple times: {out}";
    assert out.count("D-9 badged into the General ward") == 1, f"doctor General printed multiple times: {out}";
