"""Weather sweep: stations report temperatures and a walker tallies min/max."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_temp: float = 9999.0;
