        self.readings.append(here.celsius);
        if here.celsius < self.min_temp {
            self.min_temp = here.celsius;
        }
        if here.celsius > self.max_temp {
            self.max_temp = here.celsius;
        }
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North", location="Ridge", celsius=18.5)
        ++> Station(name="East", location="Harbor", celsius=22.1)
        ++> Station(name="South", location="Valley", celsius=15.3)
        ++> Station(name="West", location="Cliffs", celsius=27.8);

    sweep = WeatherSweep() spawn root;

    print(f"\nAll readings: {sweep.readings}");
    print(f"Min: {sweep.min_temp}C   Max: {sweep.max_temp}C");
}
