    assert "Treasure found in 'Vault'! Search ends." in out, f"missing treasure announcement: {out}";

    # Rooms past the vault must NEVER be visited nor printed.
    assert "Secret Chamber" not in out, f"hunter leaked past vault into Secret Chamber: {out}";
    assert "Crypt" not in out, f"hunter leaked past vault into Crypt: {out}";
