```jac
"""Hiking trail: a chain of plain waypoints from trailhead to summit.

A ``Hiker`` walker starts at root, travels every waypoint in the chain,
prints each stop number, and emits a completion line once the trail is
finished. Waypoints hold no data — the relationship itself is the
information.
"""

node Waypoint {
    has stop_index: int = 0;
}

walker Hiker {
    has stops_made: int = 0;

    can start with Root entry {
        print("Hiker sets off from the trailhead");
        visit [-->] else { disengage; }
    }

    can hike with Waypoint entry {
        self.stops_made += 1;
        print(f"  stop #{self.stops_made} reached");
        visit [-->] else {
            print(f"Trail complete: passed {self.stops_made} waypoints");
            disengage;
        }
    }
}

with entry {
    root ++> Waypoint(stop_index=1)
        ++> Waypoint(stop_index=2)
        ++> Waypoint(stop_index=3)
        ++> Waypoint(stop_index=4)
        ++> Waypoint(stop_index=5);
    root spawn Hiker();
}
```

