"""Tests for the Hiking trail program."""

import io;
import from contextlib { redirect_stdout }

test "hiker traverses all five waypoints in order" {
    root ++> Waypoint(stop_index=1)
        ++> Waypoint(stop_index=2)
        ++> Waypoint(stop_index=3)
        ++> Waypoint(stop_index=4)
        ++> Waypoint(stop_index=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Hiker sets off from the trailhead" in out, f"missing trailhead line: {out}";
    assert "stop #1 reached" in out, f"missing stop #1: {out}";
    assert "stop #2 reached" in out, f"missing stop #2: {out}";
    assert "stop #3 reached" in out, f"missing stop #3: {out}";
    assert "stop #4 reached" in out, f"missing stop #4: {out}";
    assert "stop #5 reached" in out, f"missing stop #5: {out}";
    assert "Trail complete: passed 5 waypoints" in out, f"missing completion: {out}";

    # Stops must appear in chain order
    idx1 = out.index("stop #1 reached");
    idx2 = out.index("stop #2 reached");
    idx3 = out.index("stop #3 reached");
    idx4 = out.index("stop #4 reached");
    idx5 = out.index("stop #5 reached");
    assert idx1 < idx2 < idx3 < idx4 < idx5, f"stops out of order in: {out}";

    # Completion must come after the final stop
    assert idx5 < out.index("Trail complete: passed 5 waypoints"), f"completion before last stop: {out}";
}

test "hiker counts waypoints passed via walker field" {
    root ++> Waypoint(stop_index=1)
        ++> Waypoint(stop_index=2)
        ++> Waypoint(stop_index=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stops_made == 3, f"expected 3 stops, got {res.stops_made}";
    assert "passed 3 waypoints" in out, f"missing 3-waypoint completion line: {out}";
}

test "hiker completes trail on a single waypoint" {
    root ++> Waypoint(stop_index=42);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Hiker sets off from the trailhead" in out, f"missing trailhead: {out}";
    assert "stop #1 reached" in out, f"missing stop #1: {out}";
    assert "Trail complete: passed 1 waypoints" in out, f"missing completion: {out}";
    assert res.stops_made == 1, f"expected stops_made=1, got {res.stops_made}";
}

test "hiker disengages when trailhead has no waypoints" {
    # No waypoints linked from root
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # The start ability should still print the trailhead line,
    # but the `visit [-->] else { disengage; }` branch fires, so
    # no waypoint stops and no completion line are emitted.
    assert "Hiker sets off from the trailhead" in out, f"missing trailhead: {out}";
    assert "stop #" not in out, f"unexpected stop line on empty trail: {out}";
    assert "Trail complete" not in out, f"unexpected completion on empty trail: {out}";
    assert res.stops_made == 0, f"expected stops_made=0, got {res.stops_made}";
}

test "trail chain has exactly five connected waypoints" {
    root ++> Waypoint(stop_index=1)
        ++> Waypoint(stop_index=2)
        ++> Waypoint(stop_index=3)
        ++> Waypoint(stop_index=4)
        ++> Waypoint(stop_index=5);

    # root has one outgoing edge to the first waypoint
    assert len([root-->]) == 1, f"expected 1 edge from root, got {len([root-->])}";

    # Walk the chain and verify five Waypoint nodes are reachable in order
    chain = [root-->];
    visited = [];
    while len(chain) > 0 {
        current = chain.pop(0);
        visited.append(current);
        chain.extend([current-->]);
    }
    assert len(visited) == 5, f"expected 5 waypoints in chain, got {len(visited)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    assert res.stops_made == 5, f"hiker should pass 5 waypoints, got {res.stops_made}";
}

