"""Regression tests for main.jac — order auditor with skip + halt-on-fraud."""

import io;
import from contextlib { redirect_stdout }

test "clean orders are audited and walk continues" {
    root ++> Order(amount=10.0, valid=True)
        ++> Order(amount=20.0, valid=True)
        ++> Order(amount=30.0, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT]" in out, f"expected AUDIT lines, got: {out}";
    assert "[SKIP]" not in out, f"unexpected SKIP in clean run: {out}";
    assert "[HALT-FRAUD]" not in out, f"unexpected HALT-FRAUD in clean run: {out}";
    assert res.audited == 3, f"expected 3 audited, got {res.audited}";
    assert res.skipped == 0, f"expected 0 skipped, got {res.skipped}";
    assert res.halted_on_fraud == False, f"should not have halted, got {res.halted_on_fraud}";
}

test "invalid orders are skipped but walk continues to later orders" {
    root ++> Order(amount=10.0, valid=True)
        ++> Order(amount=20.0, valid=False)
        ++> Order(amount=30.0, valid=True)
        ++> Order(amount=40.0, valid=False)
        ++> Order(amount=50.0, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert res.halted_on_fraud == False, f"should not halt on invalid, got {res.halted_on_fraud}";
    assert res.skipped == 2, f"expected 2 skipped, got {res.skipped}";
    assert res.audited == 3, f"expected 3 audited (skip must not stop walk), got {res.audited}";

    # Skip lines must reference the invalid amounts
    assert "amount=20.0" in out, f"missing skip line for 20.0: {out}";
    assert "amount=40.0" in out, f"missing skip line for 40.0: {out}";

    # Audit lines for the valid orders AFTER the first skip must still appear
    assert "[AUDIT]     order amount=30.0" in out, f"walk should continue past skip to 30.0: {out}";
    assert "[AUDIT]     order amount=50.0" in out, f"walk should continue past skip to 50.0: {out}";

    skip_count = out.count("[SKIP]");
    assert skip_count == 2, f"expected 2 SKIP lines, got {skip_count} in: {out}";
}

test "fraud order halts the walk immediately and later orders are untouched" {
    root ++> Order(amount=10.0, valid=True)
        ++> Order(amount=20.0, valid=True)
        ++> Order(amount=99.0, valid=True, fraud=True)
        ++> Order(amount=30.0, valid=True)
        ++> Order(amount=40.0, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert res.halted_on_fraud == True, f"halted_on_fraud should be True, got {res.halted_on_fraud}";

    # The fraud line itself must be printed
    assert "[HALT-FRAUD]" in out, f"missing HALT-FRAUD line: {out}";
    assert "amount=99.0" in out, f"halt line should reference amount=99.0: {out}";

    # Walk must STOP: no audit/skip lines for the 30.0 and 40.0 tail orders
    assert "amount=30.0" not in out, f"walk should have halted before 30.0: {out}";
    assert "amount=40.0" not in out, f"walk should have halted before 40.0: {out}";
    assert "[SKIP]" not in out, f"no skips should fire when fraud halts: {out}";

    # Only the two pre-fraud orders were audited
    assert res.audited == 2, f"expected 2 audited before halt, got {res.audited}";
    assert res.skipped == 0, f"expected 0 skipped, got {res.skipped}";

    # Halt line must come AFTER both audit lines
    halt_idx = out.find("[HALT-FRAUD]");
    audit_30_idx = out.find("amount=10.0");
    audit_20_idx = out.find("amount=20.0");
    assert audit_30_idx != -1 and audit_30_idx < halt_idx, f"amount=10.0 audit must precede halt: {out}";
    assert audit_20_idx != -1 and audit_20_idx < halt_idx, f"amount=20.0 audit must precede halt: {out}";
}

test "fraud before any valid order still halts with audited=0" {
    root ++> Order(amount=50.0, valid=True, fraud=True)
        ++> Order(amount=60.0, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert res.halted_on_fraud == True, f"halted_on_fraud should be True, got {res.halted_on_fraud}";
    assert res.audited == 0, f"expected 0 audited, got {res.audited}";
    assert res.skipped == 0, f"expected 0 skipped, got {res.skipped}";
    assert "[HALT-FRAUD]" in out, f"missing halt line: {out}";
    assert "amount=60.0" not in out, f"later order must not be reached: {out}";
}

test "skip-then-fraud still halts and counts the skip" {
    root ++> Order(amount=15.0, valid=True)
        ++> Order(amount=25.0, valid=False)
        ++> Order(amount=77.0, valid=True, fraud=True)
        ++> Order(amount=88.0, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert res.halted_on_fraud == True, f"halted_on_fraud should be True, got {res.halted_on_fraud}";
    assert res.skipped == 1, f"expected 1 skipped, got {res.skipped}";
    assert res.audited == 1, f"expected 1 audited (15.0), got {res.audited}";

    assert "[SKIP]" in out, f"expected SKIP line: {out}";
    assert "[HALT-FRAUD]" in out, f"expected HALT-FRAUD line: {out}";
    assert "amount=88.0" not in out, f"tail order must be unreachable after fraud halt: {out}";
}

