"""City itinerary: stations connected to hotels and rated attractions; shortlist 4+ star attractions only."""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has rooms: int = 0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

edge Linked {
    has label: str = "";
}

walker ItineraryPlanner {
    has itinerary: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can plan with Station entry {
        print(f"Planning from station: {here.name}");
        visit [-->];
    }

    can inspect with Hotel | Attraction entry {
        if isinstance(here, Attraction) {
            if here.stars >= 4 {
                self.itinerary.append(f"{here.name} ({here.stars}★)");
                print(f"  shortlisted: {here.name} ({here.stars}★)");
            } else {
