"""Weather sweep: stations report their temperature as a walker sweeps them,
then we print every reading plus the min/max across the network."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        visit [-->];
    }

    can read with WeatherStation entry {
        print(f"[{here.location}] {here.celsius} C");
        self.readings.append(here.celsius);
        visit [-->];
    }
}

with entry {
    root ++> WeatherStation(location="North", celsius=12.5)
        ++> WeatherStation(location="East", celsius=18.0)
        ++> WeatherStation(location="South", celsius=9.25)
        ++> WeatherStation(location="West", celsius=22.75);

    sweep = WeatherSweep();
    root spawn sweep;

    print("---");
    print(f"all readings: {sweep.readings}");
    print(f"min: {min(sweep.readings)} C");
    print(f"max: {max(sweep.readings)} C");
}
