"""Restaurant recommender: model restaurants as nodes and walk the chain
with a finder walker whose minimum rating is supplied at spawn time."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 4.5;
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can browse with Restaurant entry {
        if here.rating >= self.min_rating {
            self.matches.append(f"{here.name} ({here.cuisine}, {here.rating})");
        }
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sakura Sushi", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Trattoria Roma", cuisine="Italian", rating=4.3)
        ++> Restaurant(name="Taco Loco", cuisine="Mexican", rating=3.9)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.6)
        ++> Restaurant(name="Salad Garden", cuisine="Healthy", rating=3.2);

    date_night = Finder(min_rating=4.5);
    root spawn date_night;
    print(f"Date night picks (>= 4.5): {date_night.matches}");

    casual_lunch = Finder(min_rating=3.5);
    root spawn casual_lunch;
    print(f"Casual lunch picks (>= 3.5): {casual_lunch.matches}");
}
