"""Quiz grader walker: typed integer reports over Quiz nodes.

Demonstrates a walker that accumulates strictly-typed integer scores
across spawned visits to Quiz nodes and reports a class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        print("Grader dispatched across the quiz set");
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        print(f"[{here.student}] scored {here.score}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Cara", score=91)
        ++> Quiz(student="Dan", score=67)
        ++> Quiz(student="Eve", score=95);

    grader = Grader();
    root spawn grader;

    total = 0;
    for s in grader.scores {
        total = total + s;
    }
    count = len(grader.scores);
    average = total // count if count > 0 else 0;

    print(f"Collected scores: {grader.scores}");
    print(f"Class average: {average}");
}
