"""Restaurant recommender: model restaurants as nodes and find matches with a finder walker."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 4.5;
    has matches: list[str] = [];

    can start with Root entry {
