```jac
"""Gallery security console: log every visitor generically, and additionally
record an official inspection under a curator's name while counting how many
rooms they inspected. A tourist gets the generic log only; a curator gets both
the generic log and an official inspection record.
"""

node Room {
    has name: str = "";
}

walker Visitor {
    has label: str;

    can start with Root entry {
        visit [-->];
    }

    can tour with Room entry {
        print(f"  [LOG] {self.label} entered room '{here.name}'");
        visit [-->];
    }
}

walker Curator {
    has label: str;
    has inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tour with Room entry {
        print(f"  [LOG] {self.label} entered room '{here.name}'");
        print(f"  [OFFICIAL INSPECTION] Curator '{self.label}' inspected '{here.name}'");
        self.inspected += 1;
        visit [-->];
    }
}

with entry {
    room_a = Room(name="Hall of Modern Art");
    room_b = Room(name="Sculpture Garden");
    root ++> room_a ++> room_b;

    print("=== Tourist walkthrough ===");
    tourist = Visitor(label="Alex");
    root spawn tourist;

    print("=== Curator walkthrough ===");
    curator = Curator(label="Dr. Morgan");
    root spawn curator;

    print(
        f"\nSummary: curator '{curator.label}' performed "
        f"{curator.inspected} official inspections; the tourist performed none."
    );
}
```

