"""Tests for the gallery security console: visitor logging and curator inspections."""

import io;
import from contextlib { redirect_stdout }

test "tourist logs generically only, no inspection count" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    tourist = Visitor(label="Alex");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn tourist;
    }
    out = buf.getvalue();

    # Generic LOG line must appear, one per room.
    assert "[LOG] Alex entered room 'Gallery A'" in out, f"missing Gallery A log: {out}";
    assert "[LOG] Alex entered room 'Gallery B'" in out, f"missing Gallery B log: {out}";

    # No OFFICIAL INSPECTION line for a plain visitor.
    assert "[OFFICIAL INSPECTION]" not in out, f"tourist should not trigger inspections: {out}";
}

test "curator logs both generic and official, and counts inspections" {
    room_a = Room(name="Hall of Modern Art");
    room_b = Room(name="Sculpture Garden");
    root ++> room_a ++> room_b;

    curator = Curator(label="Dr. Morgan");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn curator;
    }
    out = buf.getvalue();

    # Generic log per room.
    assert "[LOG] Dr. Morgan entered room 'Hall of Modern Art'" in out, f"missing A log: {out}";
    assert "[LOG] Dr. Morgan entered room 'Sculpture Garden'" in out, f"missing B log: {out}";

    # Official inspection per room, naming the curator and the room.
    assert "[OFFICIAL INSPECTION] Curator 'Dr. Morgan' inspected 'Hall of Modern Art'" in out, f"missing A inspection: {out}";
    assert "[OFFICIAL INSPECTION] Curator 'Dr. Morgan' inspected 'Sculpture Garden'" in out, f"missing B inspection: {out}";

    # Inspection count must equal the number of rooms visited.
    assert curator.inspected == 2, f"curator should have inspected 2 rooms, got {curator.inspected}";
}

