    room_a = Room(name="R1");
    room_b = Room(name="R2");
    room_c = Room(name="R3");
    root ++> room_a ++> room_b ++> room_c;

    curator = Curator(label="Inspector General");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn curator;
    }
    out = buf.getvalue();

    assert curator.inspected == 3, f"expected 3 inspections across 3 rooms, got {curator.inspected}";
    assert "[OFFICIAL INSPECTION] Curator 'Inspector General' inspected 'R1'" in out, f"missing R1: {out}";
    assert "[OFFICIAL INSPECTION] Curator 'Inspector General' inspected 'R2'" in out, f"missing R2: {out}";
    assert "[OFFICIAL INSPECTION] Curator 'Inspector General' inspected 'R3'" in out, f"missing R3: {out}";
