        ++> Pet(name="Rex", species="dog", needs_vaccine=False)
        ++> Pet(name="Bella", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Spike", species="turtle", needs_vaccine=False);

    vet = Vet();
    root spawn vet;

    print("");
    print(f"Vet summary: saw {len(vet.patients)} patient(s) needing shots");
    print(f"Patients vaccinated: {vet.patients}");
    print(f"Total shots given: {vet.shots_given}");
}
