"""Tiny dungeon crawler: chained rooms, one holds the treasure.

A Hunter walker walks the corridor one room at a time, counting what it
has seen, and disengages the moment it reaches the TreasureRoom so that
nothing past the vault is ever visited.
"""

node Room {
    has name: str = "";
}

node TreasureRoom {
    has name: str = "";
}

walker Hunter {
    has seen: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can sweep with Room entry {
        self.seen += 1;
        print(f"  inspected {here.name} (total seen: {self.seen})");
        visit [-->] else { disengage; }
    }

    can claim with TreasureRoom entry {
        self.seen += 1;
        self.found = True;
        print(f"  TREASURE in {here.name}! Search ends after {self.seen} room(s).");
        disengage;
    }
}

with entry {
    root ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> TreasureRoom(name="Sealed Vault")
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Bottomless Pit");

    h = Hunter();
    root spawn h;

    print(f"Hunter report -> seen={h.seen}, found={h.found}");
}
