"""Regression tests for the dungeon crawler Hunter walker."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: count and stop at the vault ----------
test "stops at treasure room and counts correctly" {
    root ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> TreasureRoom(name="Sealed Vault")
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Bottomless Pit");

    buf = io.StringIO();
    h = Hunter();
    with redirect_stdout(buf) {
        res = root spawn h;
    }
    out = buf.getvalue();

    # The hunter should have inspected exactly two non-treasure rooms
    # and then the treasure room itself before disengaging.
    assert res.seen == 3, f"expected seen=3, got {res.seen}";
    assert res.found is True, f"expected found=True, got {res.found}";

    # Past-the-vault rooms must NOT have been inspected.
    assert "Forbidden Crypt" not in out, f"hunter visited past-the-vault room: {out}";
    assert "Bottomless Pit" not in out, f"hunter visited past-the-vault room: {out}";

    # The treasure must have been claimed with the right label.
    assert "TREASURE in Sealed Vault" in out, f"missing treasure announcement: {out}";
    assert "inspected Antechamber" in out, f"missing antechamber inspect: {out}";
    assert "inspected Hall of Echoes" in out, f"missing hall inspect: {out}";
}

# ---------- Test 2: treasure first room ----------
test "finds treasure in the very first room" {
    root ++> TreasureRoom(name="Only Vault")
        ++> Room(name="Should Not Visit");

    buf = io.StringIO();
    h = Hunter();
    with redirect_stdout(buf) {
        res = root spawn h;
    }
    out = buf.getvalue();

    # Found on entry; seen count is incremented exactly once inside the
    # treasure-room ability and no further rooms should be touched.
    assert res.found is True, f"expected found=True, got {res.found}";
    assert res.seen == 1, f"expected seen=1, got {res.seen}";
    assert "Should Not Visit" not in out, f"hunter should not have continued: {out}";
    assert "TREASURE in Only Vault" in out, f"missing treasure announcement: {out}";
