"""Toll plaza G-4: collect per-vehicle tolls and report total revenue."""

node Vehicle {
    has kind: str = "";
    has tons: float = 0.0;
}

node Lane {
    has label: str = "";
}

walker TollCollector {
    has total: float = 0.0;

    can start with Root entry {
        print("Plaza G-4 open");
        visit [-->];
    }

    can enter_lane with Lane entry {
        print(f"  [{here.label}] sweeping");
        visit [-->];
    }

    can charge with Vehicle entry {
        if here.kind == "truck" {
            amount = 2.50 + (0.50 * here.tons);
        } elif here.kind == "car" {
            amount = 2.50;
        } else {
            amount = 1.00;
        }
        self.total = self.total + amount;
        print(f"    {here.kind}: paid ${amount:.2f}");
        visit [-->];
    }
}

with entry {
    gate = Lane(label="G-4");
    root ++> gate;

    car_a = Vehicle(kind="car");
    truck_a = Vehicle(kind="truck", tons=8.0);
    bike_a = Vehicle(kind="motorcycle");
    truck_b = Vehicle(kind="truck", tons=12.5);
    car_b = Vehicle(kind="car");

    gate ++> car_a;
    gate ++> truck_a;
    gate ++> bike_a;
    gate ++> truck_b;
    gate ++> car_b;

    collector = TollCollector();
    root spawn collector;
    print(f"Total revenue at G-4: ${collector.total:.2f}");
}
