"""Warehouse route planner: a robot follows a per-cell movement plan,
choosing floor rolls or stair climbs at each step and logging the path."""

node Cell {
    has label: str = "";
    has move: str = "floor";
}

walker Robot {
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can roll with Cell entry {
        kind = here.move;
        if kind == "floor" {
            self.log.append(f"floor: {here.label}");
        } else {
            self.log.append(f"stairs: {here.label}");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Cell(label="dock-1", move="floor")
        ++> Cell(label="dock-2", move="stairs")
        ++> Cell(label="mezz-1", move="floor")
        ++> Cell(label="mezz-2", move="floor")
        ++> Cell(label="mezz-3", move="stairs");

    robot = Robot();
    root spawn robot;

    print("path taken:");
    for step in robot.log {
        print(f"  {step}");
    }
}
