"""Quiz grader: walker that visits Quiz nodes and reports integer scores."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has total: int = 0;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        report here.score;
        self.total = self.total + here.score;
        self.count = self.count + 1;
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carla", score=95)
        ++> Quiz(student="Dmitri", score=61)
        ++> Quiz(student="Evelyn", score=82);

    grader = root spawn Grader();

    print("Quiz scores:");
    for s in grader.reports {
        print(f"  {s}");
    }

    avg = grader.total / grader.count if grader.count > 0 else 0;
    print(f"Class average: {avg}");
}
