"""Tests for the Quiz Grader walker.

Verifies:
- The walker strictly reports integer scores.
- Reports correspond to the actual quiz nodes in the graph.
- Aggregation fields (total, count) are updated correctly.
- The class average equals total / count.
"""

import io;
import from contextlib { redirect_stdout }


# ---------- helpers ---------------------------------------------------------

def build_quiz_graph {
    return root ++> Quiz(student="Alice",   score=88)
                  ++> Quiz(student="Bob",     score=74)
                  ++> Quiz(student="Carla",   score=95)
                  ++> Quiz(student="Dmitri",  score=61)
                  ++> Quiz(student="Evelyn",  score=82);
}


# ---------- tests -----------------------------------------------------------

test "reports are strictly integers" {
    build_quiz_graph();
    res = root spawn Grader();

    # Every reported value must be an int — the problem forbids string scores.
    for s in res.reports {
        assert isinstance(s, int), f"expected int report, got {type(s).__name__}: {s!r}";
    }

    # The count of reports must match the number of quiz nodes (5).
    assert len(res.reports) == 5, f"expected 5 reports, got {len(res.reports)}";
}

test "reports match quiz scores in graph order" {
    build_quiz_graph();
    res = root spawn Grader();

    expected = [88, 74, 95, 61, 82];
    assert res.reports == expected, f"reports {res.reports} != expected {expected}";
}

test "aggregates total and count" {
    build_quiz_graph();
    res = root spawn Grader();

    # 88 + 74 + 95 + 61 + 82 = 400
    assert res.total == 400, f"expected total=400, got {res.total}";
    assert res.count == 5,   f"expected count=5, got {res.count}";

    # Sanity: total equals sum of reported scores.
    assert res.total == sum(res.reports), "total does not match sum of reports";
}

test "class average equals total over count" {
    build_quiz_graph();
    res = root spawn Grader();

    # 400 / 5 = 80.0  — note: float division in the program, so allow float.
    avg = res.total / res.count;
    assert avg == 80.0, f"expected class average 80.0, got {avg}";
}

test "no quiz nodes -> no reports and zero count" {
    # Empty graph: spawn Grader on a root with no children.
    res = root spawn Grader();

    assert res.reports == [], f"expected no reports, got {res.reports}";
    assert res.count == 0,     f"expected count=0, got {res.count}";
    assert res.total == 0,     f"expected total=0, got {res.total}";

    # Exercise the fail-safe branch the program uses: division guarded by count>0.
    avg = res.total / res.count if res.count > 0 else 0;
    assert avg == 0, f"expected avg=0 when no quizzes, got {avg}";
}

test "demo entry block prints scores and average" {
    # Mirror the program's `with entry` block via stdout capture.
    build_quiz_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = root spawn Grader();
        print("Quiz scores:");
        for s in grader.reports {
            print(f"  {s}");
        }
        avg = grader.total / grader.count if grader.count > 0 else 0;
        print(f"Class average: {avg}");
    }
    out = buf.getvalue();

    assert "Quiz scores:" in out, f"missing 'Quiz scores:' header in: {out!r}";
    assert "Class average: 80.0" in out, f"missing/incorrect average in: {out!r}";

    # Every score must appear in the printed output.
    for s in [88, 74, 95, 61, 82] {
        assert f"  {s}" in out, f"score {s} not printed: {out!r}";
    }
}

