inspectors walk the stations but rack up zero distance."""

import io;
import from contextlib { redirect_stdout }

test "driver accumulates segment distance per station" {
    buf = io.StringIO();
    root ++> Station(name="Central", line="Blue", signage_ok=True, segment_km=1.2)
        ++> Station(name="Market", line="Blue", signage_ok=True, segment_km=0.8)
        ++> Station(name="Harbor", line="Blue", signage_ok=False, segment_km=2.5)
        ++> Station(name="Airport", line="Blue", signage_ok=True, segment_km=3.0);

    d = Driver(line_name="Blue");
    with redirect_stdout(buf) {
        res = root spawn d;
    }
    out = buf.getvalue();
    assert "[Driver/Blue] Now approaching Central on the Blue line" in out, f"missing Central announcement: {out}";
    assert "[Driver/Blue] Now approaching Market on the Blue line" in out, f"missing Market announcement: {out}";
    assert "[Driver/Blue] Now approaching Harbor on the Blue line" in out, f"missing Harbor announcement: {out}";
    assert "[Driver/Blue] Now approaching Airport on the Blue line" in out, f"missing Airport announcement: {out}";
    assert res.distance_km == 1.2 + 0.8 + 2.5 + 3.0, f"driver distance wrong: {res.distance_km}";
    assert res.stops_visited == 4, f"driver stops wrong: {res.stops_visited}";
    assert "[Driver/Blue] departing terminus" in out, f"missing departure print: {out}";
}

test "inspector walks stations but covers zero distance" {
    buf = io.StringIO();
    root ++> Station(name="Central", line="Blue", signage_ok=True, segment_km=1.2)
        ++> Station(name="Market", line="Blue", signage_ok=True, segment_km=0.8)
        ++> Station(name="Harbor", line="Blue", signage_ok=False, segment_km=2.5)
        ++> Station(name="Airport", line="Blue", signage_ok=True, segment_km=3.0);

    insp = Inspector(line_name="Blue");
    with redirect_stdout(buf) {
        res = root spawn insp;
    }
    out = buf.getvalue();
    assert res.distance_km == 0.0, f"inspector must cover 0 km, got {res.distance_km}";
    assert res.stops_visited == 4, f"inspector stops wrong: {res.stops_visited}";
    assert "[Inspector/Blue] Central: signage OK" in out, f"missing Central audit: {out}";
    assert "[Inspector/Blue] Market: signage OK" in out, f"missing Market audit: {out}";
    assert "[Inspector/Blue] Harbor: signage BROKEN" in out, f"missing Harbor BROKEN audit: {out}";
    assert "[Inspector/Blue] Airport: signage OK" in out, f"missing Airport audit: {out}";
}

test "inspector counts only broken signage" {
    root ++> Station(name="A", line="Blue", signage_ok=True, segment_km=1.0)
        ++> Station(name="B", line="Blue", signage_ok=False, segment_km=1.0)
        ++> Station(name="C", line="Blue", signage_ok=False, segment_km=1.0)
        ++> Station(name="D", line="Blue", signage_ok=True, segment_km=1.0);

    insp = Inspector(line_name="Blue");
    res = root spawn insp;
    assert res.stops_visited == 4, f"all stations must be walked: {res.stops_visited}";
    assert res.signage_issues == 2, f"exactly 2 broken: {res.signage_issues}";
    assert res.distance_km == 0.0, f"inspector must never gain distance: {res.distance_km}";
}

test "driver accumulates distance independent of signage" {
    root ++> Station(name="A", line="Red", signage_ok=False, segment_km=2.5)
        ++> Station(name="B", line="Red", signage_ok=False, segment_km=0.5);

    d = Driver(line_name="Red");
    res = root spawn d;
    assert res.distance_km == 3.0, f"driver must sum all segments regardless of signage: {res.distance_km}";
    assert res.stops_visited == 2, f"driver must stop at all stations: {res.stops_visited}";
}

test "single-station line gives driver zero distance? no, still one segment" {
    root ++> Station(name="Sole", line="Green", signage_ok=True, segment_km=4.2);

    d = Driver(line_name="Green");
    res = root spawn d;
    assert res.stops_visited == 1, f"one station visited: {res.stops_visited}";
    assert res.distance_km == 4.2, f"single segment distance: {res.distance_km}";

    insp = Inspector(line_name="Green");
    res2 = root spawn insp;
    assert res2.stops_visited == 1, f"inspector one stop: {res2.stops_visited}";
    assert res2.distance_km == 0.0, f"inspector zero distance: {res2.distance_km}";
    assert res2.signage_issues == 0, f"no signage issues: {res2.signage_issues}";
}

