"""Delivery dispatch check: each route must carry 2-8 tonnes to be dispatchable."""

node Route {
    has label: str = "";
    has weight: float = 0.0;
}

walker Dispatch {
    can start with Root entry {
        print("Scanning depots for dispatchable routes...");
        visit [-->];
    }

    can check with Route entry {
        ok = here.weight >= 2.0 and here.weight <= 8.0;
        verdict = "DISPATCH" if ok else "HOLD";
        print(f"[{verdict}] {here.label}: {here.weight}t");
        visit [-->];
    }
}

with entry {
    root ++> Route(label="R-01 North", weight=3.5)
        ++> Route(label="R-02 East", weight=1.2)
        ++> Route(label="R-03 South", weight=7.8)
        ++> Route(label="R-04 West", weight=9.0)
        ++> Route(label="R-05 Central", weight=5.0);
    root spawn Dispatch();
}
```

