"""Tests for the Delivery dispatch check program."""

import io;
import from contextlib { redirect_stdout }

test "all dispatchable routes within 2-8t range" {
    root ++> Route(label="A", weight=2.0)
        ++> Route(label="B", weight=4.5)
        ++> Route(label="C", weight=8.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatch();
    }
    out = buf.getvalue();

    assert "[DISPATCH] A: 2.0t" in out, f"missing DISPATCH for A: {out}";
    assert "[DISPATCH] B: 4.5t" in out, f"missing DISPATCH for B: {out}";
    assert "[DISPATCH] C: 8.0t" in out, f"missing DISPATCH for C: {out}";
    assert "HOLD" not in out, f"unexpected HOLD in output: {out}";
    assert "Scanning depots for dispatchable routes..." in out, f"missing header: {out}";
}

test "routes below 2t are held" {
    root ++> Route(label="Too-Light-1", weight=0.5)
        ++> Route(label="Too-Light-2", weight=1.99);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatch();
    }
    out = buf.getvalue();

    assert "[HOLD] Too-Light-1: 0.5t" in out, f"missing HOLD for Too-Light-1: {out}";
    assert "[HOLD] Too-Light-2: 1.99t" in out, f"missing HOLD for Too-Light-2: {out}";
    assert "DISPATCH" not in out, f"unexpected DISPATCH in output: {out}";
}

test "routes above 8t are held" {
    root ++> Route(label="Too-Heavy-1", weight=8.01)
        ++> Route(label="Too-Heavy-2", weight=15.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatch();
    }
    out = buf.getvalue();

    assert "[HOLD] Too-Heavy-1: 8.01t" in out, f"missing HOLD for Too-Heavy-1: {out}";
    assert "[HOLD] Too-Heavy-2: 15.0t" in out, f"missing HOLD for Too-Heavy-2: {out}";
    assert "DISPATCH" not in out, f"unexpected DISPATCH in output: {out}";
}

test "boundary values 2.0 and 8.0 are dispatchable" {
