test "mixed routes get correct verdicts in order" {
    root ++> Route(label="R1", weight=1.0)
        ++> Route(label="R2", weight=3.0)
        ++> Route(label="R3", weight=10.0)
        ++> Route(label="R4", weight=6.0)
        ++> Route(label="R5", weight=8.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Dispatch();
    }
    out = buf.getvalue();

    pos_r1 = out.find("R1:");
    pos_r2 = out.find("R2:");
    pos_r3 = out.find("R3:");
    pos_r4 = out.find("R4:");
    pos_r5 = out.find("R5:");

    assert pos_r1 >= 0, f"missing R1 in output: {out}";
    assert pos_r2 > pos_r1, f"R2 must come after R1: {out}";
    assert pos_r3 > pos_r2, f"R3 must come after R2: {out}";
    assert pos_r4 > pos_r3, f"R4 must come after R3: {out}";
    assert pos_r5 > pos_r4, f"R5 must come after R4: {out}";

