import io;
import from contextlib { redirect_stdout }

test "setup seeds one counter per ballot option" {
    options = ["Dune", "Neuromancer", "Circe"];
    root spawn PollSetup(ballot=options);

    counters = [root-->];
    assert len(counters) == 3, "expected one counter per option";

    has_dune = False;
    has_neuromancer = False;
    has_circe = False;
    for c in counters {
        if c.title == "Dune" {
            has_dune = True;
        }
        if c.title == "Neuromancer" {
            has_neuromancer = True;
        }
        if c.title == "Circe" {
            has_circe = True;
        }
    }

    assert has_dune, "missing Dune counter";
    assert has_neuromancer, "missing Neuromancer counter";
    assert has_circe, "missing Circe counter";
}

test "votes increment only the selected counter" {
    options = ["Dune", "Circe"];
    root spawn PollSetup(ballot=options);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Vote(pick="Dune");
        root spawn Vote(pick="Dune");
        root spawn Vote(pick="Unknown");
    }

    dune_votes = -1;
    circe_votes = -1;
    for c in [root-->] {
        if c.title == "Dune" {
            dune_votes = c.votes;
        }
        if c.title == "Circe" {
            circe_votes = c.votes;
        }
    }

    assert dune_votes == 2, f"got Dune votes: {dune_votes}";
    assert circe_votes == 0, f"got Circe votes: {circe_votes}";
}

test "tally report returns the final poll counts" {
    options = ["Dune", "Neuromancer", "Circe", "Piranesi"];
    root spawn PollSetup(ballot=options);

    clicks = ["Dune", "Circe", "Dune", "Piranesi", "Neuromancer", "Dune", "Circe"];
    buf = io.StringIO();
    with redirect_stdout(buf) {
        for pick in clicks {
            root spawn Vote(pick=pick);
        }
        root spawn TallyReport();
    }

    out = buf.getvalue();
    assert "Dune: 3" in out, f"missing Dune tally: {out}";
    assert "Neuromancer: 1" in out, f"missing Neuromancer tally: {out}";
    assert "Circe: 2" in out, f"missing Circe tally: {out}";
    assert "Piranesi: 1" in out, f"missing Piranesi tally: {out}";
}

