```jac
"""Dungeon crawler: chain rooms and let a hunter walker find the treasure.

Rooms are chained nodes; one of them holds the treasure. The hunter visits
them in order, counts what it has seen, and disengages the moment it finds
the vault so rooms beyond it are never explored.
"""

node Room {
    has name: str = "";
    has holds_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->];
    }

    can search with Room entry {
        self.rooms_checked += 1;
        if here.holds_treasure {
            print(f"Treasure found in '{here.name}' after checking {self.rooms_checked} room(s). Hunt over.");
            disengage;
        }
        print(f"Room '{here.name}' checked, no treasure.");
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Mossy Crypt", holds_treasure=True)
        ++> Room(name="Sunken Vault")
        ++> Room(name="Forgotten Catacombs");
    root spawn Hunter();
}
```

