```jac
"""Order auditor: skip-invalid vs halt-on-fraud side by side.

An invalid order is logged and the walk continues to the next sibling;
a fraud-flagged order is logged and the entire audit stops immediately.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"HALT  fraud detected on {here.label} (${here.amount:.2f})");
            disengage;
        }
        if not here.valid {
            print(f"SKIP  invalid order {here.label} (${here.amount:.2f})");
            visit [-->];
        }
        print(f"OK    {here.label} (${here.amount:.2f})");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="A-100", amount=49.99)
        ++> Order(label="A-101", amount=120.00, valid=False)
        ++> Order(label="A-102", amount=310.50)
