"""Tests for OrderAuditor: skip-invalid vs halt-on-fraud."""

import io;
import from contextlib { redirect_stdout }

def run_audit(orders: list) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> orders;
        root spawn OrderAuditor();
    }
    return buf.getvalue();
}

test "valid orders are printed as OK and traversal continues" {
    out = run_audit([
        Order(label="A-100", amount=49.99),
        Order(label="A-101", amount=120.00),
    ]);
    assert "OK    A-100 ($49.99)" in out, f"missing OK for A-100: {out}";
    assert "OK    A-101 ($120.00)" in out, f"missing OK for A-101: {out}";
    assert "SKIP" not in out, f"unexpected SKIP in output: {out}";
    assert "HALT" not in out, f"unexpected HALT in output: {out}";
}

test "invalid order is skipped and audit continues to later siblings" {
    out = run_audit([
        Order(label="A-200", amount=49.99),
        Order(label="A-201", amount=120.00, valid=False),
        Order(label="A-202", amount=310.50),
    ]);
    assert "OK    A-200 ($49.99)" in out, f"missing OK for A-200: {out}";
    assert "SKIP  invalid order A-201 ($120.00)" in out, f"missing SKIP for A-201: {out}";
    assert "OK    A-202 ($310.50)" in out, f"audit should continue past invalid order, got: {out}";
    assert "HALT" not in out, f"unexpected HALT in output: {out}";
}

test "fraud-flagged order halts the entire walk immediately" {
    out = run_audit([
        Order(label="A-300", amount=49.99),
        Order(label="A-301", amount=120.00, valid=False),
        Order(label="A-302", amount=310.50),
        Order(label="A-303", amount=85.25, fraud=True),
        Order(label="A-304", amount=22.00),
    ]);
    assert "OK    A-300 ($49.99)" in out, f"missing OK for A-300: {out}";
    assert "SKIP  invalid order A-301 ($120.00)" in out, f"missing SKIP for A-301: {out}";
    assert "OK    A-302 ($310.50)" in out, f"missing OK for A-302: {out}";
    assert "HALT  fraud detected on A-303 ($85.25)" in out, f"missing HALT for A-303: {out}";
    assert "A-304" not in out, f"walk should halt before A-304, got: {out}";
}

test "fraud on the first order still halts with no prior output" {
    out = run_audit([
        Order(label="A-400", amount=10.00, fraud=True),
        Order(label="A-401", amount=20.00),
    ]);
    assert "HALT  fraud detected on A-400 ($10.00)" in out, f"missing HALT for A-400: {out}";
    assert "A-401" not in out, f"walk should halt, A-401 should not appear: {out}";
    assert "SKIP" not in out, f"unexpected SKIP in output: {out}";
    assert "OK    " not in out, f"unexpected OK in output: {out}";
}

test "fraud takes precedence over invalid on the same order" {
    out = run_audit([
        Order(label="A-500", amount=10.00, valid=False, fraud=True),
    ]);
    assert "HALT  fraud detected on A-500 ($10.00)" in out, f"fraud should beat invalid: {out}";
    assert "SKIP" not in out, f"invalid branch should not fire when fraud is set: {out}";
    assert "OK    " not in out, f"valid branch should not fire when fraud is set: {out}";
}

