    assert "Joe's Pizza" not in out, f"Joe's Pizza (4.2) must be excluded: {out}";
    assert "Taco Truck" not in out, f"Taco Truck (3.9) must be excluded: {out}";
    assert "Diner 51" not in out, f"Diner 51 (3.3) must be excluded: {out}";
}

# ---------------------------------------------------------------
# Test 2: casual lunch (3.5+) — broader net, but still gated.
# ---------------------------------------------------------------
test "casual lunch picks at min_rating 3.5" {
    root ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Joe's Pizza", cuisine="Pizza", rating=4.2)
        ++> Restaurant(name="Tsukiji Sushi", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Taco Truck", cuisine="Mexican", rating=3.9)
        ++> Restaurant(name="Diner 51", cuisine="American", rating=3.3);

    buf = io.StringIO();
