    assert "Le Bernardin" in out, f"Le Bernardin should appear: {out}";
    assert "Joe's Pizza" in out, f"Joe's Pizza (4.2) should appear at 3.5+: {out}";
    assert "Tsukiji Sushi" in out, f"Tsukiji Sushi should appear: {out}";
    assert "Taco Truck" in out, f"Taco Truck (3.9) should appear at 3.5+: {out}";
    assert "Diner 51" not in out, f"Diner 51 (3.3) must stay excluded: {out}";
}

# ---------------------------------------------------------------
# Test 3: threshold cutoff is inclusive — exactly at the bound passes.
# ---------------------------------------------------------------
test "min_rating is inclusive at the boundary" {
    root ++> Restaurant(name="Boundary Cafe", cuisine="Brunch", rating=4.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Finder(min_rating=4.0);
