"""Bug tracker: tickets hang off a project node; file a ticket and capture the
newly connected node in one expression, then print its title and priority.
"""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
    has available: bool = True;
}

walker FileTicket {
    has new_title: str = "Untitled";
    has new_priority: str = "low";

    can start with Root entry {
        # Walk to the project node, then file a ticket off it.
        visit [-->];
    }

    can file with Project entry {
        # Connect AND grab the fresh ticket in a single expression.
        fresh = here ++> Ticket(title=self.new_title, priority=self.new_priority);
        # `fresh` is the Ticket node returned by the connection expression.
        print(f"Filed ticket under {here.name}: "
              f"title={fresh.title}, priority={fresh.priority}");
        visit [-->] else { disengage; }
    }
}

with entry {
    web_project = Project(name="Web");
    root ++> web_project;

    root spawn FileTicket(new_title="Login broken", new_priority="high");
}
