"""Tests for the bug tracker: connect-and-grab ticket behavior."""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
    has available: bool = True;
}

walker FileTicket {
    has new_title: str = "Untitled";
    has new_priority: str = "low";

    can start with Root entry {
        visit [-->];
    }

    can file with Project entry {
        fresh = here ++> Ticket(title=self.new_title, priority=self.new_priority);
        print(
            f"Filed ticket under {here.name}: "
            f"title={fresh.title}, priority={fresh.priority}"
        );
        visit [-->] else { disengage; }
    }
}

test "file ticket connects one Ticket child to the Project" {
    import io;
    import from contextlib { redirect_stdout }

    root ++> Project(name="Web");
    proj = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        proj spawn FileTicket(new_title="Login broken", new_priority="high");
    }

    out = buf.getvalue();
    assert "Filed ticket under Web" in out, f"missing header in: {out}";
    assert "title=Login broken" in out, f"missing title in: {out}";
    assert "priority=high" in out, f"missing priority in: {out}";

    children = [proj -->];
    assert len(children) == 1, f"expected exactly 1 child, got {len(children)}";

    ticket = children[0];
    assert ticket.title == "Login broken", f"got title={ticket.title}";
    assert ticket.priority == "high", f"got priority={ticket.priority}";
    assert ticket.available == True, f"got available={ticket.available}";
}

test "connect-and-grab returns the same Ticket that was linked" {
    import io;
    import from contextlib { redirect_stdout }

    root ++> Project(name="API");
    proj = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        proj spawn FileTicket(new_title="401 on /me", new_priority="low");
    }

    out = buf.getvalue();

    # The expression `here ++> Ticket(...)` must yield the freshly connected node,
    # so the printed title/priority come from the SAME object that's linked.
    # Verify by parsing the printed values and comparing against the linked node.
    assert "title=401 on /me" in out, f"missing printed title: {out}";
    assert "priority=low" in out, f"missing printed priority: {out}";

    linked = [proj -->];
    assert len(linked) == 1, f"expected one child, got {len(linked)}";
    assert linked[0].title == "401 on /me", f"got title={linked[0].title}";
    assert linked[0].priority == "low", f"got priority={linked[0].priority}";

    # The printed values must match the values on the single linked child —
    # proves the walker grabbed the connected node in one expression instead of
    # running a separate lookup.
    printed_marker = "title=401 on /me, priority=low";
    assert printed_marker in out, (
        f"expected exact printed marker '{printed_marker}' in: {out}"
