"""City itinerary planner.

Model a city as a station that connects to hotels and attractions.
A walker starting at the station walks every connection, collects only
the attractions (ignoring hotels), keeps the ones rated 4 stars or
higher, and prints the final shortlist as the itinerary.
"""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has nightly_rate: int = 0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

edge ConnectsTo {}

walker Itinerary {
    has min_stars: int = 4;

    can start with Root entry {
        print("Planning city itinerary...");
        visit [-->];
    }

    can collect with Station entry {
        visit [-->];
    }

    can gather with Hotel entry {
        # Hotels are intentionally ignored.
        visit [-->];
    }

    can filter with Attraction entry {
        if here.stars >= self.min_stars {
            print(f"[{here.stars}*] {here.name}");
        }
        visit [-->];
    }
}

with entry {
    root ++> Station(name="Central Plaza")
        ++> Hotel(name="Grand Inn", nightly_rate=180)
        ++> Hotel(name="Budget Stay", nightly_rate=75)
        ++> Attraction(name="Skyline Tower", stars=5)
        ++> Attraction(name="City Museum", stars=4)
        ++> Attraction(name="Riverside Park", stars=3)
        ++> Attraction(name="Old Cathedral", stars=4);

    root spawn Itinerary();
}
