    assert "Stop #1: passed waypoint 1" in out, f"missing stop 1: {out}";
    assert "Trail complete after 1 waypoints!" in out, f"missing completion: {out}";

    # No further stops should be printed.
    for n in [2, 3, 4, 5] {
        assert f"Stop #{n}" not in out, f"unexpected stop #{n}: {out}";
    }

    assert res.stops_made == 1, f"expected stops_made=1, got {res.stops_made}";
    assert res.target_stops == 1, f"expected target_stops=1, got {res.target_stops}";
