test "trail graph shape: root connects to a linear chain of waypoints" {
    # The trailhead connects to waypoint 1, which connects to waypoint 2,
    # and so on, with no branching. Verify the graph shape directly.
    w1 = Waypoint(marker=1);
    w2 = Waypoint(marker=2);
    w3 = Waypoint(marker=3);
    root ++> w1 ++> w2 ++> w3;

    # Exactly one outgoing edge from root.
    assert len([root-->]) == 1, f"expected 1 outgoing from root, got {len([root-->])}";
    # That edge leads to w1.
    assert w1 in [root-->], "root must link to w1";
    # Chain links are sequential.
    assert w2 in [w1-->], "w1 must link to w2";
    assert w3 in [w2-->], "w2 must link to w3";
    # Terminal waypoint has no outgoing edges.
    assert len([w3-->]) == 0, f"expected 0 outgoing from w3, got {len([w3-->])}";
    # Each waypoint carries its assigned marker.
    assert w1.marker == 1, f"w1.marker={w1.marker}";
    assert w2.marker == 2, f"w2.marker={w2.marker}";
    assert w3.marker == 3, f"w3.marker={w3.marker}";
}

