"""Tests for the Hiking trail program.

We verify the hiker walker behavior:
  - traversal prints stop numbers in order
  - completion line is emitted once target is reached
  - walker disengages when target met (no extra stops printed)
  - with insufficient waypoints the walker stops without completion line
"""

import io;
import from contextlib { redirect_stdout }


test "hiker reaches target and prints completion line" {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target=4);
    }
    out = buf.getvalue();

    # First four waypoints should each announce themselves with a stop number.
    assert "Stop 1" in out, f"missing Stop 1 in: {out!r}";
    assert "Stop 2" in out, f"missing Stop 2 in: {out!r}";
    assert "Stop 3" in out, f"missing Stop 3 in: {out!r}";
    assert "Stop 4" in out, f"missing Stop 4 in: {out!r}";

    # Completion line should fire exactly once, on the 4th stop.
    assert "Summit reached after 4 stops!" in out, f"missing completion line in: {out!r}";
    assert out.count("Summit reached") == 1, f"completion line printed multiple times: {out!r}";

    # After reaching the target the walker must disengage, so the 5th
    # waypoint should NOT be announced.
    assert "Stop 5" not in out, f"hiker did not disengage after target, got: {out!r}";

    # Walker count must reflect the number of waypoints actually visited.
    assert res.count == 4, f"expected count=4, got {res.count}";
}


test "hiker prints stops in ascending order" {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target=5);
    }
    out = buf.getvalue();

    # Stops must appear in increasing sequence.
    idx1 = out.find("Stop 1");
    idx2 = out.find("Stop 2");
    idx3 = out.find("Stop 3");
    assert idx1 >= 0 and idx2 > idx1 and idx3 > idx2, (
        f"stops not in ascending order in output: {out!r}"
    );

    # Target not reachable in 3 waypoints -> no completion line.
    assert "Summit reached" not in out, f"unexpected completion line: {out!r}";
    assert res.count == 3, f"expected count=3, got {res.count}";
}


test "hiker with single waypoint does not complete" {
    root ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target=3);
    }
    out = buf.getvalue();

    assert "Stop 1" in out, f"expected Stop 1, got: {out!r}";
    assert "Summit reached" not in out, f"should not complete with 1 waypoint: {out!r}";
    assert res.count == 1, f"expected count=1, got {res.count}";
}


test "default target requires three waypoints" {
    # Default target is 3; with exactly three waypoints the hiker should
    # complete on the third stop.
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

