test "hiker counts each waypoint stop in order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        rt ++> Waypoint(stop=1)
            ++> Waypoint(stop=2)
            ++> Waypoint(stop=3)
            ++> Waypoint(stop=4)
            ++> Waypoint(stop=5)
            ++> Waypoint(stop=6);
        res = rt spawn Hiker(target_stops=5);
    }
    out = buf.getvalue();
    # Trailhead announcement
    assert "Setting off from the trailhead" in out, f"missing trailhead line: {out!r}";
    # Every stop from #1 through #5 must appear
    for n in [1, 2, 3, 4, 5] {
        assert f"Stop #{n} reached" in out, f"missing Stop #{n} in output: {out!r}";
    }
    # Completion line printed exactly once
    assert out.count("Trail complete!") == 1, f"completion line not exactly once: {out!r}";
    # After 5 stops the walker disengages, so stop #6 must not be printed
    assert "Stop #6 reached" not in out, f"hiker kept walking past target: {out!r}";
    # visited_count reflects the stops actually traversed
    assert res.visited_count == 5, f"expected 5 visited, got {res.visited_count}";
