test "hiker disengages immediately when target is one" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        rt ++> Waypoint(stop=1)
            ++> Waypoint(stop=2)
            ++> Waypoint(stop=3);
        res = rt spawn Hiker(target_stops=1);
