    out = buf.getvalue();
    assert "Stop #1 reached" in out, f"first stop missing: {out!r}";
    assert "Trail complete!" in out, f"completion missing: {out!r}";
    assert "Stop #2 reached" not in out, f"target=1 should disengage after first stop: {out!r}";
    assert "Stop #3 reached" not in out, f"target=1 should disengage after first stop: {out!r}";
    assert res.visited_count == 1, f"expected 1 visited, got {res.visited_count}";
