test "hiker disengages if the chain ends before target is met" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        rt ++> Waypoint(stop=1)
            ++> Waypoint(stop=2);
        res = rt spawn Hiker(target_stops=5);
