    assert "Trail complete!" not in out, f"should not announce complete when chain ends: {out!r}";
    assert "Stop #1 reached" in out, f"stop 1 missing: {out!r}";
    assert "Stop #2 reached" in out, f"stop 2 missing: {out!r}";
