import io;
import from contextlib { redirect_stdout }

# Helper: run the walker on a freshly built trail and return captured stdout.
def run_hiker(min_stops: int = 3) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Waypoint(label="A")
            ++> Waypoint(label="B")
            ++> Waypoint(label="C")
            ++> Summit(label="Cloudpeak Summit");
        root spawn Hiker(min_stops=min_stops);
    }
    return buf.getvalue();
}

test "hiker counts every waypoint along the chain" {
    out = run_hiker(min_stops=3);
    # Exactly one numbered line per waypoint, in order.
    assert "Stop #1: A" in out, f"missing first stop: {out}";
