"""Hiking trail: a chain of bare waypoints from trailhead to summit.

The waypoints are data-free nodes that exist only to mark the path. A
hiker walker walks the chain, counts each stop, prints the stop number
along the way, and finishes with a completion line once the required
number of stops has been passed.
"""

node Waypoint {
    # No data fields: the waypoints exist purely as graph markers
    # between the trailhead and the summit.
}

node Summit {
    has name: str = "Summit";
}

walker Hiker {
    has min_stops: int = 3;
    has stops_passed: int = 0;

    can start with Root entry {
        print("Hiker begins the ascent from the trailhead");
        visit [-->] else { disengage; }
    }

    can walk with Waypoint entry {
        self.stops_passed += 1;
        print(f"Stop #{self.stops_passed}");
        if self.stops_passed >= self.min_stops {
            print(f"Completed trail after {self.stops_passed} waypoints");
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can summit with Summit entry {
        print(f"Reached {here.name} after {self.stops_passed} waypoints");
    }
}

with entry {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Mount Jac");

    hiker = Hiker(min_stops=5);
    root spawn hiker;
}
