    root ++> Waypoint(title="Trailhead")
        ++> Waypoint(title="Stream Crossing")
        ++> Waypoint(title="Wildflower Meadow")
        ++> Waypoint(title="Rocky Ridge")
        ++> Waypoint(title="Eagle Overlook")
        ++> Waypoint(title="Summit");

