    assert "Stop #3: Wildflower Meadow" in out, f"missing stop 3: {out}";
    assert "Stop #4" not in out, f"hiker overran its goal: {out}";
    assert "Summit" not in out, f"hiker reached the summit: {out}";
    assert "Trail complete after 3 stops." in out, f"missing completion: {out}";
    assert res.stops == 3, f"walker reports {res.stops} stops, expected 3";
