        visit [-->];
    }

    can hike with Waypoint entry {
        self.stop_count += 1;
        stop_label = f"stop #{self.stop_count}";
        if here.label != "" {
            stop_label = f"stop #{self.stop_count} ({here.label})";
        }
        print(f"{stop_label} reached at {here.elevation}m");
        if self.stop_count >= self.goal {
            print("Trail complete: summit achieved!");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    trailhead = Waypoint(label="Trailhead", elevation=1200);
    meadow = Waypoint(label="Wildflower Meadow", elevation=1450);
    ridge = Waypoint(label="Ridge Overlook", elevation=1800);
    summit = Waypoint(label="Summit", elevation=2200);

    root ++> trailhead ++> meadow ++> ridge ++> summit;

    root spawn Hiker(goal=4);
}
