"""Tests for the Hiking trail program: chain of Waypoints walked by a Hiker."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts all waypoints and disengages at summit" {
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(min_stops=4);
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing Stop #1: {out!r}";
    assert "Stop #2" in out, f"missing Stop #2: {out!r}";
    assert "Stop #3" in out, f"missing Stop #3: {out!r}";
    assert "Stop #4" in out, f"missing Stop #4: {out!r}";
    assert "Summit reached — trail complete!" in out, f"missing completion line: {out!r}";

    # The completion message must come after the final stop print.
    last_stop_idx = out.rfind("Stop #4");
    completion_idx = out.rfind("Summit reached");
    assert completion_idx > last_stop_idx, (
        f"completion should follow final stop; out={out!r}"
    );

    # Exactly four stops printed, then completion — nothing past the summit.
    stops_printed = out.count("Stop #");
    assert stops_printed == 4, f"expected 4 stops printed, got {stops_printed}: {out!r}";
}

test "hiker disengages early when min_stops is reached before the end" {
    # min_stops=2 means the hiker should stop after printing Stop #2.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3)
        ++> Waypoint(stop_number=4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(min_stops=2);
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing Stop #1: {out!r}";
    assert "Stop #2" in out, f"missing Stop #2: {out!r}";
    assert "Stop #3" not in out, f"should not have reached Stop #3: {out!r}";
    assert "Stop #4" not in out, f"should not have reached Stop #4: {out!r}";
    assert "Summit reached — trail complete!" in out, f"missing completion: {out!r}";

    # Disengagement check: the stop that meets the threshold prints first,
    # then the completion message immediately after (no further waypoints).
    assert out.strip().endswith("Summit reached — trail complete!"), (
        f"trail should end with completion line; out={out!r}"
    );
}

test "hiker never disengages when min_stops exceeds every waypoint" {
    # No waypoint has stop_number >= 5, so the walker should traverse the
    # whole chain and never print the completion line.
    root ++> Waypoint(stop_number=1)
        ++> Waypoint(stop_number=2)
        ++> Waypoint(stop_number=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(min_stops=5);
    }
    out = buf.getvalue();

    assert "Stop #1" in out, f"missing Stop #1: {out!r}";
    assert "Stop #2" in out, f"missing Stop #2: {out!r}";
    assert "Stop #3" in out, f"missing Stop #3: {out!r}";
    assert "Summit reached — trail complete!" not in out, (
        f"completion should not appear when min_stops unreachable; out={out!r}"
    );
}

test "chain shape: trailhead through summit is a single linear path from Root" {
    # The problem requires a chain of plain waypoints between trailhead and
    # summit. Verify the graph shape: Root has exactly one outgoing edge to
    # the first waypoint, and each waypoint links to exactly one successor
    # until the summit (which has none).
    wp1 = Waypoint(stop_number=1);
    wp2 = Waypoint(stop_number=2);
    wp3 = Waypoint(stop_number=3);
    wp4 = Waypoint(stop_number=4);
    root ++> wp1 ++> wp2 ++> wp3 ++> wp4;

    root_children = [root-->];
    assert len(root_children) == 1, (
        f"root should have exactly one child (trailhead), got {len(root_children)}"
    );
    assert root_children[0].stop_number == 1, (
        f"trailhead should be stop #1, got stop #{root_children[0].stop_number}"
    );

    # Chain links: each waypoint (except the summit) has exactly one successor.
    assert len([wp1-->]) == 1, f"wp1 should link forward to wp2";
    assert len([wp2-->]) == 1, f"wp2 should link forward to wp3";
    assert len([wp3-->]) == 1, f"wp3 should link forward to wp4";
    # Summit (wp4) terminates the chain.
    assert len([wp4-->]) == 0, f"summit wp4 should have no successors";

    # Successor identity checks along the chain.
    assert [wp1-->][0].stop_number == 2, "wp1 successor must be wp2";
    assert [wp2-->][0].stop_number == 3, "wp2 successor must be wp3";
    assert [wp3-->][0].stop_number == 4, "wp3 successor must be wp4";
}

