"""Hiking trail: a chain of lightweight waypoints from trailhead to summit.

The hiker walker counts each waypoint it visits, prints the stop number
as it goes, and reports a completion line once it has passed the
required number of waypoints.
"""

node Waypoint {
    has label: str = "";
}

walker Hiker {
    has goal: int = 5;
    has visited: int = 0;
    has done: bool = False;

    can start with Root entry {
        print("Hiker begins the ascent...");
        visit [-->] else { disengage; }
    }

    can trek with Waypoint entry {
        self.visited += 1;
        stop_no = self.visited;
        label = here.label;
        print(f"Stop #{stop_no}: {label}");
        if self.visited >= self.goal {
            print(f"Trek complete! Passed {self.visited} waypoints (goal was {self.goal}).");
            self.done = True;
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Waypoint(label="Trailhead Marker")
        ++> Waypoint(label="Creek Crossing")
        ++> Waypoint(label="Switchback Bend")
        ++> Waypoint(label="Pine Ridge")
        ++> Waypoint(label="Granite Ledge")
        ++> Waypoint(label="False Summit")
        ++> Waypoint(label="Summit Cairn");
    root spawn Hiker(goal=5);
}
