    assert "[IN] Dune (1965)" in out, f"missing Dune IN line: {out}";
    assert "[IN] Neuromancer (1984)" in out, f"missing Neuromancer IN line: {out}";
    assert "[OUT] Circe (2018)" in out, f"missing Circe OUT line: {out}";
}

# Single-book shelf: header prints and the one book is reported.
