        visit [-->];
    }

    can depart with Trailhead entry {
        print(f"Departing {here.name}");
        visit [-->];
    }

    can mark with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can finish with Summit entry {
        print(f"Summit reached — passed {self.stop_count} waypoints.");
        disengage;
    }
}

with entry {
    root ++> Trailhead(name="Pine Ridge Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Eagle Peak");
    root spawn Hiker();
}
