"""Tests for the hiking trail walker."""

import io;
import from contextlib { redirect_stdout }

test "hiker visits every waypoint in order and prints each stop" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Trailhead(name="Pine Ridge")
            ++> Waypoint()
            ++> Waypoint()
            ++> Waypoint()
            ++> Summit(name="Eagle");
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    # Stop numbering is 1, 2, 3 — one per Waypoint, in walk order.
    assert "Stop 1" in out, f"expected 'Stop 1' in: {out!r}";
    assert "Stop 2" in out, f"expected 'Stop 2' in: {out!r}";
    assert "Stop 3" in out, f"expected 'Stop 3' in: {out!r}";
    # Stop 1 must precede Stop 2, which must precede Stop 3.
    s1 = out.index("Stop 1");
    s2 = out.index("Stop 2");
    s3 = out.index("Stop 3");
    assert s1 < s2 < s3, f"stops out of order: {s1}, {s2}, {s3}";
    # No phantom fourth stop.
    assert out.count("Stop ") == 3, f"unexpected stop count in: {out!r}";
    # Final completion line reflects the actual number of waypoints passed.
    assert "Summit reached — passed 3 waypoints." in out, f"missing completion line: {out!r}";
}

test "hiker reports zero waypoints on a bare trail" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Trailhead(name="Empty Trail")
            ++> Summit(name="Bare Summit");
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    assert "Stop " not in out, f"no stops expected on waypoint-less trail: {out!r}";
    assert "Summit reached — passed 0 waypoints." in out, f"missing zero-count completion: {out!r}";
}

test "hiker departs the trailhead before counting waypoints" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Trailhead(name="Pine Ridge")
            ++> Waypoint()
            ++> Summit(name="Eagle");
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    # Departure message comes from the Trailhead ability.
    assert "Departing Pine Ridge" in out, f"missing departure line: {out!r}";
    # Departure precedes the first waypoint stop.
    dep = out.index("Departing Pine Ridge");
    stop = out.index("Stop 1");
    assert dep < stop, f"departure must come before first stop: {dep} vs {stop}";
}

test "hiker disengages at the summit and does not overshoot" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        # If disengage failed, the walker would try to visit Summit's outgoing
        # edges and blow up, or print the completion line more than once.
        root ++> Trailhead(name="Pine Ridge")
            ++> Waypoint()
            ++> Summit(name="Eagle")
            ++> Waypoint()
            ++> Waypoint();
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    # Completion line appears exactly once.
    assert out.count("Summit reached") == 1, f"completion should fire exactly once: {out!r}";
    # Passed count is 1 — only the waypoint before the summit, not those after.
    assert "passed 1 waypoints" in out, f"expected passed count of 1: {out!r}";
    # Stops past the summit must not appear.
    assert "Stop 2" not in out, f"walker leaked past summit: {out!r}";
    assert "Stop 3" not in out, f"walker leaked past summit: {out!r}";
}

