"""Vet-clinic round: walk a chain of pets, vaccinate the ones that need it today, and report shots given."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet beginning clinic round");
        visit [-->];
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"  Vaccinated {here.name} the {here.species}");
        } else {
            print(f"  Checked {here.name} the {here.species} - up to date");
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=False)
        ++> Pet(name="Bubbles", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Ziggy", species="parrot", needs_vaccine=False);

    vet = Vet();
    root spawn vet;

    print(f"\nRound summary");
    print(f"  Patients seen: {len(vet.patients)} ({vet.patients})");
    print(f"  Shots given:   {vet.shots_given}");
}
