"""Tests for the Vet-clinic round: walker state, side effects, and traversal."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: defaults on Pet ----------
test "pet defaults match spec" {
    p = Pet();
    assert p.name == "", f"name default wrong: {p.name}";
    assert p.species == "", f"species default wrong: {p.species}";
    assert p.needs_vaccine is True, f"needs_vaccine default wrong: {p.needs_vaccine}";
}

# ---------- Test 2: round with all pets needing a shot ----------
test "vet counts shots and records every patient" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True);
    root ++> Pet(name="Rex", species="dog", needs_vaccine=True);
    root ++> Pet(name="Hopper", species="rabbit", needs_vaccine=True);
    root ++> Pet(name="Nimbus", species="parrot", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    vet = res;

    assert len(vet.patients) == 4, f"expected 4 patients, got {len(vet.patients)}";
    assert vet.shots_given == 4, f"expected 4 shots, got {vet.shots_given}";
    assert set(vet.patients) == {"Mochi", "Rex", "Hopper", "Nimbus"}, f"patients wrong: {vet.patients}";

    # every pet should now be flagged up-to-date
    for p in [root-->] {
        assert p.needs_vaccine is False, f"{p.name} still needs vaccine after round";
    }

    out = buf.getvalue();
    assert "Vet starting the clinic round" in out, f"missing start line: {out}";
    assert "Examining Mochi the cat" in out, f"missing Mochi exam: {out}";
    assert "Examining Rex the dog" in out, f"missing Rex exam: {out}";
    assert "Examining Hopper the rabbit" in out, f"missing Hopper exam: {out}";
    assert "Examining Nimbus the parrot" in out, f"missing Nimbus exam: {out}";
    assert "gave Mochi a vaccine" in out, f"missing Mochi shot: {out}";
    assert "gave Rex a vaccine" in out, f"missing Rex shot: {out}";
}

# ---------- Test 3: mixed needs_vaccine flags ----------
test "vet skips pets that are already up to date" {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True);
    root ++> Pet(name="Rex", species="dog", needs_vaccine=False);
    root ++> Pet(name="Hopper", species="rabbit", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    vet = res;

    assert len(vet.patients) == 3, f"should visit all 3, got {len(vet.patients)}";
    assert vet.shots_given == 2, f"only Mochi and Hopper need shots, got {vet.shots_given}";

    out = buf.getvalue();
    assert "Rex is up to date" in out, f"missing up-to-date note for Rex: {out}";
    assert "gave Mochi a vaccine" in out, f"missing Mochi shot: {out}";
    assert "gave Hopper a vaccine" in out, f"missing Hopper shot: {out}";

    # Rex's flag must remain False; the two needy ones flipped to False
    pets = [root-->];
    rex = [p for p in pets if p.name == "Rex"][0];
    assert rex.needs_vaccine is False, "Rex flag should be untouched";
}

# ---------- Test 4: empty clinic ----------
test "vet on empty clinic records nothing" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Vet();
    }
    vet = res;

    assert len(vet.patients) == 0, f"no patients expected, got {len(vet.patients)}";
    assert vet.shots_given == 0, f"no shots expected, got {vet.shots_given}";

    out = buf.getvalue();
    assert "Vet starting the clinic round" in out, f"start line missing: {out}";
    assert "Examining" not in out, f"should not examine anyone: {out}";
}

# ---------- Test 5: spawned walker instance carries its own state ----------
test "two spawns do not share state" {
    root ++> Pet(name="A", species="cat", needs_vaccine=True);
    root ++> Pet(name="B", species="dog", needs_vaccine=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        v1 = root spawn Vet();
    }
    assert v1.shots_given == 2, f"first round shots: {v1.shots_given}";
    assert "A" in v1.patients and "B" in v1.patients, f"first round patients: {v1.patients}";

    # second spawn on the same root -- pets are now flagged False by first round
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        v2 = root spawn Vet();
    }
    assert len(v2.patients) == 2, f"second round still visits all: {len(v2.patients)}";
    assert v2.shots_given == 0, f"second round should give 0 shots, got {v2.shots_given}";

    out2 = buf2.getvalue();
    assert "A is up to date" in out2, f"missing A up-to-date: {out2}";
    assert "B is up to date" in out2, f"missing B up-to-date: {out2}";

    # v1 state untouched by second walk
    assert v1.shots_given == 2, f"v1 state was mutated: {v1.shots_given}";
}

