"""Hiking trail: chain waypoints from trailhead to summit; a hiker counts each stop."""

node Trailhead {
    has label: str = "Trailhead";
}

node Waypoint {
    has active: bool = True;
}

node Summit {
    has label: str = "Summit";
}

walker Hiker {
    has stops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can depart with Trailhead entry {
        print(f"Departing {here.label}");
        visit [-->];
    }

    can mark_stop with Waypoint entry {
        self.stops += 1;
        print(f"Stop {self.stops}");
        visit [-->];
    }

    can finish with Summit entry {
        print(f"Reached {here.label} — passed {self.stops} waypoint(s)");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Trailhead(label="North Ridge Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(label="Eagle Peak");
    root spawn Hiker();
}
