"""Tests for the hiking trail program: chain waypoints between Trailhead and Summit, Hiker walker counts stops."""

import io;
import from contextlib { redirect_stdout }

# Helper to build a trail: root -> Trailhead -> n Waypoints -> Summit
def build_trail(n: int) {
    th = Trailhead(label="Trailhead");
    summit = Summit(label="Summit");
    root ++> th;
    cur = th;
    for i in range(n) {
        wp = Waypoint();
        cur ++> wp;
        cur = wp;
    }
    cur ++> summit;
    return (th, summit);
}

test "hiker counts all waypoints in order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        (th, sm) = build_trail(3);
        res = th spawn Hiker();
    }
    out = buf.getvalue();
    # All three waypoints should be reported as Stop 1, 2, 3 in order
    assert "Stop 1" in out, f"missing Stop 1: {out}";
    assert "Stop 2" in out, f"missing Stop 2: {out}";
    assert "Stop 3" in out, f"missing Stop 3: {out}";
    # Order: Stop 1 must appear before Stop 2, which appears before Stop 3
    assert out.index("Stop 1") < out.index("Stop 2"), f"out-of-order stops: {out}";
    assert out.index("Stop 2") < out.index("Stop 3"), f"out-of-order stops: {out}";
    # Hiker should record 3 stops
    assert res.stops == 3, f"expected stops=3, got {res.stops}";
}

test "hiker departure line uses trailhead label" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        (th, sm) = build_trail(2);
        res = th spawn Hiker();
    }
    out = buf.getvalue();
    assert "Departing Trailhead" in out, f"missing departure line: {out}";
    # Departing must be printed before the first Stop
    assert out.index("Departing") < out.index("Stop 1"), f"departure should precede stops: {out}";
}

test "hiker completion line reports total waypoints passed" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        (th, sm) = build_trail(4);
        res = th spawn Hiker();
    }
    out = buf.getvalue();
    # Completion line at the Summit
    assert "Reached Summit" in out, f"missing summit line: {out}";
    assert "passed 4 waypoint" in out, f"missing waypoint count: {out}";
    # Completion line must come after the last stop
    assert out.index("Stop 4") < out.index("Reached"), f"completion should be after last stop: {out}";
    assert res.stops == 4, f"expected stops=4, got {res.stops}";
}

test "hiker with zero waypoints still reaches summit with zero count" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        th = Trailhead(label="Trailhead");
        sm = Summit(label="Summit");
        root ++> th ++> sm;
        res = th spawn Hiker();
    }
    out = buf.getvalue();
    # No waypoints => no Stop lines
    assert "Stop " not in out, f"unexpected Stop line for zero-waypoint trail: {out}";
    # But the completion line still fires
    assert "Reached Summit" in out, f"missing summit line: {out}";
    assert "passed 0 waypoint" in out, f"expected zero count: {out}";
    assert res.stops == 0, f"expected stops=0, got {res.stops}";
}

