"""Vet-clinic round: pets are nodes, a vet walker visits them and tallies shots.

Each pet carries a name, species, and a flag for whether it needs a vaccine
today. The vet walker maintains its own running list of patient names and
count of shots given. After the walk, those totals are read straight off the
spawned walker instance and printed as a summary.
"""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet starting the round");
        visit [-->];
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"  vaccinated {here.name} the {here.species}");
        } else {
            print(f"  checked {here.name} the {here.species}, no shot needed");
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="dog", needs_vaccine=False)
        ++> Pet(name="Hopper", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Nimbus", species="parrot", needs_vaccine=False);

    vet = Vet();
    root spawn vet;

    print(f"\nRound complete.");
    print(f"Patients seen : {vet.patients}");
    print(f"Shots given   : {vet.shots_given}");
}
