"""Vet-clinic round: a walker visits pets in order and tallies vaccines given.

Pets are nodes with a name, species, and a flag for whether they need a
vaccine today. The Vet walker keeps a running list of patient names and
a shot count as it moves pet-to-pet along the chain. After the walk,
the caller reads those numbers straight off the spawned walker instance
and prints a summary.
"""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = True;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can examine with Pet entry {
        if here.needs_vaccine {
            self.shots_given += 1;
            action = "vaccinated";
        } else {
            action = "checked (no shot needed)";
        }
        print(f"{here.name} the {here.species}: {action}");
        self.patients.append(here.name);
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="dog", needs_vaccine=True)
        ++> Pet(name="Ziggy", species="parrot", needs_vaccine=False)
        ++> Pet(name="Noodle", species="rabbit", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\nRound complete: visited {len(vet.patients)} patients, "
          f"gave {vet.shots_given} shots.");
    print(f"Patient list: {vet.patients}");
}
