"""Hiking trail: chain waypoints from trailhead to summit and count each stop."""

node Trailhead {
    has title: str = "Trailhead";
    has year: int = 0;
    has available: bool = True;
}

node Waypoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Summit {
    has title: str = "Summit";
    has year: int = 0;
    has available: bool = True;
}

walker Hiker {
    has stop_num: int = 0;
    has total_waypoints: int = 0;

    can start with Root entry {
        print("Setting out on the trail...");
        visit [-->];
    }

    can begin with Trailhead entry {
        print(f"At {here.title} — hike begins.");
        visit [-->];
    }

    can tread with Waypoint entry {
        self.stop_num += 1;
        print(f"Stop {self.stop_num}");
        visit [-->];
    }

    can arrive with Summit entry {
        if self.stop_num >= self.total_waypoints {
            print(f"Hike complete — passed {self.stop_num} waypoint(s) to reach {here.title}.");
        } else {
            print(f"Reached {here.title} but only passed {self.stop_num} of {self.total_waypoints} waypoint(s).");
        }
        disengage;
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker(total_waypoints=3);
}
