    assert "Welcome to the Skyline Tour!" in out, f"missing default tour banner: {out}";
    assert "Stop 1: welcome to the Lobby department" in out, f"missing lobby stop: {out}";
    assert "Stop 2: welcome to the Engineering department" in out, f"missing engineering stop: {out}";
    assert "Stop 3: welcome to the Marketing department" in out, f"missing marketing stop: {out}";
    assert "Stop 4: welcome to the Executive Suite department" in out, f"missing executive stop: {out}";

    # Stops must follow the banner in walk order.
    banner_idx = out.index("Welcome to the Skyline Tour!");
    lobby_idx = out.index("Stop 1");
    exec_idx = out.index("Stop 4");
    assert banner_idx < lobby_idx < exec_idx, f"stops not ordered after banner: {out}";
}

test "custom tour_name overrides the default banner" {
    root ++> Floor(number=1, department="Lobby")
        ++> Floor(number=2, department="Engineering");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="VIP Investor Tour");
    }
    out = buf.getvalue();

    assert "Welcome to the VIP Investor Tour!" in out, f"custom banner missing: {out}";
    assert "Skyline Tour" not in out, f"default tour name leaked into output: {out}";
    assert "Stop 1: welcome to the Lobby department" in out, f"lobby stop missing: {out}";
    assert "Stop 2: welcome to the Engineering department" in out, f"engineering stop missing: {out}";
}

test "floor announce_stop helper formats the stop line" {
    f = Floor(number=7, department="Legal");
    assert f.announce_stop() == "  Stop 7: welcome to the Legal department", f"got: {f.announce_stop()}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        print(f.announce_stop());
    }
    assert "Stop 7" in buf.getvalue(), "announce_stop output not captured";
}

test "tour walks root then each connected floor exactly once" {
    f1 = Floor(number=1, department="Lobby");
    f2 = Floor(number=2, department="Engineering");
    f3 = Floor(number=3, department="Marketing");
    root ++> f1;
    f1 ++> f2;
    f2 ++> f3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Countdown Tour");
    }
    out = buf.getvalue();

    # Banner appears once.
    assert out.count("Welcome to the Countdown Tour!") == 1, f"banner printed wrong times: {out!r}";
    # Each floor's stop appears once, in spawn traversal order.
    assert out.count("Stop 1") == 1, f"floor 1 stop count: {out!r}";
    assert out.count("Stop 2") == 1, f"floor 2 stop count: {out!r}";
    assert out.count("Stop 3") == 1, f"floor 3 stop count: {out!r}";
    assert out.index("Stop 1") < out.index("Stop 2") < out.index("Stop 3"), f"stops not in order: {out!r}";

    # Graph shape: root has one direct child; total reachable nodes is 4.
    assert len([root-->]) == 1, f"root should have exactly one direct child, got {len([root-->])}";
    reachable = [root --> --> -->];
    assert f1 in [root-->], "f1 not directly linked from root";
    assert f2 in [f1-->], "f2 not linked from f1";
    assert f3 in [f2-->], "f3 not linked from f2";
}

