"""Hiking trail: waypoints chained from trailhead to summit, counted by a hiker walker."""

node Trailhead {
    has label: str = "Trailhead";
}

node Waypoint {}

node Summit {
    has label: str = "Summit";
}

walker Hiker {
    has waypoint_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can depart with Trailhead entry {
        print(f"Departing {here.label}");
        visit [-->];
    }

    can mark with Waypoint entry {
        self.waypoint_count += 1;
        print(f"Stop {self.waypoint_count}");
        visit [-->];
    }

    can arrive with Summit entry {
        print(f"Reached {here.label}");
        print(f"Completed: passed {self.waypoint_count} waypoints");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}
