"""Tests for the hiking trail walker program."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts waypoints and prints each stop" {
    root ++> TrailHead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Hiker();
    }
    out = buf.getvalue();
    lines_list = out.splitlines();

    # The walker prints one Stop line per node visited after the trailhead.
    # Chain has TrailHead + 3 Waypoints + Summit = 5 nodes that print a Stop.
    stop_lines = [l for l in lines_list if l.startswith("Stop ")];
    assert len(stop_lines) == 5, f"expected 5 Stop lines, got {len(stop_lines)}: {stop_lines}";

    # Stop numbers must be strictly sequential 1..5.
    assert stop_lines[0] == "Stop 1", f"first stop wrong: {stop_lines[0]}";
    assert stop_lines[1] == "Stop 2", f"second stop wrong: {stop_lines[1]}";
    assert stop_lines[2] == "Stop 3", f"third stop wrong: {stop_lines[2]}";
    assert stop_lines[3] == "Stop 4", f"fourth stop wrong: {stop_lines[3]}";
    assert stop_lines[4] == "Stop 5", f"fifth stop wrong: {stop_lines[4]}";

    # The completion line must come after the last Stop line.
    last_stop_idx = -1;
    for (i, line) in enumerate(lines_list) {
        if line.startswith("Stop ") {
            last_stop_idx = i;
        }
    }
    completion_idx = -1;
    for (i, line) in enumerate(lines_list) {
        if line.startswith("Trail complete:") {
            completion_idx = i;
        }
    }
    assert completion_idx > last_stop_idx, "completion line must print after the last Stop";
}

test "completion line reports the total number of stops" {
    root ++> TrailHead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Hiker();
    }
    out = buf.getvalue();

    # 5 nodes visited -> "passed 5 stops".
    assert "Trail complete: passed 5 stops." in out, f"missing or wrong completion line: {out!r}";

    # The hiker must announce starting from the trailhead.
    assert "Starting hike from trailhead" in out, f"missing start line: {out!r}";
}

test "hiker adapts to a longer chain" {
    root ++> TrailHead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Hiker();
    }
    out = buf.getvalue();
    lines_list = out.splitlines();

    stop_lines = [l for l in lines_list if l.startswith("Stop ")];
    # 1 TrailHead + 5 Waypoints + 1 Summit = 7 stops.
    assert len(stop_lines) == 7, f"expected 7 stops, got {len(stop_lines)}: {stop_lines}";
    assert stop_lines[0] == "Stop 1";
    assert stop_lines[6] == "Stop 7";
    assert "Trail complete: passed 7 stops." in out, f"wrong completion: {out!r}";
