test "trailhead has exactly one direct child" {
    # Chain via repeated ++> links means the trailhead has exactly one outgoing edge,
    # but 5 nodes are reachable from it.
    th = TrailHead();
    root ++> th
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    assert len([th -->]) == 1, "trailhead should have exactly one direct child in a chain";
