"""Vet-clinic round: walk the pet roster with a Vet walker.

Each pet is a node carrying its name, species, and whether it needs a
vaccine today. The Vet walker keeps a per-spawn list of patient names
and a running shot count as it visits pets. After the walk, the
summary is read directly off the spawned walker instance.
"""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet starting the clinic round");
        visit [-->];
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        action = "vaccinated" if here.needs_vaccine else "checked";
        print(f"  - {here.name} the {here.species}: {action}");
        if here.needs_vaccine {
            self.shots_given += 1;
            here.needs_vaccine = False;
        }
        visit [-->];
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Biscuit", species="dog")
        ++> Pet(name="Pepper", species="parrot", needs_vaccine=True)
        ++> Pet(name="Luna", species="rabbit", needs_vaccine=True);

    vet = Vet();
    root spawn vet;

    print(f"\n--- Round summary ---");
    print(f"Patients seen: {vet.patients}");
    print(f"Shots given:   {vet.shots_given}");
}
