"""Weather sweep: stations hold temperature readings; a walker visits each one and collects min/max across the whole network."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker Sweep {
    has readings: list[float] = [];
    has current_min: float = 9999.0;
    has current_max: float = -9999.0;

    can start with Root entry {
        print(f"Sweeping weather stations...");
        visit [-->];
    }

    can read with Station entry {
        self.readings.append(here.celsius);
        next_min = here.celsius if here.celsius < self.current_min else self.current_min;
        next_max = here.celsius if here.celsius > self.current_max else self.current_max;
        self.current_min = next_min;
        self.current_max = next_max;
        print(f"  reading at {here.name} ({here.location}): {here.celsius} C");
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North", location="Ridge", celsius=12.5)
        ++> Station(name="East", location="Coast", celsius=18.0)
        ++> Station(name="South", location="Valley", celsius=22.3)
        ++> Station(name="West", location="Highlands", celsius=9.7);

    sweeper = Sweep();
    root spawn sweeper;

    print("");
    print(f"All readings: {sweeper.readings}");
    print(f"min = {sweeper.current_min} C, max = {sweeper.current_max} C");
}
