        visit [-->];
    }

    can finish with Summit entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        print(f"Completed trail after {self.stop_count} stops");
    }
}

with entry {
    root ++> Trailhead(name="Oak Ridge Trail")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Eagle Peak");
    root spawn Hiker();
}
