"""Quiz grader: a walker whose reports are strictly typed to integers.

Demonstrates typed report accumulation (scores: list[int] = []) and a class
average computed after the walk completes, printed from the spawn site.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        print(f"{here.student}: {here.score}");
        self.scores.append(here.score);
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student="Ava", score=88)
        ++> Quiz(student="Ben", score=74)
        ++> Quiz(student="Cleo", score=95)
        ++> Quiz(student="Dee", score=61)
        ++> Quiz(student="Eli", score=82);

    grader = Grader();
    root spawn grader;

    total: int = 0;
    for s in grader.scores {
        total = total + s;
    }
    average: float = 0.0;
    if len(grader.scores) > 0 {
        average = total / len(grader.scores);
    }
    print(f"Collected scores: {grader.scores}");
    print(f"Class average: {average}");
}
