"""Hiking trail: chain waypoints from trailhead to summit; a hiker walker counts each stop."""

node Trailhead {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Waypoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Summit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Hiker {
    has stop_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can depart with Trailhead entry {
        print("Departing trailhead");
        visit [-->];
    }

    can reach with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can finish with Summit entry {
        print(f"Trail complete — passed {self.stop_count} waypoints to the summit.");
        disengage;
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}
```

