"""Quiz grader walker: strictly typed int reports over quiz nodes."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];
    has report: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        visit [-->];
    }

    can summarize with Root exit {
        if len(self.scores) > 0 {
            total = 0;
            for s in self.scores {
                total = total + s;
            }
            average = total / len(self.scores);
            print(f"Scores collected: {self.scores}");
            print(f"Class average: {average}");
            self.report = int(average);
        } else {
            print("No quizzes graded.");
            self.report = 0;
        }
    }
}

with entry {
    root ++> Quiz(student="Alice", score=88)
        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Carmen", score=95)
        ++> Quiz(student="Dmitri", score=61)
        ++> Quiz(student="Elena", score=82);

    grader = Grader();
    root spawn grader;
    print(f"Grader report (int): {grader.report}");
}
