"""Hiking trail: chain waypoints from trailhead to summit; a hiker counts each stop."""

node TrailHead {
    has title: str = "Trailhead";
    has mile: int = 0;
    has marked: bool = True;
}

node Waypoint {
    has title: str = "";
    has mile: int = 0;
    has marked: bool = True;
}

node Summit {
    has title: str = "Summit";
    has mile: int = 0;
    has marked: bool = True;
