    can mark_stop with TrailHead | Waypoint | Summit entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->] else {
            print(f"Trail complete — passed {self.stop_count} stops.");
            disengage;
        }
    }
}

with entry {
    root ++> TrailHead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}
