        visit [-->];
    }

    can search with Room entry {
        self.rooms_seen += 1;
        if here.has_treasure {
            print(f"Found treasure in {here.name} after {self.rooms_seen} rooms!");
            disengage;
        } else {
            print(f"Checked {here.name} (no treasure)");
            visit [-->];
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Guard Room")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Hidden Chamber")
        ++> Room(name="Dragon's Lair");
    root spawn Hunter();
}
