"""Tiny dungeon crawler: a chain of room nodes where one vault hides the treasure.

The Hunter walker threads the rooms one by one, counting its path, and the
moment it steps into the vault it ends the entire search so any rooms that
lie past the vault are never visited.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        print(f"[{self.rooms_seen}] Hunter enters {here.name}");
        if here.is_vault {
            print(f"Treasure found in '{here.name}' after {self.rooms_seen} room(s). Search ends.");
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Pillar Chamber", is_vault=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Sunken Reliquary");

    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter saw {hunter.rooms_seen} room(s) in total.");
}
