"""Quiz grader walker with strictly integer reports.

Each Quiz node carries a student's name and numeric score. A Grader walker
traverses the quizzes, collects scores into a strictly typed integer list,
and reports the class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        print(f"{here.student}: {here.score}");
        visit [-->];
    }

    can summarize with Root exit {
        total = 0;
        for s in self.scores {
            total = total + s;
        }
        avg = total // len(self.scores) if len(self.scores) > 0 else 0;
        print(f"Collected scores: {self.scores}");
        print(f"Class average: {avg}");
        report self.scores;
    }
}

with entry {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bao", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dax", score=64)
        ++> Quiz(student="Esi", score=90);
    root spawn Grader();
}
