"""Tiny dungeon crawler: rooms chained as nodes, hunter walker counts visited rooms and stops at the treasure vault."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        verdict = "VAULT FOUND!" if here.has_treasure else "empty";
        print(f"[{self.rooms_checked}] {here.name} -> {verdict}");

        if here.has_treasure {
            self.found = True;
            disengage;
        }

        visit [-->] else { disengage; }
    }
}

with entry {
    entrance = Room(name="Entrance");
    hall = Room(name="Damp Hall");
    armory = Room(name="Old Armory");
    vault = Room(name="Treasure Vault", has_treasure=True);
    cave = Room(name="Hidden Cave");
    pit = Room(name="Bottomless Pit");

    root ++> entrance ++> hall ++> armory ++> vault ++> cave ++> pit;

    hunter = Hunter();
    root spawn hunter;

    result = "treasure located" if hunter.found else "treasure missed";
    print(f"Hunter checked {hunter.rooms_checked} rooms and {result}.");
}
