    assert "Found treasure in 'Vault'" in out, f"missing treasure line in: {out}";

    # Rooms after the vault must NOT be searched — neither announced nor reached.
    assert "Secret Chamber" not in out, f"post-vault room was visited: {out}";
    assert "Dragon's Lair" not in out, f"post-vault room was visited: {out}";

    # The pre-vault rooms SHOULD have been searched.
