"""Order auditor demonstrating both flavors of early return.

Invalid orders are skipped (the walker keeps going to the next order),
while fraud-flagged orders halt the whole walk immediately via disengage.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print(f"Auditor starting walk");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] {here.title}: fraud detected (${here.amount}) -- stopping walk");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] {here.title}: invalid order -- continuing");
            visit [-->];
            return;
        }
        print(f"[OK]   {here.title}: ${here.amount} passed audit");
        visit [-->];
    }
}

with entry {
    root ++> Order(title="Order-001", amount=120.50, valid=True, fraud=False)
        ++> Order(title="Order-002", amount=45.00, valid=False, fraud=False)
        ++> Order(title="Order-003", amount=300.00, valid=True, fraud=False)
        ++> Order(title="Order-004", amount=9999.99, valid=True, fraud=True)
        ++> Order(title="Order-005", amount=75.25, valid=True, fraud=False);

    root spawn OrderAuditor();
}
