"""Test annex for the dungeon crawler: chain of rooms with a treasure vault.

Verifies that the Hunter walker:
  - walks forward through chained rooms
  - counts rooms it has entered
  - disengages immediately upon entering the treasure room
  - never visits rooms downstream of the vault
"""

import io;
import from contextlib { redirect_stdout }

# --- helpers ---------------------------------------------------------------

def _build_dungeon() {
    root ++> Room(name="Entrance Hall")
        ++> Room(name="Mossy Corridor")
        ++> Room(name="Flooded Chamber")
        ++> Room(name="Old Armory")
        ++> Room(name="Treasure Vault", has_treasure=True)
        ++> Room(name="Forbidden Passage")
        ++> Room(name="Dragon's Lair");
    return root;
}

def _run_hunter(rt) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn Hunter();
    }
    return (res, buf.getvalue());
}

# --- tests -----------------------------------------------------------------

test "hunter counts rooms up to and including the vault" {
    rt = _build_dungeon();
    (res, _) = _run_hunter(rt);
    assert res.rooms_seen == 5, f"expected rooms_seen=5 (4 empties + vault), got {res.rooms_seen}";
}

test "hunter announces the dungeon entry banner" {
    rt = _build_dungeon();
    (_, out) = _run_hunter(rt);
    assert "Hunter enters the dungeon..." in out, f"missing entry banner: {out!r}";
}

test "hunter reports the vault as the treasure room" {
    rt = _build_dungeon();
    (_, out) = _run_hunter(rt);
