    assert "Treasure Vault" in out, f"vault name missing from output: {out!r}";
}

test "hunter never visits rooms past the vault" {
    rt = _build_dungeon();
    (_, out) = _run_hunter(rt);
    assert "Forbidden Passage" not in out, f"hunter must disengage before Forbidden Passage: {out!r}";
    assert "Dragon's Lair" not in out, f"hunter must disengage before Dragon's Lair: {out!r}";
}

test "hunter visits every empty room before the vault" {
    rt = _build_dungeon();
    (_, out) = _run_hunter(rt);
    for name in ["Entrance Hall", "Mossy Corridor", "Flooded Chamber", "Old Armory"] {
        assert name in out, f"hunter skipped empty room {name}: {out!r}";
    }
    for line in out.splitlines() {
        if "pressing on" in line {
            assert "Treasure Vault" not in line, f"vault was treated as empty: {line!r}";
        }
    }
}

