"""Quiz grader walker: typed reports of integer scores collected across quizzes."""

node Quiz {
    has title: str = "";
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    # Typed accumulator: only ints can be reported, so a stray string
    # at any `report` site is a type error at compile time.
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        print(f"[{here.student}] {here.title}: {here.score}");
        visit [-->];
    }
}

with entry {
    root ++> Quiz(title="Algebra Pop Quiz", student="Alice", score=88)
        ++> Quiz(title="Algebra Pop Quiz", student="Bob", score=74)
        ++> Quiz(title="History Pop Quiz", student="Carol", score=95)
        ++> Quiz(title="History Pop Quiz", student="Dan", score=61)
        ++> Quiz(title="Science Pop Quiz", student="Eve", score=82);

    grader = Grader();
    root spawn grader;

    print(f"Collected scores: {grader.scores}");
    total = 0;
    for s in grader.scores {
        total = total + s;
    }
    average = total / len(grader.scores);
    print(f"Class average: {average}");
