```jac
"""Tiny dungeon crawler: chain of rooms with a hidden treasure.

A Hunter walker traverses the rooms one by one, counting how many it
has inspected. The moment it steps into the vault (the treasure room)
it reports the find and ``disengage``s — every room past the vault is
left unseen, by design.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;
    has found: bool = False;
    has vault_name: str = "";

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_inspected += 1;
        if here.is_vault {
            self.found = True;
            self.vault_name = here.name;
            print(f"Found the treasure in '{here.name}'! "
                  + f"Searched {self.rooms_inspected} rooms.");
            disengage;
        }
        print(f"Checked '{here.name}' — no treasure here.");
        visit [-->] else { disengage; }
    }
}

with entry {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", is_vault=True);
    secret = Room(name="Secret Chamber");

    root ++> entrance
        ++> hallway
        ++> armory
        ++> vault
        ++> secret;

    hunter = Hunter();
    root spawn hunter;

    if hunter.found {
        print(f"Treasure was in '{hunter.vault_name}'. "
              + f"Total rooms inspected: {hunter.rooms_inspected}. "
              + f"Rooms beyond the vault were skipped.");
    } else {
        print("No treasure found in this dungeon.");
    }
}
