"""Quiz grader: a walker whose reports are strictly typed to integers."""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];
    has total: int = 0;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        self.total = self.total + here.score;
        self.count = self.count + 1;
        report here.score;
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Lin", score=78)
        ++> Quiz(student="Sam", score=85)
        ++> Quiz(student="Mira", score=64);

