"""Tiny dungeon crawler: a hunter walks a chain of rooms and stops at the treasure vault."""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can search with Room entry {
        self.rooms_visited += 1;
        if here.is_treasure {
            print(f"Found treasure in '{here.name}' after checking {self.rooms_visited} room(s)!");
            disengage;
        }
        print(f"Checked '{here.name}' - empty.");
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Armory")
        ++> Room(name="Vault", is_treasure=True)
        ++> Room(name="Forbidden Chamber")
        ++> Room(name="Dragon's Lair");

    root spawn Hunter();
}
