"""Tiny dungeon crawler: chain of rooms with one vault holding treasure.

The Hunter walks the corridor one room at a time, counting visits,
and stops the entire search the instant it enters the vault.
Rooms past the vault must never be visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can explore with Room entry {
        self.rooms_seen += 1;
        if here.has_treasure {
            print(f"Found the treasure in {here.name} after {self.rooms_seen} room(s)!");
            disengage;
        }
        print(f"Searched {here.name}... nothing here.");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Whispers")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Forgotten Crypt")
        ++> Room(name="Throne Room");

    h = Hunter();
    root spawn h;

    print(f"Total rooms searched: {h.rooms_seen}");
}
