"""Weather sweep: stations hold a location and Celsius reading; a walker
visits each one and reports the temperature without disengaging mid-walk,
then the demo prints the full list plus min/max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[tuple[str, float]] = [];
    has min_t: float = 0.0;
    has max_t: float = 0.0;
    has count: int = 0;

    can start with Root entry {
        print("Weather sweep starting...");
        visit [-->];
    }

    can read with WeatherStation entry {
        print(f"At {here.location}: {here.celsius} C");
        self.readings.append((here.location, here.celsius));
        if self.count == 0 {
            self.min_t = here.celsius;
            self.max_t = here.celsius;
        } else {
            if here.celsius < self.min_t {
                self.min_t = here.celsius;
            }
            if here.celsius > self.max_t {
                self.max_t = here.celsius;
            }
        }
        self.count += 1;
        visit [-->];
    }

    can finish with Root exit {
        if self.count == 0 {
            print("No stations visited.");
            disengage;
        }
        print("All readings:");
        for (loc, temp) in self.readings {
            print(f"  {loc}: {temp} C");
        }
        print(f"Min: {self.min_t} C");
        print(f"Max: {self.max_t} C");
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Airport", celsius=19.0)
        ++> WeatherStation(location="Hilltop", celsius=27.3)
        ++> WeatherStation(location="Harbor", celsius=15.8);
    sweeper = WeatherSweep();
    root spawn sweeper;
}
```

jac_tests:
"""Tests for weather sweep walker."""

import io;
import from contextlib { redirect_stdout }

test "sweep reports all stations and computes min max" {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Airport", celsius=19.0)
        ++> WeatherStation(location="Hilltop", celsius=27.3)
        ++> WeatherStation(location="Harbor", celsius=15.8);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WeatherSweep();
    }
    out = buf.getvalue();

    assert "Weather sweep starting..." in out, f"missing start banner: {out}";
    assert "At Downtown: 22.5 C" in out, f"missing Downtown: {out}";
    assert "At Airport: 19.0 C" in out, f"missing Airport: {out}";
    assert "At Hilltop: 27.3 C" in out, f"missing Hilltop: {out}";
    assert "At Harbor: 15.8 C" in out, f"missing Harbor: {out}";
    assert "All readings:" in out, f"missing readings header: {out}";
    assert "Min: 15.8 C" in out, f"missing min: {out}";
    assert "Max: 27.3 C" in out, f"missing max: {out}";

    assert res.count == 4, f"expected 4 stations visited, got {res.count}";
    assert res.min_t == 15.8, f"expected min 15.8, got {res.min_t}";
    assert res.max_t == 27.3, f"expected max 27.3, got {res.max_t}";
    assert len(res.readings) == 4, f"expected 4 readings, got {len(res.readings)}";

    locs = [r[0] for r in res.readings];
    assert "Downtown" in locs, f"missing Downtown in readings: {locs}";
    assert "Airport" in locs, f"missing Airport in readings: {locs}";
    assert "Hilltop" in locs, f"missing Hilltop in readings: {locs}";
    assert "Harbor" in locs, f"missing Harbor in readings: {locs}";
}

test "sweep handles single station" {
    root ++> WeatherStation(location="Solo", celsius=10.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WeatherSweep();
    }
    out = buf.getvalue();

    assert "At Solo: 10.0 C" in out, f"missing Solo: {out}";
    assert "Min: 10.0 C" in out, f"single station min wrong: {out}";
    assert "Max: 10.0 C" in out, f"single station max wrong: {out}";
    assert res.count == 1, f"expected count 1, got {res.count}";
    assert res.min_t == 10.0, f"min wrong: {res.min_t}";
    assert res.max_t == 10.0, f"max wrong: {res.max_t}";
}

test "sweep handles negative and zero temperatures" {
    root ++> WeatherStation(location="Tundra", celsius=-15.5)
        ++> WeatherStation(location="Equator", celsius=0.0)
        ++> WeatherStation(location="Desert", celsius=45.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WeatherSweep();
    }
    out = buf.getvalue();

    assert "At Tundra: -15.5 C" in out, f"missing Tundra: {out}";
    assert "At Equator: 0.0 C" in out, f"missing Equator: {out}";
    assert "At Desert: 45.2 C" in out, f"missing Desert: {out}";
    assert "Min: -15.5 C" in out, f"min wrong: {out}";
    assert "Max: 45.2 C" in out, f"max wrong: {out}";
    assert res.min_t == -15.5, f"expected min -15.5, got {res.min_t}";
    assert res.max_t == 45.2, f"expected max 45.2, got {res.max_t}";
    assert res.count == 3, f"expected count 3, got {res.count}";
}

test "walker does not disengage early during traversal" {
    root ++> WeatherStation(location="A", celsius=20.0)
        ++> WeatherStation(location="B", celsius=21.0)
        ++> WeatherStation(location="C", celsius=22.0)
        ++> WeatherStation(location="D", celsius=23.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WeatherSweep();
    }
    out = buf.getvalue();

    # Every station should be visited before the "All readings" line appears,
    # and the All readings block must contain all four entries.
    all_idx = out.find("All readings:");
    assert all_idx != -1, f"missing readings header: {out}";

    station_visits = [
        out.find("At A: 20.0 C"),
        out.find("At B: 21.0 C"),
        out.find("At C: 22.0 C"),
        out.find("At D: 23.0 C"),
    ];
    assert all(v != -1 for v in station_visits), f"missing station visit: {out}";
    assert all(v < all_idx for v in station_visits), f"station visited after readings printed: {out}";
    assert res.count == 4, f"expected count 4 (no early disengage), got {res.count}";
    assert "No stations visited." not in out, f"should not report empty: {out}";
}

