"""Quiz grader walker with strictly typed integer reports.

Demonstrates a walker whose ``report`` field is typed as ``list[int]`` so
only integer scores can be collected, preventing accidental string
pollution of the grade book.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has report: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.report.append(here.score);
        visit [-->];
    }
}

with entry {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bashir", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dmitri", score=64);

    grader = Grader();
    root spawn grader;

    total = 0;
    for s in grader.report {
        print(f"score: {s}");
        total = total + s;
    }
    avg = total / len(grader.report);
    print(f"class average: {avg}");
}
```

jac_tests:
"""Tests for the Quiz grader walker: strictly typed integer reports
and correct traversal/aggregation behavior."""

import io;
import from contextlib { redirect_stdout }

test "report collects integer scores in order" {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bashir", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dmitri", score=64);

    grader = Grader();
    root spawn grader;

    assert grader.report == [92, 78, 85, 64], f"expected [92,78,85,64], got {grader.report}";
    assert len(grader.report) == 4, f"expected 4 reports, got {len(grader.report)}";
}

test "all collected reports are integers" {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bashir", score=78);

    grader = Grader();
    root spawn grader;

    for s in grader.report {
        assert isinstance(s, int), f"report entry {s!r} is not an int";
        assert not isinstance(s, bool), f"bool leaked into reports as {s!r}";
    }
}

test "report field starts empty and only fills after spawning" {
    root ++> Quiz(student="Ada", score=50);

    grader = Grader();
    assert grader.report == [], f"fresh report should be empty, got {grader.report}";

    root spawn grader;
    assert grader.report == [50], f"after spawn expected [50], got {grader.report}";
}

test "no Quiz nodes means empty report" {
    grader = Grader();
    root spawn grader;

    assert grader.report == [], f"expected empty report with no quizzes, got {grader.report}";
    assert len(grader.report) == 0, f"expected len 0, got {len(grader.report)}";
}

test "stdout prints each score and class average" {
    root ++> Quiz(student="Ada", score=92)
        ++> Quiz(student="Bashir", score=78)
        ++> Quiz(student="Cleo", score=85)
        ++> Quiz(student="Dmitri", score=64);

    buf = io.StringIO();
    grader = Grader();
    with redirect_stdout(buf) {
        root spawn grader;

        total = 0;
        for s in grader.report {
            print(f"score: {s}");
            total = total + s;
        }
        avg = total / len(grader.report);
        print(f"class average: {avg}");
    }
    out = buf.getvalue();

    assert "score: 92" in out, f"missing score 92 in: {out}";
    assert "score: 78" in out, f"missing score 78 in: {out}";
    assert "score: 85" in out, f"missing score 85 in: {out}";
    assert "score: 64" in out, f"missing score 64 in: {out}";
    assert "class average: 79.75" in out, f"missing average in: {out}";
}

