"""Hiking trail: plain waypoints between trailhead and summit; a hiker counts each stop."""

node TrailHead {
    has name: str = "Trailhead";
}

node Waypoint {}

node Summit {
    has name: str = "Summit";
}

walker Hiker {
    has stop_num: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with TrailHead entry {
        print(f"Departing {here.name}");
        visit [-->];
    }

    can pass_marker with Waypoint entry {
        self.stop_num += 1;
        print(f"Stop {self.stop_num}");
        visit [-->];
    }

    can finish with Summit entry {
        print(f"Reached {here.name}: passed {self.stop_num} waypoints.");
        disengage;
    }
}

with entry {
    root ++> TrailHead(name="Oak Ridge Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Eagle Peak");
    root spawn Hiker();
}
```

