"""Tests for the hiking trail walker."""

import io;
import from contextlib { redirect_stdout }

test "hiker counts every waypoint it passes" {
    root ++> TrailHead(name="Pine Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Pine Summit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stop_num == 3, f"expected 3 waypoints passed, got {res.stop_num}";
    assert "Stop 1" in out, f"missing Stop 1 in output: {out}";
    assert "Stop 2" in out, f"missing Stop 2 in output: {out}";
    assert "Stop 3" in out, f"missing Stop 3 in output: {out}";
}

test "hiker prints completion line with count on summit" {
    root ++> TrailHead(name="Cedar Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Cedar Summit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Reached Cedar Summit" in out, f"missing summit message: {out}";
    assert "passed 5 waypoints" in out, f"missing waypoint count: {out}";
    assert res.stop_num == 5, f"expected 5 stops, got {res.stop_num}";
}

test "trail with no waypoints reaches summit with zero count" {
    root ++> TrailHead(name="Bare Trailhead")
        ++> Summit(name="Bare Summit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stop_num == 0, f"expected 0 waypoints, got {res.stop_num}";
    assert "passed 0 waypoints" in out, f"expected zero count in completion: {out}";
    assert "Reached Bare Summit" in out, f"missing summit message: {out}";
    assert "Stop 1" not in out, f"unexpected stop line on empty trail: {out}";
}

test "stop numbers are sequential starting at one" {
    root ++> TrailHead(name="Oak Trailhead")
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit(name="Oak Summit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();
    lines = out.strip().split("\n");

    stop_lines = [l for l in lines if l.startswith("Stop ")];
    assert len(stop_lines) == 3, f"expected 3 stop lines, got {len(stop_lines)}: {out}";
    assert stop_lines[0] == "Stop 1", f"first stop should be 'Stop 1', got '{stop_lines[0]}'";
    assert stop_lines[1] == "Stop 2", f"second stop should be 'Stop 2', got '{stop_lines[1]}'";
    assert stop_lines[2] == "Stop 3", f"third stop should be 'Stop 3', got '{stop_lines[2]}'";
    assert res.stop_num == 3, f"final count should be 3, got {res.stop_num}";
