        ++> Summit(name="Maple Summit");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Departing Maple Trailhead" in out, f"missing departing message: {out}";
    assert res.stop_num == 1, f"expected 1 waypoint, got {res.stop_num}";
}

