"""Tests for the dungeon crawler Hunter walker behavior."""

import io;
import from contextlib { redirect_stdout }

test "hunter counts only rooms up to and including the vault" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Chamber")
        ++> Room(name="Dragon's Lair");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.rooms_checked == 4, f"hunter should count 4 rooms (3 before vault + vault), got {res.rooms_checked}";
    assert "Vault" in out, f"expected 'Vault' in traversal output: {out}";
    assert "Forbidden Chamber" not in out, f"rooms past vault must not be visited: {out}";
    assert "Dragon's Lair" not in out, f"rooms past vault must not be visited: {out}";
    assert "Treasure found in Vault! Search ends." in out, f"missing treasure announcement: {out}";
    assert "Final tally" in out or res.rooms_checked == 4, f"output missing tally line: {out}";
}

test "hunter stops immediately when vault is the very first room" {
    root ++> Room(name="Immediate Vault", is_vault=True)
        ++> Room(name="Should Not See")
        ++> Room(name="Also Not Seen");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.rooms_checked == 1, f"hunter should count exactly 1 (just the vault), got {res.rooms_checked}";
    assert "Immediate Vault" in out, f"vault room should be announced: {out}";
    assert "Should Not See" not in out, f"rooms after vault must not be entered: {out}";
    assert "Treasure found" in out, f"treasure announcement missing: {out}";
}

test "hunter visits every room when no vault is present" {
    root ++> Room(name="A")
        ++> Room(name="B")
        ++> Room(name="C")
        ++> Room(name="D");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.rooms_checked == 4, f"hunter should visit all 4 rooms when no vault, got {res.rooms_checked}";
    assert "Treasure found" not in out, f"no treasure announcement should appear: {out}";
    for name in ["A", "B", "C", "D"] {
        assert name in out, f"room {name} missing from output: {out}";
    }
}

test "hunter never enters a room past the vault regardless of chain length" {
    root ++> Room(name="R1")
        ++> Room(name="R2")
        ++> Room(name="R3", is_vault=True)
        ++> Room(name="R4")
        ++> Room(name="R5")
        ++> Room(name="R6")
        ++> Room(name="R7");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert res.rooms_checked == 3, f"hunter should stop at the vault (count 3), got {res.rooms_checked}";
    for leaked in ["R4", "R5", "R6", "R7"] {
        assert leaked not in out, f"room {leaked} past vault must never be entered: {out}";
    }
    assert "R3" in out, f"vault room R3 must appear in output: {out}";
}

test "hunter spawn from a Room node still respects disengage at vault" {
    root ++> Room(name="Entrance")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Past1")
        ++> Room(name="Past2");

    # Start the hunter directly on the Entrance Room node so we exercise the
    # `can explore with Room entry` ability path rather than the Root path.
    entrance = [root -->][0];
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = entrance spawn Hunter();
    }
    out = buf.getvalue();

    assert res.rooms_checked == 2, f"hunter should visit Entrance + Vault (count 2), got {res.rooms_checked}";
    assert "Past1" not in out, f"room past vault must never be entered: {out}";
    assert "Past2" not in out, f"room past vault must never be entered: {out}";
    assert "Treasure found in Vault! Search ends." in out, f"missing treasure line: {out}";
}

