```jac
"""Tiny dungeon crawler: chained rooms with a treasure vault that halts the hunt."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;
    has found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        self.rooms_checked += 1;
        if here.has_treasure {
            self.found = True;
            print(f"Found the treasure in '{here.name}' after checking "
                  f"{self.rooms_checked} room(s)!");
            disengage;
        }
        print(f"'{here.name}' is empty ({self.rooms_checked} checked)");
        visit [-->] else { disengage; }
    }
}

with entry {
    entry_room = Room(name="Entry Hall");
    armory = Room(name="Armory");
    library = Room(name="Library");
    vault = Room(name="Vault", has_treasure=True);
    # Rooms past the vault must never be visited.
    secret_grotto = Room(name="Secret Grotto");
    dragons_lair = Room(name="Dragon's Lair");

    root ++> entry_room
        ++> armory
        ++> library
        ++> vault
        ++> secret_grotto
        ++> dragons_lair;

    hunter = Hunter();
    root spawn hunter;

    print(f"Hunter stopped. Checked {hunter.rooms_checked} room(s); "
          f"treasure found = {hunter.found}");
}
```

