"""Tests for the tiny dungeon crawler: hunter halts at the treasure room."""

import io;
import from contextlib { redirect_stdout }

test "hunter finds treasure in vault and stops" {
    root ++> Room(name="Entry Hall")
        ++> Room(name="Armory")
        ++> Room(name="Library")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Secret Grotto")
        ++> Room(name="Dragon's Lair");

    buf = io.StringIO();
    hunter = Hunter();
    with redirect_stdout(buf) {
        res = root spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.found == True, f"expected found=True, got {hunter.found}";
    assert hunter.rooms_checked == 4, f"expected 4 rooms checked, got {hunter.rooms_checked}";
    assert "Found the treasure in 'Vault'" in out, f"missing treasure message: {out}";
    assert "Secret Grotto" not in out, f"hunter visited rooms past the vault: {out}";
    assert "Dragon's Lair" not in out, f"hunter visited rooms past the vault: {out}";
    assert "Hunter enters the dungeon..." in out, f"missing entry banner: {out}";
}

test "hunter stops after the vault even with no treasure marker on earlier rooms" {
    root ++> Room(name="Entry Hall")
        ++> Room(name="Empty Room A")
        ++> Room(name="Empty Room B")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Should Not Visit 1")
        ++> Room(name="Should Not Visit 2");

    buf = io.StringIO();
    hunter = Hunter();
    with redirect_stdout(buf) {
        res = root spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.found == True, f"expected found=True, got {hunter.found}";
    assert hunter.rooms_checked == 4, f"expected 4 rooms checked, got {hunter.rooms_checked}";
    assert "Should Not Visit 1" not in out, f"walker leaked past the vault: {out}";
    assert "Should Not Visit 2" not in out, f"walker leaked past the vault: {out}";
}

test "hunter with no treasure disengages at dead end" {
    root ++> Room(name="Lone Room");

    buf = io.StringIO();
    hunter = Hunter();
    with redirect_stdout(buf) {
        res = root spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.found == False, f"expected found=False, got {hunter.found}";
    assert hunter.rooms_checked == 1, f"expected 1 room checked, got {hunter.rooms_checked}";
    assert "Lone Room" in out, f"missing room report: {out}";
    assert "Found the treasure" not in out, f"false positive treasure detection: {out}";
}

test "hunter stops at first treasure even when a second vault lies deeper" {
    root ++> Room(name="Entry Hall")
        ++> Room(name="First Vault", has_treasure=True)
        ++> Room(name="Beyond First")
        ++> Room(name="Second Vault", has_treasure=True)
        ++> Room(name="Beyond Second");

    buf = io.StringIO();
    hunter = Hunter();
    with redirect_stdout(buf) {
        res = root spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.found == True, f"expected found=True, got {hunter.found}";
    assert hunter.rooms_checked == 2, f"expected 2 rooms checked, got {hunter.rooms_checked}";
    assert "Found the treasure in 'First Vault'" in out, f"missing first-vault message: {out}";
    assert "Second Vault" not in out, f"hunter continued past first treasure: {out}";
    assert "Beyond First" not in out, f"hunter visited room past treasure: {out}";
    assert "Beyond Second" not in out, f"hunter visited room past treasure: {out}";
}

