```jac
"""Weather sweep: model weather stations as nodes and walk them with a reporter walker."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweeper {
    has readings: list[tuple[str, float]] = [];

    can start with Root entry {
        visit [-->];
    }

    can sample with WeatherStation entry {
        self.readings.append((here.location, here.celsius));
        print(f"Reading at {here.location}: {here.celsius} C");
        visit [-->];
    }
}

with entry {
    root ++> WeatherStation(location="North Ridge", celsius=14.5)
        ++> WeatherStation(location="River Valley", celsius=22.0)
        ++> WeatherStation(location="Coastal Pier", celsius=18.3)
        ++> WeatherStation(location="Desert Mesa", celsius=31.7);

    sweeper = WeatherSweeper();
    root spawn sweeper;

    print("--- Sweep complete ---");
    for (loc, temp) in sweeper.readings {
        print(f"{loc}: {temp} C");
    }

    temps = [temp for (_, temp) in sweeper.readings];
    lo = min(temps);
    hi = max(temps);
    print(f"Min: {lo} C");
    print(f"Max: {hi} C");
}
```

jac_tests:
"""Tests for the weather sweep walker."""

import io;
import from contextlib { redirect_stdout }

test "sweeper visits all stations and records readings in order" {
    root ++> WeatherStation(location="Alpha", celsius=10.0)
        ++> WeatherStation(location="Beta", celsius=20.0)
        ++> WeatherStation(location="Gamma", celsius=15.0);

    sweeper = WeatherSweeper();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn sweeper;
    }
    out = buf.getvalue();

    # 3 stations, 3 "Reading at" lines printed in traversal order.
    assert out.count("Reading at") == 3, f"expected 3 reading lines, got: {out}";
    assert "Reading at Alpha: 10.0 C" in out, f"missing Alpha line: {out}";
    assert "Reading at Beta: 20.0 C" in out, f"missing Beta line: {out}";
    assert "Reading at Gamma: 15.0 C" in out, f"missing Gamma line: {out}";

    # Readings list preserves visit order and pairs location with celsius.
    assert len(sweeper.readings) == 3, f"expected 3 readings, got {len(sweeper.readings)}";
    assert sweeper.readings[0] == ("Alpha", 10.0), f"first reading wrong: {sweeper.readings[0]}";
    assert sweeper.readings[1] == ("Beta", 20.0), f"second reading wrong: {sweeper.readings[1]}";
    assert sweeper.readings[2] == ("Gamma", 15.0), f"third reading wrong: {sweeper.readings[2]}";
}

test "sweeper on a graph with one station reports only that station" {
    root ++> WeatherStation(location="Solo", celsius=7.25);

    sweeper = WeatherSweeper();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn sweeper;
    }
    out = buf.getvalue();

    assert len(sweeper.readings) == 1, f"expected 1 reading, got {len(sweeper.readings)}";
    assert sweeper.readings[0] == ("Solo", 7.25), f"got {sweeper.readings[0]}";
    assert "Reading at Solo: 7.25 C" in out, f"missing output line: {out}";
}

test "sweeper does not stop at the first station (keeps walking)" {
    # If the walker stopped at the first station, only the first
    # temperature would ever be recorded and "Reading at" would print once.
    root ++> WeatherStation(location="First", celsius=1.0)
        ++> WeatherStation(location="Second", celsius=2.0)
        ++> WeatherStation(location="Third", celsius=3.0);

    sweeper = WeatherSweeper();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn sweeper;
    }
    out = buf.getvalue();

    assert len(sweeper.readings) == 3, f"walker stopped early, got {len(sweeper.readings)} readings";
    assert out.count("Reading at") == 3, f"walker stopped early, output: {out}";
    # All three distinct stations appear, confirming continued traversal.
    assert "First" in out and "Second" in out and "Third" in out, f"missing stations: {out}";
}

test "min and max can be derived from the recorded readings" {
    root ++> WeatherStation(location="Cold", celsius=-4.0)
        ++> WeatherStation(location="Mild", celsius=12.5)
        ++> WeatherStation(location="Hot", celsius=35.0)
        ++> WeatherStation(location="Warm", celsius=22.0);

    sweeper = WeatherSweeper();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn sweeper;
    }

    temps = [temp for (_, temp) in sweeper.readings];
    assert min(temps) == -4.0, f"min wrong: {min(temps)}";
    assert max(temps) == 35.0, f"max wrong: {max(temps)}";
    assert len(temps) == 4, f"expected 4 temps, got {len(temps)}";
}

