import io;
import from contextlib { redirect_stdout }

test "all valid no fraud walks every order and counts them" {
    root ++> Order(order_id="B1", amount=10.0, valid=True, fraud=False)
        ++> Order(order_id="B2", amount=20.0, valid=True, fraud=False)
        ++> Order(order_id="B3", amount=30.0, valid=True, fraud=False);

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK]   order B1 ($10.0) cleared" in out, f"missing B1 OK line: {out}";
    assert "[OK]   order B2 ($20.0) cleared" in out, f"missing B2 OK line: {out}";
    assert "[OK]   order B3 ($30.0) cleared" in out, f"missing B3 OK line: {out}";
    assert "[SKIP]" not in out, f"unexpected skip on all-valid run: {out}";
    assert "[HALT]" not in out, f"unexpected halt on all-valid run: {out}";
    assert res.processed == 3, f"expected 3 processed, got {res.processed}";
}

test "invalid order is skipped but audit continues to later valid ones" {
    root ++> Order(order_id="C1", amount=100.0, valid=True,  fraud=False)
        ++> Order(order_id="C2", amount= 50.0, valid=False, fraud=False)
        ++> Order(order_id="C3", amount=200.0, valid=True,  fraud=False);

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK]   order C1 ($100.0) cleared" in out, f"missing C1 OK line: {out}";
    assert "[SKIP] order C2 invalid — audit continues" in out, f"missing C2 SKIP line: {out}";
    assert "[OK]   order C3 ($200.0) cleared" in out, f"C3 must run after skip, got: {out}";
    assert "[HALT]" not in out, f"invalid order must not halt the walk: {out}";
    assert res.processed == 2, f"only the 2 valid orders count, got {res.processed}";
}

test "fraud flag aborts the entire walk on the spot" {
    root ++> Order(order_id="D1", amount=10.0, valid=True, fraud=False)
        ++> Order(order_id="D2", amount=20.0, valid=True, fraud=True)
        ++> Order(order_id="D3", amount=30.0, valid=True, fraud=False);

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK]   order D1 ($10.0) cleared" in out, f"D1 should run before halt: {out}";
    assert "[HALT] fraud flag on order D2 ($20.0) — walk aborted" in out, f"missing HALT line: {out}";
    assert "[OK]   order D3" not in out, f"D3 must NOT be visited after disengage, got: {out}";
    assert "[SKIP]" not in out, f"fraud halt should not produce skip lines: {out}";
    assert res.processed == 1, f"only D1 counts before halt, got {res.processed}";
}

test "invalid then fraud still halts on the fraud order" {
    root ++> Order(order_id="E1", amount=10.0, valid=False, fraud=False)
        ++> Order(order_id="E2", amount=20.0, valid=True,  fraud=True);

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP] order E1 invalid — audit continues" in out, f"missing E1 skip: {out}";
    assert "[HALT] fraud flag on order E2 ($20.0) — walk aborted" in out, f"missing E2 halt: {out}";
    assert res.processed == 0, f"no valid orders processed before halt, got {res.processed}";
}

