"""Tests for the tiny dungeon crawler: Hunter walker terminates at the vault."""

import io;
import from contextlib { redirect_stdout }

test "hunter terminates at treasure and never visits rooms past the vault" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes", is_treasure=True)
        ++> Room(name="Forbidden Vault")
        ++> Room(name="Sunken Crypt")
        ++> Room(name="Bottomless Pit");

    buf = io.StringIO();
    res: Hunter = None;
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # Treasure was found.
    assert "Found the treasure" in out, f"missing treasure announcement: {out}";
    assert "Hall of Echoes" in out, f"treasure room not named: {out}";

    # The number of rooms the hunter stepped into must equal the index of the
    # vault (3: Entrance, Antechamber, Hall of Echoes).
    assert res.rooms_checked == 3, f"got rooms_checked={res.rooms_checked}";

    # No room beyond the vault may appear in the search log.
    assert "Forbidden Vault" not in out, f"hunter visited past vault: {out}";
    assert "Sunken Crypt" not in out, f"hunter visited past vault: {out}";
    assert "Bottomless Pit" not in out, f"hunter visited past vault: {out}";

    # The explored branch should match exactly the chain up to the vault.
    explored_names = [
        r.name for r in [root-->]
        if r.name in {"Entrance", "Antechamber", "Hall of Echoes",
                      "Forbidden Vault", "Sunken Crypt", "Bottomless Pit"}
    ];
    assert "Forbidden Vault" not in explored_names, "vault must remain unvisited in graph traversal";
}

test "hunter reports each non-treasure room before reaching the vault" {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Hall of Echoes", is_treasure=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # Every non-treasure room on the chain must be announced.
    assert "Checked Entrance" in out, f"Entrance not announced: {out}";
    assert "Checked Antechamber" in out, f"Antechamber not announced: {out}";

    # Treasure announcement must come after the checks.
    pos_entrance = out.find("Checked Entrance");
    pos_ante = out.find("Checked Antechamber");
    pos_treasure = out.find("Found the treasure");
    assert pos_entrance >= 0 and pos_ante > pos_entrance, f"wrong order: {out}";
    assert pos_treasure > pos_ante, f"treasure line out of order: {out}";

    assert res.rooms_checked == 3, f"got rooms_checked={res.rooms_checked}";
}

test "hunter disengages at a one-room dungeon where root points straight at the treasure" {
    root ++> Room(name="Vault", is_treasure=True);

    buf = io.StringIO();
    res: Hunter = None;
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Found the treasure in Vault" in out, f"missing treasure line: {out}";
    assert res.rooms_checked == 1, f"got rooms_checked={res.rooms_checked}";
}

test "hunter ends cleanly at a dead-end branch when no treasure is present" {
    # Only non-treasure rooms chained off root: the walker should visit each
    # one, then disengage because the final room has no outgoing edges.
    root ++> Room(name="A")
        ++> Room(name="B")
        ++> Room(name="C");

    buf = io.StringIO();
    res: Hunter = None;
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Checked A" in out, f"A missing: {out}";
    assert "Checked B" in out, f"B missing: {out}";
    assert "Checked C" in out, f"C missing: {out}";
    assert "Found the treasure" not in out, f"no treasure expected: {out}";
    assert res.rooms_checked == 3, f"got rooms_checked={res.rooms_checked}";
}

