"""Weather sweep: stations hold a Celsius reading; a walker reports each one, then we summarize."""

node Station {
    has name: str = "";
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[tuple[str, str, float]] = [];

    can start with Root entry {
        visit [-->];
    }

    can sample with Station entry {
        print(f"  reading {here.celsius}C at {here.name} ({here.location})");
        self.readings.append((here.name, here.location, here.celsius));
        visit [-->];
    }
}

with entry {
    root ++> Station(name="North",  location="Ridge",    celsius=12.5)
        ++> Station(name="East",   location="Harbor",   celsius=18.0)
        ++> Station(name="South",  location="Valley",   celsius=9.25)
        ++> Station(name="West",   location="Plateau",  celsius=21.75);

    sweep = WeatherSweep();
    root spawn sweep;

    print("--- summary ---");
    for (n, loc, t) in sweep.readings {
        print(f"{n} @ {loc}: {t}C");
    }
    if len(sweep.readings) > 0 {
        lo = sweep.readings[0][2];
        hi = sweep.readings[0][2];
        for (_, _, t) in sweep.readings {
            lo = t if t < lo else lo;
            hi = t if t > hi else hi;
        }
        print(f"min: {lo}C");
        print(f"max: {hi}C");
    }
}
