"""Tests for the WeatherSweep walker."""

import io;
import from contextlib { redirect_stdout }

test "walker reports every station reading and keeps order" {
    root ++> Station(name="A", location="North", celsius=10.0)
        ++> Station(name="B", location="East",  celsius=20.0)
        ++> Station(name="C", location="West",  celsius=30.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
    }
    out = buf.getvalue();

    # Each station should have been announced.
    assert "reading 10.0C at A (North)" in out, f"missing A: {out}";
    assert "reading 20.0C at B (East)"  in out, f"missing B: {out}";
    assert "reading 30.0C at C (West)"  in out, f"missing C: {out}";

    # Three readings were recorded in traversal order.
    assert len(sweep.readings) == 3, f"expected 3 readings, got {len(sweep.readings)}}";
    assert sweep.readings[0][0] == "A", f"first name wrong: {sweep.readings[0]}";
    assert sweep.readings[1][0] == "B", f"second name wrong: {sweep.readings[1]}";
    assert sweep.readings[2][0] == "C", f"third name wrong: {sweep.readings[2]}";

    # Tuples must carry (name, location, celsius).
    assert sweep.readings[0][1] == "North", f"loc wrong: {sweep.readings[0]}";
    assert sweep.readings[0][2] == 10.0,     f"temp wrong: {sweep.readings[0]}";
    assert sweep.readings[2][2] == 30.0,     f"temp wrong: {sweep.readings[2]}";
}

test "walker visits all direct children in one sweep" {
    root ++> Station(name="x1", location="L1", celsius=1.0)
           ++> Station(name="x2", location="L2", celsius=2.0)
           ++> Station(name="x3", location="L3", celsius=3.0)
           ++> Station(name="x4", location="L4", celsius=4.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
    }
    out = buf.getvalue();

    for nm in ["x1", "x2", "x3", "x4"] {
        assert f"at {nm}" in out, f"station {nm} not reported: {out}";
    }
    assert len(sweep.readings) == 4, f"expected 4 readings, got {len(sweep.readings)}";
}

test "min and max span the whole set, not just endpoints" {
    # Endpoints are warm; the middle node is the coldest.
    root ++> Station(name="Warm1", location="South", celsius=25.0)
        ++> Station(name="Cold",  location="Peak",   celsius=-5.5)
        ++> Station(name="Warm2", location="North", celsius=30.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
        print("--- summary ---");
        for (n, loc, t) in sweep.readings {
            print(f"{n} @ {loc}: {t}C");
        }
        lo = sweep.readings[0][2];
        hi = sweep.readings[0][2];
        for (_, _, t) in sweep.readings {
            lo = t if t < lo else lo;
            hi = t if t > hi else hi;
        }
        print(f"min: {lo}C");
        print(f"max: {hi}C");
    }
    out = buf.getvalue();

    # Reproduce the same min/max reduction and check it matches what's printed.
    temps = [r[2] for r in sweep.readings];
    expected_min = min(temps);
    expected_max = max(temps);

    assert f"min: {expected_min}C" in out, f"min line wrong: {out}";
    assert f"max: {expected_max}C" in out, f"max line wrong: {out}";

    # Sanity: the min really is the coldest, not one of the warm endpoints.
    assert expected_min == -5.5, f"min should be -5.5, got {expected_min}";
    assert expected_max == 30.0, f"max should be 30.0, got {expected_max}";
}

test "graph edges link stations in a chain off the root" {
    n1 = Station(name="S1", location="L1", celsius=1.0);
    n2 = Station(name="S2", location="L2", celsius=2.0);
    n3 = Station(name="S3", location="L3", celsius=3.0);
    root ++> n1 ++> n2 ++> n3;

    # Root has exactly one direct child (the chain head).
    assert len([root-->]) == 1, f"root should have one direct child, got {len([root-->])}";

    # Follow the chain: n1 -> n2 -> n3.
    children = [n1 -->];
    assert len(children) == 1 and children[0] == n2, f"n1 child wrong: {children}";
    children = [n2 -->];
    assert len(children) == 1 and children[0] == n3, f"n2 child wrong: {children}";
    assert len([n3 -->]) == 0, f"n3 should be terminal, got {len([n3 -->])}";

    # Three stations reachable from root.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;
    }
    out = buf.getvalue();

    assert "at S1" in out and "at S2" in out and "at S3" in out, f"missing stations: {out}";
    assert len(sweep.readings) == 3, f"expected 3 readings, got {len(sweep.readings)}";
}

