```jac
"""Order auditor demonstrating both early-return flavors side by side.

Invalid orders are skipped (the walker advances past them), but a
fraud-flagged order halts the entire walk via ``disengage;``.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] {here.label} flagged for fraud: ${here.amount} \u2014 disengaging");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] {here.label} invalid: ${here.amount} \u2014 continuing");
            visit [-->];
        }
        print(f"[OK]   {here.label} cleared: ${here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="ORD-1", amount=120.50)
        ++> Order(label="ORD-2", amount=80.00, valid=False)
        ++> Order(label="ORD-3", amount=45.25)
        ++> Order(label="ORD-4", amount=999.99, fraud=True)
        ++> Order(label="ORD-5", amount=30.00);

    root spawn OrderAuditor();
}
```

