"""Order auditor: invalid orders are skipped, fraud orders halt the walk."""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print(f"OrderAuditor beginning sweep");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALTED";
            self.halted = True;
        } elif not here.valid {
            action = "SKIPPED";
        } else {
            action = "OK";
            self.audited += 1;
        }
        print(f"[{action}] {here.title} amount={here.amount} valid={here.valid} fraud={here.fraud}");
        if here.fraud {
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Order(title="ORD-001", amount=120.50)
        ++> Order(title="ORD-002", amount=0.00, valid=False)
        ++> Order(title="ORD-003", amount=9999.99)
        ++> Order(title="ORD-004", amount=42.00, fraud=True)
        ++> Order(title="ORD-005", amount=77.77);
    root spawn OrderAuditor();
    print(f"final: audited={OrderAuditor().audited} halted={OrderAuditor().halted}");
}
