"""Restaurant recommender: a finder walker filters by minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 0.0;
    has matches: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scout with Restaurant entry {
        if here.rating >= self.min_rating {
            self.matches.append(f"{here.name} ({here.cuisine}, {here.rating})");
        }
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.7)
        ++> Restaurant(name="Sakura", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.8)
        ++> Restaurant(name="Burger Hub", cuisine="American", rating=3.2)
        ++> Restaurant(name="Spice Route", cuisine="Indian", rating=4.3)
        ++> Restaurant(name="Cafe Fresca", cuisine="Italian", rating=3.9);

    date_night = Finder(min_rating=4.5);
    root spawn date_night;
    print(f"Date night picks (4.5+): {date_night.matches}");

    casual_lunch = Finder(min_rating=3.5);
    root spawn casual_lunch;
    print(f"Casual lunch picks (3.5+): {casual_lunch.matches}");
}
