    library = Room(name="Forbidden Library");
    vault = Room(name="Sealed Vault", is_treasure=True);
    forbidden_halls = Room(name="Forbidden Halls Beyond");
    inner_sanctum = Room(name="Inner Sanctum");

    root ++> entry_room
        ++> armory
        ++> library
        ++> vault
        ++> forbidden_halls
        ++> inner_sanctum;

    root spawn Hunter();
}
