    library = Room(name="Library");
    vault = Room(name="Vault of Wonders", is_vault=True);
    throne = Room(name="Throne Room");
    dungeon = Room(name="Dungeon");

    root ++> entry_room
        ++> armory
        ++> library
        ++> vault
        ++> throne
        ++> dungeon;

    hunter = Hunter();
    root spawn hunter;
    print(f"Total rooms inspected: {hunter.rooms_seen}");
}
