    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    return buf.getvalue();
}


test "valid orders are all audited and walker reaches the end" {
    root ++> Order(label="A1", amount=10.00, valid=True)
        ++> Order(label="A2", amount=20.00, valid=True)
        ++> Order(label="A3", amount=30.00, valid=True);

