    assert "Auditor beginning walk..." in out, f"missing start banner: {out}";
    assert "AUDIT A1: amount=10.00" in out, f"missing A1 audit line: {out}";
    assert "AUDIT A2: amount=20.00" in out, f"missing A2 audit line: {out}";
    assert "AUDIT A3: amount=30.00" in out, f"missing A3 audit line: {out}";
    assert "HALT" not in out, f"unexpected halt: {out}";
    assert "SKIP" not in out, f"unexpected skip: {out}";
}


test "invalid orders are skipped but walk continues to later valid orders" {
    root ++> Order(label="B1", amount=50.00, valid=True)
        ++> Order(label="B2", amount=60.00, valid=False)
        ++> Order(label="B3", amount=70.00, valid=True)
        ++> Order(label="B4", amount=80.00, valid=False)
        ++> Order(label="B5", amount=90.00, valid=True);

    out = _run_walk([]);

    assert "AUDIT B1: amount=50.00" in out, f"missing B1 audit: {out}";
    assert "SKIP B2: invalid order, continuing" in out, f"missing B2 skip: {out}";
    assert "AUDIT B3: amount=70.00" in out, f"B3 must still be audited after invalid: {out}";
    assert "SKIP B4: invalid order, continuing" in out, f"missing B4 skip: {out}";
    assert "AUDIT B5: amount=90.00" in out, f"B5 must still be audited after invalid: {out}";
    assert "HALT" not in out, f"walk should not halt on invalid-only chain: {out}";
}


test "fraud flag halts the walk immediately and later orders are not visited" {
    root ++> Order(label="C1", amount=11.00, valid=True)
        ++> Order(label="C2", amount=22.00, valid=True)
        ++> Order(label="C3", amount=33.00, valid=True, fraud=True)
        ++> Order(label="C4", amount=44.00, valid=True)
        ++> Order(label="C5", amount=55.00, valid=True);

    out = _run_walk([]);

    assert "AUDIT C1: amount=11.00" in out, f"missing C1 audit: {out}";
    assert "AUDIT C2: amount=22.00" in out, f"missing C2 audit: {out}";
    assert "HALT on C3: fraud flag set, aborting audit" in out, f"missing halt on C3: {out}";
