    # rather than the skip-and-continue branch.
    root ++> Order(label="D1", amount=5.00, valid=False)
        ++> Order(label="D2", amount=6.00, valid=False, fraud=True)
        ++> Order(label="D3", amount=7.00, valid=True);

    out = _run_walk([]);

    assert "SKIP D1: invalid order, continuing" in out, f"missing D1 skip: {out}";
    assert "HALT on D2: fraud flag set, aborting audit" in out, f"fraud must win over invalid: {out}";
    assert "AUDIT D3" not in out, f"D3 must not be reached after fraud halt: {out}";
}


test "mixed chain exercises both early returns in the documented order" {
