    assert "AUDIT ORD-001: amount=120.50" in out, f"missing ORD-001 audit: {out}";
    assert "SKIP ORD-002: invalid order, continuing" in out, f"missing ORD-002 skip: {out}";
    assert "AUDIT ORD-003: amount=45.75" in out, f"missing ORD-003 audit after skip: {out}";
    assert "HALT on ORD-004: fraud flag set, aborting audit" in out, f"missing ORD-004 halt: {out}";
    assert "AUDIT ORD-005" not in out, f"ORD-005 must not be reached after fraud: {out}";

