"""Order auditor: skip invalid orders but halt the walk on fraud.

Demonstrates two flavors of early-return side by side:
  - ``continue`` semantics for invalid orders (skip this node, keep walking).
  - ``disengage`` semantics for fraud-flagged orders (halt the whole walk).
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning audit walk");
        visit [-->];
