    can audit with Order entry {
        if here.fraud {
            print(f"[HALT]   fraud detected on {here.label} "
                  f"(${here.amount}); disengaging walk");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP]   {here.label} invalid; "
                  f"continuing to next order");
            visit [-->];
        }
        print(f"[OK]     {here.label} cleared (${here.amount})");
        visit [-->];
    }
}

with entry {
