"""Restaurant recommender: model restaurants as nodes and use a finder walker parameterized by minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
    has available: bool = True;
}

walker Finder {
    has min_rating: float = 0.0;

    can start with Root entry {
