"""Regression tests for OrderAuditor: skip-invalid vs halt-on-fraud."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: invalid order is skipped, walk continues ----------
test "invalid order skipped, walk continues to later orders" {
    root ++> Order(title="Inv-1", amount=50.0, valid=False)
        ++> Order(title="Ok-1", amount=10.0)
        ++> Order(title="Ok-2", amount=20.0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[SKIP] Invalid order 'Inv-1' ($50.0) - continuing" in out, f"missing SKIP line: {out}";
    assert "[OK] Audited order 'Ok-1' ($10.0)" in out, f"walk did not continue after skip: {out}";
    assert "[OK] Audited order 'Ok-2' ($20.0)" in out, f"later order not reached: {out}";
    assert "Beginning order audit" in out, f"missing start banner: {out}";
    # Skip must NOT halt the walk.
    assert "[HALT]" not in out, f"unexpected HALT on skip-only run: {out}";
}

# ---------- Test 2: fraud-flagged order disengages the whole walk ----------
test "fraud order disengages the walk immediately" {
    root ++> Order(title="Ok-Before", amount=11.0)
        ++> Order(title="Fraud-1", amount=999.0, fraud=True)
        ++> Order(title="Ok-After", amount=22.0)
        ++> Order(title="Should-Never-Audit", amount=33.0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[HALT] Fraud detected on order 'Fraud-1' ($999.0) - audit aborted" in out, f"missing HALT line: {out}";
    # The order immediately preceding the fraud order is still audited
    # because the walker visits it before reaching the fraud node.
    assert "[OK] Audited order 'Ok-Before' ($11.0)" in out, f"pre-fraud order not audited: {out}";
    # Anything after the fraud node must NOT appear -- disengage halts the walk.
    assert "Ok-After" not in out, f"walk continued past HALT (Ok-After): {out}";
    assert "Should-Never-Audit" not in out, f"walk continued past HALT (Should-Never-Audit): {out}";
    # Fraud node itself is HALT-printed, not OK-printed, not SKIP-printed.
    assert "[OK] Audited order 'Fraud-1'" not in out, f"fraud order audited instead of halted: {out}";
    assert "[SKIP]" not in out, f"unexpected SKIP on fraud-only run: {out}";
}

# ---------- Test 3: skip-then-fraud shows correct ordering ----------
test "skip before fraud still halts on fraud" {
    root ++> Order(title="Skip-1", amount=5.0, valid=False)
        ++> Order(title="Ok-1", amount=15.0)
        ++> Order(title="Fraud-X", amount=500.0, fraud=True)
        ++> Order(title="Later-1", amount=25.0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    skip_pos = out.find("[SKIP] Invalid order 'Skip-1'");
    ok_pos = out.find("[OK] Audited order 'Ok-1'");
    halt_pos = out.find("[HALT] Fraud detected on order 'Fraud-X'");
    assert skip_pos >= 0, f"missing SKIP for Skip-1: {out}";
    assert ok_pos >= 0, f"missing OK for Ok-1: {out}";
    assert halt_pos >= 0, f"missing HALT for Fraud-X: {out}";
    assert skip_pos < ok_pos < halt_pos, f"wrong order of events: skip={skip_pos} ok={ok_pos} halt={halt_pos} in {out}";
    # Anything beyond Fraud-X is unreachable.
    assert "Later-1" not in out, f"walk continued past HALT: {out}";
}

# ---------- Test 4: all-valid, no-fraud baseline ----------
test "clean orders all audited with no halt or skip" {
    root ++> Order(title="Clean-A", amount=1.0)
        ++> Order(title="Clean-B", amount=2.0)
        ++> Order(title="Clean-C", amount=3.0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[OK] Audited order 'Clean-A' ($1.0)" in out, f"missing Clean-A: {out}";
    assert "[OK] Audited order 'Clean-B' ($2.0)" in out, f"missing Clean-B: {out}";
    assert "[OK] Audited order 'Clean-C' ($3.0)" in out, f"missing Clean-C: {out}";
    assert "[HALT]" not in out, f"unexpected HALT on clean run: {out}";
    assert "[SKIP]" not in out, f"unexpected SKIP on clean run: {out}";
}

# ---------- Test 5: fraud as the very first order halts before any audit ----------
test "fraud on first order halts before any [OK] is printed" {
    root ++> Order(title="First-Fraud", amount=42.0, fraud=True)
        ++> Order(title="Never-Audited", amount=7.0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[HALT] Fraud detected on order 'First-Fraud' ($42.0) - audit aborted" in out, f"missing HALT: {out}";
    assert "Never-Audited" not in out, f"walk reached node after first-order HALT: {out}";
    assert "[OK]" not in out, f"unexpected [OK] when first order is fraud: {out}";
    assert "[SKIP]" not in out, f"unexpected [SKIP] when first order is fraud: {out}";
}

