"""Tests for OrderAuditor: skip vs disengage early-return flavors."""

import io;
import from contextlib { redirect_stdout }

test "fraud halts walk immediately and skips remaining orders" {
    buf = io.StringIO();
    o1 = Order(title="Order-001", amount=120.50, valid=True);
    o2 = Order(title="Order-002", amount=45.00, valid=False);
