"""Order auditor: invalid orders are skipped, fraud orders halt the walk."""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print(f"Auditor starting sweep");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flag on order {here.label} (amount={here.amount}) — disengaging");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP] invalid order {here.label} — continuing");
            visit [-->];
            return;
        }
        print(f"[OK] order {here.label} amount={here.amount}");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="A", amount=120.0)
        ++> Order(label="B", amount=80.0, valid=False)
        ++> Order(label="C", amount=250.0)
        ++> Order(label="D", amount=60.0, fraud=True)
        ++> Order(label="E", amount=40.0);

    root spawn OrderAuditor();
}
