"""Order auditor demonstrating both early-return flavors side by side.

Invalid orders are *skipped* (the walker moves on), but a fraud-flagged
order *halts* the entire walk via `disengage;`.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting order audit");
        visit [-->];
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALT-FRAUD";
        } elif not here.valid {
            action = "SKIP-INVALID";
        } else {
            action = "OK";
        }
        print(f"[{action}] {here.title} amount={here.amount}");
        if here.fraud {
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> Order(title="Order-001", amount=120.50)
        ++> Order(title="Order-002", amount=80.00, valid=False)
        ++> Order(title="Order-003", amount=45.25)
        ++> Order(title="Order-004", amount=999.99, fraud=True)
        ++> Order(title="Order-005", amount=10.00);
    root spawn OrderAuditor();
}
