"""Tests for the OrderAuditor walker: skip vs. halt early-return behavior."""

import io;
import from contextlib { redirect_stdout }

test "invalid order is skipped and audit continues" {
    root ++> Order(title="B-2001", amount=50.00, valid=True)
        ++> Order(title="B-2002", amount=10.00, valid=False)
        ++> Order(title="B-2003", amount=75.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # The invalid order must produce a SKIP line
    assert "[SKIP] invalid order 'B-2002'" in out, f"expected skip line, got: {out}";
    # Audit must continue after the skip — later valid orders still produce OK lines
    assert "[OK]   'B-2001' amount=$50.0" in out, f"pre-skip OK missing: {out}";
    assert "[OK]   'B-2003' amount=$75.0" in out, f"post-skip OK missing — audit did not continue: {out}";
    # No halt should fire on this graph
    assert "[HALT]" not in out, f"unexpected halt in skip-only graph: {out}";
}

test "fraud order halts the walk immediately via disengage" {
    root ++> Order(title="C-3001", amount=10.00, valid=True)
        ++> Order(title="C-3002", amount=200.00, valid=True, fraud=True)
        ++> Order(title="C-3003", amount=300.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # The fraud order must produce a HALT line
    assert "[HALT] fraud flagged on 'C-3002'" in out, f"expected halt line, got: {out}";
    # The order BEFORE the fraud one must have been audited (reached, not skipped silently)
    assert "[OK]   'C-3001' amount=$10.0" in out, f"pre-halt OK missing: {out}";
    # CRITICAL: orders AFTER the fraud one must NOT be audited — disengage stops the walk
    assert "C-3003" not in out, f"walk continued past halt — disengage failed: {out}";
    assert "[OK]   'C-3003'" not in out, f"post-halt order audited: {out}";
    # No skip should fire here (all non-fraud orders are valid)
    assert "[SKIP]" not in out, f"unexpected skip on all-valid fraud graph: {out}";
}

test "fraud halts even when encountered after some skips" {
    root ++> Order(title="D-4001", amount=5.00, valid=False)
        ++> Order(title="D-4002", amount=15.00, valid=True)
        ++> Order(title="D-4003", amount=0.00, valid=False)
        ++> Order(title="D-4004", amount=999.00, valid=True, fraud=True)
        ++> Order(title="D-4005", amount=42.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Both skips must be reported (audit continues past them)
    assert "[SKIP] invalid order 'D-4001'" in out, f"first skip missing: {out}";
    assert "[SKIP] invalid order 'D-4003'" in out, f"second skip missing: {out}";
    # The valid order between skips must have been audited
    assert "[OK]   'D-4002' amount=$15.0" in out, f"intervening OK missing: {out}";
    # The halt fires on the fraud order
    assert "[HALT] fraud flagged on 'D-4004'" in out, f"halt missing: {out}";
    # The post-halt order is unreachable
    assert "D-4005" not in out, f"walk continued past halt after skips: {out}";
}

test "all-valid no-fraud graph produces only OK lines and audit begin" {
    root ++> Order(title="E-5001", amount=1.00, valid=True)
        ++> Order(title="E-5002", amount=2.00, valid=True)
        ++> Order(title="E-5003", amount=3.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Begin banner is printed from the Root entry ability
    assert "Order audit begin" in out, f"begin banner missing: {out}";
    # Every order is audited with an OK line
    assert "[OK]   'E-5001' amount=$1.0" in out, f"E-5001 missing: {out}";
    assert "[OK]   'E-5002' amount=$2.0" in out, f"E-5002 missing: {out}";
    assert "[OK]   'E-5003' amount=$3.0" in out, f"E-5003 missing: {out}";
    # Neither skip nor halt fires on a clean graph
    assert "[SKIP]" not in out, f"unexpected skip on clean graph: {out}";
    assert "[HALT]" not in out, f"unexpected halt on clean graph: {out}";
    # OK count matches the number of orders audited
    assert out.count("[OK]") == 3, f"expected 3 OK lines, got {out.count('[OK]')} in: {out}";
}

test "fraud as the very first order halts before any audit line" {
    root ++> Order(title="F-6001", amount=500.00, valid=True, fraud=True)
        ++> Order(title="F-6002", amount=600.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # The halt fires on the first order visited
    assert "[HALT] fraud flagged on 'F-6001'" in out, f"halt missing on first order: {out}";
    # No OK line is possible before the halt
    assert "[OK]" not in out, f"OK line appeared before halt on first order: {out}";
    # Subsequent orders are never reached
    assert "F-6002" not in out, f"walk reached order past first-order halt: {out}";
}

