"""Tiny dungeon crawler: chained room nodes with a treasure vault and a hunter walker."""

node Room {
    has name: str = "";
    has is_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can explore with Room entry {
        self.rooms_checked += 1;
        print(f"Hunter enters {here.name} (rooms seen: {self.rooms_checked})");
        if here.is_treasure {
            print(f"Treasure found in {here.name}! Search ends.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", is_treasure=True);
    forbidden = Room(name="Forbidden Crypt");

    root ++> entrance ++> hallway ++> armory ++> vault ++> forbidden;

    root spawn Hunter();
}
```

jac_tests:
"""Tests for the dungeon crawler Hunter walker."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Hunter visits rooms in order, counts them, and disengages at the
# treasure room — rooms AFTER the vault must never be visited.
# ---------------------------------------------------------------------------
test "hunter stops at treasure and never visits post-vault rooms" {
    entrance = Room(name="Entrance");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", is_treasure=True);
    forbidden = Room(name="Forbidden Crypt");

    root ++> entrance ++> hallway ++> armory ++> vault ++> forbidden;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # Treasure room message must appear (so we did reach the vault).
    assert "Treasure found in Vault" in out, f"treasure not announced: {out!r}";
    # Forbidden room must NEVER appear in output (post-vault visit = bug).
    assert "Forbidden Crypt" not in out, f"post-vault room was visited: {out!r}";
    # The four pre-vault + vault rooms must each be entered exactly once.
    assert "Hunter enters Entrance" in out, f"entrance missing: {out!r}";
    assert "Hunter enters Hallway" in out, f"hallway missing: {out!r}";
    assert "Hunter enters Armory" in out, f"armory missing: {out!r}";
    assert "Hunter enters Vault" in out, f"vault missing: {out!r}";
    # Count: 4 rooms entered (Entrance, Hallway, Armory, Vault).
    assert res.rooms_checked == 4, f"expected 4 rooms checked, got {res.rooms_checked}";
}

# ---------------------------------------------------------------------------
# Test 2: When the FIRST room is the treasure, no further rooms are visited.
# ---------------------------------------------------------------------------
test "hunter disengages immediately if first room is treasure" {
    treasure = Room(name="Immediate Vault", is_treasure=True);
    later_a = Room(name="Later A");
    later_b = Room(name="Later B");

    root ++> treasure ++> later_a ++> later_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Treasure found in Immediate Vault" in out, f"no treasure msg: {out!r}";
    assert "Later A" not in out, f"Later A should not be visited: {out!r}";
    assert "Later B" not in out, f"Later B should not be visited: {out!r}";
    assert res.rooms_checked == 1, f"expected 1 room checked, got {res.rooms_checked}";
}

# ---------------------------------------------------------------------------
# Test 3: When NO room holds treasure, hunter must traverse the entire chain
# (no premature disengage) and count every room.
# ---------------------------------------------------------------------------
test "hunter traverses all rooms when no treasure exists" {
    a = Room(name="A");
    b = Room(name="B");
    c = Room(name="C");
    d = Room(name="D");

    root ++> a ++> b ++> c ++> d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    for n in ["A", "B", "C", "D"] {
        assert f"Hunter enters {n}" in out, f"room {n} not visited: {out!r}";
    }
    assert "Treasure found" not in out, f"false treasure announcement: {out!r}";
    assert res.rooms_checked == 4, f"expected 4 rooms, got {res.rooms_checked}";
}

# ---------------------------------------------------------------------------
# Test 4: Counter increments monotonically and matches the printed sequence.
# ---------------------------------------------------------------------------
test "rooms_checked counter reflects sequential entry" {
    r1 = Room(name="Room-1");
    r2 = Room(name="Room-2");
    r3 = Room(name="Room-3");
    r4 = Room(name="Room-4");
    r5 = Room(name="Room-5", is_treasure=True);

    root ++> r1 ++> r2 ++> r3 ++> r4 ++> r5;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "rooms seen: 1" in out, f"counter missing 1: {out!r}";
    assert "rooms seen: 2" in out, f"counter missing 2: {out!r}";
    assert "rooms seen: 3" in out, f"counter missing 3: {out!r}";
    assert "rooms seen: 4" in out, f"counter missing 4: {out!r}";
    assert "rooms seen: 5" in out, f"counter missing 5: {out!r}";
    assert res.rooms_checked == 5, f"expected 5, got {res.rooms_checked}";
}

# ---------------------------------------------------------------------------
# Test 5: Only the FIRST treasure encountered stops the walk — if a later
# room also had is_treasure it must remain unseen because disengage fired.
# ---------------------------------------------------------------------------
test "disengage stops walk before any second treasure room" {
    first_treasure = Room(name="FirstVault", is_treasure=True);
    second_treasure = Room(name="SecondVault", is_treasure=True);
    bonus = Room(name="BonusRoom");

    root ++> first_treasure ++> bonus ++> second_treasure;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    assert "Treasure found in FirstVault" in out, f"first treasure missed: {out!r}";
    assert "BonusRoom" not in out, f"BonusRoom visited after disengage: {out!r}";
    assert "SecondVault" not in out, f"SecondVault visited after disengage: {out!r}";
    assert res.rooms_checked == 1, f"expected 1 room, got {res.rooms_checked}";
}

