"""Restaurant recommender: walker finds spots meeting a minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 4.5;
    has matches: list = [];

    can start with Root entry {
        visit [-->];
    }

    can scout with Restaurant entry {
        if here.rating >= self.min_rating {
            self.matches.append(here);
        }
        visit [-->];
    }

    can summarize with Root exit {
        print(f"Matches at {self.min_rating}+ ({len(self.matches)} found):");
        for r in self.matches {
            print(f"  - {r.name} ({r.cuisine}) rated {r.rating}");
        }
        report self.matches;
    }
}

