"""Order auditor: skip invalid orders but halt the walk on fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has flagged_fraud: bool = False;
}

walker Auditor {
    can start with Root entry {
        print("Audit begins");
