    }

    can audit with Order entry {
        if here.flagged_fraud {
            print(f"HALT on fraud: amount={here.amount}");
            disengage;
        }
        if not here.valid {
            print(f"SKIP invalid: amount={here.amount}");
            visit [-->] else { disengage; };
        }
        print(f"AUDIT ok: amount={here.amount}");
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Order(amount=120.0)
        ++> Order(amount=45.5, valid=False)
        ++> Order(amount=999.0, flagged_fraud=True)
        ++> Order(amount=75.0);
    root spawn Auditor();
}
