"""Dungeon crawler: chain of rooms where one hides the treasure.

A Hunter walker descends the corridor room by room, counting how many
rooms it has inspected. As soon as it enters the vault, the search
terminates immediately — no rooms past the treasure are ever visited.
"""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->] else { disengage; }
    }

    can search with Room entry {
        self.rooms_inspected += 1;
        if here.has_treasure {
            print(f"Treasure found in '{here.name}' after inspecting {self.rooms_inspected} room(s)! Hunter stops.");
            disengage;
        }
        print(f"'{here.name}' is empty ({self.rooms_inspected} inspected so far).");
        visit [-->] else { disengage; }
    }
}

with entry {
    entry_room = Room(name="Entry");
    hallway = Room(name="Hallway");
    armory = Room(name="Armory");
    vault = Room(name="Vault", has_treasure=True);
    forbidden = Room(name="Forbidden Sanctum");

    root ++> entry_room
        ++> hallway
        ++> armory
        ++> vault
        ++> forbidden;

    root spawn Hunter();
}
