```jac
"""Order auditor: skip invalid but halt on fraud.

Two early-return flavors live side by side in the same walk:

* Invalid orders are skipped: the walker moves on to the next sibling.
* Fraud-flagged orders halt the entire audit: every later order is
  ignored via ``disengage``.

Every order prints one line naming the action that fired for it.
"""

node Order {
    has title: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor beginning walk");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "FRAUD_HALT";
            print(f"[{action}] {here.title} (${here.amount}) — halting walk");
            disengage;
        } elif not here.valid {
            action = "SKIP";
            print(f"[{action}] {here.title} (${here.amount}) — invalid, continuing");
            visit [-->] else { disengage; }
        } else {
            action = "AUDIT_OK";
            print(f"[{action}] {here.title} (${here.amount}) — clean");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(title="Order-001", amount=120.50)
        ++> Order(title="Order-002", amount=89.99, valid=False)
        ++> Order(title="Order-003", amount=45.00)
        ++> Order(title="Order-004", amount=999.99, fraud=True)
        ++> Order(title="Order-005", amount=250.00);
    root spawn OrderAuditor();
}
```

