"""Order auditor: demonstrates 'skip and continue' vs 'halt on the spot'.

Invalid orders are skipped (the walker advances to the next order), but a
fraud-flagged order halts the entire walk immediately. Every order prints
exactly one line describing the action that fired for it.
"""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has is_valid: bool = True;
    has is_fraud: bool = False;
}

walker OrderAuditor {
    has audit_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        action = "";
        if here.is_fraud {
            action = f"HALT: fraud detected on {here.order_id} (${here.amount})";
            self.audit_log.append(action);
            print(action);
            disengage;
        } elif not here.is_valid {
            action = f"SKIP: invalid order {here.order_id} (${here.amount})";
            self.audit_log.append(action);
            print(action);
            visit [-->] else { disengage; };
        } else {
            action = f"OK:   cleared {here.order_id} (${here.amount})";
            self.audit_log.append(action);
            print(action);
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    root ++> Order(order_id="A-1", amount=120.50, is_valid=True, is_fraud=False)
        ++> Order(order_id="A-2", amount=45.00, is_valid=False, is_fraud=False)
        ++> Order(order_id="A-3", amount=999.99, is_valid=True, is_fraud=True)
        ++> Order(order_id="A-4", amount=60.00, is_valid=True, is_fraud=False);

    auditor = OrderAuditor();
    root spawn auditor;

    print("--- audit summary ---");
    for entry in auditor.audit_log {
        print(entry);
    }
}
