        ++> Order(order_id="S-3", amount=30.0, is_valid=True, is_fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "OK:   cleared S-1 ($10.0)" in out, f"missing S-1 OK line: {out!r}";
    assert "SKIP: invalid order S-2 ($20.0)" in out, f"missing S-2 SKIP line: {out!r}";
    assert "OK:   cleared S-3 ($30.0)" in out, f"S-3 should still be audited after skip: {out!r}";
    assert "HALT" not in out, f"no fraud here, should not halt: {out!r}";

    assert len(res.audit_log) == 3, f"expected 3 log entries, got {len(res.audit_log)}: {res.audit_log}";
    assert "S-3" in res.audit_log[2], f"third log entry should mention S-3: {res.audit_log}";
}

test "fraud order halts the walk immediately" {
    root ++> Order(order_id="F-1", amount=50.0, is_valid=True, is_fraud=False)
        ++> Order(order_id="F-2", amount=75.0, is_valid=True, is_fraud=True)
        ++> Order(order_id="F-3", amount=100.0, is_valid=True, is_fraud=False)
        ++> Order(order_id="F-4", amount=200.0, is_valid=True, is_fraud=False);

