    assert "HALT: fraud detected on F-2 ($75.0)" in out, f"fraud line missing: {out!r}";

    # F-3 and F-4 must never be visited after the halt.
    assert "F-3" not in out, f"F-3 should not be visited after halt: {out!r}";
    assert "F-4" not in out, f"F-4 should not be visited after halt: {out!r}";
    assert "SKIP" not in out, f"no invalid orders, no skip lines: {out!r}";

    assert len(res.audit_log) == 2, f"expected exactly 2 log entries (F-1, F-2), got {len(res.audit_log)}: {res.audit_log}";
