    assert "Z-2" not in out, f"Z-2 must not be visited when first order is fraud: {out!r}";

    assert len(res.audit_log) == 1, f"expected 1 log entry, got {len(res.audit_log)}: {res.audit_log}";
}

test "invalid order followed by fraud: skip first, then halt" {
    root ++> Order(order_id="M-1", amount=11.0, is_valid=True, is_fraud=False)
        ++> Order(order_id="M-2", amount=22.0, is_valid=False, is_fraud=False)
        ++> Order(order_id="M-3", amount=33.0, is_valid=True, is_fraud=True)
