"""Tiny dungeon crawler with a hunter walker that bails out at the treasure."""

node Room {
    has title: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can search with Room entry {
        self.rooms_checked += 1;
        if here.has_treasure {
            print(f"Found the treasure in '{here.title}' after checking {self.rooms_checked} room(s). Hunt over.");
            disengage;
        }
        print(f"Checked '{here.title}' — empty.");
        visit [-->];
    }
}

with entry {
    root ++> Room(title="Antechamber")
        ++> Room(title="Mossy Hall")
        ++> Room(title="Burial Crypt")
        ++> Room(title="Treasure Vault", has_treasure=True)
        ++> Room(title="Forbidden Wing")
        ++> Room(title="Dragon's Lair");

    root spawn Hunter();
}
