test "hunter bails out at the treasure room and never visits beyond it" {
    root ++> Room(title="Antechamber")
        ++> Room(title="Mossy Hall")
        ++> Room(title="Burial Crypt")
        ++> Room(title="Treasure Vault", has_treasure=True)
