    assert "Treasure Vault" in out, f"expected treasure room title, got: {out}";

    # Rooms beyond the vault must NEVER appear in output.
    assert "Forbidden Wing" not in out, f"hunter must not visit past the vault: {out}";
    assert "Dragon's Lair" not in out, f"hunter must not visit past the vault: {out}";

