    assert "Antechamber" in out, f"anted to visit antechamber: {out}";
    assert "Mossy Hall" in out, f"anted to visit mossy hall: {out}";
    assert "Burial Crypt" in out, f"anted to visit burial crypt: {out}";

    # Counter must reflect: 3 empty rooms + 1 treasure room = 4.
    assert res.rooms_checked == 4, f"expected 4 rooms checked, got {res.rooms_checked}";
}

test "hunter never reaches treasure when none exists and walks the full chain" {
    root ++> Room(title="Hall A")
        ++> Room(title="Hall B")
        ++> Room(title="Hall C");

