}

test "treasure in the very first room terminates after exactly one visit" {
    root ++> Room(title="Treasure Room", has_treasure=True)
        ++> Room(title="Hallway")
        ++> Room(title="Cellar")
        ++> Room(title="Throne");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

