test "fan-out dungeon with treasure on one branch terminates that branch only" {
    # Build a root with three branches; only the middle branch contains treasure.
    root ++> Room(title="Empty A");
    root ++> Room(title="Empty B1");
    root ++> Room(title="Treasure Branch", has_treasure=True);
    root ++> Room(title="Empty C");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hunter();
    }
    out = buf.getvalue();

    # The treasure room must have been announced.
    assert "Found the treasure" in out, f"expected treasure announcement: {out}";

    # Count occurrences of "Checked" vs "Found the treasure" — there must be
    # exactly one treasure announcement and a small number of empty checks.
    checked_count = out.count("Checked ");
    found_count = out.count("Found the treasure");
    assert found_count == 1, f"treasure must be announced exactly once, got {found_count}: {out}";
