```jac
"""Order auditor: demonstrate skip-continue vs halt-disengage side by side.

Each Order node carries an amount, a validity flag, and a fraud flag.
The OrderAuditor walker visits orders via typed `Next` edges. Invalid
orders are skipped (the audit continues forward); flagged-fraud orders
halt the entire walk immediately.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

edge Next {
    has seq: int = 0;
}

walker OrderAuditor {
    has audited: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print("OrderAuditor: beginning walk");
        visit [-->];
    }

    can audit with Order entry {
        self.audited += 1;

        # Fraud flag -> HALT the whole walk on the spot.
        if here.fraud {
            self.halted = True;
            print(f"[HALT]   {here.label} (amount={here.amount}) flagged as fraud -> disengaging");
            disengage;
        }

        # Invalid order -> SKIP this one, keep walking forward.
        if not here.valid {
            print(f"[SKIP]   {here.label} (amount={here.amount}) invalid -> continuing");
            visit [-->];
            return;
        }

        # Normal order -> record it and move on.
        print(f"[AUDIT]  {here.label} (amount={here.amount}) ok");
        visit [-->];
    }
}

with entry {
    # Build a chain of orders connected by typed `Next` edges.
    a = Order(label="ORD-001", amount=120.50, valid=True);
    b = Order(label="ORD-002", amount=80.00, valid=False);
    c = Order(label="ORD-003", amount=250.75, valid=True);
    d = Order(label="ORD-004", amount=999.99, valid=True);
    e = Order(label="ORD-005", amount=45.00, fraud=True);

    root +>:Next(seq=1):+> a
         +>:Next(seq=2):+> b
         +>:Next(seq=3):+> c
         +>:Next(seq=4):+> d
         +>:Next(seq=5):+> e;

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"");
    print(f"audited={auditor.audited} halted={auditor.halted}");
}
```

jac_tests:
"""Test annex for the OrderAuditor walker.

Verifies both early-return flavors in the same walk:
- SKIP-continue: invalid orders are recorded but traversal continues.
- HALT-disengage: a fraud order stops the walk immediately.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. Skip path: invalid order is skipped, walk continues past it.
# ---------------------------------------------------------------------------
test "skip continues past invalid order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        a = Order(label="A-OK", amount=10.00, valid=True);
        b = Order(label="B-INV", amount=20.00, valid=False);
        c = Order(label="C-OK", amount=30.00, valid=True);
        root +>:Next(seq=1):+> a
             +>:Next(seq=2):+> b
             +>:Next(seq=3):+> c;

        auditor = OrderAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    # The skip branch must fire on B.
    assert "[SKIP]   B-INV" in out, f"expected SKIP line for B-INV in:\n{out}";
    # The audit branch must fire on the surrounding valid orders.
    assert "[AUDIT]  A-OK" in out, f"expected AUDIT line for A-OK in:\n{out}";
    assert "[AUDIT]  C-OK" in out, f"expected AUDIT line for C-OK in:\n{out}";
    # No halt and no fraud line on this scenario.
    assert "[HALT]" not in out, f"unexpected HALT line in:\n{out}";
    assert "flagged as fraud" not in out, f"unexpected fraud note in:\n{out}";
}

# ---------------------------------------------------------------------------
# 2. Halt path: fraud order disengages the walk on the spot.
# ---------------------------------------------------------------------------
test "fraud halts the entire walk immediately" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        a = Order(label="A-OK", amount=10.00, valid=True);
        b = Order(label="B-FRAUD", amount=50.00, fraud=True);
        c = Order(label="C-OK", amount=30.00, valid=True);
        root +>:Next(seq=1):+> a
             +>:Next(seq=2):+> b
             +>:Next(seq=3):+> c;

        auditor = OrderAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    # HALT line must appear for B-FRAUD.
    assert "[HALT]   B-FRAUD" in out, f"expected HALT line for B-FRAUD in:\n{out}";
    assert "flagged as fraud" in out, f"expected fraud note in:\n{out}";
    # The order AFTER the fraud order must never be audited.
    assert "C-OK" not in out, f"C-OK should not appear after disengage:\n{out}";
    # HALT also wins over the normal AUDIT label for the fraud order itself.
    assert "[AUDIT]  B-FRAUD" not in out, f"fraud order must not also AUDIT:\n{out}";
}

# ---------------------------------------------------------------------------
# 3. Order of events: SKIP before HALT when both kinds occur on one walk.
# ---------------------------------------------------------------------------
test "skip and halt in correct order in one walk" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        a = Order(label="A-OK", amount=10.00, valid=True);
        b = Order(label="B-INV", amount=20.00, valid=False);
        c = Order(label="C-OK", amount=30.00, valid=True);
        d = Order(label="D-FRAUD", amount=40.00, fraud=True);
        e = Order(label="E-OK", amount=50.00, valid=True);
        root +>:Next(seq=1):+> a
             +>:Next(seq=2):+> b
             +>:Next(seq=3):+> c
             +>:Next(seq=4):+> d
             +>:Next(seq=5):+> e;

        auditor = OrderAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    a_pos = out.find("A-OK");
    b_pos = out.find("[SKIP]   B-INV");
    c_pos = out.find("[AUDIT]  C-OK");
    d_pos = out.find("[HALT]   D-FRAUD");
    e_pos = out.find("E-OK");

    assert a_pos > -1, f"missing A-OK in:\n{out}";
    assert b_pos > a_pos, f"SKIP should come after A-OK audit:\n{out}";
    assert c_pos > b_pos, f"C-OK audit should come after the SKIP:\n{out}";
    assert d_pos > c_pos, f"HALT should come after C-OK audit:\n{out}";
    # Order following the fraud node must be untouched.
    assert e_pos == -1, f"E-OK must not appear after HALT:\n{out}";
}

# ---------------------------------------------------------------------------
# 4. Skip-then-fraud: invalid order is skipped, then the next fraud order halts.
# ---------------------------------------------------------------------------
test "invalid followed by fraud still halts after the skip" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        x = Order(label="X-INV", amount=5.00, valid=False);
        y = Order(label="Y-FRAUD", amount=99.00, fraud=True);
        z = Order(label="Z-OK", amount=10.00, valid=True);
        root +>:Next(seq=1):+> x
             +>:Next(seq=2):+> y
             +>:Next(seq=3):+> z;

        auditor = OrderAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[SKIP]   X-INV" in out, f"expected SKIP for X-INV in:\n{out}";
    assert "[HALT]   Y-FRAUD" in out, f"expected HALT for Y-FRAUD in:\n{out}";
    # Z must never be visited because Y halts before we can reach it.
    assert "Z-OK" not in out, f"Z-OK should never be reached after HALT:\n{out}";
}

# ---------------------------------------------------------------------------
# 5. Pure happy path: nothing invalid, nothing fraudulent -> all audited.
# ---------------------------------------------------------------------------
test "all valid non-fraud orders are audited in sequence" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        a = Order(label="P-OK", amount=1.00, valid=True);
        b = Order(label="Q-OK", amount=2.00, valid=True);
        c = Order(label="R-OK", amount=3.00, valid=True);
        root +>:Next(seq=1):+> a
             +>:Next(seq=2):+> b
             +>:Next(seq=3):+> c;

        auditor = OrderAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[AUDIT]  P-OK" in out, f"missing P-OK in:\n{out}";
    assert "[AUDIT]  Q-OK" in out, f"missing Q-OK in:\n{out}";
    assert "[AUDIT]  R-OK" in out, f"missing R-OK in:\n{out}";
    assert "[SKIP]" not in out, f"unexpected SKIP on happy path:\n{out}";
    assert "[HALT]" not in out, f"unexpected HALT on happy path:\n{out}";
}

