"""Tests for OrderAuditor: skip-invalid vs halt-on-fraud semantics."""

import io;
import from contextlib { redirect_stdout }

def _capture_audit(order_specs: list) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        chain = Order(label=order_specs[0]["label"],
                      amount=order_specs[0]["amount"],
                      valid=order_specs[0]["valid"],
                      fraud_flag=order_specs[0]["fraud_flag"]);
        rt ++> chain;
        for i in range(1, len(order_specs)) {
            spec = order_specs[i];
            nxt = Order(label=spec["label"],
                        amount=spec["amount"],
                        valid=spec["valid"],
                        fraud_flag=spec["fraud_flag"]);
            chain ++> nxt;
            chain = nxt;
        }
        auditor = OrderAuditor();
        res = rt spawn auditor;
    }
    return (buf.getvalue(), res);
}

test "skip-invalid continues to later valid orders" {
