"""Warehouse stock take: walk the shelves and report per-item quantities."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total_units: int = 0;
    has min_shelf: int = -1;
    has seen: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can count with StockItem entry {
        shelf_label = f"{here.sku}={here.quantity}";
        report shelf_label;
        self.total_units += here.quantity;
        if not self.seen {
            self.min_shelf = here.quantity;
            self.seen = True;
        } else {
            self.min_shelf = self.min_shelf if self.min_shelf <= here.quantity else here.quantity;
        }
        visit [-->];
    }
}

with entry {
    shelf_a = StockItem(sku="A-001", quantity=12);
    shelf_b = StockItem(sku="B-014", quantity=5);
    shelf_c = StockItem(sku="C-220", quantity=27);
    root ++> shelf_a ++> shelf_b ++> shelf_c;

    result = root spawn Counter();
    for line in result.reports {
        print(line);
    }
    print(f"TOTAL_UNITS={result.total_units}");
    print(f"MIN_SHELF={result.min_shelf}");
}
