```jac
"""Order auditor: skip invalid orders but halt on any fraud-flagged one.

Orders are nodes carrying an amount, a validity flag, and a fraud flag.
The walker walks the order chain via plain ``-->`` edges. On every
order it prints exactly one line describing which action fired:

- ``SKIP``  -- the order is marked invalid; traversal continues.
- ``HALT``  -- the order is flagged for fraud; the walker disengages.
- ``OK``    -- the order is clean; traversal continues.

The "skip but keep going" behavior uses ``continue`` semantics: the
ability falls through and still issues ``visit [-->]``. The "halt now"
behavior uses ``disengage`` which terminates the entire walk.
"""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("OrderAuditor: beginning audit");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Order entry {
        action = "";
        if here.fraud_flag {
            action = "HALT";
            print(f"[{action}] amount={here.amount} fraud detected -- aborting walk");
            disengage;
        } elif not here.valid {
            action = "SKIP";
            print(f"[{action}] amount={here.amount} invalid -- continuing");
            visit [-->] else {
                disengage;
            }
        } else {
            action = "OK";
            print(f"[{action}] amount={here.amount} clean -- continuing");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    root ++> Order(amount=120.50, valid=True, fraud_flag=False)
        ++> Order(amount=9.99, valid=False, fraud_flag=False)
        ++> Order(amount=450.00, valid=True, fraud_flag=True)
        ++> Order(amount=75.00, valid=True, fraud_flag=False);

    root spawn OrderAuditor();
    print("OrderAuditor: done");
}
```

jac_tests:
"""Tests for the order auditor: skip invalid orders but halt on fraud-flagged ones."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Fraud-flagged order halts the entire walk immediately.
# ---------------------------------------------------------------------------
test "fraud flag halts walk immediately" {
    root ++> Order(amount=100.0, valid=True, fraud_flag=False)
        ++> Order(amount=200.0, valid=True, fraud_flag=True)
        ++> Order(amount=300.0, valid=True, fraud_flag=False)
        ++> Order(amount=400.0, valid=True, fraud_flag=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # The first clean order must be audited as OK.
    assert "[OK] amount=100.0 clean -- continuing" in out, f"expected first OK line, got: {out}";

    # The fraud order must be reported and the walk terminated.
    assert "[HALT] amount=200.0 fraud detected -- aborting walk" in out, f"expected HALT line, got: {out}";

    # Orders AFTER the fraud-flagged one must NOT appear in the output:
    # disengage stops the whole walk, so amounts 300.0 and 400.0 are silent.
    assert "amount=300.0" not in out, f"walk did not halt; later order appeared: {out}";
    assert "amount=400.0" not in out, f"walk did not halt; later order appeared: {out}";

    # Done marker still gets printed (it's after the spawn in main, but under
    # test we only care that the spawn finished — i.e. disengage returned
    # control rather than hanging the walker).
    assert "[SKIP]" not in out, f"no SKIP expected in this scenario, got: {out}";
}

# ---------------------------------------------------------------------------
# Test 2: Invalid orders are skipped (one line each) but traversal continues.
# ---------------------------------------------------------------------------
test "invalid orders are skipped but walk continues" {
    root ++> Order(amount=10.0, valid=True, fraud_flag=False)
        ++> Order(amount=20.0, valid=False, fraud_flag=False)
        ++> Order(amount=30.0, valid=True, fraud_flag=False)
        ++> Order(amount=40.0, valid=False, fraud_flag=False)
        ++> Order(amount=50.0, valid=True, fraud_flag=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Both invalid orders should produce SKIP lines in order.
    assert "[SKIP] amount=20.0 invalid -- continuing" in out, f"missing first SKIP: {out}";
    assert "[SKIP] amount=40.0 invalid -- continuing" in out, f"missing second SKIP: {out}";

    # All three valid orders should be reported as OK (skip keeps walking).
    assert "[OK] amount=10.0 clean -- continuing" in out, f"missing OK 10.0: {out}";
    assert "[OK] amount=30.0 clean -- continuing" in out, f"missing OK 30.0: {out}";
    assert "[OK] amount=50.0 clean -- continuing" in out, f"missing OK 50.0: {out}";

    # No fraud here -> no HALT line at all.
    assert "[HALT]" not in out, f"unexpected HALT line: {out}";

    # Each order should produce exactly one audit line.
    assert out.count("[OK]") == 3, f"expected 3 OK lines, got {out.count('[OK]')}: {out}";
    assert out.count("[SKIP]") == 2, f"expected 2 SKIP lines, got {out.count('[SKIP]')}: {out}";
}

# ---------------------------------------------------------------------------
# Test 3: A clean chain produces only OK lines, no skip/halt.
# ---------------------------------------------------------------------------
test "all-clean chain emits only OK lines" {
    root ++> Order(amount=1.0, valid=True, fraud_flag=False)
        ++> Order(amount=2.0, valid=True, fraud_flag=False)
        ++> Order(amount=3.0, valid=True, fraud_flag=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK] amount=1.0 clean -- continuing" in out, f"missing OK 1.0: {out}";
    assert "[OK] amount=2.0 clean -- continuing" in out, f"missing OK 2.0: {out}";
    assert "[OK] amount=3.0 clean -- continuing" in out, f"missing OK 3.0: {out}";

    assert "[SKIP]" not in out, f"unexpected SKIP: {out}";
    assert "[HALT]" not in out, f"unexpected HALT: {out}";
    assert out.count("[OK]") == 3, f"expected exactly 3 OK lines, got {out.count('[OK]')}: {out}";
}

# ---------------------------------------------------------------------------
# Test 4: Order of SKIP vs HALT lines — fraud takes priority over invalid.
# ---------------------------------------------------------------------------
test "fraud takes priority over invalid on the same order" {
    # An order that is BOTH invalid AND fraud-flagged must be treated as HALT,
    # not SKIP — fraud is the more severe signal and must win.
    root ++> Order(amount=999.0, valid=False, fraud_flag=True)
        ++> Order(amount=7.0, valid=True, fraud_flag=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # The combined order must be reported as HALT (fraud wins over invalid).
    assert "[HALT] amount=999.0 fraud detected -- aborting walk" in out, f"missing HALT for fraud+invalid order: {out}";
    assert "amount=999.0 invalid -- continuing" not in out, f"invalid branch fired on a fraud order: {out}";

    # Walk must terminate — the trailing clean order is never reached.
    assert "amount=7.0" not in out, f"walk did not halt at fraud; reached later order: {out}";

    # Exactly one audit line should be emitted.
    assert out.count("[HALT]") == 1, f"expected 1 HALT line, got {out.count('[HALT]')}: {out}";
}

# ---------------------------------------------------------------------------
# Test 5: Single fraud-only order — root message + one HALT line, nothing else.
# ---------------------------------------------------------------------------
test "lone fraud order emits only the halt line" {
    root ++> Order(amount=42.0, valid=True, fraud_flag=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Begin marker from the Root entry ability.
    assert "OrderAuditor: beginning audit" in out, f"missing begin marker: {out}";

    # Exactly the HALT line, no SKIP, no extra OK.
    assert "[HALT] amount=42.0 fraud detected -- aborting walk" in out, f"missing HALT line: {out}";
    assert "[SKIP]" not in out, f"unexpected SKIP: {out}";
    assert "[OK]" not in out, f"unexpected OK: {out}";
}

