"""Order auditor with both early-return flavors: `skip` for invalid orders
and `disengage` for fraud-flagged orders.

Walk the chain of Order nodes from Root. Print one line per order describing
which rule fired: SKIP, FRAUD, or OK.
"""

node Order {
    has label: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print(f"Auditor beginning walk from root");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[FRAUD] {here.label} (${here.amount}) — halting walk");
            disengage;
        }
        if not here.valid {
            print(f"[SKIP]  {here.label} (${here.amount}) — invalid, continuing");
            visit [-->];
        }
        print(f"[OK]    {here.label} (${here.amount})");
        visit [-->];
    }
}

with entry {
    root ++> Order(label="A-1001", amount=42.50)
        ++> Order(label="A-1002", amount=15.00, valid=False)
        ++> Order(label="A-1003", amount=99.99)
        ++> Order(label="A-1004", amount=250.00, fraud=True)
        ++> Order(label="A-1005", amount=7.25);
    root spawn OrderAuditor();
}
```

