"""Tests for the Order Auditor walker.

Verifies:
- `skip` flavor: invalid orders are reported but traversal continues.
- `disengage` flavor: fraud-flagged orders halt the walk entirely.
- Order output, defaults, and entry-point behavior.
"""

import io;
import from contextlib { redirect_stdout }


# ---------------------------------------------------------------------------
# Test 1: invalid order is skipped but audit continues to later orders
# ---------------------------------------------------------------------------
test "invalid order skipped audit continues" {
    root ++> Order(label="A-1001", amount=42.50)
        ++> Order(label="A-1002", amount=15.00, valid=False)
        ++> Order(label="A-1003", amount=99.99);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP]  A-1002 ($15.0) — invalid, continuing" in out, f"missing SKIP line: {out!r}";
    assert "[OK]    A-1001 ($42.5)" in out, f"missing first OK line: {out!r}";
    assert "[OK]    A-1003 ($99.99)" in out, f"skip did NOT continue to A-1003: {out!r}";
    assert "FRAUD" not in out, f"unexpected FRAUD on a clean chain: {out!r}";
    # SKIP line must appear before the final OK line — the walker must not
    # bail out on an invalid order.
    assert out.index("[SKIP]") < out.index("[OK]    A-1003"), f"order wrong: {out!r}";
}


# ---------------------------------------------------------------------------
# Test 2: fraud-flagged order disengages the walker — no later orders processed
# ---------------------------------------------------------------------------
test "fraud order disengages walk halts" {
    root ++> Order(label="A-1001", amount=42.50)
        ++> Order(label="A-1004", amount=250.00, fraud=True)
        ++> Order(label="A-1005", amount=7.25);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[FRAUD] A-1004 ($250.0) — halting walk" in out, f"missing FRAUD line: {out!r}";
    assert "[OK]    A-1001 ($42.5)" in out, f"pre-fraud order missing: {out!r}";
    # The orders AFTER the fraud one must NOT be visited — disengage stops the walk.
    assert "A-1005" not in out, f"disengage failed — post-fraud order A-1005 was visited: {out!r}";
    assert "7.25" not in out, f"disengage failed — A-1005 amount leaked into output: {out!r}";
    # The very next order after the fraud one is silently dropped.
    lines = [l for l in out.splitlines() if l.strip()];
    assert lines[-1].startswith("[FRAUD]"), f"FRAUD line should be last (walk halted): {lines!r}";
}


# ---------------------------------------------------------------------------
# Test 3: all-valid, no-fraud chain — every order prints OK
# ---------------------------------------------------------------------------
test "clean chain all orders print OK" {
    root ++> Order(label="B-1", amount=10.0)
        ++> Order(label="B-2", amount=20.0)
        ++> Order(label="B-3", amount=30.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    for lbl in ("B-1", "B-2", "B-3") {
        assert f"[OK]    {lbl}" in out, f"missing OK for {lbl}: {out!r}";
    }
    assert "SKIP" not in out, f"unexpected SKIP on clean chain: {out!r}";
    assert "FRAUD" not in out, f"unexpected FRAUD on clean chain: {out!r}";
    # Banner line comes first, orders follow in chain order.
    assert out.startswith("Auditor beginning walk from root"), f"missing banner: {out!r}";
    assert out.index("B-1") < out.index("B-2") < out.index("B-3"), f"wrong visit order: {out!r}";
}


# ---------------------------------------------------------------------------
# Test 4: default flags — fresh Order has valid=True and fraud=False
# ---------------------------------------------------------------------------
test "order defaults valid True fraud False" {
    o = Order(label="X", amount=1.0);
    assert o.valid == True, f"default valid should be True, got {o.valid}";
    assert o.fraud == False, f"default fraud should be False, got {o.fraud}";
    assert o.label == "X";
    assert o.amount == 1.0;

    # A default-built order in a chain should print OK (no SKIP, no FRAUD).
    root ++> Order(label="X");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[OK]    X" in out, f"default order should be OK: {out!r}";
    assert "SKIP" not in out and "FRAUD" not in out, f"unexpected action on default order: {out!r}";
}


# ---------------------------------------------------------------------------
# Test 5: skip interleaved with fraud — fraud must still halt, skip must still continue
# ---------------------------------------------------------------------------
test "skip then fraud fraud still halts" {
    # A → invalid (skip) → fraud (disengage) → never visited
    root ++> Order(label="S-1", amount=5.0, valid=False)
        ++> Order(label="F-1", amount=500.0, fraud=True)
        ++> Order(label="LATE", amount=1.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP]  S-1 ($5.0) — invalid, continuing" in out, f"missing SKIP for S-1: {out!r}";
    assert "[FRAUD] F-1 ($500.0) — halting walk" in out, f"missing FRAUD for F-1: {out!r}";
    assert "LATE" not in out, f"post-fraud order should not be visited: {out!r}";
    # Both flavor outputs must coexist in one walk.
    assert "SKIP" in out and "FRAUD" in out, f"both flavors should fire: {out!r}";
    # Skip line precedes the fraud line.
    assert out.index("[SKIP]") < out.index("[FRAUD]"), f"order wrong: {out!r}";
}

