"""Restaurant recommender: a finder walker that filters by minimum rating.

Spawned twice from root — once for date night (4.5+) and once for
casual lunch (3.5+) — and prints the matches from each pass.
"""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can recommend with Restaurant entry {
        if here.rating >= self.min_rating {
            print(f"[{here.rating}*] {here.name} ({here.cuisine})");
        }
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Petit Souffle", cuisine="French", rating=4.7)
        ++> Restaurant(name="Sakura Ramen", cuisine="Japanese", rating=4.2)
        ++> Restaurant(name="Taco Vista", cuisine="Mexican", rating=3.8)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2)
        ++> Restaurant(name="Verde Garden", cuisine="Vegetarian", rating=4.9);

    print("Date night picks (4.5+):");
    root spawn Finder(min_rating=4.5);
    print("Casual lunch picks (3.5+):");
    root spawn Finder(min_rating=3.5);
}
