"""Warehouse stock take: model shelves as nodes and sweep them with a counter walker."""

node Shelf {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    has total: int = 0;
    has smallest: int = 0;
    has initialized: bool = False;
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can count with Shelf entry {
        self.total = self.total + here.quantity;
        if not self.initialized {
            self.smallest = here.quantity;
            self.initialized = True;
        } else {
            self.smallest = here.quantity if here.quantity < self.smallest else self.smallest;
        }
        print(f"Shelf SKU={here.sku} quantity={here.quantity}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Shelf(sku="A-001", quantity=42)
        ++> Shelf(sku="A-002", quantity=17)
        ++> Shelf(sku="A-003", quantity=29)
        ++> Shelf(sku="A-004", quantity=8);

    counter = Counter();
    root spawn counter;

    print(f"Per-item reports:");
    for (sku, qty) in [("A-001", 42), ("A-002", 17), ("A-003", 29), ("A-004", 8)] {
        print(f"  {sku} -> {qty}");
    }
    print(f"Total units in warehouse: {counter.total}");
    print(f"Smallest shelf count: {counter.smallest}");
}
