    has quantity: int = 0;
}

walker Counter {
    has report_count: int = 0;
    has total_units: int = 0;
    has min_qty: int = 0;

    can start with Root entry {
        # Initialize the smallest count to a large sentinel before sweep.
        self.min_qty = 999999;
        visit [-->];
    }

    can sweep with Shelf entry {
        self.report_count += 1;
        self.total_units += here.quantity;
        if here.quantity < self.min_qty {
            self.min_qty = here.quantity;
        }
        print(f"Shelf {self.report_count}: SKU={here.sku}, qty={here.quantity}");
        visit [-->];
    }
}

with entry {
    root ++> Shelf(sku="A-001", quantity=42)
        ++> Shelf(sku="A-002", quantity=17)
        ++> Shelf(sku="B-010", quantity=5)
        ++> Shelf(sku="C-777", quantity=88);

    counter = Counter();
    root spawn counter;

    print("---");
    print(f"Per-item count: {counter.report_count}");
    print(f"Total units in warehouse: {counter.total_units}");
    print(f"Smallest shelf count: {counter.min_qty}");
}
