"""Tests for the mutual-friendship neighborhood program."""

import io;
import from contextlib { redirect_stdout }

test "alice greeter reaches bob forward only and stops" {
    alice_house = House(name="Alice");
    bob_house = House(name="Bob");

    root ++> alice_house ++> bob_house;
    alice_house +>:Buddy(since="childhood"):+> bob_house;
    bob_house +>:Buddy(since="childhood"):+> alice_house;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        alice_greeter = Greeter(greeting="Alice says hi");
        alice_house spawn alice_greeter;
    }
    out = buf.getvalue();

    # Alice's walker must actually traverse to Bob and record the visit.
    assert "Bob" in alice_greeter.visited, f"Alice greeter never reached Bob; visited={alice_greeter.visited}, out={out!r}";
    # The walker must not loop forever; a guard on visited should halt it.
    assert len(alice_greeter.visited) <= 2, f"Alice greeter bounced, visited={alice_greeter.visited}, out={out!r}";
    # And it must produce observable output proving the traversal happened.
    assert "Bob" in out, f"missing Bob greeting in stdout: {out!r}";
}

test "bob greeter reaches alice forward only and stops" {
    alice_house = House(name="Alice");
    bob_house = House(name="Bob");

    root ++> alice_house ++> bob_house;
    alice_house +>:Buddy(since="childhood"):+> bob_house;
    bob_house +>:Buddy(since="childhood"):+> alice_house;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        bob_greeter = Greeter(greeting="Bob says hi");
        bob_house spawn bob_greeter;
    }
    out = buf.getvalue();

    # Bob's walker must actually traverse to Alice and record the visit.
    assert "Alice" in bob_greeter.visited, f"Bob greeter never reached Alice; visited={bob_greeter.visited}, out={out!r}";
    # The walker must not loop forever; a guard on visited should halt it.
    assert len(bob_greeter.visited) <= 2, f"Bob greeter bounced, visited={bob_greeter.visited}, out={out!r}";
    # And it must produce observable output proving the traversal happened.
    assert "Alice" in out, f"missing Alice greeting in stdout: {out!r}";
}

test "buddy edges are genuinely bidirectional" {
    alice_house = House(name="Alice");
    bob_house = House(name="Bob");

    root ++> alice_house ++> bob_house;
    alice_house +>:Buddy(since="childhood"):+> bob_house;
    bob_house +>:Buddy(since="childhood"):+> alice_house;

    # Each direction must exist as a Buddy edge.
    alice_out = [alice_house ->:Buddy:->];
    bob_out = [bob_house ->:Buddy:->];
    assert len(alice_out) == 1, f"Alice should have exactly one Buddy edge, got {len(alice_out)}";
    assert len(bob_out) == 1, f"Bob should have exactly one Buddy edge, got {len(bob_out)}";
    assert alice_out[0] is bob_house, "Alice's Buddy edge must point to Bob";
    assert bob_out[0] is alice_house, "Bob's Buddy edge must point to Alice";

    # And no other Buddy edges should exist in the neighborhood.
    total_buddy = len([root -->]().edge_registry()) if False else 0;  # placeholder, replaced below
    # Count Buddy edges directly via node connections.
    edge_count = len(alice_out) + len(bob_out);
    assert edge_count == 2, f"Expected exactly 2 Buddy edges total, got {edge_count}";
}

test "both walkers independently reach the other house" {
    alice_house = House(name="Alice");
    bob_house = House(name="Bob");

    root ++> alice_house ++> bob_house;
    alice_house +>:Buddy(since="childhood"):+> bob_house;
    bob_house +>:Buddy(since="childhood"):+> alice_house;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        ag = Greeter(greeting="A");
        alice_house spawn ag;
        bg = Greeter(greeting="B");
        bob_house spawn bg;
    }
    out = buf.getvalue();

    # Both directions of reachability must hold simultaneously.
    assert "Bob" in ag.visited, f"Alice->Bob traversal failed: {ag.visited}, out={out!r}";
    assert "Alice" in bg.visited, f"Bob->Alice traversal failed: {bg.visited}, out={out!r}";

    # Each walker stops after at most one hop (no infinite bounce).
    assert len(ag.visited) <= 2, f"Alice greeter bounced: {ag.visited}";
    assert len(bg.visited) <= 2, f"Bob greeter bounced: {bg.visited}";
}

