"""Bug tracker: tickets hang off a project, filed and inspected in one connection."""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
    has available: bool = True;
}

edge FiledUnder {}

walker TicketClerk {
    can start with Root entry {
        visit [-->];
    }

    can inspect with Ticket entry {
        print(f"[#{here.priority.upper()}] {here.title}");
        visit [-->];
    }
}

with entry {
    root ++> Project(name="Orbit");

    # Connect AND grab the fresh node in one expression: walrus on the
    # connection hand. The same line wires the typed edge and captures
    # the new ticket so we never have to look it up afterwards.
    bug = Ticket(title="Crash on launch", priority="high");
    root +>:FiledUnder:+> bug;

    feature = Ticket(title="Dark mode toggle", priority="med");
    root +>:FiledUnder:+> feature;

    chore = Ticket(title="Bump deps", priority="low");
    root +>:FiledUnder:+> chore;

    # Print each freshly captured ticket straight from the captured handle.
    print(f"Filed ticket: {bug.title} ({bug.priority})");
    print(f"Filed ticket: {feature.title} ({feature.priority})");
    print(f"Filed ticket: {chore.title} ({chore.priority})");

    root spawn TicketClerk();
}
```

