import io;
import from contextlib { redirect_stdout }

test "filing connects and captures ticket in one expression" {
    root ++> Project(name="Orbit");
    bug = Ticket(title="Crash on launch", priority="high");
    root +>:FiledUnder:+> bug;

    # The freshly connected ticket must be reachable directly via the
    # captured handle — no follow-up lookup query needed.
    assert isinstance(bug, Ticket), f"captured handle must be the new Ticket, got {type(bug)}";
    assert bug.title == "Crash on launch", f"title mismatch: {bug.title}";
    assert bug.priority == "high", f"priority mismatch: {bug.priority}";
}

test "filed tickets are reachable from the project as FiledUnder edges" {
    root ++> Project(name="Orbit");
    bug = Ticket(title="Crash on launch", priority="high");
    feature = Ticket(title="Dark mode toggle", priority="med");
    root +>:FiledUnder:+> bug;
    root +>:FiledUnder:+> feature;

    filed = [root ->:FiledUnder:->];
    assert len(filed) == 2, f"expected 2 FiledUnder edges from root, got {len(filed)}";
    assert bug in filed, "captured bug must be reachable via FiledUnder edge";
    assert feature in filed, "captured feature must be reachable via FiledUnder edge";
}

