    all_reachable = [root -->];
    assert len(all_reachable) == 1, f"root should have exactly 1 direct child, got {len(all_reachable)}";

    # Walk the full chain and collect every Track node.
    visited = [];
    for n in all_reachable {
        visited.append(n);
        for m in [n -->] {
