test "inline walrus assignment binds the created Track nodes" {
    root ++> (t1 := Track(title="X", runtime=1))
        ++> (t2 := Track(title="Y", runtime=1))
        ++> (t3 := Track(title="Z", runtime=1));

    assert isinstance(t1, Track), f"t1 should be a Track, got {type(t1)}";
    assert isinstance(t2, Track), f"t2 should be a Track, got {type(t2)}";
    assert isinstance(t3, Track), f"t3 should be a Track, got {type(t3)}";
    assert t1.title == "X" and t2.title == "Y" and t3.title == "Z", f"walrus bindings wrong: {t1.title},{t2.title},{t3.title}";

    # The walrus-bound nodes must be the very same nodes wired into the graph.
    chain_from_root = [root -->];
    assert len(chain_from_root) == 1, f"root should have one direct child, got {len(chain_from_root)}";
