"""Gallery security console: log every visitor generically, plus a curator-only
official inspection that records the curator's name and counts rooms inspected.

A union ability on the room handles BOTH visitor kinds (any room occupant
matches one branch). The curator branch increments a per-walker tally and
prints an official inspection line tagged with the curator's name.
"""

node Room {
    has label: str = "";
}

walker Tourist {
    has name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can occupy with Room entry {
        print(f"[LOG] tourist '{self.name}' entered room '{here.label}'");
        visit [-->];
    }
}

walker Curator {
    has name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Room entry {
        self.rooms_inspected += 1;
        print(
            f"[LOG] curator '{self.name}' entered room '{here.label}'; "
            f"[OFFICIAL INSPECTION] recorded under '{self.name}' "
            f"(rooms inspected: {self.rooms_inspected})"
        );
        visit [-->];
    }
}

with entry {
    room_a = Room(label="Hall A");
    room_b = Room(label="Hall B");
    root ++> room_a ++> room_b;

    t = Tourist(name="Alex");
    c = Curator(name="Dr. Vale");

    root spawn t;
    print("---");
    root spawn c;

    print(
        f"tourist '{t.name}' triggered no official inspections; "
        f"curator '{c.name}' inspected {c.rooms_inspected} rooms"
    );
}
