"""Gallery security console: log every visitor, but give curators an official inspection."""

node Room {
    has name: str = "";
    has log: str = "";
}

walker Tourist {
    has visitor_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log += f"visitor: {self.visitor_name}\n";
        print(f"[{here.name}] logged visitor {self.visitor_name}");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Room entry {
        here.log += f"visitor: {self.curator_name}\n";
        here.log += f"OFFICIAL INSPECTION by {self.curator_name}\n";
        self.inspections += 1;
        print(f"[{here.name}] official inspection by {self.curator_name}");
        visit [-->];
    }
}

with entry {
    gallery_a = Room(name="Gallery A");
    gallery_b = Room(name="Gallery B");
    root ++> gallery_a ++> gallery_b;

    tourist = Tourist(visitor_name="Alex");
    root spawn tourist;

    curator = Curator(curator_name="Dr. Bell");
    root spawn curator;

    print("--- Gallery A log ---");
    print(gallery_a.log);
    print("--- Gallery B log ---");
    print(gallery_b.log);
    print(f"Curator {curator.curator_name} performed {curator.inspections} official inspections; tourist logged generically only.");
}
