    has visits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can log_entry with Room entry {
        self.visits += 1;
        print(f"[LOG] visitor {self.badge} entered room {here.name}");
        visit [-->] else { disengage; }
    }
}

walker Curator {
    has badge: str = "";
    has inspections: int = 0;
    has current_room: str = "";

    can start with Root entry {
        visit [-->];
    }

    can log_entry with Room entry {
        self.inspections += 1;
        self.current_room = here.name;
        print(f"[INSPECTION] curator {self.badge} officially inspected room {self.current_room}");
        visit [-->] else { disengage; }
    }
}

with entry {
    gallery = Room(name="Gallery");
    storage = Room(name="Storage");
    root ++> gallery ++> storage;

    t = Visitor(badge="T-9");
    root spawn t;

    c = Curator(badge="C-1");
    root spawn c;

    print(
        f"difference: curator logged {c.inspections} official inspection(s), "
        f"tourist logged only generic entries."
    );
}
