"""Road-trip playlist: tracks chained inline from root and played in order.

Three ``Track`` nodes are appended to ``root`` in a single ``++>`` chain,
each created inside the connection expression itself (no intermediate
variables). A ``Player`` walker walks the chain and prints a now-playing
line plus the running total runtime in minutes.
"""

node Track {
    has title: str = "";
    has artist: str = "";
    has runtime_min: float = 0.0;
}

walker Player {
    has total_runtime: float = 0.0;
    has track_count: int = 0;

    can start with Root entry {
        print("Pressing play on the road-trip playlist...");
        visit [-->];
    }

    can play with Track entry {
        self.track_count += 1;
        self.total_runtime += here.runtime_min;
        print(
            f"Now playing ({self.track_count}): "
            f"{here.title} -- {here.artist} "
            f"[{here.runtime_min} min]"
        );
        print(
            f"  running total: {self.total_runtime} min"
        );
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Track(title="Midnight City", artist="M83", runtime_min=4.03)
        ++> Track(title="On the Road Again", artist="Willie Nelson", runtime_min=2.33)
        ++> Track(title="Life is a Highway", artist="Rascal Flatts", runtime_min=4.36);
    root spawn Player();
}
