        ++> (t2 := Track(title="Life in the Fast Lane", artist="Eagles", runtime=7))
        ++> (t3 := Track(title="Born to Run", artist="Bruce Springsteen", runtime=4));

    # Chain links each operand left-to-right: root->t1, t1->t2, t2->t3.
    assert len([root-->]) == 1, f"root should have exactly 1 direct child, got {len([root-->])}";

    children = [root-->];
    assert children[0].title == "Highway Star", f"first chained track title wrong: {children[0].title}";
    assert children[0].artist == "Deep Purple", f"first chained track artist wrong: {children[0].artist}";
    assert children[0].runtime == 6, f"first chained track runtime wrong: {children[0].runtime}";

    grandchildren = [children[0]-->];
    assert grandchildren[0].title == "Life in the Fast Lane", f"second chained track title wrong: {grandchildren[0].title}";
    assert grandchildren[0].artist == "Eagles", f"second chained track artist wrong: {grandchildren[0].artist}";
    assert grandchildren[0].runtime == 7, f"second chained track runtime wrong: {grandchildren[0].runtime}";

    great_grandchildren = [grandchildren[0]-->];
    assert great_grandchildren[0].title == "Born to Run", f"third chained track title wrong: {great_grandchildren[0].title}";
    assert great_grandchildren[0].artist == "Bruce Springsteen", f"third chained track artist wrong: {great_grandchildren[0].artist}";
    assert great_grandchildren[0].runtime == 4, f"third chained track runtime wrong: {great_grandchildren[0].runtime}";

    # The third track has no outgoing edges — chain terminates.
    assert len([great_grandchildren[0]-->]) == 0, f"third chained track should be a leaf, got {len([great_grandchildren[0]-->])}";
}

