    root ++> (t1 := Track(title="Highway Star", artist="Deep Purple", runtime=6))
        ++> (t2 := Track(title="Life in the Fast Lane", artist="Eagles", runtime=7))
        ++> (t3 := Track(title="Born to Run", artist="Bruce Springsteen", runtime=4));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # Header is emitted on Root entry.
    assert "=== Road Trip Playlist ===" in out, f"missing playlist header in: {out}";

