    assert "#1: Highway Star by Deep Purple [6 min]" in out, f"missing first now-playing line in: {out}";
    assert "#2: Life in the Fast Lane by Eagles [7 min]" in out, f"missing second now-playing line in: {out}";
    assert "#3: Born to Run by Bruce Springsteen [4 min]" in out, f"missing third now-playing line in: {out}";

    # Ordering: header comes first; track #1 < #2 < #3 in the printed stream.
    header_idx = out.index("=== Road Trip Playlist ===");
    one_idx = out.index("#1: Highway Star");
    two_idx = out.index("#2: Life in the Fast Lane");
    three_idx = out.index("#3: Born to Run");
