        ++> Track(title="Take It Easy", artist="Eagles", runtime=3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    # Header line.
    assert "Starting road-trip playlist" in out, f"missing start banner: {out}";

    # All three now-playing lines must appear, in chain order.
    idx1 = out.find("Highway to Hell");
    idx2 = out.find("Life is a Highway");
    idx3 = out.find("Take It Easy");
    assert idx1 >= 0 and idx2 >= 0 and idx3 >= 0, f"missing tracks in output: {out}";
    assert idx1 < idx2 < idx3, f"tracks out of order: idx1={idx1}, idx2={idx2}, idx3={idx3}";

    # Each line must mention its artist and its runtime.
    assert "AC/DC" in out, f"missing AC/DC artist: {out}";
    assert "Rascal Flatts" in out, f"missing Rascal Flatts artist: {out}";
    assert "Eagles" in out, f"missing Eagles artist: {out}";

    # Running total progression: 3, 7, 10.
    assert "running total: 3 min" in out, f"missing running total 3: {out}";
    assert "running total: 7 min" in out, f"missing running total 7: {out}";
    assert "running total: 10 min" in out, f"missing running total 10: {out}";

    # Order of totals must match order of plays.
    assert out.find("running total: 3 min") < out.find("running total: 7 min") < out.find("running total: 10 min"), (
        f"running totals out of order: {out}"
    );

    # Walker's accumulated total matches the sum of runtimes.
    assert res.total_runtime == 10, f"walker total_runtime wrong: {res.total_runtime}";
}

test "player on an empty graph prints only the banner" {
    import io;
    import from contextlib { redirect_stdout }

    # No tracks attached; Player should visit zero Track nodes.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Player();
    }
    out = buf.getvalue();

    assert "Starting road-trip playlist" in out, f"missing banner on empty graph: {out}";
    assert "Now playing" not in out, f"should not print any now-playing lines: {out}";
    assert res.total_runtime == 0, f"total_runtime should stay 0, got {res.total_runtime}";
}

test "single track plays once with correct total" {
    import io;
    import from contextlib { redirect_stdout }

    root ++> Track(title="Route 66", artist="Nat King Cole", runtime=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
