    assert "entry: Alice" in room_b.log, f"room B should log generic entry for Alice; got {room_b.log}";
    assert room_a.inspections == [], f"tourist must NOT create inspections; got {room_a.inspections}";
    assert room_b.inspections == [], f"tourist must NOT create inspections; got {room_b.inspections}";
}

test "curator logs entry and records official inspection in each room" {
    rooms = build_gallery();
    room_a = rooms[0];
    room_b = rooms[1];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        curator = Curator(curator_name="Dr. Bell");
