    assert "entry: Dr. Bell" in room_a.log, f"room A should log generic entry for curator; got {room_a.log}";
    assert "entry: Dr. Bell" in room_b.log, f"room B should log generic entry for curator; got {room_b.log}";
    assert "inspection by Dr. Bell" in room_a.inspections, f"room A should record curator inspection; got {room_a.inspections}";
    assert "inspection by Dr. Bell" in room_b.inspections, f"room B should record curator inspection; got {room_b.inspections}";
}

test "curator rooms_inspected counter increments once per room" {
    rooms = build_gallery();
    room_a = rooms[0];
    room_b = rooms[1];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        curator = Curator(curator_name="Dr. Bell");
        res = root spawn curator;
    }

    assert res.rooms_inspected == 2, f"curator should have inspected 2 rooms; got {res.rooms_inspected}";
    assert len(room_a.inspections) == 1, f"room A should have exactly 1 inspection record; got {room_a.inspections}";
    assert len(room_b.inspections) == 1, f"room B should have exactly 1 inspection record; got {room_b.inspections}";
}

test "tourist walker has no inspection counter and rooms have no inspection entries" {
    rooms = build_gallery();
    room_a = rooms[0];
    room_b = rooms[1];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tourist = Visitor(visitor_name="Bob");
        res = root spawn tourist;
