    assert len(room_a.inspections) == 0, f"tourist walk should leave room A inspections empty; got {room_a.inspections}";
    assert len(room_b.inspections) == 0, f"tourist walk should leave room B inspections empty; got {room_b.inspections}";
    assert len(room_a.log) == 1, f"room A log should have exactly 1 tourist entry; got {room_a.log}";
    assert len(room_b.log) == 1, f"room B log should have exactly 1 tourist entry; got {room_b.log}";
