    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Tourist(visitor_name="Alice");
    }
    out = buf.getvalue();

    rooms = [root -->];
    # Two rooms, chained: root -> Modern Hall -> Sculpture Garden
    assert len(rooms) == 1, f"root should have one direct child, got {len(rooms)}";
    room_a = rooms[0];
    room_b = [room_a -->][0];

    # Tourist visited both rooms, so both should have one log line each.
    assert len(room_a.log) == 1, f"room A log len: {room_a.log}";
    assert len(room_b.log) == 1, f"room B log len: {room_b.log}";
    assert "visitor: Alice" in room_a.log[0], f"unexpected A log: {room_a.log}";
    assert "visitor: Alice" in room_b.log[0], f"unexpected B log: {room_b.log}";

    # No inspection should have been recorded by a tourist.
    assert room_a.inspectors == [], f"tourist should not stamp inspectors, got {room_a.inspectors}";
    assert room_b.inspectors == [], f"tourist should not stamp inspectors, got {room_b.inspectors}";

