    assert out == "", f"family visitor should be silent, got {out!r}";
    # FamilyVisitor has no shift_visits field at all — guard with hasattr in case
    # the walker ever gains one; today the spec says it stays silent and
    # contributes nothing to any count.
    assert not hasattr(res, "shift_visits") or res.shift_visits == 0, (
        f"family visitor should not record ward visits, got {res.shift_visits}"
    );
}

test "shift_visits count scales with number of wards" {
    root ++> Ward(ward_name="A") ++> Ward(ward_name="B") ++> Ward(ward_name="C") ++> Ward(ward_name="D");

