"""Test annex for the bug tracker connect-and-grab pattern."""

import io;
import from contextlib { redirect_stdout }

test "connect-and-grab returns the freshly created ticket node" {
    root ++> (t := Ticket(title="Login button broken", priority="high"));

    # The connection expression itself must yield the new node so we can
    # read its fields directly — no follow-up lookup query needed.
    assert t is not None, "connect expression must capture the new node";
    assert t.title == "Login button broken", f"got title {t.title}";
    assert t.priority == "high", f"got priority {t.priority}";
    assert t.describe() == "[HIGH] Login button broken", f"got describe {t.describe()}";

    # And the node must actually be linked off the root by the same
    # connection that produced it.
    children = [root-->];
    assert len(children) == 1, f"expected 1 child on root, got {len(children)}";
    assert t in children, "captured node must be the same node linked off root";
}

test "second connect-and-grab works for a low-priority ticket" {
    root ++> (t2 := Ticket(title="Typo in footer", priority="low"));

    assert t2.title == "Typo in footer", f"got title {t2.title}";
    assert t2.priority == "low", f"got priority {t2.priority}";
    assert t2.describe() == "[LOW] Typo in footer", f"got describe {t2.describe()}";

    children = [root-->];
    assert len(children) == 1, f"expected 1 child, got {len(children)}";
    assert t2 in children, "captured node must be the same node linked off root";
}

test "FilingClerk walks every filed ticket and prints its description" {
    root ++> (t1 := Ticket(title="Login button broken", priority="high"));
    root ++> (t2 := Ticket(title="Typo in footer", priority="low"));
    root ++> (t3 := Ticket(title="Server OOM", priority="critical"));

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FilingClerk();
    }
    out = buf.getvalue();

    # Opening banner from the Root-entry ability.
    assert "Filing clerk opening the queue" in out, f"missing banner: {out}";

    # Every filed ticket must be reported by the walker, in some order,
    # using the Ticket.describe() format (priority uppercase, bracketed).
    assert "filed ticket: [HIGH] Login button broken" in out, f"missing high: {out}";
    assert "filed ticket: [LOW] Typo in footer" in out, f"missing low: {out}";
    assert "filed ticket: [CRITICAL] Server OOM" in out, f"missing critical: {out}";

    # Three distinct ticket descriptions must appear.
    assert out.count("filed ticket:") == 3, f"expected 3 filings, got: {out}";
}

test "connect-and-grab works when chained before a walker spawn" {
    # The pattern must compose: connect-and-grab a ticket, then run the
    # walker, and the captured node must be among those the walker files.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> (t := Ticket(title="Login button broken", priority="high"));
        root spawn FilingClerk();
    }
    out = buf.getvalue();

    assert t.priority == "high", f"got {t.priority}";
    assert t in [root-->], "captured node must be linked off root";
    assert "[HIGH] Login button broken" in out, f"walker must file the captured node: {out}";
}

