"""Gallery security console: log every visitor, and additionally record an official inspection for curators across rooms."""

node Room {
    has room_name: str = "";
    has visitor_log: list[str] = [];
    has curator_inspections: list[str] = [];
}

walker Tourist {
    has visitor_name: str = "Tourist";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.visitor_log.append(self.visitor_name);
        print(f"  [log] tourist '{self.visitor_name}' entered {here.room_name}");
        visit [-->];
    }
}

walker Curator {
    has visitor_name: str = "Curator";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.visitor_log.append(self.visitor_name);
        here.curator_inspections.append(f"Official inspection by {self.visitor_name}");
        self.rooms_inspected += 1;
        print(f"  [log] curator '{self.visitor_name}' entered {here.room_name} (official inspection)");
        visit [-->];
    }
}

with entry {
    lobby = Room(room_name="Lobby");
    gallery = Room(room_name="Gallery");
    root ++> lobby ++> gallery;

    tourist = Tourist(visitor_name="Alice");
    root spawn tourist;

    curator = Curator(visitor_name="Dr. Bell");
    root spawn curator;

    print("");
    print(f"Lobby visitor log: {lobby.visitor_log}");
    print(f"Lobby curator inspections: {lobby.curator_inspections}");
    print(f"Gallery visitor log: {gallery.visitor_log}");
    print(f"Gallery curator inspections: {gallery.curator_inspections}");
    print("");
    print(f"Tourist '{tourist.visitor_name}' performed 0 official inspections.");
    print(f"Curator '{curator.visitor_name}' performed {curator.rooms_inspected} official inspections.");
}
