```jac
"""Bug tracker: tickets connect off a project node, and the connection itself yields the fresh ticket."""

node Project {
    has name: str = "";
}

node Ticket {
    has title: str = "";
    has priority: str = "low";
}

edge Filed {
    has filed_at: str = "today";
}

walker Reporter {
    can start with Root entry {
        visit [-->];
    }

    can file with Project entry {
        print(f"Filing tickets under project: {here.name}");
        visit [-->];
    }

    can announce with Ticket entry {
        label = "URGENT" if here.priority == "high" else "normal";
        print(f"[{label}] {here.title} ({here.priority})");
        visit [-->];
    }
}

with entry {
    root ++> Project(name="Phoenix");

    # Connection itself returns the freshly created ticket.
    fresh_ticket = root +>:Filed(filed_at="Mon"):+> Ticket(title="Login broken", priority="high");

    # Print right away — no lookup query needed.
    first_word = "high" if fresh_ticket.priority == "high" else "low";
    print(f"Captured on connect: '{fresh_ticket.title}' [priority={first_word}]");

    # Now have the reporter walker traverse and announce every ticket.
    root spawn Reporter();
}
```

