        root spawn guest;
    }
    out = buf.getvalue();

    assert out == "", f"expected no output for family visitor, got: {out}";
    assert guest not in [root -->], f"family visitor should not appear on root edges";
}

test "staff badges print in ward graph order" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");
    nurse = Nurse(badge="N-202");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
    }
    out = buf.getvalue();

    icu_idx = out.find("ICU ward");
    gen_idx = out.find("General ward");
    assert icu_idx >= 0 and gen_idx >= 0, f"missing ward prints: {out}";
    assert icu_idx < gen_idx, f"expected ICU before General in output, got: {out}";
    assert nurse.shift_visits == 2, f"expected 2 ward visits, got {nurse.shift_visits}";
}

test "mixed staff and visitor: only staff produce output" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");
    nurse = Nurse(badge="N-303");
    doctor = Doctor(badge="D-77");
    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
        root spawn doctor;
        root spawn guest;
    }
    out = buf.getvalue();

    assert "N-303 badged into the ICU ward" in out, f"missing nurse ICU: {out}";
    assert "N-303 badged into the General ward" in out, f"missing nurse General: {out}";
    assert "D-77 badged into the ICU ward" in out, f"missing doctor ICU: {out}";
    assert "D-77 badged into the General ward" in out, f"missing doctor General: {out}";

    family_lines = [
        ln for ln in out.split("\n")
        if ln and "ICU" not in ln and "General" not in ln
    ];
    assert family_lines == [], f"family visitor produced output: {family_lines}";

    assert nurse.shift_visits == 2, f"nurse visits expected 2, got {nurse.shift_visits}";
    assert doctor.shift_visits == 2, f"doctor visits expected 2, got {doctor.shift_visits}";
}

