"""Gallery security console: every visitor is logged generically, but a curator triggers an official inspection tied to their name and a count of rooms inspected."""

node Room {
    has name: str = "";
    has log: list[str] = [];
}

node Visitor {
    has badge: str = "";
}

node Curator {
    has badge: str = "";
    has rooms_inspected: int = 0;
}

walker Tourist {
    has badge: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.badge}");
        visit [-->];
    }
}

walker Inspector {
    has badge: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"inspection by curator: {self.badge}");
        self.rooms_inspected += 1;
        visit [-->];
    }
}

with entry {
    r1 = Room(name="Hall A");
    r2 = Room(name="Hall B");
    root ++> r1 ++> r2;

    tourist = Tourist(badge="T-001");
    root spawn tourist;

    curator = Inspector(badge="C-007");
    root spawn curator;

    print(f"Tourist badge: {tourist.badge}");
    print(f"Curator badge: {curator.badge}, rooms inspected: {curator.rooms_inspected}");
    print(f"Room '{r1.name}' log: {r1.log}");
    print(f"Room '{r2.name}' log: {r2.log}");
    print(f"Difference: only the curator triggered an official inspection record on each room.");
}
