    r2 = Room(name="Hall B");
    root ++> r1 ++> r2;

    tourist = Tourist(badge="T-001");
    root spawn tourist;

    assert ("visitor: T-001" in r1.log), f"missing generic visitor entry on r1: {r1.log}";
    assert ("visitor: T-001" in r2.log), f"missing generic visitor entry on r2: {r2.log}";

    assert not any("inspection by curator" in entry for entry in r1.log), f"tourist should not trigger inspection on r1: {r1.log}";
    assert not any("inspection by curator" in entry for entry in r2.log), f"tourist should not trigger inspection on r2: {r2.log}";
}

