    assert len(r1_curator_entries) == 1 and r1_curator_entries[0] == "inspection by curator: C-007", f"r1 curator log wrong: {r1.log}";

    assert len(r2_tourist_entries) == 1 and r2_tourist_entries[0] == "visitor: T-001", f"r2 tourist log wrong: {r2.log}";
    assert len(r2_curator_entries) == 1 and r2_curator_entries[0] == "inspection by curator: C-007", f"r2 curator log wrong: {r2.log}";
