```jac
"""Gallery security console.

Every visitor is logged generically as they enter a room. When a curator
walks in, the room additionally records an official inspection under the
curator's name and increments the curator's tally of rooms inspected.
A plain tourist triggers only the generic log.
"""

node Room {
    has room_name: str = "";

    # Generic log fires for any visitor (Tourist or Curator).
    can log_entry with Tourist | Curator entry {
        visitor_type = "tourist" if isinstance(visitor, Tourist) else "curator";
        print(f"[LOG] {visitor_type} entered {self.room_name}");
        visitor.rooms_visited += 1;
    }

    # Official inspection fires only for curators.
    can record_inspection with Curator entry {
        print(f"[INSPECTION] {self.room_name} inspected by {visitor.curator_name}");
        visitor.inspections += 1;
    }
}

walker Tourist {
    has rooms_visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter_room with Room entry {
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "Anonymous Curator";
    has rooms_visited: int = 0;
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter_room with Room entry {
        visit [-->];
    }
}

with entry {
    room_a = Room(room_name="Gallery A");
    room_b = Room(room_name="Gallery B");
    root ++> room_a ++> room_b;

    print("=== Tourist pass ===");
    tourist = Tourist();
    root spawn tourist;

    print("=== Curator pass ===");
    curator = Curator(curator_name="Dr. Lin");
    root spawn curator;

    print(f"\nTourist visited {tourist.rooms_visited} rooms; "
          f"Curator inspected {curator.inspections} rooms under '{curator.curator_name}'.");
}
```

