"""Gallery security console.

A generic visitor logs every room it enters. A curator does the same,
plus triggers an official room inspection recorded under the curator's
name and counts the rooms they inspected. The console then shows the
difference between the two visitors.
"""

node Room {
    has name: str = "";
    has visitor_log: list[str] = [];
    has inspections: list[str] = [];
}

walker Tourist {
    has label: str = "Tourist";

    can start with Root entry {
        visit [-->];
    }

    can walk with Room entry {
        here.visitor_log.append(self.label);
        print(f"Visitor '{self.label}' entered {here.name}");
        visit [-->] else { disengage; }
    }
}

walker GalleryCurator {
    has label: str = "Curator";
    has curator_name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_rooms with Room entry {
        here.visitor_log.append(self.label);
        print(f"Visitor '{self.label}' entered {here.name}");
        here.inspections.append(self.curator_name);
        self.rooms_inspected += 1;
        print(f"  [INSPECTION by {self.curator_name} at {here.name}]");
        visit [-->] else { disengage; }
    }
}

with entry {
    lobby = Room(name="Lobby");
    gallery = Room(name="Gallery");
    root ++> lobby ++> gallery;

    tourist = Tourist();
    root spawn tourist;

    curator_walker = GalleryCurator(curator_name="Dr. Vex");
    curator_walker.label = "Curator-C";
    root spawn curator_walker;

    print("");
    print("=== Room logs ===");
    for r in [lobby, gallery] {
        log_summary = ", ".join(r.visitor_log) if r.visitor_log else "(none)";
        insp_summary = ", ".join(r.inspections) if r.inspections else "(none)";
        print(f"{r.name} visitors: {log_summary}");
        print(f"{r.name} inspections: {insp_summary}");
    }

    print("");
    print(f"Tourist visited rooms but recorded 0 inspections.");
    print(f"Curator '{curator_walker.curator_name}' officially inspected "
          f"{curator_walker.rooms_inspected} room(s).");
    print(f"Difference in official inspections: "
          f"{curator_walker.rooms_inspected - 0}");
}
