"""Gallery security console: log every visitor, but curators trigger an official inspection."""

node Room {
    has name: str = "";
    has log: list[str] = [];
    has inspections: list[str] = [];
}

# Plain visitor: every Room logs a generic entry line.
walker Tourist {
    has visitor_name: str = "Tourist";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.visitor_name} entered {here.name}");
        print(f"[LOG] {here.name}: visitor {self.visitor_name} entered");
        visit [-->];
    }
}

# Curator: same generic log, PLUS the room records an official
# inspection under the curator's name and the curator tallies up
# how many rooms they inspected.
walker Curator {
    has curator_name: str = "Curator";
    has inspected_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.log.append(f"visitor: {self.curator_name} entered {here.name}");
        print(f"[LOG] {here.name}: visitor {self.curator_name} entered");

        here.inspections.append(f"inspected by {self.curator_name}");
        print(f"[INSPECTION] {here.name}: inspected by {self.curator_name}");

        self.inspected_count += 1;
        visit [-->];
    }
}

with entry {
    hall = Room(name="Hall");
    gallery = Room(name="Gallery");
    root ++> hall ++> gallery;

    print("--- Tourist walk-through ---");
    t = Tourist(visitor_name="Alice");
    root spawn t;

