"""Tests for the gallery security console."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh two-room gallery (Hall -> Gallery) under root.
def:pub make_gallery() {
    hall = Room(name="Hall");
    gallery = Room(name="Gallery");
    root ++> hall ++> gallery;
    return (hall, gallery);
}

test "tourist logs generic entry on every room" {
    (hall, gallery) = make_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        t = Tourist(visitor_name="Alice");
        root spawn t;
    }
    out = buf.getvalue();

    # Both rooms got a generic visitor log line.
    assert hall.log == ["visitor: Alice entered Hall"], f"hall.log={hall.log}";
    assert gallery.log == ["visitor: Alice entered Gallery"], f"gallery.log={gallery.log}";

    # No inspections recorded on the tourist run.
    assert hall.inspections == [], f"hall.inspections={hall.inspections}";
    assert gallery.inspections == [], f"gallery.inspections={gallery.inspections}";

    # The TOURIST's own ability is `can enter with Room entry` — it only logs.
    # A tourist has no `inspected_count` field at all, so the program must
    # NOT have produced an [INSPECTION] line for Alice.
    assert "[INSPECTION]" not in out, f"unexpected inspection output: {out}";
    assert "[LOG] Hall: visitor Alice entered" in out, f"missing hall log: {out}";
    assert "[LOG] Gallery: visitor Alice entered" in out, f"missing gallery log: {out}";

    # Graph shape: root -> Hall -> Gallery (chain), not fan-out.
    assert len([root-->]) == 1, f"root should have 1 direct child, got {len([root-->])}";
    assert len([hall-->]) == 1, f"Hall should have 1 direct child (Gallery), got {len([hall-->])}";
    assert len([gallery-->]) == 0, f"Gallery should be a leaf, got {len([gallery-->])}";
}

test "curator triggers generic log PLUS official inspection on every room" {
    (hall, gallery) = make_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = Curator(curator_name="Dr. Bell");
        root spawn c;
    }
    out = buf.getvalue();

    # Both rooms got the generic log line.
    assert hall.log == ["visitor: Dr. Bell entered Hall"], f"hall.log={hall.log}";
    assert gallery.log == ["visitor: Dr. Bell entered Gallery"], f"gallery.log={gallery.log}";

    # ADDITIONALLY, each room recorded an official inspection under the
    # curator's name.
    assert hall.inspections == ["inspected by Dr. Bell"], f"hall.inspections={hall.inspections}";
    assert gallery.inspections == ["inspected by Dr. Bell"], f"gallery.inspections={gallery.inspections}";

    # The curator tallies how many rooms they inspected.
    assert c.inspected_count == 2, f"inspected_count should be 2, got {c.inspected_count}";

    # Output: generic [LOG] line AND [INSPECTION] line for each room.
    assert "[LOG] Hall: visitor Dr. Bell entered" in out, f"missing hall log: {out}";
    assert "[LOG] Gallery: visitor Dr. Bell entered" in out, f"missing gallery log: {out}";
    assert "[INSPECTION] Hall: inspected by Dr. Bell" in out, f"missing hall inspection: {out}";
    assert "[INSPECTION] Gallery: inspected by Dr. Bell" in out, f"missing gallery inspection: {out}";
}

test "tourist and curator together show the difference" {
    (hall, gallery) = make_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        t = Tourist(visitor_name="Alice");
        root spawn t;

        c = Curator(curator_name="Dr. Bell");
        root spawn c;
    }
    out = buf.getvalue();

    # After BOTH walks, both rooms have 2 generic logs (one per visitor)
    # and only the curator's inspections were recorded.
    assert hall.log == [
        "visitor: Alice entered Hall",
        "visitor: Dr. Bell entered Hall",
    ], f"hall.log={hall.log}";
    assert gallery.log == [
        "visitor: Alice entered Gallery",
        "visitor: Dr. Bell entered Gallery",
    ], f"gallery.log={gallery.log}";

    # Inspections only come from the curator — exactly one per room.
    assert hall.inspections == ["inspected by Dr. Bell"], f"hall.inspections={hall.inspections}";
    assert gallery.inspections == ["inspected by Dr. Bell"], f"gallery.inspections={gallery.inspections}";

    # 4 generic logs total, 2 inspections total.
    total_logs = len(hall.log) + len(gallery.log);
    total_inspections = len(hall.inspections) + len(gallery.inspections);
    assert total_logs == 4, f"total_logs should be 4, got {total_logs}";
    assert total_inspections == 2, f"total_inspections should be 2, got {total_inspections}";

    # The difference the problem asks us to show:
    # the curator walked the same generic logs as the tourist AND filed
    # one extra inspection per room.
    assert c.inspected_count == 2, f"inspected_count should be 2, got {c.inspected_count}";

    # Output must contain BOTH markers for the curator and ONLY [LOG] (no
    # [INSPECTION]) for the tourist.
    assert "[LOG] Hall: visitor Alice entered" in out, f"missing tourist hall log: {out}";
    assert "[LOG] Gallery: visitor Alice entered" in out, f"missing tourist gallery log: {out}";
    assert "[LOG] Hall: visitor Dr. Bell entered" in out, f"missing curator hall log: {out}";
    assert "[LOG] Gallery: visitor Dr. Bell entered" in out, f"missing curator gallery log: {out}";
    assert "[INSPECTION] Hall: inspected by Dr. Bell" in out, f"missing curator hall inspection: {out}";
    assert "[INSPECTION] Gallery: inspected by Dr. Bell" in out, f"missing curator gallery inspection: {out}";

    # Exactly two [INSPECTION] markers in the combined output (one per room).
    assert out.count("[INSPECTION]") == 2, f"expected 2 inspection markers, got {out.count('[INSPECTION]')}: {out}";
    # Exactly four [LOG] markers (two rooms x two visitors).
    assert out.count("[LOG]") == 4, f"expected 4 log markers, got {out.count('[LOG]')}: {out}";
}

test "curator with default name still records inspections and counts rooms" {
    (hall, gallery) = make_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = Curator();  # default curator_name="Curator", inspected_count=0
        root spawn c;
    }
    out = buf.getvalue();

    # Generic log uses the default name.
    assert hall.log == ["visitor: Curator entered Hall"], f"hall.log={hall.log}";
    assert gallery.log == ["visitor: Curator entered Gallery"], f"gallery.log={gallery.log}";

    # Inspection recorded under the default name.
    assert hall.inspections == ["inspected by Curator"], f"hall.inspections={hall.inspections}";
    assert gallery.inspections == ["inspected by Curator"], f"gallery.inspections={gallery.inspections}";

    # The count must reflect BOTH rooms visited, starting from the default 0.
    assert c.inspected_count == 2, f"inspected_count should be 2, got {c.inspected_count}";

    assert "[INSPECTION] Hall: inspected by Curator" in out, f"missing inspection: {out}";
    assert "[INSPECTION] Gallery: inspected by Curator" in out, f"missing inspection: {out}";
}

