"""Bug tracker: file tickets from project, capture the new ticket directly, and report it."""

node Ticket {
    has title: str = "";
    has priority: int = 0;
}

node Project {
    has name: str = "";
}

walker Reporter {
    can start with Root entry {
        visit [-->];
    }

    can file with Project entry {
        new_ticket = Ticket(title="Login fails on SSO redirect", priority=2);
        here ++> new_ticket;
        print(f"FILED on {here.name}: {new_ticket.title} (priority {new_ticket.priority})");
        visit [-->];
    }
}

with entry {
    p = Project(name="Billing");
    root ++> p;
    root spawn Reporter();
}
