"""Test annex for the gallery security console."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a two-room gallery with root -> Lobby -> Gallery.
def build_gallery() {
    lobby = Room(name="Lobby");
    gallery = Room(name="Gallery");
    root ++> lobby ++> gallery;
    return (lobby, gallery);
}

test "generic visitor only logs, no inspection" {
    (lobby, gallery) = build_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        generic = Visitor(visitor_name="Alex");
        root spawn generic;
    }
    out = buf.getvalue();

    # Generic visitor must NOT bump an inspection counter (the base walker
    # declares no `inspections` field at all).
    # We assert behaviorally: no "official inspection" line is printed.
    assert "official inspection" not in out, f"generic visitor should not inspect, got: {out}";

    # Both rooms should have exactly one generic visitor log entry.
    assert len(lobby.log) == 1, f"lobby log should have 1 entry, got {lobby.log}";
    assert "visitor: Alex" in lobby.log[0], f"unexpected lobby entry: {lobby.log[0]}";
    assert len(gallery.log) == 1, f"gallery log should have 1 entry, got {gallery.log}";
    assert "visitor: Alex" in gallery.log[0], f"unexpected gallery entry: {gallery.log[0]}";

    # Printed output should contain both room visits.
    assert "Lobby" in out and "Gallery" in out, f"missing rooms in output: {out}";
}

test "curator logs AND records an inspection per room" {
    (lobby, gallery) = build_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        curator = Curator(curator_name="Dr. Lee");
        root spawn curator;
    }
    out = buf.getvalue();

    # Per-room log: a "curator:" entry plus an "official inspection by" entry.
    assert len(lobby.log) == 2, f"lobby should have 2 entries, got {lobby.log}";
    assert lobby.log[0] == "curator: Dr. Lee", f"unexpected lobby[0]: {lobby.log[0]}";
    assert lobby.log[1] == "official inspection by Dr. Lee", f"unexpected lobby[1]: {lobby.log[1]}";

    assert len(gallery.log) == 2, f"gallery should have 2 entries, got {gallery.log}";
    assert gallery.log[0] == "curator: Dr. Lee", f"unexpected gallery[0]: {gallery.log[0]}";
    assert gallery.log[1] == "official inspection by Dr. Lee", f"unexpected gallery[1]: {gallery.log[1]}";

    # The curator walker's inspections count must equal the number of rooms.
    assert curator.inspections == 2, f"curator should have 2 inspections, got {curator.inspections}";

    # Both inspection lines must appear in stdout, in order.
    idx_lobby = out.find("Lobby");
    idx_gallery = out.find("Gallery");
    assert idx_lobby != -1 and idx_gallery != -1, f"missing room names in output: {out}";
    assert idx_lobby < idx_gallery, f"rooms should be visited in order, got: {out}";

    # The official-inspection marker must appear for each room.
    assert out.count("official inspection") == 2, f"expected 2 inspection lines, got: {out}";
}

test "tourist behavior matches generic visitor" {
    (lobby, gallery) = build_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tourist = Tourist(tourist_name="Sam");
        root spawn tourist;
    }
    out = buf.getvalue();

    # Tourist is a flavor of visitor: it must NOT trigger official inspections
    # nor modify any counter (its `has` declares no inspections field).
    assert "official inspection" not in out, f"tourist should not inspect, got: {out}";

    # Both rooms get exactly one visitor log entry naming the tourist.
    assert len(lobby.log) == 1, f"lobby should have 1 entry, got {lobby.log}";
    assert lobby.log[0] == "visitor: Sam", f"unexpected lobby entry: {lobby.log[0]}";
    assert len(gallery.log) == 1, f"gallery should have 1 entry, got {gallery.log}";
    assert gallery.log[0] == "visitor: Sam", f"unexpected gallery entry: {gallery.log[0]}";

    # Tourist's own `tourist_name` field must remain intact after the walk.
    assert tourist.tourist_name == "Sam", f"tourist_name corrupted: {tourist.tourist_name}";
}

test "tourist and curator together show the difference" {
    (lobby, gallery) = build_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tourist = Tourist(tourist_name="Sam");
        root spawn tourist;
        curator = Curator(curator_name="Dr. Lee");
        root spawn curator;
    }
    out = buf.getvalue();

    # After both runs, lobby and gallery should each have 1 tourist entry +
    # 2 curator entries = 3 entries per room.
    assert len(lobby.log) == 3, f"lobby should have 3 entries, got {lobby.log}";
    assert len(gallery.log) == 3, f"gallery should have 3 entries, got {gallery.log}";

    # Tourist line is a plain visitor log.
    assert lobby.log[0] == "visitor: Sam", f"unexpected lobby[0]: {lobby.log[0]}";
    assert gallery.log[0] == "visitor: Sam", f"unexpected gallery[0]: {gallery.log[0]}";

    # Curator appends two more entries per room.
    assert "curator: Dr. Lee" in lobby.log and "curator: Dr. Lee" in gallery.log, f"missing curator entries: lobby={lobby.log}, gallery={gallery.log}";
    assert "official inspection by Dr. Lee" in lobby.log and "official inspection by Dr. Lee" in gallery.log, f"missing official inspections: lobby={lobby.log}, gallery={gallery.log}";

    # Only the curator increments an inspection count, and only by room count.
    assert curator.inspections == 2, f"curator should have 2 inspections, got {curator.inspections}";

    # Stdout should distinguish tourist's plain log line from curator's
    # official-inspection line.
    assert "Sam logged into Lobby" in out, f"missing tourist lobby log: {out}";
    assert "official inspection in Lobby" in out, f"missing curator inspection: {out}";
    assert out.count("official inspection") == 2, f"expected exactly 2 inspection lines, got: {out}";
}

test "curator inspection count is independent per spawn" {
    (lobby, gallery) = build_gallery();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        curator = Curator(curator_name="Dr. Lee");
        root spawn curator;
    }
    out = buf.getvalue();

    # The curator walked both rooms: counter must reflect exactly two inspections.
    assert curator.inspections == 2, f"expected 2 inspections, got {curator.inspections}";

    # Counter must NOT be polluted by generic visitors or tourists, which have
    # no such field at all. Re-spawning a generic visitor on the same root
    # must not change the curator's count.
    before = curator.inspections;
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        generic = Visitor(visitor_name="Alex");
        root spawn generic;
    }
    assert curator.inspections == before, f"generic visitor altered inspections: {curator.inspections}";

    # And spawning a tourist must not change it either.
    before = curator.inspections;
    buf3 = io.StringIO();
    with redirect_stdout(buf3) {
        tourist = Tourist(tourist_name="Sam");
        root spawn tourist;
    }
    assert curator.inspections == before, f"tourist altered inspections: {curator.inspections}";

    # Rooms should now have the original curator entries plus the new logs.
    assert len(lobby.log) == 4, f"lobby should have 2 curator + 2 visitor entries, got {lobby.log}";
    assert len(gallery.log) == 4, f"gallery should have 2 curator + 2 visitor entries, got {gallery.log}";
}

