"""Gallery security console.

A generic visitor ability fires for any visitor on entry to a room.
A curator ability additionally records an inspection under the curator's
name and tallies how many rooms the curator inspected. A tourist uses
the generic path only.
"""

node Room {
    has name: str = "";
}

walker Visitor {
    has visitor_name: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        print(f"Visitor {self.visitor_name} entered {here.name}");
        visit [-->];
    }
}

walker Curator {
    has visitor_name: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        print(f"Visitor {self.visitor_name} entered {here.name}");
        print(f"  [OFFICIAL INSPECTION] {self.visitor_name} inspected {here.name}");
        self.inspections += 1;
        visit [-->];
    }
}

with entry {
    room_a = Room(name="Gallery A");
    room_b = Room(name="Gallery B");
    root ++> room_a ++> room_b;

    tourist = Visitor(visitor_name="Tourist_Tess");
    curator = Curator(visitor_name="Curator_Carl");
    root spawn tourist;
    root spawn curator;

    print(f"Tourist logged in {2 if True else 0} rooms, Curator inspected {curator.inspections} rooms");
}
```

