"""Tests for the gallery security console.

The program defines two walkers that visit rooms attached to Root:
- Visitor: logs generically on every Room entry.
- Curator: logs generically AND records an official inspection, incrementing
  its own inspections counter once per Room visited.
- The `with entry` demo block is stripped before tests run, so every test
  must build its own graph and spawn its own walkers.
"""

import io;
import from contextlib { redirect_stdout }

test "tourist logs generic entry on every room and records no inspections" {
    root ++> Room(name="Gallery A");
    root ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tourist = Visitor(visitor_name="Tourist_Tess");
        root spawn tourist;
    }
    out = buf.getvalue();

    assert "Visitor Tourist_Tess entered Gallery A" in out, f"missing Gallery A entry: {out}";
    assert "Visitor Tourist_Tess entered Gallery B" in out, f"missing Gallery B entry: {out}";
    assert "OFFICIAL INSPECTION" not in out, f"tourist should not trigger inspection: {out}";
    assert tourist.inspections == 0, f"tourist should have 0 inspections, got {tourist.inspections}";
    assert out.count("Visitor Tourist_Tess entered") == 2, f"expected 2 generic entries, got {out}";
}

test "curator logs generic entry and an attributed official inspection per room" {
    root ++> Room(name="Gallery A");
    root ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        curator = Curator(visitor_name="Curator_Carl");
        root spawn curator;
    }
    out = buf.getvalue();

    assert "Visitor Curator_Carl entered Gallery A" in out, f"missing Gallery A generic entry: {out}";
    assert "Visitor Curator_Carl entered Gallery B" in out, f"missing Gallery B generic entry: {out}";
    assert "[OFFICIAL INSPECTION] Curator_Carl inspected Gallery A" in out, f"missing Gallery A inspection: {out}";
    assert "[OFFICIAL INSPECTION] Curator_Carl inspected Gallery B" in out, f"missing Gallery B inspection: {out}";
    assert curator.inspections == 2, f"curator should have 2 inspections, got {curator.inspections}";
    assert out.count("OFFICIAL INSPECTION") == 2, f"expected 2 inspection lines, got {out}";
}

test "curator inspection count matches number of rooms visited" {
    root ++> Room(name="R1");
    root ++> Room(name="R2");
    root ++> Room(name="R3");

    curator = Curator(visitor_name="Curator_Carl");
    root spawn curator;

    assert curator.inspections == 3, f"expected 3 inspections across three rooms, got {curator.inspections}";
}

test "tourist and curator running through the same rooms show different totals" {
    root ++> Room(name="Gallery A");
    root ++> Room(name="Gallery B");

    tourist = Visitor(visitor_name="Tourist_Tess");
    curator = Curator(visitor_name="Curator_Carl");

    root spawn tourist;
    root spawn curator;

    assert tourist.inspections == 0, f"tourist inspections should be 0, got {tourist.inspections}";
    assert curator.inspections == 2, f"curator inspections should be 2, got {curator.inspections}";
    assert curator.inspections > tourist.inspections, f"curator ({curator.inspections}) should exceed tourist ({tourist.inspections})";
}

