"""Tests for the Hotel service desks program."""

import io;
import from contextlib { redirect_stdout }

test "Alice is charged all three desk prices and total is correct" {
    spa = Desk(name="spa session", price=45.0);
    dinner = Desk(name="room-service dinner", price=28.5);
    laundry = Desk(name="express laundry", price=12.0);
    root ++> spa ++> dinner ++> laundry;

    alice = Guest(guest_name="Alice");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn alice;
        print(f"Checkout for {alice.guest_name}: owes ${alice.total_owed}");
    }
    out = buf.getvalue();

    assert alice.total_owed == 85.5, f"Alice total should be 45.0+28.5+12.0=85.5, got {alice.total_owed}";
    assert "Alice charged $45.0 for spa session" in out, f"missing spa charge line: {out}";
    assert "Alice charged $28.5 for room-service dinner" in out, f"missing dinner charge line: {out}";
    assert "Alice charged $12.0 for express laundry" in out, f"missing laundry charge line: {out}";
    assert "Checkout for Alice: owes $85.5" in out, f"missing checkout line: {out}";
}

test "Charges are printed in walk order, not desk-declaration order" {
    spa = Desk(name="spa session", price=45.0);
    dinner = Desk(name="room-service dinner", price=28.5);
    laundry = Desk(name="express laundry", price=12.0);
    root ++> spa ++> dinner ++> laundry;

    guest = Guest(guest_name="OrderCheck");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn guest;
    }
    out = buf.getvalue();

    spa_pos = out.find("spa session");
    dinner_pos = out.find("room-service dinner");
    laundry_pos = out.find("express laundry");

    assert spa_pos != -1 and dinner_pos != -1 and laundry_pos != -1, f"missing one or more charges: {out}";
    assert spa_pos < dinner_pos < laundry_pos, f"charges should appear in walk order spa->dinner->laundry, got positions {spa_pos},{dinner_pos},{laundry_pos}";

    # Final running total in last charge line should equal sum of all three prices.
    assert "(running total: $85.5)" in out, f"final running total should be 85.5, got: {out}";
}

test "Each printed charge includes a running total that grows monotonically" {
    a = Desk(name="spa session", price=45.0);
    b = Desk(name="room-service dinner", price=28.5);
    c = Desk(name="express laundry", price=12.0);
    root ++> a ++> b ++> c;

    guest = Guest(guest_name="Totals");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn guest;
    }
    out = buf.getvalue();

    # Extract running totals from each charge line: "(running total: $X)"
    import re;
    totals = [float(m) for m in re.findall(r"running total: \$([0-9.]+)", out)];
    assert len(totals) == 3, f"expected 3 running totals, got {len(totals)} from {out}";
    assert totals[0] == 45.0, f"first total should be 45.0, got {totals[0]}";
    assert totals[1] == 73.5, f"second total should be 73.5, got {totals[1]}";
    assert totals[2] == 85.5, f"third total should be 85.5, got {totals[2]}";
    # Strictly increasing.
    assert totals[0] < totals[1] < totals[2], f"running totals must strictly increase, got {totals}";
}

test "Two independent guests each get their own running total" {
    spa = Desk(name="spa session", price=45.0);
    dinner = Desk(name="room-service dinner", price=28.5);
    laundry = Desk(name="express laundry", price=12.0);
    root ++> spa ++> dinner ++> laundry;

    alice = Guest(guest_name="Alice");
    bob = Guest(guest_name="Bob");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn alice;
        print(f"Checkout for {alice.guest_name}: owes ${alice.total_owed}");
        root spawn bob;
        print(f"Checkout for {bob.guest_name}: owes ${bob.total_owed}");
    }
    out = buf.getvalue();

    # Both walkers must end with identical totals since the chain is the same.
    assert alice.total_owed == 85.5, f"Alice total should be 85.5, got {alice.total_owed}";
    assert bob.total_owed == 85.5, f"Bob total should be 85.5, got {bob.total_owed}";

    # Each guest's charges must be labelled with their own name.
    alice_lines = [l for l in out.splitlines() if "Alice" in l and "charged" in l];
    bob_lines = [l for l in out.splitlines() if "Bob" in l and "charged" in l];
    assert len(alice_lines) == 3, f"Alice should have 3 charge lines, got {len(alice_lines)}: {alice_lines}";
    assert len(bob_lines) == 3, f"Bob should have 3 charge lines, got {len(bob_lines)}: {bob_lines}";

    # Alice's checkout line should appear before Bob's (walks are sequential in the spawn calls).
    alice_checkout = out.find("Checkout for Alice: owes $85.5");
    bob_checkout = out.find("Checkout for Bob: owes $85.5");
    assert alice_checkout != -1, f"missing Alice checkout line: {out}";
    assert bob_checkout != -1, f"missing Bob checkout line: {out}";
    assert alice_checkout < bob_checkout, f"Alice's checkout should print before Bob's, got positions {alice_checkout},{bob_checkout}";
}

