"""Gallery security console: log every visitor generically, and additionally
record an official inspection when a curator walks through a room."""

node Room {
    has room_name: str = "";
    has visitor_log: list[str] = [];
    has inspection_log: list[str] = [];
}

walker Tourist {
    has tourist_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter_room with Room entry {
        here.visitor_log.append(f"Tourist {self.tourist_name}");
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_room with Room entry {
        here.visitor_log.append(f"Curator {self.curator_name}");
        here.inspection_log.append(
            f"Official inspection by {self.curator_name}"
        );
        self.rooms_inspected += 1;
        visit [-->];
    }
}

with entry {
    gallery_a = Room(room_name="Modern Art");
    gallery_b = Room(room_name="Sculpture Hall");
    root ++> gallery_a ++> gallery_b;

    tourist = Tourist(tourist_name="Alex");
    root spawn tourist;

    curator = Curator(curator_name="Dr. Bell");
    root spawn curator;

    print("--- Visitor Logs ---");
    for (idx, room) in enumerate([gallery_a, gallery_b], start=1) {
        print(f"Room {idx} ({room.room_name}):");
        for entry in room.visitor_log {
            print(f"  {entry}");
        }
    }

    print("--- Inspection Logs ---");
    for (idx, room) in enumerate([gallery_a, gallery_b], start=1) {
        print(f"Room {idx} ({room.room_name}):");
        for entry in room.inspection_log {
            print(f"  {entry}");
        }
    }

    print("--- Summary ---");
    print(f"Tourist {tourist.tourist_name} triggered generic logging only.");
    print(
        f"Curator {curator.curator_name} performed "
        f"{curator.rooms_inspected} official inspections."
    );
}
