test "bob gets charged for dinner and laundry in order" {
    root ++> Guest(name="Bob") ++> ServiceDesk(service="Room-service dinner", price=42.5) ++> ServiceDesk(service="Express laundry", price=18.0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn GuestWalker();
    }
