"""Gallery security console: generic visitor logging plus curator inspections."""

node Room {
    has name: str = "";
    has official_log: list[str] = [];

    can admit with Visitor entry {
        print(f"[LOG] {visitor.kind} entered {self.name}");
    }

    can inspect with Curator entry {
        self.official_log.append(visitor.curator_name);
        visitor.rooms_inspected += 1;
        print(f"[INSPECTION] Curator {visitor.curator_name} inspected {self.name}");
    }
}

walker Visitor {
    has kind: str = "tourist";

    can start with Root entry {
        visit [-->];
    }

    can enter_room with Room entry {
        visit [-->];
    }
}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can tour_room with Room entry {
        visit [-->];
    }
}

walker Curator {
    has curator_name: str = "Anonymous";
    has rooms_inspected: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_room with Room entry {
        visit [-->];
    }
}

with entry {
    room_a = Room(name="Gallery A");
    room_b = Room(name="Gallery B");
    root ++> room_a ++> room_b;

    tourist = Tourist();
    curator = Curator(curator_name="Dr. Sato");

    root spawn tourist;
    root spawn curator;

    print(f"\nFinal tally: curator '{curator.curator_name}' inspected "
          f"{curator.rooms_inspected} rooms; tourist triggered only the generic log.");
}
