"""Regression tests for the hospital ward doors program.

We exercise the three behaviors the spec promises:

  * Nurse and Doctor badges print when they enter a Ward.
  * FamilyVisitor enters wards silently — no staff_enter fires.
  * shift_visits increments by exactly one per ward the staff member
    walks through during a single spawn.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1) Nurse badging in prints their badge ID and the ward name.
# ---------------------------------------------------------------------------
test "nurse badge printed when entering ward" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    nurse = Nurse(badge="N-101");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
    }
    out = buf.getvalue();

    assert "N-101" in out, f"nurse badge missing from output: {out!r}";
    assert "ICU" in out, f"ICU ward name missing from output: {out!r}";
    assert "General" in out, f"General ward name missing from output: {out!r}";
    assert "badged into" in out, f"badging phrase missing: {out!r}";
}

# ---------------------------------------------------------------------------
# 2) Doctor badge prints the same way (union trigger fires for Doctor too).
# ---------------------------------------------------------------------------
test "doctor badge printed when entering ward" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn doctor;
    }
    out = buf.getvalue();

    assert "D-55" in out, f"doctor badge missing from output: {out!r}";
    assert "ICU" in out, f"ICU ward name missing: {out!r}";
    assert "General" in out, f"General ward name missing: {out!r}";
}

# ---------------------------------------------------------------------------
# 3) Family visitor walks the wards but triggers zero ward responses.
# ---------------------------------------------------------------------------
test "family visitor triggers no ward response" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn guest;
    }
    out = buf.getvalue();

    # The union trigger only fires for Nurse | Doctor, not for FamilyVisitor.
    # There must be no "badged into" line at all.
    assert "badged into" not in out, (
        f"FamilyVisitor must not trigger staff_enter, got: {out!r}"
    );
    # And the staff IDs / ward names must not leak through the silent pass.
    assert "N-101" not in out, f"unexpected nurse badge in output: {out!r}";
    assert "D-55" not in out, f"unexpected doctor badge in output: {out!r}";
}

# ---------------------------------------------------------------------------
# 4) shift_visits increments by exactly one per ward entered.
# ---------------------------------------------------------------------------
test "staff shift_visits counts wards entered" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    nurse = Nurse(badge="N-101");
    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
