    assert res.max_fare == 450.0, f"got {res.max_fare}";
    assert len(res.reports) == 3, f"got {len(res.reports)} reports";
    assert res.reports[0] == 450.0, f"got {res.reports[0]}";
    assert res.reports[1] == 320.0, f"got {res.reports[1]}";
