    # Two wards visited -> two badge lines printed.
    assert "N-101 badged into the ICU ward" in out, f"missing ICU badge line: {out!r}";
    assert "N-101 badged into the General ward" in out, f"missing General badge line: {out!r}";
    assert nurse.shift_visits == 2, f"nurse should have 2 shift visits, got {nurse.shift_visits}";
}

# ---- Doctor triggers ward ability and increments shift_visits ----
test "doctor badges in and counts ward visits" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn doctor;
    }
    out = buf.getvalue();

    assert "D-55 badged into the ICU ward" in out, f"missing ICU badge line: {out!r}";
    assert "D-55 badged into the General ward" in out, f"missing General badge line: {out!r}";
    assert doctor.shift_visits == 2, f"doctor should have 2 shift visits, got {doctor.shift_visits}";
}

# ---- FamilyVisitor triggers no ward response ----
test "family visitor triggers no ward response" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn guest;
    }
    out = buf.getvalue();

    # A plain visitor matches neither Nurse nor Doctor, so the ward's
    # union-triggered ability must NOT fire.
    assert out == "", f"family visitor should produce no output, got {out!r}";
    assert "badged into" not in out, f"unexpected badge line for visitor: {out!r}";
}

# ---- Per-ward isolation: ward_name is printed correctly per ward ----
test "each ward prints its own ward_name on staff entry" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="Cardiology") ++> Ward(ward_name="Pediatrics");

    nurse = Nurse(badge="N-202");

    buf = io.StringIO();
    with redirect_stdout(buf) {
