"""Gallery security console: every visitor is logged, curators additionally log an inspection and tally rooms inspected."""

node Room {
    has name: str = "";
    has visitor_log: list[str] = [];
}

walker Visitor {
    has visitor_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.visitor_log.append(f"visitor: {self.visitor_name}");
        print(f"[log] {self.visitor_name} entered {here.name}");
        visit [-->];
    }
}

walker Curator {
