"""Gallery security console: visitors are logged generically; curators trigger an extra official inspection per room and accumulate inspection counts."""

node Room {
    has name: str = "";
    has log: list[str] = [];
}

walker Tourist {
    has name: str = "Tourist";

    can start with Root entry {
        visit [-->];
    }

    can wander with Room entry {
        here.log.append(f"visitor: {self.name} entered");
        visit [-->] else {
            disengage;
        }
    }
}

walker Curator {
    has name: str = "Curator";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Room entry {
        here.log.append(f"visitor: {self.name} entered");
        here.log.append(f"official inspection by {self.name}");
        self.inspections += 1;
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    room_a = Room(name="Modern Art");
    room_b = Room(name="Sculpture Hall");
    root ++> room_a ++> room_b;

    tourist = Tourist(name="Alice");
    tourist spawn root;
    curator = Curator(name="Dr. Bell");
    curator spawn root;

    print(f"Room A log: {room_a.log}");
    print(f"Room B log: {room_b.log}");
    print(f"Curator {curator.name} performed {curator.inspections} official inspections");
    print(f"Tourist {tourist.name} performed 0 official inspections");
}
