"""Tests for the flight network with priced FlightLeg edges."""

import io;
import from contextlib { redirect_stdout }

# --- Test 1: fare_fraction normalizes against the peak fare ---
test "fare_fraction normalizes price against peak" {
    # Build a graph with legs of varying prices
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    root ++> jfk;
    jfk +>:FlightLeg(ticket_price=100.0, origin_code="JFK", dest_code="LAX"):+> lax;

    # Spawn a scout to find the peak fare
    scout = Scout();
    root spawn scout;

    peak = scout.peak_fare;
    leg = [edge jfk ->:FlightLeg:->][0];
    share = leg.fare_fraction(peak);
    assert share == 1.0, f"cheapest fare that is also peak should be 100%, got {share}";
}

# --- Test 2: Scout collects all leg prices and tracks peak correctly ---
test "scout reports all leg prices and finds peak" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");
    bos = Airport(code="BOS");
    root ++> jfk;

    leg1 = FlightLeg(ticket_price=450.0, origin_code="JFK", dest_code="LAX");
    jfk +>:leg1:+> lax;
    leg2 = FlightLeg(ticket_price=320.0, origin_code="LAX", dest_code="ORD");
    lax +>:leg2:+> ord;
    leg3 = FlightLeg(ticket_price=580.0, origin_code="ORD", dest_code="BOS");
    ord +>:leg3:+> bos;

    scout = Scout();
    root spawn scout;

    assert scout.peak_fare == 580.0, f"peak should be 580.0, got {scout.peak_fare}";
    assert len(scout.fare_report) == 3, f"expected 3 prices reported, got {len(scout.fare_report)}";
    assert 450.0 in scout.fare_report, "JFK->LAX price missing from report";
    assert 320.0 in scout.fare_report, "LAX->ORD price missing from report";
    assert 580.0 in scout.fare_report, "ORD->BOS price missing from report";
}

# --- Test 3: fare_fraction returns 0.0 when peak is non-positive (fail-closed) ---
test "fare_fraction returns zero for non-positive peak" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    root ++> jfk;
    jfk +>:FlightLeg(ticket_price=500.0, origin_code="JFK", dest_code="LAX"):+> lax;

    leg = [edge jfk ->:FlightLeg:->][0];

    # When peak is zero (no fares collected)
    share_zero = leg.fare_fraction(0.0);
    assert share_zero == 0.0, f"peak=0 should yield 0.0, got {share_zero}";

    # When peak is negative (defensive)
    share_neg = leg.fare_fraction(-10.0);
    assert share_neg == 0.0, f"negative peak should yield 0.0, got {share_neg}";
}

# --- Test 4: Normalized fractions printed as percentages sum to expected ratios ---
test "printed fractions reflect price ratios vs peak" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    root ++> jfk;
    jfk +>:FlightLeg(ticket_price=200.0, origin_code="JFK", dest_code="LAX"):+> lax;

    scout = Scout();
    root spawn scout;
    peak = scout.peak_fare;
    leg = [edge jfk ->:FlightLeg:->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        share = leg.fare_fraction(peak);
        print(f"{share:.2%}");
    }
    out = buf.getvalue().strip();
    assert out == "100.00%", f"expected 100.00%, got {out}";
}

# --- Test 5: Scout disengages on revisiting an airport (seen-tracking) ---
test "scout disengages on previously seen airport code" {
    # Two airports that share a code shouldn't cause double reporting
    a1 = Airport(code="AAA");
    a2 = Airport(code="AAA");  # same code - should be treated as already seen
    root ++> a1;
    a1 +>:FlightLeg(ticket_price=100.0, origin_code="AAA", dest_code="BBB"):+> a2;

    scout = Scout();
    root spawn scout;

    # Disengage on second visit means only the first leg is reported
    assert len(scout.fare_report) == 1, f"expected 1 price report, got {len(scout.fare_report)}";
    assert scout.fare_report[0] == 100.0, f"expected 100.0, got {scout.fare_report[0]}";
}

