"""Tests for the hospital ward door model.

Each test builds its own graph, spawns the relevant walkers, and asserts
on stdout (printed badge messages) plus the per-walker shift counters.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Nurse badging in prints their badge ID and increments their count.
# ---------------------------------------------------------------------------
test "nurse badge prints and increments shift visits" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    nurse = Nurse(badge="N-101");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
    }
    out = buf.getvalue();

    # Ward ability fired exactly twice (once per ward), printing the badge.
    assert out.count("N-101 badged into the ICU ward") == 1, (
        f"missing ICU badge line: {out}"
    );
    assert out.count("N-101 badged into the General ward") == 1, (
        f"missing General badge line: {out}"
    );
    # Both wards are clinical wards, so nurse visited both.
    assert nurse.shift_visits == 2, (
        f"nurse should have visited 2 wards, got {nurse.shift_visits}"
    );
}

# ---------------------------------------------------------------------------
# Test 2: Doctor behaves the same way -- union trigger fires for Doctor too.
# ---------------------------------------------------------------------------
test "doctor badge prints and increments shift visits" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    doctor = Doctor(badge="D-55");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn doctor;
    }
    out = buf.getvalue();

    assert "D-55 badged into the ICU ward" in out, (
        f"doctor ICU badge line missing: {out}"
    );
    assert "D-55 badged into the General ward" in out, (
        f"doctor General badge line missing: {out}"
    );
    assert doctor.shift_visits == 2, (
        f"doctor should have visited 2 wards, got {doctor.shift_visits}"
    );
}

# ---------------------------------------------------------------------------
# Test 3: FamilyVisitor matches neither Nurse nor Doctor -- ward stays silent.
# ---------------------------------------------------------------------------
test "family visitor triggers no ward response" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    guest = FamilyVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn guest;
    }
    out = buf.getvalue();

    # Critical promise: NO badge line is printed for the family visitor.
    assert "badged into" not in out, (
        f"family visitor should not trigger any ward response, got: {out}"
    );
    # The visitor has no badge/visit tracking fields at all.
    assert not hasattr(guest, "shift_visits"), (
        "FamilyVisitor should not carry a shift_visits counter"
    );
}

# ---------------------------------------------------------------------------
# Test 4: Two clinical staff in one graph each get their own counters.
# ---------------------------------------------------------------------------
test "nurse and doctor counters are independent across one shift" {
    root ++> Ward(ward_name="ICU") ++> Ward(ward_name="General");

    nurse = Nurse(badge="N-202");
    doctor = Doctor(badge="D-77");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
        root spawn doctor;
    }
    out = buf.getvalue();

    # Each staff member's badge appears in exactly two ward lines.
    assert out.count("N-202 badged") == 2, (
        f"nurse badge should appear twice, got: {out}"
    );
    assert out.count("D-77 badged") == 2, (
        f"doctor badge should appear twice, got: {out}"
    );

    # Counters stay scoped to the individual walker.
    assert nurse.shift_visits == 2, (
        f"nurse visited {nurse.shift_visits} wards, expected 2"
    );
    assert doctor.shift_visits == 2, (
        f"doctor visited {doctor.shift_visits} wards, expected 2"
    );
}

# ---------------------------------------------------------------------------
# Test 5: Union trigger fires for Nurse AND Doctor in the same ward graph.
# ---------------------------------------------------------------------------
test "union trigger fires for both nurse and doctor types" {
    root ++> Ward(ward_name="ICU");

    nurse = Nurse(badge="N-9");
    doctor = Doctor(badge="D-9");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn nurse;
        root spawn doctor;
    }
    out = buf.getvalue();

    # Union with Nurse | Doctor entry must accept both kinds of staff.
    assert "N-9 badged into the ICU ward" in out, (
        f"union trigger missed Nurse: {out}"
    );
    assert "D-9 badged into the ICU ward" in out, (
        f"union trigger missed Doctor: {out}"
    );
}

