"""Warehouse packing line: robots report stations they stop at; stations
report which robot they are serving. Walkers tally stops per robot and
boxes packed per station across a three-station line."""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
}

node Robot {
    has label: str = "";
    has stops: int = 0;
}

edge Serves {
    has label: str = "";
}

walker Counter {
    has robot_totals: dict = {};
    has station_totals: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can tally with Robot entry {
        self.robot_totals[here.label] = here.stops;
        visit [-->];
    }

    can count with Station entry {
        self.station_totals[here.name] = here.boxes_packed;
        visit [-->];
    }
}

with entry {
    s1 = Station(name="Pack-1", boxes_packed=12);
    s2 = Station(name="Pack-2", boxes_packed=9);
    s3 = Station(name="Pack-3", boxes_packed=15);

    r1 = Robot(label="R-A", stops=4);
    r2 = Robot(label="R-B", stops=6);
    r3 = Robot(label="R-C", stops=3);

    root ++> r1 +>:Serves(label="R-A"):+> s1;
    root ++> r2 +>:Serves(label="R-B"):+> s2;
    root ++> r3 +>:Serves(label="R-C"):+> s3;

    counter = Counter();
    root spawn counter;

    print("Stops per robot:");
    for (label, n) in counter.robot_totals.items() {
        print(f"  {label}: {n}");
    }
    print("Boxes packed per station:");
    for (name, n) in counter.station_totals.items() {
        print(f"  {name}: {n}");
    }
}
