"""Warehouse packing line: stations announce the robot they serve; robots announce each station they stop at; tally stops per robot and boxes packed per station."""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
}

node Robot {
    has name: str = "";
    has stops: int = 0;
}

edge Served {
    has order: int = 0;
}

walker RobotMover {
    has name: str = "";
    has stops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can move_to_station with Station entry {
        here.boxes_packed += 1;
        self.stops += 1;
        print(f"{self.name} stops at {here.name} (stops={self.stops})");
        visit [-->] else {
            disengage;
        }
    }
}

walker StationAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Station entry {
        print(f"{here.name} packed {here.boxes_packed} boxes");
        visit [-->];
    }
}

with entry {
    s1 = Station(name="Pack-1");
    s2 = Station(name="Pack-2");
    s3 = Station(name="Pack-3");
    root ++> s1 ++> s2 ++> s3;

    r1 = RobotMover(name="R-Atlas");
    r2 = RobotMover(name="R-Bolt");
    r1 spawn root;
    r2 spawn root;

    StationAuditor() spawn root;
}
