    assert c.boxes_packed == 2, f"c packed {c.boxes_packed}";
    assert a.last_robot == "R5" and b.last_robot == "R5" and c.last_robot == "R5",
        f"last_robot should be R5: {a.last_robot}/{b.last_robot}/{c.last_robot}";

