"""Hotel service-desk charges: guests walk past desks and each desk adds its price to the passing guest."""

node Guest {
    has name: str = "";
    has balance: float = 0.0;
}

node Desk {
    has service: str = "";
    has price: float = 0.0;
}

walker GuestWalker {
    can start with Root entry {
        visit [-->];
    }

    can walk with Guest entry {
        for d in [-->][?:Desk] {
            here.balance += d.price;
            print(f"Charge: {here.name} <- {d.service} (${d.price})");
        }
        print(f"{here.name} owes ${here.balance} at checkout");
        visit [-->] else { disengage; }
    }
}

with entry {
    alice = Guest(name="Alice", balance=0.0);
    bob = Guest(name="Bob", balance=0.0);
    spa = Desk(service="Spa session", price=80.0);
    dinner = Desk(service="Room-service dinner", price=45.0);
    laundry = Desk(service="Express laundry", price=25.0);

    root ++> alice ++> spa;
