        plate = here.plate;
        kind = here.kind;
        tons = here.tons;
        print(
            f"[G-4] {kind} {plate}"
            + (f" ({tons}t)" if kind == "truck" else "")
            + f" paid ${fare:.2f}"
        );
        visit [-->];
