"""Warehouse line: packing stations announce their robot while robots
announce every station they stop at. Count stops per robot and boxes
packed per station across a three-station line."""

node Robot {
    has name: str = "";
    has stops: int = 0;
    has boxes_packed: int = 0;
}

node Station {
    has station_name: str = "";
    has boxes_packed: int = 0;
}

walker RobotVisitor {
    has robot_name: str = "";

    can start with Root entry {
        print(f"=== Robot {self.robot_name} visiting stations ===");
        visit [-->];
    }

    can stop_at with Station entry {
        here.boxes_packed += 1;
        print(f"Robot {self.robot_name} stopped at {here.station_name} (station total: {here.boxes_packed})");
        visit [-->];
    }
}

walker StationGreeter {
    has station_name: str = "";

    can start with Root entry {
        print(f"\n=== Station {self.station_name} receiving robots ===");
        visit [-->];
    }

    can greet with Robot entry {
        print(f"Station {self.station_name} is serving Robot {here.name}");
        here.stops += 1;
        visit [-->];
    }
}

walker LineWorker {
    can start with Root entry {
        print("\n=== Summary walk ===");
        visit [-->];
    }

    can sweep with Station entry {
        print(f"Station {here.station_name} reporting: {here.boxes_packed} box(es) packed");
        visit [-->];
    }

    can audit with Robot entry {
        print(f"Robot {here.name} stopped at {here.stops} station(s)");
        visit [-->];
    }
}

with entry {
    s1 = Station(station_name="Pack-1");
    s2 = Station(station_name="Pack-2");
    s3 = Station(station_name="Pack-3");

    r1 = Robot(name="R2D2");
    r2 = Robot(name="WALL-E");
    r3 = Robot(name="BB-8");

    root ++> s1 ++> s2 ++> s3;
    s1 ++> r1;
    s2 ++> r2;
    s3 ++> r3;

    r1 spawn RobotVisitor(robot_name="R2D2");
    r2 spawn RobotVisitor(robot_name="WALL-E");
    r3 spawn RobotVisitor(robot_name="BB-8");

    s1 spawn StationGreeter(station_name="Pack-1");
    s2 spawn StationGreeter(station_name="Pack-2");
    s3 spawn StationGreeter(station_name="Pack-3");

    root spawn LineWorker();
}
