            leg_jfk_ord,
        ];
        for leg in legs {
            share = leg.fare_fraction(peak);
            print(
                f"{leg.origin_code}->{leg.dest_code} "
                f"${leg.ticket_price} is {share:.2%} of top fare"
            );
        }
    }
    out = buf.getvalue();

    assert "JFK->LAX" in out, f"missing JFK->LAX line: {out}";
    assert "LAX->ORD" in out, f"missing LAX->ORD line: {out}";
    assert "ORD->BOS" in out, f"missing ORD->BOS line: {out}";
    assert "BOS->JFK" in out, f"missing BOS->JFK line: {out}";
    assert "JFK->ORD" in out, f"missing JFK->ORD line: {out}";
    # ORD->BOS is the peak at 580.0, so its share must print as 100.00%.
    assert "100.00%" in out, f"peak leg should print 100.00%, got: {out}";
    # 275 / 580 ≈ 47.41%
    assert "47.41%" in out, f"BOS->JFK share should print 47.41%, got: {out}";
}

