"""Warehouse packing line: robots announce stations they stop at and
stations announce which robot they are serving. Tally stops per robot
and boxes packed per station across a three-station line."""

node Station {
    has name: str = "";
    has robots_served: list[str] = [];
    has boxes_packed: int = 0;

    def serve(robot_id: str, boxes: int) {
        self.robots_served.append(robot_id);
        self.boxes_packed += boxes;
    }
}

node Robot {
    has robot_id: str = "";
    has stations_visited: list[str] = [];
    has stops: int = 0;

    def stop_at(station_name: str) {
        self.stations_visited.append(station_name);
        self.stops += 1;
    }
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Station entry {
        here.serve("R-7", 3);
        visit [-->];
    }

    can log with Robot entry {
        here.stop_at("S1");
        visit [-->];
    }
}

walker Reporter {
    can start with Root entry {
        visit [-->];
    }

    can gather with Station entry {
        print(f"{here.name} packed {here.boxes_packed} boxes "
              f"for robots {here.robots_served}");
        visit [-->];
    }

    can tally with Robot entry {
        print(f"Robot {here.robot_id} stopped at "
              f"{here.stations_visited} -> {here.stops} stops");
        visit [-->];
    }
}

with entry {
    s1 = Station(name="S1");
    s2 = Station(name="S2");
    s3 = Station(name="S3");
    r7 = Robot(robot_id="R-7");

    s1 ++> s2 ++> s3;
    root ++> s1;
    root ++> r7;

    root spawn Auditor();
    root spawn Reporter();
}
