```jac
"""Rental shop media shelf audit.

Books report title + author, DVDs report title + runtime, and anything
unclassified (e.g. an old archive reel) falls through to a default handler.
The auditor walker counts total items audited and how many needed the
default path.
"""

node Book {
    has title: str = "";
    has author: str = "";
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
}

node Reel {
    has title: str = "";
    has format: str = "";
}

walker ShelfAuditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_book with Book entry {
        self.total += 1;
        print(f"Book: {here.title} by {here.author}");
        visit [-->];
    }

    can audit_dvd with DVD entry {
        self.total += 1;
        print(f"DVD: {here.title} ({here.runtime} min)");
        visit [-->];
    }

    can audit_reel with Reel entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"Default (unclassified): {here.title} [{here.format}]");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", author="Frank Herbert")
        ++> DVD(title="Blade Runner", runtime=117)
        ++> Reel(title="Newsreel 1947", format="16mm")
        ++> Book(title="Neuromancer", author="William Gibson")
        ++> DVD(title="Arrival", runtime=116);

    auditor = ShelfAuditor();
    root spawn auditor;
    print(f"Audited {auditor.total} items; {auditor.defaulted} needed the default path");
}
