"""Tests for flight network: FlightLeg.fare_fraction and Scout walker."""

import io;
import from contextlib { redirect_stdout }

test "fare_fraction returns ratio against max" {
    a = Airport(code="A");
    b = Airport(code="B");
    leg = FlightLeg(price=300.0, label="A-B");
    a +>:leg:+> b;

    # max fare in network is 450 -> 300/450 = 0.6666...
    share = leg.fare_fraction(450.0);
    assert abs(share - (300.0 / 450.0)) < 1e-9, f"got {share}";

    # equality when price equals max
    leg_top = FlightLeg(price=999.0, label="TOP");
    assert leg_top.fare_fraction(999.0) == 1.0, "top should be 1.0";

    # smallest possible fraction
    leg_zero = FlightLeg(price=0.0, label="FREE");
    assert leg_zero.fare_fraction(500.0) == 0.0, "zero price -> 0.0";
}

test "fare_fraction is fail-closed on bad max" {
    leg = FlightLeg(price=123.0, label="ANY");
    # max fare <= 0 must short-circuit to 0.0 (no ZeroDivisionError)
    assert leg.fare_fraction(0.0) == 0.0, "max=0 should return 0.0";
    assert leg.fare_fraction(-50.0) == 0.0, "negative max should return 0.0";
}

test "Scout gathers every FlightLeg price exactly once" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    sfo = Airport(code="SFO");
    ord_ = Airport(code="ORD");
    root ++> jfk;

    leg1 = FlightLeg(price=450.0, label="JFK-LAX");
    leg2 = FlightLeg(price=320.0, label="LAX-SFO");
    leg3 = FlightLeg(price=380.0, label="JFK-SFO");
    leg4 = FlightLeg(price=210.0, label="JFK-ORD");

    jfk +>:leg1:+> lax;
    lax +>:leg2:+> sfo;
    jfk +>:leg3:+> sfo;
    jfk +>:leg4:+> ord_;

    res = jfk spawn Scout();

    # Scout on Airport reports all outgoing FlightLeg prices, then visits
    # further airports. JFK has 3 outgoing legs (450, 380, 210). LAX has 1
    # outgoing (320). ORD and SFO have none. SFO is reached but has no
    # outgoing legs so reports nothing extra; ORD same. Total = 4 reports.
    assert len(res.reports) == 4, f"expected 4 fare reports, got {res.reports}";
    assert 450.0 in res.reports, "missing 450.0";
    assert 380.0 in res.reports, "missing 380.0";
    assert 320.0 in res.reports, "missing 320.0";
    assert 210.0 in res.reports, "missing 210.0";
}

test "end-to-end: peak fare and printed fractions" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    sfo = Airport(code="SFO");
    root ++> jfk;

    leg_a = FlightLeg(price=450.0, label="JFK-LAX");
    leg_b = FlightLeg(price=320.0, label="LAX-SFO");
    leg_c = FlightLeg(price=380.0, label="JFK-SFO");

    jfk +>:leg_a:+> lax;
    lax +>:leg_b:+> sfo;
    jfk +>:leg_c:+> sfo;

    scout = Scout();
    res = jfk spawn scout;

    # Peak fare must be the max reported value, 450.0.
    max_fare = 0.0;
    for fare in res.reports {
        if fare > max_fare {
            max_fare = fare;
        }
    }
    assert max_fare == 450.0, f"peak fare should be 450.0, got {max_fare}";

    # Drive the same normalization the entry block does and check printed
    # output captures each leg's share of the peak.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        network_legs = [leg_a, leg_b, leg_c];
        for leg in network_legs {
            share = leg.fare_fraction(max_fare);
            print(f"{leg.label}: {share:.2f} of peak fare (${leg.price} / ${max_fare})");
        }
    }
    out = buf.getvalue();

    # JFK-LAX is the peak leg itself: share = 1.00.
    assert "JFK-LAX: 1.00 of peak fare" in out, f"missing JFK-LAX peak line in: {out}";
    # LAX-SFO: 320/450 = 0.71
    assert "LAX-SFO: 0.71 of peak fare" in out, f"missing LAX-SFO line in: {out}";
    # JFK-SFO: 380/450 = 0.84
    assert "JFK-SFO: 0.84 of peak fare" in out, f"missing JFK-SFO line in: {out}";
}

