"""Rental shop media shelf audit.

Books and DVDs have specialized audit handling; anything else (e.g. an
old archive reel) falls through to a default ability. A union trigger
serves the two classified media types, while the default path is its
own ability so the count of unclassified items is observable.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has available: bool = True;
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has available: bool = True;
}

# An unclassified item (e.g. an archive reel) has no specialized node
# type, so no specialized ability fires for it on the auditor.
node ArchiveReel {
    has label: str = "";
}

walker Auditor {
    has total_audited: int = 0;
    has default_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can shelve with Book | DVD entry {
        if here.title == "" {
            # Title missing — treat as unclassified.
            self.default_count += 1;
        } else {
            print(f"Shelved: {here.title} "
                  f"({'author=' + here.author if isinstance(here, Book) else 'runtime=' + str(here.runtime) + 'min'})");
        }
        self.total_audited += 1;
        visit [-->];
    }

    can fallback with ArchiveReel entry {
        print(f"Default path: unclassified item '{here.label}'");
        self.default_count += 1;
        self.total_audited += 1;
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", author="Frank Herbert", available=False)
        ++> DVD(title="Blade Runner", runtime=117, available=True)
        ++> ArchiveReel(label="Reel #42")
        ++> Book(title="Neuromancer", author="William Gibson")
        ++> DVD(title="Arrival", runtime=116)
        ++> ArchiveReel(label="Reel #7");

    auditor = Auditor();
    root spawn auditor;

    print(f"Audited {auditor.total_audited} items; "
          f"{auditor.default_count} needed the default path.");
}
