"""Warehouse line: packing stations announce serving robots; robots log every stop.

Counts stops per robot and boxes packed per station across a three-station line.
"""

node Station {
    has name: str = "";
    has boxes_packed: int = 0;
}

node Robot {
    has label: str = "";
}

edge Serves {
    has note: str = "";
}

walker AnnounceStation {
    has from_robot: str = "";

    can start with Root entry {
        visit [-->];
    }

    can greet with Station entry {
        here.boxes_packed += 1;
        announcement = f"{here.name} is serving robot {self.from_robot}";
        print(announcement);
        visit [-->];
    }
}

walker AnnounceRobot {
    has robot_label: str = "";
    has stops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can log with Station entry {
        self.stops += 1;
        announcement = f"Robot {self.robot_label} stopped at {here.name}";
        print(announcement);
        visit [-->];
    }
}

with entry {
    s1 = Station(name="Pack-A");
    s2 = Station(name="Pack-B");
    s3 = Station(name="Pack-C");
    root ++> s1 ++> s2 ++> s3;

    r1 = Robot(label="R-01");
    r2 = Robot(label="R-02");

    a1 = AnnounceStation(from_robot=r1.label);
    a2 = AnnounceStation(from_robot=r2.label);
    b1 = AnnounceRobot(robot_label=r1.label);
    b2 = AnnounceRobot(robot_label=r2.label);

    root spawn a1;
    root spawn a2;
    root spawn b1;
    root spawn b2;

    print(f"S1 packed={s1.boxes_packed}, S2 packed={s2.boxes_packed}, S3 packed={s3.boxes_packed}");
    print(f"R1 stops={b1.stops}, R2 stops={b2.stops}");
}
