"""Rental shop media audit.

Books and DVDs each get a specialized audit message. Anything else on
the shelf (a misfiled archive reel, say) falls through to the default
audit path. We track the total items audited and how many took the
default branch.
"""

node Book {
    has title: str = "";
    has author: str = "";
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
}

# A catch-all node archetype for unclassified media (e.g. archive reels).
node Misc {
    has label: str = "";
}

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # Specialized handlers for classified media.
    can audit_book with Book entry {
        self.total += 1;
        print(f"Book: \"{here.title}\" by {here.author}");
        visit [-->];
    }

    can audit_dvd with DVD entry {
        self.total += 1;
        print(f"DVD: \"{here.title}\" ({here.runtime} min)");
        visit [-->];
    }

    # Default fallback: anything not a Book or DVD.
    can audit_misc with Misc entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"Unclassified: \"{here.label}\" (default audit path)");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", author="Frank Herbert")
        ++> DVD(title="Blade Runner", runtime=117)
        ++> Misc(label="Archive Reel #14")
        ++> Book(title="Neuromancer", author="William Gibson")
        ++> DVD(title="Arrival", runtime=116)
        ++> Misc(label="VHS Sampler");

    a = Auditor();
    root spawn a;

    print(f"Audited {a.total} item(s); {a.defaulted} needed the default path.");
}
