"""Toll plaza G-4: classify vehicles by type, charge per type, report revenue."""

node Vehicle {
    has label: str = "";
    has rate: float = 0.0;
    has tons: float = 0.0;

    def charge() -> float {
        return self.rate + 0.50 * self.tons;
    }

    def describe(amount: float) -> None {
        if self.tons > 0.0 {
            print(f"{self.label}: paid ${amount:.2f} (rate ${self.rate:.2f} + 0.50*{self.tons}t)");
        } else {
            print(f"{self.label}: paid ${amount:.2f}");
        }
    }
}

walker Collector {
    has revenue: float = 0.0;

    can start with Root entry {
        print("Gate G-4 sweep begin");
        visit [-->];
    }

    can toll with Vehicle entry {
        amount = here.charge();
        here.describe(amount);
        self.revenue = self.revenue + amount;
        visit [-->];
    }
}

with entry {
    root ++> Vehicle(label="Car", rate=2.50)
        ++> Vehicle(label="Truck", rate=2.50, tons=3.0)
        ++> Vehicle(label="Motorcycle", rate=1.00)
        ++> Vehicle(label="Truck", rate=2.50, tons=1.5);
    c = Collector();
    root spawn c;
    print(f"Gate G-4 total revenue: ${c.revenue:.2f}");
}
