    assert "Car: paid $2.50" in out, f"car line missing or wrong: {out}";
    assert "Motorcycle: paid $1.00" in out, f"motorcycle line missing or wrong: {out}";
    # Truck 2.50 + 0.50*3.0 = 4.00
    assert "Truck: paid $4.00" in out, f"truck line missing or wrong: {out}";
    assert "rate $2.50 + 0.50*3.0t" in out, f"truck breakdown missing: {out}";
}

