"""Rental shop media audit.

Books, DVDs, and unclassified archive items share an audit walker.
A union ability handles Book and DVD with typed output; a fallback
ability catches anything else (e.g. ArchiveReel) and counts it as
default-handled.
"""

node Book {
    has title: str = "";
    has author: str = "";
    has kind: str = "BOOK";

    def show() -> str {
        return f"[BOOK]  {self.title} by {self.author}";
    }
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
    has kind: str = "DVD";

    def show() -> str {
        return f"[DVD]   {self.title} ({self.runtime} min)";
    }
}

node ArchiveReel {
    has label: str = "";
    has kind: str = "ARCHIVE";

    def show() -> str {
        return f"[ARCHIVE] unclassified item reached default handler";
    }
}

edge Shelved { has section: str = ""; }

walker Auditor {
    has total: int = 0;
    has default_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can catalog with Book | DVD entry {
        self.total += 1;
        print(here.show());
        visit [-->];
    }

    can fallback with ArchiveReel entry {
        # Default path: any unclassified shelf item falls through here.
        self.default_count += 1;
        print(here.show());
        visit [-->];
    }
}

with entry {
    b1 = Book(title="Dune", author="Frank Herbert");
    b2 = Book(title="Neuromancer", author="William Gibson");
    d1 = DVD(title="Blade Runner", runtime=117);
    d2 = DVD(title="Arrival", runtime=116);
    reel = ArchiveReel(label="Reel #7");

    root +>:Shelved(section="Fiction"):+> b1;
    root +>:Shelved(section="Fiction"):+> b2;
    root +>:Shelved(section="Movies"):+> d1;
    root +>:Shelved(section="Movies"):+> d2;
    root +>:Shelved(section="Archive"):+> reel;

    auditor = Auditor();
    root spawn auditor;

    print(f"Audited {auditor.total} items; {auditor.default_count} needed the default path");
}
