```jac
"""Rental shop media shelf audit.

Books expose title and author, DVDs expose title and runtime, and any
unclassified item (an old archive reel, say) falls through to a default
path. A union ability handles the two classified media types; a separate
ability catches the unclassified leftovers. The walker counts total items
audited and how many needed the default path.
"""

node Media {
    has title: str = "";
    has available: bool = True;
}

node Book(Media) {
    has author: str = "";
}

node DVD(Media) {
    has runtime: int = 0;
}

node Reel(Media) {
    has format: str = "";
}

walker Auditor {
    has total: int = 0;
    has default_count: int = 0;

    can start with Root entry {
        print("Starting shelf audit...");
        visit [-->] else { disengage; }
    }

    can shelve with Book | DVD entry {
        self.total += 1;
        status = "IN" if here.available else "OUT";
        if isinstance(here, Book) {
            print(f"[{status}] Book: {here.title} by {here.author}");
        } else {
            print(f"[{status}] DVD: {here.title} ({here.runtime} min)");
        }
        visit [-->] else { disengage; }
    }

    can fallback with Reel entry {
        self.total += 1;
        self.default_count += 1;
        print(f"[DEFAULT] {here.title} (reel, {here.format}) - unclassified");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Book(title="The Hobbit", author="Tolkien", available=True)
        ++> Book(title="Dune", author="Herbert", available=False)
        ++> DVD(title="Inception", runtime=148, available=True)
        ++> DVD(title="Blade Runner", runtime=117, available=True)
        ++> Reel(title="Archive-1972", format="16mm", available=False);

    auditor = Auditor();
    root spawn auditor;

    print(f"\nAudit complete: {auditor.total} items audited, {auditor.default_count} needed the default path.");
}
```

