        return self.title;
    }

    def media_year() -> int {
        return self.year;
    }
}

node Book(Media) {
    has author: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    override def media_title() -> str {
        return self.title;
    }

    override def media_year() -> int {
        return self.year;
    }
}

node DVD(Media) {
    has runtime: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    override def media_title() -> str {
        return self.title;
    }

    override def media_year() -> int {
        return self.year;
    }
}

node ArchiveReel(Media) {
    has label: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    override def media_title() -> str {
        return self.title;
    }

    override def media_year() -> int {
        return self.year;
    }
}

walker Auditor {
