"""Orchard maintenance: a crew walker tours groves servicing pumps and sprinklers."""

node Pump {
    has label: str = "";
    has idle_hours: int = 0;

    def service() -> int {
        logged = self.idle_hours;
        print(f"[PUMP] {self.label} idle for {logged}h — counter reset");
        self.idle_hours = 0;
        return logged;
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;

    def service() -> int {
        logged = self.idle_hours;
        print(f"[SPRINKLER] {self.label} idle for {logged}h — counter reset");
        self.idle_hours = 0;
        return logged;
    }
}

walker Crew {
    has total_serviced: int = 0;
    has total_hours: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tour with Pump | Sprinkler entry {
        hours = here.service();
        self.total_serviced += 1;
        self.total_hours += hours;
        visit [-->];
    }
}

with entry {
    root ++> Pump(label="Pump-A", idle_hours=12)
        ++> Sprinkler(label="Sprinkler-B", idle_hours=4)
        ++> Pump(label="Pump-C", idle_hours=7)
        ++> Sprinkler(label="Sprinkler-D", idle_hours=0);

    crew = Crew();
    root spawn crew;

    print(f"Crew serviced {crew.total_serviced} devices, "
          f"total idle hours cleared: {crew.total_hours}");
}
