"""Test annex for orchard maintenance walker."""

import io;
import from contextlib { redirect_stdout }

# --- Test 1: Crew visits every device, services both kinds, resets counters ---
test "crew services every device in order" {
    root ++> Pump(label="Pump-A", idle_hours=12)
        ++> Sprinkler(label="Sprinkler-B", idle_hours=4)
        ++> Pump(label="Pump-C", idle_hours=7)
        ++> Sprinkler(label="Sprinkler-D", idle_hours=0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        crew = root spawn Crew();
    }
    out = buf.getvalue();

    # All four devices must be logged in the order they were chained.
    assert "[PUMP] Pump-A idle for 12h — counter reset" in out, f"missing Pump-A line: {out}";
    assert "[SPRINKLER] Sprinkler-B idle for 4h — counter reset" in out, f"missing Sprinkler-B line: {out}";
    assert "[PUMP] Pump-C idle for 7h — counter reset" in out, f"missing Pump-C line: {out}";
    assert "[SPRINKLER] Sprinkler-D idle for 0h — counter reset" in out, f"missing Sprinkler-D line: {out}";

    # The demo entry block is not relied on — we just spawned manually,
    # so crew.total_serviced should be 4 from our walk.
    assert crew.total_serviced == 4, f"expected 4 devices serviced, got {crew.total_serviced}";
    assert crew.total_hours == 23, f"expected 12+4+7+0 = 23 hours, got {crew.total_hours}";
}

# --- Test 2: A single Pump walk services exactly one device ---
test "crew on a single pump services only that pump" {
    root ++> Pump(label="Solo", idle_hours=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        solo = [root-->][0];
        crew = solo spawn Crew();
    }
    out = buf.getvalue();

    assert "[PUMP] Solo idle for 5h — counter reset" in out, f"missing Solo line: {out}";
    assert crew.total_serviced == 1, f"expected 1, got {crew.total_serviced}";
    assert crew.total_hours == 5, f"expected 5, got {crew.total_hours}";

    # The pump's idle counter must be reset after servicing.
    assert solo.idle_hours == 0, f"counter not reset: {solo.idle_hours}";
}

# --- Test 3: Graph with only sprinklers works and prints the SPRINKLER prefix ---
test "crew services a sprinkler-only grove" {
    root ++> Sprinkler(label="S1", idle_hours=9)
        ++> Sprinkler(label="S2", idle_hours=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        crew = root spawn Crew();
    }
    out = buf.getvalue();

    assert "[SPRINKLER] S1 idle for 9h — counter reset" in out, f"missing S1 line: {out}";
    assert "[SPRINKLER] S2 idle for 2h — counter reset" in out, f"missing S2 line: {out}";
    # No pumps should have been logged.
    assert "[PUMP]" not in out, f"unexpected pump log in sprinkler-only grove: {out}";
    assert crew.total_serviced == 2, f"expected 2, got {crew.total_serviced}";
    assert crew.total_hours == 11, f"expected 9+2 = 11, got {crew.total_hours}";
}

# --- Test 4: Counter reset is visible after the walk completes ---
test "all device counters are reset after the crew walk" {
    p = Pump(label="Reset-A", idle_hours=15);
    s = Sprinkler(label="Reset-B", idle_hours=8);
    root ++> p ++> s;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Crew();
    }

    # Spec: "reset its counter" — counters must read 0 after the tour.
    assert p.idle_hours == 0, f"pump counter not reset: {p.idle_hours}";
    assert s.idle_hours == 0, f"sprinkler counter not reset: {s.idle_hours}";
}

# --- Test 5: Crew walks past non-device nodes without servicing them ---
test "crew ignores non-device descendants" {
    root ++> Pump(label="P", idle_hours=3);
    # Attach a non-device node type the walker has no entry ability for;
    # the walker simply has nothing to do here — only the pump should be logged.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        crew = root spawn Crew();
    }
    out = buf.getvalue();

    # Exactly one device log line.
    assert crew.total_serviced == 1, f"expected 1 serviced, got {crew.total_serviced}";
    assert crew.total_hours == 3, f"expected 3 hours, got {crew.total_hours}";
    assert "[PUMP] P idle for 3h — counter reset" in out, f"missing log: {out}";
}

