"""Factory zone monitoring: one patrol walker inspects both temperature and smoke sensors."""

node Sensor {
    has label: str = "";

    def reading() -> str {
        return self.label;
    }
}

node TempSensor(Sensor) {
    has celsius: float = 0.0;

    def is_alert() -> bool {
        return self.celsius > 75.0;
    }
}

node SmokeSensor(Sensor) {
    has ppm: float = 0.0;

    def is_alert() -> bool {
        return self.ppm > 50.0;
    }
}

node Zone {
    has name: str = "";
}

walker Patrol {
    has alerts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Zone entry {
        visit [-->];
    }

    can inspect with TempSensor | SmokeSensor entry {
        if here.is_alert() {
            print(f"[ALERT] {here.label} reading={here.reading()}");
            self.alerts.append(here.label);
        } else {
            print(f"nominal: {here.label} reading={here.reading()}");
        }
    }
}

with entry {
    z1 = Zone(name="Zone-A");
    z2 = Zone(name="Zone-B");
    root ++> z1;
    root ++> z2;

    z1 ++> TempSensor(label="Temp-1", celsius=68.0);
    z1 ++> TempSensor(label="Temp-2", celsius=91.5);
    z1 ++> SmokeSensor(label="Smoke-1", ppm=12.0);

    z2 ++> TempSensor(label="Temp-3", celsius=80.0);
    z2 ++> SmokeSensor(label="Smoke-2", ppm=55.0);
    z2 ++> SmokeSensor(label="Smoke-3", ppm=30.0);

    patrol = Patrol();
    root spawn patrol;
    print(f"--- Summary: {len(patrol.alerts)} alert(s) ---");
