test "mixed zones produce correct alert summary across both sensor types" {
    za = Zone(name="Zone A");
    zb = Zone(name="Zone B");
    root ++> za ++> zb;

    za ++> TempSensor(label="Boiler-1", celsius=91.5);
    za ++> SmokeSensor(label="Vent-1", ppm=12.0);
    zb ++> TempSensor(label="Boiler-2", celsius=62.0);
    zb ++> SmokeSensor(label="Vent-2", ppm=73.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Patrol();
    }
    out = buf.getvalue();

    # Both zones must be visited and produce the right number of readings.
    temp_lines = [l for l in out.splitlines() if ("Boiler-1" in l or "Boiler-2" in l)];
    smoke_lines = [l for l in out.splitlines() if ("Vent-1" in l or "Vent-2" in l)];
    assert len(temp_lines) == 2, f"expected 2 temp readings, got {len(temp_lines)}: {out}";
    assert len(smoke_lines) == 2, f"expected 2 smoke readings, got {len(smoke_lines)}: {out}";

    # Exactly the two over-threshold sensors should be in the alert list.
    assert len(res.alerts) == 2, f"expected 2 alerts, got {len(res.alerts)}: {res.alerts}";

    alert_text = " ".join(res.alerts);
    assert "91.5C" in alert_text, f"Boiler-1 alert missing from summary: {alert_text}";
    assert "73.0ppm" in alert_text, f"Vent-2 alert missing from summary: {alert_text}";
    assert "12.0" not in alert_text, f"Vent-1 (12.0 ppm) should not be in alerts: {alert_text}";
    assert "62.0" not in alert_text, f"Boiler-2 (62.0 C) should not be in alerts: {alert_text}";

    # Union trigger must fire on both sensor types.
    for alert_label in res.alerts {
        assert "reading" in alert_label, f"alert format unexpected: {alert_label}";
        assert ("C" in alert_label) or ("ppm" in alert_label), f"alert missing unit: {alert_label}";
    }
