"""Orchard maintenance: tour groves and service irrigation devices with a shared routine."""

node Pump {
    has label: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;

    def log_and_reset() -> int {
        kind = "Pump";
        print(f"[{kind}] {self.label} idled {self.idle_hours}h -> counter reset");
        prior = self.idle_hours;
        self.idle_hours = 0;
        self.serviced = True;
        return prior;
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;

    def log_and_reset() -> int {
        kind = "Sprinkler";
        print(f"[{kind}] {self.label} idled {self.idle_hours}h -> counter reset");
        prior = self.idle_hours;
        self.idle_hours = 0;
        self.serviced = True;
        return prior;
    }
}

node IrrigationDevice {
    has label: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;

    def log_and_reset() -> int {
        kind = "Device";
        print(f"[{kind}] {self.label} idled {self.idle_hours}h -> counter reset");
        prior = self.idle_hours;
        self.idle_hours = 0;
        self.serviced = True;
        return prior;
    }
}

walker Crew {
    has devices_serviced: int = 0;

    can start with Root entry {
        print("Crew beginning grove tour");
        visit [-->];
    }

    # Single union ability covers every irrigation device archetype.
    can service with Pump | Sprinkler | IrrigationDevice entry {
        idle = here.log_and_reset();
        self.devices_serviced += 1;
        report idle;
        visit [-->];
    }
}

with entry {
    root ++> Pump(label="Pump-A", idle_hours=14)
        ++> Sprinkler(label="Sprink-B", idle_hours=3)
        ++> IrrigationDevice(label="Drip-C", idle_hours=27)
        ++> Pump(label="Pump-D", idle_hours=9);

    crew = Crew();
    root spawn crew;
    print(f"Crew serviced {crew.devices_serviced} devices");
}
