```jac
"""Game account moderation sweep.

Member accounts are audited normally, admin accounts get their
reputation boosted by 5, and the welcome desk greets every bot
passing through no matter what kind of walker it is.
"""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reputation: int = 0;
    has role: str = "member";

    def is_admin() -> bool {
        return self.role == "admin";
    }
}

node Bot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has model: str = "";
}

walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Account entry {
        if here.is_admin() {
            here.reputation += 5;
            print(f"[ADMIN BOOST] {here.title} -> rep {here.reputation}");
        } else {
            print(f"[AUDIT] {here.title} rep={here.reputation}");
        }
        visit [-->];
    }
}

walker Greeter {
    can start with Root entry {
        visit [-->];
    }

    can greet with Bot | Account entry {
        print(f"[WELCOME] bot-style greeting for {here.title}");
        visit [-->];
    }
}

with entry {
    player1 = Account(title="alice", role="member", reputation=10);
    player2 = Account(title="bob", role="admin", reputation=20);
    mod_bot = Bot(title="ModBot-1", model="v2");
    root ++> player1 ++> player2 ++> mod_bot;

    print("--- Auditor sweep ---");
    root spawn Auditor();

    print("--- Greeter sweep ---");
    root spawn Greeter();
}
```

jac_tests:
"""Test annex for the moderation sweep program."""

import io;
import from contextlib { redirect_stdout }

test "Auditor boosts admin reputation by 5 and leaves member alone" {
    root spawn Auditor();

    alice = Account(title="alice", role="member", reputation=10);
    bob = Account(title="bob", role="admin", reputation=20);
    root ++> alice ++> bob;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    # Only members printed on the member side; the printed audit rep for
    # alice must match her starting reputation (no boost).
    assert "[AUDIT] alice rep=10" in out, f"expected alice unboosted audit, got: {out!r}";
    # Admin gets +5 and the dedicated marker line.
    assert "[ADMIN BOOST] bob -> rep 25" in out, f"expected admin boost to 25, got: {out!r}";
    # Confirm the mutation persisted on the graph node.
    assert bob.reputation == 25, f"bob.reputation should be 25, got {bob.reputation}";
    assert alice.reputation == 10, f"alice.reputation should be unchanged 10, got {alice.reputation}";
    # Sanity: is_admin() must agree with what Auditor decided.
    assert alice.is_admin() == False, "alice should not be admin";
    assert bob.is_admin() == True, "bob should be admin";
}

test "Auditor traversal visits every account exactly once" {
    root spawn Auditor();

    a1 = Account(title="a1", role="member", reputation=1);
    a2 = Account(title="a2", role="admin", reputation=2);
    a3 = Account(title="a3", role="member", reputation=3);
    a4 = Account(title="a4", role="admin", reputation=4);
    root ++> a1 ++> a2 ++> a3 ++> a4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    # Each account must appear in exactly one line of the sweep output.
    for t in ["a1", "a2", "a3", "a4"] {
        # Count occurrences of this title across both marker flavors.
        n_audit = out.count(f"[AUDIT] {t} ");
        n_boost = out.count(f"[ADMIN BOOST] {t} ");
        total = n_audit + n_boost;
        assert total == 1, f"{t} should be visited exactly once, got {total} in: {out!r}";
    }

    # Member vs admin classification must be honored on every node.
    assert "[AUDIT] a1 rep=1" in out, f"a1 is a member, got: {out!r}";
    assert "[ADMIN BOOST] a2 -> rep 7" in out, f"a2 admin boost wrong, got: {out!r}";
    assert "[AUDIT] a3 rep=3" in out, f"a3 is a member, got: {out!r}";
    assert "[ADMIN BOOST] a4 -> rep 9" in out, f"a4 admin boost wrong, got: {out!r}";

    # Final reputation reflects the boost on admins only.
    assert a1.reputation == 1, f"a1 unchanged, got {a1.reputation}";
    assert a2.reputation == 7, f"a2 should be 2+5, got {a2.reputation}";
    assert a3.reputation == 3, f"a3 unchanged, got {a3.reputation}";
    assert a4.reputation == 9, f"a4 should be 4+5, got {a4.reputation}";
}

test "Greeter greets every Bot and every Account regardless of walker kind" {
    root spawn Greeter();

    # Build a mixed graph: Account nodes (members AND admins) and Bot nodes.
    alice = Account(title="alice", role="member", reputation=10);
    bob = Account(title="bob", role="admin", reputation=20);
    mod_bot = Bot(title="ModBot-1", model="v2");
    helper = Bot(title="Helper-9", model="v1");
    root ++> alice ++> bob ++> mod_bot ++> helper;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Greeter();
    }
    out = buf.getvalue();

    # Welcome desk must greet *every* node it can match: each Account AND
    # each Bot, irrespective of role, reputation, or model.
    assert "[WELCOME] bot-style greeting for alice" in out, f"alice not greeted: {out!r}";
    assert "[WELCOME] bot-style greeting for bob" in out, f"bob (admin) not greeted: {out!r}";
    assert "[WELCOME] bot-style greeting for ModBot-1" in out, f"ModBot-1 not greeted: {out!r}";
    assert "[WELCOME] bot-style greeting for Helper-9" in out, f"Helper-9 not greeted: {out!r}";

    # Exactly one greeting per node — the visitor walks the chain once.
    for t in ["alice", "bob", "ModBot-1", "Helper-9"] {
        n = out.count(f"[WELCOME] bot-style greeting for {t}");
        assert n == 1, f"{t} should be greeted exactly once, got {n} in: {out!r}";
    }
}

test "Greeter does not boost reputation and leaves Bot fields untouched" {
    root spawn Greeter();

    alice = Account(title="alice", role="member", reputation=42);
    bob = Account(title="bob", role="admin", reputation=99);
    mod_bot = Bot(title="ModBot-1", model="v2");
    root ++> alice ++> bob ++> mod_bot;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Greeter();
    }
    out = buf.getvalue();

    # Greeting must NOT touch reputation (that's Auditor's job).
    assert alice.reputation == 42, f"alice rep must stay 42, got {alice.reputation}";
    assert bob.reputation == 99, f"bob rep must stay 99, got {bob.reputation}";

    # Greeting must NOT mutate Bot fields like model.
    assert mod_bot.model == "v2", f"Bot model must stay 'v2', got {mod_bot.model!r}";
    assert mod_bot.title == "ModBot-1", f"Bot title must stay 'ModBot-1', got {mod_bot.title!r}";

    # No audit / boost markers should leak from a Greeter run.
    assert "[AUDIT]" not in out, f"Greeter should not print AUDIT lines: {out!r}";
    assert "[ADMIN BOOST]" not in out, f"Greeter should not print ADMIN BOOST lines: {out!r}";
}

