"""Orchard maintenance: walk groves servicing pumps and sprinklers with one shared routine."""

node Device {
    has name: str = "";
    has idle_hours: int = 0;
    has serviced: bool = False;

    def kind() -> str {
        return "Device";
    }
}

node Pump(Device) {
    has pressure_psi: float = 0.0;

    override def kind() -> str {
        return "Pump";
    }
}

node Sprinkler(Device) {
    has radius_m: float = 0.0;

    override def kind() -> str {
        return "Sprinkler";
    }
}

edge InGrove {
    has plot: str = "";
}

walker Technician {
    has crew: str = "Field Ops";
    has serviced_count: int = 0;

    can start with Root entry {
        print(f"Crew '{self.crew}' beginning grove sweep");
        visit [-->];
    }

    can enter_grove with Device entry {
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        device_kind = here.kind();
        idle = here.idle_hours;
        print(f"[SERVICED] {device_kind} '{here.name}' was idle {idle} hours");
        here.idle_hours = 0;
        here.serviced = True;
        self.serviced_count += 1;
    }
}

with entry {
    pump_a = Pump(name="Pump-A", idle_hours=12, pressure_psi=45.0);
    pump_b = Pump(name="Pump-B", idle_hours=3, pressure_psi=50.0);
    sprinkler_a = Sprinkler(name="Sprinkler-A", idle_hours=20, radius_m=3.5);
    sprinkler_b = Sprinkler(name="Sprinkler-B", idle_hours=8, radius_m=4.0);
    sprinkler_c = Sprinkler(name="Sprinkler-C", idle_hours=15, radius_m=2.8);

    root ++> pump_a
        ++> pump_b
        ++> sprinkler_a
        ++> sprinkler_b
        ++> sprinkler_c;

    tech = Technician(crew="Blue Crew");
    root spawn tech;

    print(f"Total devices serviced: {tech.serviced_count}");
}
