"""Game account moderation sweep.

Members are audited normally, admins get a +5 reputation boost, and the
welcome desk greets every bot regardless of which walker type arrives.
"""

node Account {
    has handle: str = "";
    has reputation: int = 0;
}

node Member(Account) {}

node Admin(Account) {}

node WelcomeDesk {
    has greeting: str = "Welcome to the lobby!";

    can greet_bots with Bot | PatrolBot | AuditBot entry {
        print(self.greeting);
    }
}

walker Bot {
    can start with Root entry {
        visit [-->];
    }

    can wander with WelcomeDesk entry {
        visit [-->];
    }
}

walker PatrolBot {
    can start with Root entry {
        visit [-->];
    }

    can patrol with WelcomeDesk entry {
        visit [-->];
    }
}

walker AuditBot {
    has boost: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can greet with WelcomeDesk entry {
        visit [-->];
    }

    can audit with Member entry {
        print(f"Auditing member {here.handle} (rep={here.reputation})");
        visit [-->];
    }

    can boost_admin with Admin entry {
        new_rep = here.reputation + 5;
        here.reputation = new_rep;
        self.boost += 1;
        print(f"Boosted admin {here.handle} -> rep={here.reputation}");
        visit [-->];
    }
}

with entry {
    desk = WelcomeDesk();
    alice = Member(handle="alice", reputation=10);
    bob = Member(handle="bob", reputation=20);
    carol = Admin(handle="carol", reputation=50);

    root ++> desk ++> alice ++> bob ++> carol;

    bot = Bot();
    root spawn bot;

    patrol = PatrolBot();
    root spawn patrol;

    auditor = AuditBot();
    root spawn auditor;

    print(f"AuditBot applied {auditor.boost} admin boost(s)");
}
```

