"""Tests for the game account moderation sweep."""

import io;
import from contextlib { redirect_stdout }

test "member audit reports current reputation" {
    root ++> Member(handle="alice", reputation=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = AuditBot();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "Auditing member alice (rep=10)" in out, f"missing audit line: {out}";
    assert auditor.boost == 0, f"expected 0 boosts for member-only graph, got {auditor.boost}";
}

test "admin gets +5 reputation and walker boost counter increments" {
    root ++> Admin(handle="carol", reputation=50);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = AuditBot();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "Boosted admin carol -> rep=55" in out, f"missing boost line: {out}";
    assert auditor.boost == 1, f"expected 1 boost recorded, got {auditor.boost}";

    # Walk back to the Admin node and confirm its reputation was mutated.
    carol = [root -->][?Admin][0];
    assert carol.reputation == 55, f"expected admin rep=55, got {carol.reputation}";
}

test "mixed sweep: members audited, admins boosted, counts are exact" {
    desk = WelcomeDesk();
    alice = Member(handle="alice", reputation=10);
    bob = Member(handle="bob", reputation=20);
    carol = Admin(handle="carol", reputation=50);
    dave = Admin(handle="dave", reputation=40);
    root ++> desk ++> alice ++> bob ++> carol ++> dave;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = AuditBot();
        root spawn auditor;
    }
    out = buf.getvalue();

    # Every member must be audited with its current reputation.
    assert "Auditing member alice (rep=10)" in out, f"missing alice audit: {out}";
    assert "Auditing member bob (rep=20)" in out, f"missing bob audit: {out}";

    # Every admin must be boosted by exactly 5.
    assert "Boosted admin carol -> rep=55" in out, f"missing carol boost: {out}";
    assert "Boosted admin dave -> rep=45" in out, f"missing dave boost: {out}";

    # The walker must record exactly as many boosts as admins in the graph.
    assert auditor.boost == 2, f"expected 2 admin boosts, got {auditor.boost}";

    # Membership audit lines should not carry any admin boost markers and vice versa.
    audit_lines = [l for l in out.splitlines() if l.startswith("Auditing member ")];
    boost_lines = [l for l in out.splitlines() if l.startswith("Boosted admin ")];
    assert len(audit_lines) == 2, f"expected 2 audit lines, got {len(audit_lines)}: {out}";
    assert len(boost_lines) == 2, f"expected 2 boost lines, got {len(boost_lines)}: {out}";
}

test "welcome desk greets Bot" {
