"""Vet clinic round: pets as nodes; a vet walker records patients and gives vaccines."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = True;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        visit [-->];
