    has label: str = "";
    has idle_hours: int = 0;

    def device_kind() -> str {
        return "Pump";
    }
}

node Sprinkler {
    has label: str = "";
    has idle_hours: int = 0;

    def device_kind() -> str {
        return "Sprinkler";
    }
}

walker Crew {
    has serviced: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        kind = here.device_kind();
        print(f"Serviced {kind} '{here.label}': was idle for {here.idle_hours}h, resetting counter.");
        here.idle_hours = 0;
        self.serviced += 1;
        visit [-->];
    }
}

with entry {
    p1 = Pump(label="North-Well", idle_hours=12);
    p2 = Pump(label="South-Well", idle_hours=5);
    s1 = Sprinkler(label="Row-3-Drip", idle_hours=20);
    s2 = Sprinkler(label="Row-7-Drip", idle_hours=8);
    s3 = Sprinkler(label="Orchard-Mist", idle_hours=15);
    root ++> p1 ++> p2 ++> s1 ++> s2 ++> s3;

    crew = Crew();
    root spawn crew;
    print(f"Total devices serviced: {crew.serviced}");
}
