"""Moderation sweep over game accounts.

Member accounts are audited normally, admin accounts get their reputation
boosted by 5, and the welcome desk greets every bot passing through no
matter what kind of walker it is.
"""

node Account {
    has owner: str = "";
    has reputation: int = 0;
}

node Member(Account) {
    has member_id: str = "";
}

node Admin(Account) {
    has admin_level: int = 1;
}

node WelcomeDesk {
    has desk_name: str = "Front Gate";
}

edge Patronizes {}

walker Bot {
    has tag: str = "bot";

    can start with Root entry {
        visit [-->];
    }

    can approach with WelcomeDesk entry {
        print(f"Welcome desk '{here.desk_name}' greets {self.tag}");
        visit [-->];
    }
}

walker OrderAuditor {
    has audit_label: str = "Audit";

    can start with Root entry {
        print(f"Starting sweep: {self.audit_label}");
        visit [-->];
    }

    can sweep with WelcomeDesk entry {
        visit [-->];
    }

    can audit with Account entry {
        print(f"[{self.audit_label}] account owner={here.owner} rep={here.reputation}");
        visit [-->];
    }
}

walker Moderator {
    has sweep_name: str = "Mod";

    can start with Root entry {
        print(f"Moderator '{self.sweep_name}' beginning sweep");
        visit [-->];
    }

    can enter_desk with WelcomeDesk entry {
        print(f"Moderator '{self.sweep_name}' passes {here.desk_name}");
        visit [-->];
    }

    can review with Member entry {
        print(f"[MEMBER] {here.owner} (id={here.member_id}) reputation={here.reputation}");
        visit [-->];
    }

    can boost with Admin entry {
        boost = 5;
        new_rep = here.reputation + boost;
        label = "BOOSTED" if here.admin_level >= 2 else "STANDARD";
        print(f"[ADMIN:{label}] {here.owner} rep {here.reputation} -> {new_rep}");
        visit [-->];
    }
}

with entry {
    desk_a = WelcomeDesk(desk_name="North Gate");
    desk_b = WelcomeDesk(desk_name="South Gate");

    alice = Member(owner="alice", member_id="M-001");
    bob = Member(owner="bob", member_id="M-002");
    carol = Admin(owner="carol", admin_level=3, reputation=42);
    dave = Admin(owner="dave", admin_level=1, reputation=10);

    root +>:Patronizes:+> desk_a
        +>:Patronizes:+> alice
        +>:Patronizes:+> carol
        +>:Patronizes:+> desk_b
        +>:Patronizes:+> bob
        +>:Patronizes:+> dave;

    greeter = Bot(tag="greeter-1");
    root spawn greeter;

    print("--- Order audit sweep ---");
    root spawn OrderAuditor(audit_label="Q1-Audit");

    print("--- Moderator sweep with admin boosts ---");
    root spawn Moderator(sweep_name="Mod-A");
}
