"""Tests for moderation sweep over game accounts."""

import io;
import from contextlib { redirect_stdout }

test "welcome desk greets every bot regardless of walker" {
    root ++> WelcomeDesk(desk_name="Lobby");

    buf = io.StringIO();
    with redirect_stdout(buf) {
