        root spawn b1;
    }
    out1 = buf.getvalue();

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        b2 = Bot(tag="bot-B");
        root spawn b2;
    }
    out2 = buf2.getvalue();

    assert "Welcome desk 'Lobby' greets bot-A" in out1, f"bot-A not greeted: {out1}";
    assert "Welcome desk 'Lobby' greets bot-B" in out2, f"bot-B not greeted: {out2}";
}

test "OrderAuditor prints account owner and reputation" {
    root ++> WelcomeDesk(desk_name="Gate-1")
        ++> Member(owner="alice", member_id="M-001")
        ++> Admin(owner="carol", admin_level=3, reputation=42);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = OrderAuditor(audit_label="Q1-Audit");
        root spawn w;
    }
    out = buf.getvalue();

    assert "Starting sweep: Q1-Audit" in out, f"missing sweep header: {out}";
    assert "[Q1-Audit] account owner=alice rep=0" in out, f"alice not audited: {out}";
    assert "[Q1-Audit] account owner=carol rep=42" in out, f"carol not audited: {out}";
}

test "Moderator audits members and boosts admin reputation by exactly 5" {
    root ++> WelcomeDesk(desk_name="Gate-2")
        ++> Member(owner="bob", member_id="M-002", reputation=7)
        ++> Admin(owner="carol", admin_level=3, reputation=42)
        ++> Admin(owner="dave", admin_level=1, reputation=10);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        m = Moderator(sweep_name="Mod-A");
        root spawn m;
    }
    out = buf.getvalue();

    # member audit (no boost, no admin label)
    assert "[MEMBER] bob (id=M-002) reputation=7" in out, f"member not reviewed: {out}";

    # admin carol: high level -> BOOSTED, rep +5
    assert "[ADMIN:BOOSTED] carol rep 42 -> 47" in out, f"carol boost wrong: {out}";

    # admin dave: level 1 -> STANDARD, rep +5
    assert "[ADMIN:STANDARD] dave rep 10 -> 15" in out, f"dave boost wrong: {out}";

    # moderator should announce itself and traverse desks
    assert "Moderator 'Mod-A' beginning sweep" in out, f"missing moderator header: {out}";
    assert "Moderator 'Mod-A' passes Gate-2" in out, f"desk not traversed: {out}";
}

test "moderator boost is exactly +5 and only affects admin reputation" {
    root ++> WelcomeDesk(desk_name="Gate-3")
        ++> Member(owner="eve", member_id="M-003", reputation=99)
        ++> Admin(owner="frank", admin_level=5, reputation=0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        m = Moderator(sweep_name="Mod-B");
        root spawn m;
    }
    out = buf.getvalue();

    # Member reported unchanged - no admin boost applied
    assert "[MEMBER] eve (id=M-003) reputation=99" in out, f"member rep altered: {out}";
    # Frank (level >=2) gets +5: 0 -> 5
    assert "[ADMIN:BOOSTED] frank rep 0 -> 5" in out, f"frank boost wrong: {out}";
    # Exactly +5: nothing bigger should appear
    assert "rep 0 -> 10" not in out, f"boost magnitude wrong: {out}";
    assert "rep 0 -> 15" not in out, f"boost magnitude wrong: {out}";
}

test "bot does not audit or boost accounts; only welcome desk prints" {
    root ++> WelcomeDesk(desk_name="Gate-4")
        ++> Member(owner="alice", member_id="M-001", reputation=3)
        ++> Admin(owner="carol", admin_level=3, reputation=42);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        b = Bot(tag="scout");
        root spawn b;
    }
    out = buf.getvalue();

    # Bot greets the desk
    assert "Welcome desk 'Gate-4' greets scout" in out, f"bot missed desk: {out}";

    # Bot has no Account ability, so no audit/boost output
    assert "[AUDIT]" not in out, f"bot should not audit: {out}";
    assert "[MEMBER]" not in out, f"bot should not review members: {out}";
    assert "[ADMIN" not in out, f"bot should not boost admins: {out}";
    assert "rep" not in out.lower().replace("welcome desk 'gate-4' greets scout", ""), f"bot leaked rep data: {out}";
}

