    root ++> Pet(name="Buddy", species="dog", needs_vaccine=True)
        ++> Pet(name="Whiskers", species="cat", needs_vaccine=False)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True);
    vet = Vet();
    root spawn vet;
    print(f"Round complete: {len(vet.patient_names)} patients seen, {vet.shots_given} shots given");
    print(f"Patients: {', '.join(vet.patient_names)}");
}
