"""Moderation sweep: audit member accounts, boost admin reputation, and greet bots at the welcome desk."""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reputation: int = 0;
}

node Bot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Moderator {
    can start with Root entry {
        print("Moderation sweep beginning");
        visit [-->];
    }

    can audit with Account entry {
        status = "CLEAN" if here.available else "FLAGGED";
        print(f"[{status}] member account: {here.title} (rep={here.reputation})");
        visit [-->];
    }
}

walker AdminAuditor {
    can start with Root entry {
        print("Admin audit beginning");
        visit [-->];
    }

    can audit_admin with Account entry {
        if here.available {
            here.reputation = here.reputation + 5;
        }
        status = "CLEAN" if here.available else "FLAGGED";
        print(f"[{status}] admin account: {here.title} (rep boosted to {here.reputation})");
        visit [-->];
    }
}

walker Greeter {
    can start with Root entry {
        print("Welcome desk open");
        visit [-->];
    }

    can greet with Bot entry {
        print(f"Welcome, bot {here.title}!");
        visit [-->];
    }
}

with entry {
    a1 = Account(title="Alice", year=2021, available=True, reputation=20);
    a2 = Account(title="Bob", year=2022, available=False, reputation=15);
    b1 = Bot(title="HelperBot", year=2023);
    b2 = Bot(title="ModBot", year=2024);

    root ++> a1 ++> a2 ++> b1 ++> b2;

    mod = Moderator();
    root spawn mod;

    adm = AdminAuditor();
    root spawn adm;

    greet = Greeter();
    root spawn greet;
}
