"""Orchard irrigation tour: a single shared routine services both pumps and sprinklers.

A maintenance crew walker traverses a grove of irrigation devices. One union
ability handles every device kind uniformly: it logs the kind, records how many
hours the device sat idle, resets the idle counter, and tallies the service.
"""

node IrrigationDevice {
    has kind: str = "";
    has idle_hours: int = 0;
}

node Pump(IrrigationDevice) {
    has kind: str = "pump";
}

node Sprinkler(IrrigationDevice) {
    has kind: str = "sprinkler";
}

node Grove {
    has grove_name: str = "";
}

walker MaintenanceCrew {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew dispatched for irrigation maintenance round");
        visit [-->];
    }

    can tour with Grove entry {
        print(f"Entering grove: {here.grove_name}");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        device_kind = here.kind;
        idle = here.idle_hours;
        here.idle_hours = 0;
        self.serviced += 1;
        print(f"[SERVICED] kind={device_kind}, idle_hours={idle}, counter reset, total serviced={self.serviced}");
        visit [-->];
    }
}

with entry {
    north = Grove(grove_name="North Orchard");
    south = Grove(grove_name="South Orchard");
    root ++> north ++> south;

    north ++> Pump(idle_hours=14);
    north ++> Pump(idle_hours=3);
    north ++> Sprinkler(idle_hours=22);
    south ++> Sprinkler(idle_hours=7);
    south ++> Sprinkler(idle_hours=11);
    south ++> Pump(idle_hours=5);

    crew = MaintenanceCrew();
    root spawn crew;
    print(f"Crew finished — devices serviced total: {crew.serviced}");
}
```

