"""Test annex for the Office tower tour program."""

import io;
import from contextlib { redirect_stdout }

test "tour guide announces tour name and visits every floor" {
    root ++> Floor(number=1, department="Lobby & Security")
        ++> Floor(number=12, department="Engineering")
        ++> Floor(number=24, department="Executive Suites");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Skyline Tower Tour");
    }
    out = buf.getvalue();

    # Tour header must be announced when the walker enters Root
    assert "Welcome to the Skyline Tower Tour!" in out, f"missing welcome line: {out}";

    # Every floor must print its own stop, in chain order (bottom -> top)
    assert "Stop 1: Lobby & Security" in out, f"missing lobby stop: {out}";
    assert "Stop 12: Engineering" in out, f"missing engineering stop: {out}";
    assert "Stop 24: Executive Suites" in out, f"missing executive stop: {out}";

    # Stops must appear in ascending order up the building
    idx_lobby = out.index("Stop 1:");
    idx_eng = out.index("Stop 12:");
    idx_exec = out.index("Stop 24:");
    assert idx_lobby < idx_eng < idx_exec, (
        f"stops out of order: lobby={idx_lobby}, eng={idx_eng}, exec={idx_exec} in {out!r}"
    );

    # Welcome must come before any stop announcement
    idx_welcome = out.index("Welcome to the Skyline Tower Tour!");
    assert idx_welcome < idx_lobby, (
        f"welcome must precede stops: welcome={idx_welcome}, lobby={idx_lobby} in {out!r}"
    );
}

test "different tour_name parameter is reflected in the welcome line" {
    root ++> Floor(number=2, department="Reception")
        ++> Floor(number=10, department="Marketing");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Sunset Tower Tour");
    }
    out = buf.getvalue();

    assert "Welcome to the Sunset Tower Tour!" in out, f"missing welcome: {out}";
    assert "Skyline Tower Tour" not in out, f"unexpected tour name leaked: {out}";
    assert "Stop 2: Reception" in out, f"missing reception stop: {out}";
    assert "Stop 10: Marketing" in out, f"missing marketing stop: {out}";
}

test "walker traverses the whole chain via floor connections" {
    a = Floor(number=3, department="A");
    b = Floor(number=4, department="B");
    c = Floor(number=5, department="C");
    root ++> a ++> b ++> c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Chain Tour");
    }
    out = buf.getvalue();

    # All three floors should be reached via the chain links
    assert "Stop 3: A" in out, f"missing A: {out}";
    assert "Stop 4: B" in out, f"missing B: {out}";
    assert "Stop 5: C" in out, f"missing C: {out}";

    # The root itself is not a Floor and must not print a stop
    assert "Stop 0:" not in out, f"root should not announce a stop: {out}";

    # Graph shape sanity: root has exactly one direct child (chain head)
    assert len([root-->]) == 1, "root should have exactly one direct child in a chain";
    assert a in [root-->], "a should be the direct child of root";
