"""Orchard maintenance tour: pump and sprinkler nodes share a single servicing routine.

One walker ability handles both irrigation pump and sprinkler archetypes via a
union trigger, logging each device, the hours it was idle, resetting its idle
counter, and accumulating a service total that is reported on exit.
"""

node Pump {
    has name: str = "";
    has idle_hours: float = 0.0;
}

node Sprinkler {
    has name: str = "";
    has idle_hours: float = 0.0;
}

walker Crew {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew starting irrigation maintenance tour");
        visit [-->];
    }

    can service with Pump | Sprinkler entry {
        kind = "Pump" if isinstance(here, Pump) else "Sprinkler";
        print(f"[SERVICED {kind}] {here.name} idle for {here.idle_hours}h — resetting counter");
        here.idle_hours = 0.0;
        self.serviced += 1;
        visit [-->];
    }
}

with entry {
    root ++> Pump(name="North Well Pump", idle_hours=14.5)
        ++> Sprinkler(name="Block A Sprinkler", idle_hours=6.25)
        ++> Pump(name="South Well Pump", idle_hours=22.0)
        ++> Sprinkler(name="Block B Sprinkler", idle_hours=3.75);

    crew = Crew();
    root spawn crew;
    print(f"Tour complete: {crew.serviced} devices serviced");
}
```

