```jac
"""Game-account moderation sweep.

Member accounts are audited normally, admin accounts get their reputation
boosted by 5, and the welcome desk greets every bot passing through no
matter what kind of walker it is.
"""

node MemberAccount {
    has username: str = "";
    has reputation: int = 0;
}

node AdminAccount {
    has username: str = "";
    has reputation: int = 0;
}

node Bot {
    has label: str = "";
}

walker OrderAuditor {
    has greeting_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with MemberAccount entry {
        print(f"[AUDIT] {here.username} (member) reputation={here.reputation}");
        visit [-->];
    }

    can boost with AdminAccount entry {
        here.reputation = here.reputation + 5;
        print(f"[ADMIN BOOST] {here.username} -> reputation {here.reputation}");
        visit [-->];
    }

    can greet with Bot entry {
        print(f"[GREET] hello bot '{here.label}' from OrderAuditor");
        self.greeting_count = self.greeting_count + 1;
        visit [-->];
    }
}

with entry {
    root ++> MemberAccount(username="alice", reputation=42)
        ++> AdminAccount(username="mod_jane", reputation=100)
        ++> Bot(label="welcome-bot-1")
        ++> Bot(label="welcome-bot-2");

    auditor = OrderAuditor();
    root spawn auditor;

    print(f"Welcome desk greeted {auditor.greeting_count} bot(s)");
}
