"""Wildlife park feeding rounds.

The info kiosk greets every tour party (union trigger on Visitor).
Zookeepers actually feed animals their species-appropriate meal via
a per-species override. School groups only watch.
"""

node Animal {
    has name: str = "";
    has species: str = "";

    def meal() -> str {
        return "standard feed";
    }
}

node Lion(Animal) {
    override def meal() -> str {
        return "meat";
    }
}

node Parrot(Animal) {
    override def meal() -> str {
        return "seed";
    }
}

node GenericAnimal(Animal) {
    override def meal() -> str {
        return "standard feed";
    }
}

node ZooKeeper {
    has name: str = "";
}

node SchoolGroup {
    has name: str = "";
}

node Kiosk {
    has park_name: str = "";
}

walker Visitor {
    can start with Root entry {
        visit [-->];
    }

    # Kiosk greets every kind of visitor: zookeepers, school groups,
    # and any other tour party alike.
    can greet with Kiosk entry {
        print(f"Welcome to {here.park_name}!");
        visit [-->];
    }
}

walker ZooKeeperWalker {
    has keeper_name: str = "";

    can start with Root entry {
        print(f"Zookeeper {self.keeper_name} starts the feeding round");
        visit [-->];
    }

    can feed with Lion | Parrot | GenericAnimal entry {
        print(f"{self.keeper_name} feeds {here.name} the {here.species}: {here.meal()}");
        visit [-->];
    }
}

walker SchoolGroupWalker {
    has group_name: str = "";

    can start with Root entry {
        print(f"School group {self.group_name} arrives to watch the animals");
        visit [-->];
    }

    can watch with Lion | Parrot | GenericAnimal entry {
        print(f"{self.group_name} watches {here.name} the {here.species}");
        visit [-->];
    }
}

with entry {
    kiosk = Kiosk(park_name="Wildlife Park");

    lion = Lion(name="Leo", species="lion");
    parrot = Parrot(name="Polly", species="parrot");
    generic = GenericAnimal(name="Bessie", species="antelope");

    root ++> kiosk ++> lion ++> parrot ++> generic;

    keeper_walker = ZooKeeperWalker(keeper_name="Sam");
    root spawn keeper_walker;

    group_walker = SchoolGroupWalker(group_name="Class 5B");
    root spawn group_walker;

    visitor = Visitor();
    root spawn visitor;
}
