"""Regression tests for the orchard irrigation tour."""

import io;
import from contextlib { redirect_stdout }

def make_graph() {
    pump_a = Pump(label="Pump-A", kind="pump", idle_hours=12, pressure_psi=45.0);
    pump_b = Pump(label="Pump-B", kind="pump", idle_hours=3, pressure_psi=50.0);
    sprinkler_a = Sprinkler(label="Sprinkler-A", kind="sprinkler", idle_hours=8, radius_ft=15.0);
    sprinkler_b = Sprinkler(label="Sprinkler-B", kind="sprinkler", idle_hours=20, radius_ft=20.0);
    pump_b.serviced = True;
    root ++> pump_a ++> pump_b ++> sprinkler_a ++> sprinkler_b;
    return [pump_a, pump_b, sprinkler_a, sprinkler_b];
}

test "all unserviced devices get serviced, idle_hours reset, counter increments" {
    devices = make_graph();
    [pump_a, pump_b, sprinkler_a, sprinkler_b] = devices;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        crew = root spawn Crew();
    }
    out = buf.getvalue();

    assert pump_a.serviced == True, "Pump-A should be marked serviced";
    assert pump_a.idle_hours == 0, f"Pump-A idle_hours should reset, got {pump_a.idle_hours}";
    assert sprinkler_a.serviced == True, "Sprinkler-A should be marked serviced";
    assert sprinkler_a.idle_hours == 0, f"Sprinkler-A idle_hours should reset, got {sprinkler_a.idle_hours}";
    assert sprinkler_b.serviced == True, "Sprinkler-B should be marked serviced";
    assert sprinkler_b.idle_hours == 0, f"Sprinkler-B idle_hours should reset, got {sprinkler_b.idle_hours}";
    assert crew.total_serviced == 3, f"expected 3 devices serviced (skipping pre-serviced Pump-B), got {crew.total_serviced}";

    assert "[pump] Pump-A idle_hours=12 -> serviced" in out, f"missing Pump-A log: {out}";
    assert "[pump] Pump-B idle_hours=3 -> skip" in out, f"missing Pump-B skip log: {out}";
    assert "[sprinkler] Sprinkler-A idle_hours=8 -> serviced" in out, f"missing Sprinkler-A log: {out}";
    assert "[sprinkler] Sprinkler-B idle_hours=20 -> serviced" in out, f"missing Sprinkler-B log: {out}";
}

test "already-serviced devices are skipped and not counted again" {
    pump_a = Pump(label="Pump-A", kind="pump", idle_hours=12, pressure_psi=45.0);
    pump_b = Pump(label="Pump-B", kind="pump", idle_hours=3, pressure_psi=50.0);
    pump_a.serviced = True;
    pump_b.serviced = True;
    root ++> pump_a ++> pump_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        crew = root spawn Crew();
    }
    out = buf.getvalue();

    assert crew.total_serviced == 0, f"nothing should be serviced, got {crew.total_serviced}";
    assert pump_a.idle_hours == 12, f"idle_hours must NOT be reset on skip, got {pump_a.idle_hours}";
    assert pump_b.idle_hours == 3, f"idle_hours must NOT be reset on skip, got {pump_b.idle_hours}";
    assert "Pump-A idle_hours=12 -> skip" in out, out;
    assert "Pump-B idle_hours=3 -> skip" in out, out;
}

test "traversal order follows graph edges from root" {
    p1 = Pump(label="P1", kind="pump", idle_hours=1, pressure_psi=10.0);
    s1 = Sprinkler(label="S1", kind="sprinkler", idle_hours=2, radius_ft=5.0);
    p2 = Pump(label="P2", kind="pump", idle_hours=3, pressure_psi=10.0);
    s2 = Sprinkler(label="S2", kind="sprinkler", idle_hours=4, radius_ft=5.0);
    root ++> p1;
    root ++> s1;
    root ++> p2;
    root ++> s2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        crew = root spawn Crew();
    }
    out = buf.getvalue();

    assert crew.total_serviced == 4, f"all 4 unserviced devices should be serviced, got {crew.total_serviced}";
    assert all(d.serviced for d in [p1, s1, p2, s2]), "every device must be serviced";
    assert all(d.idle_hours == 0 for d in [p1, s1, p2, s2]), "every idle_hours must be reset";
    assert "Crew starting irrigation tour..." in out, f"missing start banner: {out}";
}

test "second tour adds zero because everything is already serviced" {
    devices = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        first = root spawn Crew();
    }
    assert first.total_serviced == 3, f"first tour: expected 3, got {first.total_serviced}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        second = root spawn Crew();
    }
    out2 = buf2.getvalue();

    assert second.total_serviced == 0, f"second tour: expected 0 new, got {second.total_serviced}";
    assert "Pump-A idle_hours=0 -> skip" in out2, f"already-serviced pump should report skip, got: {out2}";
    assert "Sprinkler-A idle_hours=0 -> skip" in out2, f"already-serviced sprinkler should report skip, got: {out2}";
}

