"""Vet clinic round: walk patient pets, record names, and tally vaccines given."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = True;
}

walker Veterinarian {
    has patient_names: list[str] = [];
    has shots_given: int = 0;

