"""Wildlife park feeding rounds.

A kiosk walker greets every visitor regardless of species. Zookeepers feed
each animal its species-appropriate meal: lions get meat, parrots get seed,
and every other animal gets the standard feed. School groups just observe.
"""

node Lion {
    has name: str = "";
    has fed: bool = False;

    def kind() -> str {
        return "lion";
    }
}

node Parrot {
    has name: str = "";
    has fed: bool = False;

    def kind() -> str {
        return "parrot";
    }
}

node Animal {
    has species: str = "";
    has name: str = "";
    has fed: bool = False;

    def kind() -> str {
        return self.species;
    }
}

walker Kiosk {
    can start with Root entry {
        print("[Kiosk] Welcome to the wildlife park!");
        visit [-->];
    }

    can greet with Lion | Parrot | Animal entry {
        print(f"[Kiosk] Hello, tour party heading to see {here.name} the {here.kind()}");
        visit [-->];
    }
}

walker Zookeeper {
    can start with Root entry {
        print("[Zookeeper] Starting feeding rounds");
        visit [-->];
    }

    can feed_meat with Lion entry {
        print(f"[Zookeeper] Serving meat to {here.name} the lion");
        here.fed = True;
        visit [-->];
    }

    can feed_seed with Parrot entry {
        print(f"[Zookeeper] Serving seed to {here.name} the parrot");
        here.fed = True;
        visit [-->];
    }

    can feed_standard with Animal entry {
        print(f"[Zookeeper] Serving standard feed to {here.name} the {here.species}");
        here.fed = True;
        visit [-->];
    }
}

walker SchoolGroup {
    can start with Root entry {
        print("[SchoolGroup] Class arriving to watch the animals");
        visit [-->];
    }

    can observe with Lion | Parrot | Animal entry {
        print(f"[SchoolGroup] Students watch {here.name} the {here.kind()} in silence");
        visit [-->];
    }
}

with entry {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    rocky = Animal(species="rock hyrax", name="Rocky");

    root ++> simba ++> polly ++> rocky;

    root spawn Kiosk();
    print("---");
    root spawn Zookeeper();
    print("---");
    root spawn SchoolGroup();
}
