    mittens = Pet(name="Mittens", species="Cat", needs_vaccine=False);
    rex = Pet(name="Rex", species="Dog", needs_vaccine=True);
    root ++> buddy ++> mittens ++> rex;

    assert buddy.needs_vaccine == True, "Buddy should start needing a vaccine";
    assert mittens.needs_vaccine == False, "Mittens should start not needing a vaccine";
    assert rex.needs_vaccine == True, "Rex should start needing a vaccine";

    vet = Vet();
    root spawn vet;

    assert buddy.needs_vaccine == False, "Buddy's flag should be cleared after vaccination";
    assert mittens.needs_vaccine == False, "Mittens' flag should remain False (no shot given)";
    assert rex.needs_vaccine == False, "Rex's flag should be cleared after vaccination";
