```jac
"""Moderation sweep over game accounts.

Member accounts are audited normally, admin accounts get their reputation
boosted by 5, and the welcome desk greets every bot passing through no
matter what kind of walker it is.
"""

node Account {
    has name: str = "";
    has reputation: int = 0;
}

node Member(Account) {
    has joined: str = "";
}

node Admin(Account) {
    has permissions: str = "";
}

edge Registered {}

edge Greets {}

walker Moderator {
    has audit_log: list[str] = [];

    can start with Root entry {
        print("Moderation sweep beginning...");
        visit [-->];
    }

    can audit with Member entry {
        self.audit_log.append(f"audited member {here.name}");
        print(f"[AUDIT] member {here.name} (reputation {here.reputation})");
        visit [-->];
    }

    can boost with Admin entry {
        old_rep = here.reputation;
        here.reputation = here.reputation + 5;
        self.audit_log.append(
            f"boosted admin {here.name} from {old_rep} to {here.reputation}"
        );
        print(
            f"[BOOST] admin {here.name}: {old_rep} -> {here.reputation}"
        );
        visit [-->];
    }

    can greet_bots with Member | Admin entry {
        print(f"[DESK] welcome, {here.name}");
        visit [-->];
    }
}

with entry {
    alpha = Member(name="alpha_player", reputation=42, joined="2024-03-01");
    beta = Admin(name="beta_ops", reputation=77, permissions="full");
    gamma = Member(name="gamma_guest", reputation=10, joined="2024-06-15");

    root +>:Registered:+> alpha;
    root +>:Registered:+> beta;
    root +>:Registered:+> gamma;

    alpha +>:Greets:+> gamma;

    desk = Moderator();
    root spawn desk;
}
```

