"""Tests for moderation sweep over game accounts."""

import io;
import from contextlib { redirect_stdout }

test "member is audited and greeted" {
    root ++> Member(name="alice", reputation=20, joined="2024-01-01");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Moderator();
    }
    out = buf.getvalue();

    assert "[AUDIT] member alice (reputation 20)" in out, f"missing audit line: {out}";
    assert "[DESK] welcome, alice" in out, f"missing desk greeting: {out}";
    assert "[BOOST]" not in out, f"member should not be boosted: {out}";

    alice = [root -->][?:Member][0];
    assert alice.reputation == 20, f"member reputation should be untouched: {alice.reputation}";

    assert "audited member alice" in res.audit_log, f"audit log missing entry: {res.audit_log}";
    assert not any("boosted" in e for e in res.audit_log), f"no boost should be recorded: {res.audit_log}";
}

test "admin gets reputation boosted by 5" {
    root ++> Admin(name="bob", reputation=50, permissions="full");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Moderator();
    }
    out = buf.getvalue();

    assert "[BOOST] admin bob: 50 -> 55" in out, f"missing boost line: {out}";
    assert "[AUDIT]" not in out, f"admin should not be audited: {out}";

    bob = [root -->][?:Admin][0];
    assert bob.reputation == 55, f"admin reputation should be boosted by 5: {bob.reputation}";

    assert any("boosted admin bob from 50 to 55" in e for e in res.audit_log), f"boost log missing: {res.audit_log}";
    assert not any("audited" in e for e in res.audit_log), f"no audit should be recorded for admin: {res.audit_log}";
}

test "greet_bots fires for both member and admin" {
    m = Member(name="cara", reputation=5, joined="2024-02-02");
    a = Admin(name="dave", reputation=99, permissions="super");
    root ++> m;
    root ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Moderator();
    }
    out = buf.getvalue();

    assert "[DESK] welcome, cara" in out, f"member not greeted: {out}";
    assert "[DESK] welcome, dave" in out, f"admin not greeted: {out}";
    assert "[AUDIT] member cara" in out, f"member should still be audited: {out}";
    assert "[BOOST] admin dave" in out, f"admin should still be boosted: {out}";

    assert m.reputation == 5, f"member rep unchanged: {m.reputation}";
    assert a.reputation == 104, f"admin rep boosted: {a.reputation}";
}

test "moderation sweep over mixed accounts" {
    alpha = Member(name="alpha_player", reputation=42, joined="2024-03-01");
    beta = Admin(name="beta_ops", reputation=77, permissions="full");
    gamma = Member(name="gamma_guest", reputation=10, joined="2024-06-15");

    root +>:Registered:+> alpha;
    root +>:Registered:+> beta;
    root +>:Registered:+> gamma;
    alpha +>:Greets:+> gamma;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Moderator();
    }
    out = buf.getvalue();

    assert "Moderation sweep beginning..." in out, f"sweep banner missing: {out}";
    assert "[AUDIT] member alpha_player (reputation 42)" in out, f"missing alpha audit: {out}";
    assert "[BOOST] admin beta_ops: 77 -> 82" in out, f"missing beta boost: {out}";
    assert "[AUDIT] member gamma_guest (reputation 10)" in out, f"missing gamma audit: {out}";

    assert alpha.reputation == 42, f"alpha rep untouched: {alpha.reputation}";
    assert beta.reputation == 82, f"beta rep boosted: {beta.reputation}";
    assert gamma.reputation == 10, f"gamma rep untouched: {gamma.reputation}";

    desk_lines = [l for l in out.split("\n") if l.startswith("[DESK]")];
    assert len(desk_lines) >= 2, f"each account should be greeted, got: {desk_lines}";

    assert "audited member alpha_player" in res.audit_log, f"audit log: {res.audit_log}";
    assert "audited member gamma_guest" in res.audit_log, f"audit log: {res.audit_log}";
    assert "boosted admin beta_ops from 77 to 82" in res.audit_log, f"audit log: {res.audit_log}";

    visited = [root -->];
    assert len(visited) == 3, f"root should have 3 registered children: {len(visited)}";
}

