"""Wildlife park feeding rounds: kiosk greets all visitors, zookeepers feed animals their species-appropriate meals, school groups just observe."""

node Animal {
    has name: str = "";
    has species: str = "";
}

walker Tourist {
    can start with Root entry {
        print("Kiosk: Welcome to the wildlife park!");
        visit [-->];
    }

    can greet with Animal entry {
        print(f"Kiosk: Enjoy spotting the {here.species} ({here.name}).");
        visit [-->];
    }
}

walker Zookeeper {
    can start with Root entry {
        visit [-->];
    }

    can feed with Animal entry {
        if here.species == "lion" {
            print(f"Zookeeper: Serving meat to {here.name} the lion.");
        } elif here.species == "parrot" {
            print(f"Zookeeper: Offering seed mix to {here.name} the parrot.");
        } else {
            print(f"Zookeeper: Giving standard feed to {here.name} the {here.species}.");
        }
        visit [-->];
    }
}

walker SchoolGroup {
    can start with Root entry {
        visit [-->];
    }

    can observe with Animal entry {
        print(f"SchoolGroup: Quietly watching {here.name} the {here.species}.");
        visit [-->];
    }
}

with entry {
    root ++> Animal(name="Leo", species="lion")
        ++> Animal(name="Polly", species="parrot")
        ++> Animal(name="Gigi", species="giraffe");

    root spawn Tourist();
    print("---");
    root spawn Zookeeper();
    print("---");
    root spawn SchoolGroup();
}
