```jac
"""Moderation sweep over game accounts.

Member accounts are audited normally, admin accounts get their reputation
boosted by 5, and the welcome desk greets every bot passing through no
matter what kind of walker it is.
"""

node Account {
    has owner: str = "";
    has reputation: int = 0;
}

node Member(Account) {}

node Admin(Account) {}

node Bot {
    has handle: str = "";
}

walker Moderator {
    has report_lines: list[str] = [];

    can start with Root entry {
        print("Beginning moderation sweep...");
        visit [-->];
    }

    can audit with Member | Admin entry {
        note = f"Audited member: {here.owner} (rep={here.reputation})";
        self.report_lines.append(note);
        print(note);
        visit [-->];
    }
}

walker ReputationBooster {
    has boost: int = 5;

    can start with Root entry {
        print("Starting reputation boost pass...");
        visit [-->];
    }

    can boost_admin with Admin entry {
        old_rep = here.reputation;
        here.reputation = here.reputation + self.boost;
        print(f"Boosted admin {here.owner}: {old_rep} -> {here.reputation}");
        visit [-->];
    }
}

walker Greeter {
    has greeting_count: int = 0;

    can start with Root entry {
        print("Welcome desk open.");
        visit [-->];
    }

    can greet with Bot entry {
        self.greeting_count += 1;
        print(f"Hello, bot {here.handle}! (greeting #{self.greeting_count})");
        visit [-->];
    }
}

with entry {
    # Member accounts
    alice = Member(owner="Alice", reputation=42);
    bob = Member(owner="Bob", reputation=17);

    # Admin accounts
    carol = Admin(owner="Carol", reputation=120);
    dave = Admin(owner="Dave", reputation=95);

    # Bots (any walker passing through greets them at the welcome desk)
    helper_bot = Bot(handle="HelperBot-01");
    mod_bot = Bot(handle="ModBot-09");

    root ++> alice ++> bob ++> carol ++> dave ++> helper_bot ++> mod_bot;

    # Moderator audits members (and admins if reached, but we also boost them).
    print("=== Moderation sweep ===");
    root spawn Moderator();

    print("\n=== Reputation boost pass ===");
    root spawn ReputationBooster();

    print("\n=== Welcome desk ===");
    root spawn Greeter();
}
