"""Tests for the office tower tour walker."""

import io;
import from contextlib { redirect_stdout }


test "start announcement fires at root before any floor" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Engineering");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Skyline Tower Highlights");
    }
    out = buf.getvalue();
    lines = out.splitlines();

    assert "Starting tour: Skyline Tower Highlights" in out, f"missing start line: {out}";
    assert lines[0] == "Starting tour: Skyline Tower Highlights", f"start not first line: {lines}";
}

test "each floor announces itself in chain order" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Engineering")
        ++> Floor(number=3, department="Product")
        ++> Floor(number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Skyline Tower Highlights");
    }
    out = buf.getvalue();
    lines = out.splitlines();

    assert lines[0] == "Starting tour: Skyline Tower Highlights", f"start wrong: {lines}";
    idx_start = lines.index("Starting tour: Skyline Tower Highlights");
    idx_f1 = lines.index("  Floor 1 — Lobby & Reception");
    idx_f2 = lines.index("  Floor 2 — Engineering");
    idx_f3 = lines.index("  Floor 3 — Product");
    idx_f4 = lines.index("  Floor 4 — Executive Suite");

    assert idx_start < idx_f1 < idx_f2 < idx_f3 < idx_f4, f"wrong order: start={idx_start} f1={idx_f1} f2={idx_f2} f3={idx_f3} f4={idx_f4}";
}

test "walker traverses every floor in a longer chain" {
    root ++> Floor(number=5, department="Marketing")
        ++> Floor(number=6, department="Sales")
        ++> Floor(number=7, department="R&D")
        ++> Floor(number=8, department="Legal");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Upward Bound");
    }
    out = buf.getvalue();

    assert "Starting tour: Upward Bound" in out, f"missing start: {out}";
    assert "  Floor 5 — Marketing" in out, f"missing floor 5: {out}";
    assert "  Floor 6 — Sales" in out, f"missing floor 6: {out}";
    assert "  Floor 7 — R&D" in out, f"missing floor 7: {out}";
    assert "  Floor 8 — Legal" in out, f"missing floor 8: {out}";

    floor_lines = [l for l in out.splitlines() if l.startswith("  Floor ")];
    assert len(floor_lines) == 4, f"expected 4 floor announcements, got {len(floor_lines)}: {floor_lines}";
}

test "single floor produces one announcement after the start line" {
    root ++> Floor(number=10, department="Rooftop Lounge");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Penthouse Visit");
    }
    out = buf.getvalue();
    lines = out.splitlines();

    assert len(lines) == 2, f"expected exactly 2 lines, got {lines}";
    assert lines[0] == "Starting tour: Penthouse Visit", f"first line wrong: {lines[0]}";
    assert lines[1] == "  Floor 10 — Rooftop Lounge", f"second line wrong: {lines[1]}";
}

test "graph shape is a true chain: root has exactly one direct child" {
    a = Floor(number=1, department="Lobby & Reception");
    b = Floor(number=2, department="Engineering");
    c = Floor(number=3, department="Product");
    d = Floor(number=4, department="Executive Suite");
    root ++> a ++> b ++> c ++> d;

    assert len([root-->]) == 1, f"root should have 1 direct child, got {len([root-->])}";
    direct = [root-->][0];
    assert direct.number == 1, f"direct child should be floor 1, got {direct.number}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Skyline Tower Highlights");
    }
    out = buf.getvalue();
    announcements = [l for l in out.splitlines() if l.startswith("  Floor ")];
    assert len(announcements) == 4, f"expected 4 floor announcements, got {len(announcements)}: {out}";
}

