"""Vet clinic rounds: pets as nodes; a vet walker records patients and vaccines given."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patient_names: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print("Vet clinic round starting");
        visit [-->];
    }

    can examine with Pet entry {
        self.patient_names.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"Vaccinated {here.name} ({here.species})");
        } else {
            print(f"Checked {here.name} ({here.species}) — no shot needed");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Pet(name="Buddy", species="dog", needs_vaccine=True)
        ++> Pet(name="Mittens", species="cat", needs_vaccine=False)
        ++> Pet(name="Rex", species="dog", needs_vaccine=True)
        ++> Pet(name="Whiskers", species="cat", needs_vaccine=True);

    vet = root spawn Vet();

    print(f"Summary: {vet.shots_given} shots given across {len(vet.patient_names)} patients");
    print(f"Patients seen: {', '.join(vet.patient_names)}");
}
