"""Moderation sweep over game accounts: normal audit for members, reputation boost for admins, welcome desk greets every bot."""

node Account {
    has handle: str = "";
    has kind: str = "member";
    has reputation: int = 0;
    has flagged: bool = False;
}

edge Greeter { }

walker Moderator {
    can start with Root entry {
        print("Moderator beginning sweep");
        visit [-->];
    }

    can audit with Account entry {
        if here.kind == "admin" {
            here.reputation = here.reputation + 5;
            print(f"[BOOST] admin {here.handle} reputation now {here.reputation}");
        } else {
            here.flagged = False;
            print(f"[AUDIT] member {here.handle} clean (reputation {here.reputation})");
        }
        visit [-->];
    }
}

walker GreeterBot {
    can start with Root entry {
        print("GreeterBot at welcome desk");
        visit [-->];
    }

    can greet with Account entry {
        print(f"[WELCOME] hello {here.handle}!");
        visit [-->];
    }
}

walker SpyBot {
    can start with Root entry {
        print("SpyBot passing through");
        visit [-->];
    }

    can peek with Account entry {
        print(f"[SPY] observing {here.handle} (reputation {here.reputation})");
        visit [-->];
    }
}

with entry {
    root ++> Account(handle="alice", kind="member", reputation=10)
        ++> Account(handle="bob", kind="member", reputation=20)
        ++> Account(handle="carol", kind="admin", reputation=50)
        ++> Account(handle="dave", kind="admin", reputation=40);

    root spawn Moderator();
    root spawn GreeterBot();
    root spawn SpyBot();
}
