"""Moderation sweep over game accounts: audit members, boost admin reputation, greet every bot."""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Member(Account) {
    has reputation: int = 0;
}

node Admin(Account) {
    has reputation: int = 0;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting moderation sweep");
        visit [-->];
    }

    can audit with Member | Admin entry {
        status = "OK" if here.available else "FLAGGED";
        print(f"[{status}] {here.title} (rep={here.reputation})");
        visit [-->];
    }

    can boost with Admin entry {
        here.reputation = here.reputation + 5;
        print(f"[BOOSTED] Admin {here.title} reputation now {here.reputation}");
        visit [-->];
    }
}

node WelcomeDesk {
    can greet with OrderAuditor entry {
        print("Welcome, bot! You passed the welcome desk.");
        visit [-->];
    }
}

with entry {
    desk = WelcomeDesk();
    root ++> desk
        ++> Member(title="alice", year=2021)
        ++> Admin(title="boss", year=2020)
        ++> Member(title="charlie", year=2022, available=False)
        ++> Admin(title="dana", year=2019);

    root spawn OrderAuditor();
}
