}

with entry {
    simba = Lion(species="lion", name="Simba", mane_color="golden");
    polly = Parrot(species="parrot", name="Polly", feather_color="scarlet");
    zed = Zebra(species="zebra", name="Zed");
    root ++> simba ++> polly ++> zed;

    root spawn Kiosk();
    print("");
    root spawn Zookeeper(keeper_name="Alex");
    print("");
