        res = root spawn TourGuide(tour_name="Order Check");
    }
    out = buf.getvalue();

    start_idx = out.find("Starting tour: Order Check");
    floor1_idx = out.find("Stop: Floor 1 — Lobby");
    floor3_idx = out.find("Stop: Floor 3 — Engineering");

    assert start_idx >= 0, f"no start line in: {out}";
    assert floor1_idx >= 0, f"no floor 1 stop in: {out}";
    assert floor3_idx >= 0, f"no floor 3 stop in: {out}";
    assert start_idx < floor1_idx, f"start must precede floor 1: {out}";
    assert floor1_idx < floor3_idx, f"floors must print in ascending order: {out}";
}

