        ++> Floor(floor_number=2, department="HR")
        ++> Floor(floor_number=3, department="Engineering");

    floors = [root -->];
    assert len(floors) == 1, f"root should link to exactly one first floor, got {len(floors)}";

    visited = [];
    current = floors[0];
    while current is not None {
