```jac
"""Wildlife park feeding rounds.

The kiosk greets every tour party (union trigger on ZooKeeper | SchoolGroup).
Zookeepers feed each animal its species-appropriate meal. School groups
simply observe. The script wires a root with a kiosk, animals, and parties,
then spawns the parties on root so the kiosk reacts to all of them.
"""

node Kiosk {
    has name: str = "Main Gate";

    # Union trigger: fires when either a ZooKeeper or a SchoolGroup
    # arrives at the kiosk, regardless of which party it is.
    can welcome_party with ZooKeeper | SchoolGroup entry {
        print(f"Welcome to the park! (visitor triggered kiosk welcome)");
        visit [-->];
    }
}

node Animal {
    has species: str = "";
    has diet: str = "standard";
}

node Lion {
    has name: str = "";
}

node Parrot {
    has name: str = "";
}

walker ZooKeeper {
    has keeper_id: str = "Z-001";

    can start with Root entry {
        visit [-->];
    }

    can greet with Kiosk entry {
        print(f"Keeper {self.keeper_id} checked in at {here.name} kiosk");
        visit [-->];
    }

    can feed_lion with Lion entry {
        print(f"Keeper {self.keeper_id} serves meat to lion {here.name}");
        visit [-->];
    }

    can feed_parrot with Parrot entry {
        print(f"Keeper {self.keeper_id} offers seed to parrot {here.name}");
        visit [-->];
    }
}

walker SchoolGroup {
    has grade: int = 3;

    can start with Root entry {
        visit [-->];
    }

    can observe_lion with Lion entry {
        print(f"Grade {self.grade} students watch lion {here.name}");
        visit [-->];
    }

    can observe_parrot with Parrot entry {
        print(f"Grade {self.grade} students watch parrot {here.name}");
        visit [-->];
    }
}

with entry {
    kiosk = Kiosk(name="Safari Entrance");
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");

    root ++> kiosk ++> simba ++> polly;

    root spawn ZooKeeper(keeper_id="Z-007");
    root spawn SchoolGroup(grade=4);
}
