"""Kitchen line health-inspection walker.

Two inspectors traverse the kitchen line together: one flags any station
above 40 C as a violation, the other logs every station visit. Both
inspectors run at every station.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker TempInspector {
    can start with Root entry {
        visit [-->];
    }

    can check_temp with Station entry {
        if here.celsius > 40.0 {
            print(f"[VIOLATION] {here.name} is {here.celsius} C (>40 C)");
        } else {
            print(f"[OK] {here.name} is {here.celsius} C");
        }
        visit [-->];
    }
}

walker VisitLogger {
    can start with Root entry {
        visit [-->];
    }

    can log_visit with Station entry {
        print(f"  -> visited {here.name} at {here.celsius} C");
        visit [-->];
    }
}

with entry {
    grill = Station(name="grill", celsius=180.0);
    fryer = Station(name="fryer", celsius=160.0);
    cold_prep = Station(name="cold prep", celsius=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    print("--- Temperature inspection ---");
    root spawn TempInspector();
    print("--- Visit log ---");
    root spawn VisitLogger();
}
