"""Wildlife park feeding rounds.

Kiosk greets every tour party; zookeepers feed animals their species-appropriate
meal (lions get meat, parrots get seed, everyone else gets standard feed);
school groups simply observe the animals.
"""

node Animal {
    has name: str = "";
    has species: str = "";
}

node Lion(Animal) {}
node Parrot(Animal) {}
node Other(Animal) {}

node Kiosk {
    has park_name: str = "Wildlife Park";
}

edge Enclosure {}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can greet with Kiosk entry {
        print(f"Welcome to {here.park_name}!");
        visit [-->];
    }

    can observe with Lion | Parrot | Other entry {
        print(f"  * {here.name} the {here.species} draws an admiring crowd");
        visit [-->];
    }
}

walker Zookeeper {
    can start with Root entry {
        visit [-->];
    }

    can greet with Kiosk entry {
        print(f"Zookeeper reporting for duty at {here.park_name}");
        visit [-->];
    }

    can feed_lion with Lion entry {
        print(f"  -> Serving raw meat to {here.name} the lion");
        visit [-->];
    }

    can feed_parrot with Parrot entry {
        print(f"  -> Mixing fresh seed for {here.name} the parrot");
        visit [-->];
    }

    can feed_other with Other entry {
        print(f"  -> Dropping standard feed for {here.name} the {here.species}");
        visit [-->];
    }
}

walker SchoolGroup {
    can start with Root entry {
        visit [-->];
    }

    can greet with Kiosk entry {
        print("SchoolGroup: hello from the field trip!");
        visit [-->];
    }

    can observe with Lion | Parrot | Other entry {
        print(f"  * students sketch {here.name} the {here.species}");
        visit [-->];
    }
}

with entry {
    kiosk = Kiosk(park_name="Savanna Wildlife Park");
    lion_a = Lion(name="Simba", species="lion");
    lion_b = Lion(name="Nala", species="lion");
    parrot = Parrot(name="Polly", species="parrot");
    giraffe = Other(name="Geoffrey", species="giraffe");
    zebra = Other(name="Zara", species="zebra");

    kiosk +>:Enclosure:+> lion_a;
    kiosk +>:Enclosure:+> lion_b;
    kiosk +>:Enclosure:+> parrot;
    kiosk +>:Enclosure:+> giraffe;
    kiosk +>:Enclosure:+> zebra;
    root ++> kiosk;

    print("=== Tourist round ===");
    root spawn Tourist();
    print("=== Zookeeper round ===");
    root spawn Zookeeper();
    print("=== School group round ===");
    root spawn SchoolGroup();
}
