```jac
"""Restaurant kitchen line health-inspection walker.

Two checks run at every station — temperature audit (flag anything above
40 C as a violation) and a visit log. Using a union trigger for the
audit lets one ability serve all station node types without duplication.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker Inspector {
    has stations_visited: int = 0;
    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can travel with Grill | Fryer | ColdPrep entry {
        self.stations_visited += 1;
        if here.temperature > 40.0 {
            violation = f"{here.name}: {here.temperature}C TOO HOT";
            self.violations.append(violation);
        }
        visit [-->];
    }
}

walker Logger {
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can record with Grill | Fryer | ColdPrep entry {
        self.log.append(f"visited {here.name}");
        visit [-->];
    }
}

with entry {
    root ++> Grill(name="grill", temperature=180.0)
        ++> Fryer(name="fryer", temperature=35.0)
        ++> ColdPrep(name="cold-prep", temperature=50.0);

    inspector = Inspector();
    root spawn inspector;

    logger = Logger();
    root spawn logger;

    print(f"Stations visited: {inspector.stations_visited}");
    print(f"Violations ({len(inspector.violations)}):");
    for v in inspector.violations {
        print(f"  - {v}");
    }
    print("Visit log:");
    for entry in logger.log {
        print(f"  - {entry}");
    }
}
