    assert floor1_idx >= 0, f"missing floor 1 announcement: {out!r}";
    assert floor2_idx >= 0, f"missing floor 2 announcement: {out!r}";
    assert start_idx < floor1_idx, "start announcement must come before floor 1";
    assert floor1_idx < floor2_idx, "floor 1 announcement must come before floor 2";
}

test "walker carries the tour_name provided at spawn" {
    root ++> Floor(floor_number=10, department="Observatory");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Sunset Special");
    }
    out = buf.getvalue();

    assert "Sunset Special" in out, f"custom tour name not announced: {out!r}";
    assert "Floor 10 — Observatory" in out, f"floor stop not announced: {out!r}";
    assert res.tour_name == "Sunset Special", f"walker lost its tour_name: got {res.tour_name!r}";
}

test "graph structure is a linear chain from root through floors" {
    f1 = Floor(floor_number=1, department="Lobby & Reception");
    f2 = Floor(floor_number=2, department="Engineering");
    f3 = Floor(floor_number=3, department="Product");
    f4 = Floor(floor_number=4, department="Executive Suite");
    root ++> f1 ++> f2 ++> f3 ++> f4;

    # Root has exactly one Floor child (the first floor).
    root_kids = [root -->];
    assert len(root_kids) == 1, f"root should have 1 child floor, got {len(root_kids)}";

    # Each floor has exactly one next floor, except the last.
    f1_next = [f1 -->];
    assert len(f1_next) == 1, f"floor 1 should have 1 next floor, got {len(f1_next)}";
    f2_next = [f2 -->];
    assert len(f2_next) == 1, f"floor 2 should have 1 next floor, got {len(f2_next)}";
    f3_next = [f3 -->];
    assert len(f3_next) == 1, f"floor 3 should have 1 next floor, got {len(f3_next)}";
    f4_next = [f4 -->];
    assert len(f4_next) == 0, f"top floor should have no next floor, got {len(f4_next)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name="Structural Walk");
    }
    out = buf.getvalue();

    lines = [l for l in out.splitlines() if l];
    assert len(lines) == 5, f"expected 5 output lines (1 start + 4 floors), got {len(lines)}: {lines}";
