"""Health-inspect a restaurant kitchen line: grill, fryer, cold prep.

Each station's temperature is checked, and any reading above 40 C is flagged
as a violation. Separately, every station visit is logged. Both checks run
at every station."""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
    has threshold: float = 40.0;
}

walker Inspector {
    has log: list[str] = [];
    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with Station entry {
        flagged = here.celsius > here.threshold;
        verdict = "VIOLATION" if flagged else "OK";
        print(f"[{verdict}] {here.name}: {here.celsius}C (limit {here.threshold}C)");
        if flagged {
            self.violations.append(f"{here.name} @ {here.celsius}C");
        }
        self.log.append(here.name);
        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", celsius=185.0);
    fryer = Station(name="Fryer", celsius=165.0);
    cold_prep = Station(name="Cold Prep", celsius=6.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print(f"Visited {len(inspector.log)} stations: {inspector.log}");
    print(f"Violations: {len(inspector.violations)} -> {inspector.violations}");
}
```

