    assert "[VIOLATION] Fryer: 165.0C (limit 40.0C)" in out, f"Fryer should be flagged: {out}";
    assert "[OK] Cold Prep: 6.0C (limit 40.0C)" in out, f"Cold Prep should be OK: {out}";
}

