    assert "Fryer @ 165.0C" in res.violations, f"Fryer missing from violations: {res.violations}";
    assert not any("Cold Prep" in v for v in res.violations), f"Cold Prep should not violate: {res.violations}";
}

test "custom threshold still flags only readings above it" {
    grill = Station(name="Grill", celsius=185.0, threshold=200.0);
    fryer = Station(name="Fryer", celsius=165.0, threshold=150.0);
    cold_prep = Station(name="Cold Prep", celsius=6.0, threshold=40.0);
    root ++> grill ++> fryer ++> cold_prep;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Grill: 185 <= 200 -> OK; Fryer: 165 > 150 -> VIOLATION; Cold Prep: OK
    assert "[OK] Grill: 185.0C (limit 200.0C)" in out, f"Grill should be OK at 185/200: {out}";
    assert "[VIOLATION] Fryer: 165.0C (limit 150.0C)" in out, f"Fryer should violate at 165/150: {out}";
