"""Wildlife park feeding rounds: kiosk greets all visitors, zookeepers feed species-appropriate meals, school groups observe."""

node Kiosk {
    has name: str = "Info Kiosk";
}

node Animal {
    has name: str = "";
    has species: str = "";

    def describe() -> str {
        return f"{self.name} the {self.species}";
    }
}

node Lion(Animal) {
    has mane_color: str = "golden";

    override def describe() -> str {
        return f"{self.name} the lion";
    }
}

node Parrot(Animal) {
    has feather_color: str = "green";

    override def describe() -> str {
        return f"{self.name} the parrot";
    }
}

node OtherAnimal(Animal) {
    has diet_note: str = "";
}

walker TourParty {
    has party_label: str = "Visitors";

    can start with Root entry {
        visit [-->];
    }

    can tour with Kiosk entry {
        print(f"Welcome to the park, {self.party_label}!");
        visit [-->];
    }

    can watch with Animal entry {
        print(f"{self.party_label} watches {here.describe()}");
        visit [-->];
    }
}

walker Zookeeper {
    has badge: str = "Z-001";

    can start with Root entry {
        print(f"Zookeeper {self.badge} starting feeding rounds");
        visit [-->];
    }

    can tour with Kiosk entry {
        visit [-->];
    }

    can feed_lion with Lion entry {
        print(f"Zookeeper {self.badge} feeds {here.name} the lion raw meat");
        visit [-->];
    }

    can feed_parrot with Parrot entry {
        print(f"Zookeeper {self.badge} feeds {here.name} the parrot a seed mix");
        visit [-->];
