"""Kitchen line health-inspection: grill, fryer, cold prep.

Each station carries a temperature. As the inspector visits each station
two abilities fire in turn: one flags temperatures above 40 C as a
violation, the other logs the visit. Both checks run at every station.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker Inspector {
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can move with Station entry {
        visit [-->];
    }

    can flag with Station entry {
        status = "VIOLATION" if here.celsius > 40.0 else "OK";
        print(f"[{status}] {here.name}: {here.celsius} C");
    }

    can record with Station entry {
        self.log.append(here.name);
    }
}

with entry {
    grill = Station(name="Grill", celsius=180.0);
    fryer = Station(name="Fryer", celsius=165.0);
    cold_prep = Station(name="Cold Prep", celsius=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print(f"Visits logged: {inspector.log}");
}
