test "40 C is not a violation (strict greater-than threshold)" {
    import io;
    import from contextlib { redirect_stdout }

    root ++> Station(name="Exactly40", celsius=40.0)
        ++> Station(name="Above40", celsius=40.001);

    inspector = Inspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn inspector;
    }
    out = buf.getvalue();

    assert "[OK] Exactly40: 40.0 C" in out, f"40 C must be OK, got: {out}";
    assert "[VIOLATION] Above40: 40.001 C" in out, f"40.001 C must be VIOLATION, got: {out}";
    assert "VIOLATION" not in out.split("Above40")[0].split("Exactly40")[-1] if False else True;
    # explicit: no VIOLATION line refers to Exactly40
    assert not any("Exactly40" in ln and "VIOLATION" in ln for ln in out.splitlines()), (
        f"Exactly40 should never be a violation, got: {out}"
    );
}

