    # Two stations are above 40 C -> two violations.
    assert res.total_violations == 2, f"expected 2 violations, got {res.total_violations}";

    # Each hot station must print [VIOLATION] with its reading.
    assert "[VIOLATION] Grill @ 180.0 C" in out, f"missing Grill VIOLATION line: {out!r}";
    assert "[VIOLATION] Fryer @ 175.0 C" in out, f"missing Fryer VIOLATION line: {out!r}";
    # Cold station must print [OK].
    assert "[OK] Cold Prep @ 4.0 C" in out, f"missing Cold Prep OK line: {out!r}";
}


# ---------- Test 2: threshold boundary -- 40 C is OK, >40 C is a violation ----------
test "threshold at 40C is OK strictly above is violation" {
    # 40.0 exactly is NOT a violation; 40.0001 is.
    root ++> Station(name="Edge", celsius=40.0)
         ++> Station(name="Over", celsius=40.0001)
         ++> Station(name="Way",  celsius=-5.0);

    inspector = Inspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }
    out = buf.getvalue();

    assert res.stations_visited == 3, f"expected 3 visits, got {res.stations_visited}";
    assert res.total_violations == 1, f"only 40.0001 should violate, got {res.total_violations}";

    assert "[OK] Edge @ 40.0 C"    in out, f"40.0 should be OK: {out!r}";
    assert "[VIOLATION] Over @ 40.0001 C" in out, f"40.0001 should violate: {out!r}";
    assert "[OK] Way @ -5.0 C"     in out, f"negative temp should be OK: {out!r}";
}


# ---------- Test 3: per-station violations counter increments only when hot ----------
test "per-station violations counter" {
    g = Station(name="Grill", celsius=200.0);
    f = Station(name="Fryer", celsius=160.0);
    c = Station(name="Cold Prep", celsius=2.0);
    root ++> g ++> f ++> c;

    inspector = Inspector();
    root spawn inspector;

    # Each hot station's own .violations field must reflect the flag.
    assert g.violations == 1, f"Grill violations expected 1, got {g.violations}";
    assert f.violations == 1, f"Fryer violations expected 1, got {f.violations}";
    assert c.violations == 0, f"Cold Prep violations expected 0, got {c.violations}";
}


