    can enter_kiosk with Kiosk entry {
        visit [-->];
    }

    can observe with Lion | Parrot | Animal entry {
        print(f"  [School] '{self.group_name}' watches {here.name} the {here.species}.");
        visit [-->];
    }
}

with entry {
    kiosk = Kiosk(name="Entrance");
    lion = Lion(species="lion", name="Simba");
    parrot = Parrot(species="parrot", name="Polly");
    zebra = Animal(species="zebra", name="Ziggy");

    root ++> kiosk ++> lion ++> parrot ++> zebra;

    keeper = Zookeeper(badge="Z-42");
    root spawn keeper;

    print("");
    students = SchoolGroup(group_name="Grade 3A");
    root spawn students;
}
