        self.patient_names.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"Shot given to {here.name} ({here.species})");
        } else {
            print(f"No shot needed for {here.name} ({here.species})");
        }
        visit [-->] else { disengage; }
    }
}

