"""Health-inspect a restaurant kitchen line (grill, fryer, cold prep).

Two parallel inspections run at every station:
  1. Temperature check -- flag any station above 40 C as a violation.
  2. Visit log -- record every station the inspector passes through.
"""

# Three station archetypes share a common base so a single union ability
# can handle all of them at once.
node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Grill(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node Fryer(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

node ColdPrep(Station) {
    override def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

# The inspector carries two running tallies: violations found and a log
# of every station it visited.
walker HealthInspector {
    has violations: int = 0;
    has visit_log: list[str] = [];

    can start with Root entry {
        print("Health inspector beginning kitchen walk-through");
        visit [-->];
    }

    # Union trigger: fires once for Grill, Fryer, OR ColdPrep.
    # Both the temperature check and the visit log happen here, so
    # every station is inspected AND logged in a single ability.
    can inspect with Grill | Fryer | ColdPrep entry {
        station_name = here.name;
        self.visit_log.append(station_name);
        if here.is_violation() {
            self.violations += 1;
            print(f"[VIOLATION] {station_name} at {here.temperature} C");
        } else {
            print(f"[OK] {station_name} at {here.temperature} C");
        }
        visit [-->];
    }
}

with entry {
    grill = Grill(name="Grill", temperature=180.0);
    fryer = Fryer(name="Fryer", temperature=175.0);
    cold_prep = ColdPrep(name="ColdPrep", temperature=4.0);
    root ++> grill ++> fryer ++> cold_prep;

    inspector = HealthInspector();
    root spawn inspector;

    print(f"Inspector logged visits: {inspector.visit_log}");
    print(f"Total violations found: {inspector.violations}");
}
