"""Tests for the kitchen health-inspection walker."""

import io;
import from contextlib { redirect_stdout }

# ---------- 1. Both checks run at EVERY station ------------------------------

test "both checks fire at every station" {
    root ++> Grill(station_name="Grill", celsius=180.0)
        ++> Fryer(station_name="Fryer", celsius=175.0)
        ++> ColdPrep(station_name="Cold Prep", celsius=4.0)
        ++> Grill(station_name="Salamander", celsius=55.0)
        ++> ColdPrep(station_name="Salad Bar", celsius=6.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # 1) Temperature branch fired for each of the 5 stations
    assert "[VIOLATION] Grill" in out, f"missing Grill violation line: {out}";
    assert "[VIOLATION] Fryer" in out, f"missing Fryer violation line: {out}";
    assert "[VIOLATION] Salamander" in out, f"missing Salamander violation line: {out}";
    assert "[ok]        Cold Prep" in out, f"missing Cold Prep ok line: {out}";
    assert "[ok]        Salad Bar" in out, f"missing Salad Bar ok line: {out}";

    # 2) Visit log captured every station (both checks, not just one type)
    assert res.log == ["Grill", "Fryer", "Cold Prep", "Salamander", "Salad Bar"],
        f"log should record every station in order, got {res.log}";
    assert len(res.log) == 5, f"expected 5 logged visits, got {len(res.log)}";
}


# ---------- 2. Violation threshold: > 40 C is a violation, <= 40 C is not ---

test "violation threshold is strictly above 40 C" {
    # Boundary cases around 40 C, plus extremes.
    root ++> Grill(station_name="At40", celsius=40.0)
        ++> Fryer(station_name="At41", celsius=41.0)
        ++> ColdPrep(station_name="JustOver", celsius=40.1)
        ++> Grill(station_name="VeryCold", celsius=-5.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Exactly 40 C is NOT a violation; anything strictly above is.
    assert "[ok]        At40 reads 40.0 C" in out, f"40 C must be ok: {out}";
    assert "[VIOLATION] At41 reads 41.0 C" in out, f"41 C must be flagged: {out}";
    assert "[VIOLATION] JustOver reads 40.1 C" in out, f"40.1 C must be flagged: {out}";
    assert "[ok]        VeryCold reads -5.0 C" in out, f"sub-zero must be ok: {out}";

    assert res.violations == 2,
        f"expected 2 violations (At41, JustOver), got {res.violations}";
}


# ---------- 3. Visit log is independent of violation count -------------------

test "visit log records every stop regardless of temperature outcome" {
    # Two stations: one violating, one safe. Both must be logged.
    grill = Grill(station_name="Hot Grill", celsius=200.0);
    cold = ColdPrep(station_name="Cold Station", celsius=2.0);
    root ++> grill ++> cold;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }

    # Log proves the visit-happened check ran on BOTH stations, even though
    # the violation count only reflects the hot one.
    assert "Hot Grill" in res.log, f"violating station should still be logged: {res.log}";
    assert "Cold Station" in res.log, f"safe station should be logged: {res.log}";
    assert res.violations == 1, f"exactly one violation expected, got {res.violations}";
    assert len(res.log) == 2, f"both stations must be in log: {res.log}";
}


# ---------- 4. Union ability covers every station subtype -------------------

test "union ability fires on Grill, Fryer, and ColdPrep alike" {
    # Build a graph containing all three concrete subtypes.
    root ++> Grill(station_name="G", celsius=180.0)
        ++> Fryer(station_name="F", celsius=180.0)
        ++> ColdPrep(station_name="C", celsius=180.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # The single union ability must trigger for each subtype (no per-type
    # ability shadows it). If it only fired on one type, others would be
    # missing from both stdout and the log.
    assert "G reads 180.0 C" in out, f"Grill branch not fired: {out}";
    assert "F reads 180.0 C" in out, f"Fryer branch not fired: {out}";
    assert "C reads 180.0 C" in out, f"ColdPrep branch not fired: {out}";

    assert res.log == ["G", "F", "C"], f"all three subtypes must be logged: {res.log}";
    assert res.violations == 3, f"all three over 40 C, expected 3 violations, got {res.violations}";
}


# ---------- 5. Graph shape -- the inspector actually traversed it -----------

test "inspector reaches all stations linked from root" {
    root ++> Grill(station_name="A", celsius=10.0)
        ++> Fryer(station_name="B", celsius=20.0)
        ++> ColdPrep(station_name="C", celsius=30.0)
        ++> Grill(station_name="D", celsius=40.0)
        ++> ColdPrep(station_name="E", celsius=50.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }

    # Every station wired into the chain must appear in the log -- confirms
    # the walk followed edges off of root, not just the first node.
    assert len(res.log) == 5,
        f"inspector should visit all 5 linked stations, got {len(res.log)}: {res.log}";
    assert res.violations == 1,
        f"only E is over 40 C, expected 1 violation, got {res.violations}";
    assert "E" in res.log and res.log[-1] == "E",
        f"E must be visited and is the last in the chain: {res.log}";
}

