"""Orchard maintenance crew: tour groves and service pumps and sprinklers in one shared routine.

Models irrigation devices as nodes with a typed 'HasHoursIdle' counter field. A maintenance
walker traverses the grove and a single union ability handles both pump and sprinkler entries,
logging the device kind, idle hours, resetting the counter, and reporting the running total.
"""

node Pump {
    has hours_idle: int = 0;
}

node Sprinkler {
    has hours_idle: int = 0;
}

edge HasHoursIdle {
    has hours: int = 0;
}

walker MaintenanceCrew {
    has serviced: int = 0;

    can start with Root entry {
        print("Crew dispatched to the orchard grove");
        visit [-->];
    }

    can grove_walk with Pump | Sprinkler entry {
        kind_label = "Pump" if isinstance(here, Pump) else "Sprinkler";
        idle = here.hours_idle;
        print(f"[SERVICED] {kind_label} sat idle for {idle} hours");
        here.hours_idle = 0;
        self.serviced += 1;
        visit [-->] else { disengage; }
    }
}

with entry {
    pump_a = Pump(hours_idle=42);
    sprinkler_a = Sprinkler(hours_idle=7);
    pump_b = Pump(hours_idle=15);
    sprinkler_b = Sprinkler(hours_idle=23);

    root ++> pump_a
        ++> sprinkler_a
        ++> pump_b
        ++> sprinkler_b;

    crew = MaintenanceCrew();
    root spawn crew;

    print(f"Total devices serviced: {crew.serviced}");
}
