"""Wildlife park feeding rounds: kiosk greets all, zookeepers feed by species, school groups observe."""

node Animal {
    has species: str = "";
    has name: str = "";
}

node Lion(Animal) {
    has mane_size: int = 0;
}

node Parrot(Animal) {
    has vocabulary: int = 0;
}

node OtherAnimal(Animal) {}

walker Visitor {
    has party: str = "";

    can start with Root entry {
        print(f"Info kiosk: welcome, {self.party}!");
        visit [-->];
    }

    can observe with Lion | Parrot | OtherAnimal entry {
        print(f"{self.party} is watching {here.name} the {here.species}");
        visit [-->];
    }
}

walker Zookeeper {
    can start with Root entry {
        print("Zookeeper on duty: starting feeding rounds");
        visit [-->];
    }

