"""Kitchen health inspection: walk the line and flag any station above 40 C,
while logging every station visit. Both checks run at each station via
separate abilities that trigger on each visit."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

walker Inspector {
    has violation_count: int = 0;
    has visits: int = 0;

    can start with Root entry {
        print("Inspector beginning kitchen walk-through");
        visit [-->];
    }

    can advance with Station entry {
        # traversal continues after both checks complete
        visit [-->];
    }

    # First check: temperature violation flag
    can check_temperature with Station entry {
        self.visits += 1;
        if here.temperature > 40.0 {
            self.violation_count += 1;
            print(f"  VIOLATION: {here.name} at {here.temperature} C exceeds 40 C");
        } else {
            print(f"  OK: {here.name} at {here.temperature} C");
        }
    }

    # Second check: visit log (independent of temperature reading)
    can log_visit with Station entry {
        print(f"  LOG: visited station '{here.name}'");
    }
}

with entry {
    grill = Station(name="Grill", temperature=85.0);
    fryer = Station(name="Fryer", temperature=38.0);
    cold_prep = Station(name="Cold Prep", temperature=150.0);
    dishwashing = Station(name="Dishwashing", temperature=22.0);

    root ++> grill ++> fryer ++> cold_prep ++> dishwashing;

    inspector = Inspector();
    root spawn inspector;

    print(f"\nInspection complete: {inspector.visits} stations visited, "
          f"{inspector.violation_count} violations flagged");
}
