each animal its species-appropriate meal (meat for lions, seed for
parrots, standard feed otherwise), and school groups just observe.
"""

node Animal {
    has species: str = "";
    has name: str = "";
    has meal: str = "";
    has fed: bool = False;

    def species_kind() -> str {
        return self.species;
    }
}

node Lion(Animal) {
    has species: str = "lion";
    has meal: str = "meat";
    override def species_kind() -> str {
