"""Wildlife park feeding rounds.

A kiosk greets every tour party, zookeepers feed each animal its
species-appropriate meal, and school groups only observe. Walker
abilities trigger on the relevant archetypes via typed-entry unions.
"""

node Lion { has name: str = ""; }
node Parrot { has name: str = ""; }
node Animal { has name: str = ""; }

node Kiosk { has greeting: str = "Welcome to the wildlife park!"; }

walker TourParty {
    has party_label: str = "Visitors";

    can start with Root entry {
        print(self.party_label + " arriving at the park");
        visit [-->];
    }

    can greet with Kiosk entry {
        print(here.greeting);
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        print(self.party_label + " observes " + here.name);
        visit [-->];
    }
}

walker Zookeeper {
    has keeper_name: str = "Keeper";

    can start with Root entry {
        print(self.keeper_name + " beginning feeding rounds");
        visit [-->];
    }

    can greet_kiosk with Kiosk entry {
        print(self.keeper_name + " nods at the kiosk");
        visit [-->];
