"""Data center clearance enforcement: technicians walk rooms; deeper rooms require higher clearance."""

node ServerRoom {
    has name: str = "";
    has clearance_required: int = 1;
}

walker Technician {
    has badge_id: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
