    can start with Root entry {
        print(f"Technician {self.badge_id} (clearance={self.clearance}) entering data center");
        visit [-->];
    }

    can approach with ServerRoom entry {
        if self.denied {
            visit [-->] else { disengage; }
        } elif self.clearance >= here.clearance_required {
            self.rooms_reached += 1;
            print(f"  GRANTED  [{self.badge_id}] -> {here.name} (needs {here.clearance_required})");
            visit [-->] else { disengage; }
        } else {
            self.denied = True;
            print(f"  DENIED   [{self.badge_id}] -> {here.name} (needs {here.clearance_required}, has {self.clearance}) -- walkthrough ended");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    lobby = ServerRoom(name="Lobby", clearance_required=0);
    staging = ServerRoom(name="Staging", clearance_required=1);
    prod = ServerRoom(name="Production", clearance_required=3);
