"""Weather sweep: walk weather stations, report temperatures, then summarize."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_c: float = 0.0;
    has max_c: float = 0.0;
    has seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can record with WeatherStation entry {
        print(f"{here.location}: {here.celsius}C");
        self.readings.append(here.celsius);
        if self.seen == 0 {
            self.min_c = here.celsius;
            self.max_c = here.celsius;
            self.seen = 1;
        } else {
            if here.celsius < self.min_c {
                self.min_c = here.celsius;
            }
            if here.celsius > self.max_c {
                self.max_c = here.celsius;
            }
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> WeatherStation(location="Boston", celsius=22.5)
        ++> WeatherStation(location="Chicago", celsius=-3.0)
        ++> WeatherStation(location="Miami", celsius=31.2)
        ++> WeatherStation(location="Denver", celsius=15.0);

    sweep = WeatherSweep();
    root spawn sweep;

    print(f"All readings: {sweep.readings}");
    print(f"Min: {sweep.min_c}C, Max: {sweep.max_c}C");
}
```

jac_tests:
"""Tests for the weather sweep walker."""

import io;
import from contextlib { redirect_stdout }

test "records all station readings in visitation order" {
    root ++> WeatherStation(location="Boston", celsius=22.5)
        ++> WeatherStation(location="Chicago", celsius=-3.0)
        ++> WeatherStation(location="Miami", celsius=31.2)
        ++> WeatherStation(location="Denver", celsius=15.0);

    sweep = WeatherSweep();
    root spawn sweep;

    assert len(sweep.readings) == 4, f"expected 4 readings, got {len(sweep.readings)}";
    assert sweep.readings[0] == 22.5, f"first reading should be 22.5, got {sweep.readings[0]}";
    assert sweep.readings[1] == -3.0, f"second reading should be -3.0, got {sweep.readings[1]}";
    assert sweep.readings[2] == 31.2, f"third reading should be 31.2, got {sweep.readings[2]}";
    assert sweep.readings[3] == 15.0, f"fourth reading should be 15.0, got {sweep.readings[3]}";
}

test "computes min and max across all stations" {
    root ++> WeatherStation(location="A", celsius=10.0)
        ++> WeatherStation(location="B", celsius=-5.0)
        ++> WeatherStation(location="C", celsius=25.0)
        ++> WeatherStation(location="D", celsius=0.0);

    sweep = WeatherSweep();
    root spawn sweep;

    assert sweep.min_c == -5.0, f"min should be -5.0, got {sweep.min_c}";
    assert sweep.max_c == 25.0, f"max should be 25.0, got {sweep.max_c}";
    assert sweep.seen == 1, f"seen flag should be 1 after walk, got {sweep.seen}";
}

test "prints each station with location and temperature" {
    root ++> WeatherStation(location="Boston", celsius=22.5)
        ++> WeatherStation(location="Chicago", celsius=-3.0);

    buf = io.StringIO();
    sweep = WeatherSweep();
    with redirect_stdout(buf) {
        root spawn sweep;
    }
    out = buf.getvalue();

    assert "Boston: 22.5C" in out, f"missing Boston line: {out}";
    assert "Chicago: -3.0C" in out, f"missing Chicago line: {out}";
    assert out.count("C\n") == 2 or out.count(": ") == 2, f"expected 2 station lines, got: {out}";
}

test "handles single station without errors" {
    root ++> WeatherStation(location="Solo", celsius=18.0);

    buf = io.StringIO();
    sweep = WeatherSweep();
    with redirect_stdout(buf) {
        root spawn sweep;
    }
    out = buf.getvalue();

    assert len(sweep.readings) == 1, f"expected 1 reading, got {len(sweep.readings)}";
    assert sweep.min_c == 18.0, f"min should equal sole reading 18.0, got {sweep.min_c}";
    assert sweep.max_c == 18.0, f"max should equal sole reading 18.0, got {sweep.max_c}";
    assert "Solo: 18.0C" in out, f"missing Solo line: {out}";
}

test "handles two station chain" {
    root ++> WeatherStation(location="First", celsius=7.0)
        ++> WeatherStation(location="Last", celsius=42.0);

    sweep = WeatherSweep();
    root spawn sweep;

    assert len(sweep.readings) == 2, f"expected 2 readings, got {len(sweep.readings)}";
    assert sweep.readings == [7.0, 42.0], f"readings should be [7.0, 42.0], got {sweep.readings}";
    assert sweep.min_c == 7.0, f"min should be 7.0, got {sweep.min_c}";
    assert sweep.max_c == 42.0, f"max should be 42.0, got {sweep.max_c}";
}

