"""Office tower tour: floors announce stops as a guide walker ascends the building."""

node Floor {
    has number: int = 0;
    has department: str = "";

    can announce_stop with TourGuide entry {
        print(f"Stop {self.number}: {self.department}");
    }
}

walker TourGuide {
    has tour_name: str = "";

    can start with Root entry {
        print(f"Welcome to the {self.tour_name} tour!");
        visit [-->];
    }

    can ascend with Floor entry {
        visit [-->];
    }
}

with entry {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suite");
    root spawn TourGuide(tour_name="Skyline Tower");
}
