"""Tests for office tower tour walker."""

import io;
import from contextlib { redirect_stdout }

test "tour guide announces tour name at root" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Skyline Tower");
    }
    out = buf.getvalue();
    lines = out.split("\n");

    assert "Welcome to the Skyline Tower tour!" in lines, f"missing welcome line, got: {lines!r}";
}

test "each floor announces its stop during tour" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Skyline Tower");
    }
    out = buf.getvalue();
    lines = out.split("\n");

    assert "Stop 1: Lobby & Reception" in lines, f"missing floor 1 stop, got: {lines!r}";
    assert "Stop 2: Human Resources" in lines, f"missing floor 2 stop, got: {lines!r}";
    assert "Stop 3: Engineering" in lines, f"missing floor 3 stop, got: {lines!r}";
    assert "Stop 4: Executive Suite" in lines, f"missing floor 4 stop, got: {lines!r}";
}

test "welcome line precedes floor stops" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Skyline Tower");
    }
    out = buf.getvalue();
    lines = out.split("\n");

    welcome_idx = lines.index("Welcome to the Skyline Tower tour!");
    stop1_idx = lines.index("Stop 1: Lobby & Reception");
    stop4_idx = lines.index("Stop 4: Executive Suite");
    assert welcome_idx < stop1_idx, f"welcome should come before stops: {lines!r}";
    assert stop1_idx < stop4_idx, f"stops should be in chain order: {lines!r}";
}

test "tour name is taken from walker field" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Penthouse Express");
    }
    out = buf.getvalue();
    lines = out.split("\n");

    assert "Welcome to the Penthouse Express tour!" in lines, f"custom tour name not used: {lines!r}";
}

test "tower has exactly one direct child from root with chain of four floors" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suite");

    assert len([root-->]) == 1, f"root should have 1 direct child in a chain, got {len([root-->])}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Skyline Tower");
    }
    out = buf.getvalue();
    assert out.count("Stop ") == 4, f"should visit 4 floors, got stop count {out.count('Stop ')} in: {out!r}";
}

