jac_tests:
"""Test annex for the office tower tour program."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------
test "tour guide announces tour name at root" {
    root ++> Floor(floor_number=1, department="Lobby")
        ++> Floor(floor_number=2, department="Finance")
        ++> Floor(floor_number=3, department="Engineering")
        ++> Floor(floor_number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Corporate Tower");
    }
    out = buf.getvalue();

    assert "Welcome to the Corporate Tower tour!" in out, f"missing welcome line: {out!r}";

    # The welcome message must come before any floor announcements.
    welcome_idx = out.index("Welcome to the Corporate Tower tour!");
    first_stop_idx = out.index("Stop 1: Lobby");
    assert welcome_idx < first_stop_idx, f"welcome ({welcome_idx}) should precede first stop ({first_stop_idx}): {out!r}";
}

# ---------------------------------------------------------------
test "each floor presents its own stop in order" {
    root ++> Floor(floor_number=1, department="Lobby")
        ++> Floor(floor_number=2, department="Finance")
        ++> Floor(floor_number=3, department="Engineering")
        ++> Floor(floor_number=4, department="Executive Suite");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Skyline");
    }
    out = buf.getvalue();

    # Every floor must announce itself with its number and department.
    assert "Stop 1: Lobby" in out, f"missing lobby stop: {out!r}";
    assert "Stop 2: Finance" in out, f"missing finance stop: {out!r}";
    assert "Stop 3: Engineering" in out, f"missing engineering stop: {out!r}";
    assert "Stop 4: Executive Suite" in out, f"missing executive stop: {out!r}";

    # The four floor announcements must appear in increasing-floor order.
    idx1 = out.index("Stop 1: Lobby");
    idx2 = out.index("Stop 2: Finance");
    idx3 = out.index("Stop 3: Engineering");
    idx4 = out.index("Stop 4: Executive Suite");
    assert idx1 < idx2 < idx3 < idx4, f"stops out of order: 1@{idx1} 2@{idx2} 3@{idx3} 4@{idx4}";

    # Exactly four stop lines should be emitted.
    assert out.count("Stop ") == 4, f"expected 4 stop announcements, got {out.count('Stop ')}: {out!r}";
}

# ---------------------------------------------------------------
test "tour_name is configurable via spawn arg" {
    root ++> Floor(floor_number=1, department="Lobby");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Penthouse Preview");
    }
    out = buf.getvalue();

    assert "Welcome to the Penthouse Preview tour!" in out, f"custom tour_name not used: {out!r}";
    assert "Stop 1: Lobby" in out, f"lobby stop missing: {out!r}";

    # The default tour_name is empty, so a default-spawned guide must NOT
    # advertise a Corporate Tower or Penthouse Preview tour.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        res2 = root spawn TourGuide();
    }
    out2 = buf2.getvalue();

    assert "Welcome to the  tour!" in out2, f"default tour_name not empty: {out2!r}";
    assert "Corporate Tower" not in out2, f"default leaked Corporate Tower: {out2!r}";
}

# ---------------------------------------------------------------
test "graph has exactly four floors chained off root" {
    root ++> Floor(floor_number=1, department="Lobby")
        ++> Floor(floor_number=2, department="Finance")
        ++> Floor(floor_number=3, department="Engineering")
        ++> Floor(floor_number=4, department="Executive Suite");

    # Root must have exactly one outgoing edge to the lobby floor.
    root_neighbors = [root-->];
    assert len(root_neighbors) == 1, f"root should have 1 child, got {len(root_neighbors)}";

    lobby = root_neighbors[0];
    assert isinstance(lobby, Floor), f"root's child should be a Floor, got {type(lobby)}";
    assert lobby.floor_number == 1, f"first floor should be #1, got {lobby.floor_number}";
    assert lobby.department == "Lobby", f"first floor should be Lobby, got {lobby.department!r}";

    # Walk the chain manually and verify floor numbers are 1..4 in order.
    chain = [];
    cur = lobby;
    while cur is not None {
        chain.append(cur);
        nxts = [cur-->];
        cur = nxts[0] if len(nxts) > 0 else None;
    }
    assert len(chain) == 4, f"chain should have 4 floors, got {len(chain)}";
    assert [f.floor_number for f in chain] == [1, 2, 3, 4], f"unexpected floor numbers: {[f.floor_number for f in chain]}";
    assert [f.department for f in chain] == ["Lobby", "Finance", "Engineering", "Executive Suite"], f"unexpected departments: {[f.department for f in chain]}";

    # Sanity: spawning the guide actually walks all four floors (each presents a stop).
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Express");
    }
    out = buf.getvalue();
    assert all(f"Stop {f.floor_number}: {f.department}" in out for f in chain), f"not every floor announced: {out!r}";
}

