```jac
"""Restaurant kitchen line health inspection.

Each station (grill, fryer, cold prep) reports its current temperature.
A health inspector walker visits every station, flagging temperatures
above 40 C as a violation. Simultaneously, every station visit is logged
on a separate audit walker. Both inspections run on the same line.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

node Grill(Station) {}
node Fryer(Station) {}
node ColdPrep(Station) {}

walker HealthInspector {
    can start with Root entry {
        print("Health inspector beginning line walk");
        visit [-->];
    }

    can inspect with Station entry {
        violation = here.celsius > 40.0;
        if violation {
            print(f"  [VIOLATION] {here.name} at {here.celsius} C exceeds 40 C");
        } else {
            print(f"  [OK] {here.name} at {here.celsius} C");
        }
        visit [-->];
    }
}

walker VisitLogger {
    can start with Root entry {
        print("Audit log opened");
        visit [-->];
    }

    can log with Station entry {
        print(f"  [LOG] visited {here.name} ({here.celsius} C)");
        visit [-->];
    }
}

with entry {
    grill = Grill(name="Grill", celsius=180.0);
    fryer = Fryer(name="Fryer", celsius=22.0);
    cold = ColdPrep(name="Cold Prep", celsius=45.5);
    root ++> grill ++> fryer ++> cold;

    root spawn HealthInspector();
    print("---");
    root spawn VisitLogger();
}
```

jac_tests:
import io;
import from contextlib { redirect_stdout }

test "health inspector flags only stations above 40 C" {
    root ++> Grill(name="Grill", celsius=180.0)
         ++> Fryer(name="Fryer", celsius=22.0)
         ++> ColdPrep(name="Cold Prep", celsius=45.5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn HealthInspector();
    }
    out = buf.getvalue();

    assert "Health inspector beginning line walk" in out, f"missing intro line: {out}";
    assert "[VIOLATION] Grill at 180.0 C exceeds 40 C" in out, f"grill should violate: {out}";
    assert "[VIOLATION] Cold Prep at 45.5 C exceeds 40 C" in out, f"cold prep should violate: {out}";
    assert "[OK] Fryer at 22.0 C" in out, f"fryer should be ok: {out}";
    # Make sure OK line is not mistakenly a violation
    assert "Fryer at 22.0 C exceeds 40 C" not in out, f"fryer incorrectly flagged: {out}";
}

test "visit logger logs every station" {
    root ++> Grill(name="Grill", celsius=180.0)
         ++> Fryer(name="Fryer", celsius=22.0)
         ++> ColdPrep(name="Cold Prep", celsius=45.5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn VisitLogger();
    }
    out = buf.getvalue();

    assert "Audit log opened" in out, f"missing audit open line: {out}";
    assert "[LOG] visited Grill (180.0 C)" in out, f"grill not logged: {out}";
    assert "[LOG] visited Fryer (22.0 C)" in out, f"fryer not logged: {out}";
    assert "[LOG] visited Cold Prep (45.5 C)" in out, f"cold prep not logged: {out}";
    # Three log entries, one per station
    assert out.count("[LOG] visited") == 3, f"expected 3 log entries, got: {out}";
}

test "exact 40 C boundary is not a violation" {
    # 40.0 should be OK (not > 40). 40.1 should violate.
    root ++> Grill(name="Grill", celsius=40.0)
         ++> ColdPrep(name="Cold Prep", celsius=40.1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn HealthInspector();
    }
    out = buf.getvalue();

    assert "[OK] Grill at 40.0 C" in out, f"40.0 must be OK: {out}";
    assert "[VIOLATION] Cold Prep at 40.1 C exceeds 40 C" in out, f"40.1 must violate: {out}";
}

test "inspector and logger both visit same stations" {
    root ++> Grill(name="Grill", celsius=180.0)
         ++> Fryer(name="Fryer", celsius=22.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn HealthInspector();
        print("---");
        root spawn VisitLogger();
    }
    out = buf.getvalue();

    # Both walks must visit both stations
    assert out.count("[LOG] visited") == 2, f"logger should visit both: {out}";
    # One violation (grill) and one OK (fryer)
    assert out.count("[VIOLATION]") == 1, f"expected exactly one violation: {out}";
    assert out.count("[OK]") == 1, f"expected exactly one OK: {out}";
}

