"""Moderation sweep over game accounts.

Member accounts are audited normally; admin accounts have their
reputation boosted by 5. The welcome desk greets every bot that
passes through, regardless of which walker is doing the visiting.
"""

node Account {
    has owner: str = "";
    has reputation: int = 0;
    has kind_label: str = "";
}

node Member(Account) {
    has member_level: int = 1;
}

node Admin(Account) {
    has admin_role: str = "";
}

node Bot {
    has bot_name: str = "";
}

walker Moderator {
    has visited_admins: list[str] = [];

    can start with Root entry {
        print("Beginning moderation sweep...");
        visit [-->];
    }

    can audit with Member | Admin entry {
        if here.kind_label == "admin" {
            here.reputation = here.reputation + 5;
            self.visited_admins.append(here.owner);
            print(f"[BOOST] admin {here.owner} reputation -> {here.reputation}");
        } else {
            print(f"[AUDIT] member {here.owner} reputation={here.reputation}");
        }
        visit [-->];
    }

    can greet with Bot entry {
        print(f"Welcome bot {here.bot_name}!");
        visit [-->];
    }
}

with entry {
    m = Member(owner="alice", member_level=3, kind_label="member");
    a = Admin(owner="boss", admin_role="owner", reputation=10, kind_label="admin");
    b = Bot(bot_name="HelperBot");

    root ++> m ++> a ++> b;

    mod = Moderator();
    root spawn mod;
}
