"""Wildlife park feeding rounds: kiosk greets every party, zookeepers feed animals their species-appropriate meal, and school groups just observe."""

node Animal {
    has species: str = "";
    has name: str = "";
    has fed: bool = False;

    def meal() -> str {
        return "standard feed";
    }

    def feed() -> None {
        self.fed = True;
    }
}

node Lion(Animal) {
    override def meal() -> str {
        return "meat";
    }
}

node Parrot(Animal) {
    override def meal() -> str {
        return "seed";
    }
}

# Generic party base — kiosk must accept ANY party.
node TourParty {
    has label: str = "";
}

node Family(TourParty) {}
node School(TourParty) {}

# --- Walkers ---

# The info kiosk greets EVERY tour party regardless of type.
walker InfoKiosk {
    has greeted_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can greet with TourParty entry {
        print(f"Kiosk: welcome, {here.label}!");
        self.greeted_count += 1;
        visit [-->];
    }

    can greet_animals with Animal | Lion | Parrot entry {
        print(f"Kiosk: welcome, {here.species} named {here.name}!");
        self.greeted_count += 1;
        visit [-->];
    }
}

# Zookeepers feed each animal its species-appropriate meal.
walker Zookeeper {
    can start with Root entry {
        visit [-->];
    }

    can tour with TourParty entry {
        visit [-->];
    }

    can feed with Lion | Parrot | Animal entry {
        here.feed();
        print(f"Zookeeper: {here.name} the {here.species} gets {here.meal()}.");
        visit [-->];
    }
}

# School groups just watch the animals.
walker SchoolGroup {
    can start with Root entry {
        visit [-->];
    }

    can tour with TourParty entry {
        print(f"SchoolGroup: excited to visit {here.label}!");
        visit [-->];
    }

    can watch with Animal | Lion | Parrot entry {
        print(f"SchoolGroup: watching {here.name} the {here.species}.");
        visit [-->];
    }
}

with entry {
    lion = Lion(species="Lion", name="Leo");
    parrot = Parrot(species="Parrot", name="Polly");
    zebra = Animal(species="Zebra", name="Zara");

    family_party = Family(label="the Patel family");
    school_party = School(label="Mr. Ng's grade 3 class");

    root ++> family_party ++> lion;
    root ++> school_party ++> parrot;
    root ++> zebra;

    # The kiosk greets every tour party regardless of who they are.
    print("=== Info kiosk rounds ===");
    kiosk = InfoKiosk();
    root spawn kiosk;
    print(f"Kiosk greeted {kiosk.greeted_count} entities.\n");

    # Zookeepers feed each animal its species-appropriate meal.
    print("=== Zookeeper rounds ===");
    root spawn Zookeeper();
    print("");

    # School groups just watch the animals.
    print("=== School group rounds ===");
    school = SchoolGroup();
    root spawn school;

    print("\nFeeding complete.");
}
