import io;
import from contextlib { redirect_stdout }

# Build a kitchen line and run the inspector.
# Verify both union abilities (check_temp AND log_visit) fire at every
# station, violations flag only stations above 40 C, and the visit log
# records every station exactly once.

test "all stations above threshold flag as violations" {
    root ++> Grill(name="Char-broiler", celsius=220.0)
        ++> Fryer(name="Deep fryer", celsius=180.0)
        ++> ColdPrep(name="Salad station", celsius=55.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }

    assert res.violations == 3, f"expected 3 violations, got {res.violations}";
    assert "[VIOLATION]" in buf.getvalue(), "missing VIOLATION marker";
    assert "[OK]" not in buf.getvalue(), "no station should be OK";

    # All three stations must still be logged (both checks fire at every station).
    assert len(res.visits) == 3, f"expected 3 visits, got {len(res.visits)}";
    assert "Char-broiler (grill)" in res.visits, f"grill missing from visits: {res.visits}";
    assert "Deep fryer (fryer)" in res.visits, f"fryer missing from visits: {res.visits}";
    assert "Salad station (cold prep)" in res.visits, f"cold prep missing from visits: {res.visits}";
}

test "all stations below threshold are safe with no violations" {
    root ++> Grill(name="Warm grill", celsius=38.0)
        ++> Fryer(name="Cool fryer", celsius=20.0)
        ++> ColdPrep(name="Salad station", celsius=4.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }

    assert res.violations == 0, f"expected 0 violations, got {res.violations}";
    out = buf.getvalue();
    assert "[VIOLATION]" not in out, "no violation should be printed";
    assert "[OK]" in out, "expected OK markers for safe stations";

    # Visit log still records every station.
    assert len(res.visits) == 3, f"expected 3 visits, got {len(res.visits)}";
}

test "mixed temperatures flag only the hot ones" {
    root ++> Grill(name="Char-broiler", celsius=220.0)
        ++> Fryer(name="Deep fryer", celsius=35.0)
        ++> ColdPrep(name="Salad station", celsius=4.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }

    # Only the grill exceeds 40 C.
    assert res.violations == 1, f"expected 1 violation, got {res.violations}";

    out = buf.getvalue();
    assert "[VIOLATION] Char-broiler (grill) at 220.0 C exceeds 40 C" in out, out;
    assert "[OK] Deep fryer (fryer) at 35.0 C is safe" in out, out;
    assert "[OK] Salad station (cold prep) at 4.0 C is safe" in out, out;

    # Both checks still fire at every station: 3 visits total, grill first.
    assert len(res.visits) == 3, f"expected 3 visits, got {len(res.visits)}";
    assert res.visits[0] == "Char-broiler (grill)", f"visit order: {res.visits}";
}

test "boundary temperature of exactly 40 C is not a violation" {
    root ++> Grill(name="Edge grill", celsius=40.0)
        ++> Fryer(name="Edge fryer", celsius=40.0)
        ++> ColdPrep(name="Edge cold", celsius=40.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }

    # Threshold is strict > 40, so 40.0 exactly is safe.
