    assert "[VIOLATION]" not in buf.getvalue(), "40.0 should not violate";

    # But visit log still runs at every station.
    assert len(res.visits) == 3, f"expected 3 visits, got {len(res.visits)}";
    assert "Edge grill (grill)" in res.visits;
    assert "Edge fryer (fryer)" in res.visits;
    assert "Edge cold (cold prep)" in res.visits;
}

test "single station spawns log and check together" {
    root ++> Grill(name="Solo grill", celsius=95.0);

