    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn inspector;
    }

    assert res.violations == 1, f"expected 1 violation, got {res.violations}";
    # Both abilities fired: violation message AND log message for the same station.
    out = buf.getvalue();
    assert "[VIOLATION] Solo grill (grill) at 95.0 C exceeds 40 C" in out, out;
    assert "[LOG] visited Solo grill (grill)" in out, out;
    assert res.visits == ["Solo grill (grill)"], f"visits: {res.visits}";
}

