```jac
"""Health-inspect a restaurant kitchen line: grill, fryer, cold prep.

A patrol walker visits each station and runs two checks at every stop:
a temperature audit (anything above 40 C is a violation) and a visit log
(every station visited is recorded). Both checks fire at every station.
"""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
}

walker Inspector {
    has station_log: list[str] = [];
    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Station entry {
        # Check 1: temperature audit. Anything above 40 C is a violation.
        if here.temperature > 40.0 {
            note = f"VIOLATION at {here.name}: {here.temperature} C exceeds 40 C";
            self.violations.append(note);
            print(note);
        } else {
            print(f"OK at {here.name}: {here.temperature} C");
        }

        # Check 2: visit log. Every station visit is recorded separately.
        self.station_log.append(here.name);
        print(f"LOG: visited {here.name}");

        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", temperature=180.0);
    fryer = Station(name="Fryer", temperature=175.0);
    cold_prep = Station(name="Cold Prep", temperature=4.0);

    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print("--- Summary ---");
    print(f"Stations visited: {inspector.station_log}");
    print(f"Violations found: {len(inspector.violations)}");
    for v in inspector.violations {
        print(v);
    }
}
```

