import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# OrderAuditor: Member faces no boost; Admin gets +5 on reputation.
# ---------------------------------------------------------------------------
test "OrderAuditor audits members at face value and boosts admins" {
    root ++> Member(owner="Alice", reputation=42);
    root ++> Admin(owner="Bob", reputation=80);
    root ++> Member(owner="Carol", reputation=15);
    root ++> Admin(owner="Dave", reputation=60);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
