    assert "[AUDIT] Member Alice -> reputation 42" in out, f"Alice audit missing/wrong: {out}";
    assert "[AUDIT] Member Carol -> reputation 15" in out, f"Carol audit missing/wrong: {out}";

    # Admins: reputation bumped by +5
    assert "[AUDIT] Admin Bob -> reputation 85" in out, f"Bob admin boost missing: {out}";
    assert "[AUDIT] Admin Dave -> reputation 65" in out, f"Dave admin boost missing: {out}";

    # No accidental boost on members and no missed visits
    assert "reputation 47" not in out, f"Alice should not be boosted: {out}";
    assert "reputation 20" not in out, f"Carol should not be boosted: {out}";
}

# ---------------------------------------------------------------------------
# OrderAuditor: reports each account exactly once (visit is exhaustive).
# ---------------------------------------------------------------------------
test "OrderAuditor visits every account on the lobby" {
    root ++> Member(owner="Alice", reputation=1);
    root ++> Admin(owner="Bob", reputation=1);
    root ++> Member(owner="Carol", reputation=1);
    root ++> Admin(owner="Dave", reputation=1);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Count AUDIT lines — should equal number of accounts (4)
    n_audits = out.count("[AUDIT]");
    assert n_audits == 4, f"expected 4 audits, got {n_audits}: {out}";

    # Each owner mentioned exactly once
    for owner in ["Alice", "Bob", "Carol", "Dave"] {
        assert out.count(owner) == 1, f"{owner} should appear once in audit, got {out.count(owner)} in: {out}";
    }
}

# ---------------------------------------------------------------------------
# Greeter: regardless of walker-internal abilities (greet/welcome), every
# account (Member and Admin) gets a hello.
# ---------------------------------------------------------------------------
test "Greeter greets every account regardless of subtype" {
    root ++> Member(owner="Alice", reputation=42);
    root ++> Admin(owner="Bob", reputation=80);
    root ++> Member(owner="Carol", reputation=15);
    root ++> Admin(owner="Dave", reputation=60);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Greeter(desk_name="Front Desk");
