    # Every account — Member or Admin — must receive a greeting
    assert "Front Desk: hello, Alice!" in out, f"Alice greeting missing: {out}";
    assert "Front Desk: hello, Bob!" in out, f"Bob greeting missing: {out}";
    assert "Front Desk: hello, Carol!" in out, f"Carol greeting missing: {out}";
    assert "Front Desk: hello, Dave!" in out, f"Dave greeting missing: {out}";

