    n_hellos = out.count("hello,");
    assert n_hellos == 4, f"expected 4 greetings, got {n_hellos}: {out}";
}

# ---------------------------------------------------------------------------
# Greeter: desk_name init arg is honored in every greeting line.
# ---------------------------------------------------------------------------
test "Greeter honors custom desk_name across all visits" {
    root ++> Member(owner="Alice", reputation=0);
    root ++> Admin(owner="Bob", reputation=0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Greeter(desk_name="VIP Lounge");
    }
    out = buf.getvalue();

    # Banner and every greeting should carry the custom desk name
    assert "VIP Lounge: greeting all visitors" in out, f"banner missing custom name: {out}";
    assert "VIP Lounge: hello, Alice!" in out, f"Alice greeting missing custom name: {out}";
