# ---------------------------------------------------------------------------
# Independence: auditors don't mutate reputation, and greetings don't audit.
# ---------------------------------------------------------------------------
test "Auditor and Greeter are independent passes" {
    a = Member(owner="Alice", reputation=10);
    b = Admin(owner="Bob", reputation=20);
    root ++> a;
    root ++> b;

    buf = io.StringIO();
