    assert out.count("[AUDIT] Member Alice -> reputation 10") == 1, f"Alice audit: {out}";
    assert out.count("[AUDIT] Admin Bob -> reputation 25") == 1, f"Bob admin boosted audit: {out}";

    # Greeting pass ran
    assert "Front Desk: hello, Alice!" in out, f"Alice greeting: {out}";
    assert "Front Desk: hello, Bob!" in out, f"Bob greeting: {out}";

    # Underlying reputation values are unchanged (boost is report-only)
    assert a.reputation == 10, f"Alice reputation mutated to {a.reputation}";
    assert b.reputation == 20, f"Bob reputation mutated to {b.reputation}";
