```jac
"""Wildlife park feeding rounds.

The kiosk greets every tour party regardless of who they are
(union trigger on Root). Zookeepers feed each animal its
species-appropriate meal via a per-node-type ability. School groups
just watch the animals (no per-animal feeding, no greeting output).
"""

node Lion {
    has name: str = "";
    has fed: bool = False;

    def feed() {
        self.fed = True;
        print(f"  fed meat to lion {self.name}");
    }
}

node Parrot {
    has name: str = "";
    has fed: bool = False;

    def feed() {
        self.fed = True;
        print(f"  fed seed to parrot {self.name}");
    }
}

node Animal {
    has name: str = "";
    has fed: bool = False;

    def feed() {
        self.fed = True;
        print(f"  fed standard feed to {self.name}");
    }
}

node Kiosk;

walker Zookeeper {
    has zookeeper_name: str = "";

    can start with Root entry {
        print(f"Zookeeper {self.zookeeper_name} clocks in");
        visit [-->];
    }

    # Species-specific feeding: each subtype overrides feed() with its
    # own diet, so one union ability feeds them all correctly.
    can feed_animal with Lion | Parrot | Animal entry {
        here.feed();
        visit [-->];
    }

    # The kiosk is in the chain too; just keep walking.
    can pass_kiosk with Kiosk entry {
        visit [-->];
    }
}

walker SchoolGroup {
    has group_name: str = "";

    can start with Root entry {
        print(f"School group '{self.group_name}' is watching the animals");
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        print(f"  {self.group_name} watches {here.name}");
        visit [-->];
    }

    can pass_kiosk with Kiosk entry {
        visit [-->];
    }
}

walker TourParty {
    has party_label: str = "";

    can start with Root entry {
        print(f"Tour party '{self.party_label}' enters the park");
        visit [-->];
    }

    can pass_kiosk with Kiosk entry {
        visit [-->];
    }
}

with entry {
    # Build the park: a kiosk on root, then enclosures of animals.
    root ++> Kiosk()
        ++> Animal(name="Giraffe")
        ++> Lion(name="Leo")
        ++> Parrot(name="Polly")
        ++> Animal(name="Zebra");

    zk = Zookeeper(zookeeper_name="Alex");
    root spawn zk;

    school = SchoolGroup(group_name="Maple Elementary");
    root spawn school;

    visitors = TourParty(party_label="Smith family");
    root spawn visitors;
}
