"""Tests for HealthInspector walker: union ability fires at every station."""

import io;
import from contextlib { redirect_stdout }

test "all violations flagged at every station" {
    root ++> Grill(name="Charbroiler #1", temp_c=215.0)
         ++> Fryer(name="Deep Fryer #2", temp_c=180.0)
         ++> ColdPrep(name="Salad Station", temp_c=12.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn inspector;
    }
    out = buf.getvalue();

    assert inspector.stations_checked == 3, f"expected 3 stations checked, got {inspector.stations_checked}";
    assert inspector.violations == 2, f"expected 2 violations (grill + fryer), got {inspector.violations}";

    assert "[VIOLATION] Charbroiler #1 (grill): 215.0 C exceeds 40 C" in out, f"grill violation missing: {out}";
    assert "[VIOLATION] Deep Fryer #2 (fryer): 180.0 C exceeds 40 C" in out, f"fryer violation missing: {out}";
    assert "[OK] Salad Station (cold prep): 12.0 C" in out, f"cold prep OK missing: {out}";

    assert len(inspector.log) == 3, f"expected 3 log entries, got {len(inspector.log)}";
    assert "Visited Charbroiler #1 (grill) at 215.0 C" in inspector.log;
    assert "Visited Deep Fryer #2 (fryer) at 180.0 C" in inspector.log;
    assert "Visited Salad Station (cold prep) at 12.0 C" in inspector.log;
}

test "boundary at 40 C is OK not a violation" {
    root ++> Grill(name="Charbroiler #1", temp_c=40.0)
         ++> Fryer(name="Deep Fryer #2", temp_c=40.0)
         ++> ColdPrep(name="Salad Station", temp_c=40.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn inspector;
    }
    out = buf.getvalue();

    assert inspector.stations_checked == 3, f"expected 3 stations checked, got {inspector.stations_checked}";
    assert inspector.violations == 0, f"40.0 is not >40, expected 0 violations, got {inspector.violations}";

    assert "[OK] Charbroiler #1 (grill): 40.0 C" in out, f"grill should be OK at 40 C: {out}";
    assert "[OK] Deep Fryer #2 (fryer): 40.0 C" in out, f"fryer should be OK at 40 C: {out}";
    assert "[OK] Salad Station (cold prep): 40.0 C" in out, f"cold prep should be OK at 40 C: {out}";
    assert "exceeds 40 C" not in out, f"no VIOLATION line should appear: {out}";

    assert len(inspector.log) == 3, f"expected 3 log entries, got {len(inspector.log)}";
}

test "union ability fires identically for each station type" {
    g = Grill(name="G", temp_c=10.0);
    f = Fryer(name="F", temp_c=10.0);
    c = ColdPrep(name="C", temp_c=10.0);
    root ++> g;
    root ++> f;
    root ++> c;

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn inspector;
    }
    out = buf.getvalue();

    assert inspector.stations_checked == 3, f"all three types should be counted: {inspector.stations_checked}";
    assert inspector.violations == 0, f"all under 40 should yield no violations: {inspector.violations}";

    assert "[OK] G (grill): 10.0 C" in out;
    assert "[OK] F (fryer): 10.0 C" in out;
    assert "[OK] C (cold prep): 10.0 C" in out;

    assert "Health inspector beginning kitchen line walk-through" in out, f"start banner missing: {out}";

    assert len(inspector.log) == 3, f"each station should log, got {len(inspector.log)} entries";
    assert "Visited G (grill) at 10.0 C" in inspector.log;
    assert "Visited F (fryer) at 10.0 C" in inspector.log;
    assert "Visited C (cold prep) at 10.0 C" in inspector.log;
}

test "all hot stations produce violations and log entries" {
    root ++> Grill(name="G1", temp_c=250.0)
         ++> Fryer(name="F1", temp_c=190.0)
         ++> ColdPrep(name="C1", temp_c=18.0);

    inspector = HealthInspector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn inspector;
    }
    out = buf.getvalue();

    assert inspector.stations_checked == 3, f"got {inspector.stations_checked}";
    assert inspector.violations == 2, f"expected 2 violations, got {inspector.violations}";
    assert "VIOLATION" in out;
    assert out.count("VIOLATION") == 2, f"expected 2 VIOLATION lines, got {out.count('VIOLATION')}: {out}";

    assert "Visited G1 (grill) at 250.0 C" in inspector.log;
    assert "Visited F1 (fryer) at 190.0 C" in inspector.log;
    assert "Visited C1 (cold prep) at 18.0 C" in inspector.log;

    assert inspector.log[0] == "Visited G1 (grill) at 250.0 C", f"log order wrong: {inspector.log}";
    assert inspector.log[1] == "Visited F1 (fryer) at 190.0 C", f"log order wrong: {inspector.log}";
    assert inspector.log[2] == "Visited C1 (cold prep) at 18.0 C", f"log order wrong: {inspector.log}";
}

