"""Weather sweep: walk weather stations and collect temperature readings."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        visit [-->] else {
            self.report_summary();
            disengage;
        }
    }

    can record with WeatherStation entry {
        print(f"{here.location}: {here.celsius}°C");
        self.readings.append(here.celsius);
        visit [-->] else {
            self.report_summary();
            disengage;
        }
    }

    def report_summary() {
        print(f"Readings: {self.readings}");
        if self.readings {
            min_val = min(self.readings);
            max_val = max(self.readings);
            print(f"Min: {min_val}°C, Max: {max_val}°C");
        }
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Hilltop", celsius=26.3);
    root spawn WeatherSweep();
}
