            ++> Station(name="Cold Prep", celsius=4.0)
            ++> Station(name="Pantry", celsius=22.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TempAuditor(threshold=40.0);
    }
    out = buf.getvalue();

    # All four stations must be visited and reported in order.
    assert "Grill" in out, f"grill not swept: {out}";
    assert "Fryer" in out, f"fryer not swept: {out}";
    assert "Cold Prep" in out, f"cold prep not swept: {out}";
    assert "Pantry" in out, f"pantry not swept: {out}";

    # Hot stations (Grill 185, Fryer 165) violate the 40 C threshold;
    # cold/ambient stations (4 C, 22 C) must not be flagged.
    assert "[VIOLATION] Grill at 185.0 C" in out, f"grill not flagged: {out}";
    assert "[VIOLATION] Fryer at 165.0 C" in out, f"fryer not flagged: {out}";
    assert "[ok] Cold Prep at 4.0 C" in out, f"cold prep wrongly flagged: {out}";
    assert "[ok] Pantry at 22.0 C" in out, f"pantry wrongly flagged: {out}";

    # Exactly two violations expected for the given graph.
    assert res.violations == 2, f"expected 2 violations, got {res.violations}";
}

