    assert "logged visit to Fryer" in out, f"fryer visit not printed: {out}";
    assert "logged visit to Cold Prep" in out, f"cold prep visit not printed: {out}";
    assert "logged visit to Pantry" in out, f"pantry visit not printed: {out}";
    assert "VisitLogger tracking every station pass" in out, (
        f"logger banner missing: {out}"
    );
