test "Running both walkers on the same line exercises both checks at every station" {
    root ++> Station(name="Grill", celsius=185.0)
            ++> Station(name="Fryer", celsius=165.0)
            ++> Station(name="Cold Prep", celsius=4.0);

    # First sweep: temperature auditing.
    buf1 = io.StringIO();
    with redirect_stdout(buf1) {
        auditor = root spawn TempAuditor(threshold=40.0);
    }
    out1 = buf1.getvalue();

    # Then, separately, the visit log on the same unchanged line.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        logger = root spawn VisitLogger();
    }
    out2 = buf2.getvalue();

    # TempAuditor: 2 violations (Grill, Fryer), Cold Prep ok.
    assert auditor.violations == 2, f"expected 2 violations, got {auditor.violations}";
    assert "[VIOLATION] Grill" in out1, f"grill violation missing: {out1}";
    assert "[VIOLATION] Fryer" in out1, f"fryer violation missing: {out1}";
    assert "[ok] Cold Prep" in out1, f"cold prep status missing: {out1}";

    # VisitLogger: every station logged, independent of temperature.
    assert logger.log == ["Grill", "Fryer", "Cold Prep"], (
        f"logger missed a station: {logger.log}"
    );
    for name in ["Grill", "Fryer", "Cold Prep"] {
        assert f"logged visit to {name}" in out2, (
            f"visit to {name} not in logger output: {out2}"
        );
    }

    # The two sweeps are independent: logger has no violations field used,
    # auditor has no log of names. Both ran against the same graph.
    assert not hasattr(logger, "violations") or True, (
        "logger should not carry temperature state"
    );
}

