node Animal {
    has species: str = "";
    has name: str = "";
    has fed: bool = False;

    def feed_msg(food: str) -> str {
        return f"{self.name} the {self.species} eats {food}";
    }
}

node Lion(Animal) {
    has species: str = "lion";

    override def feed_msg(food: str) -> str {
        return f"{self.name} the lion devours a rack of meat";
    }
}

node Parrot(Animal) {
    has species: str = "parrot";

    override def feed_msg(food: str) -> str {
        return f"{self.name} the parrot nibbles a bowl of seed";
    }
}

node Kiosk {
    has greeting: str = "Welcome to the Wildlife Park!";
}

edge Path {}

walker Tourist {
    can start with Root entry {
        print("Tourist begins the journey");
        visit [-->];
    }

    can arrive with Kiosk entry {
        print(here.greeting);
        visit [-->];
    }

    can observe with Lion | Parrot | Animal entry {
        if here.fed {
            print(f"  {here.name} the {here.species} rests after a meal");
        } else {
            print(f"  {here.name} the {here.species} watches the school group");
        }
        visit [-->];
    }
}

walker SchoolGroup {
    has group_name: str = "Class";

    can start with Root entry {
        print(f"School group '{self.group_name}' enters the park");
        visit [-->];
    }

    can watch with Kiosk entry {
        print(f"  {self.group_name} reads the info kiosk");
        visit [-->];
    }

    can watch_animal with Lion | Parrot | Animal entry {
        print(f"  {self.group_name} quietly observes {here.name} the {here.species}");
        visit [-->];
    }
}

walker Zookeeper {
    has keeper_name: str = "Zookeeper";

    can start with Root entry {
        print(f"Zookeeper {self.keeper_name} begins feeding rounds");
        visit [-->];
    }

    can pass_kiosk with Kiosk entry {
        print(f"  {self.keeper_name} passes the info kiosk");
        visit [-->];
    }

    can feed with Lion | Parrot | Animal entry {
        here.fed = True;
        print(f"  {self.keeper_name} offers {here.name} food -> {here.feed_msg('')}");
        visit [-->];
    }
}

with entry {
    kiosk = Kiosk(greeting="Welcome to Greenwood Wildlife Park!");
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    gnu = Animal(species="gnu", name="Gnu");
    zara = Animal(species="zebra", name="Zara");

    root ++> kiosk
        +>:Path:+> simba
        +>:Path:+> polly
        +>:Path:+> gnu
        +>:Path:+> zara;

    print("=== Tourist ===");
    root spawn Tourist();

    print("=== School Group ===");
    root spawn SchoolGroup(group_name="Year 5");

    print("=== Zookeeper ===");
    root spawn Zookeeper(keeper_name="Alex");
}
