"""Weather sweep: walk weather stations and report temperatures along the route."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_c: float = 0.0;
    has max_c: float = 0.0;
    has seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with WeatherStation entry {
        print(f"{here.location}: {here.celsius}°C");
        self.readings.append(here.celsius);
        if self.seen == 0 {
            self.min_c = here.celsius;
            self.max_c = here.celsius;
        } else {
            if here.celsius < self.min_c {
                self.min_c = here.celsius;
            }
            if here.celsius > self.max_c {
                self.max_c = here.celsius;
            }
        }
        self.seen += 1;
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> WeatherStation(location="North", celsius=18.5)
        ++> WeatherStation(location="East", celsius=22.0)
        ++> WeatherStation(location="South", celsius=15.3)
        ++> WeatherStation(location="West", celsius=27.8);

    sweep = WeatherSweep();
    root spawn sweep;

    print(f"All readings: {sweep.readings}");
    print(f"Minimum: {sweep.min_c}°C, Maximum: {sweep.max_c}°C");
}
