"""Weather sweep: walk weather stations and report temperatures."""

node WeatherStation {
    has location: str = "";
    has temperature_celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    def print_summary() {
        print(f"All readings: {self.readings}");
        if self.readings {
            print(f"Min: {min(self.readings)}°C");
            print(f"Max: {max(self.readings)}°C");
        } else {
            print("Min: n/a");
            print("Max: n/a");
        }
    }

    can start with Root entry {
        print("Beginning weather sweep");
        visit [-->] else {
            self.print_summary();
            disengage;
        }
    }

    can record with WeatherStation entry {
        print(f"{here.location}: {here.temperature_celsius}°C");
        self.readings.append(here.temperature_celsius);
        visit [-->] else {
            self.print_summary();
            disengage;
        }
    }
}

with entry {
    root ++> WeatherStation(location="Seattle", temperature_celsius=12.5)
        ++> WeatherStation(location="Phoenix", temperature_celsius=38.2)
        ++> WeatherStation(location="Denver", temperature_celsius=22.0)
        ++> WeatherStation(location="Miami", temperature_celsius=31.4);
    root spawn WeatherSweep();
}
