```jac
"""Wildlife park feeding rounds.

The info kiosk greets every tour party (a union trigger matches
Tour, Zookeeper, and SchoolGroup). Zookeepers hand out the right meal
for each animal species (meat for lions, seed for parrots, standard
feed otherwise). School groups simply observe.
"""

node Animal {
    has species: str = "";
    has name: str = "";
}

node Tour {
    has party_name: str = "";
}

node Zookeeper {
    has keeper_name: str = "";
}

node SchoolGroup {
    has school_name: str = "";
    has students: int = 0;
}

walker Greeter {
    can start with Root entry {
        print("Info kiosk open.");
        visit [-->];
    }

    can greet with Tour | Zookeeper | SchoolGroup entry {
        if isinstance(here, Tour) {
            print(f"Welcome, tour party '{here.party_name}'!");
        } elif isinstance(here, Zookeeper) {
            print(f"Welcome, zookeeper {here.keeper_name} — feeding rounds begin.");
        } else {
            print(f"Welcome, {here.school_name} school group ({here.students} students) — enjoy the show!");
        }
        visit [-->];
    }

    can feed with Animal entry {
        meal = "standard feed";
        if here.species == "lion" {
            meal = "meat";
        } elif here.species == "parrot" {
            meal = "seed";
        }
        print(f"  feeding {here.name} the {here.species}: {meal}");
        visit [-->];
    }
}

with entry {
    lion = Animal(species="lion", name="Simba");
    parrot = Animal(species="parrot", name="Kiwi");
    giraffe = Animal(species="giraffe", name="Tall");
    root ++> Tour(party_name="Smith Family")
        ++> Zookeeper(keeper_name="Alex")
        ++> SchoolGroup(school_name="Lincoln Elementary", students=22)
        ++> lion
        ++> parrot
        ++> giraffe;
    root spawn Greeter();
}
```

