"""Health-inspect a restaurant kitchen line: check station temperatures and log visits."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;
    has violation_flagged: bool = False;
    has visit_count: int = 0;
}

walker Inspector {
    can start with Root entry {
        visit [-->];
    }

    can check_station with Station entry {
        if here.temperature > 40.0 {
            here.violation_flagged = True;
            print(f"VIOLATION: {here.name} at {here.temperature}C exceeds 40C threshold");
        } else {
            print(f"OK: {here.name} at {here.temperature}C is safe");
        }
        here.visit_count += 1;
        print(f"LOG: Inspector visited {here.name} (total visits: {here.visit_count})");
    }
}

with entry {
    grill = Station(name="Grill", temperature=85.0);
    fryer = Station(name="Fryer", temperature=180.0);
    cold_prep = Station(name="Cold Prep", temperature=4.0);

    root ++> grill;
    root ++> fryer;
    root ++> cold_prep;

    root spawn Inspector();
}
