```jac
"""Wildlife park feeding rounds.

Kiosks greet any tour party; zookeepers deliver species-appropriate meals
(meat for lions, seed for parrots, standard feed otherwise); school groups
merely observe the animals. A single union ability on the exhibit handles
both kinds of visitors, while the kiosk greets everyone indiscriminately.
"""

node Exhibit {
    has species: str = "";

    # Union trigger: fires for a Zookeeper OR a SchoolGroup, not for a
    # plain Visitor, so the exhibit stays silent for a casual guest.
    can host with Zookeeper | SchoolGroup entry {
        visitor.visit_log.append(f"observed {self.species}");
        if visitor.__class__ == Zookeeper {
            meal = "meat" if self.species == "lion"
                else "seed" if self.species == "parrot"
                else "standard feed";
            print(f"Zookeeper feeds {self.species}: {meal}");
        } else {
            print(f"SchoolGroup watches {self.species}");
        }
    }
}

walker Visitor {
    has visit_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can wander with Exhibit entry {
        print(f"Visitor passes by the {here.species} exhibit");
        visit [-->];
    }
}

walker Zookeeper {
    has visit_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can make_rounds with Exhibit entry {
        visit [-->];
    }
}

walker SchoolGroup {
    has visit_log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can tour with Exhibit entry {
        visit [-->];
    }
}

# The kiosk greets every tour party regardless of type: a Visitor,
# Zookeeper, or SchoolGroup all receive a warm welcome.
node Kiosk {
    has park_name: str = "";

    can greet with Visitor | Zookeeper | SchoolGroup entry {
        kind = "Visitor" if visitor.__class__ == Visitor
            else "Zookeeper" if visitor.__class__ == Zookeeper
            else "SchoolGroup";
        print(f"Kiosk welcomes the {kind} to {self.park_name} Park");
    }
}

with entry {
    lions = Exhibit(species="lion");
    parrots = Exhibit(species="parrot");
    antelope = Exhibit(species="antelope");

    kiosk = Kiosk(park_name="Sunrise");
    root ++> kiosk ++> lions ++> parrots ++> antelope;

    guest = Visitor();
    zookeeper = Zookeeper();
    pupils = SchoolGroup();

    root spawn guest;
    root spawn zookeeper;
    root spawn pupils;

    print(f"Visitor log: {guest.visit_log}");
    print(f"Zookeeper log: {zookeeper.visit_log}");
    print(f"SchoolGroup log: {pupils.visit_log}");
}
