"""Restaurant kitchen health inspection.

Each station is a node holding its current temperature. A single Inspector
walker visits every station, logs the visit, and flags any station whose
temperature exceeds 40 C as a violation. Both checks run at every station.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
}

walker Inspector {
    has violations: int = 0;
