    has species: str = "lion";
}

node Parrot(Animal) {
    has name: str = "";
    has species: str = "parrot";
}

node Zebra(Animal) {
    has name: str = "";
    has species: str = "zebra";
}

# Tour parties: a kiosk greets them, a keeper feeds them, a school just watches.
node TourParty {
    has label: str = "";
}

walker Tourist {
    can start with Root entry {
        visit [-->];
    }

    can arrive with TourParty entry {
        print(f"Welcome to the park, {here.label}!");
        visit [-->];
    }
}

walker Zookeeper {
    has meals: dict[str, str] = {"lion": "meat", "parrot": "seed", "zebra": "hay"};

    can start with Root entry {
        visit [-->];
    }

    can feed with Lion | Parrot | Zebra entry {
        meal = self.meals.get(here.species, "standard feed");
        print(f"Feeding {here.name} the {here.species}: {meal}");
        visit [-->];
    }
}

walker SchoolGroup {
    has label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can watch with Lion | Parrot | Zebra entry {
        print(f"{self.label} watches {here.name} the {here.species}");
        visit [-->];
    }
}

with entry {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    zed = Zebra(name="Zed");
    simba ++> polly ++> zed;

    party = TourParty(label="Smith family");
    root ++> party;

    root spawn Tourist();
    root spawn Zookeeper();
    sg = SchoolGroup(label="Maple Elementary");
    sg spawn simba;
}
