import io;
import from contextlib { redirect_stdout }

# --- Test 1: Tourist greets the tour party ---
test "tourist greets tour party" {
    root ++> TourParty(label="Smith family");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Tourist();
    }
    out = buf.getvalue();

    assert "Welcome to the park, Smith family!" in out, f"missing greeting: {out!r}";
}

# --- Test 2: Zookeeper feeds each species its appropriate meal ---
test "zookeeper feeds species-specific meals" {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    zed = Zebra(name="Zed");
    simba ++> polly ++> zed;
    root ++> simba;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Zookeeper();
    }
    out = buf.getvalue();

    assert "Feeding Simba the lion: meat" in out, f"missing lion feeding: {out!r}";
    assert "Feeding Polly the parrot: seed" in out, f"missing parrot feeding: {out!r}";
    assert "Feeding Zed the zebra: hay" in out, f"missing zebra feeding: {out!r}";
}

# --- Test 3: Zookeeper uses standard feed for unknown species ---
test "zookeeper uses standard feed for unknown species" {
    # Build a zebra but override its species to something not in the meals dict
    mystery = Zebra(name="Mystery");
    # Mutate species after construction so the dict lookup falls back
    mystery.species = "dragon";
    root ++> mystery;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Zookeeper();
    }
    out = buf.getvalue();

    assert "Feeding Mystery the dragon: standard feed" in out, f"missing fallback feeding: {out!r}";
}

# --- Test 4: School group watches animals ---
test "school group watches animals" {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    simba ++> polly;
    root ++> simba;

    sg = SchoolGroup(label="Maple Elementary");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sg spawn simba;
