    assert "Maple Elementary watches Simba the lion" in out, f"missing lion watch: {out!r}";
    assert "Maple Elementary watches Polly the parrot" in out, f"missing parrot watch: {out!r}";
}

# --- Test 5: Graph wiring matches the demo's structure ---
test "graph wiring connects tour party and animal chain" {
    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    zed = Zebra(name="Zed");
    simba ++> polly ++> zed;
    party = TourParty(label="Smith family");
    root ++> party;
    root ++> simba;

    children = [root -->];
    assert len(children) == 2, f"expected 2 root children, got {len(children)}";

    # Animal chain order: simba -> polly -> zed
    assert polly in [simba -->], "polly should be linked from simba";
    assert zed in [polly -->], "zed should be linked from polly";

