"""Weather sweep: walk weather stations, report each reading, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        visit [--> ] else {
            print("Readings: []");
            print("Min: n/a, Max: n/a");
            disengage;
        }
    }

    can record with WeatherStation entry {
        print(f"{here.location}: {here.celsius} C");
        self.readings.append(here.celsius);
        visit [--> ] else {
            lo = min(self.readings);
            hi = max(self.readings);
            print(f"Readings: {self.readings}");
            print(f"Min: {lo} C, Max: {hi} C");
            disengage;
        }
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Uplands", celsius=26.3);
    root spawn WeatherSweep();
}
