"""Tests for the weather sweep walker."""

import io;
import from contextlib { redirect_stdout }

def make_chain() {
    rt = root;
    rt ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Uplands", celsius=26.3);
    return rt;
}

test "sweep prints each station reading as it visits" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = make_chain() spawn WeatherSweep();
    }
    out = buf.getvalue();
    assert "Downtown: 22.5 C" in out, f"missing Downtown reading: {out}";
    assert "Harbor: 18.0 C" in out, f"missing Harbor reading: {out}";
    assert "Uplands: 26.3 C" in out, f"missing Uplands reading: {out}";
    # Readings should appear before the summary block.
    d_idx = out.index("Downtown: 22.5 C");
    h_idx = out.index("Harbor: 18.0 C");
    u_idx = out.index("Uplands: 26.3 C");
    summary_idx = out.index("Readings: [");
    assert d_idx < summary_idx and h_idx < summary_idx and u_idx < summary_idx, (
        f"per-station readings must print before summary, got: {out}"
    );
}

test "sweep prints full readings list and correct min/max" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = make_chain() spawn WeatherSweep();
    }
    out = buf.getvalue();
    assert "Readings: [22.5, 18.0, 26.3]" in out, f"bad readings line: {out}";
    assert "Min: 18.0 C" in out, f"bad min line: {out}";
    assert "Max: 26.3 C" in out, f"bad max line: {out}";
}

test "sweep records each visited station in walker state" {
    res = make_chain() spawn WeatherSweep();
    assert len(res.readings) == 3, f"expected 3 readings, got {res.readings}";
    assert res.readings[0] == 22.5, f"first reading wrong: {res.readings}";
    assert res.readings[1] == 18.0, f"second reading wrong: {res.readings}";
    assert res.readings[2] == 26.3, f"third reading wrong: {res.readings}";
    # Sanity: min/max on the recorded list match the problem's spec.
    assert min(res.readings) == 18.0, f"min mismatch: {res.readings}";
    assert max(res.readings) == 26.3, f"max mismatch: {res.readings}";
}

test "sweep on empty graph fails closed with n/a summary" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        # No children attached to root.
        res = root spawn WeatherSweep();
    }
    out = buf.getvalue();
    assert "Readings: []" in out, f"empty readings line missing: {out}";
    assert "Min: n/a" in out, f"missing min n/a: {out}";
    assert "Max: n/a" in out, f"missing max n/a: {out}";
    assert len(res.readings) == 0, f"walker readings should be empty, got {res.readings}";
}

test "sweep follows the chain order not arbitrary order" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = make_chain() spawn WeatherSweep();
    }
    out = buf.getvalue();
    # The chain is Downtown -> Harbor -> Uplands; per-station prints must follow that order.
    d = out.index("Downtown: 22.5 C");
    h = out.index("Harbor: 18.0 C");
    u = out.index("Uplands: 26.3 C");
    assert d < h < u, f"visits not in chain order: {out}";
}

