```jac
"""Data center clearance check.

Each Room declares the clearance level required to enter. A Technician
walking the corridor is granted or denied per room based on their own
level. A denial ends the walkthrough immediately (disengage) so they
never reach deeper rooms. Report how many rooms each technician reached.
"""

node Room {
    has name: str = "";
    has required_level: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_entered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk with Room entry {
        if here.required_level <= self.clearance {
            self.rooms_entered += 1;
            print(f"{self.name} GRANTED entry to {here.name} "
                  f"(needs {here.required_level})");
            visit [-->];
        } else {
            print(f"{self.name} DENIED entry to {here.name} "
                  f"(needs {here.required_level}, has {self.clearance})");
            disengage;
        }
    }
}

with entry {
    # Corridor: server rooms chained in traversal order. A denial on
    # any room must cut off every deeper room.
    root ++> Room(name="Lobby", required_level=0)
        ++> Room(name="Server A", required_level=1)
        ++> Room(name="Server B", required_level=2)
        ++> Room(name="Vault", required_level=3);

    junior = Technician(name="Junior", clearance=1);
    root spawn junior;
    print(f"-> {junior.name} reached {junior.rooms_entered} rooms");

    senior = Technician(name="Senior", clearance=3);
    root spawn senior;
    print(f"-> {senior.name} reached {senior.rooms_entered} rooms");

    contractor = Technician(name="Contractor", clearance=1);
    root spawn contractor;
    print(f"-> {contractor.name} reached {contractor.rooms_entered} rooms");
}
```

