"""Wildlife park feeding rounds: kiosk greets everyone, zookeepers feed
species-appropriate meals, school groups just observe."""

node TourParty {
    has name: str = "";
}

node Visitor {
    has badge: str = "";
}

node SchoolGroup {
    has name: str = "";
}

node Zookeeper {
    has badge: str = "";
}

node Lion {
    has name: str = "";
}

node Parrot {
    has name: str = "";
}

node Animal {
    has name: str = "";
}

node Kiosk {
    has location: str = "";
}

edge LeadsTo {
    has label: str = "";
}

walker Greeter {
    can start with Root entry {
        visit [-->];
    }

    can greet with TourParty | Zookeeper | SchoolGroup | Visitor entry {
        kind = "visitor" if isinstance(here, Visitor) else "school group"
            if isinstance(here, SchoolGroup) else "zookeeper"
            if isinstance(here, Zookeeper) else "tour party";
        print(f"Kiosk: welcome, {kind}!");
        visit [-->];
    }
}

walker Feeder {
    has feeder_badge: str = "";

    can start with Root entry {
        print(f"Feeder {self.feeder_badge} beginning rounds");
        visit [-->];
    }

    can arrive with Kiosk entry {
        print(f"  passing through {here.location}");
        visit [-->];
    }

    can feed with Lion | Parrot | Animal entry {
        meal = "meat" if isinstance(here, Lion) else "seed" if isinstance(here, Parrot) else "standard feed";
        label = "lion" if isinstance(here, Lion) else "parrot" if isinstance(here, Parrot) else "animal";
        print(f"  feeding {label} {here.name}: {meal}");
        visit [-->];
    }
}

walker SchoolObserver {
    has group_name: str = "";

    can start with Root entry {
        print(f"School group {self.group_name} starting observation tour");
        visit [-->];
    }

    can arrive with Kiosk entry {
        print(f"  at {here.location}, reading the map");
        visit [-->];
    }

    can watch with Lion | Parrot | Animal entry {
        kind = "lion" if isinstance(here, Lion) else "parrot" if isinstance(here, Parrot) else "animal";
        print(f"  watching the {kind} ({here.name})");
        visit [-->];
    }
}

with entry {
    kiosk_a = Kiosk(location="Main Gate");
    kiosk_b = Kiosk(location="Aviary");

    simba = Lion(name="Simba");
    polly = Parrot(name="Polly");
    hazel = Animal(name="Hazel");

    root +>:LeadsTo(label="enter"):+> kiosk_a;
    kiosk_a +>:LeadsTo(label="lion den"):+> simba;
    kiosk_a +>:LeadsTo(label="aviary"):+> kiosk_b;
    kiosk_b +>:LeadsTo(label="perch"):+> polly;
    kiosk_a +>:LeadsTo(label="yard"):+> hazel;

    print("=== Greeter round ===");
    root spawn Greeter();

    print("=== Feeder round ===");
    Feeder(feeder_badge="ZK-7") spawn root;

    print("=== School observer tour ===");
    SchoolObserver(group_name="Ms. Maple's class") spawn root;
}
