        ++> WeatherStation(location="D", celsius=11.5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweep = WeatherSweep();
        root spawn sweep;

        # Mirror the program's own summary computation so we can assert
        # both the printed line AND the resulting min/max values.
        min_c = sweep.readings[0];
        max_c = sweep.readings[0];
        for t in sweep.readings {
            if t < min_c { min_c = t; }
            if t > max_c { max_c = t; }
        }

        print(f"Readings: {sweep.readings}");
        print(f"Min: {min_c}°C, Max: {max_c}°C");
    }
    out = buf.getvalue();

    # Full readings list must be printed.
    assert "[4.2, 18.7, 32.1, 11.5]" in out, f"missing readings line: {out}";

    # Min must be the coldest station (North Ridge/A), Max the hottest (Desert Plain/C).
    assert "Min: 4.2°C" in out, f"missing/wrong Min line: {out}";
    assert "Max: 32.1°C" in out, f"missing/wrong Max line: {out}";
