```jac
"""Data center clearance enforcement.

Each ServerRoom declares the clearance level it requires. A Technician
walker carries a clearance badge and tries to enter every room along
the corridor. If the room's required level is higher than the
technician's granted level, the technician is denied, the walk ends
immediately (deeper rooms are not visited), and the walk is reported
short. Otherwise the technician enters, the room is counted, and the
walk continues down the corridor.
"""

node ServerRoom {
    has name: str = "";
    has required_clearance: int = 0;
}

walker Technician {
    has name: str = "anon";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can walk_corridor with ServerRoom entry {
        if here.required_clearance > self.clearance {
            self.denied = True;
            print(f"[DENY] {self.name} blocked at {here.name} (needs {here.required_clearance}, has {self.clearance})");
            disengage;
        }
        self.rooms_reached += 1;
        print(f"[OK]   {self.name} entered {here.name}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    root ++> ServerRoom(name="Lobby", required_clearance=0)
        ++> ServerRoom(name="Cold Aisle", required_clearance=1)
        ++> ServerRoom(name="Power Room", required_clearance=3)
        ++> ServerRoom(name="Core", required_clearance=5);

    alice = Technician(name="Alice", clearance=2);
    root spawn alice;
    print(f"--- {alice.name} reached {alice.rooms_reached} room(s); denied={alice.denied} ---\n");

    bob = Technician(name="Bob", clearance=4);
    root spawn bob;
    print(f"--- {bob.name} reached {bob.rooms_reached} room(s); denied={bob.denied} ---\n");

    cara = Technician(name="Cara", clearance=5);
    root spawn cara;
    print(f"--- {cara.name} reached {cara.rooms_reached} room(s); denied={cara.denied} ---");
}
```

