"""Weather sweep: visit each weather station, report live readings, and summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweeper {
    has readings: list[float] = [];
    has min_c: float = 0.0;
    has max_c: float = 0.0;
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with WeatherStation entry {
        print(f"{here.location}: {here.celsius} C");
        self.readings.append(here.celsius);
        if self.count == 0 {
            self.min_c = here.celsius;
            self.max_c = here.celsius;
        } else {
            if here.celsius < self.min_c {
                self.min_c = here.celsius;
            }
            if here.celsius > self.max_c {
                self.max_c = here.celsius;
            }
        }
        self.count += 1;
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> WeatherStation(location="Boston", celsius=12.5)
        ++> WeatherStation(location="Miami", celsius=28.3)
        ++> WeatherStation(location="Denver", celsius=8.1);
    sweeper = WeatherSweeper();
    root spawn sweeper;
    print(f"All readings: {sweeper.readings}");
    print(f"Min: {sweeper.min_c} C, Max: {sweeper.max_c} C");
}
