```jac
"""Restaurant kitchen line health-inspection walker.

Visits each station (Grill, Fryer, ColdPrep) on the line and runs TWO
inspections at every stop:

  1. TemperatureCheck  — flags the station as a violation if its
     temperature is above 40 C.
  2. VisitLog          — records that the station was visited (eagerly).

Two separate walkers traverse the same line so the two responsibilities
remain decoupled and observable.
"""

node Station {
    has name: str = "";
    has temperature_c: float = 0.0;
}

node Grill(Station) {
    has temperature_c: float = 200.0;
}

node Fryer(Station) {
    has temperature_c: float = 180.0;
}

node ColdPrep(Station) {
    has temperature_c: float = 4.0;
}

walker TemperatureCheck {
    has violations: int = 0;
    can start with Root entry {
        visit [-->];
    }
    can audit with Grill | Fryer | ColdPrep entry {
        if here.temperature_c > 40.0 {
            self.violations += 1;
            print(f"[VIOLATION] {here.name} station at {here.temperature_c} C");
        } else {
            print(f"[OK] {here.name} station at {here.temperature_c} C");
        }
        visit [-->];
    }
}

walker VisitLog {
    has visits: int = 0;
    can start with Root entry {
        visit [-->];
    }
    can log with Grill | Fryer | ColdPrep entry {
        self.visits += 1;
        print(f"[VISIT] Logged visit #{self.visits} to {here.name} station");
        visit [-->];
    }
}

with entry {
    grill = Grill(name="Grill");
    fryer = Fryer(name="Fryer");
    cold = ColdPrep(name="ColdPrep");
    root ++> grill ++> fryer ++> cold;

    temp_walker = TemperatureCheck();
    root spawn temp_walker;
    print(f"--- Total violations flagged: {temp_walker.violations} ---");

    log_walker = VisitLog();
    root spawn log_walker;
    print(f"--- Total station visits logged: {log_walker.visits} ---");
}
```

