        root spawn walker_instance;
    }
    out = buf.getvalue();

    assert "[VIOLATION] HotGrill station at 200.0 C" in out, f"grill violation missing: {out}";
    assert "[VIOLATION] HotFryer station at 180.0 C" in out, f"fryer violation missing: {out}";
    assert "[OK] Chilly station at 4.0 C" in out, f"cold prep OK missing: {out}";
    assert "[VIOLATION] WarmGrill station at 200.0 C" in out, f"second grill violation missing: {out}";
