    # Run TemperatureCheck
    buf_temp = io.StringIO();
    with redirect_stdout(buf_temp) {
        temp_walker = TemperatureCheck();
        root spawn temp_walker;
    }
    temp_out = buf_temp.getvalue();

    # Run VisitLog on the SAME graph
    buf_log = io.StringIO();
    with redirect_stdout(buf_log) {
        log_walker = VisitLog();
        root spawn log_walker;
    }
    log_out = buf_log.getvalue();

    # Every station name appears in BOTH outputs
    assert "TheGrill" in temp_out and "TheGrill" in log_out, f"grill only in one: temp={temp_out} log={log_out}";
    assert "TheFryer" in temp_out and "TheFryer" in log_out, f"fryer only in one: temp={temp_out} log={log_out}";
    assert "TheCold" in temp_out and "TheCold" in log_out, f"cold prep only in one: temp={temp_out} log={log_out}";

    # Counts: 2 violations (grill 200, fryer 180), 3 visits
    assert temp_walker.violations == 2, f"expected 2 violations, got {temp_walker.violations}";
    assert log_walker.visits == 3, f"expected 3 visits, got {log_walker.visits}";

    # Visit log is independent of temperature check (log does not depend on temp)
    assert "[VISIT] Logged visit #1" in log_out, f"visit log missing: {log_out}";
}

