    root ++> Grill(name="G1") ++> Grill(name="G2") ++> ColdPrep(name="CP1");

    temp_buf = io.StringIO();
    with redirect_stdout(temp_buf) {
        temp_walker = TemperatureCheck();
        root spawn temp_walker;
    }

    log_buf = io.StringIO();
    with redirect_stdout(log_buf) {
        log_walker = VisitLog();
        root spawn log_walker;
    }

    # Decoupled: temperature walker counts violations only, log walker counts visits only
    assert temp_walker.violations == 2, f"expected 2 violations, got {temp_walker.violations}";
    assert log_walker.visits == 3, f"expected 3 visits, got {log_walker.visits}";
}

