```jac
"""Restaurant kitchen line health inspection.

A patrol walker traverses the kitchen stations (grill, fryer, cold prep).
At each station two checks run on every visit:
  1. Temperature check -- flag stations above 40 C as a violation.
  2. Visit log -- record that the patrol reached this station.

Both checks must fire at every station, so we use union triggers so
that the same patrol visits every node archetype.
"""

node Station {
    has station_name: str = "";
    has temperature: float = 0.0;
    has violations: list[str] = [];
}

node GrillStation(Station) {
    has station_name: str = "Grill";
}

node FryerStation(Station) {
    has station_name: str = "Fryer";
}

node ColdPrepStation(Station) {
    has station_name: str = "Cold Prep";
}

edge NextStation {}

walker Inspector {
    has station_count: int = 0;
    has violation_count: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("Health inspection: beginning kitchen line patrol");
        visit [-->];
    }

    can approach with GrillStation | FryerStation | ColdPrepStation entry {
        # Check 1: temperature violation (above 40 C is unsafe).
        flagged = here.temperature > 40.0;
        if flagged {
            msg = f"VIOLATION at {here.station_name}: {here.temperature} C exceeds 40 C";
            here.violations.append(msg);
            self.violation_count += 1;
            print(msg);
        }

        # Check 2: visit log (every station gets logged).
        entry = f"Visited {here.station_name} ({here.temperature} C)";
        self.log.append(entry);
        self.station_count += 1;
        print(entry);

        visit [-->];
    }
}

with entry {
    grill = GrillStation(temperature=85.0);
    fryer = FryerStation(temperature=180.0);
    cold = ColdPrepStation(temperature=4.0);
    root ++> grill ++> fryer ++> cold;

    inspector = Inspector();
    root spawn inspector;

    print(f"\nInspection summary: visited {inspector.station_count} stations, "
          f"found {inspector.violation_count} violations");
    for entry in inspector.log {
        print(f"  log: {entry}");
    }
}
```

