import io;
import from contextlib { redirect_stdout }

test "flags violation above 40 and logs every station" {
    buf = io.StringIO();
    grill = GrillStation(temperature=85.0);
    fryer = FryerStation(temperature=180.0);
    cold = ColdPrepStation(temperature=4.0);
    root ++> grill ++> fryer ++> cold;

    inspector = Inspector();
    with redirect_stdout(buf) {
        root spawn inspector;
    }

    assert inspector.station_count == 3, f"expected 3 visits, got {inspector.station_count}";
    assert inspector.violation_count == 2, f"expected 2 violations, got {inspector.violation_count}";

    # Grill and fryer were over 40 C -> must carry violation messages.
    assert len(grill.violations) == 1, f"grill violations: {grill.violations}";
    assert "VIOLATION at Grill" in grill.violations[0], f"bad grill msg: {grill.violations[0]}";
    assert len(fryer.violations) == 1, f"fryer violations: {fryer.violations}";
    assert "VIOLATION at Fryer" in fryer.violations[0], f"bad fryer msg: {fryer.violations[0]}";

    # Cold prep at 4 C is safe -> no violation recorded on the node.
    assert len(cold.violations) == 0, f"cold prep should have no violations, got {cold.violations}";

    # Every station must appear in the walker's log.
    assert len(inspector.log) == 3, f"expected 3 log entries, got {len(inspector.log)}";
    assert "Grill" in inspector.log[0] and "85.0" in inspector.log[0], f"log[0]: {inspector.log[0]}";
    assert "Fryer" in inspector.log[1] and "180.0" in inspector.log[1], f"log[1]: {inspector.log[1]}";
    assert "Cold Prep" in inspector.log[2] and "4.0" in inspector.log[2], f"log[2]: {inspector.log[2]}";

    out = buf.getvalue();
    assert "VIOLATION at Grill" in out, f"missing grill violation print: {out}";
    assert "VIOLATION at Fryer" in out, f"missing fryer violation print: {out}";
    assert "Visited Grill" in out, f"missing grill visit print: {out}";
    assert "Visited Fryer" in out, f"missing fryer visit print: {out}";
    assert "Visited Cold Prep" in out, f"missing cold prep visit print: {out}";
}

