"""Weather sweep: visit each station, report temperatures live, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[str] = [];
    has min_temp: float = 0.0;
    has max_temp: float = 0.0;
    has seen: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can report with WeatherStation entry {
        loc = here.location;
        temp = here.celsius;
        line = f"{loc}: {temp} C";
        print(line);
        self.readings.append(line);
        if not self.seen {
            self.min_temp = temp;
            self.max_temp = temp;
            self.seen = True;
        } else {
            new_min = temp if temp < self.min_temp else self.min_temp;
            self.min_temp = new_min;
            new_max = temp if temp > self.max_temp else self.max_temp;
            self.max_temp = new_max;
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> WeatherStation(location="North", celsius=12.5)
        ++> WeatherStation(location="Downtown", celsius=22.0)
        ++> WeatherStation(location="Harbor", celsius=8.3);
    sweep = WeatherSweep();
    root spawn sweep;
    print("--- All readings ---");
    for line in sweep.readings {
        print(line);
    }
    print(f"Min: {sweep.min_temp} C, Max: {sweep.max_temp} C");
}
