        ++> WeatherStation(location="Phoenix", celsius=38.2)
        ++> WeatherStation(location="Chicago", celsius=5.0)
        ++> WeatherStation(location="Miami", celsius=29.8);

    sweep = WeatherSweep();
    root spawn sweep;

    min_reading = sweep.readings[0];
    max_reading = sweep.readings[0];
    for temp in sweep.readings {
        if temp < min_reading {
            min_reading = temp;
        }
        if temp > max_reading {
            max_reading = temp;
        }
    }

    print(f"All readings: {sweep.readings}");
    print(f"Min: {min_reading}°C, Max: {max_reading}°C");
}
