```jac
"""Data center clearance enforcement.

Each server room posts the clearance level required to enter. A technician
walking the corridor is granted or denied at each room based on their
personal clearance. A denied technician ends their walkthrough immediately
and never visits deeper rooms. The walker reports how many rooms each
technician successfully reached.
"""

node Room {
    has name: str = "";
    has required_level: int = 0;
}

walker Technician {
    has name: str = "Tech";
    has clearance: int = 0;
    has rooms_reached: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can attempt_entry with Room entry {
        if here.required_level <= self.clearance {
            self.rooms_reached += 1;
            print(f"{self.name} GRANTED entry to {here.name} "
                  f"(needs {here.required_level}, has {self.clearance})");
            visit [-->];
        } else {
            print(f"{self.name} DENIED at {here.name} "
                  f"(needs {here.required_level}, has {self.clearance}) "
                  f"- walkthrough over after {self.rooms_reached} room(s)");
            disengage;
        }
    }
}

with entry {
    root ++> Room(name="Lobby", required_level=0)
        ++> Room(name="Storage", required_level=1)
        ++> Room(name="Server A", required_level=2)
        ++> Room(name="Server B", required_level=3)
        ++> Room(name="Vault", required_level=5);

    junior = Technician(name="Junior", clearance=2);
    root spawn junior;

    senior = Technician(name="Senior", clearance=4);
    root spawn senior;

    intern = Technician(name="Intern", clearance=0);
    root spawn intern;

    print(f"Junior reached {junior.rooms_reached} room(s)");
    print(f"Senior reached {senior.rooms_reached} room(s)");
    print(f"Intern reached {intern.rooms_reached} room(s)");
}
```

