"""Weather sweep: visit each station, report temperatures live, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_temp: float = 0.0;
    has max_temp: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can measure with WeatherStation entry {
        print(f"{here.location}: {here.celsius} C");
        self.readings.append(here.celsius);
        if len(self.readings) == 1 {
            self.min_temp = here.celsius;
            self.max_temp = here.celsius;
        } else {
            if here.celsius < self.min_temp {
                self.min_temp = here.celsius;
            }
            if here.celsius > self.max_temp {
                self.max_temp = here.celsius;
            }
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> WeatherStation(location="Austin", celsius=32.5)
        ++> WeatherStation(location="Denver", celsius=18.2)
        ++> WeatherStation(location="Seattle", celsius=12.1);

    sweep = WeatherSweep();
    root spawn sweep;
    print(f"All readings: {sweep.readings}");
    print(f"Min: {sweep.min_temp} C, Max: {sweep.max_temp} C");
}
