"""Weather sweep: walk weather stations, report each reading, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];
    has min_celsius: float = 0.0;
    has max_celsius: float = 0.0;
    has seen_any: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can sweep with WeatherStation entry {
        print(f"{here.location}: {here.celsius}°C");
        self.readings.append(here.celsius);
        if not self.seen_any {
            self.min_celsius = here.celsius;
            self.max_celsius = here.celsius;
            self.seen_any = True;
        } else {
            if here.celsius < self.min_celsius {
                self.min_celsius = here.celsius;
            }
            if here.celsius > self.max_celsius {
                self.max_celsius = here.celsius;
            }
        }
        visit [-->];
    }
}

with entry {
    root ++> WeatherStation(location="North Ridge", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Desert Mesa", celsius=31.2)
        ++> WeatherStation(location="Alpine Pass", celsius=4.8);
    sweeper = WeatherSweep();
    root spawn sweeper;
    print(f"All readings: {sweeper.readings}");
    print(f"Min: {sweeper.min_celsius}°C, Max: {sweeper.max_celsius}°C");
}
