"""Data center clearance walk: technicians traverse rooms, denied ones stop immediately."""

node Room {
    has room_name: str = "";
    has required_level: int = 0;
}

node Technician {
    has tech_name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied: bool = False;
}

edge Corridor {}

walker Walkthrough {
    has tech_name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;
    has denied: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can approach with Room entry {
        if here.required_level <= self.clearance {
            self.rooms_reached += 1;
            print(f"{self.tech_name} entered {here.room_name} (level {here.required_level} OK)");
            visit [-->];
        } else {
            self.denied = True;
            print(f"{self.tech_name} DENIED at {here.room_name} (needs {here.required_level}, has {self.clearance}) — walkthrough ends");
            disengage;
        }
    }
}

with entry {
    server_room = Room(room_name="Server Room A", required_level=1);
    vault = Room(room_name="Crypto Vault", required_level=5);
    datacenter_core = Room(room_name="Datacenter Core", required_level=3);
    network_ops = Room(room_name="Network Ops", required_level=2);

    root ++> server_room
        +>:Corridor:+> vault
        +>:Corridor:+> datacenter_core
        +>:Corridor:+> network_ops;

    junior = Walkthrough(tech_name="Junior", clearance=2);
    senior = Walkthrough(tech_name="Senior", clearance=5);
    contractor = Walkthrough(tech_name="Contractor", clearance=1);

    root spawn junior;
    root spawn senior;
    root spawn contractor;

    print(f"{junior.tech_name} reached {junior.rooms_reached} room(s), denied={junior.denied}");
    print(f"{senior.tech_name} reached {senior.rooms_reached} room(s), denied={senior.denied}");
    print(f"{contractor.tech_name} reached {contractor.rooms_reached} room(s), denied={contractor.denied}");
}
```

