"""Data center clearance enforcement: technicians walk rooms, are admitted or denied by clearance."""

node ServerRoom {
    has name: str = "";
    has required_clearance: int = 0;
}

walker Technician {
    has name: str = "";
    has clearance: int = 0;
    has rooms_reached: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can approach with ServerRoom entry {
        if here.required_clearance <= self.clearance {
            self.rooms_reached += 1;
            print(f"{self.name} ADMITTED into {here.name} (needs {here.required_clearance}, has {self.clearance})");
            visit [-->];
        } else {
            print(f"{self.name} DENIED at {here.name} (needs {here.required_clearance}, has {self.clearance}) — walkthrough ends");
            disengage;
        }
    }
}

with entry {
    root ++> ServerRoom(name="Lobby", required_clearance=1)
        ++> ServerRoom(name="Server Bay A", required_clearance=2)
        ++> ServerRoom(name="Server Bay B", required_clearance=3)
        ++> ServerRoom(name="Crypto Vault", required_clearance=5);

    junior = Technician(name="Jamie", clearance=2);
    root spawn junior;
    print(f"--> {junior.name} reached {junior.rooms_reached} rooms\n");

    senior = Technician(name="Morgan", clearance=4);
    root spawn senior;
    print(f"--> {senior.name} reached {senior.rooms_reached} rooms\n");
}
```

