"""Social graph: people and pets connected as friends; recommend only adult humans."""

node Profile {
    has name: str = "";
    has age: int = 0;
    has species: str = "human";
}

edge Friend {}

walker Recommender {
    has raw_seen: int = 0;
    has kept: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Profile entry {
        if here.species != "human" {
            return;
        }
        if here.age < 18 {
            return;
        }
        next_targets = [];
        for n in [-->] {
            self.raw_seen += 1;
            if (n.species == "human") and (n.age >= 18) {
                self.kept += 1;
                next_targets.append(n);
            }
        }
        print(f"{here.name}: raw={self.raw_seen} kept={self.kept}");
        visit next_targets else {
            disengage;
        }
    }
}

with entry {
