test "grader reports integers in visit order and computes class average" {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Dave", score=94)
        ++> Quiz(student_name="Eve", score=88);

    grader = root spawn Grader();
    collected = grader.reports;

    # Reports must be strictly typed to integers and in traversal order.
    assert len(collected) == 5, f"expected 5 reports, got {len(collected)}";
    assert collected == [92, 85, 78, 94, 88], f"unexpected reports: {collected}";
    assert all(isinstance(s, int) for s in collected), "reports must all be ints";

    total = sum(collected);
    class_avg = total / len(collected);
    assert abs(class_avg - 87.4) < 1e-9, f"expected avg 87.4, got {class_avg}";

    # Class average should ignore the node's student_name field.
    assert all(isinstance(s, int) for s in collected), "score type must be int";
}

test "grader walks quiz chain beyond first node" {
    # Build a chain so the walker's `visit [-->]` on Quiz entry must traverse
    # multiple links to collect more than one report.
    q1 = Quiz(student_name="Solo", score=10);
    q2 = Quiz(student_name="Next", score=20);
    q3 = Quiz(student_name="Last", score=30);
    root ++> q1 ++> q2 ++> q3;

    grader = root spawn Grader();
    collected = grader.reports;

    assert len(collected) == 3, f"expected 3 reports, got {len(collected)}";
    assert collected == [10, 20, 30], f"unexpected chain reports: {collected}";
}

test "grader yields no reports and average stays at zero with no quizzes" {
    # No Quiz nodes at all — reports must be empty and average must
    # remain the documented default (0.0), not raise.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = root spawn Grader();
    }
    collected = grader.reports;

    assert collected == [], f"expected no reports, got {collected}";
    assert all(isinstance(s, int) for s in collected), "empty list must still satisfy int type";

    total = 0;
    for s in collected {
        total += s;
    }
    count = len(collected);
    class_avg = 0.0;
    if count > 0 {
        class_avg = total / count;
    }
    assert class_avg == 0.0, f"expected default avg 0.0, got {class_avg}";
    assert "[OUT]" not in buf.getvalue(), "no output expected for empty graph";
}

test "score zero and larger classes still produce correct integer average" {
    # Edge values (0 and high score) plus a wider class to stress the
    # strict-int contract and the average arithmetic.
    root ++> Quiz(student_name="Zero", score=0)
        ++> Quiz(student_name="Top", score=100)
        ++> Quiz(student_name="Mid1", score=50)
        ++> Quiz(student_name="Mid2", score=75)
