"""City planner: stations connect to hotels and attractions; build a 4+ star itinerary."""

node Hotel {
    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

node Station {
    has name: str = "";

    def shortlist -> list {
        picks: list = [];
        for n in [-->] {
            if isinstance(n, Attraction) and n.stars >= 4 {
                picks.append(n);
            }
        }
        return picks;
    }
}

edge Near {
    has walking_minutes: int = 0;
}

walker Planner {
    has itinerary: list = [];

    can start with Root entry {
        visit [-->];
    }

    can plan with Station entry {
        print(f"Station: {here.name}");
        picks = here.shortlist();
        for p in picks {
            self.itinerary.append(p);
            print(f"  -> {p.name} ({p.stars}★)");
        }
        visit [-->];
    }
}

with entry {
    central = Station(name="Central Station");
    riverside = Station(name="Riverside Station");

    central +>:Near(walking_minutes=5):+> Hotel(name="Grand Plaza");
    central +>:Near(walking_minutes=8):+> Hotel(name="Budget Inn");
    central +>:Near(walking_minutes=3):+> Attraction(name="Old Museum", stars=3);
    central +>:Near(walking_minutes=7):+> Attraction(name="Sky Tower", stars=5);
    central +>:Near(walking_minutes=12):+> Attraction(name="Harbor Cruise", stars=4);

    riverside +>:Near(walking_minutes=4):+> Hotel(name="Riverside Lodge");
    riverside +>:Near(walking_minutes=6):+> Attraction(name="River Park", stars=4);
    riverside +>:Near(walking_minutes=10):+> Attraction(name="Local Cafe", stars=2);

    root ++> central ++> riverside;

    planner = Planner();
    root spawn planner;

    print("\nFinal itinerary (4★+ attractions):");
    for a in planner.itinerary {
        print(f"  • {a.name} — {a.stars}★");
    }
}
