"""Test annex for city planner: filter to 4+ star attractions only."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: All kept attractions have stars >= 4 ----------
test "filter rejects hotels and sub-4-star attractions" {
    central = Station(name="Central");
    riverside = Station(name="Riverside");

    # Hotels must never appear in itinerary
    central +>:Near:+> Hotel(name="Grand Plaza");
    central +>:Near:+> Hotel(name="Budget Inn");
    # Sub-4-star attraction must be excluded
    central +>:Near:+> Attraction(name="Old Museum", stars=3);
    # 4-star and 5-star attractions must be kept
    central +>:Near:+> Attraction(name="Sky Tower", stars=5);
    central +>:Near:+> Attraction(name="Harbor Cruise", stars=4);

    riverside +>:Near:+> Hotel(name="Riverside Lodge");
    riverside +>:Near:+> Attraction(name="River Park", stars=4);
    riverside +>:Near:+> Attraction(name="Local Cafe", stars=2);

    root ++> central ++> riverside;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        planner = Planner();
        root spawn planner;
    }

    itinerary = planner.itinerary;
    # Only 3 attractions qualify (Sky Tower, Harbor Cruise, River Park)
    assert len(itinerary) == 3, f"expected 3 attractions, got {len(itinerary)}";

    names = [a.name for a in itinerary];
    assert "Sky Tower" in names, f"missing Sky Tower: {names}";
    assert "Harbor Cruise" in names, f"missing Harbor Cruise: {names}";
    assert "River Park" in names, f"missing River Park: {names}";

    # Hotels must not appear
    assert "Grand Plaza" not in names, "hotel Grand Plaza leaked into itinerary";
    assert "Budget Inn" not in names, "hotel Budget Inn leaked into itinerary";
    assert "Riverside Lodge" not in names, "hotel Riverside Lodge leaked into itinerary";

    # Sub-4-star attractions must not appear
    assert "Old Museum" not in names, "3-star Old Museum leaked into itinerary";
    assert "Local Cafe" not in names, "2-star Local Cafe leaked into itinerary";

    # Every kept attraction must satisfy stars >= 4
    for a in itinerary {
        assert a.stars >= 4, f"attraction {a.name} has {a.stars} stars (<4)";
        assert isinstance(a, Attraction), f"{a.name} is not an Attraction";
    }
}

# ---------- Test 2: Single-station graph keeps only qualifying attractions ----------
test "single station filters own neighbors correctly" {
    s = Station(name="Solo");

    s +>:Near:+> Hotel(name="H1");
    s +>:Near:+> Attraction(name="A5", stars=5);
    s +>:Near:+> Attraction(name="A4", stars=4);
    s +>:Near:+> Attraction(name="A3", stars=3);
    s +>:Near:+> Attraction(name="A0", stars=0);

    root ++> s;

    planner = Planner();
    root spawn planner;

    names = [a.name for a in planner.itinerary];
    assert len(planner.itinerary) == 2, f"expected 2, got {len(planner.itinerary)}: {names}";
    assert "A5" in names, f"missing A5: {names}";
    assert "A4" in names, f"missing A4: {names}";
    assert "A3" not in names, f"3-star A3 leaked: {names}";
    assert "A0" not in names, f"0-star A0 leaked: {names}";
    assert "H1" not in names, f"hotel H1 leaked: {names}";
}

# ---------- Test 3: Edge direction is station -> attraction, not attraction -> station ----------
test "edges point from station outward to hotels and attractions" {
    s = Station(name="Outward");
    a = Attraction(name="Spire", stars=5);
    h = Hotel(name="Hostel");

    s +>:Near:+> a;
    s +>:Near:+> h;

    root ++> s;

    neighbors = [s -->];
    assert a in neighbors, "Attraction must be reachable from Station via -->";
    assert h in neighbors, "Hotel must be reachable from Station via -->";
    assert len([s -->]) == 2, f"station should have 2 outgoing edges, got {len([s -->])}";

    # Reverse direction: attraction/hotel should not point back to station
    assert len([a -->]) == 0, "attraction should have no outgoing edges";
    assert len([h -->]) == 0, "hotel should have no outgoing edges";
