    b +>:Near:+> Attraction(name="B-keep", stars=5);

    c +>:Near:+> Attraction(name="C-keep", stars=4);
    c +>:Near:+> Hotel(name="C-hotel");
    c +>:Near:+> Attraction(name="C-drop", stars=1);

