"""Order audit: skip invalid orders, halt the walk on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid amount={here.amount}");
            } else {
                print(f"[AUDIT] amount={here.amount}");
            }
