"""City tourism planner: stations connect to hotels and attractions; build a 4+ star itinerary."""

node Hotel {
    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

edge ConnectsTo {}

walker ItineraryPlanner {
    has min_stars: int = 4;

    can start with Root entry {
        visit [-->];
    }

    can plan with Station entry {
        print(f"--- Planning from station: {here.name} ---");
        visit [-->];
    }

    can select with Hotel | Attraction entry {
        # Union trigger: fires for both Hotel and Attraction.
        # Only Attractions with stars >= min_stars make the cut.
        if isinstance(here, Attraction) {
            if here.stars >= self.min_stars {
                print(f"  [PICK] {here.name} ({here.stars}★)");
            } else {
                print(f"  [skip] {here.name} ({here.stars}★ too low)");
