        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=75.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=300.0, valid=True, fraud=False);
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    return buf.getvalue().strip().splitlines();
}

test "invalid order is skipped but walk continues to later valid orders" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=75.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=False)
        ++> Order(amount=300.0, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    lines = buf.getvalue().strip().splitlines();

