    assert "[AUDIT] amount=100.0" in lines[0], f"first line should audit 100.0: {lines[0]}";
    assert "[SKIP] amount=50.0" in lines[1], f"second line should skip invalid 50.0: {lines[1]}";
    assert "[AUDIT] amount=75.0" in lines[2], f"third line should audit 75.0 (walk continued past skip): {lines[2]}";
    assert "[AUDIT] amount=999.0" in lines[3], f"fourth line should audit 999.0: {lines[3]}";
    assert "[AUDIT] amount=300.0" in lines[4], f"fifth line should audit 300.0: {lines[4]}";
