    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    lines = buf.getvalue().strip().splitlines();

    assert len(lines) == 2, f"fraud must halt the walk; expected 2 lines, got {len(lines)}: {lines}";
    assert "[AUDIT] amount=100.0" in lines[0], f"first audited normally: {lines[0]}";
    assert "[HALT] amount=999.0 flagged for fraud" in lines[1], f"second must be halt: {lines[1]}";
