"""Test annex for OrderAuditor: skip-invalid and halt-on-fraud behaviors."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh order chain on a fresh root and capture stdout.
def run_audit(amounts: list, valids: list, frauds: list) -> str {
    buf = io.StringIO();
    rt = root;
    rt ++> Order(amount=amounts[0], valid=valids[0], fraud=frauds[0])
        ++> Order(amount=amounts[1], valid=valids[1], fraud=frauds[1])
        ++> Order(amount=amounts[2], valid=valids[2], fraud=frauds[2])
        ++> Order(amount=amounts[3], valid=valids[3], fraud=frauds[3])
        ++> Order(amount=amounts[4], valid=valids[4], fraud=frauds[4]);
    with redirect_stdout(buf) {
        res = rt spawn OrderAuditor();
    }
    return buf.getvalue();
}

test "invalid order is skipped and audit continues to next order" {
    amounts = [100.0, 0.0, 250.0, 75.0, 50.0];
    valids = [True, False, True, True, True];
    frauds = [False, False, False, False, False];
    out = run_audit(amounts, valids, frauds);
    assert "Starting order audit" in out, f"missing start line: {out}";
    assert "[AUDIT] approved order amount=100.0" in out, f"first should audit: {out}";
    assert "[SKIP] invalid order amount=0.0" in out, f"second should skip: {out}";
    assert "[AUDIT] approved order amount=250.0" in out, f"third should still audit after skip: {out}";
    assert "[AUDIT] approved order amount=75.0" in out, f"fourth should audit: {out}";
    assert "[AUDIT] approved order amount=50.0" in out, f"fifth should audit: {out}";
    # No halt when there's no fraud.
    assert "[HALT]" not in out, f"unexpected halt line: {out}";
}

test "fraud flag halts the walk immediately and later orders are not visited" {
    amounts = [100.0, 250.0, 999.0, 50.0, 10.0];
    valids = [True, True, True, True, True];
    frauds = [False, False, True, False, False];
    out = run_audit(amounts, valids, frauds);
    assert "Starting order audit" in out, f"missing start: {out}";
    assert "[AUDIT] approved order amount=100.0" in out, f"first should audit: {out}";
    assert "[AUDIT] approved order amount=250.0" in out, f"second should audit: {out}";
    assert "[HALT] fraud flagged amount=999.0" in out, f"third should halt: {out}";
    # Walk must stop on fraud — later orders must NOT be audited.
    assert "amount=50.0" not in out, f"walk should have stopped before 50.0: {out}";
    assert "amount=10.0" not in out, f"walk should have stopped before 10.0: {out}";
    # No skip line should appear either (all orders were valid).
    assert "[SKIP]" not in out, f"unexpected skip line: {out}";
}

test "fraud takes precedence over invalid when both flags are set" {
    amounts = [100.0, 0.0, 999.0, 50.0, 50.0];
    valids = [True, False, True, True, True];
    frauds = [False, False, True, False, False];
    out = run_audit(amounts, valids, frauds);
    assert "[AUDIT] approved order amount=100.0" in out, f"first should audit: {out}";
    # Invalid-but-not-fraud still gets skipped, audit continues.
    assert "[SKIP] invalid order amount=0.0" in out, f"invalid should be skipped: {out}";
    # Fraud must trigger halt, not skip — fraud check is first.
    assert "[HALT] fraud flagged amount=999.0" in out, f"fraud should halt before skip: {out}";
    # Trailing orders not visited due to halt.
    assert "amount=50.0" not in out, f"walk should halt, leaving 50.0 unvisited: {out}";
}

test "fraud on the very first order halts before any audit line" {
    amounts = [999.0, 100.0, 250.0, 50.0, 10.0];
    valids = [True, True, True, True, True];
    frauds = [True, False, False, False, False];
    out = run_audit(amounts, valids, frauds);
    assert "[HALT] fraud flagged amount=999.0" in out, f"first order fraud must halt: {out}";
    assert "[AUDIT]" not in out, f"no audit line should precede the first-order halt: {out}";
    assert "[SKIP]" not in out, f"no skip line either: {out}";
    # Everything after is unreachable.
    assert "amount=100.0" not in out, f"tail must not be visited: {out}";
    assert "amount=250.0" not in out, f"tail must not be visited: {out}";
}

