    }

    # Dispatch count must equal 3 (N1, N3, S1).
    dispatch_lines = [ln for ln in leg_lines if "[DISPATCH]" in ln];
    hold_lines = [ln for ln in leg_lines if "[HOLD]" in ln];
    assert len(dispatch_lines) == 3, f"expected 3 dispatches, got {len(dispatch_lines)}: {out}";
    assert len(hold_lines) == 3, f"expected 3 holds, got {len(hold_lines)}: {out}";
