"""Order audit walk: skip invalid orders, halt on fraud, audit the rest."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged on order ${here.amount}");
            disengage;
        } elif not here.valid {
            print(f"[SKIP] invalid order ${here.amount}");
            visit [-->];
        } else {
            print(f"[AUDIT] cleared order ${here.amount}");
            visit [-->];
        }
    }
}

with entry {
    root ++> Order(amount=49.99, valid=True, fraud=False)
        ++> Order(amount=10.00, valid=False, fraud=False)
        ++> Order(amount=150.00, valid=True, fraud=False)
        ++> Order(amount=999.00, valid=True, fraud=True)
        ++> Order(amount=25.00, valid=True, fraud=False);
    root spawn OrderAuditor();
}
