"""Order auditor: skip invalid orders and halt the whole walk on fraud."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud_flagged: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud_flagged {
            print(f"[HALT] fraud flagged order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"[AUDIT] order amount={here.amount}");
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=100, valid=True)
        ++> Order(amount=0, valid=False)
        ++> Order(amount=250, valid=True)
        ++> Order(amount=999, valid=True, fraud_flagged=True)
        ++> Order(amount=50, valid=True);
    root spawn OrderAuditor();
}
