jac_tests:
"""Test annex for OrderAuditor: skip-invalid vs halt-on-fraud semantics."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a chain of Orders off root and run the auditor, returning stdout.
def run_audit(orders: list) -> str {
    buf = io.StringIO();
    rt = root;
    # Attach orders as a chain in given order using ++>.
    cur = rt;
    for o in orders {
        cur ++> o;
        cur = o;
    }
    with redirect_stdout(buf) {
        rt spawn OrderAuditor();
    }
    return buf.getvalue();
}

test "audits every valid order in order" {
    out = run_audit([
        Order(amount=100, valid=True),
        Order(amount=200, valid=True),
        Order(amount=300, valid=True),
    ]);
    expected = (
        "[AUDIT] order amount=100\n"
        "[AUDIT] order amount=200\n"
        "[AUDIT] order amount=300\n"
    );
    assert out == expected, f"unexpected audit output: {out!r}";
}

test "invalid orders are skipped but audit continues to later orders" {
    out = run_audit([
        Order(amount=100, valid=True),
        Order(amount=0, valid=False),
        Order(amount=250, valid=True),
    ]);
    # The invalid one must show SKIP, and the third valid one must still audit.
    assert "[AUDIT] order amount=100" in out, f"first audit missing: {out}";
    assert "[SKIP] invalid order amount=0" in out, f"skip missing: {out}";
    assert "[AUDIT] order amount=250" in out, f"audit did not continue past invalid: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";
}

test "fraud flagged order halts the whole walk immediately" {
    out = run_audit([
        Order(amount=100, valid=True),
        Order(amount=250, valid=True),
        Order(amount=999, valid=True, fraud_flagged=True),
        Order(amount=50, valid=True),
    ]);
    # The fraud order itself prints HALT.
    assert "[HALT] fraud flagged order amount=999" in out, f"halt line missing: {out}";
    # Earlier orders must have been audited.
    assert "[AUDIT] order amount=100" in out, f"pre-fraud audit missing: {out}";
    assert "[AUDIT] order amount=250" in out, f"pre-fraud audit missing: {out}";
    # Nothing after the fraud order should appear.
    assert "[AUDIT] order amount=50" not in out, f"walk continued past halt: {out}";
    assert "[SKIP]" not in out, f"unexpected skip after halt: {out}";
}

test "fraud on first order halts before any audit" {
    out = run_audit([
        Order(amount=7, valid=True, fraud_flagged=True),
        Order(amount=8, valid=True),
    ]);
    assert out.startswith("[HALT] fraud flagged order amount=7"), f"not halted first: {out!r}";
    assert "[AUDIT]" not in out, f"audit fired despite immediate halt: {out}";
}

test "default flags produce full audit of defaults" {
    # Defaults: valid=True, fraud_flagged=False, amount=0.
    out = run_audit([
        Order(),
        Order(),
    ]);
    assert "[AUDIT] order amount=0\n[AUDIT] order amount=0\n" == out, f"defaults wrong: {out!r}";
    assert "[SKIP]" not in out and "[HALT]" not in out, f"unexpected marker: {out}";
}

