    with redirect_stdout(buf) {
        root spawn Dispatcher();
    }
    out = buf.getvalue();

    assert "[HOLD] South Yard: 1.2 tonnes" in out, (
        f"1.2 (below 2) must be held, got: {out!r}"
    );
    assert "[HOLD] West Mine: 9.4 tonnes" in out, (
