"""City itinerary: model stations, hotels, and rated attractions, then walk
from each station to shortlist only the attractions rated 4 stars or higher."""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has rooms: int = 0;
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

walker ItineraryPlanner {
    has min_stars: int = 4;

    can start with Root entry {
        visit [-->];
    }

    can plan with Station entry {
        print(f"Itinerary from station: {here.name}");
        visit [-->];
    }

    can filter with Hotel | Attraction entry {
        # Only attractions make the cut; hotels are skipped silently.
        visit [-->];
    }

    can shortlist with Attraction entry {
        if here.stars >= self.min_stars {
            rating = f"{here.stars}-star";
            print(f"  -> {rating} attraction: {here.name}");
        }
        visit [-->];
    }
}

with entry {
    central = Station(name="Central Station");
    north = Station(name="North Station");
    west = Station(name="West Station");

    central ++> Hotel(name="Grand Plaza", rooms=120);
    central ++> Attraction(name="Old Museum", stars=3);
    central ++> Attraction(name="Skyline Tower", stars=5);
    central ++> Attraction(name="River Cruise", stars=4);

    north ++> Hotel(name="Lakeside Inn", rooms=60);
    north ++> Attraction(name="Botanical Garden", stars=4);
    north ++> Attraction(name="Historic Fort", stars=2);

    west ++> Attraction(name="Amusement Park", stars=5);
    west ++> Hotel(name="Budget Lodge", rooms=40);
    west ++> Attraction(name="Street Market", stars=4);

    root ++> central ++> north ++> west;

    root spawn ItineraryPlanner(min_stars=4);
}
