"""Order auditor: skip invalid orders and halt the walk on fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged on order amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
            } else {
                print(f"[AUDIT] approved order amount={here.amount}");
            }
            visit [-->];
        }
    }
}

with entry {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=200.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=10.0, valid=True, fraud=False);
    root spawn OrderAuditor();
}
```

