"""Delivery dispatch: check every depot and flag routes that meet the 2-8 tonne weight window."""

node Route {
    has destination: str = "";
    has weight: float = 0.0;
    has available: bool = True;
}

walker Dispatcher {
    can start with Root entry {
        print("Checking routes for dispatch eligibility (2-8 tonnes)...");
        visit [-->];
    }

    can inspect with Route entry {
        qualifies = (here.weight >= 2.0) and (here.weight <= 8.0);
        status = "DISPATCH" if qualifies else "HOLD";
        print(f"[{status}] {here.destination}: {here.weight}t");
        visit [-->];
    }
}

with entry {
    root ++> Route(destination="North Yard", weight=3.5)
        ++> Route(destination="East Depot", weight=7.8)
        ++> Route(destination="South Hub", weight=1.2)
        ++> Route(destination="West Terminal", weight=8.0)
        ++> Route(destination="Central Warehouse", weight=9.5);
    root spawn Dispatcher();
}
