"""Dungeon crawler: chained rooms, one treasure vault, hunter stops at loot."""

node Room {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

