        state = "TREASURE" if here.has_treasure else "empty";
        print(f"[{self.rooms_seen}] {here.title} (depth {here.year}) — {state}");
        if here.has_treasure {
            print(f"Loot secured in {here.title}! Turning back.");
            disengage;
        } else {
            visit [-->] else { disengage; };
