    root ++> Room(title="Entrance", year=1)
        ++> Room(title="Hall of Echoes", year=2)
        ++> Room(title="Vault", year=3, has_treasure=True)
        ++> Room(title="Dragon's Lair", year=4);
    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter stopped after {hunter.rooms_seen} room(s).");
}
