"""Dungeon crawler: chain rooms and hunt treasure with early termination."""

node Room {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        print("Hunter enters the dungeon.");
        visit [-->];
    }

    can search with Room entry {
        self.rooms_seen += 1;
        status = "TREASURE" if here.has_treasure else "empty";
        print(f"Room {self.rooms_seen}: {here.title} (depth {here.year}) [{status}]");
        if here.has_treasure {
            print(f"Treasure found in {here.title}! Ending search after {self.rooms_seen} rooms.");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(title="Entrance", year=1)
        ++> Room(title="Hallway", year=2)
        ++> Room(title="Vault", year=3, has_treasure=True)
        ++> Room(title="Secret Lair", year=4);
    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter finished — examined {hunter.rooms_seen} room(s); rooms beyond the vault were skipped.");
}
