"""Tests for the quiz grader walker."""

import io;
import from contextlib { redirect_stdout }

test "reports are strictly typed integers" {
    root ++> Quiz(student="Alice", score=95)
        ++> Quiz(student="Bob", score=82)
        ++> Quiz(student="Carol", score=88);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = root spawn Grader();
    }
    for score in grader.reports {
        assert isinstance(score, int) and not isinstance(score, bool),
            f"score must be plain int, got {type(score).__name__}: {score!r}";
    }
    out = buf.getvalue();
    assert "Graded Alice: 95" in out, f"missing Alice line: {out}";
    assert "Graded Bob: 82" in out, f"missing Bob line: {out}";
    assert "Graded Carol: 88" in out, f"missing Carol line: {out}";
}

test "collected scores and class average match expectations" {
    root ++> Quiz(student="Alice", score=95)
        ++> Quiz(student="Bob", score=82)
        ++> Quiz(student="Carol", score=88)
        ++> Quiz(student="Dan", score=76);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = root spawn Grader();
        collected: list[int] = grader.reports;
        total = 0;
        for s in collected {
            total += s;
        }
        count = len(collected);
        avg = total // count if count > 0 else 0;
        print(f"Collected scores: {collected}");
        print(f"Class average: {avg}");
    }
    assert grader.reports == [95, 82, 88, 76], f"unexpected reports: {grader.reports}";
    out = buf.getvalue();
    assert "Collected scores: [95, 82, 88, 76]" in out,
        f"missing collected scores line: {out}";
    # 95+82+88+76 = 341, 341//4 = 85
    assert "Class average: 85" in out, f"missing/incorrect average line: {out}";
}

