    assert set(grader.reports) == expected_scores,
        f"score set mismatch: {set(grader.reports)} vs {expected_scores}";
}

test "rejects string scores and averages correctly when scores vary" {
    root ++> Quiz(student="X", score=100)
        ++> Quiz(student="Y", score=50)
        ++> Quiz(student="Z", score=0);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        grader = root spawn Grader();
        collected: list[int] = grader.reports;
        total = 0;
        for s in collected {
            total += s;
        }
        count = len(collected);
        avg = total // count if count > 0 else 0;
        print(f"Class average: {avg}");
    }
    for v in grader.reports {
        assert isinstance(v, int), f"non-int leaked into reports: {type(v).__name__}";
        assert v >= 0, f"negative score in reports: {v}";
    }
    # 100+50+0 = 150, 150//3 = 50
    assert "Class average: 50" in buf.getvalue(),
        f"average should be 50, got output: {buf.getvalue()}";
}

