"""Test annex for order auditor: skip vs halt behavior."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: invalid orders skipped, audit continues ----------
test "invalid order is skipped and audit continues" {
    root ++> Order(amount=50.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=False, fraud=False)
        ++> Order(amount=70.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "Beginning order audit" in out, f"missing audit banner: {out}";
    assert "[AUDIT] valid order amount=50.0" in out, f"first order should be audited: {out}";
    assert "[SKIP] invalid order amount=20.0" in out, f"invalid order should be skipped: {out}";
    assert "[AUDIT] valid order amount=70.0" in out, f"audit must continue after skip: {out}";
}

# ---------- Test 2: fraud halts the walk immediately ----------
test "fraud flagged order halts the entire walk" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=200.0, valid=True, fraud=True)
        ++> Order(amount=300.0, valid=True, fraud=False)
        ++> Order(amount=400.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] valid order amount=100.0" in out, f"first valid order should be audited: {out}";
    assert "[HALT] fraud flagged order amount=200.0" in out, f"fraud order should trigger halt: {out}";
    # Orders after the fraud must never be visited
    assert "amount=300.0" not in out, f"walk should have stopped before 300.0: {out}";
    assert "amount=400.0" not in out, f"walk should have stopped before 400.0: {out}";
}

# ---------- Test 3: fraud takes priority over invalidity ----------
test "fraud check fires before validity check" {
    # Even an invalid+fraud order must halt, not skip
    root ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=25.0, valid=False, fraud=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] valid order amount=10.0" in out, f"first order should be audited: {out}";
    assert "[HALT] fraud flagged order amount=25.0" in out, f"fraud should halt even when also invalid: {out}";
    assert "[SKIP]" not in out, f"fraud order must not be reported as skip: {out}";
}

# ---------- Test 4: fraud as the very first order halts immediately ----------
test "fraud on the first order halts before any audit" {
    root ++> Order(amount=500.0, valid=True, fraud=True)
        ++> Order(amount=600.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] fraud flagged order amount=500.0" in out, f"first-order fraud should halt: {out}";
    assert "[AUDIT]" not in out, f"no valid order audit should occur: {out}";
    assert "amount=600.0" not in out, f"later order must not be visited: {out}";
}

