"""Dungeon crawl: chained rooms hide treasure; a hunter stops at the vault."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
    has cleared: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can search with Room entry {
        self.rooms_seen += 1;
        label = "VAULT" if here.has_treasure else "empty";
        print(f"[{self.rooms_seen}] {here.name} ({label})");
        if here.has_treasure {
            print("Treasure secured — search ends.");
            disengage;
        } else {
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Room(name="Entry Hall")
        ++> Room(name="Dark Corridor")
        ++> Room(name="Treasure Vault", has_treasure=True)
        ++> Room(name="Dragon Lair");
    hunter = Hunter();
    root spawn hunter;
    print(f"Rooms searched: {hunter.rooms_seen}");
}
