"""City tour planner: stations connect to hotels and rated attractions.

Each station shortlists its high-rated attractions (>= 4 stars),
ignoring hotels entirely, and prints the curated itinerary.
"""

node Hotel {
    has name: str = "";
}

node Attraction {
    has name: str = "";
    has stars: int = 0;
}

node Station {
    has name: str = "";
}

edge ConnectsTo {}

walker Planner {
    has itinerary: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can tour with Station entry {
        print(f"Station: {here.name}");
        visit [-->];
    }

    can collect with Hotel entry {
        # Hotels are intentionally ignored.
        visit [-->];
    }

    can rank with Attraction entry {
        if here.stars >= 4 {
            self.itinerary.append(f"{here.name} ({here.stars}*)");
        }
        visit [-->];
    }
}

with entry {
    central = Station(name="Central Station");
    riverside = Station(name="Riverside Station");

    central +>:ConnectsTo:+> Hotel(name="Grand Plaza Hotel");
    central +>:ConnectsTo:+> Attraction(name="Old Museum", stars=3);
    central +>:ConnectsTo:+> Attraction(name="Sky Tower", stars=5);

    riverside +>:ConnectsTo:+> Hotel(name="Riverside Inn");
    riverside +>:ConnectsTo:+> Attraction(name="Riverwalk Park", stars=4);
    riverside +>:ConnectsTo:+> Attraction(name="Backstreet Cafe", stars=2);

    root ++> central ++> riverside;

    planner = Planner();
    root spawn planner;

    print("Final Itinerary:");
    for stop in planner.itinerary {
        print(f"  - {stop}");
    }
}
