    chain = [children[0]];
    for _ in range(5) {
        next_nodes = [chain[-1]-->];
        if len(next_nodes) == 0 { break; }
        chain.extend(next_nodes);
    }

    titles = [r.title for r in chain];
    assert titles == ["Entry", "Hall", "Vault", "Exit"], f"unexpected chain order/titles: {titles}";

    vault = chain[2];
