"""City tour planner: stations branch to hotels and attractions, and a walker
shortlists only the top-rated attractions (>= 4 stars) for the itinerary."""

node Place {
    has name: str = "";
    has stars: int = 0;
}

node Hotel(Place) {
}

node Attraction(Place) {
}

node Station {
    has name: str = "";
}

edge Branch {
    has kind: str = "";
}

walker Itinerary {
    can start with Root entry {
        visit [-->];
    }

