    central +>:Branch(kind="lodging"):+> Hotel(name="Grand Plaza", stars=5);
    central +>:Branch(kind="lodging"):+> Hotel(name="Budget Inn", stars=2);
    central +>:Branch(kind="sight"):+> Attraction(name="Old Museum", stars=4);
