"""Order auditor: skip invalid orders and halt the walk on flagged fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] amount={here.amount} flagged for fraud — stopping audit");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] amount={here.amount} invalid — continuing");
                visit [-->];
            } else {
                print(f"[AUDIT] amount={here.amount} cleared");
                visit [-->];
            }
        }
    }
}

with entry {
    root ++> Order(amount=120.0, valid=True, fraud=False)
        ++> Order(amount=45.0, valid=False, fraud=False)
        ++> Order(amount=310.0, valid=True, fraud=False)
        ++> Order(amount=5000.0, valid=True, fraud=True)
        ++> Order(amount=80.0, valid=True, fraud=False);
    root spawn OrderAuditor();
}
```

