"""Dungeon crawler: chained rooms, treasure vault, and a hunter that stops at the loot."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
