        print(f"[Hunter] Checking {here.name} (room {self.rooms_seen})");
        if here.has_treasure {
            print(f"[Hunter] Treasure found in {here.name}! Ending search.");
            disengage;
        }
        visit [-->];
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hall")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Beyond");
    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter saw {hunter.rooms_seen} room(s); nothing past the vault was entered.");
}
