"""Order auditor: skip invalid orders, halt the walk on fraud flags."""

node Order {
    has amount: int = 0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] fraud flagged amount={here.amount}");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] invalid order amount={here.amount}");
                visit [-->] else { disengage; }
            } else {
                print(f"[OK] audited amount={here.amount}");
                visit [-->] else { disengage; }
            }
        }
    }
}

with entry {
    root ++> Order(amount=40, valid=True, fraud=False)
        ++> Order(amount=0, valid=False, fraud=False)
        ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=500, valid=True, fraud=True)
        ++> Order(amount=15, valid=True, fraud=False);
    root spawn OrderAuditor();
}
```

