"""Test annex for the order auditor."""

import io;
import from contextlib { redirect_stdout }

test "skip invalid and halt on fraud" {
    root ++> Order(amount=100)
        ++> Order(amount=50, valid=False)
        ++> Order(amount=75)
        ++> Order(amount=999, fraud=True)
        ++> Order(amount=200);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Head: "Starting order audit"
    assert out.startswith("Starting order audit\n"), f"missing banner: {out!r}";

    # 1) PASS the first valid order
    assert "[PASS] audited amount=100" in out, f"missing PASS 100: {out!r}";

    # 2) SKIP the invalid one — invalid orders do NOT abort, audit continues
    assert "[SKIP] invalid order amount=50" in out, f"missing SKIP 50: {out!r}";

    # 3) After the skip, the walk MUST resume onto later orders
    assert "[PASS] audited amount=75" in out, f"audit did not continue past invalid: {out!r}";

    # 4) HALT on the fraud order
    assert "[HALT] fraud flagged amount=999" in out, f"missing HALT 999: {out!r}";

    # 5) disengage must stop the walk — the order AFTER the fraud one must not be audited
    assert "[PASS] audited amount=200" not in out, f"walk continued after HALT: {out!r}";
    assert "[SKIP] invalid order amount=200" not in out, f"walk continued after HALT: {out!r}";
    assert "[HALT] fraud flagged amount=200" not in out, f"walk continued after HALT: {out!r}";

    # Exactly four order lines (one per order visited), and HALT must be the last action
    lines = [l for l in out.splitlines() if l.startswith("[")];
    assert len(lines) == 4, f"expected 4 order lines, got {len(lines)}: {lines}";
    assert lines[-1].startswith("[HALT]"), f"HALT was not the final action: {lines}";
}

