    assert "[PASS] audited amount=30" in out, f"missing PASS 30: {out!r}";
    assert "[SKIP]" not in out, f"unexpected SKIP on all-valid run: {out!r}";
    assert "[HALT]" not in out, f"unexpected HALT on fraud-free run: {out!r}";

