"""Delivery route dispatch checker.

Each route carries a cargo weight in tonnes. A truck may only be dispatched
when its load is at least 2 tonnes and at most 8 tonnes. The walker visits
every route connected from the root and prints whether each route qualifies.
"""

node Route {
    has label: str = "";
    has weight: float = 0.0;

    def qualifies() -> bool {
        return self.weight >= 2.0 and self.weight <= 8.0;
    }
}

walker Dispatcher {
    can start with Root entry {
        visit [-->];
    }

    can check with Route entry {
        verdict = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"[{verdict}] route {here.label} ({here.weight}t)");
        visit [-->];
    }
}

with entry {
    root ++> Route(label="R-1", weight=1.5)
        ++> Route(label="R-2", weight=3.0)
        ++> Route(label="R-3", weight=8.0)
        ++> Route(label="R-4", weight=9.5)
        ++> Route(label="R-5", weight=2.0);
    root spawn Dispatcher();
