# ---------------------------------------------------------------------------
test "demo chain emits SKIP / OK / HALT and stops on fraud" {
    root ++> Order(amount=120.0, valid=True,  fraud_flag=False)
        ++> Order(amount=0.0,   valid=False, fraud_flag=False)
        ++> Order(amount=85.0,  valid=True,  fraud_flag=False)
        ++> Order(amount=999.0, valid=True,  fraud_flag=True)
        ++> Order(amount=40.0,  valid=True,  fraud_flag=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Every required marker must appear, in order.
    assert "Audit walk starting" in out, f"missing start banner: {out}";
    assert "OK audited order amount=120.0" in out,   f"missing first OK: {out}";
    assert "SKIP invalid order amount=0.0" in out,   f"missing SKIP: {out}";
    assert "OK audited order amount=85.0" in out,    f"missing mid OK: {out}";
    assert "HALT fraud order amount=999.0" in out,   f"missing HALT: {out}";

    # After HALT, the post-fraud order (40.0) must NOT be audited.
    assert "amount=40.0" not in out, f"fraud should halt walk but got: {out}";

    # Ordering constraints between the markers.
    assert out.index("OK audited order amount=120.0") < out.index("SKIP invalid order amount=0.0");
    assert out.index("SKIP invalid order amount=0.0") < out.index("OK audited order amount=85.0");
    assert out.index("OK audited order amount=85.0")  < out.index("HALT fraud order amount=999.0");
}

# ---------------------------------------------------------------------------
