    assert "SKIP invalid order amount=20.0" in out, f"missing SKIP: {out}";
    assert "OK audited order amount=30.0"   in out, f"missing last OK: {out}";
    assert "HALT" not in out, f"no fraud should produce no HALT: {out}";
