"""Delivery routes: model depots and routes as nodes, walk the network with a dispatcher walker."""

node Depot {
    has name: str = "";
}

node Route {
    has name: str = "";
    has cargo_tonnes: float = 0.0;

    def qualifies() -> bool {
        return self.cargo_tonnes >= 2.0 and self.cargo_tonnes <= 8.0;
    }
}

edge Serves {
    has leg_id: str = "";
}

walker Dispatcher {
    can start with Root entry {
        visit [-->];
    }

    can check_depot with Depot entry {
        print(f"Checking depot: {here.name}");
        visit [-->];
    }

    can inspect_route with Route entry {
        verdict = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  Route {here.name} ({here.cargo_tonnes}t) -> {verdict}");
    }
}

with entry {
    north = Depot(name="North Depot");
    south = Depot(name="South Depot");

    north +>:Serves(leg_id="N1"):+> Route(name="N-A", cargo_tonnes=1.5);
    north +>:Serves(leg_id="N2"):+> Route(name="N-B", cargo_tonnes=5.0);
    north +>:Serves(leg_id="N3"):+> Route(name="N-C", cargo_tonnes=9.0);

    south +>:Serves(leg_id="S1"):+> Route(name="S-A", cargo_tonnes=2.0);
    south +>:Serves(leg_id="S2"):+> Route(name="S-B", cargo_tonnes=8.0);
    south +>:Serves(leg_id="S3"):+> Route(name="S-C", cargo_tonnes=3.5);

    root ++> north ++> south;

    root spawn Dispatcher();
}
