    assert "[AUDIT] approved order amount=40.0" in lines[4], f"fifth line wrong: {lines[4]}";

    skip_count = sum(1 for l in lines if "[SKIP]" in l);
    audit_count = sum(1 for l in lines if "[AUDIT]" in l);
