"""Dungeon crawler: chained rooms with a treasure vault; Hunter stops at the loot."""

node Room {
    has name: str = "";
    has has_treasure: bool = False;
}

walker Hunter {
    has rooms_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hunt with Room entry {
        self.rooms_seen += 1;
        print(f"Checking {here.name} (room {self.rooms_seen})");
        if here.has_treasure {
            print(f"Treasure found in {here.name}! Ending search.");
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Hallway")
        ++> Room(name="Vault", has_treasure=True)
        ++> Room(name="Secret Chamber");
    hunter = Hunter();
    root spawn hunter;
    print(f"Hunter inspected {hunter.rooms_seen} room(s); rooms beyond the vault were skipped.");
}
