"""Depot dispatch checker: walk routes from each depot and qualify legs by cargo weight."""

node Depot {
    has name: str = "";
}

node Route {
    has label: str = "";
    has cargo_tonnes: float = 0.0;

    def qualifies() -> bool {
        return self.cargo_tonnes >= 2.0 and self.cargo_tonnes <= 8.0;
    }
}

edge Serves {}

walker Dispatcher {
    has depot_name: str = "";
    can start with Root entry {
        visit [-->];
    }
    can check_depot with Depot entry {
        self.depot_name = here.name;
        print(f"Depot {self.depot_name} routes:");
        visit [-->];
    }
    can inspect_route with Route entry {
        verdict = "DISPATCH" if here.qualifies() else "HOLD";
        print(f"  [{verdict}] {here.label} ({here.cargo_tonnes}t)");
    }
}

with entry {
    north = Depot(name="North");
    south = Depot(name="South");

    north +>:Serves:+> Route(label="N-A", cargo_tonnes=1.5);
    north +>:Serves:+> Route(label="N-B", cargo_tonnes=3.0);
    north +>:Serves:+> Route(label="N-C", cargo_tonnes=7.5);
    north +>:Serves:+> Route(label="N-D", cargo_tonnes=9.0);

    south +>:Serves:+> Route(label="S-A", cargo_tonnes=2.0);
    south +>:Serves:+> Route(label="S-B", cargo_tonnes=8.0);
    south +>:Serves:+> Route(label="S-C", cargo_tonnes=0.5);
    south +>:Serves:+> Route(label="S-D", cargo_tonnes=5.5);

    root ++> north ++> south;
    root spawn Dispatcher();
}
