"""Order auditor: skip invalid orders and halt the walk on fraud flags."""

node Order {
    has amount: float = 0.0;
    has is_valid: bool = True;
    has is_fraud: bool = False;
}

walker OrderAuditor {
    has audited_count: int = 0;

    can start with Root entry {
        print("Order audit started");
        visit [-->];
    }

    can audit with Order entry {
        if here.is_fraud {
            print(f"[HALT] amount={here.amount} — fraud flagged, stopping audit");
            disengage;
        }
        if not here.is_valid {
            print(f"[SKIP] amount={here.amount} — invalid order, continuing");
            visit [-->] else { disengage; };
        } else {
            self.audited_count += 1;
            print(f"[OK] amount={here.amount} — audited (total {self.audited_count})");
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    root ++> Order(amount=120.50, is_valid=True, is_fraud=False)
        ++> Order(amount=0.0, is_valid=False, is_fraud=False)
        ++> Order(amount=75.25, is_valid=True, is_fraud=False)
        ++> Order(amount=999.99, is_valid=True, is_fraud=True)
        ++> Order(amount=15.00, is_valid=True, is_fraud=False);
    auditor = OrderAuditor();
    root spawn auditor;
    print(f"Audit finished with {auditor.audited_count} orders passed");
}
