"""Tests for OrderAuditor: SKIP on invalid continues walk; HALT on fraud stops walk."""

import io;
import from contextlib { redirect_stdout }

def make_chain {
    return root ++> Order(amount=100, valid=True)
        ++> Order(amount=50, valid=False)
        ++> Order(amount=200, valid=True)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=75, valid=True);
}

test "valid orders are audited and fraud halts mid-walk" {
    make_chain();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    # The "Starting order audit" header always fires first.
    assert out.startswith("Starting order audit\n"), f"missing start line: {out!r}";
    # First valid order (100) is audited.
    assert "[AUDIT] valid order amount=100" in out, f"missing AUDIT 100: {out}";
    # Invalid order (50) is skipped, not audited.
    assert "[SKIP] invalid order amount=50" in out, f"missing SKIP 50: {out}";
    # Audit continues to the next valid order (200) after the skip.
    assert "[AUDIT] valid order amount=200" in out, f"missing AUDIT 200 after SKIP: {out}";
    # Fraud order (999) triggers HALT.
    assert "[HALT] fraud flagged order amount=999" in out, f"missing HALT 999: {out}";
    # The post-halt order (75) must NOT be visited — disengage stops the whole walk.
    assert "amount=75" not in out, f"walk continued past HALT: {out}";
    # Fraud line must come after the 200 audit and before any 75 line.
    assert out.index("amount=200") < out.index("amount=999"), f"order wrong: {out}";
}

test "invalid order is skipped but traversal continues to next valid order" {
    root ++> Order(amount=10, valid=True)
        ++> Order(amount=20, valid=False)
        ++> Order(amount=30, valid=True);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    # Both 10 and 30 should be audited, 20 skipped.
    assert "[AUDIT] valid order amount=10" in out, f"missing AUDIT 10: {out}";
    assert "[SKIP] invalid order amount=20" in out, f"missing SKIP 20: {out}";
    assert "[AUDIT] valid order amount=30" in out, f"missing AUDIT 30 after SKIP: {out}";
    # No fraud halt, so no HALT marker.
    assert "[HALT]" not in out, f"unexpected HALT: {out}";
}

test "fraud on the very first order halts before any audits" {
    root ++> Order(amount=7, valid=True, fraud=True)
        ++> Order(amount=8, valid=True);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();
    # The first order (7) hits fraud and halts.
    assert "[HALT] fraud flagged order amount=7" in out, f"missing HALT 7: {out}";
    # No audit line should appear since fraud fired on entry.
    assert "[AUDIT]" not in out, f"audit ran despite first-order fraud: {out}";
    # Second order never visited.
    assert "amount=8" not in out, f"second order visited after HALT: {out}";
}

test "all-valid chain produces only AUDIT lines and a clean exit" {
    root ++> Order(amount=1, valid=True)
        ++> Order(amount=2, valid=True)
        ++> Order(amount=3, valid=True);
