```jac
"""Co-authorship contact suggester: walks two edges out and filters self and direct co-authors."""

node Researcher {
    has name: str = "";
    has direct_coauthors: list[str] = [];
    has suggestions: list[str] = [];
}

edge Coauthored { has since: str = ""; }

walker SuggestContacts {
    has owner_name: str = "";
    has first_hop: list = [];
    has seen: dict = {};
    has results: list = [];
    has target: Researcher | None = None;

    can start with Root entry {
        if self.target is None {
            print("No researcher to suggest contacts for.");
            disengage;
        }
        visit [-->];
    }

    can land_on_target with Researcher entry {
        if self.target is None or here.name != self.target.name {
            visit [-->];
        } else {
            print(f"Suggesting contacts for {here.name}:");
            # First hop: gather direct co-authors to exclude later.
            self.first_hop = [];
            for person in self.first_hop {
                continue;
            }
            self.first_hop = [r.name for r in [->:Coauthored:->]];
            # Second hop: walk to co-authors of co-authors, collecting names.
            self.results = [];
            for direct in [->:Coauthored:->] {
                for second in [direct->:Coauthored:->] {
                    if second.name == here.name {
                        continue;
                    }
                    if second.name in self.first_hop {
                        continue;
                    }
                    if second.name in self.results {
                        continue;
                    }
                    self.results.append(second.name);
                }
            }
            print(f"  direct co-authors: {self.first_hop}");
            print(f"  suggested contacts (distance 2): {self.results}");
            disengage;
        }
    }
}

with entry {
    # Build a small co-authorship graph.
    # Alice <-> Bob <-> Carol <-> David
    # Alice <-> Eve
    # Bob <-> Frank
    alice = Researcher(name="Alice");
    bob = Researcher(name="Bob");
    carol = Researcher(name="Carol");
    david = Researcher(name="David");
    eve = Researcher(name="Eve");
    frank = Researcher(name="Frank");

    root ++> alice ++> bob ++> carol ++> david;
    root ++> alice ++> eve;
    root ++> bob ++> frank;

    alice +>:Coauthored(since="2021"):+> bob;
    bob +>:Coauthored(since="2021"):+> alice;
    alice +>:Coauthored(since="2020"):+> eve;
    eve +>:Coauthored(since="2020"):+> alice;
    bob +>:Coauthored(since="2019"):+> frank;
    frank +>:Coauthored(since="2019"):+> bob;
    bob +>:Coauthored(since="2022"):+> carol;
    carol +>:Coauthored(since="2022"):+> bob;
    carol +>:Coauthored(since="2023"):+> david;
    david +>:Coauthored(since="2023"):+> carol;

    # Demonstrate for Alice.
    root spawn SuggestContacts(target=alice);
}
