"""Regression tests for Order auditor: skip invalid, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

def run_audit(orders) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        r = root;
        for o in orders {
            r ++> o;
            r = o;
        }
        root spawn OrderAuditor();
    }
    return buf.getvalue();
}

test "halt on fraud stops walk immediately" {
    out = run_audit([
        Order(amount=100),
        Order(amount=999, fraud=True),
        Order(amount=75),
    ]);
    lines = [l for l in out.split("\n") if l];
    assert lines[0] == "Order audit started", f"got first line: {lines[0]}";
    assert "[HALT] amount=999 flagged for fraud — audit stopped" in out, f"missing halt line: {out}";
    assert "[PASS] amount=100 approved" in out, f"halt should still come after the approved pre-fraud order: {out}";
    assert "[PASS] amount=75 approved" not in out, f"walk must NOT continue past fraud: {out}";
    assert "[SKIP] amount=75" not in out, f"walk must NOT continue past fraud: {out}";
    assert lines.index("[HALT] amount=999 flagged for fraud — audit stopped") < len(lines) - 1 or out.endswith("\n"), f"halt must not be last meaningful line plus check trailing";
}

test "invalid orders are skipped and walk continues" {
    out = run_audit([
        Order(amount=100),
