"""Tests for the OrderAuditor: skip invalid while continuing, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

test "audits all valid non-fraud orders and stops at end" {
    root ++> Order(amount=10, valid=True, fraud=False)
        ++> Order(amount=20, valid=True, fraud=False)
        ++> Order(amount=30, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "Starting order audit" in out, f"missing banner: {out!r}";
    assert "[AUDIT] approved order amount=10" in out, f"missing order 10: {out!r}";
    assert "[AUDIT] approved order amount=20" in out, f"missing order 20: {out!r}";
    assert "[AUDIT] approved order amount=30" in out, f"missing order 30: {out!r}";
    assert "[SKIP]" not in out, f"unexpected skip in all-valid run: {out!r}";
    assert "[HALT]" not in out, f"unexpected halt in all-valid run: {out!r}";
    assert out.count("[AUDIT]") == 3, f"expected 3 audits, got {out.count('[AUDIT]')}: {out!r}";
}

test "invalid orders are skipped but walk continues to later orders" {
    root ++> Order(amount=50, valid=True, fraud=False)
        ++> Order(amount=0, valid=False, fraud=False)
        ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=30, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP] invalid order amount=0" in out, f"missing skip line: {out!r}";
    assert "[AUDIT] approved order amount=50" in out, f"missing audit 50 (pre-skip): {out!r}";
    assert "[AUDIT] approved order amount=120" in out, f"missing audit 120 (post-skip): {out!r}";
    assert "[AUDIT] approved order amount=30" in out, f"missing audit 30 (post-skip): {out!r}";
    assert "[HALT]" not in out, f"no halt expected when only skipping: {out!r}";
    assert out.count("[SKIP]") == 1, f"expected exactly 1 skip, got {out.count('[SKIP]')}: {out!r}";
    assert out.count("[AUDIT]") == 3, f"expected 3 audits, got {out.count('[AUDIT]')}: {out!r}";
}

test "fraud flag halts the walk immediately and skips remaining orders" {
    root ++> Order(amount=50, valid=True, fraud=False)
        ++> Order(amount=0, valid=False, fraud=False)
        ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=30, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] fraud flagged order amount=999" in out, f"missing halt line: {out!r}";
    assert "[AUDIT] approved order amount=50" in out, f"missing pre-fraud audit: {out!r}";
    assert "[SKIP] invalid order amount=0" in out, f"missing pre-fraud skip: {out!r}";
    assert "[AUDIT] approved order amount=120" in out, f"missing pre-fraud audit 120: {out!r}";

    # Post-fraud orders must NOT be visited.
    assert "[AUDIT] approved order amount=30" not in out, f"post-fraud order 30 should not be audited: {out!r}";
    assert "amount=30" not in out or "[HALT]" in out and out.find("amount=30") == out.rfind("amount=30"), (
        f"order 30 should never appear after halt: {out!r}"
    );

    assert out.count("[HALT]") == 1, f"expected exactly 1 halt, got {out.count('[HALT]')}: {out!r}";
