"""City itinerary: stations linked to hotels and attractions, shortlist top-rated attractions only."""

node Station {
    has name: str = "";
}

node Hotel {
    has name: str = "";
    has price: int = 0;
}

node Attraction {
    has title: str = "";
    has stars: int = 0;
}

edge LinkedTo {}

walker ItineraryPlanner {
    has final_plan: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Station entry {
        print(f"Arrived at station: {here.name}");
        visit [-->];
    }

    can plan with Attraction entry {
        if here.stars >= 4 {
            self.final_plan.append(f"{here.title} ({here.stars} stars)");
        }
        visit [-->];
    }

    can skip with Hotel entry {
        # Hotels are intentionally ignored: no attractions shortlisted here.
        print(f"  skipping hotel: {here.name}");
        visit [-->];
    }
}

with entry {
    central = Station(name="Central Station");
    north = Station(name="North Station");
    south = Station(name="South Station");

    central +>:LinkedTo:+> Hotel(name="Grand Plaza", price=220);
    central +>:LinkedTo:+> Attraction(title="Old Museum", stars=5);
    central +>:LinkedTo:+> Attraction(title="City Park", stars=3);

    north +>:LinkedTo:+> Hotel(name="Riverside Inn", price=95);
