"""Order audit walk: skip invalid orders, halt on fraud flags."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting order audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud_flag {
            print(f"[HALT] amount={here.amount} fraud flagged — audit stopped");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] amount={here.amount} invalid — continuing");
            } else {
                print(f"[AUDIT] amount={here.amount} approved");
            }
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(amount=49.99)
        ++> Order(amount=12.00, valid=False)
        ++> Order(amount=89.50)
        ++> Order(amount=500.00, fraud_flag=True)
        ++> Order(amount=15.75);
    root spawn OrderAuditor();
}
