"""Tests for OrderAuditor: skip invalid, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

# ---------- 1. Fraud halts the entire walk on the spot ----------
test "fraud flag disengages the walker immediately" {
    root ++> Order(amount=49.99, valid=True)
        ++> Order(amount=12.00, valid=False)
        ++> Order(amount=89.50, valid=True)
        ++> Order(amount=500.00, fraud_flag=True)
        ++> Order(amount=15.75, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    # Trailing order must NOT be reached once fraud fires.
    assert "[AUDIT] amount=15.75 approved" not in out, f"fraud did not halt walk: {out}";
    # The fraud order itself must print the halt line.
    assert "[HALT] amount=500.0 fraud flagged" in out, f"halt line missing: {out}";
    # Header still prints.
    assert "Starting order audit" in out, f"header missing: {out}";
}

# ---------- 2. Invalid orders are skipped, walk continues ----------
test "invalid orders are skipped without halting" {
    root ++> Order(amount=10.00, valid=False)
        ++> Order(amount=20.00, valid=True)
        ++> Order(amount=30.00, valid=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP] amount=10.0 invalid" in out, f"first skip missing: {out}";
    assert "[AUDIT] amount=20.0 approved" in out, f"middle audit missing: {out}";
    assert "[SKIP] amount=30.0 invalid" in out, f"second skip missing: {out}";
    # No halt should have fired.
    assert "[HALT]" not in out, f"unexpected halt in skip-only run: {out}";
}

# ---------- 3. Fraud in position 2 halts before position 3+ ----------
test "fraud mid-walk halts before later valid orders" {
    root ++> Order(amount=1.00, valid=True)
        ++> Order(amount=2.00, fraud_flag=True)
        ++> Order(amount=3.00, valid=True)
        ++> Order(amount=4.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] amount=1.0 approved" in out, f"pre-fraud audit missing: {out}";
    assert "[HALT] amount=2.0 fraud flagged" in out, f"halt line missing: {out}";
    assert "[AUDIT] amount=3.0 approved" not in out, f"walk continued past fraud: {out}";
    assert "[AUDIT] amount=4.0 approved" not in out, f"walk continued past fraud: {out}";
}

# ---------- 4. All-valid, no fraud: every order audited in order ----------
test "all valid orders produce audit lines in traversal order" {
    root ++> Order(amount=5.00, valid=True)
        ++> Order(amount=6.00, valid=True)
        ++> Order(amount=7.00, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] amount=5.0 approved" in out, f"first audit missing: {out}";
    assert "[AUDIT] amount=6.0 approved" in out, f"second audit missing: {out}";
    assert "[AUDIT] amount=7.0 approved" in out, f"third audit missing: {out}";
    assert "[SKIP]" not in out, f"unexpected skip: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";

    # Verify ordering: 5.0 must come before 6.0, which must come before 7.0.
    i5 = out.index("amount=5.0");
    i6 = out.index("amount=6.0");
    i7 = out.index("amount=7.0");
    assert i5 < i6 < i7, f"audit lines out of order: {out}";
}

# ---------- 5. Single fraud-only graph: halt fires on first order ----------
test "fraud on the very first order halts immediately" {
    root ++> Order(amount=999.99, fraud_flag=True, valid=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] amount=999.99 fraud flagged" in out, f"halt missing: {out}";
    # The fraud order must not also produce an AUDIT or SKIP line.
    assert "[AUDIT]" not in out, f"fraud order also audited: {out}";
    assert "[SKIP]" not in out, f"fraud order also skipped: {out}";
}

