"""Multi-depot stock auditor: anchor one combined query from all depots and flag low-stock stores."""

node Store {
    has name: str = "";
    has stock: int = 0;
}

node Depot {
    has name: str = "";
}

walker Auditor {
    has low_stock: list = [];

    can launch with Root entry {
        print(f"Auditing stores reachable from every depot:");
        visit [-->];
    }

    can branch with Depot entry {
        print(f"  - depot {here.name} serving:");
        visit [-->];
    }

    can inspect with Store entry {
        status = "LOW" if here.stock < 20 else "OK ";
        print(f"      [{status}] {here.name} stock={here.stock}");
        if here.stock < 20 {
            self.low_stock.append(here.name);
        }
        visit [-->];
    }
}

with entry {
    d1 = Depot(name="North");
    d2 = Depot(name="South");
    d3 = Depot(name="East");
    root ++> d1 ++> d2 ++> d3;

    d1 ++> Store(name="S-101", stock=45)
        ++> Store(name="S-102", stock=12)
        ++> Store(name="S-103", stock=30);

    d2 ++> Store(name="S-201", stock=8)
        ++> Store(name="S-202", stock=55);

    d3 ++> Store(name="S-301", stock=19)
        ++> Store(name="S-302", stock=100)
        ++> Store(name="S-303", stock=5);

    root spawn Auditor();

    print("Combined query from every depot finished; low-stock stores are now flagged.");
}
