    assert "[SKIP]" not in out, f"no skip on this walk: {out}";
    assert out.count("[HALT]") == 1, f"exactly one halt expected: {out}";
}

test "fraud at first order halts before any audit" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Order(amount=999, valid=True, fraud=True)
            ++> Order(amount=100, valid=True, fraud=False)
            ++> Order(amount=200, valid=True, fraud=False);
        root spawn OrderAuditor();
    }
