    assert "[AUDIT] order amount 200" not in out, f"nothing after first fraud: {out}";
    assert out.count("[HALT]") == 1, f"only one halt: {out}";
    assert out.count("[AUDIT]") == 0, f"no audits when first is fraud: {out}";
}

test "fraud on an invalid order still halts" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> Order(amount=100, valid=True, fraud=False)
            ++> Order(amount=50, valid=False, fraud=True)
            ++> Order(amount=200, valid=True, fraud=False);
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] order amount 100" in out, f"pre-fraud audits: {out}";
    assert "[HALT] fraud flagged on order amount 50" in out, f"fraud wins over invalid: {out}";
    assert "[SKIP] order amount 50" not in out, f"fraud must not be reported as skip: {out}";
    assert "[AUDIT] order amount 200" not in out, f"post-fraud not visited: {out}";
    assert "[SKIP]" not in out, f"fraud suppresses skip: {out}";
    assert out.count("[HALT]") == 1, f"one halt: {out}";
}

