"""Combined depot sweep: anchor one query from every depot at once, reach every store, and flag any store whose stock has dropped below 20 units."""

node Depot {
    has name: str = "";
}

node Store {
    has name: str = "";
    has stock: int = 0;
    has available: bool = True;
}

edge Serves {}

walker Auditor {
    has threshold: int = 20;
    has seen: list[Store] = [];

    can start with Root entry {
        visit [-->];
    }

    can sweep with Depot entry {
        visit [-->];
    }

    can inspect with Store entry {
        flagged = here.stock < self.threshold;
        status = "OK" if here.available and here.stock >= self.threshold else ("LOW" if here.stock < self.threshold else "OUT");
        if flagged {
            print(f"[{status}] {here.name} stock={here.stock} (below {self.threshold})");
        } else {
            print(f"[{status}] {here.name} stock={here.stock}");
        }
        self.seen.append(here);
        visit [-->];
    }
}

with entry {
    depot_a = Depot(name="Depot-A");
    depot_b = Depot(name="Depot-B");

    depot_a +>:Serves:+> Store(name="Store-1", stock=55);
    depot_a +>:Serves:+> Store(name="Store-2", stock=12);
    depot_a +>:Serves:+> Store(name="Store-3", stock=30);

    depot_b +>:Serves:+> Store(name="Store-4", stock=8);
    depot_b +>:Serves:+> Store(name="Store-5", stock=41);
    depot_b +>:Serves:+> Store(name="Store-6", stock=19, available=False);

    root ++> depot_a ++> depot_b;

    auditor = Auditor(threshold=20);
    root spawn auditor;
    print(f"audited {len(auditor.seen)} stores from both depots in one sweep");
}
