"""Order auditor: skip invalid orders, halt the walk on fraud."""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Starting order audit");
        visit [-->];
    }

    can audit with Order entry {
        if here.fraud {
            print(f"[HALT] {here.order_id}: fraud flagged (${here.amount})");
            disengage;
        } else {
            if not here.valid {
                print(f"[SKIP] {here.order_id}: invalid order (${here.amount})");
                visit [-->];
            } else {
                print(f"[AUDIT] {here.order_id}: approved (${here.amount})");
                visit [-->];
            }
        }
    }
}

with entry {
    root ++> Order(order_id="O-100", amount=49.99)
        ++> Order(order_id="O-101", amount=0.0, valid=False)
        ++> Order(order_id="O-102", amount=120.0)
        ++> Order(order_id="O-103", amount=999.0, fraud=True)
        ++> Order(order_id="O-104", amount=25.0);
    root spawn OrderAuditor();
}
```

