"""Tests for OrderAuditor: skip-invalid semantics and fraud disengage."""

import io;
import from contextlib { redirect_stdout }

test "all valid orders print AUDIT and traverse fully" {
    root ++> Order(order_id="A1", amount=10.0)
        ++> Order(order_id="A2", amount=20.0)
        ++> Order(order_id="A3", amount=30.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert out.startswith("Starting order audit\n"), f"missing startup line: {out!r}";
    assert "[AUDIT] A1: approved ($10.0)" in out, f"missing A1 AUDIT: {out!r}";
    assert "[AUDIT] A2: approved ($20.0)" in out, f"missing A2 AUDIT: {out!r}";
    assert "[AUDIT] A3: approved ($30.0)" in out, f"missing A3 AUDIT: {out!r}";
    assert "[SKIP]" not in out, f"unexpected SKIP in all-valid run: {out!r}";
    assert "[HALT]" not in out, f"unexpected HALT in all-valid run: {out!r}";
    # Traversal should have visited all three orders.
    assert res is not None, "spawn returned None";
}

test "invalid order is skipped but audit continues to later valid orders" {
    root ++> Order(order_id="B1", amount=15.0)
        ++> Order(order_id="B2", amount=0.0, valid=False)
        ++> Order(order_id="B3", amount=75.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] B1: approved ($15.0)" in out, f"B1 should audit before skip: {out!r}";
    assert "[SKIP] B2: invalid order ($0.0)" in out, f"B2 invalid must SKIP: {out!r}";
    assert "[AUDIT] B3: approved ($75.0)" in out, f"walk must continue after skip to B3: {out!r}";
    assert "[HALT]" not in out, f"no fraud here, must not HALT: {out!r}";

    # Ordering check: B1 line before B2 line before B3 line.
    i_b1 = out.find("[AUDIT] B1");
    i_b2 = out.find("[SKIP] B2");
    i_b3 = out.find("[AUDIT] B3");
    assert -1 < i_b1 < i_b2 < i_b3, f"wrong traversal order B1< B2< B3: indices {i_b1},{i_b2},{i_b3} in {out!r}";
}

test "fraud order halts the walk — later orders never visited" {
    root ++> Order(order_id="C1", amount=10.0)
        ++> Order(order_id="C2", amount=200.0, fraud=True)
        ++> Order(order_id="C3", amount=300.0)
        ++> Order(order_id="C4", amount=400.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] C1: approved ($10.0)" in out, f"C1 must audit before fraud: {out!r}";
    assert "[HALT] C2: fraud flagged ($200.0)" in out, f"C2 fraud must HALT: {out!r}";
    # disengage means the walk stops on the spot.
    assert "[AUDIT] C3" not in out, f"walk must NOT continue to C3 after disengage: {out!r}";
    assert "[AUDIT] C4" not in out, f"walk must NOT continue to C4 after disengage: {out!r}";
    assert "[SKIP]" not in out, f"no skip expected: {out!r}";

    # HALT line must come after the C1 audit line.
    i_c1 = out.find("[AUDIT] C1");
    i_c2 = out.find("[HALT] C2");
    assert -1 < i_c1 < i_c2, f"C1 AUDIT must precede C2 HALT: {out!r}";
}

test "fraud on first order halts immediately with nothing audited" {
    root ++> Order(order_id="D1", amount=500.0, fraud=True)
        ++> Order(order_id="D2", amount=10.0)
        ++> Order(order_id="D3", amount=20.0, valid=False);

