"""Depot dispatch: walk cargo routes and report which loads qualify for truck dispatch."""

node Depot {
    has name: str = "";
}

node Route {
    has cargo_tonnes: float = 0.0;
    has destination: str = "";
}

edge Serves {
    has leg: str = "";
}

walker Dispatcher {
    has qualified: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can review with Depot entry {
        print(f"Depot {here.name}:");
        visit [-->];
    }

    can check with Route entry {
        can_dispatch = here.cargo_tonnes >= 2.0 and here.cargo_tonnes <= 8.0;
        status = "QUALIFIES" if can_dispatch else "REJECTED";
        print(f"  -> {here.destination}: {here.cargo_tonnes}t [{status}]");
        if can_dispatch {
            self.qualified += 1;
        }
    }
}

with entry {
    depot_north = Depot(name="North");
    depot_south = Depot(name="South");

    root ++> depot_north ++> depot_south;

    depot_north +>:Serves(leg="A"):+> Route(cargo_tonnes=3.5, destination="Brisbane");
    depot_north +>:Serves(leg="B"):+> Route(cargo_tonnes=9.0, destination="Sydney");
    depot_north +>:Serves(leg="C"):+> Route(cargo_tonnes=7.8, destination="Melbourne");

    depot_south +>:Serves(leg="A"):+> Route(cargo_tonnes=1.5, destination="Adelaide");
    depot_south +>:Serves(leg="B"):+> Route(cargo_tonnes=5.0, destination="Canberra");
    depot_south +>:Serves(leg="C"):+> Route(cargo_tonnes=8.0, destination="Perth");

    d = Dispatcher();
    root spawn d;
    print(f"Total routes qualified for dispatch: {d.qualified}/6");
}
