    assert "Robot booting up at the loading dock" in out, f"missing boot line: {out}";
    assert "floor-roll through F1" in out, f"missing F1 step: {out}";
    assert "floor-roll through F2" in out, f"missing F2 step: {out}";
    assert "floor-roll through F3" in out, f"missing F3 step: {out}";
    assert len(res.log) == 3, f"expected 3 log entries, got {len(res.log)}";
    assert res.log[0] == "floor-roll through F1", f"first log wrong: {res.log[0]}";
    assert res.log[1] == "floor-roll through F2", f"second log wrong: {res.log[1]}";
    assert res.log[2] == "floor-roll through F3", f"third log wrong: {res.log[2]}";
}

test "robot logs stair-climb on Stairs cells" {
    root ++> Stairs(label="S1")
        ++> Stairs(label="S2");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Robot();
    }
    out = buf.getvalue();

    assert "Robot booting up at the loading dock" in out, f"missing boot line: {out}";
    assert "stair-climb at S1" in out, f"missing S1 step: {out}";
    assert "stair-climb at S2" in out, f"missing S2 step: {out}";
    assert len(res.log) == 2, f"expected 2 log entries, got {len(res.log)}";
    assert res.log[0] == "stair-climb at S1", f"first log wrong: {res.log[0]}";
    assert res.log[1] == "stair-climb at S2", f"second log wrong: {res.log[1]}";
}

test "robot alternates movement kinds per cell type" {
    root ++> Floor(label="A1")
        ++> Stairs(label="B1")
        ++> Floor(label="C1")
        ++> Stairs(label="D1")
        ++> Floor(label="E1");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Robot();
    }
    out = buf.getvalue();

    expected = [
        "floor-roll through A1",
        "stair-climb at B1",
        "floor-roll through C1",
        "stair-climb at D1",
        "floor-roll through E1",
    ];
    assert len(res.log) == 5, f"expected 5 log entries, got {len(res.log)}";
    for (i, step) in enumerate(expected) {
        assert res.log[i] == step, f"log[{i}] expected {step!r}, got {res.log[i]!r}";
        assert step in out, f"missing step in output: {step} not in {out}";
    }
    # Each floor step uses the 'floor-roll' wording; each stairs step uses 'stair-climb'.
    assert res.log[0].startswith("floor-roll"), f"step 0 not a floor roll: {res.log[0]}";
    assert res.log[1].startswith("stair-climb"), f"step 1 not a stair climb: {res.log[1]}";
    assert res.log[2].startswith("floor-roll"), f"step 2 not a floor roll: {res.log[2]}";
    assert res.log[3].startswith("stair-climb"), f"step 3 not a stair climb: {res.log[3]}";
    assert res.log[4].startswith("floor-roll"), f"step 4 not a floor roll: {res.log[4]}";
}

test "robot builds a per-cell path matching plan length" {
    # The plan has 3 cells; the path log must have exactly 3 entries,
    # in traversal order, each describing the movement kind for that cell.
    root ++> Floor(label="X1")
        ++> Stairs(label="Y1")
        ++> Floor(label="Z1");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Robot();
    }
    out = buf.getvalue();

    # Path equals plan length.
    assert len(res.log) == 3, f"path length {len(res.log)} != plan length 3: log={res.log}";

    # Path order matches linked order: X1 -> Y1 -> Z1.
    assert res.log[0].endswith("X1"), f"path[0] should be X1 cell, got {res.log[0]}";
    assert res.log[1].endswith("Y1"), f"path[1] should be Y1 cell, got {res.log[1]}";
    assert res.log[2].endswith("Z1"), f"path[2] should be Z1 cell, got {res.log[2]}";

    # Each step's wording matches the node's allowed movement kind.
    assert "floor-roll" in res.log[0], f"Floor X1 should be floor-roll: {res.log[0]}";
    assert "stair-climb" in res.log[1], f"Stairs Y1 should be stair-climb: {res.log[1]}";
    assert "floor-roll" in res.log[2], f"Floor Z1 should be floor-roll: {res.log[2]}";

    # The same set of strings must appear in the printed output (robot logs path).
    assert "floor-roll through X1" in out, f"missing X1 in stdout: {out}";
    assert "stair-climb at Y1" in out, f"missing Y1 in stdout: {out}";
    assert "floor-roll through Z1" in out, f"missing Z1 in stdout: {out}";
}

