```jac
"""Warehouse robot: per-cell route plan with allowed movement kind."""

node Cell {
    has title: str = "";
    has row: int = 0;
    has col: int = 0;
    # Allowed movement out of this cell: "floor" or "stairs"
    has allowed_kind: str = "floor";
    has visited: bool = False;
}

walker RoutePlanner {
    has path_log: list[str] = [];
    has max_steps: int = 20;

    can start with Root entry {
        print("Robot booting up at the dock");
        visit [-->] else { disengage; }
    }

    can inspect with Cell entry {
        if here.visited {
            print(f"[BLOCKED] already at {here.title}, would cycle");
            disengage;
        }
        here.visited = True;
        self.path_log.append(f"{here.title}({here.row},{here.col})");
        print(f"At {here.title} row={here.row} col={here.col} kind={here.allowed_kind}");

        if len(self.path_log) >= self.max_steps {
            print("[STOP] max steps reached");
            disengage;
        }

        if here.allowed_kind == "floor" {
            visit [-->] else { disengage; }
        } elif here.allowed_kind == "stairs" {
            visit [-->] else { disengage; }
        } else {
            print(f"[STOP] unknown kind {here.allowed_kind}");
            disengage;
        }
    }
}

with entry {
    root ++> Cell(title="Dock", row=0, col=0, allowed_kind="floor")
        ++> Cell(title="Aisle-1", row=0, col=1, allowed_kind="floor")
        ++> Cell(title="Stair-Base", row=0, col=2, allowed_kind="stairs")
        ++> Cell(title="Mezz-North", row=1, col=2, allowed_kind="floor")
        ++> Cell(title="Mezz-South", row=1, col=3, allowed_kind="floor")
        ++> Cell(title="Pack-Zone", row=1, col=4, allowed_kind="stairs");

    planner = RoutePlanner();
    root spawn planner;

    print(f"\nFull path: {planner.path_log}");
    print(f"Cells traversed: {len(planner.path_log)}");
}
