"""Warehouse stock take: model stock items as nodes and sweep shelves with a counter walker."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    can start with Root entry {
        visit [-->];
    }

    can tally with StockItem entry {
        report here;
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> StockItem(sku="A-100", quantity=24)
        ++> StockItem(sku="B-200", quantity=7)
        ++> StockItem(sku="C-300", quantity=15);

    result = root spawn Counter();

    total = 0;
    min_qty = 0;
    for (i, item) in enumerate(result.reports) {
        print(f"{item.sku}: {item.quantity} units on shelf");
        total += item.quantity;
        if i == 0 {
            min_qty = item.quantity;
        } elif item.quantity < min_qty {
            min_qty = item.quantity;
        }
    }
    print(f"total units in warehouse: {total}");
    print(f"smallest shelf count: {min_qty}");
}
