"""Restaurant recommender: walk eateries and filter by a spawn-time minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker Finder {
    has min_rating: float = 0.0;
    has pass_label: str = "";

    can start with Root entry {
        print("--- " + self.pass_label + " (rating >= " + str(self.min_rating) + ") ---");
        visit [-->];
    }

    can recommend with Restaurant entry {
        if here.rating >= self.min_rating {
            print(f"  {here.name} — {here.cuisine} ({here.rating})");
        }
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Jardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Mario's", cuisine="Italian", rating=4.2)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Quick Bites", cuisine="Burgers", rating=3.4)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.7);

    root spawn Finder(min_rating=4.5, pass_label="Date night");
    root spawn Finder(min_rating=3.5, pass_label="Casual lunch");
}
