"""Restaurant recommender: walk the dining graph and filter by minimum rating."""

node Restaurant {
    has name: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;

    def print_if_meets(min_rating: float) {
        if self.rating >= min_rating {
            print(f"  [{self.rating}] {self.name} ({self.cuisine})");
        }
    }
}

walker Finder {
    has min_rating: float = 0.0;
    has occasion_label: str = "";

    can start with Root entry {
        print(f"--- {self.occasion_label} (min rating {self.min_rating}+) ---");
        visit [-->];
    }

    can inspect with Restaurant entry {
        here.print_if_meets(self.min_rating);
        visit [-->];
    }
}

with entry {
    root ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Joe's Pizza", cuisine="Italian", rating=3.7)
        ++> Restaurant(name="Nobu", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="The Diner", cuisine="American", rating=3.2);

    root spawn Finder(min_rating=4.5, occasion_label="date night");
    root spawn Finder(min_rating=3.5, occasion_label="casual lunch");
}
