"""Tests for contact tracing: wave-by-wave BFS outbreak spread."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the contact network from the demo graph.
def build_network() -> tuple {
    p0 = Person(name="Alice");
    p1 = Person(name="Bob");
    p2 = Person(name="Cleo");
    p3 = Person(name="Diego");
    p4 = Person(name="Esha");
    p5 = Person(name="Finn");
    p6 = Person(name="Gita");
    p7 = Person(name="Hugo");

    p0 +>:Contact(strength="household"):+> p1;
    p0 +>:Contact(strength="work"):+> p2;
    p0 +>:Contact(strength="work"):+> p3;
    p1 +>:Contact(strength="household"):+> p4;
    p2 +>:Contact(strength="gym"):+> p5;
    p3 +>:Contact(strength="cafe"):+> p6;
    p4 +>:Contact(strength="neighbor"):+> p7;
    p6 +>:Contact(strength="neighbor"):+> p7;

    root ++> p0;
    return (p0, p1, p2, p3, p4, p5, p6, p7);
}

test "patient zero is marked infected at wave 0" {
    (p0, p1, p2, p3, p4, p5, p6, p7) = build_network();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tracer();
    }
    out = buf.getvalue();
    assert p0.infected == True, f"Alice must be infected, got {p0.infected}";
    assert p0.wave == 0, f"Alice wave must be 0, got {p0.wave}";
    assert "Wave 0 -> patient zero: Alice" in out, f"missing seed line: {out}";
}

test "wave ordering is breadth-first" {
    (p0, p1, p2, p3, p4, p5, p6, p7) = build_network();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Tracer();
    }
    out = buf.getvalue();
    lines = [l for l in out.split("\n") if l];
    # Wave 1 = Alice's contacts (Bob, Cleo, Diego)
    wave1 = [l for l in lines if l.startswith("Wave 1 ->")];
    assert len(wave1) == 3, f"Wave 1 should have 3 lines, got {len(wave1)}: {wave1}";
