"""Warehouse robot route planner.

Each warehouse cell carries a movement directive (floor or stairs) that
the robot must obey. The robot walks the layout as a walker, logging
only the movement kind it actually used at each cell.
"""

node Cell {
    has label: str = "";
    has movement: str = "floor";
}

edge Next {}

walker Robot {
    has path_log: list[str] = [];

    can start with Root entry {
        print("Robot booting up at dispatch");
        visit [-->];
    }

    can roll with Cell entry {
        kind = here.movement;
        self.path_log.append(kind);
        print(f"[{kind.upper()}] {here.label}");
        visit [-->] else { disengage; };
    }
}

with entry {
    bay_a = Cell(label="Bay-A", movement="floor");
    bay_b = Cell(label="Bay-B", movement="floor");
    stairs_up = Cell(label="Stairs-Up", movement="stairs");
    mezzanine = Cell(label="Mezzanine", movement="floor");
    bay_c = Cell(label="Bay-C", movement="floor");

    root ++> bay_a ++> bay_b ++> stairs_up ++> mezzanine ++> bay_c;

    bot = Robot();
    root spawn bot;
    print(f"Path log: {bot.path_log}");
}
