    linker = root ++> Task(title="linker", minutes=8);
    codegen = root ++> Task(title="codegen", minutes=12);
    compiler = root ++> Task(title="compiler", minutes=15, available=False);

    shared_lib ++> parser;
    shared_lib ++> linker;
    parser ++> codegen;
    linker ++> codegen;
    codegen ++> compiler;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = Auditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[OK] shared-lib: 5 min" in out, f"missing shared-lib line: {out}";
    assert "[OK] parser: 10 min" in out, f"missing parser line: {out}";
    assert "[OK] linker: 8 min" in out, f"missing linker line: {out}";
    assert "[OK] codegen: 12 min" in out, f"missing codegen line: {out}";
    assert "[BLOCKED] compiler: 15 min" in out, f"missing compiler line: {out}";
    # 5 + 10 + 8 + 12 + 15 = 50, NOT 50 + duplicates from diamond convergence
    assert auditor.total_minutes == 50, f"diamond double-counted: got {auditor.total_minutes}, want 50";
    assert len(auditor.visited_titles) == 5, f"visited count off: {auditor.visited_titles}";
}

test "unavailable task is marked BLOCKED but still counted once" {
    a = root ++> Task(title="alpha", minutes=4, available=False);
    b = a ++> Task(title="beta", minutes=6, available=False);
    # diamond convergence: two parents both point to the same leaf
    c1 = b ++> Task(title="gamma", minutes=7, available=False);
    c2 = b ++> Task(title="gamma", minutes=7, available=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = Auditor();
        root spawn auditor;
    }
    out = buf.getvalue();

