"""Build system dependency auditor.

Walks a diamond-shaped dependency graph and counts build minutes,
ensuring tasks reachable by multiple paths are audited exactly once.
"""

node BuildTask {
    has title: str = "";
    has minutes: int = 0;
}

walker Auditor {
    has visited: list[str] = [];
    has total_minutes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with BuildTask entry {
        already_seen = False;
        for v in self.visited {
            if v == here.title {
                already_seen = True;
            }
        }
        if not already_seen {
            self.visited.append(here.title);
            self.total_minutes = self.total_minutes + here.minutes;
