    core ++> app;
    core ++> cli;
    app ++> pkg;
    app ++> lib;
    cli ++> pkg;
    cli ++> lib;
    pkg ++> leaf;
    lib ++> leaf;

    (out, auditor) = run_auditor(root);
    # 2+3+4+5+6+7 = 27
    assert auditor.total_minutes == 27,
