"""Warehouse inventory audit: assign stable unique ids, persist each item during the walk, and dump the graph."""

import uuid;

node Item {
    has name: str = "";
    has sku: str = "";
    has qty: int = 0;
    has uid: str = "";
    has persisted: bool = False;
}

node Shelf {
    has label: str = "";
}

walker WarehouseAuditor {
    has audit_log: list = [];

    can start with Root entry {
        print("[AUDIT] beginning warehouse walk");
        visit [-->];
    }

    can traverse_aisle with Shelf entry {
        print(f"[AISLE] entering shelf {here.label}");
        visit [-->];
    }

    can record_item with Item entry {
        here.uid = str(uuid.uuid4());
        here.persisted = True;
        self.audit_log.append(here.name);
        print(f"[PERSIST] {here.name} (sku={here.sku}, qty={here.qty}) -> storage uid={here.uid}");
    }
}

walker DumpGraph {
    has depth: int = 0;

    can show_root with Root entry {
        print("ROOT");
        visit [-->];
    }

    can show_shelf with Shelf entry {
        pad = "  " * self.depth;
        print(f"{pad}- Shelf: {here.label}");
        visit [-->];
    }

    can show_item with Item entry {
        pad = "  " * self.depth;
        print(f"{pad}* Item: {here.name} (uid={here.uid}, persisted={here.persisted})");
    }
}

with entry {
    a1 = Shelf(label="A1");
    a2 = Shelf(label="A2");
    root ++> a1 ++> a2;

    a1 ++> Item(name="Drill", sku="DRL-001", qty=12)
         ++> Item(name="Hammer", sku="HMR-002", qty=30);

    a2 ++> Item(name="Saw", sku="SAW-003", qty=7)
         ++> Item(name="Wrench", sku="WRN-004", qty=22)
         ++> Item(name="Pliers", sku="PLR-005", qty=18);

    auditor = WarehouseAuditor();
    root spawn auditor;
    print(f"Audit complete: persisted {len(auditor.audit_log)} items");

    print("\n--- Graph dump ---");
    root spawn DumpGraph(depth=1);
}
