"""Build dependency audit: count total build minutes across a diamond-shaped task graph, auditing each task exactly once even when traversal reaches it via multiple paths."""

node Task {
    has title: str = "";
    has minutes: int = 0;
    has available: bool = True;
}

walker BuildAuditor {
    has audited: list[str] = [];

    can start with Root entry {
        print("Starting build audit from root...");
        visit [-->];
    }

    can audit with Task entry {
        already = here.title in self.audited;
        label = "SKIP (already audited)" if already else "AUDIT";
        print(f"[{label}] {here.title} ({here.minutes} min)");
        if not already {
            self.audited.append(here.title);
        }
        visit [-->];
    }
}

with entry {
    # Diamond shape:
    #   Task A (foundation)
    #     /        \
    #   Task B    Task C     <- both depend on A (the shared library)
    #     \        /
    #      Task D            <- merge point: would be reached twice without dedup
    #        \
    #         Task E
    a = Task(title="FoundationLib", minutes=10);
    b = Task(title="ModuleB", minutes=20);
    c = Task(title="ModuleC", minutes=15);
    d = Task(title="IntegrationD", minutes=30);
    e = Task(title="FinalBuildE", minutes=25);

    root ++> a ++> b ++> d ++> e;
    root ++> a ++> c ++> d;

    auditor = BuildAuditor();
    root spawn auditor;

    total = 10 + 20 + 15 + 30 + 25;
    print(f"Unique tasks audited: {auditor.audited}");
    print(f"Total build minutes: {total}");
}
