"""Tests for the diamond dependency audit walker."""

import io;
import from contextlib { redirect_stdout }

# Helper to build the standard diamond graph and run Auditor, returning captured stdout.
def run_audit {
    compile = Task(title="compile", minutes=10);
    link_tests = Task(title="link_tests", minutes=5);
    link_app = Task(title="link_app", minutes=5);
    bundle_lib = Task(title="bundle_lib", minutes=3);

    root ++> compile ++> link_tests;
    root ++> link_tests ++> bundle_lib;
    root ++> link_app;
    root ++> link_app ++> bundle_lib;

    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    return (buf.getvalue(), auditor, res);
}

test "diamond deduplicates shared library minutes" {
    (out, auditor, res) = run_audit();

    # Expected unique audit minutes: 10 + 5 + 5 + 3 = 23 (no double-counting of bundle_lib).
    assert auditor.total_minutes == 23, f"expected 23 total minutes, got {auditor.total_minutes}";
    # The walker still reports a single visit order list with no duplicates.
    assert len(auditor.visited_titles) == 4, f"expected 4 unique audits, got {auditor.visited_titles}";
    # bundle_lib must appear exactly once in the visit list.
    assert auditor.visited_titles.count("bundle_lib") == 1, f"bundle_lib double-counted: {auditor.visited_titles}";
}

test "shared node is marked audited only once but skip message may appear" {
    (out, auditor, res) = run_audit();

    # Exactly one bundle_lib audit message should appear (the first visit).
    bundle_lib_audited = out.count("Audited 'bundle_lib' (+3 min)");
    bundle_lib_skipped = out.count("Skipped 'bundle_lib' (already counted)");
    assert bundle_lib_audited == 1, f"bundle_lib should be audited once, got {bundle_lib_audited} (full out: {out!r})";
    # And it must be skipped on at least one subsequent arrival.
    assert bundle_lib_skipped >= 1, f"bundle_lib should be skipped on re-visit, got {bundle_lib_skipped} (full out: {out!r})";

    # Every Task reachable from root must end up flagged audited == True.
    seen: list = [root -->];
    i = 0;
    while i < len(seen) {
        n = seen[i];
        if n not in seen[i + 1:] {
            for (j, m) in enumerate(seen) {
                if j == i { continue; }
            }
        }
        for child in [n -->] {
            if child not in seen {
                seen = seen + [child];
            }
        }
        i = i + 1;
    }
    for n in seen {
        assert isinstance(n, Task), "unexpected non-Task node reachable from root";
        assert bool(n.audited) is True, f"task '{n.title}' not flagged audited";
    }
}

test "auditor reports each unique task in order" {
    (out, auditor, res) = run_audit();

    # The order of first audits must list each task exactly once.
    expected_order = ["compile", "link_tests", "link_app", "bundle_lib"];
    assert auditor.visited_titles == expected_order, f"unexpected visit order: {auditor.visited_titles}";

    # Output should contain an audit line for every task at least once.
    for t in expected_order {
        assert f"Audited '{t}' (" in out, f"missing audit line for '{t}' in output: {out!r}";
    }
}

test "linear chain has no skipped audits and sums correctly" {
    # Build a strictly linear chain: root -> a -> b -> c. No diamond, so no skips.
    a = Task(title="a", minutes=2);
    b = Task(title="b", minutes=4);
    c = Task(title="c", minutes=6);
    root ++> a ++> b ++> c;

    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.total_minutes == 12, f"expected 12 minutes, got {auditor.total_minutes}";
    assert len(auditor.visited_titles) == 3, f"expected 3 visits, got {auditor.visited_titles}";
    assert "Skipped" not in out, f"no skip messages expected on linear graph, got: {out!r}";
}

