"""Build system dependency graph: audit tasks exactly once even if reachable by many paths.

Models build tasks as nodes connected by a typed ``DependsOn`` edge (carrying
the per-edge build-minute cost). The ``BuildAuditor`` walker traverses the
dependency graph, accumulating each task's minutes on first encounter and
ignoring repeats. The explicit visited guard replaces what would otherwise
be a memo cache around a manual recursion.
"""

node Task {
    has title: str = "";
    has minutes: int = 0;
}

edge DependsOn {
    has minutes: int = 0;
}

walker BuildAuditor {
    has visited: list[str] = [];
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        if here.title in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.title);
            self.total += here.minutes;
            print(f"audited {here.title} ({here.minutes} min) — running total {self.total} min");
            visit [-->];
        }
    }
}

with entry {
    # Diamond: core_lib is needed by both ui_module and api_module;
    # both of those feed into app_bin. core_lib must be audited once.
    core_lib = Task(title="core_lib", minutes=5);
    ui_module = Task(title="ui_module", minutes=8);
    api_module = Task(title="api_module", minutes=12);
    db_driver = Task(title="db_driver", minutes=3);
    app_bin = Task(title="app_bin", minutes=2);

    root ++> core_lib;
    root ++> db_driver;
    core_lib ++> ui_module;
    core_lib ++> api_module;
    db_driver ++> api_module;
    ui_module ++> app_bin;
    api_module ++> app_bin;

    auditor = BuildAuditor();
    root spawn auditor;

    print(f"TOTAL BUILD MINUTES: {auditor.total}");
}
```

jac_tests:
"""Test annex for BuildAuditor dependency-graph walker."""

import io;
import from contextlib { redirect_stdout }

test "diamond counts shared node exactly once" {
    # Diamond: core_lib -> ui_module, core_lib -> api_module,
    # ui_module -> app_bin, api_module -> app_bin.
    # core_lib is reachable by two paths; must still be audited once.
    core_lib = Task(title="core_lib", minutes=5);
    ui_module = Task(title="ui_module", minutes=8);
    api_module = Task(title="api_module", minutes=12);
    app_bin = Task(title="app_bin", minutes=2);

    root ++> core_lib;
    core_lib ++> ui_module;
    core_lib ++> api_module;
    ui_module ++> app_bin;
    api_module ++> app_bin;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    # 5 + 8 + 12 + 2 = 27 (no double-count of core_lib or any other).
    assert res.total == 27, f"expected 27 total minutes, got {res.total}";
    assert len(res.visited) == 4, f"expected 4 distinct nodes visited, got {len(res.visited)} ({res.visited})";
    # core_lib audited exactly once.
    assert res.visited.count("core_lib") == 1, f"core_lib visited {res.visited.count('core_lib')} times";
    # Each node printed exactly one audit line.
    assert out.count("audited core_lib") == 1, f"core_lib audited line count: {out.count('audited core_lib')}";
    assert out.count("audited ui_module") == 1, f"ui_module audited line count: {out.count('audited ui_module')}";
    assert out.count("audited api_module") == 1, f"api_module audited line count: {out.count('audited api_module')}";
    assert out.count("audited app_bin") == 1, f"app_bin audited line count: {out.count('audited app_bin')}";
}

test "two converging paths into one node" {
    # A -> B, A -> C, B -> D, C -> D. D reachable twice; audit once.
    a = Task(title="A", minutes=10);
    b = Task(title="B", minutes=20);
    c = Task(title="C", minutes=30);
    d = Task(title="D", minutes=40);

    root ++> a;
    a ++> b;
    a ++> c;
    b ++> d;
    c ++> d;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    # 10 + 20 + 30 + 40 = 100
    assert res.total == 100, f"expected 100 total minutes, got {res.total}";
    assert len(res.visited) == 4, f"expected 4 distinct nodes visited, got {len(res.visited)}";
    assert res.visited.count("D") == 1, f"D visited {res.visited.count('D')} times";
    assert out.count("audited D") == 1, f"D audited line count: {out.count('audited D')}";
}

test "shared upstream shared by three converging paths" {
    # root -> X, X -> a, X -> b, X -> c; a, b, c all converge into sink.
    # Sink reachable three times; audit once.
    x = Task(title="X", minutes=1);
    a = Task(title="A", minutes=2);
    b = Task(title="B", minutes=3);
    c = Task(title="C", minutes=4);
    sink = Task(title="sink", minutes=50);

    root ++> x;
    x ++> a;
    x ++> b;
    x ++> c;
    a ++> sink;
    b ++> sink;
    c ++> sink;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }

    # 1 + 2 + 3 + 4 + 50 = 60
    assert res.total == 60, f"expected 60 total minutes, got {res.total}";
    assert res.visited.count("sink") == 1, f"sink visited {res.visited.count('sink')} times";
    assert len(res.visited) == 5, f"expected 5 distinct nodes visited, got {len(res.visited)}";
}

test "linear chain visits each node once" {
    # root -> A -> B -> C. No diamonds; each visited exactly once.
    a = Task(title="A", minutes=7);
    b = Task(title="B", minutes=11);
    c = Task(title="C", minutes=13);

    root ++> a;
    a ++> b;
    b ++> c;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    assert res.total == 7 + 11 + 13, f"expected 31 total minutes, got {res.total}";
    assert res.visited == ["A", "B", "C"], f"unexpected visit order: {res.visited}";
    assert out.count("audited A") == 1, f"A audit line count: {out.count('audited A')}";
    assert out.count("audited B") == 1, f"B audit line count: {out.count('audited B')}";
    assert out.count("audited C") == 1, f"C audit line count: {out.count('audited C')}";
}

test "running total increases monotonically and matches final sum" {
    # Two parallel subtrees under root, both feeding into tail.
    # tail reachable twice; final total must be sum of distinct nodes only.
    left1 = Task(title="left1", minutes=2);
    left2 = Task(title="left2", minutes=4);
    right1 = Task(title="right1", minutes=6);
    right2 = Task(title="right2", minutes=8);
    tail = Task(title="tail", minutes=100);

    root ++> left1;
    root ++> right1;
    left1 ++> left2;
    right1 ++> right2;
    left2 ++> tail;
    right2 ++> tail;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = root spawn BuildAuditor();
    }
    out = buf.getvalue();

    # 2 + 4 + 6 + 8 + 100 = 120 (tail not double-counted).
    assert res.total == 120, f"expected 120 total minutes, got {res.total}";
    assert res.visited.count("tail") == 1, f"tail visited {res.visited.count('tail')} times";

    # Sanity-check the printed running totals are monotonically increasing
    # and the last one equals the final total.
    lines = [ln for ln in out.splitlines() if ln.startswith("audited ")];
    totals: list[int] = [];
    for ln in lines {
        # Format: "audited <title> (<n> min) — running total <m> min"
        parts = ln.split("running total ");
        tail_part = parts[1];
        num_str = tail_part.split(" min")[0];
        totals.append(int(num_str));
    }
    for i in range(1, len(totals)) {
        assert totals[i] > totals[i - 1], f"running total not increasing: {totals}";
    }
    assert totals[-1] == res.total, f"final printed total {totals[-1]} != walker total {res.total}";
}

