"""Metro line: platform and four stations linked by Track edges with travel minutes."""

node Platform {
    has name: str = "";
    has stop_number: int = 0;
}

node Station {
    has name: str = "";
    has stop_number: int = 0;
}

edge Track {
    has minutes: int = 0;
}

walker Rider {
    can start with Root entry {
        visit [-->];
    }

    can arrive with Platform | Station entry {
        print(f"Stop {here.stop_number}: {here.name}");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Platform(name="Central Platform", stop_number=1)
        +>:Track(minutes=3):+> Station(name="Oak Park", stop_number=2)
        +>:Track(minutes=5):+> Station(name="Riverbend", stop_number=3)
        +>:Track(minutes=4):+> Station(name="Harbor View", stop_number=4)
        +>:Track(minutes=6):+> Station(name="Terminal Heights", stop_number=5);
    root spawn Rider();
}
```

jac_tests:
import io;
import from contextlib { redirect_stdout }

test "rider prints every stop in order" {
    root ++> Platform(name="Central Platform", stop_number=1)
        +>:Track(minutes=3):+> Station(name="Oak Park", stop_number=2)
        +>:Track(minutes=5):+> Station(name="Riverbend", stop_number=3)
        +>:Track(minutes=4):+> Station(name="Harbor View", stop_number=4)
        +>:Track(minutes=6):+> Station(name="Terminal Heights", stop_number=5);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Rider();
    }
    out = buf.getvalue();

    expected = "Stop 1: Central Platform\nStop 2: Oak Park\nStop 3: Riverbend\nStop 4: Harbor View\nStop 5: Terminal Heights\n";
    assert out == expected, f"got {out}";
}

test "metro chain has directed tracks with travel minutes" {
    platform = Platform(name="Central Platform", stop_number=1);
    oak = Station(name="Oak Park", stop_number=2);
    riverbend = Station(name="Riverbend", stop_number=3);
    harbor = Station(name="Harbor View", stop_number=4);
    terminal = Station(name="Terminal Heights", stop_number=5);

    root ++> platform
        +>:Track(minutes=3):+> oak
        +>:Track(minutes=5):+> riverbend
        +>:Track(minutes=4):+> harbor
        +>:Track(minutes=6):+> terminal;

    assert len([root -->]) == 1, f"got {len([root -->])} root children";
    assert platform in [root -->], "platform is not linked from root";
    assert oak in [platform ->:Track:->], "oak is not after platform";
    assert riverbend in [oak ->:Track:->], "riverbend is not after oak";
    assert harbor in [riverbend ->:Track:->], "harbor is not after riverbend";
    assert terminal in [harbor ->:Track:->], "terminal is not after harbor";
    assert len([terminal -->]) == 0, f"terminal has outgoing nodes";

    platform_tracks = [edge platform ->:Track:->];
    oak_tracks = [edge oak ->:Track:->];
    riverbend_tracks = [edge riverbend ->:Track:->];
    harbor_tracks = [edge harbor ->:Track:->];

    assert len(platform_tracks) == 1, f"got {len(platform_tracks)} platform tracks";
    assert len(oak_tracks) == 1, f"got {len(oak_tracks)} oak tracks";
    assert len(riverbend_tracks) == 1, f"got {len(riverbend_tracks)} riverbend tracks";
