"""Online store checkout: product archetypes and a checkout walker.

The cart holds a heterogeneous mix of products (paper books, digital books,
electronics, clothing). Each product type carries its own shipping and
handling rule. A single ``Checkout`` walker traverses the cart and reacts to
each product's concrete type using union triggers on a base ``Product`` node.
The walker accumulates a typed receipt report and prints an itemized bill.
"""

node Product {
    has name: str = "";
    has price: float = 0.0;

    def shipping_cost() -> float {
        return 0.0;
    }

    def handling_cost() -> float {
        return 0.0;
    }
}

node PaperBook(Product) {
    has weight_lb: float = 1.0;
    has stock: int = 5;

    override def shipping_cost() -> float {
        return 3.50 + 1.25 * self.weight_lb;
    }

    override def handling_cost() -> float {
        return 1.00;
    }
}

node DigitalBook(Product) {
    has file_format: str = "EPUB";
    has stock: int = 999;

    override def shipping_cost() -> float {
        return 0.0;
    }

    override def handling_cost() -> float {
        return 0.25;
    }
}

node Electronics(Product) {
    has warranty_months: int = 12;
    has stock: int = 3;

    override def shipping_cost() -> float {
        return 7.95;
    }

    override def handling_cost() -> float {
        return 4.50 + 0.50 * float(self.warranty_months);
    }
}

node Clothing(Product) {
    has size: str = "M";
    has stock: int = 10;

    override def shipping_cost() -> float {
        return 5.25;
    }

    override def handling_cost() -> float {
        return 1.75;
    }
