        DigitalBook(name="Dig", price=5.00),
        Electronics(name="Gadget", price=100.00, warranty_months=12),
        Clothing(name="Shirt", price=25.00),
    ];
    r = run_checkout(items);

    expected_subtotal = 10.00 + 5.00 + 100.00 + 25.00;
    # PaperBook: 3.50 + 1.25*1.0 = 4.75 ; Digital: 0 ; Electronics: 7.95 ; Clothing: 5.25
    expected_ship = 4.75 + 0.0 + 7.95 + 5.25;
