    assert inspector.rejected_external == 1, f"got {inspector.rejected_external}";
    assert inspector.accepted == [], f"got {inspector.accepted}";
    assert inspector.rejected_traversal == 0, f"got {inspector.rejected_traversal}";
    assert inspector.rejected_cycle == 0, f"got {inspector.rejected_cycle}";
}

test "traversal escape attempts are rejected" {
    rt = Root();

    document = Part(part_name="word/document.xml", content_kind="xml",
                    content="<doc>hi</doc>");
