    assert "[REJECT traversal]" in out, f"expected traversal marker: {out}";
    assert inspector.rejected_traversal == 1, f"got {inspector.rejected_traversal}";
    assert "../../etc/passwd" in out, f"missing backdoor path in output: {out}";
    assert inspector.accepted == [], f"got {inspector.accepted}";
    assert inspector.rejected_external == 0, f"got {inspector.rejected_external}";
    assert inspector.rejected_cycle == 0, f"got {inspector.rejected_cycle}";
}

test "duplicate rel_id cycles are bounded and parts marked visited" {
    rt = Root();

    document = Part(part_name="word/document.xml", content_kind="xml",
                    content="<doc>hi</doc>");
    styles = Part(part_name="word/styles.xml", content_kind="xml",
                  content="<styles/>");
