    sess +>:OwnsTranscript(role="canonical"):+> TranscriptEntry(
        entry_id="e1", parent_id="root", kind="message"
    );
    [sess ->:OwnsTranscript:->][0] +>:ScopedTo(branch_id="br-1"):+> art;

    auditor = LifecycleAuditor();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }
    out = buf.getvalue();
    assert "wf-u1" not in res.replayable, f"uncached must not be replayable, got {res.replayable}";
    assert "wf-u1" not in res.forbidden, f"uncached readonly must not be forbidden, got {res.forbidden}";
    assert "[reexec] artifact wf-u1 has no cached result; must re-execute" in out, f"missing reexec marker: {out}";
}

test "transcript cycle halts descent without revisiting" {
    buf = io.StringIO();
    rt = root ++> Session(session_id="sess-c1", leaf_entry_id="e2");
    sess = [root -->][0];
    e1 = TranscriptEntry(entry_id="e1", parent_id="root", kind="message");
