"""WRC ↔ HCC no-op write-storm model.

Models the scenario from issue #460: a workflow-recipe controller (WRC)
reconciles shared resources unconditionally, hashing them to detect changes.
The hash gate is wired on one path but missing on the adjacent path in the
same module, so an idempotency guard on McpServer writes exists while
Context writes still churn every loop. A reconciler walker demonstrates the
two write paths; an auditor walker exposes the missed gate by inspecting
which writes carry a hash check.
"""

# ---------- Domain nodes ----------

node Resource {
    has name: str = "";
    has generation: int = 0;
    has resource_version: int = 0;
    has spec_hash: str = "";
    has writes: int = 0;
}

node McpServer(Resource) {
    has kind: str = "McpServer";
}

node Context(Resource) {
    has kind: str = "Context";
}

node NetworkPolicy(Resource) {
    has kind: str = "NetworkPolicy";
}

node Recipe {
    has name: str = "";
    has desired_hash: str = "";
}

# ---------- Typed edges ----------

edge Owns {
    has since: str = "";
}

edge Drives {
    has via: str = "";
}

# ---------- Walkers ----------

walker Reconcile {
    has recipe_name: str;
    has desired_hash: str;

    can start with Root entry {
        print(f"WRC reconcile tick for {self.recipe_name} (hash={self.desired_hash})");
        visit [-->];
    }

    can plan with Recipe entry {
        # Carry the desired hash forward by stashing on self so write
        # abilities can compare without re-resolving the recipe node.
        print(f"  planning recipe {here.name}");
        visit [-->];
    }

    can write_mcpserver with McpServer entry {
        # FIXED path: idempotency gate via specHashUnchanged is wired here.
        guard = "SKIP" if here.spec_hash == self.desired_hash else "WRITE";
        if guard == "SKIP" {
            print(f"  [McpServer/{here.name}] specHashUnchanged -> SKIP write");
        } else {
            here.writes += 1;
            here.generation += 1;
            here.resource_version += 1;
            here.spec_hash = self.desired_hash;
            print(f"  [McpServer/{here.name}] WRITE gen={here.generation} rv={here.resource_version}");
        }
        visit [-->];
    }

    can write_context with Context entry {
        # BUGGY path: gate exists in the same module but was never wired here,
        # so the unconditional replace keeps bumping resourceVersion every tick.
        here.writes += 1;
        here.generation += 1;
        here.resource_version += 1;
        here.spec_hash = self.desired_hash;
        print(f"  [Context/{here.name}] UNCONDITIONAL WRITE gen={here.generation} rv={here.resource_version}");
        visit [-->];
    }

    can write_networkpolicy with NetworkPolicy entry {
        # Downstream effect: HCC watches Context rv bumps and rewrites NPs.
        here.writes += 1;
        here.generation += 1;
        here.resource_version += 1;
        print(f"  [NetworkPolicy/{here.name}] HCC recompute (no-op write storm) gen={here.generation}");
        visit [-->];
    }
}

walker OrderAuditor {
    has report: list = [];

    can start with Root entry {
        print("Auditor: scanning resource write counts across the graph");
        visit [-->];
    }

    can count with McpServer | Context | NetworkPolicy entry {
        self.report.append((here.kind, here.name, here.writes, here.generation));
        print(f"  audit {here.kind}/{here.name}: writes={here.writes} gen={here.generation}");
    }
}

# ---------- Demo wiring ----------

with entry {
    helpdesk = Recipe(name="recipe-helpdesk-v1-0-0", desired_hash="h-helpdesk-001");
    brain = Recipe(name="recipe-evenfire-dev-brain-plugin-v0-1-5", desired_hash="h-brain-001");
    vul = Recipe(name="evenfire-vulnerability-plugin", desired_hash="h-vul-001");
    work = Recipe(name="recipe-evenfire-worktracker-v1-1-0", desired_hash="h-work-001");
    root ++> helpdesk ++> brain ++> vul ++> work;

    shared_ctx = Context(name="shared-context-1");
    root +>:Owns(since="2026-08-26"):+> shared_ctx;

    mcp_a = McpServer(name="recipe-helpdesk-mcp");
    mcp_b = McpServer(name="recipe-worktracker-mcp");
    shared_ctx +>:Drives(via="mcp"):+> mcp_a;
    shared_ctx +>:Drives(via="mcp"):+> mcp_b;

    np_ctx = NetworkPolicy(name="np-context-ingress");
    np_mcp = NetworkPolicy(name="np-mcp-egress");
    shared_ctx +>:Drives(via="np"):+> np_ctx;
    shared_ctx +>:Drives(via="np"):+> np_mcp;

    # Pre-seed the McpServer spec_hash so the gate is observable on tick 1.
    mcp_a.spec_hash = "h-helpdesk-001";
    mcp_b.spec_hash = "h-work-001";

    # Three reconcile ticks, each recipe takes a turn at the shared resources.
    root spawn Reconcile(recipe_name=helpdesk.name, desired_hash=helpdesk.desired_hash);
    root spawn Reconcile(recipe_name=work.name, desired_hash=work.desired_hash);
    root spawn Reconcile(recipe_name=helpdesk.name, desired_hash=helpdesk.desired_hash);

    auditor = OrderAuditor();
    root spawn auditor;
    print(f"final audit snapshot: {auditor.report}");
}
```

jac_tests:
test "fixed McpServer gate versus unconditional Context write" {
    recipe = Recipe(name="recipe-a", desired_hash="h-a");
    ctx = Context(name="shared-context");
    mcp = McpServer(name="mcp-a");
    np = NetworkPolicy(name="np-a");

    root ++> recipe;
    recipe +>:Owns(since="now"):+> ctx;
    ctx +>:Drives(via="mcp"):+> mcp;
    ctx +>:Drives(via="np"):+> np;

    mcp.spec_hash = "h-a";

    res = root spawn Reconcile(recipe_name=recipe.name, desired_hash=recipe.desired_hash);

    assert mcp.writes == 0, f"expected unchanged McpServer to skip, got {mcp.writes}";
    assert mcp.generation == 0, f"expected McpServer generation 0, got {mcp.generation}";
    assert ctx.writes == 1, f"expected one unconditional Context write, got {ctx.writes}";
    assert ctx.generation == 1, f"expected Context generation 1, got {ctx.generation}";
    assert ctx.spec_hash == "h-a", f"expected Context hash h-a, got {ctx.spec_hash}";
    assert np.writes == 1, f"expected one downstream NetworkPolicy write, got {np.writes}";
    assert np.generation == 1, f"expected NetworkPolicy generation 1, got {np.generation}";
    assert mcp in [ctx ->:Drives:->], f"missing typed McpServer drive edge";
    assert np in [ctx ->:Drives:->], f"missing typed NetworkPolicy drive edge";
}

test "repeated reconcile ticks churn Context and NetworkPolicy but not McpServer" {
    recipe = Recipe(name="recipe-b", desired_hash="h-b");
    ctx = Context(name="shared-context");
    mcp = McpServer(name="mcp-b");
    np = NetworkPolicy(name="np-b");

    root ++> recipe;
    recipe +>:Owns(since="now"):+> ctx;
    ctx +>:Drives(via="mcp"):+> mcp;
    ctx +>:Drives(via="np"):+> np;

    mcp.spec_hash = "old-hash";

    first = root spawn Reconcile(recipe_name=recipe.name, desired_hash=recipe.desired_hash);
    second = root spawn Reconcile(recipe_name=recipe.name, desired_hash=recipe.desired_hash);

    assert mcp.writes == 1, f"expected McpServer to write only on first changed tick, got {mcp.writes}";
    assert mcp.generation == 1, f"expected McpServer generation 1, got {mcp.generation}";
    assert mcp.resource_version == 1, f"expected McpServer resource version 1, got {mcp.resource_version}";
    assert mcp.spec_hash == "h-b", f"expected McpServer hash h-b, got {mcp.spec_hash}";
    assert ctx.writes == 2, f"expected Context to rewrite on both ticks, got {ctx.writes}";
    assert ctx.generation == 2, f"expected Context generation 2, got {ctx.generation}";
    assert ctx.resource_version == 2, f"expected Context resource version 2, got {ctx.resource_version}";
    assert np.writes == 2, f"expected downstream NetworkPolicy rewrites on both ticks, got {np.writes}";
    assert np.generation == 2, f"expected NetworkPolicy generation 2, got {np.generation}";
}

test "auditor reports the asymmetric write counts" {
    mcp = McpServer(name="mcp-audited");
    ctx = Context(name="context-audited");
    np = NetworkPolicy(name="np-audited");
    recipe = Recipe(name="recipe-audited", desired_hash="h-audited");

    root ++> recipe;
    root ++> mcp;
    root ++> ctx;
    root ++> np;

    mcp.spec_hash = "h-audited";

    reconcile_result = root spawn Reconcile(
        recipe_name=recipe.name,
        desired_hash=recipe.desired_hash
    );

    auditor = root spawn OrderAuditor();

    assert len(auditor.report) == 3, f"expected three audited resources, got {auditor.report}";
    assert ("McpServer", "mcp-audited", 0, 0) in auditor.report, f"missing gated McpServer audit entry: {auditor.report}";
    assert ("Context", "context-audited", 1, 1) in auditor.report, f"missing Context churn audit entry: {auditor.report}";
    assert ("NetworkPolicy", "np-audited", 1, 1) in auditor.report, f"missing NetworkPolicy downstream audit entry: {auditor.report}";
}

