test "dispatcher skips cards with claims before sweep" {
    clean = Card(title="A-clean");
    orphan = Card(title="B-orphan", claim_lock="dead-worker", claim_expires="99900");
    live = Card(title="C-fresh", claim_lock="alive-worker", claim_expires="99990");

    root ++> clean;
    root ++> orphan;
    root ++> live;

    clean +>:Claim(claimed_by="", expires_at=""):+> Worker(worker_id="none");
    orphan +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-9");
    live +>:Claim(claimed_by="alive-worker", expires_at="99990"):+> Worker(worker_id="W-1");

    disp = Dispatcher();
    root spawn disp;

    assert "A-clean" in disp.dispatched, f"got {disp.dispatched}";
    assert "B-orphan" not in disp.dispatched, f"got {disp.dispatched}";
    assert "C-fresh" not in disp.dispatched, f"got {disp.dispatched}";
