    live = Card(title="C-fresh", claim_lock="alive-worker", claim_expires="99990");
    grace = Card(title="D-just-claimed", claim_lock="dead-worker", claim_expires="99985");

    root ++> orphan;
    root ++> live;
    root ++> grace;

    orphan +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-9");
    live +>:Claim(claimed_by="alive-worker", expires_at="99990"):+> Worker(worker_id="W-1");
    grace +>:Claim(claimed_by="dead-worker", expires_at="99985"):+> Worker(worker_id="W-7");

    sweep = ReclaimSweep(grace_seconds=30, now_epoch=100000);
    root spawn sweep;

    assert len(sweep.cleared) == 1, f"got {sweep.cleared}";
    assert "B-orphan" in sweep.cleared, f"got {sweep.cleared}";
    assert orphan.claim_lock is None, f"got {orphan.claim_lock}";
    assert orphan.claim_expires is None, f"got {orphan.claim_expires}";
    assert live.claim_lock == "alive-worker", f"got {live.claim_lock}";
    assert grace.claim_lock == "dead-worker", f"got {grace.claim_lock}";

    disp = Dispatcher();
    root spawn disp;

    assert "B-orphan" in disp.dispatched, f"got {disp.dispatched}";
    assert "C-fresh" not in disp.dispatched, f"got {disp.dispatched}";
    assert "D-just-claimed" not in disp.dispatched, f"got {disp.dispatched}";
}

test "sweep handles non-running statuses but not running cards" {
    todo_card = Card(
        title="todo-orphan",
        status="todo",
        claim_lock="dead-worker",
        claim_expires="99900"
    );
    blocked_card = Card(
        title="blocked-orphan",
        status="blocked",
        claim_lock="dead-worker",
        claim_expires="99900"
    );
    running_card = Card(
        title="running-claim",
        status="running",
        claim_lock="dead-worker",
        claim_expires="99900"
    );

    root ++> todo_card;
    root ++> blocked_card;
    root ++> running_card;

    todo_card +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-1");
    blocked_card +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-2");
    running_card +>:Claim(claimed_by="dead-worker", expires_at="99900"):+> Worker(worker_id="W-3");

    sweep = ReclaimSweep(grace_seconds=30, now_epoch=100000);
    root spawn sweep;

    assert len(sweep.cleared) == 2, f"got {sweep.cleared}";
    assert "todo-orphan" in sweep.cleared, f"got {sweep.cleared}";
    assert "blocked-orphan" in sweep.cleared, f"got {sweep.cleared}";
    assert "running-claim" not in sweep.cleared, f"got {sweep.cleared}";
    assert running_card.claim_lock == "dead-worker", f"got {running_card.claim_lock}";

    disp = Dispatcher();
    root spawn disp;

    assert "todo-orphan" in disp.dispatched, f"got {disp.dispatched}";
    assert "blocked-orphan" in disp.dispatched, f"got {disp.dispatched}";
    assert "running-claim" not in disp.dispatched, f"got {disp.dispatched}";
}

