test "shared values survive repeated fields" {
    shared = Body(kind="value", text="user");
    author = Body(kind="map");
    reviewer = Body(kind="map");
    author +>:Item:+> shared;
    reviewer +>:Item:+> shared;
    msg = Body(kind="map");
    msg +>:Item:+> author;
