    assert shared.null_broken == False, f"got {shared.null_broken}";
}

test "true cycle is cut without corrupting siblings" {
    cyclic = Body(kind="map");
    inner = Body(kind="map");
    sibling = Body(kind="value", text="ok");
    cyclic +>:Item:+> inner;
    cyclic +>:Item:+> sibling;
    inner +>:CyclesTo:+> cyclic;
    root ++> cyclic;

    res = root spawn Encoder();

    assert len(res.out) > 0, f"got {res.out}";
    assert "null  # cycle broken" in res.out[0], f"got {res.out[0]}";
    assert "value(ok)" in res.out[0], f"got {res.out[0]}";
    assert cyclic.null_broken == True, f"got {cyclic.null_broken}";
}

