import io;
import from contextlib { redirect_stdout }

test "zero-click owner enters observation window" {
    logistics = OwnerPage(
        slug="/services/seo-for-logistics-companies/",
        decision="KEEP_OWNER",
        clicks=0,
        impressions=242
    );
    checkpoint = Evidence(
        label="owner-provided checkpoint",
        klass="OWNER_PROVIDED_HANDOFF",
        window_days=18
    );

    root ++> logistics;
    logistics +>:AuthorityHandoff(bounded=True, regression_protected=True):+> checkpoint;

