    with redirect_stdout(buf) {
        res = root spawn Router();
    }
    out = buf.getvalue();

    assert checkpoint in [logistics ->:AuthorityHandoff:->], "missing authority handoff";
    assert logistics.decision == "OBSERVATION_WINDOW_ACTIVE", f"decision={logistics.decision}";
    assert len(res.visited) == 1, f"visited={res.visited}";
    assert logistics.slug in res.visited, f"visited={res.visited}";
    assert len(res.invalidations) == 1, f"invalidations={res.invalidations}";
    assert "evidence[OWNER_PROVIDED_HANDOFF]" in out, f"output={out}";
}

test "router traverses owners and closed provenance" {
    logistics = OwnerPage(
        slug="/services/seo-for-logistics-companies/",
        decision="KEEP_OWNER",
        clicks=0,
        impressions=242
    );
    loadboard = OwnerPage(
        slug="/load-board/",
