A maintainer on the project vercel-labs/scriptc (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #32: Mutually recursive nested function declarations abort at runtime with no diagnostic (exit 133, no output)

Two function declarations **nested inside another function** that call each other abort at runtime. The build succeeds with no diagnostic, and the binary produces no output and no error message — just `exit 133` (SIGTRAP).

The same pair of functions at module top level works correctly, so the trigger is the nesting.

## Repro

```ts
export {}
function outer(n: number): number {
  function even(k: number): number {
    if (k === 0) return 1
    return odd(k - 1)
  }
  function odd(k: number): number {
    if (k === 0) return 0
    return even(k - 1)
  }
  return even(n)
}
function main() {
  console.log(`r=${outer(4)}`)
}
main()
```

```console
$ bun recA.ts
r=1

$ scriptc build recA.ts -o recA     # no diagnostic
$ ./recA
$ echo $?
133
```

Nothing is printed on stdout or stderr.

## Narrowing

| shape | result |
|---|---|
| mutual recursion between nested declarations | **abort, exit 133** |
| the same mutual recursion at top level | works (`r=1`) |
| nested, plain forward reference (`first()` calls `second()`, no cycle) | works |
| nested, backward reference only | works |

So it is specifically the **cycle** among nested declarations, not a forward reference on its own:

```ts
// works
function outer(): number {
  function first(): number { return second() + 1 }
  function second(): number { return 41 }
  return first()
}
```

## Where I hit it

A recursive-descent parser written the conventional way — `primary`/`comparison`/`and`/`or` nested inside `parse()`, with `primary()` calling `or()` for a parenthesised sub-expression. Compiled clean, aborted on every input. Restructuring to top-level functions over an explicit cursor object fixed it.

## Impact

Silent, message-free abort is the worst failure mode: there is nothing to search for and nothing to point at. Even if the fix takes a while, a compile-time refusal naming the cycle would make this tractable.

## Environment

- scriptc 0.0.17, `@scriptc/compiler` 0.0.17
- macOS 26.5.2, arm64, Node v24.18.0
- Static build (no `--dynamic`), default backend

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Detect mutually recursive nested function declarations with a cycle-safe walker."""

node Module {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FunctionDecl {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has nested: bool = False;
    has cycle_detected: bool = False;
}

edge Contains {
    has relation: str = "";
}

edge Calls {
    has relation: str = "";
}

walker CycleDetector {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_module with Module entry {
        print(f"module: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_function with FunctionDecl entry {
        if here.title in self.seen {
            here.cycle_detected = True;
            self.cycle_found = True;
            print(f"cycle detected at nested function {here.title}");
            disengage;
        } else {
            self.seen.append(here.title);
            print(f"visiting function {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    catalog = Module(title="recursion demo", year=2026);

    outer = FunctionDecl(title="outer", year=1, nested=False);
    even = FunctionDecl(title="even", year=2, nested=True);
    odd = FunctionDecl(title="odd", year=3, nested=True);

    root +>:Contains(relation="module"):+> catalog;
    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> even;
    outer +>:Contains(relation="nested declaration"):+> odd;
    even +>:Calls(relation="mutual recursion"):+> odd;
    odd +>:Calls(relation="mutual recursion"):+> even;

    root spawn CycleDetector();
}
```

jac_tests:
"""Test annex for the mutually recursive nested function detector."""

import io;
import from contextlib { redirect_stdout }


test "cycle detected on mutually recursive nested declarations" {
    root ++> Module(title="recursion demo", year=2026);
    catalog = [root -->][?:Module][0];
    outer = FunctionDecl(title="outer", nested=False);
    even = FunctionDecl(title="even", nested=True);
    odd = FunctionDecl(title="odd", nested=True);

    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> even;
    outer +>:Contains(relation="nested declaration"):+> odd;
    even +>:Calls(relation="mutual recursion"):+> odd;
    odd +>:Calls(relation="mutual recursion"):+> even;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert res.cycle_found, "expected cycle_found True on mutually recursive nested decls";

    even_node = [outer -->][?:FunctionDecl][0];
    odd_node = [outer -->][?:FunctionDecl][1];
    assert even_node.title in res.seen or odd_node.title in res.seen, f"expected at least one of the pair in seen, got {res.seen}";

    detected_count = len([f for f in [even_node, odd_node] if f.cycle_detected]);
    assert detected_count >= 1, f"expected at least one node flagged cycle_detected, got {detected_count}";

    out = buf.getvalue();
    assert "cycle detected" in out, f"missing cycle diagnostic in output: {out}";
    assert "visiting function" in out, f"expected traversal output: {out}";
}


test "no cycle on plain forward reference among nested declarations" {
    root ++> Module(title="forward ref demo", year=2026);
    catalog = [root -->][?:Module][0];
    outer = FunctionDecl(title="outer", nested=False);
    first = FunctionDecl(title="first", nested=True);
    second = FunctionDecl(title="second", nested=True);

    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> first;
    outer +>:Contains(relation="nested declaration"):+> second;
    first +>:Calls(relation="forward ref"):+> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert not res.cycle_found, f"forward-reference nest should not flag a cycle, got cycle_found={res.cycle_found}";
    assert "first" in res.seen, f"expected 'first' traversed, seen={res.seen}";
    assert "second" in res.seen, f"expected 'second' traversed, seen={res.seen}";
    assert not first.cycle_detected, "first should not be flagged";
    assert not second.cycle_detected, "second should not be flagged";
}


test "no cycle when only one of the nested pair calls the other (no back edge)" {
    root ++> Module(title="one-way demo", year=2026);
    catalog = [root -->][?:Module][0];
    outer = FunctionDecl(title="outer", nested=False);
    a = FunctionDecl(title="alpha", nested=True);
    b = FunctionDecl(title="beta", nested=True);

    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> a;
    outer +>:Contains(relation="nested declaration"):+> b;
    a +>:Calls(relation="calls beta"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert not res.cycle_found, f"one-way nested call must not be flagged, got cycle_found={res.cycle_found}";
    assert not a.cycle_detected, "alpha should not be flagged";
    assert not b.cycle_detected, "beta should not be flagged";
}


test "mutual recursion at module top level only — outer is not nested" {
    root ++> Module(title="top-level demo", year=2026);
    catalog = [root -->][?:Module][0];
    a = FunctionDecl(title="alpha-top", nested=False);
    b = FunctionDecl(title="beta-top", nested=False);

    catalog +>:Contains(relation="top-level function"):+> a;
    catalog +>:Contains(relation="top-level function"):+> b;
    a +>:Calls(relation="mutual recursion"):+> b;
    b +>:Calls(relation="mutual recursion"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert res.cycle_found, f"mutual cycle between two reachable functions must be detected, got cycle_found={res.cycle_found}";
    assert "alpha-top" in res.seen, f"expected 'alpha-top' in seen={res.seen}";
    assert "beta-top" in res.seen, f"expected 'beta-top' in seen={res.seen}";
    assert a.cycle_detected or b.cycle_detected, "at least one of the cycle nodes should be flagged";

    out = buf.getvalue();
    assert "cycle detected" in out, f"missing cycle diagnostic: {out}";
}


test "walker disengages cleanly on empty graph" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }
    assert not res.cycle_found, "empty graph must not produce a false cycle";
    assert len(res.seen) == 0, f"seen should be empty on no traversal, got {res.seen}";
}

