```jac
"""Lakehouse pipeline decoupling demo.

Models the tension described in Lakehouse_Plumber issue #212: a single
``pipeline:`` value on every flowgroup collapses the generated output into
one flat folder and one bundle resource file, destroying the source-side
medallion organization. We model flowgroups, their layer membership, and
the pipeline grouping as a graph, then walk it with a walker that exposes
the original-code pain (a fan-in at Gold without an execution boundary).
"""

node FlowGroup {
    has title: str = "";
    has layer: str = "";
    has pipeline: str = "";
}

node Pipeline {
    has pipeline_name: str = "";
    has is_dlt_boundary: bool = True;
}

node OutputTable {
    has table_name: str = "";
}

edge LivesIn {
    has folder: str = "";
}

edge Feeds {
    has cardinality: str = "";
}

edge BundledAs {
    has resource_file: str = "";
}

walker Plumber {
    has visited: list[str] = [];

    can start with Root entry {
        print("Plumber walking the repo -> generated layout");
        visit [-->];
    }

    can inspect_flowgroup with FlowGroup entry {
        layer_folder = f"pipelines/{here.layer}/{here.title}.yaml";
        generated_file = f"generated/dev/{here.pipeline}/{here.title}.py";
        bundle_file = f"resources/lhp/{here.pipeline}.pipeline.yml";
        print(
            f"[FG] {here.title}  layer={here.layer}  pipeline={here.pipeline}\n"
            f"     source : {layer_folder}\n"
            f"     gen    : {generated_file}\n"
            f"     bundle : {bundle_file}"
        );
        self.visited.append(here.title);
        visit [-->];
    }

    can inspect_pipeline with Pipeline entry {
        n_groups = 0;
        for fg in [-->] {
            if isinstance(fg, FlowGroup) {
                n_groups = n_groups + 1;
            }
        }
        kind = "DLT" if here.is_dlt_boundary else "logical";
        print(f"[PIPELINE] {here.pipeline_name}  ({kind}, {n_groups} flowgroups)");
        visit [-->];
    }

    can inspect_output with OutputTable entry {
        print(f"[TABLE] {here.table_name}");
    }
}

walker CascadeInvalidator {
    can start with Root entry {
        print("\nCascadeInvalidator: invalidating downstream of a slow Bronze flow");
        visit [-->];
    }

    can fanin with OutputTable entry {
        print(f"  fan-in surface : {here.table_name}");
        visit [-->];
    }
}

with entry {
    bronze_a = FlowGroup(title="parts_bronze_a", layer="01_bronze", pipeline="all");
    bronze_b = FlowGroup(title="parts_bronze_b", layer="01_bronze", pipeline="all");
    silver_a = FlowGroup(title="parts_silver_a", layer="02_silver", pipeline="all");
    silver_b = FlowGroup(title="parts_silver_b", layer="02_silver", pipeline="all");
    gold_join = FlowGroup(title="parts_gold", layer="03_gold", pipeline="all");

    end_to_end = Pipeline(pipeline_name="all", is_dlt_boundary=True);

    table_silver_a = OutputTable(table_name="silver.a_clean");
    table_silver_b = OutputTable(table_name="silver.b_clean");
    table_gold = OutputTable(table_name="gold.ab_join");

    root ++> bronze_a ++> silver_a;
    root ++> bronze_b ++> silver_b;
    root ++> silver_a ++> gold_join;
    root ++> silver_b ++> gold_join;

    bronze_a +>:LivesIn(folder="pipelines/01_FIRST_LAYER"):+> end_to_end;
    bronze_b +>:LivesIn(folder="pipelines/01_FIRST_LAYER"):+> end_to_end;
    silver_a +>:LivesIn(folder="pipelines/02_SECOND_LAYER"):+> end_to_end;
    silver_b +>:LivesIn(folder="pipelines/02_SECOND_LAYER"):+> end_to_end;
    gold_join +>:LivesIn(folder="pipelines/03_GOLD"):+> end_to_end;

    bronze_a +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    bronze_b +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    silver_a +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    silver_b +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;
    gold_join +>:BundledAs(resource_file="resources/lhp/all.pipeline.yml"):+> end_to_end;

    silver_a +>:Feeds(cardinality="1:1"):+> table_silver_a;
    silver_b +>:Feeds(cardinality="1:1"):+> table_silver_b;
    table_silver_a +>:Feeds(cardinality="N:1"):+> table_gold;
    table_silver_b +>:Feeds(cardinality="N:1"):+> table_gold;

    plumber = Plumber();
    root spawn plumber;

    print("\n--- flat-folder pain (every FG -> generated/<pipeline>/<title>.py) ---");
    print("Notice: bronze/silver/gold layer info is lost at the generated path.");

    invalidator = CascadeInvalidator();
    root spawn invalidator;
}
```

jac_tests:
"""Tests for the Lakehouse pipeline decoupling demo.

Each test builds its own small graph and exercises the walkers
(Plumber, CascadeInvalidator) to assert behaviors described in
Lakehouse_Plumber issue #212.
"""

import io;
import from contextlib { redirect_stdout }

test "Plumber visits every flowgroup exactly once" {
    root ++> FlowGroup(title="fg1", layer="L1", pipeline="p1");
    root ++> FlowGroup(title="fg2", layer="L1", pipeline="p1");
    root ++> FlowGroup(title="fg3", layer="L2", pipeline="p1");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = Plumber();
        res = root spawn w;
    }
    out = buf.getvalue();
    assert "[FG] fg1" in out, f"missing fg1: {out}";
    assert "[FG] fg2" in out, f"missing fg2: {out}";
    assert "[FG] fg3" in out, f"missing fg3: {out}";
    assert len(res.visited) == 3, f"expected 3 visited, got {len(res.visited)}";
    assert res.visited.count("fg1") == 1, "fg1 visited more than once";
    assert res.visited.count("fg2") == 1, "fg2 visited more than once";
    assert res.visited.count("fg3") == 1, "fg3 visited more than once";
}

test "Plumber emits generated and bundle paths using the pipeline field" {
    fg = FlowGroup(title="parts_x", layer="01_bronze", pipeline="all");
    root ++> fg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Plumber();
    }
    out = buf.getvalue();
    assert "generated/dev/all/parts_x.py" in out, f"flat generated path missing: {out}";
    assert "resources/lhp/all.pipeline.yml" in out, f"bundle file missing: {out}";
    assert "source : pipelines/01_bronze/parts_x.yaml" in out, f"source path wrong: {out}";
}

test "flat pipeline grouping loses layer info in generated paths" {
    bronze = FlowGroup(title="b", layer="01_bronze", pipeline="all");
    silver = FlowGroup(title="s", layer="02_silver", pipeline="all");
    gold = FlowGroup(title="g", layer="03_gold", pipeline="all");
    root ++> bronze;
    root ++> silver;
    root ++> gold;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Plumber();
    }
    out = buf.getvalue();

    # Source side preserves the layer organization:
    assert "pipelines/01_bronze/b.yaml" in out, f"bronze source path missing: {out}";
    assert "pipelines/02_silver/s.yaml" in out, f"silver source path missing: {out}";
    assert "pipelines/03_gold/g.yaml" in out, f"gold source path missing: {out}";

    # Generated side collapses them into the SAME folder regardless of layer:
    assert "generated/dev/all/b.py" in out, f"bronze generated missing: {out}";
    assert "generated/dev/all/s.py" in out, f"silver generated missing: {out}";
    assert "generated/dev/all/g.py" in out, f"gold generated missing: {out}";

    # And every flowgroup shares the same bundle resource file:
    bundle_count = out.count("resources/lhp/all.pipeline.yml");
    assert bundle_count == 3, f"expected 3 bundle references, got {bundle_count}: {out}";
}

test "Pipeline node reports dlt boundary and counts its flowgroups" {
    fg1 = FlowGroup(title="a", layer="L1", pipeline="p1");
    fg2 = FlowGroup(title="b", layer="L1", pipeline="p1");
    fg3 = FlowGroup(title="c", layer="L2", pipeline="p1");
    p = Pipeline(pipeline_name="p1", is_dlt_boundary=True);
    root ++> p;
    p ++> fg1;
    p ++> fg2;
    p ++> fg3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Plumber();
    }
    out = buf.getvalue();
    assert "[PIPELINE] p1" in out, f"pipeline header missing: {out}";
    assert "(DLT" in out, f"DLT kind missing: {out}";
    assert "3 flowgroups" in out, f"flowgroup count wrong: {out}";
}

test "CascadeInvalidator walks the fan-in surface from an OutputTable" {
    t = OutputTable(table_name="gold.ab_join");
    root ++> t;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CascadeInvalidator();
    }
    out = buf.getvalue();
    assert "CascadeInvalidator" in out, f"header missing: {out}";
    assert "gold.ab_join" in out, f"fan-in surface not printed: {out}";
}

