```jac
"""Cyclic graph traversal: cycle-safe walker that mirrors the issue's repro.

Models the essential scenario from jac issue #8562: ``visit [-->]`` on a
graph with a cycle must NOT hang. We declare a tiny graph of two nodes
with a back-edge, then spawn a walker that keeps an explicit visited
set on the walker itself so each node is reported at most once. A
second walker that ``disengage``s on the first revisit demonstrates the
opt-in revisit policy.
"""

node Site {
    has tag: str = "";
    has alive: bool = True;
}

edge Link {
    has weight: int = 1;
}

walker CyclicVisitor {
    has visited: list[str] = [];

    can start with Root entry {
        print(f"begin traversal from root; visited starts as {self.visited}");
        visit [-->];
    }

    can scan with Site entry {
        if here.tag in self.visited {
            print(f"cycle guard fired: {here.tag} already seen, disengaging");
            disengage;
        }
        self.visited.append(here.tag);
        print(f"visiting site {here.tag} (alive={here.alive})");
        visit [-->] else {
            print("frontier empty; traversal ends cleanly");
            disengage;
        }
    }
}

walker CascadeInvalidator {
    has invalidated: list[str] = [];

    can start with Root entry {
        print("cascade invalidation begins");
        visit [-->];
    }

    can invalidate with Site entry {
        if not here.alive {
            print(f"{here.tag} already dead, disengage");
            disengage;
        }
        here.alive = False;
        self.invalidated.append(here.tag);
        print(f"invalidated site {here.tag}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    a = Site(tag="A");
    b = Site(tag="B");
    root ++> a +>:Link(weight=1):+> b;
    b +>:Link(weight=2):+> a;

    print("--- CyclicVisitor on A<->B cycle ---");
    CyclicVisitor() spawn root;

    print("--- CascadeInvalidator on same cycle ---");
    c = Site(tag="C");
    d = Site(tag="D");
    root ++> c +>:Link:+> d;
    d +>:Link:+> c;
    CascadeInvalidator() spawn root;
}
```

jac_tests:
"""Test annex for the cycle-safe traversal demo.

Verifies the three behaviors the issue and program promise:

1. CyclicVisitor terminates on a cyclic graph (does not hang) and visits
   each Site at most once, in DFS order with a cycle-guard disengage.
2. CascadeInvalidator cascades through a cycle, marks every reachable
   Site alive=False exactly once, and disengages cleanly when revisiting
   a dead node.
3. A trivial acyclic graph terminates cleanly with no false cycle-guard
   firings and no spurious prints from disengage branches.
"""

import io;
import from contextlib { redirect_stdout }


# -------------------------------------------------------------------------
# Test 1: CyclicVisitor terminates on a cycle, reports each node once.
# -------------------------------------------------------------------------
test "cyclic visitor terminates and visits each site once" {
    a = Site(tag="A");
    b = Site(tag="B");
    root ++> a +>:Link(weight=1):+> b;
    b +>:Link(weight=2):+> a;

    w = CyclicVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn w;
    }
    out = buf.getvalue();

    # Termination: the walker must report a finite number of visits.
    assert out.count("visiting site") == 2, (
        f"expected exactly 2 visits on the A<->B cycle, got: {out!r}"
    );

    # Cycle-guard must fire exactly once (the second arrival at A).
    assert out.count("cycle guard fired") == 1, (
        f"expected one cycle-guard firing, got {out.count('cycle guard fired')} in: {out!r}"
    );

    # No "frontier empty" message should appear — the cycle always
    # provides a non-empty frontier; the guard is what ends the walk.
    assert "frontier empty" not in out, (
        f"frontier-empty branch should not fire on a cycle, got: {out!r}"
    );

    # The walker's reported order must be A then B (DFS from root).
    assert [v for v in res.visited] == ["A", "B"], (
        f"expected visit order ['A','B'], got {res.visited}"
    );

    # Underlying graph shape sanity check.
    assert len([root-->]) == 1, "root should have exactly one outgoing edge";
}


# -------------------------------------------------------------------------
# Test 2: CascadeInvalidator cascades through a cycle, marking each
# reachable Site dead exactly once.
# -------------------------------------------------------------------------
test "cascade invalidator marks each reachable site dead once" {
    a = Site(tag="A");
    b = Site(tag="B");
    root ++> a +>:Link(weight=1):+> b;
    b +>:Link(weight=2):+> a;

    w = CascadeInvalidator();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn w;
    }
    out = buf.getvalue();

    # Each Site is invalidated exactly once.
    assert out.count("invalidated site") == 2, (
        f"expected 2 invalidations, got: {out!r}"
    );
    assert res.invalidated == ["A", "B"], (
        f"expected invalidation order ['A','B'], got {res.invalidated}"
    );

    # Cycle-guard via the alive=False check should disengage cleanly on
    # the revisit; no node should be reported as visited twice.
    assert out.count("already dead, disengage") == 1, (
        f"expected one disengage-on-dead-revisit, got: {out!r}"
    );

    # Both nodes are now dead in the graph.
    assert a.alive == False, "site A should be dead after cascade";
    assert b.alive == False, "site B should be dead after cascade";
}


# -------------------------------------------------------------------------
# Test 3: Acyclic chain terminates cleanly with no cycle-guard firings
# and no spurious disengage messages.
# -------------------------------------------------------------------------
test "acyclic chain terminates cleanly without cycle guard" {
    a = Site(tag="A");
    b = Site(tag="B");
    c = Site(tag="C");
    root ++> a +>:Link:+> b +>:Link:+> c;

    w = CyclicVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn w;
    }
    out = buf.getvalue();

    # All three sites visited, in order.
    assert out.count("visiting site") == 3, (
        f"expected 3 visits on acyclic chain, got: {out!r}"
    );
    assert res.visited == ["A", "B", "C"], (
        f"expected ['A','B','C'], got {res.visited}"
    );

    # No cycle guard on an acyclic graph.
    assert "cycle guard fired" not in out, (
        f"cycle guard must not fire on a DAG, got: {out!r}"
    );

    # Frontier becomes empty at the leaf — that's how the walk ends.
    assert "frontier empty" in out, (
        f"expected 'frontier empty' termination on a leaf, got: {out!r}"
    );

    # Graph shape sanity check.
    assert len([root-->]) == 1, "root should have exactly one outgoing edge";
    assert len([a-->]) == 1, "A should have exactly one outgoing edge";
    assert len([b-->]) == 1, "B should have exactly one outgoing edge";
    assert len([c-->]) == 0, "C should be a leaf";
}


# -------------------------------------------------------------------------
# Test 4: Self-loop (the minimal repro from the issue) must also
# terminate, visiting the lone site exactly once.
# -------------------------------------------------------------------------
test "self-loop terminates after a single visit" {
    a = Site(tag="A");
    root ++> a +>:Link(weight=1):+> a;

    w = CyclicVisitor();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn w;
    }
    out = buf.getvalue();

    # The single site is visited exactly once; the immediate revisit
    # via the self-loop trips the guard and disengages.
    assert out.count("visiting site") == 1, (
        f"self-loop must yield one visit, got: {out!r}"
    );
    assert out.count("cycle guard fired") == 1, (
        f"expected cycle guard to fire once on self-loop, got: {out!r}"
    );
    assert res.visited == ["A"], (
        f"expected visited=['A'], got {res.visited}"
    );

    # Self-loop edge present in graph.
    assert a in [a ->:Link:->], "self-loop Link edge should exist";
}

