test "partial procfs snapshot loses descendant attribution" {
    snap = Snapshot(source="DockerDesktop-LinuxKit", filled=39, total=95);
    inv = KernelInvariant(
        name="hereditary",
        description="child joins execve_map only if parent already present"
    );

    mapped_root = ProcEntry(
        pid=4101,
        binary="/sbin/init",
        exec_id="e1",
        flags="EXEC",
        pod="kube-system/init",
        in_execve_map=True,
        probed=True
    );
    mapped_worker = ProcEntry(
        pid=4102,
        binary="/usr/bin/containerd",
        exec_id="e2",
        flags="EXEC",
        pod="kube-system/containerd",
        in_execve_map=True,
        probed=True
    );
    mapped_agent = ProcEntry(
        pid=4103,
        binary="/usr/bin/tetragon",
        exec_id="e3",
        flags="EXEC",
        pod="kube-system/tetragon",
        in_execve_map=True,
        probed=True
    );
    dropped = ProcEntry(pid=4104, in_execve_map=False, probed=True);
    descendant = ProcEntry(pid=4105, in_execve_map=False, probed=True);
    pod_process = ProcEntry(pid=4106, in_execve_map=False, probed=True);

    root ++> snap ++> inv ++> mapped_root;
    mapped_root ++> mapped_worker ++> mapped_agent ++> dropped;
    dropped ++> descendant ++> pod_process;

