    assert res.neutralised == 3, f"got {res.neutralised}";
    assert "[seed] DockerDesktop-LinuxKit: 39/95 filled" in out, f"got {out}";
    assert "[kprobe] pid=4103 FULL" in out, f"got {out}";
    assert "pid=4104 EMPTY binary='' exec_id='' flags='' pod=''" in out, f"got {out}";
    assert "pid=4106 EMPTY binary='' exec_id='' flags='' pod=''" in out, f"got {out}";
