    assert "COVERED" in out, f"missing COVERED marker in output: {out}";
    assert "sum_all" in out, f"sum_all not reported: {out}";
    assert "then_chain" in out, f"then_chain not reported: {out}";
}

test "duplicate method nodes are only classified once" {
    ext = ExtendBlock(receiver="Vec", type_param="number");
    m = Method(
        name="sum_all",
        body_size=11,
        span_table_len=4,
        missing_exprs=["BinaryOp@96-101"]
    );

    # Same method linked twice via two edge types — should classify once.
    ext +>:Hosts:+> m;
    ext +>:Calls:+> m;
    root ++> ext;

    probe = CoverageProbe();
    root spawn probe;

    assert probe.residual_count == 1, (
        f"duplicate visit should not double-count, got "
        f"residual_count={probe.residual_count}"
    );
    assert probe.covered_count == 0, f"got covered={probe.covered_count}";
    assert len(probe.seen) == 1, f"expected single entry in seen, got {probe.seen}";
}

test "traversal reaches methods through both Hosts and Calls edges" {
    src_ext = ExtendBlock(receiver="Option", type_param="T");
    target = Method(
        name="then_chain",
        body_size=27,
        span_table_len=15,
        missing_exprs=["Closure@440-475"]
    );

    # Calls edge reaches the same method that Hosts edge reaches.
    src_ext +>:Calls:+> target;
    root ++> src_ext;

    probe = CoverageProbe();
    root spawn probe;

    assert probe.residual_count == 1, (
        f"Calls edge traversal missed the residual method, got "
        f"residual_count={probe.residual_count}"
    );
}

