        status="WAITING_FOR_APPROVAL",
        pending_decision="DENY",
        last_result=""
    );
    sess +>:SpawnedBy:+> spawned;
    deny_rule = Rule(rule_id="R2", effect="DENY", pattern="/secret/**");
    spawned +>:WaitsForApproval:+> deny_rule;
    decide = ApprovalFlow();
