test "waiting approval is non-terminal and cancel avoids orphan" {
    pending = SpawnedChild(
        task_id="task-3",
        status="WAITING_FOR_APPROVAL",
        pending_decision="PENDING",
        last_result=""
    );
    assert pending.status == "WAITING_FOR_APPROVAL", f"expected waiting status, got {pending.status}";
    assert pending.status != "COMPLETED", f"approval pending must not be completed: {pending.status}";
    assert pending.last_result == "", f"pending task must not have terminal result: {pending.last_result}";
    sess = Session(session_id="child-3", working_dir="/work/child");
    root ++> sess;
    spawned = SpawnedChild(
        task_id="task-4",
        status="WAITING_FOR_APPROVAL",
        pending_decision="CANCEL",
        last_result=""
    );
    sess +>:SpawnedBy:+> spawned;
    decide = ApprovalFlow();
    decide.decision = "CANCEL";
    res = sess spawn decide;
    assert "cancel -> no orphan for session=child-3" in res.verdict_line, f"unexpected cancel verdict: {res.verdict_line}";
