    assert "Settings" in auditor.visited, f"missing Settings: {auditor.visited}";
    assert "AccessibilityPrefs" in auditor.visited, f"missing AccessibilityPrefs: {auditor.visited}";
    assert len(auditor.visited) == 5, f"expected 5 visited, got {auditor.visited}";
