    assert res.fail_count >= 1, f"non-admitted provider must increment fail_count, got {res.fail_count}";
    assert "[GATE] tesseract NOT ADMITTED -> baseline blocked" in out, f"missing gate line: {out}";
    assert "[RUN" not in out, f"no run lines expected when gated: {out}";
    assert not r1.completed, f"r1 must not be marked completed when gated: {r1.completed}";
