test "nonzero provider cost is a guardrail failure and stops baseline" {
    root ++> Provider(name="tesseract", admitted=True, cost=12.5);
    r1 = Run(label="DEV-A", deterministic=True, holdout_touched=False,
             latency_ms=1000, rss_mb=100);
