    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RunBaseline(provider_name="tesseract");
    }
    out = buf.getvalue();

    assert res.run_count == 0, f"costly provider must execute zero runs, got {res.run_count}";
    assert res.fail_count >= 1, f"cost guardrail must record failure, got {res.fail_count}";
    assert "[GUARD] cost 12.5 != 0 -> baseline blocked" in out, f"missing guard line: {out}";
    assert "RUN 1/2" not in out, f"no runs allowed under cost guardrail: {out}";
}

test "run with holdout access is blocked and records a failure" {
    root ++> Provider(name="tesseract", admitted=True, cost=0.0);
    r1 = Run(label="DEV-A", deterministic=True, holdout_touched=False,
             latency_ms=1000, rss_mb=100);
    r2 = Run(label="DEV-B", deterministic=True, holdout_touched=True,
             latency_ms=1000, rss_mb=100);
