    assert res.fail_count >= 1, f"holdout-touching run must fail, got {res.fail_count}";
    assert "[GUARD] DEV-B touched HOLDOUT -> blocked" in out, f"missing holdout guard line: {out}";
    assert r1.completed and not r2.completed, f"only r1 should complete: {r1.completed},{r2.completed}";
}

test "wrong provider name is skipped and recorded but baseline continues" {
    root ++> Provider(name="pp-structurev3", admitted=True, cost=0.0);
    root ++> Provider(name="tesseract", admitted=True, cost=0.0);
    r1 = Run(label="DEV-A", deterministic=True, holdout_touched=False,
             latency_ms=4200, rss_mb=380);
