    assert "tesseract" in res.seen_providers, f"walker must observe tesseract: {res.seen_providers}";
    assert res.run_count == 2, f"both runs must still execute, got {res.run_count}";
    assert "[ADMIT] tesseract cost=0.0 status=ADMITTED" in out, f"tesseract must still be admitted: {out}";
