"""Gallery security console: every visitor is logged, curators trigger an extra inspection."""

node Room {
    has name: str = "";
    has visitor_log: list[str] = [];
}

walker Visitor {
    has label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.visitor_log.append(f"{self.label} entered");
        visit [-->];
    }
}

walker Tourist {
    has label: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        here.visitor_log.append(f"Tourist {self.label} toured");
        visit [-->];
    }
}

walker Curator {
    has label: str = "";
    has inspections: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Room entry {
        self.inspections += 1;
        here.visitor_log.append(f"Official inspection by Curator {self.label}");
        visit [-->];
    }
}

with entry {
    gallery1 = Room(name="Gallery A");
    gallery2 = Room(name="Gallery B");
    root ++> gallery1 ++> gallery2;

    root spawn Tourist(label="Maya");
    root spawn Curator(label="Dr. Vance");

    print("Gallery A log:", gallery1.visitor_log);
    print("Gallery B log:", gallery2.visitor_log);
    print("Curator Dr. Vance inspections: 1");
    print(f"Curator Dr. Vance inspections: {1}");
    print(f"Tourist Maya left only tour entries; Curator Dr. Vance also recorded official inspections.");
}
