"""Test annex for the gallery security console."""

import io;
import from contextlib { redirect_stdout }

test "tourist logs tour entries across rooms" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Tourist(label="Maya");
    }
    out = buf.getvalue();

    g1 = [root -->][0];
    g2 = [([root -->][0]) -->][0];

    # Exactly two rooms, both visited by the tourist.
    assert len(g1.visitor_log) == 1, f"Gallery A should have one tourist entry, got {g1.visitor_log}";
    assert len(g2.visitor_log) == 1, f"Gallery B should have one tourist entry, got {g2.visitor_log}";

    # Tourist logs use the tour phrasing.
    assert g1.visitor_log[0] == "Tourist Maya toured",
        f"Gallery A tourist entry wording wrong: {g1.visitor_log}";
    assert g2.visitor_log[0] == "Tourist Maya toured",
        f"Gallery B tourist entry wording wrong: {g2.visitor_log}";

    # Curator-specific phrasing must not appear from a pure tourist run.
    assert all("Official inspection" not in e for e in (g1.visitor_log + g2.visitor_log)),
        f"tourist run must not record official inspections: {g1.visitor_log} / {g2.visitor_log}";
}

test "curator logs official inspections and counts them" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Curator(label="Dr. Vance");
    }
    out = buf.getvalue();

    g1 = [root -->][0];
    g2 = [([root -->][0]) -->][0];

    # Each room gets exactly one official-inspection line.
    assert len(g1.visitor_log) == 1, f"Gallery A should have one curator entry, got {g1.visitor_log}";
    assert len(g2.visitor_log) == 1, f"Gallery B should have one curator entry, got {g2.visitor_log}";

    assert g1.visitor_log[0] == "Official inspection by Curator Dr. Vance",
        f"Gallery A curator entry wrong: {g1.visitor_log}";
    assert g2.visitor_log[0] == "Official inspection by Curator Dr. Vance",
        f"Gallery B curator entry wrong: {g2.visitor_log}";

    # The curator's per-walker counter reflects the two-room traversal.
    assert res.inspections == 2,
        f"curator should have inspected 2 rooms, got {res.inspections}";

    # Tourist phrasing must not leak into a pure curator run.
    assert all("toured" not in e for e in (g1.visitor_log + g2.visitor_log)),
        f"curator run must not produce tourist entries: {g1.visitor_log} / {g2.visitor_log}";
}

test "tourist and curator leave distinguishable records on shared rooms" {
    root ++> Room(name="Gallery A") ++> Room(name="Gallery B");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Tourist(label="Maya");
        curator_res = root spawn Curator(label="Dr. Vance");
    }
    out = buf.getvalue();

    g1 = [root -->][0];
    g2 = [([root -->][0]) -->][0];

    # After both walkers ran, each room has exactly two entries: one tourist + one curator.
    assert len(g1.visitor_log) == 2,
        f"Gallery A should have two entries (tourist + curator), got {g1.visitor_log}";
    assert len(g2.visitor_log) == 2,
        f"Gallery B should have two entries (tourist + curator), got {g2.visitor_log}";

    combined = g1.visitor_log + g2.visitor_log;
    tourist_entries = [e for e in combined if "toured" in e];
    inspection_entries = [e for e in combined if "Official inspection" in e];

    assert len(tourist_entries) == 2,
        f"expected exactly two tourist tour entries, got {tourist_entries}";
    assert len(inspection_entries) == 2,
        f"expected exactly two official-inspection entries, got {inspection_entries}";

    # Curator's counter is independent of tourist activity.
    assert curator_res.inspections == 2,
        f"curator should still report 2 inspections, got {curator_res.inspections}";
}

test "curator inspections counter resets per spawn" {
    root ++> Room(name="Solo Room");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        solo = root spawn Curator(label="Solo");
    }
    out = buf.getvalue();

    room = [root -->][0];
    assert len(room.visitor_log) == 1, f"single-room run: expected 1 entry, got {room.visitor_log}";
    assert room.visitor_log[0] == "Official inspection by Curator Solo",
        f"unexpected solo-room entry: {room.visitor_log}";
    assert solo.inspections == 1,
        f"curator inspecting one room should report 1, got {solo.inspections}";
}

