"""Rental shop shelf audit: book and DVD items get typed handling, anything else triggers a default audit path."""

node Book {
    has title: str = "";
    has author: str = "";
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
}

# Catch-all node type for anything unclassified (e.g., an old archive reel).
node MiscItem {
    has label: str = "";
}

edge Shelved { }

walker Auditor {
    has total_count: int = 0;
    has default_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_book with Book entry {
        self.total_count += 1;
        print(f"[BOOK] '{here.title}' by {here.author}");
        visit [-->];
    }

    can audit_dvd with DVD entry {
        self.total_count += 1;
        print(f"[DVD]  '{here.title}' ({here.runtime} min)");
        visit [-->];
    }

    can audit_default with MiscItem entry {
        self.total_count += 1;
        self.default_count += 1;
        print(f"[DEFAULT] unclassified item: {here.label}");
        visit [-->];
    }
}

with entry {
    root +>:Shelved:+> Book(title="The Hobbit", author="Tolkien");
    root +>:Shelved:+> Book(title="Dune", author="Herbert");
    root +>:Shelved:+> DVD(title="Blade Runner", runtime=117);
    root +>:Shelved:+> DVD(title="Spirited Away", runtime=125);
    root +>:Shelved:+> MiscItem(label="Archive Reel #42");
    root +>:Shelved:+> MiscItem(label="VHS Promo");

    auditor = Auditor();
    root spawn auditor;

    print(f"Audit complete: {auditor.total_count} items, "
          f"{auditor.default_count} needed default handling");
}
```

