    assert res.default_count == 2, f"expected 2 default items, got {res.default_count}";
    assert "[DEFAULT] unclassified item: Archive Reel #42" in out, f"missing archive line: {out}";
    assert "[DEFAULT] unclassified item: VHS Promo" in out, f"missing VHS line: {out}";
