test "mixed shelf counts every item and only unclassified ones as default" {
    root ++> Book(title="The Hobbit", author="Tolkien");
    root +>:Shelved:+> DVD(title="Blade Runner", runtime=117);
    root +>:Shelved:+> MiscItem(label="Archive Reel #42");
    root +>:Shelved:+> Book(title="Dune", author="Herbert");
    root +>:Shelved:+> MiscItem(label="VHS Promo");
    root +>:Shelved:+> DVD(title="Spirited Away", runtime=125);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.total_count == 6, f"expected 6 total items, got {res.total_count}";
    assert res.default_count == 2, f"expected 2 default items, got {res.default_count}";

    # Every typed item must appear with its proper prefix.
    assert "[BOOK] 'The Hobbit' by Tolkien" in out, f"missing Hobbit: {out}";
    assert "[BOOK] 'Dune' by Herbert" in out, f"missing Dune: {out}";
    assert "[DVD]  'Blade Runner' (117 min)" in out, f"missing Blade Runner: {out}";
    assert "[DVD]  'Spirited Away' (125 min)" in out, f"missing Spirited Away: {out}";
    # Both unclassified items must hit the default path.
    assert "[DEFAULT] unclassified item: Archive Reel #42" in out, f"missing archive: {out}";
    assert "[DEFAULT] unclassified item: VHS Promo" in out, f"missing VHS: {out}";

    # Output count of prefix lines must equal total_count.
    book_lines = out.count("[BOOK]");
    dvd_lines = out.count("[DVD]");
    default_lines = out.count("[DEFAULT]");
    assert book_lines + dvd_lines + default_lines == res.total_count, (
        f"prefix line count {book_lines + dvd_lines + default_lines} != total {res.total_count}"
    );
    assert default_lines == res.default_count, (
        f"[DEFAULT] lines {default_lines} != default_count {res.default_count}"
    );
}

test "empty shelf reports zero items" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.total_count == 0, f"expected 0 total, got {res.total_count}";
    assert res.default_count == 0, f"expected 0 default, got {res.default_count}";
    assert "[BOOK]" not in out, f"unexpected book output on empty shelf: {out}";
    assert "[DVD]" not in out, f"unexpected dvd output on empty shelf: {out}";
    assert "[DEFAULT]" not in out, f"unexpected default output on empty shelf: {out}";
}

