"""Micro-blog reader: walks the public timeline in creation order.

The commons floor lets anyone reach the shared graph, and authors
publish with `readable` access. A `Publisher` walker creates posts
so the file runs standalone; the `Reader` walker collects posts in
the order they were published.
"""

node Post {
    has title: str = "";
    has body: str = "";
    has created_at: int = 0;
}

walker Reader {
    has collected: list = [];

    can start with Root entry {
        visit [-->];
    }

    can read with Post entry {
        self.collected.append(here);
        visit [-->];
    }
}

walker Publisher {
    can start with Root entry {
        visit [-->];
    }

    can publish with Post entry {
        print(f"post: {here.title}");
        visit [-->];
    }
}

with entry {
    root ++> Post(title="hello", body="first", created_at=1)
        ++> Post(title="world", body="second", created_at=2)
        ++> Post(title="!", body="third", created_at=3);

    publisher = Publisher();
    root spawn publisher;

    reader = Reader();
    root spawn reader;

    print(f"reader collected {len(reader.collected)} posts in order");
    for p in reader.collected {
        print(f"  - {p.title} @ {p.created_at}");
    }
}
```

