"""Test annex for the micro-blog reader + publisher walkers."""

import io;
import from contextlib { redirect_stdout }

test "Reader collects posts in creation order" {
    root ++> Post(title="hello", body="first", created_at=1)
        ++> Post(title="world", body="second", created_at=2)
        ++> Post(title="!", body="third", created_at=3);

