"""Weather sweep: visit weather stations, report each reading, then summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[float] = [];

    can start with Root entry {
        print("Starting weather sweep");
        visit [--> ] else {
            print("Readings: []");
            print("Min: N/A  Max: N/A");
            disengage;
        };
    }

    can record with WeatherStation entry {
        print(f"{here.location}: {here.celsius} C");
        self.readings.append(here.celsius);
        visit [--> ] else {
            print(f"Readings: {self.readings}");
            min_temp = min(self.readings);
            max_temp = max(self.readings);
            print(f"Min: {min_temp} C  Max: {max_temp} C");
            disengage;
        };
    }
}

with entry {
    root ++> WeatherStation(location="North Ridge", celsius=-2.5)
        ++> WeatherStation(location="Harbor Pier", celsius=14.0)
        ++> WeatherStation(location="Downtown", celsius=22.3)
        ++> WeatherStation(location="Summit", celsius=3.1);
    root spawn WeatherSweep();
}
