        template_name="Workflow Viewer",
        template_version=1,
        permission_keys=["audit.read", "tenants.manage"],
    );
    second = TenantRole(
        name="recovery-two",
        template_name="Workflow Author",
        template_version=1,
        permission_keys=["audit.read", "tenants.manage"],
