    root ++> config;
    root ++> first;
    root ++> second;

    res = root spawn RemovalAttempt();

    assert res.block_reason != "", f"got {res.block_reason}";
    assert len([root -->](?:TenantRole)) == 1, f"got {len([root -->](?:TenantRole))}";
    remaining = [root -->](?:TenantRole)[0];
    assert "audit.read" in remaining.permission_keys, f"got {remaining.permission_keys}";
    assert "tenants.manage" in remaining.permission_keys, f"got {remaining.permission_keys}";
}

