"""Regression tests for the centralized operator-safe redaction walker."""

import io;
import from contextlib { redirect_stdout }

test "policy declares forbidden fields and scrub counts" {
    # Fresh graph per test - tests run in isolated workers.
    rt = root;
    policy = RedactionPolicy(
        name="OperatorPolicy",
        forbidden_fields=[
            "password", "secret", "token", "api_key",
            "authorization", "cookie", "credentials", "embedding", "prompt",
        ],
        max_bytes=64,
    );
    rt +>:DeliveredTo:+> policy;
    log = OperatorLog(sink_name="stdout", label="OperatorLog/stdout");
    policy ++> log;

    auditor = ScrubAuditor();
    rt spawn auditor;

    # The inspector ability must report the policy's metadata.
    findings_str = "\n".join(auditor.findings);
    assert "policy=OperatorPolicy" in findings_str, f"no policy line: {findings_str}";
    assert "forbidden=9" in findings_str, f"expected 9 forbidden fields: {findings_str}";

    # No traversals into nested values occurred - counters stay zero.
    assert policy.redaction_count == 0, f"unexpected redactions: {policy.redaction_count}";
    assert policy.snapshot_count == 0, f"unexpected snapshots: {policy.snapshot_count}";
}

test "bearer token text is redacted during traversal" {
    rt = root;
    policy = RedactionPolicy(
        name="OperatorPolicy",
        forbidden_fields=[
            "password", "secret", "token", "api_key",
            "authorization", "cookie", "credentials", "embedding", "prompt",
        ],
        max_bytes=1024,
    );
    log = OperatorLog(sink_name="stdout", label="OperatorLog/stdout");
    rt +>:DeliveredTo:+> policy;
    policy ++> log;

    # Token-shaped scalar reachable through a boundary value chain.
    history_list = ListValue(label="history");
    token_scalar = ScalarValue(
        kind="string",
        raw="Bearer eyJhbGciOiJIUzI1NiJ9.payload.sig",
    );
    history_list +>:Contains:+> token_scalar;
    log +>:Contains:+> history_list;

    # Scrub the scalar value directly to verify policy behavior.
    scrubbed = policy.scrub_text(token_scalar.raw);
    assert scrubbed == "[REDACTED-TOKEN]", f"token not scrubbed: {scrubbed}";
    assert policy.redaction_count == 1, f"redaction count: {policy.redaction_count}";

    # Walking the graph must visit the boundary and the container.
    auditor = ScrubAuditor();
    rt spawn auditor;
    findings_str = "\n".join(auditor.findings);
    assert "boundary=OperatorLog/stdout" in findings_str, f"no boundary line: {findings_str}";
    assert "scalar" in findings_str, f"no scalar line: {findings_str}";
}

test "self referential list value triggers cycle detection" {
    rt = root;
    policy = RedactionPolicy(
        name="OperatorPolicy",
        forbidden_fields=[
            "password", "secret", "token", "api_key",
            "authorization", "cookie", "credentials", "embedding", "prompt",
        ],
        max_bytes=1024,
    );
    log = OperatorLog(sink_name="stdout", label="OperatorLog/stdout");
    rt +>:DeliveredTo:+> policy;
    policy ++> log;

    # A list that "loops back" to itself via shared label reuse.
    loop_list = ListValue(label="loop");
    inner_scalar = ScalarValue(kind="string", raw="inside");
    loop_list +>:Contains:+> inner_scalar;
    log +>:Contains:+> loop_list;

    auditor = ScrubAuditor();
    auditor.visited.append("loop");
    rt spawn auditor;

    findings_str = "\n".join(auditor.findings);
    assert "cycle-detected=loop" in findings_str, f"cycle not detected: {findings_str}";
}

test "oversized scalar yields truncated snapshot metadata" {
    rt = root;
    # max_bytes deliberately tiny so the 300-byte payload overflows.
    policy = RedactionPolicy(
        name="OperatorPolicy",
        forbidden_fields=[
            "password", "secret", "token", "api_key",
            "authorization", "cookie", "credentials", "embedding", "prompt",
        ],
        max_bytes=128,
    );
    log = OperatorLog(sink_name="stdout", label="OperatorLog/stdout");
    rt +>:DeliveredTo:+> policy;
    policy ++> log;

    big_payload = "x" * 300;
    snap = policy.snapshot(big_payload);

    assert snap["truncated"] == 1, f"not truncated: {snap}";
    assert snap["original_bytes"] == 300, f"original_bytes wrong: {snap}";
    assert len(snap["value"]) == 128, f"preview length wrong: {len(snap['value'])}";
    assert policy.snapshot_count == 1, f"snapshot count: {policy.snapshot_count}";

    # Small value stays untruncated and metadata absent.
    small = policy.snapshot("tiny");
    assert small["truncated"] == 0, f"small not untruncated: {small}";
    assert "value" in small, f"small missing value: {small}";
}

test "walker prints full findings list across boundaries" {
    rt = root;
    policy = RedactionPolicy(
        name="OperatorPolicy",
        forbidden_fields=[
            "password", "secret", "token", "api_key",
            "authorization", "cookie", "credentials", "embedding", "prompt",
        ],
        max_bytes=256,
    );
    rt +>:DeliveredTo:+> policy;

    log = OperatorLog(sink_name="stdout", label="OperatorLog/stdout");
    audit = AuditPayload(consumer="audit-svc", label="AuditPayload/audit-svc");
    puberr = PublicErrorWrapper(classification="public-safe", label="PublicError/public-safe");
    sse = SSEPayload(channel="events", label="SSE/events");
    policy ++> log;
    policy ++> audit;
    policy ++> puberr;
    policy ++> sse;

    config_map = MapValue(label="config");
    scalar_safe = ScalarValue(kind="string", raw="hello world");
    config_map +>:Contains:+> scalar_safe;
    log +>:Contains:+> config_map;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = ScrubAuditor();
        rt spawn auditor;
        print("AUDIT REPORT");
        for f in auditor.findings {
            print(f);
        }
    }
    out = buf.getvalue();
    assert "[OUT]" not in out, f"OUT marker leaked: {out}";

    # Each boundary must appear in the report exactly once.
    assert "boundary=OperatorLog/stdout" in out, f"missing log boundary: {out}";
    assert "boundary=AuditPayload/audit-svc" in out, f"missing audit boundary: {out}";
    assert "boundary=PublicError/public-safe" in out, f"missing puberr boundary: {out}";
    assert "boundary=SSE/events" in out, f"missing sse boundary: {out}";

    # The safe scalar must surface from the recursive walk.
    assert "scalar kind=string" in out, f"no scalar visited: {out}";

    # Confirm union trigger fires on all four boundary node types.
    boundaries_hit = [
        ("boundary=OperatorLog/stdout" in out),
        ("boundary=AuditPayload/audit-svc" in out),
        ("boundary=PublicError/public-safe" in out),
        ("boundary=SSE/events" in out),
    ];
    assert all(boundaries_hit), f"some boundaries missed: {boundaries_hit}";
}

