test "event-time window deduplicates transactions and counts cycles" {
    e1 = CanonicalEvent(
        chain="Stellar", block_or_ledger="L1",
        event_time_ms=1000, tx_id="tx-1",
        asset="USDC", amount=500.0, finality="final"
    );
    e2 = CanonicalEvent(
        chain="EVM", block_or_ledger="B2",
        event_time_ms=3000, tx_id="tx-2",
        asset="USDC", amount=495.0, finality="pending"
    );
    duplicate = CanonicalEvent(
        chain="EVM", block_or_ledger="B2-retry",
        event_time_ms=3500, tx_id="tx-2",
        asset="USDC", amount=495.0, finality="pending"
    );
    late = CanonicalEvent(
        chain="Solana", block_or_ledger="S7",
        event_time_ms=7000, tx_id="tx-3",
        asset="USDC", amount=510.0, finality="confirmed"
    );
    other_asset = CanonicalEvent(
        chain="EVM", block_or_ledger="B4",
        event_time_ms=4000, tx_id="tx-4",
        asset="WETH", amount=1.2, finality="final"
    );

    root ++> e1;
    root ++> e2;
    root ++> duplicate;
    root ++> late;
    root ++> other_asset;

    res = root spawn Correlation(horizon_ms=6000);

    assert res.cycles_found == 2, f"got {res.cycles_found}";
    assert len(res.visited) == 4, f"got {len(res.visited)}";
}

test "reorg retracts only pending EVM events before recomputation" {
    pending_evm = CanonicalEvent(
        chain="EVM", block_or_ledger="0xP",
        event_time_ms=1000, tx_id="evm-pending",
        asset="USDC", amount=100.0, finality="pending"
    );
    final_evm = CanonicalEvent(
        chain="EVM", block_or_ledger="0xF",
        event_time_ms=2000, tx_id="evm-final",
        asset="USDC", amount=100.0, finality="final"
    );
    pending_stellar = CanonicalEvent(
        chain="Stellar", block_or_ledger="L9",
        event_time_ms=3000, tx_id="stellar-pending",
        asset="USDC", amount=100.0, finality="pending"
    );

    root ++> pending_evm;
    root ++> final_evm;
    root ++> pending_stellar;

    reorg = root spawn Reorg();

    assert reorg.invalidations == 1, f"got {reorg.invalidations}";
    assert pending_evm.retracted == True, f"got {pending_evm.retracted}";
    assert final_evm.retracted == False, f"got {final_evm.retracted}";
    assert pending_stellar.retracted == False, f"got {pending_stellar.retracted}";

    res = root spawn Correlation(horizon_ms=6000);

    assert res.cycles_found == 2, f"got {res.cycles_found}";
    assert len(res.visited) == 2, f"got {len(res.visited)}";
}

test "typed ownership and bridge links remain directed" {
    asset = Asset(symbol="USDC", decimals=6);
    source = Wallet(address="0xSOURCE", chain="evm");
    destination = Wallet(address="SoDEST", chain="solana");
    event = CanonicalEvent(
        chain="EVM", block_or_ledger="0xABC",
        event_time_ms=1000, tx_id="tx-bridge",
        asset="USDC", amount=25.0, finality="final"
    );

    root ++> asset;
    root ++> source;
    root ++> event;

    event +>:BelongsTo(
        confidence=0.97, evidence="native-holding"
    ):+> source;
    source +>:BridgeLink(
        bridge="wormhole",
        confidence=0.92,
        evidence="wormhole-vaa-0xfeed"
    ):+> destination;

    assert len([root-->]) == 3, f"got {len([root-->])}";
    assert source in [event ->:BelongsTo:->], "missing ownership link";
    assert destination in [source ->:BridgeLink:->], "missing bridge link";
    assert len([destination ->:BridgeLink:->]) == 0, "bridge link is reversed";
}

