```jac
"""Snapshot field repair: model the correct/store parity defect.

Scenario: an entity has a list field ``decisions``. The bulk ``store`` tool
records it as a real nested array; the patch-style ``correct`` tool records
the same value as a JSON-encoded string. When a walker gathers fields for
the winning snapshot, stringified values yield garbage to any downstream
consumer that iterates them.
"""

node Entity {
    has entity_type: str = "";
    has entity_id: str = "";
}

node Field {
    has name: str = "";
    has value: str = "";
    has value_type: str = "str";
    has encoded: bool = False;
    has owner_id: str = "";
}

# ``Correct`` is the patch-style repair tool that, in the buggy
# implementation, JSON-stringifies array/object values before persisting.
edge Correct {
    has tool_name: str = "correct";
}

# ``Store`` is the bulk writer that preserves runtime types end-to-end.
edge Store {
    has tool_name: str = "store";
}

walker SnapshotCollector {
    has field_count: int = 0;
    has corrupted: int = 0;
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Entity entry {
        visit [-->];
    }

    can gather with Field entry {
        self.field_count += 1;
        kind = "STRINGIFIED" if here.encoded else "raw";
        line = f"{kind} {here.name}={here.value} ({here.value_type}) on {here.owner_id}";
        self.report.append(line);
        if here.encoded {
            self.corrupted += 1;
        }
        visit [-->];
    }
}

walker BackfillAdvisor {
    has advice: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can advise with Entity entry {
        visit [-->];
    }

    can scan with Field entry {
        if here.encoded {
            msg = (f"backfill: re-write field '{here.name}' on "
                   f"{here.owner_id} via store+target_id");
            self.advice.append(msg);
        }
        visit [-->];
    }
}

walker Reachable {
    has frontier: list[str] = [];
    has max_hops: int = 5;
    has visited: set[str] = set();
    has hops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can step with Entity entry {
        if self.hops >= self.max_hops {
            disengage;
        }
        if here.entity_id in self.visited {
            disengage;
        }
        self.visited.add(here.entity_id);
        self.frontier.append(here.entity_id);
        self.hops += 1;
        visit [-->] else {
            disengage;
        }
    }

    can noop with Field entry {
        visit [-->];
    }
}

# ``entity_type`` contract: a missing entity_type is an opaque error
# in the buggy tool; the fixed contract names the missing field.
def call_correct(entity_type: str | None, entity_id: str, fields: dict) -> dict {
    if entity_type is None {
        raise ValueError("entity_type is required for correct()") ;
    }
    return {"entity_type": entity_type, "entity_id": entity_id, "fields": fields};
}

with entry {
    # Two entities, one updated by store (good), one patched by correct
    # (the bug): ``decisions`` lands as a JSON-encoded string instead of
    # a real nested array.
    e1 = Entity(entity_type="session_digest", entity_id="ent_5a4b4c46a");
    e2 = Entity(entity_type="session_digest", entity_id="ent_5a4b4c46b");

    root ++> e1 ++> e2;

    # Bulk store wrote four real-array fields on e1.
    e1 +>:Store:+> Field(name="tasks_claimed", value="[1,2,3]", value_type="list[int]", encoded=False, owner_id="ent_5a4b4c46a");
    e1 +>:Store:+> Field(name="artifacts", value="[{\"id\":1}]", value_type="list[dict]", encoded=False, owner_id="ent_5a4b4c46a");
    e1 +>:Store:+> Field(name="scores", value="[0.9,0.8]", value_type="list[float]", encoded=False, owner_id="ent_5a4b4c46a");
    e1 +>:Store:+> Field(name="tags", value="[\"a\",\"b\"]", value_type="list[str]", encoded=False, owner_id="ent_5a4b4c46a");

    # A later single-field correct patch wrote ``decisions`` as a
    # JSON-encoded string — silent type corruption.
    e1 +>:Correct:+> Field(name="decisions", value="\"[{\\\"k\\\":1}]\"", value_type="list[dict]", encoded=True, owner_id="ent_5a4b4c46a");

    # The second entity has the same defect on two fields.
    e2 +>:Correct:+> Field(name="choices", value="\"[\\\"x\\\",\\\"y\\\"]\"", value_type="list[str]", encoded=True, owner_id="ent_5a4b4c46b");
    e2 +>:Correct:+> Field(name="weights", value="\"[0.1,0.2]\"", value_type="list[float]", encoded=True, owner_id="ent_5a4b4c46b");

    # Spawn the collector: it walks every Field and tallies corruption.
    collector = SnapshotCollector();
    root spawn collector;
    print("=== winning-snapshot field audit ===");
    for line in collector.report {
        print(line);
    }
    print(f"fields={collector.field_count} corrupted={collector.corrupted}");

    # Spawn the backfill advisor: it flags stringified fields and points
    # callers at the store+target_id workaround.
    advisor = BackfillAdvisor();
    root spawn advisor;
    print("=== backfill advisor ===");
    for line in advisor.advice {
        print(line);
    }

    # Spawn a bounded reachability walker from root through the entity
    # chain to confirm traversal terminates and reports visited ids.
    reacher = Reachable(max_hops=3);
    root spawn reacher;
    print("=== reachable entities ===");
    for ident in reacher.frontier {
        print(f"  - {ident}");
    }

    try {
        call_correct(None, "ent_x", {"k": 1});
    } except ValueError as err {
        print(f"contract error: {err}");
    }
}
```

