test "auditor flags unsettled records" {
    r0 = LoadedResource(title="ready", group=0, state=3);
    r1 = LoadedResource(title="pending", group=0, state=2);
    r2 = LoadedResource(title="free", group=1, state=0);
    root ++> r0;
    root ++> r1;
    root ++> r2;

    res = root spawn QuiescenceAuditor();

    assert len(res.bad) == 1, f"got {res.bad}";
    assert res.bad[0] == "pending", f"got {res.bad}";
}

test "acquisition publishes only state one from state zero" {
    free_record = LoadedResource(title="free", group=0, state=0);
    active_record = LoadedResource(title="active", group=0, state=2);
    root ++> free_record;
    root ++> active_record;

    res = root spawn Acquire(provider="L2-selected", family="MOD");

    assert free_record.state == 1, f"got {free_record.state}";
    assert active_record.state == 2, f"got {active_record.state}";
}

test "group release resets only the selected group" {
    target = LoadedResource(
        title="target", group=2, state=4, available=False
    );
    other = LoadedResource(
        title="other", group=3, state=2, available=False
    );
    root ++> target;
    root ++> other;

    res = root spawn Release(group_filter=2);

    assert target.state == 0, f"got {target.state}";
    assert target.available == True, f"got {target.available}";
    assert other.state == 2, f"got {other.state}";
    assert other.available == False, f"got {other.available}";
}

test "full reset clears every resource record" {
    r0 = LoadedResource(title="zero", group=0, state=1, available=False);
    r1 = LoadedResource(title="ready", group=4, state=3, available=False);
    r2 = LoadedResource(title="cancelled", group=5, state=4, available=False);
    root ++> r0;
    root ++> r1;
    root ++> r2;

    res = root spawn Release();

    assert r0.state == 0, f"got {r0.state}";
    assert r1.state == 0, f"got {r1.state}";
    assert r2.state == 0, f"got {r2.state}";
    assert r0.available == True, f"got {r0.available}";
    assert r1.available == True, f"got {r1.available}";
    assert r2.available == True, f"got {r2.available}";
}

