"""Rustscript admission pipeline: replace hand-rolled stage queues and AST recursion with typed edges and walkers."""

node DiagTarget {
    has span_id: str = "";
    has depth: int = 0;

    def headline() -> str {
        return "";
    }
}

node SourceUnit {
    has path: str = "";
    has byte_size: int = 0;
    has token_count: int = 0;
}

node AdmitStage {
    has name: str = "";
    has order: int = 0;
    has ok: bool = False;
}

node AstNode(DiagTarget) {
    has syntax_kind: str = "";

    override def headline() -> str {
        return self.syntax_kind;
    }
}

node SyntaxError(DiagTarget) {
    has reason: str = "";

    override def headline() -> str {
        return f"ERROR:{self.reason}";
    }
}

edge Inspects { }
edge FeedsInto { has note: str = ""; }
edge ChildOf { }

walker PipelineRunner {
    can start with Root entry {
        visit [->:Inspects:->] else { disengage; };
    }

    can preflight with SourceUnit entry {
        print(
            f"preflight {here.path}: {here.byte_size}B, "
            f"{here.token_count} tokens"
        );
        visit [->:FeedsInto:->] else { disengage; };
    }

    can run_stage with AdmitStage entry {
        verdict = "accept" if here.ok else "reject";
        print(f"  [{here.order}] {here.name}: {verdict}");
        visit [->:FeedsInto:->] else { disengage; };
    }
}

walker SyntaxPreorder {
    has max_depth: int = 8;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:ChildOf:->] else { disengage; };
    }

    can walk with AstNode | SyntaxError entry {
        cyclic = False;
        for sid in self.seen {
            if sid == here.span_id {
                cyclic = True;
            }
        }
        if cyclic {
            print(f"cycle guard: {here.headline()} @{here.span_id}");
            disengage;
        }
        self.seen.append(here.span_id);
        if here.depth > self.max_depth {
            print(
                f"depth cap d={here.depth}: "
                f"{here.headline()} @{here.span_id}"
            );
            disengage;
        }
        print(f"[{here.depth}] {here.headline()} ({here.span_id})");
        visit [->:ChildOf:->] else { disengage; };
    }
}

with entry {
    src = SourceUnit(path="main.rs", byte_size=256, token_count=58);
    lex = AdmitStage(name="lex", order=1, ok=True);
    parse = AdmitStage(name="parse", order=2, ok=True);
    admit = AdmitStage(name="subset_admit", order=3, ok=True);
    typechk = AdmitStage(name="typecheck", order=4, ok=False);

    root +>:Inspects:+> src;
    src +>:FeedsInto(note="lex"):+> lex;
    lex +>:FeedsInto(note="parse"):+> parse;
    parse +>:FeedsInto(note="admit"):+> admit;
    admit +>:FeedsInto(note="typecheck"):+> typechk;

    file = AstNode(syntax_kind="SourceFile", span_id="sf0", depth=0);
    item = AstNode(syntax_kind="FnItem", span_id="fn1", depth=1);
    body = AstNode(syntax_kind="BlockExpr", span_id="bx2", depth=2);
    call = AstNode(syntax_kind="MacroCall", span_id="mc3", depth=3);
    err = SyntaxError(reason="unknown variant", span_id="er4", depth=4);

    root +>:ChildOf:+> file;
    file +>:ChildOf:+> item;
    item +>:ChildOf:+> body;
    body +>:ChildOf:+> call;
    call +>:ChildOf:+> err;
    err +>:ChildOf:+> call;

    print("=== admission pipeline ===");
    root spawn PipelineRunner();
    print("=== AST preorder (depth cap 8, cycle guard) ===");
    root spawn SyntaxPreorder(max_depth=8);
}
