    res = root spawn DependencyAuditor();

    assert len(res.order) == 2, f"got {res.order}";
    assert res.order[0] == "#12:Benchmark split", f"got {res.order}";
    assert res.order[1] == "#14:Static workflow", f"got {res.order}";
    assert res.cycle_found == False, f"got {res.cycle_found}";
