```jac
"""Label-aware augmentation lineage: versioned policies, stable per-sample seeds, and dataset-to-model artifacts."""

edge HoldsSample {
    has slot: int = 0;
}

edge GovernedBy {
    has pipeline_seed: int = 0;
}

edge LineageFrom {
}

edge TrainsOn {
}

node SourceDataset {
    has name: str = "";
    has export_format: str = "yolo";
    has sample_count: int = 0;
}

node AugPolicy {
    has policy_name: str = "";
    has horizontal_flip_p: float = 0.5;
    has brightness_p: float = 0.2;
    has artifact_json: str = "";

    def serialize() -> str {
        return f'{{"hflip_p":{self.horizontal_flip_p},"bc_p":{self.brightness_p}}}';
    }
}

node TrainingSample {
    has sample_id: str = "";
    has sample_idx: int = 0;
    has class_labels: list[str] = [];
    has bbox_count: int = 0;
    has transform_seed: int = 0;
    has augmented: bool = False;
}

node AugmentedDataset {
    has name: str = "";
    has pipeline_seed: int = 0;
    has samples_ready: int = 0;
}

node TrainedModel {
    has model_name: str = "";
    has version: str = "";
}

walker LineageRunner {
    has pipeline_seed: int = 5191;
    has policy_artifact: str = "";
    has augmented_count: int = 0;
    has seen_ids: list[str] = [];

    can start with Root entry {
        print("=== augmentation lineage: source -> policy+seed -> dataset -> model ===");
        visit [-->];
    }

    can ingest_source with SourceDataset entry {
        print(f"Source dataset: {here.name} ({here.export_format}, {here.sample_count} samples)");
        visit [->:HoldsSample:->];
        visit [-->];
    }

    can materialize_policy with AugPolicy entry {
        here.artifact_json = here.serialize();
        self.policy_artifact = here.artifact_json;
        print(f"Policy artifact '{here.policy_name}': {here.artifact_json}");
        visit [-->];
    }

    can prepare_output with AugmentedDataset entry {
        self.pipeline_seed = here.pipeline_seed;
        print(f"Augmented dataset '{here.name}' using pipeline_seed={here.pipeline_seed}");
        visit [-->];
    }

    can augment_sample with TrainingSample entry {
        for sid in self.seen_ids {
            if sid == here.sample_id {
                print(f"CYCLE GUARD: sample {here.sample_id} already augmented — stopping");
                disengage;
            }
        }
        self.seen_ids.append(here.sample_id);
        stable_seed = self.pipeline_seed * 1000 + here.sample_idx;
        flip = (stable_seed % 2) == 0;
        here.transform_seed = stable_seed;
        here.augmented = True;
        self.augmented_count += 1;
        aug_tag = "HFLIP+labels" if flip else "labels-only";
        label_text = ",".join(here.class_labels);
        print(f"  [{here.sample_id}] seed={stable_seed} labels=[{label_text}] "
              f"bboxes={here.bbox_count} -> {aug_tag}");
    }

    can finalize_model with TrainedModel entry {
        print(f"Model artifact: {here.model_name} ({here.version})");
        print(f"Lineage complete: export -> policy({self.policy_artifact}) "
              f"+ seed({self.pipeline_seed}) -> {self.augmented_count} transformed samples -> model");
        disengage;
    }
}

with entry {
    source = SourceDataset(name="fiftyone_coco_yolo", export_format="yolo", sample_count=3);
    policy = AugPolicy(policy_name="detect_v1", horizontal_flip_p=0.5, brightness_p=0.2);
    aug = AugmentedDataset(name="aug_train_v1", pipeline_seed=5191);
    model = TrainedModel(model_name="yolov8n", version="run-001");

    s1 = TrainingSample(sample_id="img_001", sample_idx=1, class_labels=["person"], bbox_count=2);
    s2 = TrainingSample(sample_id="img_002", sample_idx=2, class_labels=["car", "person"], bbox_count=3);
    s3 = TrainingSample(sample_id="img_003", sample_idx=3, class_labels=["dog"], bbox_count=1);

    root ++> source ++> policy ++> aug ++> model;
    source +>:HoldsSample(slot=1):+> s1;
    source +>:HoldsSample(slot=2):+> s2;
    source +>:HoldsSample(slot=3):+> s3;
    policy +>:GovernedBy(pipeline_seed=5191):+> aug;
    source +>:LineageFrom:+> aug;
    aug +>:TrainsOn:+> model;

    root spawn LineageRunner();
}
```

jac_tests:
"""Tests for the augmentation lineage walker.

Verifies:
- policy is materialized into an artifact JSON and the policy node is visited
- the walker reaches every node in the source -> policy -> dataset -> model chain
- per-sample transform seeds are stable and derived from pipeline_seed + sample_idx
- the walker augments every sample exactly once (cycle-guard / seen_ids behavior)
- line-counts of typed edges match the declared lineage
"""

import io;
import from contextlib { redirect_stdout }

test "policy materialization produces an artifact JSON string" {
    root ++> SourceDataset(name="coco", export_format="yolo", sample_count=1)
        ++> AugPolicy(policy_name="p1", horizontal_flip_p=0.5, brightness_p=0.2)
        ++> AugmentedDataset(name="out", pipeline_seed=5191)
        ++> TrainedModel(model_name="m", version="v1");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageRunner();
    }
    out = buf.getvalue();

    # the walker should have produced a non-empty artifact JSON on the policy
    assert res.policy_artifact != "", f"expected policy_artifact to be set, got '{res.policy_artifact}'";
    assert "hflip_p" in res.policy_artifact, f"missing hflip_p in artifact: {res.policy_artifact}";
    assert "bc_p" in res.policy_artifact, f"missing bc_p in artifact: {res.policy_artifact}";
    assert "Policy artifact" in out, f"missing policy log: {out}";
}

test "walker traverses the full source to model lineage chain" {
    src = SourceDataset(name="coco", export_format="yolo", sample_count=2);
    pol = AugPolicy(policy_name="p1");
    ds = AugmentedDataset(name="out", pipeline_seed=42);
    mdl = TrainedModel(model_name="yolov8n", version="run-x");

    root ++> src ++> pol ++> ds ++> mdl;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageRunner();
    }
    out = buf.getvalue();

    assert "Source dataset:" in out, f"source not visited: {out}";
    assert "Augmented dataset" in out, f"dataset not visited: {out}";
    assert "Model artifact:" in out, f"model not visited: {out}";
    assert res.pipeline_seed == 42, f"pipeline_seed not propagated, got {res.pipeline_seed}";
}

test "per-sample transform seed is stable and seeded by pipeline_seed plus sample_idx" {
    src = SourceDataset(name="coco", export_format="yolo", sample_count=3);
    pol = AugPolicy(policy_name="p1");
    ds = AugmentedDataset(name="out", pipeline_seed=5191);
    mdl = TrainedModel(model_name="m", version="v");
    root ++> src ++> pol ++> ds ++> mdl;

    s1 = TrainingSample(sample_id="img_001", sample_idx=1, class_labels=["person"], bbox_count=2);
    s2 = TrainingSample(sample_id="img_002", sample_idx=2, class_labels=["car"], bbox_count=1);
    src +>:HoldsSample(slot=1):+> s1;
    src +>:HoldsSample(slot=2):+> s2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageRunner();
    }
    out = buf.getvalue();

    assert s1.augmented, f"sample 1 should be augmented: {out}";
    assert s2.augmented, f"sample 2 should be augmented: {out}";
    # stable seed = pipeline_seed * 1000 + sample_idx
    assert s1.transform_seed == 5191 * 1000 + 1, f"sample1 seed wrong: {s1.transform_seed}";
    assert s2.transform_seed == 5191 * 1000 + 2, f"sample2 seed wrong: {s2.transform_seed}";
    assert res.augmented_count == 2, f"expected 2 augmented, got {res.augmented_count}";
    assert "seed=5191001" in out, f"missing stable seed for s1: {out}";
    assert "seed=5191002" in out, f"missing stable seed for s2: {out}";
}

test "samples are augmented exactly once — cycle guard via seen_ids" {
    src = SourceDataset(name="coco", export_format="yolo", sample_count=2);
    pol = AugPolicy(policy_name="p1");
    ds = AugmentedDataset(name="out", pipeline_seed=10);
    mdl = TrainedModel(model_name="m", version="v");
    root ++> src ++> pol ++> ds ++> mdl;

    s1 = TrainingSample(sample_id="img_dup", sample_idx=1, class_labels=["x"], bbox_count=1);
    s2 = TrainingSample(sample_id="img_dup", sample_idx=1, class_labels=["x"], bbox_count=1);
    src +>:HoldsSample(slot=1):+> s1;
    src +>:HoldsSample(slot=2):+> s2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageRunner();
    }
    out = buf.getvalue();

    # seen_ids should record each encountered sample_id at most once;
    # walker increments augmented_count once per actual augmentation work.
    assert res.augmented_count == 1, f"expected 1 augmentation due to cycle guard, got {res.augmented_count}";
    assert "CYCLE GUARD" in out, f"expected CYCLE GUARD message: {out}";
}

test "lineage edge topology holds the shape declared in the issue" {
    src = SourceDataset(name="coco", export_format="yolo", sample_count=2);
    pol = AugPolicy(policy_name="p1");
    ds = AugmentedDataset(name="out", pipeline_seed=5191);
    mdl = TrainedModel(model_name="m", version="v");
    root ++> src ++> pol ++> ds ++> mdl;

    pol +>:GovernedBy(pipeline_seed=5191):+> ds;
    src +>:LineageFrom:+> ds;
    ds +>:TrainsOn:+> mdl;

    s1 = TrainingSample(sample_id="a", sample_idx=1, class_labels=["p"], bbox_count=1);
    src +>:HoldsSample(slot=1):+> s1;

    assert len([pol ->:GovernedBy:->]) == 1, f"expected one GovernedBy edge from policy";
    assert len([src ->:LineageFrom:->]) == 1, f"expected one LineageFrom edge from source";
    assert len([ds ->:TrainsOn:->]) == 1, f"expected one TrainsOn edge from dataset";
    assert len([src ->:HoldsSample:->]) == 1, f"expected one HoldsSample edge from source";
    # seed carried on the GovernedBy edge equals pipeline_seed
    for e in [pol ->:GovernedBy:->] {
        assert e.pipeline_seed == 5191, f"pipeline_seed on GovernedBy wrong: {e.pipeline_seed}";
    }
}

