"""Control Tower review queue: append-only exact-head tickets, pending resolution, and fail-closed head verification."""

node QueueEntry {
    has pr: int = 0;
    has seq: int = 0;

    def ticket_key() -> str {
        return "";
    }

    def is_result() -> bool {
        return False;
    }
}

node ControlTower {
    has title: str = "ISSUE-453 Independent Review Queue";
}

node PullRequest {
    has pr: int = 0;
    has current_head: str = "";
    has title: str = "";
}

node ReviewRequest(QueueEntry) {
    has exact_head: str = "";
    has priority: int = 1;

    override def ticket_key() -> str {
        return f"{self.pr}:{self.exact_head}";
    }
}

node ReviewResult(QueueEntry) {
    has reviewed_head: str = "";
    has verdict: str = "";
    has review_channel: str = "EXACT_HEAD_COMMENT_ATTESTATION";

    override def ticket_key() -> str {
        return f"{self.pr}:{self.reviewed_head}";
    }

    override def is_result() -> bool {
        return True;
    }
}

edge Appended {
    has seq: int = 0;
}

edge ForPR { }

walker QueueAuditor {
    has pending_keys: list[str] = [];
    has resolved_keys: list[str] = [];
    has seen_seq: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with ControlTower entry {
        print(f"Scanning {here.title}");
        visit [->:Appended:->] else { disengage; };
    }

    can scan with ReviewRequest | ReviewResult entry {
        if here.seq in self.seen_seq {
            print(f"CYCLE blocked at seq={here.seq}");
            disengage;
        }
        self.seen_seq.append(here.seq);
        key = here.ticket_key();
        if here.is_result() {
            if key not in self.resolved_keys {
                self.resolved_keys.append(key);
            }
            new_pending: list[str] = [];
            for ticket_key in self.pending_keys {
                if ticket_key != key {
                    new_pending.append(ticket_key);
                }
            }
            self.pending_keys = new_pending;
        } else {
            if key not in self.resolved_keys and key not in self.pending_keys {
                self.pending_keys.append(key);
            }
        }
        visit [->:Appended:->] else { disengage; };
    }

    can summarize with ControlTower exit {
        print(f"Resolved tickets: {len(self.resolved_keys)}; pending: {len(self.pending_keys)}");
        for ticket_key in self.pending_keys {
            print(f"  PENDING {ticket_key}");
        }
    }
}

walker HeadVerifier {
    has ticket_head: str = "";
    has ticket_pr: int = 0;
    has ticket_seq: int = 0;
    has verified: int = 0;
    has blocked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with ControlTower entry {
        print("Verifying exact-head bindings (fail-closed on stale heads)");
        visit [->:Appended:->] else { disengage; };
    }

    can verify_request with ReviewRequest entry {
        self.ticket_head = here.exact_head;
        self.ticket_pr = here.pr;
        self.ticket_seq = here.seq;
        visit [->:ForPR:->] else {
            print(f"FAIL-CLOSED: REVIEW_REQUEST/v1 seq={here.seq} has no PR binding");
            self.blocked += 1;
        };
        visit [->:Appended:->] else { disengage; };
    }

    can bind_head with PullRequest entry {
        if here.pr != self.ticket_pr {
            disengage;
        }
        if here.current_head != self.ticket_head {
            print(
                f"FAIL-CLOSED: PR #{self.ticket_pr} seq={self.ticket_seq} "
                f"wants {self.ticket_head} but current_head is {here.current_head}"
            );
            self.blocked += 1;
        } else {
            print(
                f"HEAD OK: PR #{self.ticket_pr} seq={self.ticket_seq} "
                f"exact_head {self.ticket_head} matches current_head"
            );
            self.verified += 1;
        }
    }

    can record_result with ReviewResult entry {
        channel_note = "attestation" if here.review_channel == "EXACT_HEAD_COMMENT_ATTESTATION" else here.review_channel;
        print(
            f"RESULT: PR #{here.pr} {here.reviewed_head} -> {here.verdict} "
            f"via {channel_note}"
        );
        visit [->:Appended:->] else { disengage; };
    }

    can report with ControlTower exit {
        print(f"HeadVerifier: verified={self.verified}, blocked={self.blocked}");
    }
}

with entry {
    tower = ControlTower();
    pr452 = PullRequest(
        pr=452,
        current_head="855168549ab71852f3505d53fef8b11c12bf2ff8",
        title="R149 task release impact composition gate"
    );

    req1 = ReviewRequest(
        pr=452,
        exact_head="de550c6e7bc80b6346b2bbbed13addd25ac67f0d",
        priority=1,
        seq=1
    );
    res1 = ReviewResult(
        pr=452,
        reviewed_head="de550c6e7bc80b6346b2bbbed13addd25ac67f0d",
        verdict="CHANGES_REQUIRED",
        seq=2
    );
    req2 = ReviewRequest(
        pr=452,
        exact_head="855168549ab71852f3505d53fef8b11c12bf2ff8",
        priority=1,
        seq=3
    );
    res2 = ReviewResult(
        pr=452,
        reviewed_head="855168549ab71852f3505d53fef8b11c12bf2ff8",
        verdict="ACCEPT",
        review_channel="EXACT_HEAD_COMMENT_ATTESTATION",
        seq=4
    );
    req3 = ReviewRequest(
        pr=452,
        exact_head="de550c6e7bc80b6346b2bbbed13addd25ac67f0d",
        priority=2,
        seq=5
    );

    root ++> tower;
    tower +>:Appended(seq=1):+> req1;
    req1 +>:ForPR:+> pr452;
    req1 +>:Appended(seq=2):+> res1;
    res1 +>:Appended(seq=3):+> req2;
