"""Regression tests for Hello Algo Interactive core: stable entity IDs,
semantic markers, O(1) snapshot frames, step-guarded timeline playback,
and backward seek by marker step."""

import io;
import from contextlib { redirect_stdout }

def build_run {
    run = AlgoRun(name="bubble-sort", step_guard=10000);
    e1 = Entity(entity_id="e1", value=3, slot=0);
    e2 = Entity(entity_id="e2", value=1, slot=1);
    e3 = Entity(entity_id="e3", value=2, slot=2);
    run +>:OwnsEntity:+> e1;
    run +>:OwnsEntity:+> e2;
    run +>:OwnsEntity:+> e3;
    m0 = Marker(step=0, event_kind="init", note="layout e1@0,e2@1,e3@2");
    f0 = Frame(step=0, layout="e1@0,e2@1,e3@2");
    m0 +>:SnapshotOf:+> f0;
    run +>:NextMarker:+> m0;
    m1 = Marker(step=1, event_kind="compare", note="e1(3) vs e2(1) - highlight");
    f1 = Frame(step=1, layout="e1@0,e2@1,e3@2");
    m1 +>:SnapshotOf:+> f1;
    m0 +>:NextMarker:+> m1;
    m2 = Marker(step=2, event_kind="swap", note="swap by ID: e1<->e2");
    f2 = Frame(step=2, layout="e2@0,e1@1,e3@2");
    m2 +>:SnapshotOf:+> f2;
    m1 +>:NextMarker:+> m2;
    m3 = Marker(step=3, event_kind="compare", note="e1(3) vs e3(2) - highlight");
    f3 = Frame(step=3, layout="e2@0,e1@1,e3@2");
    m3 +>:SnapshotOf:+> f3;
    m2 +>:NextMarker:+> m3;
    m4 = Marker(step=4, event_kind="swap", note="swap by ID: e1<->e3");
    f4 = Frame(step=4, layout="e2@0,e3@1,e1@2");
    m4 +>:SnapshotOf:+> f4;
    m3 +>:NextMarker:+> m4;
    return [run, m0, m1, m2, m3, m4];
}

test "EntityRegistrar walks OwnsEntity edges and exposes stable IDs by string, not slot" {
    (run, _, _, _, _, _) = build_run();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        run spawn EntityRegistrar();
    }
    out = buf.getvalue();
    assert "e1" in out and "e2" in out and "e3" in out, f"missing entity IDs: {out}";
    assert "origin_slot=0" in out and "origin_slot=1" in out and "origin_slot=2" in out,
        f"missing origin slot bindings: {out}";
    assert out.count("value=") == 3, f"expected 3 entity reads, got {out}";
}

test "StepGuardedPlayer traverses the full NextMarker chain, counts markers, and never trips the guard" {
    (run, _, _, _, _, _) = build_run();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = run spawn StepGuardedPlayer();
    }
    out = buf.getvalue();
    assert res.guard_tripped == False, f"guard tripped prematurely: {res.steps_taken}";
    assert res.steps_taken == 5, f"expected 5 markers walked, got {res.steps_taken}";
    assert out.count("Timeline end") == 1, f"expected exactly one Timeline end, got: {out}";
    assert "init" in out and "compare" in out and "swap" in out,
        f"missing event kinds: {out}";
    assert "Step Guard HALT" not in out, f"guard halted on normal run: {out}";
}

test "StepGuard trips exactly when steps_taken exceeds step_guard and disengages cleanly" {
    (run_orig, m0, _, _, _, _) = build_run();
    guard_run = AlgoRun(name="guard-demo", step_guard=2);
    guard_run +>:NextMarker:+> m0;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = guard_run spawn StepGuardedPlayer();
    }
    out = buf.getvalue();
    assert res.guard_tripped == True, "guard should have tripped with limit=2";
    assert res.steps_taken > res.step_limit, f"trip threshold broken: {res.steps_taken} vs {res.step_limit}";
    assert "Step Guard HALT" in out, f"missing halt message: {out}";
    assert "Timeline end" not in out, f"should not reach timeline end after trip: {out}";
    assert "init" in out and "compare" in out, f"expected first two markers before halt: {out}";
