    assert "Seek failed" not in out, f"seek should have succeeded: {out}";
}

test "SnapshotSeeker from an unrelated marker reports seek failure and leaves found_layout empty" {
    (run_orig, m0, _, _, _, _) = build_run();
    orphan = Marker(step=99, event_kind="init", note="unreachable");
    f99 = Frame(step=99, layout="never");
