    assert "STATUS_STACK_OVERFLOW" in out, f"missing overflow marker: {out}";
    assert "0xc00000fd" in out, f"missing status code: {out}";
    assert "zxfD3mJTKEx8P" in out, f"missing handler addr: {out}";
    assert storm.stack_frames >= 12, f"expected >=12 frames, got {storm.stack_frames}";
    assert idle.crashed is True, f"handler should be flagged crashed";
}

test "stack limit caps the recursion count to the configured threshold" {
    root ++> Application(title="osu!", file_version="1.3.3.7");
