    assert storm.stack_frames == 5, (
        f"walker must stop exactly at the stack limit, got {storm.stack_frames}"
    );
    assert idle.call_depth == 5, (
        f"handler should be visited exactly 5 times, got {idle.call_depth}"
    );
    assert idle.crashed is True, "idle handler should be flagged crashed at guard";
}

