"""Test annex for V2-FE-020 cache invalidation behavior."""

import io;
import from contextlib { redirect_stdout }

test "confirmed_tx downgrades wallet and cascades to dependents" {
    wallet = QueryEntry(domain="wallet", cache_key="0xabc", freshness="safe");
    claims = QueryEntry(domain="claims", cache_key="claim:1", freshness="finalized");
    reputation = QueryEntry(domain="reputation", cache_key="rep:7", freshness="finalized");
    evidence = QueryEntry(domain="evidence", cache_key="evid:42", freshness="finalized");

    claims +>:DependsOn:+> wallet;
    reputation +>:DependsOn:+> claims;

    reorg_tx = ConfirmedTx(tx_hash="0xdeadbeef", kind="confirmed_tx", downgrade_to="reorged");
    reorg_tx +>:Invalidates:+> wallet;
    root ++> reorg_tx;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = CacheInvalidator();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert wallet.freshness == "reorged", f"wallet should be reorged, got {wallet.freshness}";
    assert claims.freshness == "reorged", f"claims should cascade to reorged, got {claims.freshness}";
    assert reputation.freshness == "reorged", f"reputation should cascade to reorged, got {reputation.freshness}";
    assert evidence.freshness == "finalized", f"evidence untouched, got {evidence.freshness}";
    assert auditor.invalidated_count == 3, f"expected 3 invalidations, got {auditor.invalidated_count}";
    assert "[TRIGGER] confirmed_tx targets downgrade to reorged" in out, f"missing trigger log: {out}";
    assert "wallet:0xabc" in out and "claims:claim:1" in out and "reputation:rep:7" in out, f"missing invalidate logs: {out}";
}

test "projection_event downgrades only its affected domain to observed" {
    wallet = QueryEntry(domain="wallet", cache_key="0xabc", freshness="finalized");
    claims = QueryEntry(domain="claims", cache_key="claim:1", freshness="finalized");
    evidence = QueryEntry(domain="evidence", cache_key="evid:42", freshness="finalized");
    reputation = QueryEntry(domain="reputation", cache_key="rep:7", freshness="finalized");

    claims +>:DependsOn:+> wallet;
    reputation +>:DependsOn:+> claims;

    projection = ProjectionEvent(
        stream="rounds",
        affected_domain="evidence",
        kind="projection",
        downgrade_to="observed"
    );
    projection +>:Invalidates:+> evidence;
    root ++> projection;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = CacheInvalidator();
        root spawn auditor;
    }

    assert evidence.freshness == "observed", f"evidence should be observed, got {evidence.freshness}";
    assert wallet.freshness == "finalized", f"wallet untouched, got {wallet.freshness}";
    assert claims.freshness == "finalized", f"claims untouched (no depends edge from evidence), got {claims.freshness}";
    assert reputation.freshness == "finalized", f"reputation untouched, got {reputation.freshness}";
    assert auditor.invalidated_count == 1, f"expected 1 invalidation, got {auditor.invalidated_count}";
    assert "[TRIGGER] projection targets downgrade to observed" in buf.getvalue();
}

test "duplicate dependent key is not double-invalidated" {
    wallet = QueryEntry(domain="wallet", cache_key="0xshared", freshness="safe");
    claims = QueryEntry(domain="claims", cache_key="claim:1", freshness="finalized");
    evidence = QueryEntry(domain="evidence", cache_key="evid:42", freshness="finalized");
    reputation = QueryEntry(domain="reputation", cache_key="rep:7", freshness="finalized");

    # Two distinct dependents pointing to the same shared key (same domain:cache_key)
    # The walker's seen_keys guard prevents re-invalidating wallet twice.
    claims +>:DependsOn:+> wallet;
    evidence +>:DependsOn:+> wallet;
    reputation +>:DependsOn:+> claims;

    reorg_tx = ConfirmedTx(tx_hash="0xcafe", kind="confirmed_tx", downgrade_to="reorged");
    reorg_tx +>:Invalidates:+> wallet;
    root ++> reorg_tx;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = CacheInvalidator();
        root spawn auditor;
    }

    # wallet is referenced by both claims and evidence via DependsOn, but should
    # only count as one invalidation because of the seen_keys guard.
    invalidations_for_wallet = [
        l for l in buf.getvalue().splitlines() if "wallet:0xshared" in l and "[INVALIDATE]" in l
    ];
    assert len(invalidations_for_wallet) == 1, f"wallet should invalidate once, got {len(invalidations_for_wallet)}: {invalidations_for_wallet}";
    assert wallet.freshness == "reorged", f"wallet should be reorged, got {wallet.freshness}";
}

test "trigger with no Invalidates edge does not cascade" {
    claims = QueryEntry(domain="claims", cache_key="claim:1", freshness="finalized");
    reputation = QueryEntry(domain="reputation", cache_key="rep:7", freshness="finalized");
    reputation +>:DependsOn:+> claims;

    # No Invalidates edge from this trigger to any QueryEntry.
    reorg_tx = ConfirmedTx(tx_hash="0xdead", kind="confirmed_tx", downgrade_to="reorged");
    root ++> reorg_tx;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = CacheInvalidator();
        root spawn auditor;
    }

    assert claims.freshness == "finalized", f"claims untouched, got {claims.freshness}";
    assert reputation.freshness == "finalized", f"reputation untouched, got {reputation.freshness}";
    assert auditor.invalidated_count == 0, f"no entries should be invalidated, got {auditor.invalidated_count}";
    assert auditor.seen_keys == [], f"seen_keys should be empty, got {auditor.seen_keys}";
    assert "[TRIGGER]" in buf.getvalue(), "trigger should still log";
}

test "data states observed safe finalized reorged are all distinct" {
    # The four required freshness states from the spec must round-trip correctly
    # through the invalidation flow.
    wallet = QueryEntry(domain="wallet", cache_key="0x1", freshness="finalized");
    claims = QueryEntry(domain="claims", cache_key="claim:1", freshness="safe");
    evidence = QueryEntry(domain="evidence", cache_key="evid:1", freshness="observed");
    reputation = QueryEntry(domain="reputation", cache_key="rep:1", freshness="reorged");

    assert wallet.freshness == "finalized";
    assert claims.freshness == "safe";
    assert evidence.freshness == "observed";
    assert reputation.freshness == "reorged";

    # All four values must be distinct from each other.
    states = {wallet.freshness, claims.freshness, evidence.freshness, reputation.freshness};
    assert len(states) == 4, f"the four states must be distinct, got {states}";

    # A reorg trigger should demote safe -> reorged on claims.
    claims +>:DependsOn:+> wallet;
    reorg_tx = ConfirmedTx(tx_hash="0xbeef", kind="confirmed_tx", downgrade_to="reorged");
    reorg_tx +>:Invalidates:+> claims;
    root ++> reorg_tx;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = CacheInvalidator();
        root spawn auditor;
    }

    assert claims.freshness == "reorged", f"claims should be reorged, got {claims.freshness}";
    assert "safe to reorged" in buf.getvalue(), "transition log missing";
}

