    first = graph.add_task(unit, build);
    assert first == True, f"initial edge should be accepted got {first}";
    second = graph.add_task(build, unit);
    assert second == False, f"two-cycle should be rejected got {second}";
    assert unit not in [build ->:Requires:->], f"cycle edge must not be added";
    assert build in [unit ->:Requires:->], f"original prerequisite edge should remain";
