        lambda_id="f_body",
        body_hint="recursive self-call",
        recursive=True
    );

    inner +>:EscapedFrom:+> result;
    result +>:Nested:+> elem;
    elem +>:Nested:+> env;
    elem +>:Holds:+> tag;
    env +>:Holds:+> closure;
    closure +>:ResolvesTo:+> stored;
    stored +>:Captures:+> env;

    analyzer = EscapeAnalyzer();
    root spawn analyzer;

