"""Tests for the reaper fail-open demo (issue #22). Each test builds its own
graph and spawns walkers on state it built itself."""

import io;
import from contextlib { redirect_stdout }

test "fail-closed counter distinguishes empty from live" {
    rt = Root();
    fresh = WorkflowRoot(title="fresh");
    stale = WorkflowRoot(title="stale");
    rt ++> fresh;
    rt ++> stale;

    # fresh has a live descendant chain
    a = Issue(title="a", kind="task", live=True);
    b = Issue(title="b", kind="task", live=False);
    w = Wisp(title="w", live=True);
    fresh +>:Spawns:+> a;
    fresh +>:DependsOn:+> b;
    a +>:Spawns:+> w;

    # stale is genuinely empty — no descendants at all
    buf = io.StringIO();
    with redirect_stdout(buf) {
        r = CountReaper();
        rt spawn r;
    }
    out = buf.getvalue();

    assert r.known_live == 1, f"expected 1 live root, got {r.known_live}";
    assert r.known_empty == 1, f"expected 1 known-empty root, got {r.known_empty}";
    assert r.unknown == 0, f"expected 0 unknown, got {r.unknown}";
    assert "[LIVE] fresh" in out, f"missing LIVE marker for fresh: {out}";
    assert "[KNOWN-EMPTY] stale" in out, f"missing KNOWN-EMPTY marker for stale: {out}";
    assert "[FAIL-CLOSED]" not in out, f"unexpected FAIL-CLOSED marker: {out}";
    assert r.stale_roots == ["stale"], f"stale_roots should be ['stale'], got {r.stale_roots}";
}

test "fail-closed counter records unknown distinctly and never collapses to zero" {
    rt = Root();
    r1 = WorkflowRoot(title="r1");
    r2 = WorkflowRoot(title="r2");
