    assert "[NEW] r1: outcome=UNKNOWN, refusing to reap" in out, f"missing r1 NEW marker: {out}";
    assert "[NEW] r2: outcome=UNKNOWN, refusing to reap" in out, f"missing r2 NEW marker: {out}";

    # OLD wrapper would have read both as count=0 (the silent-empty bug).
    # The bug shows up as "[OLD] ... count_read_as=0" appearing alongside
    # a query_failed=True — proving the old wrapper cannot distinguish
    # "timeout" from "no rows."
    assert "[OLD] r1: query_failed=True, count_read_as=0" in out, f"missing OLD bug evidence for r1: {out}";
    assert "[OLD] r2: query_failed=True, count_read_as=0" in out, f"missing OLD bug evidence for r2: {out}";
