    late = DoLet(name="moves", is_jsx=True, inserted_index=1);
    block +>:ContainsLet(order_index=0):+> early;
    block +>:ContainsLet(order_index=1):+> late;

    ref = ExprRef(ident="xIsNext", is_record_field=False);
    late +>:RefersTo(is_forward=False):+> ref;

