"""Versioned ordering tokens for naming disambiguation.

Models the issue's central scenario: ranking siblings that share a parent set
via an ordering token stamped with a version. A walker migrates legacy
unversioned tokens to the current version on load, preserving disambiguation
semantics without hand-rolled adjacency maps or recursion plumbing.
"""

node OrderedItem {
    has label: str = "";
    has coord: tuple[float, float, float] = (0.0, 0.0, 0.0);
    has rank_token: str = "";
    has rank_version: int = 0;
}

node SiblingSet {
    has title: str = "";
    has ordering_version: int = 0;
}

edge Grouped {
    has rank_hint: int = 0;
}

edge RanksWith {
    has token: str = "";
    has version: int = 0;
}

node MigrationLog {
    has count: int = 0;
    has target_version: int = 0;
}

walker RankMigrator {
    has target_version: int = 2;
    has migrated: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_set with SiblingSet entry {
        outdated = [item for item in [-->] if isinstance(item, OrderedItem) and item.rank_version < self.target_version];
        for item in outdated {
            stamped = f"v{self.target_version}#{item.coord[0]:.3f},{item.coord[1]:.3f},{item.coord[2]:.3f}";
            item.rank_token = stamped;
            item.rank_version = self.target_version;
            self.migrated += 1;
        }
        if outdated {
            print(f"[migrator] set '{here.title}': rewrote {len(outdated)} token(s) to v{self.target_version}");
        }
        visit [-->];
    }

    can finalize with MigrationLog entry {
        here.count = self.migrated;
        here.target_version = self.target_version;
        print(f"[migrator] wrote MigrationLog: count={here.count}, target_version={here.target_version}");
        disengage;
    }
}

walker NamingAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with SiblingSet entry {
        items = [item for item in [-->] if isinstance(item, OrderedItem)];
        items_sorted = sorted(items, key=lambda (it: OrderedItem) -> str: it.rank_token);
        for it in items_sorted {
            verdict = "ok" if it.rank_version == 2 else "STALE";
            print(f"  [{verdict}] {it.label} token={it.rank_token}");
        }
        visit [-->];
    }

    can done with MigrationLog entry {
        disengage;
    }
}

with entry {
    # A sibling set with three items, two of which carry the legacy
    # unversioned lex-by-coordinate token and one already stamped v1.
    set_a = SiblingSet(title="Edges-of-Face-A", ordering_version=2);

    item1 = OrderedItem(label="edge-1", coord=(0.5, 0.5, 0.0), rank_token="0.500,0.500,0.000", rank_version=0);
    item2 = OrderedItem(label="edge-2", coord=(0.5, 0.5, 0.0), rank_token="v1#0.500,0.500,0.000", rank_version=1);
    item3 = OrderedItem(label="edge-3", coord=(0.7, 0.3, 0.0), rank_token="v1#0.700,0.300,0.000", rank_version=1);

    root ++> set_a;
    set_a +>:Grouped:+> item1;
    set_a +>:Grouped:+> item2;
    set_a +>:Grouped:+> item3;

    log = MigrationLog(count=0, target_version=0);
    set_a +>:Grouped:+> log;

    print("== before migration ==");
    root spawn NamingAuditor();

    print("== running migrator ==");
    root spawn RankMigrator(target_version=2);

    print("== after migration ==");
    root spawn NamingAuditor();
}
```

jac_tests:
import io;
import from contextlib { redirect_stdout }

test "migrator stamps legacy unversioned tokens to target version" {
    set_a = SiblingSet(title="face-a");
    item = OrderedItem(
        label="edge-1",
        coord=(0.5, 0.5, 0.0),
        rank_token="0.500,0.500,0.000",
        rank_version=0,
    );
    log = MigrationLog();
    root ++> set_a;
    set_a +>:Grouped:+> item;
    set_a +>:Grouped:+> log;

    res = root spawn RankMigrator(target_version=2);

    assert item.rank_version == 2, f"expected rank_version 2, got {item.rank_version}";
    assert item.rank_token == "v2#0.500,0.500,0.000", f"bad stamped token: {item.rank_token}";
    assert res.migrated == 1, f"expected 1 migration, got {res.migrated}";
}

test "migrator rewrites sub-target versions but skips current" {
    set_a = SiblingSet(title="mixed-set");
    legacy = OrderedItem(
        label="legacy",
        coord=(0.1, 0.2, 0.3),
        rank_token="0.100,0.200,0.300",
        rank_version=0,
    );
    v1_item = OrderedItem(
        label="v1-item",
        coord=(0.4, 0.5, 0.6),
        rank_token="v1#0.400,0.500,0.600",
        rank_version=1,
    );
    current = OrderedItem(
        label="current",
        coord=(0.9, 0.8, 0.7),
        rank_token="v2#0.900,0.800,0.700",
        rank_version=2,
    );
    log = MigrationLog();
    root ++> set_a;
    set_a +>:Grouped:+> legacy;
    set_a +>:Grouped:+> v1_item;
    set_a +>:Grouped:+> current;
    set_a +>:Grouped:+> log;

    res = root spawn RankMigrator(target_version=2);

    assert legacy.rank_token == "v2#0.100,0.200,0.300", f"legacy not migrated: {legacy.rank_token}";
    assert v1_item.rank_token == "v2#0.400,0.500,0.600", f"v1 not migrated: {v1_item.rank_token}";
    assert current.rank_token == "v2#0.900,0.800,0.700", f"current item rewritten: {current.rank_token}";
    assert res.migrated == 2, f"expected 2 migrations, got {res.migrated}";
    assert log.count == 2, f"log count expected 2, got {log.count}";
    assert log.target_version == 2, f"log target_version expected 2, got {log.target_version}";
}

test "auditor flags stale tokens before migration" {
    set_a = SiblingSet(title="audit-pre");
    stale = OrderedItem(
        label="stale-edge",
        coord=(0.5, 0.5, 0.0),
        rank_token="0.500,0.500,0.000",
        rank_version=0,
    );
    fresh = OrderedItem(
        label="fresh-edge",
        coord=(0.7, 0.3, 0.0),
        rank_token="v2#0.700,0.300,0.000",
        rank_version=2,
    );
    log = MigrationLog();
    root ++> set_a;
    set_a +>:Grouped:+> stale;
    set_a +>:Grouped:+> fresh;
    set_a +>:Grouped:+> log;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn NamingAuditor();
    }
    out = buf.getvalue();

    assert "[STALE]" in out, f"missing STALE verdict: {out}";
    assert "stale-edge" in out, f"stale item not reported: {out}";
    assert "[ok] fresh-edge" in out, f"fresh item not ok: {out}";
}

test "auditor reports all ok after versioned migration" {
    set_a = SiblingSet(title="audit-post");
    item1 = OrderedItem(
        label="edge-1",
        coord=(0.5, 0.5, 0.0),
        rank_token="0.500,0.500,0.000",
        rank_version=0,
    );
    item2 = OrderedItem(
        label="edge-2",
        coord=(0.5, 0.5, 0.0),
        rank_token="v1#0.500,0.500,0.000",
        rank_version=1,
    );
    item3 = OrderedItem(
        label="edge-3",
        coord=(0.7, 0.3, 0.0),
        rank_token="v1#0.700,0.300,0.000",
        rank_version=1,
    );
    log = MigrationLog();
    root ++> set_a;
    set_a +>:Grouped:+> item1;
    set_a +>:Grouped:+> item2;
    set_a +>:Grouped:+> item3;
    set_a +>:Grouped:+> log;

    root spawn RankMigrator(target_version=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn NamingAuditor();
    }
    out = buf.getvalue();

    assert "[STALE]" not in out, f"unexpected STALE after migration: {out}";
    assert "[ok] edge-1" in out, f"edge-1 not ok: {out}";
    assert "[ok] edge-2" in out, f"edge-2 not ok: {out}";
    assert "[ok] edge-3" in out, f"edge-3 not ok: {out}";
    assert item1.rank_version == 2, f"edge-1 version not bumped: {item1.rank_version}";
    assert item2.rank_version == 2, f"edge-2 version not bumped: {item2.rank_version}";
    assert item3.rank_version == 2, f"edge-3 version not bumped: {item3.rank_version}";
}

