```jac
"""Static-library link requirement propagation across package dependencies.

Models the essential scenario from the issue: a binary depends on wrapper
packages that own native static archives and link metadata. A walker descends
the dependency graph, harvests each wrapper's typed link requirements, and
merges them in dependency-declaration order so static-linker ordering is
preserved. Diagnostics name the declaring package for each requirement.
"""

node Package {
    has name: str = "";
    has kind: str = "binary";
}

node StaticLib {
    has name: str = "";
    has libs: list[str] = [];
    has search_paths: list[str] = [];
    has args: list[str] = [];
}

edge DependsOn {
    has declared_by: str = "";
}

edge HasLib {
    has search_path: str = "";
}

walker LinkPlanner {
    has ordered_libs: list[str] = [];
    has ordered_paths: list[str] = [];
    has ordered_args: list[str] = [];
    has provenance: dict[str, str] = {};

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        visit [->:DependsOn:->];
    }

    can harvest with StaticLib entry {
        lib_label = "";
        for lib in here.libs {
            lib_label = lib;
            if lib_label not in self.ordered_libs {
                self.ordered_libs.append(lib_label);
                self.provenance[lib_label] = here.name;
            }
        }
        for path in here.search_paths {
            path_label = path;
            if path_label not in self.ordered_paths {
                self.ordered_paths.append(path_label);
            }
        }
        arg_label = "";
        for arg in here.args {
            arg_label = arg;
            if arg_label not in self.ordered_args {
                self.ordered_args.append(arg_label);
                self.provenance[arg_label] = here.name;
            }
        }
        visit [->:HasLib:->];
    }
}

walker LinkDiagnostics {
    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        visit [->:DependsOn:->];
    }

    can probe with StaticLib entry {
        missing = "raylib";
        if missing in here.libs {
            print(f"missing native lib '{missing}' from wrapper "
                  f"'{here.name}' (declared in its (link ...))");
        }
        visit [->:HasLib:->];
    }
}

with entry {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3", "m"],
        search_paths=["vendor/sqlite/lib", "vendor/os/lib"],
        args=["-lpthread"]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib", "m"],
        search_paths=["vendor/raylib/lib"],
        args=["-ldl", "-lpthread"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;
    sqlite_wrapper +>:HasLib(search_path="vendor/sqlite/lib"):+> StaticLib(name="sqlite-archive");
    raylib_wrapper +>:HasLib(search_path="vendor/raylib/lib"):+> StaticLib(name="raylib-archive");

    planner = LinkPlanner();
    root spawn planner;

    print("Effective ordered link plan for app-binary:");
    print(f"  libs      = {planner.ordered_libs}");
    print(f"  paths     = {planner.ordered_paths}");
    print(f"  args      = {planner.ordered_args}");

    diag = LinkDiagnostics();
    root spawn diag;
}
```

jac_tests:
"""Tests for static-library link requirement propagation.

Verifies the behaviors the issue promises:
- ordered link plan is built in dependency-declaration order,
- duplicate requirements are merged once in semantics-preserving order,
- every library/arg requirement is annotated with its declaring wrapper,
- relative search paths are anchored to the wrapper that declared them,
- diagnostics name the wrapper whose (link ...) introduced a missing lib,
- walker targets Package/StaticLib entry abilities as declared.
"""

import io;
import from contextlib { redirect_stdout }

test "dependency-declaration order preserved" {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3", "m"],
        search_paths=["vendor/sqlite/lib"],
        args=["-lpthread"]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib", "m"],
        search_paths=["vendor/raylib/lib"],
        args=["-ldl", "-lpthread"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;

    planner = LinkPlanner();
    root spawn planner;

    expected_libs = ["sqlite3", "m", "raylib"];
    expected_args = ["-lpthread", "-ldl"];
    expected_paths = ["vendor/sqlite/lib", "vendor/raylib/lib"];

    assert planner.ordered_libs == expected_libs, (
        f"libs not in declaration order: got {planner.ordered_libs}, "
        f"want {expected_libs}"
    );
    assert planner.ordered_args == expected_args, (
        f"args not in declaration order: got {planner.ordered_args}, "
        f"want {expected_args}"
    );
    assert planner.ordered_paths == expected_paths, (
        f"paths not in declaration order: got {planner.ordered_paths}, "
        f"want {expected_paths}"
    );
}

test "duplicate libs and args merged exactly once" {
    shared_lib_wrapper = StaticLib(
        name="shared-wrapper-a",
        libs=["m", "pthread"],
        search_paths=["vendor/common/lib"],
        args=["-lpthread"]
    );

    shared_lib_wrapper_b = StaticLib(
        name="shared-wrapper-b",
        libs=["m", "rt"],
        search_paths=["vendor/common/lib"],
        args=["-lpthread", "-ldl"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> shared_lib_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> shared_lib_wrapper_b;

    planner = LinkPlanner();
    root spawn planner;

    assert planner.ordered_libs == ["m", "pthread", "rt"], (
        f"duplicate libs not dedup'd in order: got {planner.ordered_libs}"
    );
    assert planner.ordered_args == ["-lpthread", "-ldl"], (
        f"duplicate args not dedup'd in order: got {planner.ordered_args}"
    );
    assert planner.ordered_paths == ["vendor/common/lib"], (
        f"duplicate path not dedup'd: got {planner.ordered_paths}"
    );

    assert planner.ordered_libs.count("m") == 1, (
        f"'m' should appear once, got {planner.ordered_libs.count('m')}"
    );
    assert planner.ordered_args.count("-lpthread") == 1, (
        f"'-lpthread' should appear once, got {planner.ordered_args.count('-lpthread')}"
    );
    assert planner.ordered_paths.count("vendor/common/lib") == 1, (
        f"shared path should appear once, got "
        f"{planner.ordered_paths.count('vendor/common/lib')}"
    );
}

test "provenance names the declaring wrapper" {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3"],
        search_paths=[],
        args=["-lpthread"]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib"],
        search_paths=[],
        args=["-ldl"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;

    planner = LinkPlanner();
    root spawn planner;

    assert planner.provenance.get("sqlite3") == "sqlite-wrapper", (
        f"sqlite3 provenance: got {planner.provenance.get('sqlite3')}, "
        f"want sqlite-wrapper"
    );
    assert planner.provenance.get("-lpthread") == "sqlite-wrapper", (
        f"-lpthread provenance: got {planner.provenance.get('-lpthread')}, "
        f"want sqlite-wrapper"
    );
    assert planner.provenance.get("raylib") == "raylib-wrapper", (
        f"raylib provenance: got {planner.provenance.get('raylib')}, "
        f"want raylib-wrapper"
    );
    assert planner.provenance.get("-ldl") == "raylib-wrapper", (
        f"-ldl provenance: got {planner.provenance.get('-ldl')}, "
        f"want raylib-wrapper"
    );

    assert "m" not in planner.provenance, (
        f"'m' was never declared so must not be in provenance: "
        f"{planner.provenance}"
    );
}

test "search paths anchored to declaring wrapper" {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3"],
        search_paths=["vendor/sqlite/lib", "vendor/os/lib"],
        args=[]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib"],
        search_paths=["vendor/raylib/lib"],
        args=[]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;

    planner = LinkPlanner();
    root spawn planner;

    assert "vendor/sqlite/lib" in planner.ordered_paths, (
        f"sqlite path missing: {planner.ordered_paths}"
    );
    assert "vendor/os/lib" in planner.ordered_paths, (
        f"os path missing: {planner.ordered_paths}"
    );
    assert "vendor/raylib/lib" in planner.ordered_paths, (
        f"raylib path missing: {planner.ordered_paths}"
    );

    assert planner.ordered_paths.index("vendor/sqlite/lib") < (
        planner.ordered_paths.index("vendor/raylib/lib")
    ), (
        f"paths must follow wrapper declaration order, got "
        f"{planner.ordered_paths}"
    );
}

test "diagnostics name the wrapper that introduced a missing lib" {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3"],
        search_paths=[],
        args=[]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib"],
        search_paths=[],
        args=[]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;

    buf = io.StringIO();
    diag = LinkDiagnostics();
    with redirect_stdout(buf) {
        root spawn diag;
    }
    out = buf.getvalue();

    assert "raylib" in out, f"diagnostic must mention 'raylib': {out!r}";
    assert "raylib-wrapper" in out, (
        f"diagnostic must name wrapper 'raylib-wrapper': {out!r}"
    );
    assert "link" in out.lower(), (
        f"diagnostic must reference the (link ...) field: {out!r}"
    );
}

