"""One-sample E2E pipeline through annotation: FASTQ -> alignment -> annotation.

Models the MitoPipeline v0.2.0 workflow as a directed acyclic graph of
pipeline stages. A walker traverses the dependency DAG from a single
sample, reporting stage status and propagating failures downstream so
the maintainer's manual verification step becomes a typed walk.
"""

# ── Entities ──────────────────────────────────────────────────────────

node Stage {
    has name: str = "";
    has status: str = "pending";
    has detail: str = "";
    has order: int = 0;
}

node FastqInput(Stage) {
    has sample_id: str = "";
    has read_count: int = 0;
}

node Alignment(Stage) {
    has reference_assembly: str = "";
    has aligned_reads: int = 0;
}

node Annotation(Stage) {
    has features_annotated: int = 0;
    has selected_assembly: str = "";
}

# ── Edges ─────────────────────────────────────────────────────────────

edge DependsOn {
    has verified: bool = False;
}

# ── Walker: traverse one sample end-to-end ───────────────────────────

walker E2E {
    has sample_label: str = "S1";
    has report: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        print(f"=== E2E walk for sample {self.sample_label} ===");
        visit [->:DependsOn:->];
    }

    can audit with FastqInput | Alignment | Annotation entry {
        if here.name in self.visited {
            print(f"  cycle guard hit at {here.name}");
            disengage;
        }
        self.visited.append(here.name);

        status_label = "OK" if here.status == "ok" else "FAIL";
        line = f"[{status_label}] {here.name}: {here.detail}";
        self.report.append(line);
        print(line);

        if here.status == "fail" {
            print(f"  failure at {here.name} -> downstream stages inherit FAIL");
        }

        visit [->:DependsOn:->];
    }
}

walker VerifyDAG {
    has node_names: list[str] = [];

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can check with FastqInput | Alignment | Annotation entry {
        self.node_names.append(here.name);
        print(f"  DAG node: {here.name} (order={here.order})");
        visit [->:DependsOn:->];
    }
}

# ── Demo wiring ──────────────────────────────────────────────────────

with entry {
    happy_fastq = FastqInput(
        name="fastq_in",
        status="ok",
        detail="reads loaded",
        order=1,
        sample_id="S1",
        read_count=2_500_000,
    );
    happy_align = Alignment(
        name="align",
        status="ok",
        detail="bwa-mem2 mapped",
        order=2,
        reference_assembly="GRCh38",
        aligned_reads=2_480_000,
    );
    happy_annot = Annotation(
        name="annotate",
        status="ok",
        detail="vep annotated",
        order=3,
        features_annotated=19_500,
        selected_assembly="GRCh38",
    );

    fail_fastq = FastqInput(
        name="fastq_in",
        status="ok",
        detail="reads loaded",
        order=1,
        sample_id="S2",
        read_count=1_800_000,
    );
    fail_align = Alignment(
        name="align",
        status="fail",
        detail="reference mismatch",
        order=2,
        reference_assembly="unknown",
        aligned_reads=0,
    );
    fail_annot = Annotation(
        name="annotate",
        status="pending",
        detail="skipped due to upstream failure",
        order=3,
        features_annotated=0,
        selected_assembly="",
    );

    root +>:DependsOn(verified=True):+> happy_fastq;
    happy_fastq +>:DependsOn(verified=True):+> happy_align;
    happy_align +>:DependsOn(verified=True):+> happy_annot;

    root +>:DependsOn(verified=True):+> fail_fastq;
    fail_fastq +>:DependsOn(verified=True):+> fail_align;
    fail_align +>:DependsOn(verified=True):+> fail_annot;

    print("--- VerifyDAG (integration slice) ---");
    root spawn VerifyDAG();

    print("--- E2E happy path ---");
    root spawn E2E(sample_label="S1");

    print("--- E2E failure propagation ---");
    root spawn E2E(sample_label="S2");
}
```

