"""Beta hardening tracker: model issues, waves, and dependencies as a typed graph.

The original issue hand-rolled ownership, ordering, and dependency tracking
as flat lists. Here we lift that machinery into typed edges and a walker that
audits the release readiness by traversing dependencies.
"""

node Issue {
    has id: int = 0;
    has title: str = "";
    has priority: str = "P2";
    has resolved: bool = False;
    has risk_accepted: bool = False;
}

node Wave {
    has label: str = "";
    has order: int = 0;
}

edge WaveOf {
    has slot: int = 0;
}

edge DependsOn {
    has hard: bool = True;
}

edge OwnedBy {
    has owner: str = "";
}

walker BetaAuditor {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_wave with Wave entry {
        self.report.append(f"=== Wave {here.order}: {here.label} ===");
        visit [->:WaveOf:->];
    }

    can audit_issue with Issue entry {
        status = "DONE" if here.resolved else "OPEN";
        if not here.resolved and here.priority == "P0" and not here.risk_accepted {
            self.report.append(
                f"[BLOCKER] #{here.id} {here.title} ({here.priority}) — no risk acceptance"
            );
        } else {
            self.report.append(f"[{status}] #{here.id} {here.title} ({here.priority})");
        }
        visit [->:DependsOn:->];
    }

    can audit_dep with Issue entry {
        mark = "!" if here.priority == "P0" and not here.resolved else " ";
        self.report.append(f"   {mark}-> dep #{here.id} {here.title}");
        visit [->:DependsOn:->];
    }
}

with entry {
    # Wave 0 — release process control
    w0 = Wave(label="establish control of the release process", order=0);
    root ++> w0;

    i71 = Issue(id=71, title="formalize dev/main branch workflow", priority="P0");
    i72 = Issue(id=72, title="reconcile contribution rules", priority="P1");
    i73 = Issue(id=73, title="resolve public license metadata conflict", priority="P0");
    w0 +>:WaveOf(slot=0):+> i71;
    w0 +>:WaveOf(slot=1):+> i72;
    w0 +>:WaveOf(slot=2):+> i73;

    # Wave 2 — identity / privacy blockers
    w2 = Wave(label="close identity, session, and privacy blockers", order=2);
    root ++> w2;

    i98 = Issue(id=98, title="prevent account pre-hijacking", priority="P0");
    i91 = Issue(id=91, title="harden session lifecycle", priority="P0");
    i101 = Issue(id=101, title="minimize AI/voice provider data", priority="P0");
    i99 = Issue(id=99, title="publish privacy/terms/AI disclosures", priority="P0");
    i100 = Issue(id=100, title="user data export and account deletion", priority="P0");
    w2 +>:WaveOf(slot=0):+> i98;
    w2 +>:WaveOf(slot=1):+> i91;
    w2 +>:WaveOf(slot=2):+> i101;
    w2 +>:WaveOf(slot=3):+> i99;
    w2 +>:WaveOf(slot=4):+> i100;

    # Dependencies inside wave 2 (suggested order)
    i98 +>:DependsOn:+> i91;
    i91 +>:DependsOn:+> i101;
    i101 +>:DependsOn:+> i99;
    i99 +>:DependsOn:+> i100;

    # Wave 3 — data/runtime risks
    w3 = Wave(label="remove immediate application data/runtime risks", order=3);
    root ++> w3;

    i104 = Issue(id=104, title="atomic checkout inventory", priority="P0");
    i81 = Issue(id=81, title="stop persisting base64 images in PostgreSQL", priority="P0");
    w3 +>:WaveOf(slot=0):+> i104;
    w3 +>:WaveOf(slot=1):+> i81;

    # Ownership assignments
    i71 +>:OwnedBy(owner="release"):+> i71;
    i98 +>:OwnedBy(owner="identity"):+> i98;
    i104 +>:OwnedBy(owner="checkout"):+> i104;
    i81 +>:OwnedBy(owner="storage"):+> i81;

    # Demo: resolve one P0 with explicit risk acceptance to show the audit
    # branch picks up unresolved P0s that were NOT risk-accepted.
    i73.resolved = True;
    i73.risk_accepted = True;
    i98.risk_accepted = True;

    auditor = BetaAuditor();
    root spawn auditor;

    for line in auditor.report {
        print(line);
    }
}
```

