    root ++> w;
    i98 = Issue(id=98, title="prevent account pre-hijacking", priority="P0", risk_accepted=True);
    i91 = Issue(id=91, title="harden session lifecycle", priority="P0");
    w +>:WaveOf(slot=0):+> i98;
    i98 +>:DependsOn:+> i91;
    res = root spawn BetaAuditor();
    marked_dep = False;
