    assert marked_dep, f"unresolved P0 dependency should be flagged: {res.report}";
    assert plain_dep == False, f"unresolved P0 dep should use ! marker, not plain: {res.report}";
}

test "auditor visits each root wave and lists wave issues in order" {
    w0 = Wave(label="establish control of the release process", order=0);
    w3 = Wave(label="remove immediate application data/runtime risks", order=3);
    root ++> w0;
    root ++> w3;
    i71 = Issue(id=71, title="formalize dev/main branch workflow", priority="P0");
    i104 = Issue(id=104, title="atomic checkout inventory", priority="P0");
    w0 +>:WaveOf(slot=0):+> i71;
    w3 +>:WaveOf(slot=0):+> i104;
    res = root spawn BetaAuditor();
    has_w0 = False;
    has_w3 = False;
    has_i71 = False;
    has_i104 = False;
    for line in res.report {
        if "=== Wave 0: establish control of the release process ===" in line {
            has_w0 = True;
        }
        if "=== Wave 3: remove immediate application data/runtime risks ===" in line {
            has_w3 = True;
        }
        if "#71 formalize dev/main branch workflow" in line {
            has_i71 = True;
        }
        if "#104 atomic checkout inventory" in line {
            has_i104 = True;
        }
    }
    assert len([root-->]) == 2, f"root should have two direct wave children, got {len([root-->])}";
    assert has_w0, f"missing wave 0 banner: {res.report}";
    assert has_w3, f"missing wave 3 banner: {res.report}";
    assert has_i71, f"missing wave 0 issue audit: {res.report}";
    assert has_i104, f"missing wave 3 issue audit: {res.report}";
}

