"""Tests for Episode cycle detection in workflow.triggered_by chains.

Verifies the CycleHunter walker detects cycles of varying lengths
(depth-0 self-loop, depth-2 short cycle, depth-3 longer cycle) and
correctly reports no cycle on a linear chain.
"""

import io;
import from contextlib { redirect_stdout }

test "depth-3 cycle A->B->C->D->B is detected" {
    a = Episode(id="A");
    b = Episode(id="B");
    c = Episode(id="C");
    d = Episode(id="D");

    `root = Root();
    `root ++> a;
    a +>:TriggeredBy(timestamp="t1"):+> b;
    b +>:TriggeredBy(timestamp="t2"):+> c;
    c +>:TriggeredBy(timestamp="t3"):+> d;
    d +>:TriggeredBy(timestamp="t4"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        a spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.cycle_found, f"expected cycle_found True, got reports path={hunter.cycle_path}";
    assert "B" in hunter.cycle_path, f"expected B in cycle_path: {hunter.cycle_path}";
    assert len(hunter.cycle_path) >= 2, f"cycle_path should describe cycle, got {hunter.cycle_path}";
    assert "[REJECT]" in out, f"missing [REJECT] marker in stdout: {out}";
    assert "cycle detected" in out, f"missing 'cycle detected' in stdout: {out}";
}

test "self-trigger A->A is detected as cycle" {
    a = Episode(id="A");
    `root = Root();
    `root ++> a;
    a +>:TriggeredBy(timestamp="t1"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        a spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.cycle_found, f"expected self-loop cycle_found True, path={hunter.cycle_path}";
    assert hunter.cycle_path[0] == "A", f"expected cycle_path to start with A, got {hunter.cycle_path}";
    assert out.count("A") >= 2, f"expected A repeated in REJECT line, got: {out}";
}

test "linear chain E->F->G reports no cycle" {
    e = Episode(id="E");
    f = Episode(id="F");
    g = Episode(id="G");

    `root = Root();
    `root ++> e;
    e +>:TriggeredBy(timestamp="t1"):+> f;
    f +>:TriggeredBy(timestamp="t2"):+> g;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        e spawn hunter;
    }
    out = buf.getvalue();

    assert not hunter.cycle_found, f"expected no cycle on linear chain, got cycle_path={hunter.cycle_path}";
    assert hunter.cycle_path == [], f"expected empty cycle_path on linear chain, got {hunter.cycle_path}";
    assert "[REJECT]" not in out, f"unexpected REJECT on linear chain: {out}";
}

test "depth-2 cycle X->Y->X is detected" {
    x = Episode(id="X");
    y = Episode(id="Y");

    `root = Root();
    `root ++> x;
    x +>:TriggeredBy(timestamp="t1"):+> y;
    y +>:TriggeredBy(timestamp="t2"):+> x;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        x spawn hunter;
    }
    out = buf.getvalue();

    assert hunter.cycle_found, f"expected cycle_found True for X->Y->X, path={hunter.cycle_path}";
    assert "X" in hunter.cycle_path and "Y" in hunter.cycle_path, f"expected X and Y in cycle_path: {hunter.cycle_path}";
    assert "[REJECT]" in out, f"missing [REJECT] in stdout: {out}";
}

