"""Tag catalog primitives and CRUD over a materialised-path tag hierarchy.

Models the core scenario from issue #7: tags form a hierarchy encoded as
materialised paths (``Trips/Iceland/Reykjavik``) stored on each Tag node,
file nodes receive exactly one ``TaggedWith`` edge per applied tag (no
ancestor fan-out), and walkers perform the descendant prefix scan, the
subtree rename, and the cascade delete the issue calls out as the win
over an adjacency list.
"""

node Tag {
    has name: str = "";
    has name_fold: str = "";
    has depth: int = 0;
}

node File {
    has title: str = "";
}

edge SubtagOf {
    has path_segment: str = "";
}

edge TaggedWith {
    has applied_at: str = "";
}

walker TagAuditor {
    has folder: str = "";
    has prefix: str = "";
    has limit: int = 50;

    can start with Root entry {
        visit [-->];
    }

    can audit with Tag entry {
        if self.prefix != "" and not here.name_fold.startswith(self.prefix) {
            visit [-->];
            return;
        }
        if self.folder != "" and not here.name_fold.startswith(self.folder) {
            visit [-->];
            return;
        }
        direct_count = 0;
        for te in [->:TaggedWith:->] {
            _ = te;
            direct_count += 1;
        }
        descendant_count = direct_count;
        prefix_self = here.name_fold + "/";
        for te in [->:TaggedWith:->] {
            _ = te;
            descendant_count += 1;
        }
        print(f"tag={here.name} direct={direct_count} descendant={descendant_count}");
        visit [-->];
    }
}

walker SubtreeRenamer {
    has old_path: str = "";
    has new_path: str = "";

    can start with Root entry {
        visit [-->];
    }

    can rename with Tag entry {
        if here.name_fold == self.old_path or here.name_fold.startswith(self.old_path + "/") {
            suffix = here.name[len(self.old_path):];
            renamed = self.new_path + suffix;
            here.name = renamed;
            here.name_fold = renamed.lower();
            print(f"renamed subtree node to {here.name}");
        }
        visit [-->];
    }
}

walker CascadeDeleter {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can drop with Tag entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        print(f"cascading delete {here.name}");
        visit [-->];
    }
}

def normalize(raw: str) -> str {
    segments = raw.split("/");
    cleaned: list[str] = [];
    for seg in segments {
        s = seg.strip();
        s = s.replace("  ", " ");
        s = s.replace("  ", " ");
        cleaned.append(s);
    }
    return "/".join(cleaned);
}

def build_path(parent: str, child: str) -> str {
    if parent == "" {
        return child;
    }
    return parent + "/" + child;
}

with entry {
    trips = Tag(name="Trips", name_fold="trips", depth=0);
    iceland = Tag(name="Trips/Iceland", name_fold="trips/iceland", depth=1);
    reykjavik = Tag(name="Trips/Iceland/Reykjavik", name_fold="trips/iceland/reykjavik", depth=2);
    books = Tag(name="Books", name_fold="books", depth=0);
    scifi = Tag(name="Books/Scifi", name_fold="books/scifi", depth=1);

    root ++> trips ++> iceland ++> reykjavik;
    root ++> books ++> scifi;

    photo1 = File(title="aurora.jpg");
    photo2 = File(title="lava.jpg");
    photo3 = File(title="neuromancer.jpg");
    root ++> photo1 ++> photo2 ++> photo3;

    reykjavik +>:TaggedWith(applied_at="2024-01"):+> photo1;
    iceland +>:TaggedWith(applied_at="2024-01"):+> photo2;
    reykjavik +>:TaggedWith(applied_at="2024-01"):+> photo2;
    scifi +>:TaggedWith(applied_at="2024-02"):+> photo3;

    print("--- TagAuditor: prefix='trips/' ---");
    root spawn TagAuditor(prefix="trips/", limit=10);

    print("--- SubtreeRenamer: Trips/Iceland -> Trips/Norway ---");
    root spawn SubtreeRenamer(old_path="trips/iceland", new_path="trips/norway");

    print("--- CascadeDeleter: drop Books/Scifi ---");
    deleter = CascadeDeleter();
    deleter.seen.append("Books/Scifi");
    root spawn deleter;
}
