test "prefix audit reports matching tag counts only" {
    trips = Tag(name="Trips", name_fold="trips", depth=0);
    iceland = Tag(name="Trips/Iceland", name_fold="trips/iceland", depth=1);
    reykjavik = Tag(
        name="Trips/Iceland/Reykjavik",
        name_fold="trips/iceland/reykjavik",
        depth=2
