    root ++> trips;
    trips +>:SubtagOf(path_segment="Iceland"):+> iceland;
    iceland +>:SubtagOf(path_segment="Reykjavik"):+> reykjavik;
    root ++> books;
    root ++> photo1;
    root ++> photo2;
    root ++> photo3;

    iceland +>:TaggedWith(applied_at="2024-01"):+> photo1;
    reykjavik +>:TaggedWith(applied_at="2024-01"):+> photo2;
    books +>:TaggedWith(applied_at="2024-02"):+> photo3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
