"""Cartography canonical map: typed models with reconciliation, authority classes, and revision diff."""

# Edge archetypes — typed relationships with payloads for provenance/authority
edge MapsTo { has kind: str = ""; }
edge Claims { has authority: str = "cartographer"; }
edge Constrains { has authority: str = "cartographer"; }
edge AnchorsTo { has binding_kind: str = "path"; }

# Entity node archetypes — bounded schema-controlled fields
node MapRevision {
    has rev_id: str = "";
    has version: int = 0;
    has canonical: bool = True;
    has published: bool = False;
}

node Domain {
    has domain_id: str = "";
    has title: str = "";
    has status: str = "active";
}

node KnowledgeClaim {
    has claim_id: str = "";
    has text: str = "";
    has actor_authored: bool = False;
}

node InstitutionalConstraint {
    has constraint_id: str = "";
    has rule: str = "";
    has actor_authored: bool = True;
}

node ReconciliationNote {
    has old_id: str = "";
    has new_id: str = "";
    has outcome: str = "ambiguous";
    has reason: str = "";
}

# Walkers — the traversals the issue complains about
walker RevisionDiff {
    has rev_a: str = "";
    has rev_b: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan with MapRevision entry {
        if (here.rev_id == self.rev_a) or (here.rev_id == self.rev_b) {
            print(f"Revision {here.rev_id} v{here.version} canonical={here.canonical} published={here.published}");
        }
        visit [-->];
    }
}

walker AuthorityInspector {
    has found_actor_claims: int = 0;
    has found_cartographer_claims: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tally with KnowledgeClaim entry {
        if here.actor_authored {
            self.found_actor_claims += 1;
            print(f"ACTOR claim '{here.text}' preserved");
        } else {
            self.found_cartographer_claims += 1;
            print(f"Generated claim '{here.text}'");
        }
        visit [-->];
    }

    can tally_constraint with InstitutionalConstraint entry {
        if here.actor_authored {
            print(f"ACTOR constraint '{here.rule}' survives generated changes");
        }
        visit [-->];
    }
}

walker CascadeInvalidate {
    can start with Root entry {
        print("Cascade-invalidate traversal begins");
        visit [-->];
    }

    can invalidate with Domain entry {
        here.status = "invalidated";
        print(f"Domain {here.domain_id} invalidated; downstream claims become stale");
        visit [-->];
    }

    can mark_stale with KnowledgeClaim entry {
        print(f"Claim '{here.text}' marked stale");
        visit [-->];
    }
}

walker ReconciliationWalker {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can reconcile with ReconciliationNote entry {
        outcome = "preserved" if here.outcome == "preserved" else "ambiguous";
        self.report.append((here.old_id, here.new_id, outcome, here.reason));
        if here.outcome == "ambiguous" {
            print(f"AMBIGUOUS: {here.old_id} -> {here.new_id} ({here.reason})");
        } else {
            print(f"RESOLVED: {here.old_id} -> {here.new_id} ({here.reason})");
        }
        visit [-->];
    }
}

with entry {
    rev = MapRevision(rev_id="rev-7", version=7, canonical=True, published=True);
    root ++> rev;

    auth = Domain(domain_id="dom-auth", title="Authentication");
    billing = Domain(domain_id="dom-billing", title="Billing");
    rev +>:MapsTo(kind="contains"):+> auth;
    rev +>:MapsTo(kind="contains"):+> billing;

    actor_claim = KnowledgeClaim(claim_id="c-1", text="auth requires SSO", actor_authored=True);
    cart_claim = KnowledgeClaim(claim_id="c-2", text="billing refs dom-auth", actor_authored=False);
    auth +>:Claims(authority="actor"):+> actor_claim;
    billing +>:Claims(authority="cartographer"):+> cart_claim;

    constraint = InstitutionalConstraint(constraint_id="k-1", rule="PII never leaves auth domain", actor_authored=True);
    auth +>:Constrains(authority="actor"):+> constraint;

    ambig = ReconciliationNote(old_id="dom-billing-legacy", new_id="dom-billing", outcome="ambiguous", reason="rename suspected but path evidence insufficient");
    preserved = ReconciliationNote(old_id="dom-auth", new_id="dom-auth", outcome="preserved", reason="unchanged identity");
    rev +>:AnchorsTo(binding_kind="note"):+> ambig;
    rev +>:AnchorsTo(binding_kind="note"):+> preserved;

    print("=== Revision diff ===");
    rev_a = "rev-6";
    rev_b = "rev-7";
    rdiff = RevisionDiff(rev_a=rev_a, rev_b=rev_b);
    rev spawn rdiff;

    print("\n=== Authority inspection ===");
    inspector = AuthorityInspector();
    rev spawn inspector;
    print(f"actor={inspector.found_actor_claims} cartographer={inspector.found_cartographer_claims}");

    print("\n=== Cascade invalidation ===");
    cascade = CascadeInvalidate();
    rev spawn cascade;

    print("\n=== Reconciliation ===");
    recon = ReconciliationWalker();
    rev spawn recon;
    print(f"reconciliation report entries: {len(recon.report)}");
}
