```jac
"""Workflow retirement: model orphaned/authoritative workflows and reconcile authority.

Models a CI workflow catalog where each workflow has an inventory classification,
current callers/consumers, retirement reason, and historical evidence. A walker
walks the graph and reconciles authority by flagging workflows whose live
state contradicts their source-of-truth retirement status.
"""

node Workflow {
    has title: str = "";
    has classification: str = "";   # orphan | expired | obsolete | duplicate | authoritative | specialized
    has retirement_reason: str = "";
    has historical_evidence: str = "";
    has live_state: str = "";       # enabled | disabled | not_proven
    has reconciled: bool = False;
}

edge Calls {
    has consumer: str = "";
    has policy_ref: str = "";
}

edge ReplacedBy {
    has replacement: str = "";
}

walker Auditor {
    has visited: list[str] = [];
    has depth_limit: int = 10;
    has has_cycle: bool = False;

    can start with Root entry {
        self.visited = [];
        visit [-->] else { disengage; }
    }

    can audit with Workflow entry {
        # Explicit cycle guard — walkers do not dedupe automatically.
        if here.title in self.visited {
            self.has_cycle = True;
            print(f"[CYCLE] revisit of '{here.title}' — graph has a loop");
            disengage;
        }
        self.visited = self.visited + [here.title];

        # Reconcile source retirement classification against live state.
        if here.classification in ["orphan", "expired", "obsolete", "duplicate"] {
            if here.live_state == "enabled" {
                here.reconciled = False;
                print(f"[CONFLICT] '{here.title}' marked {here.classification} but still enabled live");
            } elif here.live_state == "not_proven" {
                here.reconciled = False;
                print(f"[UNCERTAIN] '{here.title}' {here.classification}, live state not_proven — must verify");
            } else {
                here.reconciled = True;
                print(f"[OK] '{here.title}' {here.classification} and disabled; evidence: {here.historical_evidence}");
            }
        } elif here.classification == "authoritative" {
            # Authoritative lanes must be untouched unless transition is reviewed.
            here.reconciled = True;
            print(f"[AUTH] '{here.title}' preserved as authoritative");
        } elif here.classification == "specialized" {
            # Specialized workflows are kept even when uncommon.
            here.reconciled = True;
            print(f"[KEEP] '{here.title}' specialized, uncommon but retained");
        }

        if len(self.visited) >= self.depth_limit {
            disengage;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    # Authoritative core lanes — preserved untouched.
    pr_main = Workflow(
        title="pr-main",
        classification="authoritative",
        retirement_reason="",
        historical_evidence="docs/canonical/pr-main.md",
        live_state="enabled",
    );
    nightly = Workflow(
        title="nightly",
        classification="authoritative",
        retirement_reason="",
        historical_evidence="docs/canonical/nightly.md",
        live_state="enabled",
    );
    publication = Workflow(
        title="publication",
        classification="authoritative",
        retirement_reason="",
        historical_evidence="docs/canonical/publication.md",
        live_state="enabled",
    );

    # Orphaned temporary workflow — expired, evidence preserved elsewhere.
    tmp_hotfix = Workflow(
        title="tmp-hotfix-2023",
        classification="expired",
        retirement_reason="temporary hotfix window closed",
        historical_evidence="archive/2023/tmp-hotfix-2023.tar",
        live_state="disabled",
    );

    # Obsolete reusable workflow — no active caller, evidence retained.
    legacy_release = Workflow(
        title="legacy-release-helper",
        classification="obsolete",
        retirement_reason="no active caller found in inventory",
        historical_evidence="archive/legacy/legacy-release-helper.log",
        live_state="disabled",
    );

    # Duplicate context producer — superseded by canonical.
    dup_ctx_v1 = Workflow(
        title="ctx-producer-v1",
        classification="duplicate",
        retirement_reason="superseded by ctx-producer-v2",
        historical_evidence="archive/ctx/ctx-producer-v1.snapshot",
        live_state="disabled",
    );
    dup_ctx_v2 = Workflow(
        title="ctx-producer-v2",
        classification="duplicate",
        retirement_reason="superseded by canonical ctx producer",
        historical_evidence="archive/ctx/ctx-producer-v2.snapshot",
        live_state="disabled",
    );

    # Specialized workflow — uncommon but kept with current owner.
    coverage_gate = Workflow(
        title="coverage-gate-experimental",
        classification="specialized",
        retirement_reason="",
        historical_evidence="docs/canonical/coverage-gate.md",
        live_state="enabled",
    );

    # Negative control: claimed orphan but still live-enabled — must not delete.
    conflicting = Workflow(
        title="stale-required-check",
        classification="obsolete",
        retirement_reason="believed unused",
        historical_evidence="",
        live_state="enabled",
    );

    # Negative control: orphan but evidence not yet preserved — must not delete.
    no_evidence = Workflow(
        title="tmp-migration-2024",
        classification="orphan",
        retirement_reason="no caller found",
        historical_evidence="",
        live_state="disabled",
    );

    # Wire the call graph with typed edges.
    root ++> pr_main
        ++> nightly
        ++> publication
        ++> tmp_hotfix
        ++> legacy_release
        ++> dup_ctx_v1
        ++> dup_ctx_v2
        ++> coverage_gate
        ++> conflicting
        ++> no_evidence;

    # Authoritative caller relationship.
    pr_main +>:Calls(consumer="github:required-check", policy_ref="policy/required-checks.md"):+> publication;
    pr_main +>:Calls(consumer="github:required-check", policy_ref="policy/required-checks.md"):+> nightly;

    # Replacement edges for duplicate context producers.
    dup_ctx_v1 +>:ReplacedBy(replacement="ctx-producer-v2"):+> dup_ctx_v2;
    dup_ctx_v2 +>:ReplacedBy(replacement="canonical-ctx"):+> publication;

    # Specialized owner edge.
    coverage_gate +>:Calls(consumer="team:coverage", policy_ref="policy/coverage.md"):+> pr_main;

    # Cycle demonstrating that explicit cycle policy is required.
    legacy_release +>:ReplacedBy(replacement="tmp-migration-2024"):+> no_evidence;
    no_evidence +>:ReplacedBy(replacement="legacy-release-helper"):+> legacy_release;

    root spawn Auditor(depth_limit=20);
}
```

