    out = buf.getvalue();

    assert first.present == False, f"first cache present is {first.present}";
    assert second.present == False, f"second cache present is {second.present}";
    assert len(res.seen) == 2, f"seen cache keys are {res.seen}";
    assert "old-runtime" in out, f"missing first invalidation: {out}";
    assert "old-ui" in out, f"missing second invalidation: {out}";
}

