test "end-to-end demo emits deterministic governed PostgreSQL SQL" {
    rt = Root();
    read = ReadRel(table_name="customers");
    f_name = FieldRef(field_name="name");
    f_email = FieldRef(field_name="email");
    f_country = FieldRef(field_name="country");
    p_name = ProjectRel(output_name="customer_name", expression="upper(trim(name))");
    p_email = ProjectRel(output_name="email", expression="email");
    p_country = ProjectRel(output_name="country", expression="country");

    rt ++> read;
    read +>:HasRel:+> p_name;
    read +>:HasRel:+> p_email;
    read +>:HasRel:+> p_country;
    p_name +>:DependsOn(field_name="name"):+> f_name;
    p_email +>:DependsOn(field_name="email"):+> f_email;
    p_country +>:DependsOn(field_name="country"):+> f_country;

    mapper = SubstraitToSqlGlot();
    read spawn mapper;

    sql_select = SqlGlotExpr(sql_kind="SELECT_STMT", sql_text="SELECT");
    sql_from = SqlGlotExpr(sql_kind="FROM_CLAUSE", sql_text="FROM customers");
    sql_proj1 = SqlGlotExpr(sql_kind="PROJECTION", sql_text="upper(trim(name)) AS customer_name,");
    sql_proj2 = SqlGlotExpr(sql_kind="PROJECTION", sql_text="email AS email,");
    sql_proj3 = SqlGlotExpr(sql_kind="PROJECTION", sql_text="country AS country");

    rt +>:HasExpr:+> sql_select;
    sql_select +>:HasExpr:+> sql_proj1;
    sql_select +>:HasExpr:+> sql_proj2;
    sql_select +>:HasExpr:+> sql_proj3;
    sql_select +>:HasExpr:+> sql_from;

    renderer = SqlGlotToPostgres();
    rt spawn renderer;

    governed = GovernedSql(
        dialect="postgresql",
        body="\n".join(renderer.lines),
        diagnostics=mapper.diagnostics
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        print(f"--- governed PostgreSQL ({governed.dialect}) ---");
        print(governed.body);
        print("--- diagnostics ---");
        for d in governed.diagnostics {
            print(d);
        }
    }
    out = buf.getvalue();

    assert "--- governed PostgreSQL (postgresql) ---" in out, f"missing header: {out}";
    assert "SELECT" in out, f"missing SELECT: {out}";
    assert "  upper(trim(name)) AS customer_name," in out, f"missing projection 1: {out}";
    assert "  email AS email," in out, f"missing projection 2: {out}";
    assert "  country AS country" in out, f"missing projection 3: {out}";
    assert "FROM customers" in out, f"missing FROM: {out}";
    assert "--- diagnostics ---" in out, f"missing diagnostics header: {out}";
    assert governed.dialect == "postgresql", f"dialect is {governed.dialect}";
    assert governed.body.count("customer_name") == 1, f"customer_name repeated: {governed.body}";
}

