test "typed edges preserve certification topology" {
    target = Target(label="local-microvm", kind="microvm");
    profile = SandboxProfile(
        name="fs-strict",
        backend_class="landlock",
        isolation="process",
        fs_ro_paths=["/etc/agentci"],
        net_allowlist=["api.openai.com"]
    );
    probe = Probe(label="p-ro-paths", assertion="no_read_outside_ro");
    dependency = SandboxProfile(name="base", backend_class="namespace", isolation="user");

    target +>:MountedOn(since="2026-08-01"):+> profile;
    target +>:RunsProbe:+> probe;
    profile +>:DependsOn:+> dependency;

