    probe = Probe(label="p-unknown", assertion="unsupported");

    res = probe spawn Certifier(target_label="local-namespace");
    verdicts = [probe ->:ProducesVerdict:->];
    assert len(verdicts) == 1, "unsupported probe did not create one verdict";
    verdict = verdicts[0];
    assert verdict.status == "not-applicable", f"verdict status is {verdict.status}";
    assert "not mapped for this target" in verdict.detail, f"verdict detail is {verdict.detail}";
    assert res.report[0] == "probe=p-unknown -> not-applicable", f"probe report is {res.report[0]}";
}

