    a_node = SchemaDef(name="A", description="struct A");
    b_node = SchemaDef(name="B", description="struct B");

    root +>:RefersTo(field_name="b", has_override=True):+> a_node;
    a_node +>:RefersTo(field_name="a", has_override=False):+> b_node;
    b_node +>:RefersTo(field_name="b", has_override=False):+> a_node;

    assert len([root-->]) == 1, f"got {len([root-->])} root children";
    assert len([a_node-->]) == 1, f"got {len([a_node-->])} A children";
    assert len([b_node-->]) == 1, f"got {len([b_node-->])} B children";
    assert a_node in [root ->:RefersTo:->], "root does not refer to A";
    assert b_node in [a_node ->:RefersTo:->], "A does not refer to B";
    assert a_node in [b_node ->:RefersTo:->], "B does not refer to A";
    assert a_node.name == "A", f"got {a_node.name}";
    assert b_node.name == "B", f"got {b_node.name}";
}

test "guards a cross-type recursion with a ref" {
    a_node = SchemaDef(name="A", description="struct A");
    b_node = SchemaDef(name="B", description="struct B");

    root +>:RefersTo(field_name="b", has_override=False):+> b_node;
    b_node +>:RefersTo(field_name="a", has_override=False):+> a_node;
    a_node +>:RefersTo(field_name="b", has_override=False):+> b_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SchemaCollector();
    }
    out = buf.getvalue();

    assert "Walking A->B->A... with cycle guard:" in out, f"missing walk marker: {out}";
    assert "[INLINE] expanding B" in out, f"missing B expansion: {out}";
    assert "cycle hit on A" in out, f"missing cycle marker: {out}";
    assert "$ref:#/$defs/A" in out, f"missing A ref: {out}";
    assert "[INLINE] expanding A" not in out, f"A was expanded recursively: {out}";
    assert res.collected == ["B"], f"got {res.collected}";
    assert res.done == ["B"], f"got {res.done}";
}

