    # Root must link to the Scala version anchor exactly once.
    assert len([root-->]) == 1, f"root should have one outgoing edge, got {len([root-->])}";
    assert v in [root-->], "ScalaVer must be reachable from root";

    # Typed-edge direction: ScalaVer -UsesBridge-> CompilerBridge.
    assert br in [v ->:UsesBridge:->], "UsesBridge must point ScalaVer to bridge";
    assert v not in [v ->:UsesBridge:->], "UsesBridge must be one-way";

    # Typed-edge direction: CompilerBridge -UsesZinc-> ZincCompiler.
    assert zn in [br ->:UsesZinc:->], "UsesZinc must point bridge to zinc";
    assert br not in [br ->:UsesZinc:->], "UsesZinc must be one-way";

    # Typed-edge direction: ZincCompiler -UsesSemanticDb-> SemanticDbScalac.
    assert sb in [zn ->:UsesSemanticDb:->], "UsesSemanticDb must point zinc to leaf";
    assert zn not in [zn ->:UsesSemanticDb:->], "UsesSemanticDb must be one-way";

    # No stray connections between non-adjacent layers.
    assert v not in [br -->], "v must not be reachable downward from bridge";
    assert sb not in [br -->], "leaf must not be reachable from bridge directly";
}

