"""Subagent workspace isolation: model Codex subagents, their checkouts, and
write-capable behavior as nodes connected by typed edges. A walker traverses
the parent/child checkout graph, performing a reachability + collision probe
that mirrors the issue's experimental objective."""

node Checkout {
    has label: str = "";
    has branch: str = "main";
    has head_sha: str = "";
    has worktree: str = "";
    has read_only: bool = True;
}

node SentinelFile {
    has path: str = "";
    has content: str = "";
    has collided: bool = False;
}

node PermissionProfile {
    has name: str = "";
    has can_write: bool = False;
    has can_commit: bool = False;
    has can_switch_branch: bool = False;
}

edge Spawned {
    has surface: str = "codex-cli";
    has inherited_from_parent: bool = True;
}

edge WroteTo {
    has timestamp: str = "T0";
    has succeeded: bool = False;
}

walker IsolationAuditor {
    has observed: list[str] = [];

    can start with Root entry {
        print("=== Subagent Workspace Isolation Probe ===");
        visit [-->];
    }

    can inspect with Checkout entry {
        print(f"checkout[{here.label}] branch={here.branch} "
            f"head={here.head_sha} worktree={here.worktree} "
            f"readonly={here.read_only}");
        self.observed.append(here.label);
        visit [-->];
    }

    can inspect_perms with PermissionProfile entry {
        print(f"perms[{here.name}] write={here.can_write} "
            f"commit={here.can_commit} branch={here.can_switch_branch}");
        visit [-->];
    }

    can inspect_file with SentinelFile entry {
        print(f"sentinel[{here.path}] collided={here.collided}");
        visit [-->];
    }
}

walker CollisionProbe {
    can start with Root entry {
        print("=== Concurrent Same-File Collision Probe ===");
        visit [-->];
    }

    can sweep with Checkout entry {
        print(f"probing checkout {here.label} for write collisions");
        visit [-->];
    }

    can collide with SentinelFile entry {
        here.collided = True;
        print(f"collision recorded on {here.path}");
        visit [-->];
    }

    can skip with PermissionProfile entry {
        visit [-->];
    }
}

with entry {
