test "auditor detects duplicate reference labels" {
    buf = io.StringIO();
    rt = Root();
    doc = MarkdownDocument(title="Doc", bytes="x");
    rt ++> doc;
    body = ParsedBlock(kind="doc_root", ordinal=0);
