    body +>:Contains(order=2):+> small;

    auditor = MarkdownAuditor();
    with redirect_stdout(buf) {
        rt spawn auditor;
    }
    out = buf.getvalue();
    assert "QUADRATIC inline: link x64" in out, f"quadratic flag missing: {out}";
    assert "inline[em]: len=1" in out, f"small inline should be benign: {out}";
    assert auditor.failures == 1, f"expected 1 failure, got {auditor.failures}";
}

test "takeover retires every parsed block and severs CommonMark" {
    buf = io.StringIO();
    rt = Root();
    doc = MarkdownDocument(title="README", bytes="x");
    rt ++> doc;
    body = ParsedBlock(kind="doc_root", ordinal=0);
    doc +>:Contains(order=0):+> body;
    b1 = ParsedBlock(kind="heading", ordinal=1);
    body +>:Contains(order=1):+> b1;
    b2 = ParsedBlock(kind="list", ordinal=2);
    body +>:Contains(order=2):+> b2;

    takeover = ParserTakeover();
    with redirect_stdout(buf) {
        rt spawn takeover;
    }
    out = buf.getvalue();
    assert "CommonMark dependency severed" in out, f"takeover banner missing: {out}";
    assert "rescanned advisories dropped from downstream lockfile: 6" in out, f"advisory count line missing: {out}";
    assert takeover.inherited_adv == 6, f"inherited advisories should be 6: {takeover.inherited_adv}";
    assert "invalidating external adapter for: README" in out, f"invalidating line missing: {out}";
    assert takeover.retired == 3, f"expected 3 blocks retired, got {takeover.retired}";
    assert "retire external block[0] doc_root" in out, f"doc_root retire line missing: {out}";
    assert "retire external block[1] heading" in out, f"heading retire line missing: {out}";
    assert "retire external block[2] list" in out, f"list retire line missing: {out}";
