test "depth limit blocks deep recursion and reports failure" {
    root ++> Domain(name="d0.test", spf_record="v=spf1 include:d1.test -all");
    prev = [root -->][0];
    nodes = [prev];
    for i in range(1, 8) {
        n = Domain(name=f"d{i}.test", spf_record=f"v=spf1 include:d{i + 1}.test -all");
        nodes.append(n);
    }
    for i in range(len(nodes) - 1) {
        nodes[i] +>:Ref(mechanism="include"):+> nodes[i + 1];
    }

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = root spawn SpfAuditor(max_depth=3, max_lookups=20);
    }

    out = buf.getvalue();
    assert auditor.failures >= 1, f"expected depth-limit failure, got {auditor.failures}";
    assert "[DEPTH-LIMIT]" in out, f"missing depth-limit marker: {out}";
