test "honest page tree computes the minimum claimed oldest leaf" {
    root_page = Page(pagenum=100, claimed_oldestleaf=200, pagesize=4096, key="root");
    leaf_a = Page(pagenum=101, claimed_oldestleaf=200, pagesize=4096, key="alpha");
    leaf_b = Page(pagenum=102, claimed_oldestleaf=240, pagesize=4096, key="beta");

    root +>:ParentChild:+> root_page;
    root_page +>:ParentChild:+> leaf_a;
    root_page +>:ParentChild:+> leaf_b;

    res = root spawn BTreeGC();

    assert res.observed_min == 200, f"got {res.observed_min}";
    assert len(res.visited) == 3, f"visited {len(res.visited)} pages";
    assert leaf_a in [root_page ->:ParentChild:->], f"missing leaf alpha edge";
    assert leaf_b in [root_page ->:ParentChild:->], f"missing leaf beta edge";
}

test "forged child oldestleaf controls the GC cutoff" {
    root_page = Page(pagenum=100, claimed_oldestleaf=200, pagesize=4096, key="root");
    honest_leaf = Page(pagenum=101, claimed_oldestleaf=200, pagesize=4096, key="alpha");
    forged_child = Page(
        pagenum=102,
        claimed_oldestleaf=3,
        pagesize=4096,
        key="forged",
        forged=True
    );

    root +>:ParentChild:+> root_page;
    root_page +>:ParentChild:+> honest_leaf;
    root_page +>:ParentChild:+> forged_child;

    block_one = Block(blkno=1, label="live anchor");
    block_two = Block(blkno=2, label="live block");
    block_root = Block(blkno=100, label="root page");

    root_page +>:LivesOn:+> block_one;
    honest_leaf +>:LivesOn:+> block_two;
    forged_child +>:LivesOn:+> block_root;

    res = root spawn BTreeGC();

    assert res.observed_min == 3, f"got {res.observed_min}";
    assert forged_child.pagenum in res.visited, f"forged page was not visited";
    assert block_one in [root_page ->:LivesOn:->], f"missing anchor block";
    assert block_two in [honest_leaf ->:LivesOn:->], f"missing live block";
}

test "cyclic child references are visited only once" {
    root_page = Page(pagenum=100, claimed_oldestleaf=200, pagesize=4096, key="root");
    child_a = Page(pagenum=101, claimed_oldestleaf=180, pagesize=4096, key="a");
    child_b = Page(pagenum=102, claimed_oldestleaf=160, pagesize=4096, key="b");

    root +>:ParentChild:+> root_page;
    root_page +>:ParentChild:+> child_a;
    child_a +>:ParentChild:+> child_b;
    child_b +>:ParentChild:+> child_a;

    res = root spawn BTreeGC();

    assert len(res.visited) == 3, f"visited {len(res.visited)} pages";
    assert res.observed_min == 160, f"got {res.observed_min}";
    assert child_a in [child_b ->:ParentChild:->], f"missing cycle edge";
}

