"""Test annex for main.jac — typealias cycle detection.

Verifies the three behaviors the issue promises:
  1. structural self-reference reports an error naming the cycle, no crash
  2. two-step mutual cycle reports an error naming the cycle
  3. nominal recursive type still checks cleanly (terminates at the name)
"""

import io;
import from contextlib { redirect_stdout }

test "structural self-referencing typealias reports cycle without crash" {
    root ++> AliasDecl(name="Tree", kind="structural")
        +>:Expands:+> TypeRef(name="Tree")
        +>:Expands:+> TypeRef(name="Tree");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = AliasChecker();
        root spawn c;
    }
    out = buf.getvalue();

    # The walker must not have been re-entered infinitely — guard fired.
    assert c.cycle_found, f"guard should have flagged the cycle; out={out!r}";

    # The error message must name the cycle participants so a maintainer
    # can see exactly which aliases are looping.
    assert "ERROR" in out, f"missing ERROR marker in: {out!r}";
    assert "Tree" in out, f"cycle label 'Tree' should appear in: {out!r}";
    assert "typealias cycle detected" in out, (
        f"the diagnostic phrasing must name the cycle; got: {out!r}"
    );

    # No crash, no infinite recursion — walker returned cleanly.
    assert "OK" not in out, f"self-ref must NOT be reported OK; out={out!r}";
}

test "two-step mutual cycle is detected and reported" {
    # typealias A = B ; typealias B = A
    a_decl = AliasDecl(name="A", kind="structural");
    b_decl = AliasDecl(name="B", kind="structural");
    a_ref = TypeRef(name="B");
    b_ref = TypeRef(name="A");
    root +>:Aliases:+> a_decl +>:Expands:+> a_ref;
    root +>:Aliases:+> b_decl +>:Expands:+> b_ref;
    a_decl +>:Expands:+> b_ref;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = AliasChecker();
        root spawn c;
    }
    out = buf.getvalue();

    assert c.cycle_found, f"mutual A<->B must be flagged; out={out!r}";
    assert "ERROR" in out, f"missing ERROR marker; out={out!r}";
    # The full cycle should appear in the diagnostic.
    assert "A" in out and "B" in out, (
        f"both labels must appear in the cycle trace; got: {out!r}"
    );
}

test "nominal recursive type still checks and resolves" {
    # type Tree = { l: Tree, r: Tree }  (nominal — terminates at the name)
    root ++> AliasDecl(name="Tree", kind="nominal")
        +>:Expands:+> TypeRef(name="Tree")
        +>:Expands:+> TypeRef(name="Tree");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        c = AliasChecker();
        root spawn c;
    }
    out = buf.getvalue();

    # Nominal aliases terminate at their named boundary; the walker must
    # NOT flag this as a cycle, because the recursion stops on the name.
    assert not c.cycle_found, (
        f"nominal recursion must not trip the cycle guard; out={out!r}"
    );
    assert "OK" in out, f"nominal alias should resolve OK; out={out!r}";
    assert "nominal alias 'Tree' resolves at named boundary" in out, (
        f"expected the nominal-resolution diagnostic; got: {out!r}"
    );
}

test "guard set actually carries visited names" {
    # Direct probe of the guard: start with a name already on the path,
    # the next AliasDecl entry must short-circuit with cycle_found.
    root ++> AliasDecl(name="X", kind="structural")
        +>:Expands:+> TypeRef(name="X")
        +>:Expands:+> TypeRef(name="X");

    c = AliasChecker(on_path=["X"]);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn c;
    }
    out = buf.getvalue();

    # Pre-seeded name on the path means the walker must disengage
    # immediately upon entering the matching AliasDecl.
    assert c.cycle_found, (
        f"pre-seeded guard entry should fire; out={out!r}"
    );
    assert "ERROR" in out, f"expected an error diagnostic; out={out!r}";
}

