    # C is reachable via two paths (diamond). It MUST appear exactly once.
    assert out.count("  enqueued C") == 1, f"C must be enqueued exactly once; got: {out}";
    # E is reachable only via C (which is reached via A and B). Exactly once.
    assert out.count("  enqueued E") == 1, f"E must be enqueued exactly once; got: {out}";
    # A and B are also each reached exactly once.
    assert out.count("  enqueued A") == 1, f"A must be enqueued exactly once; got: {out}";
    assert out.count("  enqueued B") == 1, f"B must be enqueued exactly once; got: {out}";
}

