        planner = ExecutionPlanner();
        root spawn planner;
    }
    out = buf.getvalue();

    # Four reachable steps: A, B, C, E. D and F are disconnected.
    assert len(planner.plan) == 4, f"plan should hold 4 reachable steps; got {len(planner.plan)}: {planner.plan}";
    assert planner.plan == ["A", "B", "C", "E"], f"deterministic order broken: {planner.plan}";
