    assert "D" not in planner.plan, f"D leaked into plan: {planner.plan}";
    assert "G" not in planner.plan, f"G leaked into plan: {planner.plan}";
    assert len(planner.plan) == 3, f"plan should have 3 steps (A,B,C); got {len(planner.plan)}: {planner.plan}";
