        planner = ExecutionPlanner();
        root spawn planner;
    }
    out = buf.getvalue();

    # The diamond convergence implies C is reachable through A and then B;
    # the second entry should be skipped (not enqueued again).
    assert "  skip duplicate enqueue for C" in out, f"expected skip-duplicate log for C; got: {out}";
    # All four reachable nodes should be flagged visited by traversal time.
    assert a.visited is True, "A should be visited";
    assert b.visited is True, "B should be visited";
    assert c.visited is True, "C should be visited";
    assert e.visited is True, "E should be visited";
}

test "linear chain preserves deterministic order without duplicates" {
    s1 = Step(label="S1");
    s2 = Step(label="S2");
    s3 = Step(label="S3");
