    orphan = Step(label="ORPHAN");

    root ++> s1;
    root ++> s2;
    root ++> s3;
    root ++> s4;
    root ++> orphan;

    root +>:DependsOn:+> s1;
    s1 +>:DependsOn:+> s2;
    s2 +>:DependsOn:+> s3;
    s3 +>:DependsOn:+> s4;

