    assert planner.plan == ["S1", "S2", "S3", "S4"], f"linear chain order broken: {planner.plan}";
    assert "  enqueued S1" in out, "S1 should be enqueued";
    assert "  skip duplicate enqueue" not in out, f"no skips expected on linear chain; got: {out}";
    assert "ORPHAN" not in planner.plan, f"orphan leaked: {planner.plan}";
    assert orphan.visited is False, "orphan should not be visited";
    assert len(planner.plan) == 4, f"expected 4-step plan; got {len(planner.plan)}";
