    assert checker.found, f"target should be marked found, got visited={checker.visited}";
    assert "reached project: projA" in out, f"projA visit missing: {out!r}";
    # Cycle-safe: a project is only reported once even though there's a back edge.
    assert out.count("reached project: projA") == 1, f"projA visited more than once: {out!r}";
    assert "[found] target skill 'release-notes' is reachable" in out, f"found marker missing: {out!r}";
}

test "reachability checker reports not found when target absent" {
    buf = io.StringIO();
    p = Project(name="solo", store_root="/s/.agents/skills", manifest_committed=True);
    s = Skill(name="unrelated", has_local_source=False);
    p +>:HasSkill(placed_at="/s/.agents/skills/unrelated/"):+> s;
    root ++> p;

    checker = ReachabilityChecker(target="never-here");
    with redirect_stdout(buf) {
        root spawn checker;
    }
    assert not checker.found, f"should not be found; visited={checker.visited}";
    assert "[found]" not in buf.getvalue(), f"spurious found marker: {buf.getvalue()!r}";
}

