    assert "[skip ] provision_db" in out, f"expected skip provision_db: {out}";
    assert "[skip ] deploy" in out, f"expected skip deploy: {out}";

    # Nothing should have re-executed
    assert nodes["fetch_secrets"].runs == 0, f"fetch_secrets re-ran: {nodes['fetch_secrets'].runs}";
    assert nodes["compile"].runs == 0, f"compile re-ran: {nodes['compile'].runs}";
    assert nodes["build_artifact"].runs == 0, f"build_artifact re-ran: {nodes['build_artifact'].runs}";
    assert nodes["provision_db"].runs == 0, f"provision_db re-ran: {nodes['provision_db'].runs}";
    assert nodes["deploy"].runs == 0, f"deploy re-ran: {nodes['deploy'].runs}";
