    # compile also runs only once even though it's only depended on by build_artifact
    assert nodes["compile"].runs == 1, f"compile ran {nodes['compile'].runs} times";

    # Sanity: the heavy tasks we do expect ran
    assert nodes["build_artifact"].runs == 1, f"build_artifact runs={nodes['build_artifact'].runs}";
    assert nodes["provision_db"].runs == 1, f"provision_db runs={nodes['provision_db'].runs}";
    assert nodes["deploy"].runs == 1, f"deploy runs={nodes['deploy'].runs}";
