test "dependency graph shape matches the issue's scenario" {
    nodes = build_tree();

    # deploy depends on build_artifact and provision_db
    deps = [nodes["deploy"] ->:Requires:->];
    assert nodes["build_artifact"] in deps, "deploy should require build_artifact";
    assert nodes["provision_db"] in deps, "deploy should require provision_db";
    assert len(deps) == 2, f"deploy should have exactly 2 deps, got {len(deps)}";

    # build_artifact depends on compile and fetch_secrets
    bdeps = [nodes["build_artifact"] ->:Requires:->];
    assert nodes["compile"] in bdeps, "build_artifact should require compile";
    assert nodes["fetch_secrets"] in bdeps, "build_artifact should require fetch_secrets";
    assert len(bdeps) == 2, f"build_artifact should have 2 deps, got {len(bdeps)}";

    # compile and provision_db both point at fetch_secrets (the shared node)
    assert nodes["fetch_secrets"] in [nodes["compile"] ->:Requires:->], "compile should require fetch_secrets";
    assert nodes["fetch_secrets"] in [nodes["provision_db"] ->:Requires:->], "provision_db should require fetch_secrets";

    # fetch_secrets has no outgoing Requires edges (it's a leaf dependency)
    leaves = [nodes["fetch_secrets"] ->:Requires:->];
    assert len(leaves) == 0, f"fetch_secrets should be a leaf, got {len(leaves)} deps";

    # root hangs deploy off via a Requires edge with via="pre"
    root_edges = [root ->:Requires:->];
    assert nodes["deploy"] in root_edges, "root should require deploy";
}

