import io;
import from contextlib { redirect_stdout }

test "logical sparse order wins over physical block offsets" {
    first = KvBlock(block_id=1, block_size=3, gm_offset=900, rows=[1, 2, 3]);
    second = KvBlock(block_id=2, block_size=3, gm_offset=100, rows=[4, 5, 6]);
    idx = SparseIndex(index_id=1, slot=0);
    qr = QueryRow(row_id=629, total_pairs=1);

    root ++> qr;
    qr +>:LogicalPair(pair_slot=0):+> idx;
    idx +>:PhysicalAlloc(allocated_at=900):+> first;
    idx +>:PhysicalAlloc(allocated_at=100):+> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.total_slots == 1, f"got {res.total_slots} slots";
    assert "[slot=0] BUG physical-order merged = [4, 5, 6, 1, 2, 3]" in out, f"missing physical ordering: {out}";
    assert "[slot=0] FIX logical-order merged  = [1, 2, 3, 4, 5, 6]" in out, f"missing logical ordering: {out}";
}

test "fixed merge is invariant across allocator layouts" {
    low_first_a = KvBlock(block_id=10, block_size=3, gm_offset=100, rows=[1, 2, 3]);
    high_second_a = KvBlock(block_id=11, block_size=3, gm_offset=500, rows=[4, 5, 6]);
    high_first_b = KvBlock(block_id=12, block_size=3, gm_offset=500, rows=[1, 2, 3]);
    low_second_b = KvBlock(block_id=13, block_size=3, gm_offset=100, rows=[4, 5, 6]);

    idx_a = SparseIndex(index_id=10, slot=0);
    idx_b = SparseIndex(index_id=11, slot=1);
    qr_a = QueryRow(row_id=629, total_pairs=1);
    qr_b = QueryRow(row_id=630, total_pairs=1);

    root ++> qr_a;
    root ++> qr_b;
    qr_a +>:LogicalPair(pair_slot=0):+> idx_a;
    qr_b +>:LogicalPair(pair_slot=1):+> idx_b;

    idx_a +>:PhysicalAlloc(allocated_at=100):+> low_first_a;
    idx_a +>:PhysicalAlloc(allocated_at=500):+> high_second_a;
    idx_b +>:PhysicalAlloc(allocated_at=500):+> high_first_b;
    idx_b +>:PhysicalAlloc(allocated_at=100):+> low_second_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.total_slots == 2, f"got {res.total_slots} slots";
    assert "[slot=0] BUG physical-order merged = [1, 2, 3, 4, 5, 6]" in out, f"missing first physical layout: {out}";
    assert "[slot=1] BUG physical-order merged = [4, 5, 6, 1, 2, 3]" in out, f"missing second physical layout: {out}";
    assert "[slot=0] FIX logical-order merged  = [1, 2, 3, 4, 5, 6]" in out, f"missing first fixed merge: {out}";
    assert "[slot=1] FIX logical-order merged  = [1, 2, 3, 4, 5, 6]" in out, f"missing invariant fixed merge: {out}";
}

