import io;
import from contextlib { redirect_stdout }

test "manifest sequence preserves declared order" {
    manifest = Manifest(sequence=["scaffold", "pre-commit", "config"]);
    scaffold = Milestone(name="scaffold");
    precommit = Milestone(name="pre-commit");
    config_m = Milestone(name="config");

    root ++> manifest;
    manifest +>:Sequence(position=0):+> scaffold;
    manifest +>:Sequence(position=1):+> precommit;
    manifest +>:Sequence(position=2):+> config_m;

    ordered = [manifest ->:Sequence:->];
    assert len(ordered) == 3, f"got {len(ordered)} sequence entries";
    assert ordered[0] == scaffold, f"first entry was {ordered[0].name}";
    assert ordered[1] == precommit, f"second entry was {ordered[1].name}";
    assert ordered[2] == config_m, f"third entry was {ordered[2].name}";
}

test "setup hook visits manifest milestones and reports status" {
    manifest = Manifest(sequence=["scaffold", "config"]);
    scaffold = Milestone(name="scaffold", completed=True);
    config_m = Milestone(name="config", completed=False);

    root ++> manifest;
    manifest +>:Sequence(position=0):+> scaffold;
    manifest +>:Sequence(position=1):+> config_m;

    setup = Setup();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        manifest spawn setup;
    }
    out = buf.getvalue();

    assert len(setup.visited) == 2, f"visited {setup.visited}";
    assert "setup hook: reading manifest with 2 entries" in out, f"missing setup header: {out}";
    assert "setup: scaffold -> DONE" in out, f"missing completed status: {out}";
    assert "setup: config -> PENDING" in out, f"missing pending status: {out}";
}

test "runner executes declared order when milestones are ready" {
    manifest = Manifest(sequence=["scaffold", "pre-commit", "config"]);
    scaffold = Milestone(name="scaffold", completed=True);
    precommit = Milestone(name="pre-commit", completed=True);
    config_m = Milestone(name="config", completed=True);

    root ++> manifest;
    manifest +>:Sequence(position=0):+> scaffold;
    manifest +>:Sequence(position=1):+> precommit;
    manifest +>:Sequence(position=2):+> config_m;

    runner = Runner();
    manifest spawn runner;

    assert runner.order == ["scaffold", "pre-commit", "config"], f"got {runner.order}";
}

test "runner fails closed for an incomplete milestone" {
    manifest = Manifest(sequence=["config"]);
    config_m = Milestone(name="config", completed=False);

    root ++> manifest;
    manifest +>:Sequence(position=0):+> config_m;

    runner = Runner();
    manifest spawn runner;

    assert len(runner.order) == 0, f"unexpected run order {runner.order}";
    assert "BLOCKED by config" in runner.log, f"missing block log: {runner.log}";
}

test "invalidation relationship points from edited milestone downstream" {
    manifest = Manifest(sequence=["config", "tests"]);
    config_m = Milestone(name="config", completed=True);
    tests_m = Milestone(name="tests", completed=True);

    root ++> manifest;
    manifest +>:Sequence(position=0):+> config_m;
    manifest +>:Sequence(position=1):+> tests_m;
    config_m +>:Invalidates:+> tests_m;

    invalidated = [config_m ->:Invalidates:->];
    assert len(invalidated) == 1, f"got {len(invalidated)} invalidation targets";
    assert invalidated[0] == tests_m, f"target was {invalidated[0].name}";
}

