    root ++> proj;
    direct = Package(name="Direct", version="1", license="Apache-2.0");
    forbidden = Package(name="Bad", version="1", license="GPL-3.0");
    direct +>:Declares:+> proj;
    forbidden +>:Declares:+> proj;
    proj +>:DependsOn:+> direct;
    direct +>:DependsOn:+> forbidden;
    forbidden +>:DependsOn:+> direct;
    res = proj spawn LicenseAuditor();
    assert len(res.seen) == 2, f"got {len(res.seen)} seen";
    assert len(res.findings) == 1, f"got {len(res.findings)} findings";
    license_name = res.findings[0]["license"];
    verdict = res.findings[0]["verdict"];
    assert license_name == "GPL-3.0", f"got {license_name}";
    assert verdict == "FORBIDDEN", f"got {verdict}";
}

