    assert "IAsyncEnumerable-Extensions" in audited_names, f"root package missing: {audited_names}";
    assert "Serilog" in audited_names, f"direct dep missing: {audited_names}";
    assert "Confluent.Kafka" in audited_names, f"transitive dep missing: {audited_names}";
    assert "librdkafka.redist" in audited_names, f"deep allowlisted dep missing: {audited_names}";
    assert "AGPL-Utility" in audited_names, f"deep incompatible dep missing: {audited_names}";
    assert not app.flagged, f"allowlisted root package should not be flagged";
    assert not librdkafka.flagged, f"allowlisted transitive package should not be flagged";
    assert agpl.flagged, f"deep AGPL transitive dep should be flagged";

    agpl_verdict = "";
    for entry in res.report {
        if entry["package"] == "AGPL-Utility" {
            agpl_verdict = entry["verdict"];
        }
    }
    assert agpl_verdict == "FAIL", f"AGPL verdict should be FAIL, got {agpl_verdict}";
