        if entry["package"] == "Shared" {
            shared_count = shared_count + 1;
        }
    }
    assert shared_count == 1, f"Shared should be audited once, got {shared_count} in {res.report}";
    assert "Shared" in res.seen, f"Shared should appear in seen list: {res.seen}";
    assert len(res.seen) == 4, f"expected 4 unique names in seen, got {res.seen}";
}

