test "follows calls edges and ignores unrelated links" {
    main = Symbol(name="main", kind="function");
    parse = Symbol(name="parse", kind="function");
    tokenize = Symbol(name="tokenize", kind="function");
    lex = Symbol(name="lex", kind="function");
    unrelated = Symbol(name="unrelated", kind="function");

    root +>:Calls(line=1):+> main;
    main +>:Calls(line=2):+> parse;
    parse +>:Calls(line=3):+> tokenize;
    tokenize +>:Calls(line=4):+> lex;
    root ++> unrelated;

    res = root spawn CallPath(origin="main", target="lex");

    assert res.found, f"target was not found: {res.visited}";
    assert res.path == ["main", "parse", "tokenize", "lex"], f"unexpected path: {res.path}";
    assert "unrelated" not in res.visited, f"untyped node was visited: {res.visited}";
}

test "terminates on call cycles" {
    validate = Symbol(name="validate", kind="function");
    check = Symbol(name="check", kind="function");

    root +>:Calls(line=10):+> validate;
    validate +>:Calls(line=11):+> check;
    check +>:Calls(line=12):+> validate;

    res = root spawn CallPath(origin="validate", target="missing");

    assert not res.found, f"missing target was found: {res.path}";
    assert res.visited == ["validate", "check"], f"cycle was not guarded: {res.visited}";
    assert len(res.visited) == 2, f"duplicate cycle visit detected: {res.visited}";
}

test "stops traversal at the depth cap" {
    first = Symbol(name="first", kind="function");
    second = Symbol(name="second", kind="function");
    third = Symbol(name="third", kind="function");

    root +>:Calls(line=20):+> first;
    first +>:Calls(line=21):+> second;
    second +>:Calls(line=22):+> third;

    res = root spawn CallPath(origin="first", target="third", max_depth=2);

    assert not res.found, f"depth-capped target was found: {res.path}";
    assert res.visited == ["first", "second"], f"unexpected capped traversal: {res.visited}";
    assert "third" not in res.visited, f"node beyond depth cap was visited: {res.visited}";
}

