"""Dependency license audit: walk the transitive dependency graph and flag licenses outside the allowlist."""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has available: bool = True;
}

edge DependsOn {
    has version_range: str = "";
}

walker LicenseAuditor {
    has allowlist: list[str] = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"];
    has seen: list[str] = [];
    has violations: list[str] = [];

    def is_allowed(lic: str) -> bool {
        for entry in self.allowlist {
            if entry == lic {
                return True;
            }
        }
        return False;
    }

    def already_seen(n: Package) -> bool {
        for s in self.seen {
            if s == n.name {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        if self.already_seen(here) {
            visit [-->];
            return;
        }
        self.seen.append(here.name);

        if not self.is_allowed(here.license) {
            finding = f"[VIOLATION] {here.name}@{here.version} -> {here.license}";
            self.violations.append(finding);
            print(finding);
        } else {
            print(f"[OK] {here.name}@{here.version} -> {here.license}");
        }

        visit [->:DependsOn:->];
    }
}

with entry {
    root ++> Package(name="DbContextBuilder", version="1.0.0", license="MIT")
        +>:DependsOn(version_range=">=2.0"):+> Package(name="EntityFrameworkCore", version="8.0.0", license="Apache-2.0")
        +>:DependsOn(version_range=">=1.0"):+> Package(name="Newtonsoft.Json", version="13.0.1", license="MIT");

    efcore = Package(name="EntityFrameworkCore", version="8.0.0", license="Apache-2.0");
    Package(name="Microsoft.Data.Sqlite", version="8.0.0", license="Apache-2.0")
        +>:DependsOn:+> Package(name="SQLitePCLRaw.bundle_e_sqlite", version="2.1.0", license="MIT");

    root +>:DependsOn:+> Package(name="LegacyGPLLib", version="0.1.0", license="GPL-3.0");
    root +>:DependsOn:+> Package(name="ProprietaryToolkit", version="2.3.4", license="BUSINESS-SOURCE");

    auditor = LicenseAuditor();
    root spawn auditor;

    print("");
    print(f"Packages scanned: {len(auditor.seen)}");
    print(f"Violations found: {len(auditor.violations)}");
    for v in auditor.violations {
        print(v);
    }
}
