    assert len(res.seen) == 2, f"expected 2 transitive packages, got {res.seen}";
    assert len(res.violations) == 1, f"expected 1 violation, got {res.violations}";
    assert "[OK] DbContextBuilder@1.0.0 -> MIT" in out, f"missing OK for root dep: {out}";
    assert "[VIOLATION] HiddenGPL@1.0.0 -> GPL-3.0" in out, f"missing transitive violation: {out}";
}

test "deduplicates shared transitive packages reached via multiple paths" {
    shared = Package(name="SharedLib", version="1.0.0", license="Apache-2.0");
    left = Package(name="LeftDep", version="1.0.0", license="MIT");
    right = Package(name="RightDep", version="1.0.0", license="MIT");
    root ++> left;
    root ++> right;
    left +>:DependsOn:+> shared;
    right +>:DependsOn:+> shared;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LicenseAuditor();
    }
    assert len(res.seen) == 3, f"expected 3 unique packages, got {res.seen}";
    assert len(res.violations) == 0, f"allowlisted shared dep should not violate: {res.violations}";
    shared_count = 0;
    for s in res.seen {
        if s == "SharedLib" {
            shared_count += 1;
        }
    }
    assert shared_count == 1, f"SharedLib should be scanned once, got {shared_count} in {res.seen}";
}

test "flags unknown license not on allowlist" {
    root ++> Package(name="MysteryPkg", version="0.0.1", license="UNKNOWN");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LicenseAuditor();
    }
    out = buf.getvalue();
    assert len(res.violations) == 1, f"unknown license should violate, got {res.violations}";
    assert "[VIOLATION] MysteryPkg@0.0.1 -> UNKNOWN" in out, f"missing violation output: {out}";
}

