import io;
import from contextlib { redirect_stdout }

test "post-burst stale summary flags all four drifts" {
    summary = StateSummary(
        l3_bc_count=42,
        l4_vp_count=57,
        total_stories=23,
        total_points=140
    );
    root +>:Audits:+> summary;
    res = root spawn ConsistencyAuditor();
    assert len(res.report.drifts) == 4,
        f"expected 4 drifts for stale summary, got {len(res.report.drifts)}: {res.report.drifts}";
}

test "recomputed summary passes with no drifts" {
    summary = StateSummary(
        l3_bc_count=43,
        l4_vp_count=58,
        total_stories=24,
        total_points=143
    );
    root +>:Audits:+> summary;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ConsistencyAuditor();
    }
    out = buf.getvalue();
    assert len(res.report.drifts) == 0,
        f"expected no drifts after recompute, got {res.report.drifts}";
    assert "no drift" in out, f"missing no-drift marker in output: {out}";
}

test "stale bc and vp counts produce targeted drift messages" {
    summary = StateSummary(
        l3_bc_count=42,
        l4_vp_count=57,
        total_stories=24,
        total_points=143
    );
    root +>:Audits:+> summary;
    res = root spawn ConsistencyAuditor();
    found_bc = False;
    found_vp = False;
    for d in res.report.drifts {
        if "l3_bc_count" in d and "claimed 42" in d and "true 43" in d {
            found_bc = True;
        }
        if "l4_vp_count" in d and "claimed 57" in d and "true 58" in d {
            found_vp = True;
        }
    }
    assert found_bc, f"BC count drift missing in {res.report.drifts}";
    assert found_vp, f"VP count drift missing in {res.report.drifts}";
}

test "stale story totals produce targeted drift messages" {
    summary = StateSummary(
        l3_bc_count=43,
        l4_vp_count=58,
        total_stories=23,
        total_points=140
    );
    root +>:Audits:+> summary;
    res = root spawn ConsistencyAuditor();
    found_stories = False;
    found_points = False;
    for d in res.report.drifts {
        if "total_stories" in d and "claimed 23" in d and "true 24" in d {
            found_stories = True;
        }
        if "total_points" in d and "claimed 140" in d and "true 143" in d {
            found_points = True;
        }
    }
    assert found_stories, f"story count drift missing in {res.report.drifts}";
    assert found_points, f"story points drift missing in {res.report.drifts}";
}

test "auditor stdout reports drift count for stale summary" {
    summary = StateSummary(
        l3_bc_count=42,
        l4_vp_count=57,
        total_stories=23,
        total_points=140
    );
    root +>:Audits:+> summary;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ConsistencyAuditor();
    }
    out = buf.getvalue();
    assert "4 drift(s) found" in out,
        f"expected drift count in stdout, got: {out}";
    assert len(res.report.drifts) == 4,
        f"stdout said 4 drifts but report has {len(res.report.drifts)}";
}

