test "refusal probe accepts positive app and rejects each negative control with stated reason" {
    root ++> DancerApp(appname="HelloWorld");
    pos = [root -->][0];

    root ++> DancerApp(appname="");
    neg_dyn = [root-->][1];

    root ++> DancerApp(appname="Broken", missing_module=True);
    neg_missing = [root-->][2];

    root ++> DancerApp(appname="OldApp", supported_version=False);
    neg_version = [root-->][3];

    root ++> DancerApp(appname="CoreOnly", core_only=True);
    neg_core = [root-->][4];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p_pos = pos spawn RefusalProbe();
        p_dyn = neg_dyn spawn RefusalProbe();
        p_missing = neg_missing spawn RefusalProbe();
        p_version = neg_version spawn RefusalProbe();
        p_core = neg_core spawn RefusalProbe();
    }
    out = buf.getvalue();

