    assert p_dyn.reason == "dynamic appname", f"dynamic appname reason wrong: {p_dyn.reason}";
    assert p_missing.reason == "missing Dancer2 module", f"missing reason wrong: {p_missing.reason}";
    assert p_version.reason == "unsupported Dancer2 version", f"version reason wrong: {p_version.reason}";
    assert p_core.reason == "Dancer2::Core only", f"core-only reason wrong: {p_core.reason}";

    assert "ACCEPTED" in out, f"missing ACCEPTED marker: {out}";
    assert out.count("REFUSAL:") == 4, f"expected 4 REFUSAL lines, got {out.count('REFUSAL:')}: {out}";
    assert "REFUSAL: dynamic appname" in out, f"dynamic refusal not printed: {out}";
    assert "REFUSAL: missing Dancer2 module" in out, f"missing refusal not printed: {out}";
    assert "REFUSAL: unsupported Dancer2 version" in out, f"version refusal not printed: {out}";
    assert "REFUSAL: Dancer2::Core only" in out, f"core-only refusal not printed: {out}";
