test "ref walker cycle guard prevents revisiting the same ref target" {
    root ++> DancerApp(appname="LoopApp");
    app = [root -->][0];

    # Two refs with identical (target, ref_kind) — second must be skipped
    # by the visited set in follow_ref.
    app +>:ReferencesRoute:+> RouteRef(target_name="loop", ref_kind="literal", safe_for_rename=True);
    app +>:ReferencesRoute:+> RouteRef(target_name="loop", ref_kind="literal", safe_for_rename=True);
    # A third ref with a different ref_kind must still be tallied.
    app +>:ReferencesRoute:+> RouteRef(target_name="loop", ref_kind="dynamic", safe_for_rename=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ConformanceAuditor();
    }
    out = buf.getvalue();

    assert res.ref_count == 2, f"cycle guard must dedupe literal refs, got ref_count={res.ref_count}";
    assert out.count("ref -> loop [literal") == 1, f"literal ref printed twice: {out}";
    assert out.count("ref -> loop [dynamic") == 1, f"dynamic ref not printed: {out}";
}

