"""Learning-path routing demo.

Models the digital-synth knowledge-base routing problem: nine orphan
documents must be attached to role-based learning paths so that a
reader walking the graph from the root reaches every document. The
walker performs the same reachability traversal that the issue
complains about being hand-rolled, and reports any document that is
still orphaned.
"""

node Document {
    has title: str = "";
    has difficulty: int = 0;
    has routed: bool = False;
}

node LearningPath {
    has role: str = "";
    has depth: int = 0;
}

edge Contains {
    has order: int = 0;
}

walker RouteAuditor {
    has visited_docs: list = [];
    has visited_paths: list = [];
    has orphans: list = [];

    can start with Root entry {
        print("Beginning learning-path routing audit");
        visit [-->];
    }

    can audit_path with LearningPath entry {
        self.visited_paths.append(here.role);
        print(f"Path: {here.role} (depth {here.depth})");
        visit [->:Contains:->];
    }

    can audit_doc with Document entry {
        title = here.title if here.title != "" else "untitled";
        if not here.routed {
            self.orphans.append(title);
        }
        self.visited_docs.append(title);
        visit [->:Contains:->];
    }

    can collect_doc with Document entry {
        title = here.title if here.title != "" else "untitled";
        here.routed = True;
        self.visited_docs.append(title);
    }
}

walker OrphanScanner {
    has orphans: list = [];

    can start with Root entry {
        print("Scanning for orphaned documents");
        visit [-->];
    }

    can check with Document entry {
        if not here.routed {
            self.orphans.append(here.title);
            print(f"  ORPHAN: {here.title}");
        }
        visit [-->];
    }

    can skip_path with LearningPath entry {
        visit [-->];
    }
}

with entry {
    beginner = LearningPath(role="Beginner", depth=1);
    sound = LearningPath(role="Sound Design", depth=2);
    dsp = LearningPath(role="DSP/Developer", depth=3);
    advanced = LearningPath(role="Advanced Synthesis", depth=4);

    root ++> beginner ++> sound ++> dsp ++> advanced;

    fm = Document(title="fm-synthesis-deep-dive", difficulty=9, routed=True);
    wt = Document(title="wavetable-synthesis-deep-dive", difficulty=9, routed=True);
    gran = Document(title="granular-synthesis-deep-dive", difficulty=9, routed=True);
    ring = Document(title="ring-modulation-and-am", difficulty=6, routed=True);
    noise = Document(title="noise-types-and-modulation", difficulty=5, routed=True);
    bit = Document(title="bit-reduction-and-lofi-effects", difficulty=5, routed=True);
    voc = Document(title="vocoding-and-formant-synthesis", difficulty=7, routed=True);
    stereo = Document(title="stereo-and-spatial-processing", difficulty=5, routed=True);
    arp = Document(title="arpeggiator-and-sequencer-design", difficulty=6, routed=True);
    filters = Document(title="filters-and-tone-shaping", difficulty=4, routed=True);

    advanced +>:Contains(order=1):+> fm;
    advanced +>:Contains(order=2):+> wt;
    advanced +>:Contains(order=3):+> gran;

    sound +>:Contains(order=1):+> ring;
    sound +>:Contains(order=2):+> noise;
    sound +>:Contains(order=3):+> bit;
    sound +>:Contains(order=4):+> voc;
    sound +>:Contains(order=5):+> stereo;
    sound +>:Contains(order=6):+> arp;
    sound +>:Contains(order=7):+> filters;

    auditor = RouteAuditor();
    root spawn auditor;

    print(f"\nDocuments visited: {len(auditor.visited_docs)}");
    print(f"Paths visited: {auditor.visited_paths}");
    print(f"Orphans detected: {auditor.orphans}");

    orphan_check = OrphanScanner();
    root spawn orphan_check;
    print(f"\nFinal orphan count: {len(orphan_check.orphans)}");
    print("All knowledge-base documents are now routed" if len(orphan_check.orphans) == 0 else "Some documents remain unrouted");
}
