"""Regression tests for the moose #33227 mesh pipeline reproducer.

Each test builds its own graph, spawns PipelineExecutor, and asserts on the
order-dependent logging that the executor emits. The hazards we care about:

  - junction log lines always appear AFTER the matching component's
    addMeshGenerator lines for the same component,
  - a junction on a component with zero generators logs the
    "NO generator" disconnected-stitch message,
  - declaration order of the hand-rolled generator list is preserved in the
    log,
  - the executor does not revisit nodes it has already processed.
"""

import io;
import from contextlib { redirect_stdout }

test "junction lines come after generators for the same component" {
    buf = io.StringIO();
    comp = Component(
        name="alpha",
        generators=[
            MeshGenerator(name="g1", offset=0.0),
            MeshGenerator(name="g2", offset=1.0),
        ],
        junctions=[ComponentJunction(name="junc_a")],
    );
    root ++> comp;
    with redirect_stdout(buf) {
        res = root spawn PipelineExecutor();
    }
    out = buf.getvalue();
    log = res.log;

    # Find indices of relevant log entries.
    g1_idx = -1;
    g2_idx = -1;
    j_idx = -1;
    i = 0;
    while i < len(log) {
        e = log[i];
        if e == f"addMeshGenerator on alpha: g1" and g1_idx == -1 {
            g1_idx = i;
        }
        if e == f"addMeshGenerator on alpha: g2" and g2_idx == -1 {
            g2_idx = i;
        }
        if e.startswith("junction junc_a on alpha -> stitches from last generator g2") and j_idx == -1 {
            j_idx = i;
        }
        i += 1;
    }
    assert g1_idx >= 0, f"missing g1 in log: {log}";
    assert g2_idx >= 0, f"missing g2 in log: {log}";
    assert j_idx >= 0, f"missing junction stitch line in log: {log}";
    assert g1_idx < g2_idx < j_idx, (
        f"expected g1 < g2 < junction, got {g1_idx}, {g2_idx}, {j_idx}: {log}"
    );
}

test "junction on a generator-less component logs disconnected stitch" {
    buf = io.StringIO();
    bare = Component(
        name="bare",
        generators=[],
        junctions=[ComponentJunction(name="bare_junc")],
    );
    root ++> bare;
    with redirect_stdout(buf) {
        res = root spawn PipelineExecutor();
    }
    log = res.log;

    found = False;
    i = 0;
    while i < len(log) {
        if log[i] == (
            "!! junction bare_junc on bare found "
            "NO generator -> stitches disconnected mesh"
        ) {
            found = True;
        }
        i += 1;
    }
    assert found, f"missing NO-generator hazard line in log: {log}";

    # And no stitch-from line should have been emitted for this junction.
    i = 0;
    while i < len(log) {
        assert not log[i].startswith("junction bare_junc on bare -> stitches"), (
            f"unexpected stitch line emitted on empty generator list: {log[i]}"
        );
        i += 1;
    }
}

test "addMeshGenerator entries preserve declaration order in the log" {
    buf = io.StringIO();
    comp = Component(
        name="ordered",
        generators=[
            MeshGenerator(name="first", offset=0.0),
            MeshGenerator(name="second", offset=1.0),
            MeshGenerator(name="third", offset=2.0),
        ],
        junctions=[],
    );
    root ++> comp;
    with redirect_stdout(buf) {
        res = root spawn PipelineExecutor();
    }
    log = res.log;

    # Extract the ordered sub-sequence of addMeshGenerator lines for this comp.
    seq = [];
    i = 0;
    while i < len(log) {
        e = log[i];
        if e.startswith("addMeshGenerator on ordered: ") {
            seq.append(e[len("addMeshGenerator on ordered: "):]);
        }
        i += 1;
    }
    assert seq == ["first", "second", "third"], (
        f"declaration order not preserved, got {seq}"
    );
}

test "executor visits each component once and emits exactly one stitch per junction" {
    buf = io.StringIO();
    a = Component(
        name="A",
        generators=[MeshGenerator(name="ag", offset=0.0)],
        junctions=[ComponentJunction(name="aj1"), ComponentJunction(name="aj2")],
    );
    b = Component(
        name="B",
        generators=[MeshGenerator(name="bg", offset=0.0)],
        junctions=[ComponentJunction(name="bj1")],
    );
    root ++> a;
    root ++> b;
    with redirect_stdout(buf) {
        res = root spawn PipelineExecutor();
    }
    log = res.log;

    # Count stitch-from lines per junction (should be exactly one each).
    counts = {"aj1": 0, "aj2": 0, "bj1": 0};
    i = 0;
    while i < len(log) {
        e = log[i];
        if e.startswith("junction aj1 on A -> stitches") {
            counts["aj1"] += 1;
        }
        if e.startswith("junction aj2 on A -> stitches") {
            counts["aj2"] += 1;
        }
        if e.startswith("junction bj1 on B -> stitches") {
            counts["bj1"] += 1;
        }
        i += 1;
    }
    assert counts == {"aj1": 1, "aj2": 1, "bj1": 1}, (
        f"each junction should fire exactly once, got {counts}; full log: {log}"
    );

    # addMeshGenerator lines must also appear exactly once per registered gen.
    gen_counts = {"ag": 0, "bg": 0};
    i = 0;
    while i < len(log) {
        e = log[i];
        if e == "addMeshGenerator on A: ag" {
            gen_counts["ag"] += 1;
        }
        if e == "addMeshGenerator on B: bg" {
            gen_counts["bg"] += 1;
        }
        i += 1;
    }
    assert gen_counts == {"ag": 1, "bg": 1}, (
        f"each generator should be added exactly once, got {gen_counts}; log: {log}"
    );
}

test "late-declared generator does not retroactively satisfy already-logged junction" {
    # Mirrors the issue's hazard: a component ends up with a junction list
    # populated and a generator list that is mutated to contain a mesh
    # generator AFTER the junction was registered. The executor still sees
    # whatever the lists look like at dispatch time, so the junction's
    # "last generator" lookup uses the current tail of the generators list.
    buf = io.StringIO();
    late = Component(name="late", generators=[], junctions=[ComponentJunction(name="late_j")]);
    root ++> late;
    late.generators = [MeshGenerator(name="late_g", offset=9.0)];
    with redirect_stdout(buf) {
        res = root spawn PipelineExecutor();
    }
    log = res.log;

    found_stitch = False;
    found_no_gen = False;
    i = 0;
    while i < len(log) {
        e = log[i];
        if e.startswith("junction late_j on late -> stitches from last generator late_g") {
            found_stitch = True;
        }
        if e.startswith("!! junction late_j on late found NO generator") {
            found_no_gen = True;
        }
        i += 1;
    }
    assert found_stitch, f"expected stitch from late_g once generator exists, log: {log}";
    assert not found_no_gen, (
        f"late-declared generator should satisfy the junction, not trigger hazard, log: {log}"
    );
}

