    );
    root ++> client;

    res = root spawn FixedDescendantsWalker();

    assert len(res.collected) == 4076,
        f"fixed closure size: {len(res.collected)}";
    assert res.collected[0] == "GO:0005575-d0",
        f"first term: {res.collected[0]}";
    assert res.collected[4075] == "GO:0005575-d4075",
        f"last term: {res.collected[4075]}";
}

test "pagination handles partial final page" {
    client = OlsClient(
        term_curie="TEST:ROOT", total_terms=1201, page_size=500
    );
    root ++> client;

    legacy = root spawn LegacyDescendantsWalker();
    fixed = root spawn FixedDescendantsWalker();

    assert client.page_count() == 3,
        f"page count: {client.page_count()}";
    assert len(client.curies_for_page(3)) == 201,
        f"final page size: {len(client.curies_for_page(3))}";
    assert len(legacy.collected) == 500,
        f"legacy collection: {len(legacy.collected)}";
    assert len(fixed.collected) == 1201,
        f"fixed collection: {len(fixed.collected)}";
}

