"""Regression tests for the Observability graph (GAP-20 demo)."""

import io;
import from contextlib { redirect_stdout }

# --- Test 1: every Recorder surfaces a complete inventory of hooks ---
test "audit walks Recorder and counts all signals" {
    rec = Recorder(name="InventoryCheck");

    rec +>:Hooked(since="v1"):+> RpcHook(label="rpcStarted", wired=True);
    rec +>:Hooked(since="v1"):+> RpcHook(label="rpcCompleted", wired=True);
    rec +>:Hooked(since="v1"):+> RetryHook(label="retryAttempted", wired=True);
    rec +>:Hooked(since="v1"):+> CacheHook(label="regionCacheHit", wired=True);
    rec +>:Hooked(since="v1"):+> CacheHook(label="regionCacheMiss", wired=True);
    rec +>:Hooked(since="v1"):+> RegionInvalidationHook(label="regionInvalidated", wired=True);

    rec +>:Hooked(since="v2"):+> Metric(label="backoff_duration", name="backoff_duration", kind="histogram", wired=True);
    rec +>:Hooked(since="v2"):+> Metric(label="per_store_outcome", name="per_store_outcome", kind="counter", wired=True);
    rec +>:Hooked(since="v2"):+> Metric(label="lock_resolution_count", name="lock_resolution_count", kind="counter", wired=True);
    rec +>:Hooked(since="v2"):+> Metric(label="2pc_prewrite_ms", name="2pc_prewrite_ms", kind="histogram", wired=True);
    rec +>:Hooked(since="v2"):+> Metric(label="2pc_commit_ms", name="2pc_commit_ms", kind="histogram", wired=True);

    rec +>:Hooked(since="v2"):+> TraceCallback(label="txn_2pc", span_name="txn_2pc", category="CategoryTxn2PC", wired=True);
    rec +>:Hooked(since="v2"):+> TraceCallback(label="kv_request", span_name="kv_request", category="CategoryKVRequest", wired=True);

    root ++> rec;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ObservabilityAuditor();
    }

    # 13 signals total: 6 v1 hooks + 5 v2 metrics + 2 v2 trace callbacks.
    assert len(res.missing) == 0, f"expected no gaps, got {res.missing}";

    out = buf.getvalue();
    assert "Recorder: InventoryCheck" in out, f"recorder header missing: {out!r}";
    assert "[WIRED] backoff_duration" in out, f"backoff metric not inspected: {out!r}";
    assert "[WIRED] 2pc_prewrite_ms" in out, f"2pc prewrite not inspected: {out!r}";
    assert "[WIRED] txn_2pc [CategoryTxn2PC]" in out, f"trace callback not inspected: {out!r}";
}

# --- Test 2: the GAP is correctly surfaced when v1 cache/invalidation hooks are no-ops ---
test "no-op cache hooks are reported as missing" {
    rec = Recorder(name="DefaultNoOp");

    rec +>:Hooked(since="v1"):+> RpcHook(label="rpcStarted", wired=True);
    rec +>:Hooked(since="v1"):+> RpcHook(label="rpcCompleted", wired=True);
    rec +>:Hooked(since="v1"):+> RetryHook(label="retryAttempted", wired=True);
    rec +>:Hooked(since="v1"):+> CacheHook(label="regionCacheHit", wired=False);
    rec +>:Hooked(since="v1"):+> CacheHook(label="regionCacheMiss", wired=False);
    rec +>:Hooked(since="v1"):+> RegionInvalidationHook(label="regionInvalidated", wired=False);

    rec +>:Hooked(since="v2"):+> Metric(label="backoff_duration", name="backoff_duration", kind="histogram", wired=False);
    rec +>:Hooked(since="v2"):+> Metric(label="2pc_commit_ms", name="2pc_commit_ms", kind="histogram", wired=False);

    root ++> rec;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ObservabilityAuditor();
    }

    missing = res.missing;
    # 2 cache hooks + 1 region invalidation + 2 v2 metrics = 5 gaps.
    assert len(missing) == 5, f"expected 5 missing, got {len(missing)}: {missing}";
    assert "regionCacheHit" in missing, f"regionCacheHit must be flagged: {missing}";
    assert "regionCacheMiss" in missing, f"regionCacheMiss must be flagged: {missing}";
    assert "regionInvalidated" in missing, f"regionInvalidated must be flagged: {missing}";
    assert "backoff_duration" in missing, f"backoff_duration must be flagged: {missing}";
    assert "2pc_commit_ms" in missing, f"2pc_commit_ms must be flagged: {missing}";

    out = buf.getvalue();
    assert "[GAP] regionCacheHit" in out, f"cache hit should print as GAP: {out!r}";
    assert "[GAP] backoff_duration" in out, f"backoff metric should print as GAP: {out!r}";
}

# --- Test 3: trace callbacks with categories are inspected (OpenTelemetry bridge hook) ---
test "trace callbacks are walked and category is rendered" {
    rec = Recorder(name="TracingRecorder");

    rec +>:Hooked(since="v2"):+> TraceCallback(label="txn_2pc", span_name="txn_2pc", category="CategoryTxn2PC", wired=True);
    rec +>:Hooked(since="v2"):+> TraceCallback(label="txn_lock_resolve", span_name="txn_lock_resolve", category="CategoryTxnLockResolve", wired=True);
    rec +>:Hooked(since="v2"):+> TraceCallback(label="kv_request", span_name="kv_request", category="CategoryKVRequest", wired=False);
    rec +>:Hooked(since="v2"):+> TraceCallback(label="region_cache", span_name="region_cache", category="CategoryRegionCache", wired=False);

    root ++> rec;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ObservabilityAuditor();
    }

    assert len(res.missing) == 2, f"expected 2 missing trace callbacks, got {res.missing}";
    assert "kv_request" in res.missing, f"kv_request should be missing: {res.missing}";
    assert "region_cache" in res.missing, f"region_cache should be missing: {res.missing}";

    out = buf.getvalue();
    assert "[WIRED] txn_2pc [CategoryTxn2PC]" in out, f"txn_2pc category not rendered: {out!r}";
    assert "[WIRED] txn_lock_resolve [CategoryTxnLockResolve]" in out, f"lock_resolve category not rendered: {out!r}";
    assert "[GAP] region_cache [CategoryRegionCache]" in out, f"region_cache GAP not rendered: {out!r}";
}

# --- Test 4: typed Hooked edges are the only traversal path; graph shape is preserved ---
test "hooked edges establish the recorder-to-signal graph" {
    rec = Recorder(name="ShapeCheck");

    rec +>:Hooked(since="v1"):+> RpcHook(label="rpcStarted", wired=True);
    rec +>:Hooked(since="v2"):+> Metric(label="backoff_duration", name="backoff_duration", kind="histogram", wired=False);

    root ++> rec;

    # Recorder is linked from Root by an untyped edge.
    recs = [root-->];
    assert len(recs) == 1, f"expected exactly one recorder off root, got {len(recs)}";
    assert recs[0].name == "ShapeCheck", f"unexpected recorder: {recs[0].name}";

    # Typed Hooked edges out of the recorder must number 2.
    hooked = [rec ->:Hooked:->];
    assert len(hooked) == 2, f"expected 2 hooked signals, got {len(hooked)}";

    # Run the auditor and verify exactly one gap (the backoff metric).
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ObservabilityAuditor();
    }
    assert res.missing == ["backoff_duration"], f"expected only backoff missing, got {res.missing}";
}

