test "audit detects a synchronous dependency cycle" {
    sales = Sales(name="Sales");
    inventory = Inventory(name="Inventory");
    orchestrator = Orchestrator(name="OrderWorkflow");

    orchestrator +>:CallsSync(operation="create_order"):+> sales;
    sales +>:CallsSync(operation="reserve"):+> inventory;
    inventory +>:CallsSync(operation="availability"):+> sales;
    root ++> orchestrator;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditModules();
    }
    out = buf.getvalue();

    assert res.cycle_detected == True, f"got {res.cycle_detected}";
    assert len(res.visited) == 2, f"visited modules: {res.visited}";
