    assert start_steps == 2, f"got {start_steps} start steps";
    assert len(res.visited) == 4, f"got {len(res.visited)} visited cells";
    assert merge_hits == 1, f"got {merge_hits} merge visits";
    assert res.answer == -1, f"got {res.answer}";
}

