"""Tests for the gated descendant loads walker."""

import io;
import from contextlib { redirect_stdout }

test "gated layout blocks descendants and runs its own load step" {
    authed = LayoutGroup(name="(authenticated)", gated=True, resolves_user=True);
    inner = LayoutGroup(name="(dashboard)", gated=False);
    root ++> authed ++> inner;

    dashboard_page = Page(title="dashboard");
    settings_page = Page(title="settings");
    inner ++> dashboard_page;
    inner ++> settings_page;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = authed spawn LoadRunner();
    }
    out = buf.getvalue();

    assert "(authenticated)" in res.pending, f"authed layout should record itself: {res.pending}";
    assert "(dashboard)" in res.pending, f"inner layout should still be visited: {res.pending}";
    assert "dashboard" in res.pending, f"dashboard page must run after gate: {res.pending}";
    assert "settings" in res.pending, f"settings page must run after gate: {res.pending}";
    assert res.aborted == False, f"gate should not abort, got {res.aborted}";
    assert "resolved user in (authenticated)" in out, f"expected user resolution print: {out}";
    assert "gate cleared: (authenticated)" in out, f"expected gate cleared print: {out}";
    assert dashboard_page.has_run == True, "dashboard page should have run";
    assert settings_page.has_run == True, "settings page should have run";
}

test "nested gated layouts chain sequentially outermost to innermost" {
    outer = LayoutGroup(name="(outer-gated)", gated=True, resolves_user=True);
    middle = LayoutGroup(name="(middle-gated)", gated=True);
    innermost = LayoutGroup(name="(inner-ungated)", gated=False);
    root ++> outer ++> middle ++> innermost;

    p = Page(title="innermost_page");
    innermost ++> p;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = outer spawn LoadRunner();
    }
    out = buf.getvalue();

    outer_idx = res.pending.index("(outer-gated)");
    middle_idx = res.pending.index("(middle-gated)");
    inner_idx = res.pending.index("(inner-ungated)");
    page_idx = res.pending.index("innermost_page");
    assert outer_idx < middle_idx, f"outer gate must precede middle: {res.pending}";
    assert middle_idx < inner_idx, f"middle gate must precede inner layout: {res.pending}";
    assert inner_idx < page_idx, f"descendant must run after all gated ancestors: {res.pending}";

    o_pos = out.find("gate cleared: (outer-gated)");
    m_pos = out.find("gate cleared: (middle-gated)");
    assert o_pos >= 0 and m_pos >= 0 and o_pos < m_pos, f"gates should clear outermost first: {out!r}";
    assert p.has_run == True, "page under nested gates must still run when no abort";
}

test "redirect from gated layout aborts every descendant" {
    locked = LayoutGroup(name="(locked)", gated=True, redirects_to="/login");
    child_a = Page(title="secret_a");
    child_b = Page(title="secret_b");
    locked ++> child_a;
    locked ++> child_b;
    root ++> locked;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = locked spawn LoadRunner();
    }
    out = buf.getvalue();

    assert res.aborted == True, f"redirecting gate must abort run, got aborted={res.aborted}";
    assert "redirect -> /login (no descendants will load)" in out, f"expected redirect print: {out}";
    assert "secret_a" not in res.pending, f"secret_a must NOT run after redirect: {res.pending}";
    assert "secret_b" not in res.pending, f"secret_b must NOT run after redirect: {res.pending}";
    assert child_a.has_run == False, "secret_a page must be blocked by redirecting gate";
    assert child_b.has_run == False, "secret_b page must be blocked by redirecting gate";
}

test "ungated layouts do not emit gate output and still descend" {
    public = LayoutGroup(name="(public)", gated=False);
    landing = Page(title="landing");
    about = Page(title="about");
    public ++> landing;
    public ++> about;
    root ++> public;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = public spawn LoadRunner();
    }
    out = buf.getvalue();

    assert "(public)" in res.pending, f"layout itself should be recorded: {res.pending}";
    assert "landing" in res.pending, f"landing must run: {res.pending}";
    assert "about" in res.pending, f"about must run: {res.pending}";
    assert res.aborted == False, f"non-gated layout must not abort: {res.aborted}";
    assert "gate cleared" not in out, f"non-gated layout must not print gate output: {out!r}";
    assert "redirect ->" not in out, f"non-gated layout must not print redirect: {out!r}";
    assert "resolved user" not in out, f"non-gated layout must not print user resolve: {out!r}";
    assert landing.has_run == True, "landing must run under ungated layout";
    assert about.has_run == True, "about must run under ungated layout";
}

