"""Glasswork Parent Task hierarchy: typed edges, leaf-first execution, ancestor rollup.

Models the core scenario from Issue #505: tasks form a parent/child hierarchy,
only Parent Tasks own cross-file children, leaves carry actionable work, and a
walker traverses the tree to gather an ancestor breadcrumb and roll up child
activity without distributed write coordination.
"""

node Task {
    has title: str = "";
    has kind: str = "task";
    has source_kind: str = "";
    has available: bool = True;
    has notes: int = 0;
    has artifacts: int = 0;
}

edge OwnsChild {
    has created_on: str = "";
}

walker HierarchyInspector {
    has path: list[str] = [];
    has rollup_notes: int = 0;
    has rollup_artifacts: int = 0;
    has leaf_count: int = 0;
    has parent_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can descend with Task entry {
        if here.kind == "parent" {
            self.parent_count += 1;
            self.path = self.path + [here.title];
        } else {
            self.leaf_count += 1;
            self.rollup_notes += here.notes;
            self.rollup_artifacts += here.artifacts;
            label = "[LEAF ] " + here.title;
            print(label);
            return;
        }
        print(f"[PARENT] {here.title} (source={here.source_kind})");
        visit [->:OwnsChild:->];
    }
}

with entry {
    epic = Task(title="Epic: Identity Platform", kind="parent", source_kind="Epic");
    feature = Task(title="Feature: SSO Login", kind="parent", source_kind="Feature");
    pbi = Task(title="PBI: OAuth Flow", kind="parent", source_kind="Product Backlog Item");
    story = Task(title="User Story: Token Refresh", kind="parent", source_kind="User Story");
    bug_leaf = Task(title="Bug: refresh races", kind="bug", source_kind="Bug",
                    notes=2, artifacts=1);
    task_leaf = Task(title="Task: implement refresh", kind="task", source_kind="Task",
                     notes=5, artifacts=3);
    bug_leaf2 = Task(title="Bug: expired token UI", kind="bug", source_kind="Bug",
                     notes=1, artifacts=0);

    root +>:OwnsChild:+> epic;
    epic +>:OwnsChild:+> feature;
    feature +>:OwnsChild:+> pbi;
    pbi +>:OwnsChild:+> story;
    story +>:OwnsChild:+> task_leaf;
    story +>:OwnsChild:+> bug_leaf;
    pbi +>:OwnsChild:+> bug_leaf2;

    inspector = HierarchyInspector();
    root spawn inspector;

    breadcrumb = " > ".join(inspector.path) if len(inspector.path) > 0 else "(no parents)";
    print("---");
    print(f"breadcrumb: {breadcrumb}");
    print(f"parents traversed: {inspector.parent_count}");
    print(f"leaves found:      {inspector.leaf_count}");
    print(f"rolled-up notes:   {inspector.rollup_notes}");
    print(f"rolled-up artifacts:{inspector.rollup_artifacts}");
}
