test "ProductCounter tallies products via CategorizedAs edges" {
    cat = Category(id="c1", name="Food", slug="food", display_order=1);
    cat +>:CategorizedAs:+> Product(id="p1", name="Kibble", price=29.99);
    cat +>:CategorizedAs:+> Product(id="p2", name="Treats", price=9.99);
    res = cat spawn ProductCounter();
    assert res.tally == 2, f"expected 2 products, got {res.tally}";
}

test "CategoryBrowser respects max_depth on nested ParentOf tree" {
    dogs = Category(id="d", name="Dogs", slug="dogs", display_order=1, product_count=5);
    food = Category(id="f", name="Food", slug="food", display_order=1, product_count=2);
    dry = Category(id="dr", name="Dry", slug="dry", display_order=1, product_count=1);
    root ++> dogs;
    dogs +>:ParentOf(order=1):+> food;
    food +>:ParentOf(order=1):+> dry;
    res = dogs spawn CategoryBrowser(max_depth=2, include_empty=True);
    assert len(res.snapshot) == 2, f"depth=2 should include Dogs and Food only, got {len(res.snapshot)}";
    names = [];
    for item in res.snapshot {
        names.append(item["name"]);
    }
    assert "Dogs" in names, f"missing Dogs in {names}";
    assert "Food" in names, f"missing Food in {names}";
    has_dry = False;
    for n in names {
        if n == "Dry" {
            has_dry = True;
        }
