    parent +>:ParentOf(order=1):+> empty_child;
    res = parent spawn CategoryBrowser(max_depth=3, include_empty=False);
    assert len(res.snapshot) == 1, f"only non-empty Parent should appear, got {len(res.snapshot)}";
