    root ++> empty;
    res = root spawn EmptyCategoryPruner();
    assert len(res.pruned_ids) == 1, f"expected exactly one pruned id, got {res.pruned_ids}";
    assert res.pruned_ids[0] == "b", f"expected empty category b to be pruned, got {res.pruned_ids}";
