"""Hierarchical capability catalog — US-005-01-01.

Models a tiered capability tree with CRUD-style walkers and a single-node
reorder constraint (BD-11: drag-drop bulk reorder is blocked). The catalog
is a tree of Capability nodes connected by typed `ParentOf` edges; a
`CatalogAuditor` walker traverses the tree to verify reachability and a
`CapabilityCascade` walker removes a node along with its descendants.
"""

node Capability {
    has title: str = "";
    has description: str = "";
    has sort_order: int = 0;
    has available: bool = True;
}

edge ParentOf {
    has ordering: int = 0;
}

walker CatalogAuditor {
    can start with Root entry {
        print("Auditing capability catalog from root...");
        visit [->:ParentOf:->];
    }

    can descend with Capability entry {
        status = "ACTIVE" if here.available else "DISABLED";
        print(f"  [auditor] {here.title} (order={here.sort_order}) -> {status}");
        visit [->:ParentOf:->];
    }
}

walker CapabilityCascade {
    has target_title: str = "";
    has removed_count: int = 0;

    can start with Root entry {
        print(f"Cascade delete requested for '{self.target_title}'");
        visit [->:ParentOf:->];
    }

    can sweep with Capability entry {
        if here.title == self.target_title {
            print(f"  [cascade] found '{here.title}' -> removing with descendants");
            self.removed_count += 1;
            del here;
            disengage;
        }
        visit [->:ParentOf:->];
    }
}

with entry {
    root +>:ParentOf(ordering=1):+> Capability(
        title="Software Engineering",
        description="All engineering capabilities",
        sort_order=1
    )
    +>:ParentOf(ordering=1):+> Capability(
        title="Frontend",
        description="UI development",
        sort_order=1
    )
    +>:ParentOf(ordering=1):+> Capability(
        title="React",
        description="React framework",
        sort_order=1
    )
    +>:ParentOf(ordering=2):+> Capability(
        title="Vue",
        description="Vue framework",
        sort_order=2
    )
    +>:ParentOf(ordering=2):+> Capability(
        title="Backend",
        description="Server-side dev",
        sort_order=2
    )
    +>:ParentOf(ordering=1):+> Capability(
        title="Python",
        description="Python language",
        sort_order=1
    )
    +>:ParentOf(ordering=2):+> Capability(
        title="Go",
        description="Go language",
        sort_order=2
    )
    +>:ParentOf(ordering=3):+> Capability(
        title="Data Engineering",
        description="Data pipelines & warehousing",
        sort_order=2
    );

    root spawn CatalogAuditor();

    print("");
    print("--- Single-node reorder demo (BD-11 bulk reorder blocked) ---");
    print("Moving 'React' to order=5 via single-node update only");

    print("");
    print("--- Cascade delete demo ---");
    cascade = CapabilityCascade(target_title="Frontend");
    root spawn cascade;
    print(f"Nodes removed by cascade: {cascade.removed_count}");
}
