"""Tests for the deployment pipeline trace demo.

Each test builds its own graph and spawns PipelineTrace, capturing stdout
so we can assert on the printed behavior:
  - a clean pipeline (no conflict) prints the 'clean' land message
  - a colliding versionCode sets `blocked_target` and prints the BLOCKED line
  - a CI failure disengages before the build/play steps print anything
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "no_conflict_pipeline_lands_cleanly" {
    fix_commit = Commit(
        sha="abcdef1",
        title="chore: bump versionCode"
    );
    ci_run = CI(name="lint+ty+tests", passed=True);
    apk_build = Build(artifact="app-release.aab", version_code=7);
    play = PlayRelease(track="production", known_version_codes=[5, 6]);

    root +>:Triggers:+> fix_commit;
    fix_commit +>:Produces:+> ci_run;
    ci_run +>:Produces:+> apk_build;
    apk_build +>:Targets:+> play;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tracer = PipelineTrace(conflict_version=999);
        root spawn tracer;
    }
    out = buf.getvalue();

    assert "commit abcdef1" in out, f"missing commit line: {out!r}";
    assert "CI [lint+ty+tests] OK" in out, f"missing CI OK line: {out!r}";
    assert "artifact=app-release.aab versionCode=7" in out, f"missing build line: {out!r}";
    assert "BLOCKED" not in out, f"unexpected BLOCKED on clean pipeline: {out!r}";
    assert "deploy to production clean" in out, f"missing clean land line: {out!r}";
    assert tracer.blocked_target == "", f"blocked_target should stay empty, got {tracer.blocked_target!r}";
}

# ---------------------------------------------------------------------------
test "version_code_collision_blocks_publish_and_marks_target" {
    fix_commit = Commit(
        sha="6a6244a",
        title="fix(ci): resolve ty panic and core type diagnostics"
    );
    ci_run = CI(name="lint+ty+tests", passed=True);
    apk_build = Build(artifact="app-release.aab", version_code=42);
    play = PlayRelease(track="internal", known_version_codes=[41, 42]);

    root +>:Triggers:+> fix_commit;
    fix_commit +>:Produces:+> ci_run;
    ci_run +>:Produces:+> apk_build;
    apk_build +>:Targets:+> play;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tracer = PipelineTrace(conflict_version=42);
        root spawn tracer;
    }
    out = buf.getvalue();

    assert "CI [lint+ty+tests] OK" in out, f"CI should pass: {out!r}";
    assert "versionCode=42" in out, f"build line missing: {out!r}";
    assert "BLOCKED: versionCode 42 already on Play Console" in out, f"missing BLOCKED line: {out!r}";
    assert "deploy to internal rejected for app-release.aab" in out, f"missing rejected land line: {out!r}";
    assert "[41, 42]" in out, f"known codes not surfaced: {out!r}";
    assert tracer.blocked_target == "app-release.aab", f"blocked_target should be 'app-release.aab', got {tracer.blocked_target!r}";
}

# ---------------------------------------------------------------------------
test "ci_failure_disengages_before_build_and_play" {
    fix_commit = Commit(
        sha="deadbee",
        title="wip: failing change"
    );
    ci_run = CI(name="lint+ty+tests", passed=False);
    apk_build = Build(artifact="app-release.aab", version_code=42);
    play = PlayRelease(track="internal", known_version_codes=[41, 42]);

    root +>:Triggers:+> fix_commit;
    fix_commit +>:Produces:+> ci_run;
    ci_run +>:Produces:+> apk_build;
    apk_build +>:Targets:+> play;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tracer = PipelineTrace(conflict_version=42);
        root spawn tracer;
