    assert "commit deadbee" in out, f"commit line should print before disengage: {out!r}";
    assert "CI [lint+ty+tests] FAIL" in out, f"CI FAIL line missing: {out!r}";
    assert "versionCode=" not in out, f"build line should NOT print after CI fail: {out!r}";
    assert "BLOCKED" not in out, f"BLOCKED should NOT print after CI fail: {out!r}";
    assert "deploy to" not in out, f"deploy line should NOT print after CI fail: {out!r}";
    assert tracer.blocked_target == "", f"blocked_target stays empty when CI fails, got {tracer.blocked_target!r}";
}

# ---------------------------------------------------------------------------
test "graph_shape_triggers_produces_targets_are_typed" {
    fix_commit = Commit(sha="s1", title="t1");
    ci_run = CI(name="ci", passed=True);
    apk_build = Build(artifact="a", version_code=1);
    play = PlayRelease(track="production", known_version_codes=[]);

    root +>:Triggers:+> fix_commit;
    fix_commit +>:Produces:+> ci_run;
    ci_run +>:Produces:+> apk_build;
    apk_build +>:Targets:+> play;

    # exactly one Triggers edge off root, leading to the commit
    triggers = [root ->:Triggers:->];
    assert len(triggers) == 1, f"expected 1 Triggers edge, got {len(triggers)}";
    assert fix_commit in triggers, f"commit should be the Triggers target: {triggers}";

    # commit has exactly one Produces edge to CI
    commit_produces = [fix_commit ->:Produces:->];
    assert len(commit_produces) == 1, f"expected 1 Produces edge from commit, got {len(commit_produces)}";
    assert ci_run in commit_produces, f"CI should be Produced by commit: {commit_produces}";

    # CI has exactly one Produces edge to Build
    ci_produces = [ci_run ->:Produces:->];
    assert len(ci_produces) == 1, f"expected 1 Produces edge from CI, got {len(ci_produces)}";
    assert apk_build in ci_produces, f"Build should be Produced by CI: {ci_produces}";

    # Build has exactly one Targets edge to PlayRelease
    targets = [apk_build ->:Targets:->];
    assert len(targets) == 1, f"expected 1 Targets edge from build, got {len(targets)}";
    assert play in targets, f"PlayRelease should be the Targets target: {targets}";

    # PlayRelease is a sink — no outgoing pipeline edges
    assert len([play ->:Triggers:->]) == 0, "PlayRelease should not have outgoing Triggers edges";
    assert len([play ->:Produces:->]) == 0, "PlayRelease should not have outgoing Produces edges";
    assert len([play ->:Targets:->]) == 0, "PlayRelease should not have outgoing Targets edges";
}

