import io;
import from contextlib { redirect_stdout }

test "lineage audit detects publication cycles" {
    p1 = Publication(version=1, label="pub-v1", accepted=True);
    p2 = Publication(version=2, label="pub-v2", accepted=False);

    root +>:Produces:+> p1;
    p1 +>:DependsOn:+> p2;
    p2 +>:DependsOn:+> p1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageAuditor();
    }
    out = buf.getvalue();

    assert res.cycles == 1, f"expected one cycle, got {res.cycles}";
    assert len(res.visited) == 2, f"expected two visited publications, got {res.visited}";
    assert "[lineage] pub-v1 accepted=True" in out, f"missing pub-v1 audit: {out}";
    assert "[lineage] pub-v2 accepted=False" in out, f"missing pub-v2 audit: {out}";
}

test "rollback restores accepted checkpoint and records corruption" {
    lkg = Checkpoint(label="lkg-v2", state="good", accepted=True);
    bad = Artifact(
        name="model.gguf",
        label="gguf-v3",
        format="GGUF",
        state="corrupt",
        bytes=900,
        accepted=True
    );

    root +>:CheckedBy:+> lkg;
    lkg +>:CheckedBy:+> bad;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Rollback(target_label="lkg-v2");
    }
    out = buf.getvalue();

    assert len(res.restored) == 1, f"expected one restored checkpoint, got {res.restored}";
    assert res.restored[0] == "lkg-v2", f"wrong restored label: {res.restored}";
    assert len(res.failed) == 1, f"expected one corrupt artifact, got {res.failed}";
    assert res.failed[0] == "gguf-v3", f"wrong failed label: {res.failed}";
    assert "[rollback] restored last-known-good lkg-v2" in out, f"missing restore output: {out}";
    assert "[rollback] gguf-v3 marked corrupt, cannot restore" in out, f"missing corruption output: {out}";
}

test "rollback skips interrupted unaccepted target" {
    interrupted = Artifact(
        name="partial.gguf",
        label="gguf-v4",
        format="GGUF",
        state="interrupted",
        bytes=128,
        accepted=False
    );

    root +>:CheckedBy:+> interrupted;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Rollback(target_label="gguf-v4");
    }
    out = buf.getvalue();

    assert len(res.restored) == 0, f"interrupted artifact was restored: {res.restored}";
    assert len(res.failed) == 0, f"interrupted artifact was marked corrupt: {res.failed}";
    assert "[rollback] skip gguf-v4 (not the target)" in out, f"missing fail-closed skip: {out}";
}

