"""Semantic relationship model: typed edges with source-anchored identity.

Models a small slice of the issue's complaint — relationships used to be
plain strings (`source: str`, `target: str`) that flattened all kinds of
edges (inherits, uses, tests) into one lossy projection. Here each kind is
a typed edge archetype carrying source/target identity, a generation stamp,
confidence, and a phase tag, and a walker projects them into immutable
per-kind indexes the way #8106 / #4799 expect.
"""

node Module {
    has module_name: str = "";
    has generation: int = 0;
}

node Symbol {
    has symbol_name: str = "";
    has kind: str = "sub";
    has generation: int = 0;
}

node Group {
    has group_name: str = "";
    has generation: int = 0;
}

edge Inherits {
    has source_path: str = "";
    has source_gen: int = 0;
    has confidence: float = 1.0;
    has phase: str = "compile";
}

edge Uses {
    has source_path: str = "";
    has source_gen: int = 0;
    has confidence: float = 1.0;
    has phase: str = "compile";
}

edge Tests {
    has source_path: str = "";
    has source_gen: int = 0;
    has confidence: float = 1.0;
    has phase: str = "runtime";
}

edge ReExports {
    has source_path: str = "";
    has source_gen: int = 0;
    has confidence: float = 1.0;
    has phase: str = "compile";
}

walker RelationshipAuditor {
    has target_name: str = "Animal";
    has inherits_index: list[str] = [];
    has uses_index: list[str] = [];
    has tests_index: list[str] = [];
    has reexports_index: list[str] = [];

    can start with Root entry {
        print(f"--- Relationship projection for '{self.target_name}' ---");
        visit [-->];
    }

    can collect_inherits with Symbol entry {
        if here.symbol_name == self.target_name {
            label = f"{here.symbol_name}#{here.generation}";
            self.inherits_index.append(label);
        }
        visit [->:Inherits:->];
    }

    can collect_uses with Symbol entry {
        if here.symbol_name == self.target_name {
            label = f"{here.symbol_name}#{here.generation}";
            self.uses_index.append(label);
        }
        visit [->:Uses:->];
    }

    can collect_tests with Symbol entry {
        if here.symbol_name == self.target_name {
            label = f"{here.symbol_name}#{here.generation}";
            self.tests_index.append(label);
        }
        visit [->:Tests:->];
    }

    can collect_reexports with Symbol entry {
        if here.symbol_name == self.target_name {
            label = f"{here.symbol_name}#{here.generation}";
            self.reexports_index.append(label);
        }
        visit [->:ReExports:->];
    }

    can finish with Root entry {
        print(f"inherits  -> {self.inherits_index}");
        print(f"uses      -> {self.uses_index}");
        print(f"tests     -> {self.tests_index}");
        print(f"reexports -> {self.reexports_index}");
    }
}

walker CascadeInvalidator {
    has visited: set[str] = set();
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Module entry {
        key = f"{here.module_name}#{here.generation}";
        if key in self.visited {
            disengage;
        }
        self.visited.add(key);
        self.invalidated.append(key);
        print(f"invalidating {here.module_name} (gen {here.generation})");
        visit [->:Uses:->];
        visit [->:Inherits:->];
        visit [->:Tests:->];
    }
}

with entry {
    animal_mod = Module(module_name="lib/Animal.pm", generation=3);
    dog_mod = Module(module_name="lib/Dog.pm", generation=7);
    cat_mod = Module(module_name="lib/Cat.pm", generation=5);
    animal_sym = Symbol(symbol_name="Animal", kind="class", generation=3);
    dog_sym = Symbol(symbol_name="Dog", kind="class", generation=7);
    cat_sym = Symbol(symbol_name="Cat", kind="class", generation=5);
    greet_sym = Symbol(symbol_name="greet", kind="sub", generation=7);
    tests_mod = Module(module_name="t/animal.t", generation=12);
    group = Group(group_name="Mammal", generation=2);

    root ++> animal_mod
        ++> animal_sym
        ++> dog_mod
        ++> dog_sym
        ++> cat_mod
        ++> cat_sym
        ++> greet_sym
        ++> tests_mod
        ++> group;

    dog_mod +>:Inherits(source_path="lib/Dog.pm", source_gen=7, confidence=0.95, phase="compile"):+> animal_sym;
    cat_mod +>:Inherits(source_path="lib/Cat.pm", source_gen=5, confidence=0.95, phase="compile"):+> animal_sym;
    dog_mod +>:Uses(source_path="lib/Dog.pm", source_gen=7, confidence=1.0, phase="compile"):+> greet_sym;
    cat_mod +>:Uses(source_path="lib/Cat.pm", source_gen=5, confidence=1.0, phase="compile"):+> greet_sym;
    dog_sym +>:ReExports(source_path="lib/Dog.pm", source_gen=7, confidence=0.9, phase="compile"):+> animal_sym;
    tests_mod +>:Tests(source_path="t/animal.t", source_gen=12, confidence=1.0, phase="runtime"):+> animal_sym;

    root spawn RelationshipAuditor(target_name="Animal");
    print("--- cascade invalidation from Animal.pm ---");
    root spawn CascadeInvalidator();
}
