import io;
import from contextlib { redirect_stdout }

test "recursively audits resolved dependencies" {
    app_shell = Package(title="app-shell", age_days=10);
    ui_kit = Package(title="ui-kit", age_days=20);
    state_mgr = Package(title="state-mgr", age_days=45);

    root ++> app_shell;
    app_shell +>:DependsOn:+> ui_kit;
    ui_kit +>:DependsOn:+> state_mgr;

    buf = io.StringIO();
