test "undeclared mapping differs by mark shape" {
    layer = SegmentedLayer(name="stackedBar", dom_order="");
    root +>:LayerOf:+> layer;

    layer +>:LayerOf:+> RectMark(series=0, index=0);
    layer +>:LayerOf:+> RectMark(series=0, index=1);
    layer +>:LayerOf:+> RectMark(series=1, index=0);

    layer +>:LayerOf:+> PathMark(series=0, index=0);
    layer +>:LayerOf:+> PathMark(series=0, index=1);
    layer +>:LayerOf:+> PathMark(series=1, index=0);

    path_res = root spawn PathPairer();
    rect_res = root spawn RectPairer();

    assert path_res.pairs == ["r0.0", "r0.1", "r1.0"], f"got {path_res.pairs}";
    assert rect_res.pairs == ["c0.0", "c1.0", "c0.1"], f"got {rect_res.pairs}";
}

