import from contextlib { redirect_stdout }

test "recursive union sums the seeded rows" {
    cte = CTE(name="t", max_depth=100);
    root ++> cte;

    iter_res = root spawn Iter();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        sum_res = root spawn SumResult();
    }
    out = buf.getvalue();

    assert len(iter_res.seen) == 99, f"got {iter_res.seen}";
    assert sum_res.total == 5050, f"got {sum_res.total}";
