    assert "walked 4 ancestors across clusters [7, 7, 12, 12]" in out, f"missing lineage output: {out}";
    assert "synthesis_depth=2, priority_boost=20" in out, f"missing metadata output: {out}";

    found = 0;
    for child in [root-->] {
        if isinstance(child, Synthesis) and child.title == "S2 (cross-cluster meta-synthesis)" {
            found = found + 1;
            assert child.cluster_id == 99, f"got {child.cluster_id}";
            assert child.synthesis_depth == 2, f"got {child.synthesis_depth}";
        }
    }
    assert found == 1, f"expected one S2, got {found}";
