Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive macro expansion model: tracked enum chain with depth-limited traversal.

Models the gccrs issue where deeply recursive macro expansion degrades compiler
performance. Each FooN enum depends on the previous one (FooN depends on FooN-1)
through a typed DependsOn edge. An Expander walker walks the dependency chain
forward (deepest first) and enforces a depth limit to mimic the compiler's
recursive bound, reporting the deepest reachable depth and any chain that
exceeds the limit.
"""

node MacroDef {
    has name: str = "";
    has depth: int = 0;
    has payload: str = "";
}

edge DependsOn {
    has weight: int = 1;
}

walker Expander {
    has max_depth: int = 10;
    has visited: list[str] = [];
    has deepest: int = 0;
    has over_limit: bool = False;
    has over_limit_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can expand with MacroDef entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        if here.depth > self.deepest {
            self.deepest = here.depth;
        }
        if here.depth > self.max_depth {
            self.over_limit = True;
            self.over_limit_name = here.name;
            print(f"DEPTH EXCEEDED at {here.name} (depth={here.depth}, limit={self.max_depth})");
            disengage;
        }
        print(f"expanding {here.name} at depth {here.depth}");
        visit [->:DependsOn:->];
    }

    def report() -> dict {
        return {
            "max_depth_seen": self.deepest,
            "over_limit": self.over_limit,
            "offender": self.over_limit_name,
            "expanded_count": len(self.visited),
        };
    }
}

with entry {
    a = root ++> MacroDef(name="Foo0", depth=0, payload="enum Foo0 { Empty, First(()), Second(()), Third(()), Fourth(()) }");
    b = a +>:DependsOn:+> MacroDef(name="Foo1", depth=1, payload="enum Foo1 { Empty, First(Foo0), Second(Foo0), Third(Foo0), Fourth(Foo0) }");
    c = b +>:DependsOn:+> MacroDef(name="Foo2", depth=2, payload="enum Foo2 { Empty, First(Foo1), Second(Foo1), Third(Foo1), Fourth(Foo1) }");
    d = c +>:DependsOn:+> MacroDef(name="Foo3", depth=3, payload="enum Foo3 { Empty, First(Foo2), Second(Foo2), Third(Foo2), Fourth(Foo2) }");
    e = d +>:DependsOn:+> MacroDef(name="Foo4", depth=4, payload="enum Foo4 { Empty, First(Foo3), Second(Foo3), Third(Foo3), Fourth(Foo3) }");
    f = e +>:DependsOn:+> MacroDef(name="Foo5", depth=5, payload="enum Foo5 { Empty, First(Foo4), Second(Foo4), Third(Foo4), Fourth(Foo4) }");
    g = f +>:DependsOn:+> MacroDef(name="Foo6", depth=6, payload="enum Foo6 { Empty, First(Foo5), Second(Foo5), Third(Foo5), Fourth(Foo5) }");
    h = g +>:DependsOn:+> MacroDef(name="Foo7", depth=7, payload="enum Foo7 { Empty, First(Foo6), Second(Foo6), Third(Foo6), Fourth(Foo6) }");
    i = h +>:DependsOn:+> MacroDef(name="Foo8", depth=8, payload="enum Foo8 { Empty, First(Foo7), Second(Foo7), Third(Foo7), Fourth(Foo7) }");
    j = i +>:DependsOn:+> MacroDef(name="Foo9", depth=9, payload="enum Foo9 { Empty, First(Foo8), Second(Foo8), Third(Foo8), Fourth(Foo8) }");
    k = j +>:DependsOn:+> MacroDef(name="Foo10", depth=10, payload="enum Foo10 { Empty, First(Foo9), Second(Foo9), Third(Foo9), Fourth(Foo9) }");
    l = k +>:DependsOn:+> MacroDef(name="Foo11", depth=11, payload="enum Foo11 { Empty, First(Foo10), Second(Foo10), Third(Foo10), Fourth(Foo10) }");
    m = l +>:DependsOn:+> MacroDef(name="Foo12", depth=12, payload="enum Foo12 { Empty, First(Foo11), Second(Foo11), Third(Foo11), Fourth(Foo11) }");

    expander = Expander(max_depth=10);
    root spawn expander;
    summary = expander.report();
    print(f"summary: {summary}");

    safe = Expander(max_depth=20);
    root spawn safe;
    safe_summary = safe.report();
    print(f"safe_summary: {safe_summary}");
}
