"""Governance DAG: model leave_namespace cascade and cross-peer consistency window.

This demo captures the essence of issue #2283: a cascade that walks the
namespace tree, gathers direct-membership rows, validates owner/last-admin
invariants upfront, then mutates each scope. We expose the walker that
performs the traversal and a second walker that demonstrates the
logically invalid state (subgroup membership without namespace membership)
that can arise during the cross-peer inconsistency window.
"""

node Namespace {
    has name: str = "";
    has owner: str = "";
}

node Group {
    has name: str = "";
    has parent_name: str = "";
}

node Member {
    has name: str = "";
    has role: str = "member";
}

edge Contains {
    has depth: int = 0;
}

edge DirectMember {
    has added_at: str = "";
}

walker CascadeLeave {
    has leaver: str = "";
    has scopes: list = [];
    has report: dict = {};

    can start with Root entry {
        self.scopes = [];
        visit [-->];
    }

    can gather with Namespace entry {
        visit [->:Contains:->];
    }

    can gather_groups with Group entry {
        self.scopes = self.scopes + [here];
        visit [->:Contains:->];
    }

    can gather_memberships with Member entry {
        self.scopes = self.scopes + [here];
    }
}

walker ValidateBeforeMutation {
    has leaver: str = "";
    has violations: list = [];

    can start with Root entry {
        self.violations = [];
        visit [-->];
    }

    can check_namespace with Namespace entry {
        if here.owner == self.leaver {
            self.violations = self.violations + [f"owner check failed at {here.name}"];
        }
        visit [-->];
    }

    can check_group with Group entry {
        visit [-->];
    }
}

walker ApplyCascade {
    has leaver: str = "";
    has mutated: list = [];

    can start with Root entry {
        self.mutated = [];
        visit [-->];
    }

    can mutate_namespace with Namespace entry {
        visit [-->];
    }

    can mutate_group with Group entry {
        self.mutated = self.mutated + [here.name];
        visit [-->];
    }

    can mutate_member with Member entry {
        if here.name == self.leaver {
            self.mutated = self.mutated + [f"removed member {here.name} from {here.role}"];
        }
    }
}

walker DetectOrphanMembership {
    has leaver: str = "";
    has leaver_in_namespace: bool = False;
    has orphan_groups: list = [];

    can start with Root entry {
        self.orphan_groups = [];
        visit [-->];
    }

    can scan_namespace with Namespace entry {
        found = False;
        for (i, m) in enumerate([->:DirectMember:->]) {
            if m.name == self.leaver {
                found = True;
            }
        }
        self.leaver_in_namespace = found;
        visit [-->];
    }

    can scan_group with Group entry {
        for (i, m) in enumerate([->:DirectMember:->]) {
            if m.name == self.leaver and not self.leaver_in_namespace {
                self.orphan_groups = self.orphan_groups + [here.name];
            }
        }
        visit [-->];
    }
}

with entry {
    root_ns = Namespace(name="root", owner="Alice");
    eng = Namespace(name="engineering", owner="Alice");
    frontend = Group(name="frontend", parent_name="engineering");
    backend = Group(name="backend", parent_name="engineering");

    alice = Member(name="Alice", role="owner");
    bob = Member(name="Bob", role="admin");
    carol = Member(name="Carol", role="member");

    root +>:Contains(depth=0):+> root_ns;
    root_ns +>:Contains(depth=1):+> eng;
    eng +>:Contains(depth=2):+> frontend;
    eng +>:Contains(depth=2):+> backend;

    root_ns +>:DirectMember(added_at="2024-01-01"):+> alice;
    root_ns +>:DirectMember(added_at="2024-01-01"):+> bob;
    eng +>:DirectMember(added_at="2024-02-01"):+> alice;
    eng +>:DirectMember(added_at="2024-02-01"):+> bob;
    eng +>:DirectMember(added_at="2024-02-01"):+> carol;
    frontend +>:DirectMember(added_at="2024-03-01"):+> alice;
    frontend +>:DirectMember(added_at="2024-03-01"):+> carol;
    backend +>:DirectMember(added_at="2024-03-01"):+> bob;

    print("=== CascadeLeave: gather all scopes where Alice has direct rows ===");
    gatherer = CascadeLeave(leaver="Alice");
    root spawn gatherer;
    print(f"scopes gathered: {len(gatherer.scopes)}");

    print("\n=== ValidateBeforeMutation: owner + last-admin checks upfront ===");
    validator = ValidateBeforeMutation(leaver="Alice");
    root spawn validator;
    print(f"violations: {validator.violations}");

    print("\n=== ApplyCascade: mutate each scope sequentially ===");
    applier = ApplyCascade(leaver="Alice");
    root spawn applier;
    print(f"mutations applied: {applier.mutated}");

    print("\n=== DetectOrphanMembership: cross-peer inconsistency window ===");
    print("Simulating: namespace leave applied, but subgroup rows not yet propagated");
    orphan_scanner = DetectOrphanMembership(leaver="Alice");
    root spawn orphan_scanner;
    print(f"leaver_in_namespace: {orphan_scanner.leaver_in_namespace}");
    print(f"orphan_groups (logically invalid until reconcile): {orphan_scanner.orphan_groups}");
}
