    root ++> env;
    root +>:Contains:+> deep;
    root +>:Contains:+> wide;

    res = root spawn Validator(max_depth=8, max_children=64);

    assert res.depth_capped == 1, f"got {res.depth_capped}";
    assert res.error_kind == "limit_error", f"got {res.error_kind}";
    assert res.error_action == "reduce_depth", f"got {res.error_action}";
}

