    expected = {"tracked-changes", "fields", "hyperlinks"};
    got = set(r.omissions);
    assert expected.issubset(got), f"omissions missing: expected superset of {expected}, got {got}";

    # Document part itself contributes no omissions.
    doc_omits_in_walk = [o for o in r.omissions if o == "word/document.xml"];
    assert doc_omits_in_walk == [], f"document part should not emit omissions: {r.omissions}";
