# --- DiagnosticsAuditor ---------------------------------------------------

test "auditor flags only parts that carry omissions" {
    doc = Part(part_name="word/document.xml", content_kind="document", raw_text="x", omissions=[]);
    fn = Part(part_name="word/footnotes.xml", content_kind="footnote",
