    en = Part(part_name="word/endnotes.xml", content_kind="endnote",
              raw_text="en", omissions=["hyperlinks"]);
    cm = Part(part_name="word/comments.xml", content_kind="comment",
              raw_text="cm", omissions=[]);

    root ++> doc;
    doc +>:Relationship(rel_type="footnotes"):+> fn;
    doc +>:Relationship(rel_type="endnotes"):+> en;
    doc +>:Relationship(rel_type="comments"):+> cm;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        a = root spawn DiagnosticsAuditor();
    }

    # fn and en each carry omissions → two flags. cm and doc carry none.
    assert len(a.flagged) == 2, f"expected 2 flags, got {len(a.flagged)}: {a.flagged}";
    assert all(l == "docx.story_parts_omitted" for l in a.flagged), f"wrong label: {a.flagged}";

    out = buf.getvalue();
    assert "docx.story_parts_omitted" in out, f"missing diagnostic label: {out}";
    assert "word/footnotes.xml" in out, f"footnotes part not warned: {out}";
    assert "word/endnotes.xml" in out, f"endnotes part not warned: {out}";
