test "ancestors stay in the seed schema and honor depth" {
    p_leaf = Struct(name="public_leaf", prefix="public", primary_key=3, depth_from_root=0);
    p_mid = Struct(name="public_mid", prefix="public", primary_key=2, depth_from_root=1);
    p_root = Struct(name="public_root", prefix="public", primary_key=1, depth_from_root=2);
    a_root = Struct(name="audit_root", prefix="audit", primary_key=10, depth_from_root=1);

    root ++> p_leaf;
    p_leaf +>:ParentLink:+> p_mid;
    p_mid +>:ParentLink:+> p_root;
