    assert (3, "public_leaf") in af.ancestors, f"got {af.ancestors}";
    assert (2, "public_mid") in af.ancestors, f"got {af.ancestors}";
    assert (1, "public_root") not in af.ancestors, f"got {af.ancestors}";
    assert (10, "audit_root") not in af.ancestors, f"got {af.ancestors}";
