test "descendants remain schema-bound across cycles" {
    p_root = Struct(name="public_root", prefix="public", primary_key=1, depth_from_root=0);
    p_mid = Struct(name="public_mid", prefix="public", primary_key=2, depth_from_root=1);
    p_leaf = Struct(name="public_leaf", prefix="public", primary_key=3, depth_from_root=2);
    a_root = Struct(name="audit_root", prefix="audit", primary_key=10, depth_from_root=0);

    root ++> p_root;
    p_root +>:ChildLink:+> p_mid;
    p_mid +>:ChildLink:+> p_leaf;
    p_leaf +>:ChildLink:+> p_root;
    p_leaf +>:ChildLink:+> a_root;

    df = DescendantFinder(seed_id=1, schema_name="public", max_depth=8);
    root spawn df;

    assert len(df.descendants) == 3, f"got {df.descendants}";
    assert (1, "public_root") in df.descendants, f"got {df.descendants}";
    assert (2, "public_mid") in df.descendants, f"got {df.descendants}";
    assert (3, "public_leaf") in df.descendants, f"got {df.descendants}";
    assert (10, "audit_root") not in df.descendants, f"got {df.descendants}";
}

test "cascade invalidation skips other schemas and dead nodes" {
    p_root = Struct(name="public_root", prefix="public", primary_key=1, alive=True);
    p_leaf = Struct(name="public_leaf", prefix="public", primary_key=2, alive=True);
    p_dead = Struct(name="public_dead", prefix="public", primary_key=3, alive=False);
    a_root = Struct(name="audit_root", prefix="audit", primary_key=10, alive=True);

    root ++> p_root;
    root ++> p_dead;
    root ++> a_root;
    p_root +>:ChildLink:+> p_leaf;
    p_root +>:ChildLink:+> a_root;

    inv = CascadeInvalidator(schema_name="public");
    root spawn inv;

    assert len(inv.invalidated) == 2, f"got {inv.invalidated}";
    assert "public_root" in inv.invalidated, f"got {inv.invalidated}";
    assert "public_leaf" in inv.invalidated, f"got {inv.invalidated}";
    assert "public_dead" not in inv.invalidated, f"got {inv.invalidated}";
    assert "audit_root" not in inv.invalidated, f"got {inv.invalidated}";
    assert p_root.alive == False, f"got {p_root.alive}";
    assert p_leaf.alive == False, f"got {p_leaf.alive}";
    assert p_dead.alive == False, f"got {p_dead.alive}";
    assert a_root.alive == True, f"got {a_root.alive}";
}

