"""Grover impact analysis: model cryptographic primitives and walk the
threat graph to flag vulnerable components under Grover's quadratic
speedup, then emit an upgrade-recommendation report."""

# ---- Base entity: all crypto components share these fields -------------

node CryptoComponent {
    has name: str = "";
    has kind: str = "";
    has bit_strength: int = 0;
    has grover_effective: int = 0;
    has vulnerable: bool = False;
    has recommendation: str = "";
}

# ---- Concrete component archetypes ------------------------------------

node SymmetricCipher(CryptoComponent) {
    has key_size: int = 0;
}

node HashFunction(CryptoComponent) {
    has digest_size: int = 0;
}

node HmacVariant(CryptoComponent) {
    has key_length: int = 0;
    has underlying_hash: str = "";
}

# A plain visitor — never matched by the union trigger.
node RelatedArtifact {
    has note: str = "";
}

# ---- Typed edges ------------------------------------------------------

edge DependsOn { }
edge MitigatedBy { }

# ---- Walker: a single auditor that traverses the threat graph ---------

walker GroverAuditor {
    has report_lines: list = [];
    has visited: list = [];

    can start with Root entry {
        print("=== Grover Quadratic Speedup Impact Audit ===");
        visit [-->] else { disengage; }
    }

    can audit_component with SymmetricCipher | HashFunction | HmacVariant entry {
        if self.visited.count(here) > 0 {
            visit [->:DependsOn:->] else { disengage; }
        }
        self.visited = self.visited + [here];

        status = "VULNERABLE" if here.vulnerable else "SAFE";
        line = f"[{status}] {here.kind} '{here.name}' "
            f"(classical={here.bit_strength}, "
            f"grover={here.grover_effective}) -> {here.recommendation}";
        self.report_lines = self.report_lines + [line];

        visit [->:DependsOn:->] else { disengage; }
    }

    can note_artifact with RelatedArtifact entry {
        visit [-->] else { disengage; }
    }

    can summarize with Root entry {
        print(f"Audited {len(self.report_lines)} components under Grover:");
        for entry in self.report_lines {
            print(f"  - {entry}");
        }
        vulnerable_count = 0;
        for entry in self.report_lines {
            if entry.startswith("[VULNERABLE]") {
                vulnerable_count = vulnerable_count + 1;
            }
        }
        print(f"Vulnerable components: {vulnerable_count}");
        print("Minimum quantum-safe baseline: AES-256 / SHA-384 / HMAC-256");
    }
}

# ---- Graph construction & demo ---------------------------------------

with entry {
    aes128 = SymmetricCipher(
        name="AES-128", kind="symmetric", key_size=128,
        bit_strength=128, grover_effective=64,
        vulnerable=True,
        recommendation="upgrade to AES-256"
    );
    aes192 = SymmetricCipher(
        name="AES-192", kind="symmetric", key_size=192,
        bit_strength=192, grover_effective=96,
        vulnerable=True,
        recommendation="upgrade to AES-256 (marginal at 96-bit)"
    );
    aes256 = SymmetricCipher(
        name="AES-256", kind="symmetric", key_size=256,
        bit_strength=256, grover_effective=128,
        vulnerable=False,
        recommendation="quantum-safe baseline"
    );

    sha256 = HashFunction(
        name="SHA-256", kind="hash",
        digest_size=256, bit_strength=256, grover_effective=128,
        vulnerable=False,
        recommendation="acceptable; plan SHA-384 upgrade for long-term"
    );
    sha384 = HashFunction(
        name="SHA-384", kind="hash",
        digest_size=384, bit_strength=384, grover_effective=192,
        vulnerable=False,
        recommendation="quantum-safe"
    );
    sha512 = HashFunction(
        name="SHA-512", kind="hash",
        digest_size=512, bit_strength=512, grover_effective=256,
        vulnerable=False,
        recommendation="quantum-safe"
    );

    hmac_sha256 = HmacVariant(
        name="HMAC-SHA256", kind="hmac",
        key_length=256, underlying_hash="SHA-256",
        bit_strength=256, grover_effective=128,
        vulnerable=False,
        recommendation="use >=256-bit keys"
    );
    hmac_sha512 = HmacVariant(
        name="HMAC-SHA512", kind="hmac",
        key_length=512, underlying_hash="SHA-512",
        bit_strength=512, grover_effective=256,
        vulnerable=False,
        recommendation="quantum-safe"
    );

    artifact = RelatedArtifact(note="Grover 1996 paper citation");

    root ++> aes128 ++> aes192 ++> aes256
        ++> sha256 ++> sha384 ++> sha512
        ++> hmac_sha256 ++> hmac_sha512
        ++> artifact;

    aes128 +>:DependsOn:+> aes256;
    aes192 +>:DependsOn:+> aes256;
    sha256 +>:DependsOn:+> sha384;
    hmac_sha256 +>:DependsOn:+> hmac_sha512;

    root spawn GroverAuditor();
}
