    assert dependent.published == False, f"dependent published state was {dependent.published}";
    assert "B-S" in res.purged, f"source was not purged: {res.purged}";
    assert "B-D" in res.purged, f"dependent was not purged: {res.purged}";
    assert len(res.purged) == 2, f"purged bundles were {res.purged}";
    assert "invalidated bundle B-S" in out, f"missing source invalidation: {out}";
    assert "invalidated bundle B-D" in out, f"missing dependent invalidation: {out}";
