```jac
"""License audit walker: traverse the transitive dependency graph and
flag any package whose declared license is not on the project allowlist.

Models issue #86: a project ships under MIT, but a transitive dependency
could silently pull in GPL/AGPL/OSL/BSL. A walker performs the recursive
enumeration that the issue describes and reports every package whose
license falls outside the documented allowlist."""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has approved: bool = False;
}

node License {
    has spdx_id: str = "";
    has compatible: bool = False;
}

edge DependsOn { has scope: str = "transitive"; }
edge Allows { }

walker LicenseAuditor {
    has project_license: str = "MIT";
    has audited: list[str] = [];
    has flagged: list[str] = [];

    can start with Root entry {
        print(f"Auditing transitive deps for project under {self.project_license}");
        visit [-->];
    }

    can walk_deps with Package entry {
        if here.name in self.audited {
            visit [-->];
        }
        self.audited.append(here.name);
        label = "OK" if here.approved else "FLAG";
        line = f"[{label}] {here.name}@{here.version} -> {here.license}";
        print(line);
        if not here.approved {
            self.flagged.append(line);
        }
        visit [-->];
    }

    can visit_licenses with License entry {
        status = "ALLOWED" if here.compatible else "BLOCKED";
        print(f"  license {here.spdx_id}: {status}");
    }

    can summarize with Root entry {
        print("--- AUDIT SUMMARY ---");
        print(f"project license: {self.project_license}");
        print(f"packages audited: {len(self.audited)}");
        print(f"flagged packages: {len(self.flagged)}");
        for entry in self.flagged {
            print(f"  * {entry}");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    newtonsoft = Package(name="Newtonsoft.Json", version="13.0.3", license="MIT", approved=True);
    json_sublib = Package(name="Json.Net.SubLib", version="1.2.0", license="MIT", approved=True);
    gpl_toolkit = Package(name="GPL.Toolkit", version="0.9.1", license="GPL-3.0-only", approved=False);
    copyleft = Package(name="Copyleft.Lib", version="2.0.0", license="AGPL-3.0-or-later", approved=False);
    apache_helper = Package(name="Apache.Helper", version="0.1.0", license="Apache-2.0", approved=True);

    root ++> newtonsoft
        ++> json_sublib
        ++> gpl_toolkit
        ++> apache_helper
        ++> copyleft;

    mit = License(spdx_id="MIT", compatible=True);
    apache = License(spdx_id="Apache-2.0", compatible=True);
    bsd2 = License(spdx_id="BSD-2-Clause", compatible=True);
    bsd3 = License(spdx_id="BSD-3-Clause", compatible=True);
    gpl = License(spdx_id="GPL-3.0-only", compatible=False);
    agpl = License(spdx_id="AGPL-3.0-or-later", compatible=False);
    osl = License(spdx_id="OSL-3.0", compatible=False);

    root ++> mit
        ++> apache
        ++> bsd2
        ++> bsd3
        ++> gpl
        ++> agpl
        ++> osl;

    newtonsoft +>:DependsOn:+> json_sublib;
    json_sublib +>:DependsOn:+> gpl_toolkit;
    gpl_toolkit +>:DependsOn:+> apache_helper;
    newtonsoft +>:DependsOn:+> copyleft;

    mit +>:Allows:+> apache;
    mit +>:Allows:+> bsd2;
    mit +>:Allows:+> bsd3;
    mit +>:Allows:+> mit;

    auditor = LicenseAuditor(project_license="MIT");
    root spawn auditor;
}
