test "crawler caps nested replies at the configured depth" {
    post = Article(title="Depth policy");
    top = Comment(author="alice", body="Top", depth=0);
    first = Comment(author="bob", body="First reply", depth=1);
    capped = Comment(author="carol", body="At cap", depth=2);
    hidden = Comment(author="dave", body="Beyond cap", depth=3);

    post +>:ReplyTo(order=1):+> top;
    top +>:ReplyTo(order=1):+> first;
    first +>:ReplyTo(order=1):+> capped;
    capped +>:ReplyTo(order=1):+> hidden;

    res = post spawn ReplyCrawler(max_depth=2);
    assert len(res.report) == 3, f"got {len(res.report)} reports";
    assert res.report[0]["author"] == "alice", f"got {res.report}";
    assert res.report[1]["author"] == "bob", f"got {res.report}";
    assert res.report[2]["author"] == "carol", f"got {res.report}";
    assert res.report[2]["marker"] == "+", f"got {res.report[2]}";
}

test "crawler honors a zero reply depth cap" {
    post = Article(title="Top-level only");
    top = Comment(author="erin", body="Top", depth=0);
    reply = Comment(author="frank", body="Reply", depth=1);

    post +>:ReplyTo(order=1):+> top;
    top +>:ReplyTo(order=1):+> reply;

    res = post spawn ReplyCrawler(max_depth=0);
    assert len(res.report) == 1, f"got {len(res.report)} reports";
    assert res.report[0]["author"] == "erin", f"got {res.report}";
    assert res.report[0]["depth"] == 0, f"got {res.report[0]}";
}

test "invalidator closes every reachable open comment once" {
    post = Article(title="Cascade policy");
    top = Comment(author="alice", body="Top", depth=0, open=True);
    reply = Comment(author="bob", body="Reply", depth=1, open=True);
    already_closed = Comment(author="carol", body="Closed", depth=0, open=False);
    nested = Comment(author="dave", body="Nested", depth=2, open=True);

    post +>:ReplyTo(order=1):+> top;
    post +>:ReplyTo(order=2):+> already_closed;
    top +>:ReplyTo(order=1):+> reply;
    reply +>:ReplyTo(order=1):+> nested;

    res = post spawn CascadeInvalidator(reason="article deleted");
    assert res.touched == 3, f"got {res.touched}";
    assert top.open == False, f"top is {top.open}";
    assert reply.open == False, f"reply is {reply.open}";
    assert nested.open == False, f"nested is {nested.open}";
    assert already_closed.open == False, f"closed is {already_closed.open}";
}

