"""bioc-registry gap: propagated packages that lost upstream DESCRIPTION.

Models the four "described-but-invisible" devel packages (easier, NanoStringNCTools,
OmicsMLRepoR, TPP) that propagated with bytes in the CAS but no desc/meta recorded,
so install.packages() cannot see them by name. A walker audits the registry
following typed edges and reports which packages are propagated yet invisible.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has desc_present: bool = False;
    has in_packages_index: bool = False;
    has in_views_index: bool = False;
    has has_bytes: bool = False;
}

edge Propagated {
    has propagated_on: str = "";
    has from_universe: str = "";
}

edge Upstream {
    has last_seen: str = "";
    has desc_present: bool = False;
}

walker GapAuditor {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        # A package is "described-but-invisible" when we propagated it with
        # real bytes (CAS artifact exists) but the registry lacks both a
        # DESCRIPTION and presence in the PACKAGES / VIEWS indices.
        if here.has_bytes and not here.desc_present
            and not here.in_packages_index and not here.in_views_index {
            entry = {
                "name": here.name,
                "version": here.version,
                "note": "propagated but invisible to R"
            };
            self.report.append(entry);
            print(f"[GAP] {here.name} {here.version} "
                  f"-> propagated but invisible to install.packages()");
        } else {
            print(f"[OK ] {here.name} {here.version}");
        }
        visit [-->];
    }
}

walker Propagator {
    has upstream_name: str = "";
    has upstream_version: str = "";
    has propagation_day: str = "";

    can start with Root entry {
        visit [->:Upstream:->];
    }

    can fetch_upstream with Package entry {
        # Simulate the upstream losing its DESCRIPTION after we propagated.
        # In real bioc-registry this is the null-upstream stub described in
        # the issue; here we record what the upstream currently reports.
        here +>:Upstream(last_seen=self.propagation_day,
                          desc_present=False):+> Package(
            name=self.upstream_name,
            version=self.upstream_version
        );
        visit [-->];
    }
}

with entry {
    # Healthy reference: bioc-release has no gap.
    bioc_release = Package(name="Biobase", version="2.62.0",
                           desc_present=True,
                           in_packages_index=True,
                           in_views_index=True,
                           has_bytes=True);
    root ++> bioc_release;

    # The four problematic devel packages from issue #6.
    easier = Package(name="easier", version="1.19.0",
                     desc_present=False,
                     in_packages_index=False,
                     in_views_index=False,
                     has_bytes=True);
    nanostring = Package(name="NanoStringNCTools", version="1.21.0",
                         desc_present=False,
                         in_packages_index=False,
                         in_views_index=False,
                         has_bytes=True);
    omics = Package(name="OmicsMLRepoR", version="1.7.0",
                    desc_present=False,
                    in_packages_index=False,
                    in_views_index=False,
                    has_bytes=True);
    tpp = Package(name="TPP", version="3.41.0",
                  desc_present=False,
                  in_packages_index=False,
                  in_views_index=False,
                  has_bytes=True);

    # Connect: every propagated package hangs off root via a typed edge that
    # records *when* it propagated and *which* universe it came from.
    root +>:Propagated(propagated_on="2026-08-08",
                       from_universe="devel"):+> easier;
    root +>:Propagated(propagated_on="2026-08-09",
                       from_universe="devel"):+> nanostring;
    root +>:Propagated(propagated_on="2026-08-08",
                       from_universe="devel"):+> omics;
    root +>:Propagated(propagated_on="2026-08-09",
                       from_universe="devel"):+> tpp;

    print("=== Registry gap audit (2026-08-14) ===");
    print("bioc-release: 2225 indexed, 2225 installable -> no gap");
    print("devel:        2251 indexed, 2247 installable -> 4 described-but-invisible");
    print("");

    root spawn GapAuditor();

    print("");
    summary_count = len(GapAuditor().report);
    # Use a fresh spawn to actually walk; the prior spawn's walker is gone,
    # so we re-spawn to demonstrate the count cleanly.
    auditor = GapAuditor();
    root spawn auditor;
    final_count = len(auditor.report);
    print(f"Audit found {final_count} propagated-but-invisible package(s).");
    print("These are the packages that issue #6 calls out: easier, "
          "NanoStringNCTools, OmicsMLRepoR, TPP.");
}
