    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IdentityResolver(config=cfg);
    }
    out = buf.getvalue();
    assert "resolved: utilities" in out, f"derived name from url path expected: {out}";
}

# ---------------------------------------------------------------------------
# 4. IdentityResolver: ambiguity flagged when sources disagree
# ---------------------------------------------------------------------------
test "flags ambiguity when identity sources disagree" {
    cfg = ResolverConfig(use_registry_identity_for_scm=True, allow_name_override=True);
    root ++> cfg;
    pkg = Package(url="https://example.com/awesome.git", explicit_name="AwesomeLib", registry_identity="awesome.registry");
    tgt = Target(name="AppCore");
