    tgt +>:DependsOn:+> pkg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IdentityResolver(config=cfg);
    }
    assert len(res.ambiguous) == 1, f"expected 1 ambiguous, got {res.ambiguous}";
    assert "awesome.registry" in res.ambiguous, f"chosen value should be recorded: {res.ambiguous}";
}

# ---------------------------------------------------------------------------
# 5. InvalidatePackage: cascade invalidates identity fields of matching pkg
# ---------------------------------------------------------------------------
test "invalidate cascade clears identity fields of matching package" {
    pkg = Package(url="https://example.com/legacy.git", explicit_name="Legacy", registry_identity="legacy.registry");
    tgt = Target(name="AppCLI");
    root +>:Owns:+> tgt;
    tgt +>:DependsOn:+> pkg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn InvalidatePackage(doomed_url="https://example.com/legacy.git");
    }
    out = buf.getvalue();
    assert "invalidated package at https://example.com/legacy.git" in out, f"expected invalidation msg: {out}";
    assert pkg.registry_identity == "", f"registry_identity should be cleared, got {pkg.registry_identity!r}";
    assert pkg.explicit_name == "", f"explicit_name should be cleared, got {pkg.explicit_name!r}";
}

# ---------------------------------------------------------------------------
# 6. InvalidatePackage: leaves non-matching packages untouched
# ---------------------------------------------------------------------------
test "invalidate does not touch unrelated packages" {
    pkg_a = Package(url="https://example.com/keep.git", explicit_name="Keep", registry_identity="keep.registry");
    pkg_b = Package(url="https://example.com/legacy.git", explicit_name="Legacy", registry_identity="legacy.registry");
    tgt = Target(name="AppCore");
