```jac
"""SQL knowledge base modeled as a graph: questions belong to sections,
sections belong to categories, and a walker computes a topical index by
traversing typed edges — replacing what would be recursive joins / CTEs
in SQL with native OSP traversal."""

node Question {
    has number: int = 0;
    has prompt: str = "";
    has difficulty: str = "";
    has answer: str = "";
}

node Section {
    has title: str = "";
}

node Category {
    has name: str = "";
}

# A question lives inside a section.
edge HasQuestion {
    has ordinal: int = 0;
}

# A section belongs to a category.
edge BelongsTo {
}

walker IndexBuilder {
    has total_questions: int = 0;
    has sections_seen: list[str] = [];
    has max_per_section: int = 0;

    can start with Root entry {
        # Begin traversal from the categories hanging off root.
        visit [-->];
    }

    can descend with Category entry {
        print(f"=== Category: {here.name} ===");
        # Walk into the sections of this category.
        visit [->:BelongsTo:->];
    }

    can tally with Section entry {
        # Collect every question in this section, in declaration order.
        here_qs: list = [q for q in [-->](?:Question)];
        self.total_questions += len(here_qs);
        self.sections_seen.append(here.title);
        if len(here_qs) > self.max_per_section {
            self.max_per_section = len(here_qs);
        }
        print(f"  Section '{here.title}' -> {len(here_qs)} question(s):");
        for q in here_qs {
            print(f"    Q{q.number} [{q.difficulty}] {q.prompt}");
        }
        # Continue onward to any further sections/categories.
        visit [-->];
    }
}

with entry {
    # --- categories ----------------------------------------------------------
    cte_cat = Category(name="CTEs & Window Functions");
    idx_cat = Category(name="Indexes & Performance");

    # --- sections ------------------------------------------------------------
    s_advanced = Section(title="Advanced CTEs");
    s_indexes = Section(title="Index Fundamentals");

    # --- questions -----------------------------------------------------------
    # Section: Advanced CTEs
    q136 = Question(
        number=136, difficulty="hard",
        prompt="How to implement pagination with CTE?",
        answer="WITH numbered AS (...) SELECT ... WHERE rn BETWEEN 21 AND 40;",
    );
    q137 = Question(
        number=137, difficulty="hard",
        prompt="How to use CTE for UPSERT with conflict handling?",
        answer="WITH new_data AS (...) INSERT ... ON CONFLICT (email) DO UPDATE ...",
    );
    q138 = Question(
        number=138, difficulty="medium",
        prompt="Subquery to find employees earning above department average?",
        answer="SELECT name FROM e WHERE salary > (SELECT AVG(salary) ...);",
    );
    q140 = Question(
        number=140, difficulty="hard",
        prompt="Compute Fibonacci sequence with recursive CTE?",
        answer="WITH RECURSIVE fib AS (...) SELECT n, a FROM fib;",
    );

    # Section: Index Fundamentals
    q141 = Question(
        number=141, difficulty="easy",
        prompt="What is an index?",
        answer="A data structure that speeds up retrieval at the cost of writes.",
    );
    q142 = Question(
        number=142, difficulty="medium",
        prompt="What types of indexes does PostgreSQL support?",
        answer="B-tree, Hash, GiST, SP-GiST, GIN, BRIN.",
    );
    q143 = Question(
        number=143, difficulty="easy",
        prompt="How to create an index?",
        answer="CREATE INDEX idx_name ON table(col);",
    );

    # --- wire the graph ------------------------------------------------------
    # root -> categories
    root ++> cte_cat;
    root ++> idx_cat;

    # categories -> sections (typed edge: membership carries meaning)
    cte_cat +>:BelongsTo:+> s_advanced;
    idx_cat +>:BelongsTo:+> s_indexes;

    # sections -> questions (typed edge with ordinal payload)
    s_advanced +>:HasQuestion(ordinal=1):+> q136;
    s_advanced +>:HasQuestion(ordinal=2):+> q137;
    s_advanced +>:HasQuestion(ordinal=3):+> q138;
    s_advanced +>:HasQuestion(ordinal=4):+> q140;
    s_indexes +>:HasQuestion(ordinal=1):+> q141;
    s_indexes +>:HasQuestion(ordinal=2):+> q142;
    s_indexes +>:HasQuestion(ordinal=3):+> q143;

    # --- spawn the walker ----------------------------------------------------
    builder = IndexBuilder();
    root spawn builder;

    print(
        f"\nIndex built: {builder.total_questions} questions across "
        f"{len(builder.sections_seen)} sections; "
        f"largest section has {builder.max_per_section} question(s)."
    );
}
