A maintainer on the project vercel-labs/scriptc (unknown) filed this issue about hand-rolled graph machinery causing pain:

Issue #32: Mutually recursive nested function declarations abort at runtime with no diagnostic (exit 133, no output)

Two function declarations **nested inside another function** that call each other abort at runtime. The build succeeds with no diagnostic, and the binary produces no output and no error message — just `exit 133` (SIGTRAP).

The same pair of functions at module top level works correctly, so the trigger is the nesting.

## Repro

```ts
export {}
function outer(n: number): number {
  function even(k: number): number {
    if (k === 0) return 1
    return odd(k - 1)
  }
  function odd(k: number): number {
    if (k === 0) return 0
    return even(k - 1)
  }
  return even(n)
}
function main() {
  console.log(`r=${outer(4)}`)
}
main()
```

```console
$ bun recA.ts
r=1

$ scriptc build recA.ts -o recA     # no diagnostic
$ ./recA
$ echo $?
133
```

Nothing is printed on stdout or stderr.

## Narrowing

| shape | result |
|---|---|
| mutual recursion between nested declarations | **abort, exit 133** |
| the same mutual recursion at top level | works (`r=1`) |
| nested, plain forward reference (`first()` calls `second()`, no cycle) | works |
| nested, backward reference only | works |

So it is specifically the **cycle** among nested declarations, not a forward reference on its own:

```ts
// works
function outer(): number {
  function first(): number { return second() + 1 }
  function second(): number { return 41 }
  return first()
}
```

## Where I hit it

A recursive-descent parser written the conventional way — `primary`/`comparison`/`and`/`or` nested inside `parse()`, with `primary()` calling `or()` for a parenthesised sub-expression. Compiled clean, aborted on every input. Restructuring to top-level functions over an explicit cursor object fixed it.

## Impact

Silent, message-free abort is the worst failure mode: there is nothing to search for and nothing to point at. Even if the fix takes a while, a compile-time refusal naming the cycle would make this tractable.

## Environment

- scriptc 0.0.17, `@scriptc/compiler` 0.0.17
- macOS 26.5.2, arm64, Node v24.18.0
- Static build (no `--dynamic`), default backend

Write a small self-contained Jac demo program that models the essential scenario from this issue natively: pick the 2-4 core entity types as node archetypes with typed has fields, connect instances with edges (typed edges where the relationship carries meaning), and implement walker(s) that perform the traversal the issue complains about (e.g. recursion over parents/children, cascade delete or invalidation, dependency ordering, cycle detection, reachability). Wire a small demonstration graph in a `with entry` block and spawn the walker(s). No I/O, no external libraries, no pytest blocks.

```jac
"""Recursive parser nodes: model mutual recursion among nested function
declarations as walker traversal over a parenthesised expression tree.

The issue describes a recursive-descent parser where `primary()` calls
`or()` for parenthesised sub-expressions, all nested inside `parse()`.
A cycle among the nested declarations aborts at runtime. We model that
as a tree walker that walks all sub-nodes and detects a cycle."""

node Expr {
    has label: str = "";
}

node Literal(Expr) {
    has value: int = 0;
}

node BinOp(Expr) {
    has op: str = "";
    has lhs: Expr | None = None;
    has rhs: Expr | None = None;
}

edge Sub {
    has role: str = "";
}

walker CycleHunter {
    has depth_limit: int = 32;
    has seen: list[str] = [];

    can start with Root entry {
        self.seen = [];
        visit [->:Sub:->];
    }

    can descend with BinOp entry {
        self.seen.append(here.label);
        if self.seen.count(here.label) > 1 {
            print(f"CYCLE detected at {here.label} after {self.seen} steps");
            disengage;
        }
        if len(self.seen) > self.depth_limit {
            print(f"DEPTH LIMIT hit at {here.label}");
            disengage;
        }
        print(f"visit BinOp {here.label} (op={here.op}), trail={self.seen}");
        visit [here ->:Sub:->];
    }

    can collect with Literal entry {
        print(f"collect Literal {here.label}={here.value}, trail={self.seen}");
    }
}

with entry {
    # Build an expression tree:
    #   parse
    #     and
    #       or
    #         primary
    #           5
    #         5
    #       3
    root_lit = Literal(label="L_5a", value=5);
    primary = Literal(label="primary", value=42);
    sub_call = BinOp(label="or", op="||", lhs=root_lit, rhs=primary);
    eq_node = BinOp(label="and", op="&&", lhs=sub_call, rhs=Literal(label="L_3", value=3));

    # Connect: parse -> and -> or -> primary (the cycle: or's rhs is `primary`,
    # but `primary` is also reachable from parse via the same edge chain).
    # To make a true cycle we wire `or` back to `and` so the walker revisits.
    root +>:Sub(role="parse"):+> eq_node;
    eq_node +>:Sub(role="lhs"):+> sub_call;
    eq_node +>:Sub(role="rhs"):+> Literal(label="L_3", value=3);
    sub_call +>:Sub(role="lhs"):+> root_lit;
    sub_call +>:Sub(role="rhs"):+> primary;
    # The cycle: or points back up to and, mirroring the mutual recursion
    # between nested declarations `or` <-> `and` in the original parser.
    sub_call +>:Sub(role="up"):+> eq_node;

    print("=== walking expression graph (cycle mirrors nested mutual recursion) ===");
    root spawn CycleHunter(depth_limit=8);
}
```

jac_tests:
"""Tests for CycleHunter walker over BinOp/Literal sub-graph."""

import io;
import from contextlib { redirect_stdout }

test "cycle in nested sub-graph is detected" {
    # Mirror the issue: mutual recursion between nested declarations.
    # or <-> and cycle, like the parser `or()` / `and()` calling each other.
    root_lit = Literal(label="L_5a", value=5);
    primary = Literal(label="primary", value=42);
    sub_call = BinOp(label="or", op="||", lhs=root_lit, rhs=primary);
    eq_node = BinOp(label="and", op="&&", lhs=sub_call, rhs=Literal(label="L_3", value=3));

    root +>:Sub(role="parse"):+> eq_node;
    eq_node +>:Sub(role="lhs"):+> sub_call;
    sub_call +>:Sub(role="lhs"):+> root_lit;
    sub_call +>:Sub(role="rhs"):+> primary;
    # The cycle: or -> and (mutual recursion among nested declarations).
    sub_call +>:Sub(role="up"):+> eq_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=8);
    }
    out = buf.getvalue();
    assert "CYCLE detected" in out, f"expected cycle detection, got: {out}";
    assert "and" in out or "or" in out, f"expected cycle label in output: {out}";
}

test "acyclic expression tree traverses all leaves" {
    # No cycle: tree walks every BinOp and collects every Literal cleanly.
    l1 = Literal(label="L_1", value=1);
    l2 = Literal(label="L_2", value=2);
    l3 = Literal(label="L_3", value=3);
    or_node = BinOp(label="or", op="||", lhs=l1, rhs=l2);
    and_node = BinOp(label="and", op="&&", lhs=or_node, rhs=l3);

    root +>:Sub(role="parse"):+> and_node;
    and_node +>:Sub(role="lhs"):+> or_node;
    and_node +>:Sub(role="rhs"):+> l3;
    or_node +>:Sub(role="lhs"):+> l1;
    or_node +>:Sub(role="rhs"):+> l2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=32);
    }
    out = buf.getvalue();
    # No cycle message should be present.
    assert "CYCLE detected" not in out, f"false cycle in acyclic tree: {out}";
    assert "DEPTH LIMIT" not in out, f"unexpected depth limit: {out}";
    # All three literals should have been collected.
    assert "L_1" in out and "L_2" in out and "L_3" in out, f"missing leaves: {out}";
    # Both BinOps should have been visited.
    assert "visit BinOp or" in out, f"missing `or` visit: {out}";
    assert "visit BinOp and" in out, f"missing `and` visit: {out}";
}

test "deep nesting without cycle hits depth limit" {
    # Build a long chain of BinOps -> BinOps, no Literal leaves at the chain tips
    # except the deepest; should walk until depth_limit trips (default 32).
    head = BinOp(label="n0", op="+", lhs=None, rhs=None);
    prev = head;
    for i in range(1, 30) {
        nxt = BinOp(label=f"n{i}", op="+", lhs=None, rhs=None);
        prev +>:Sub(role="lhs"):+> nxt;
        prev = nxt;
    }
    root +>:Sub(role="parse"):+> head;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=10);
    }
    out = buf.getvalue();
    assert "DEPTH LIMIT" in out, f"expected depth limit, got: {out}";
    assert "CYCLE detected" not in out, f"false cycle in linear chain: {out}";
}

test "graph shape: Sub edges connect BinOps to their sub-expressions" {
    # Verify the typed-edge topology itself: each BinOp fans out via Sub edges.
    l_a = Literal(label="A", value=1);
    l_b = Literal(label="B", value=2);
    top = BinOp(label="top", op="+", lhs=l_a, rhs=l_b);

    root +>:Sub(role="parse"):+> top;
    top +>:Sub(role="lhs"):+> l_a;
    top +>:Sub(role="rhs"):+> l_b;

    # From root, exactly one Sub edge to `top`.
    children = [root->:Sub:->];
    assert len(children) == 1, f"expected 1 sub from root, got {len(children)}";
    assert children[0].label == "top", f"expected `top`, got {children[0].label}";

    # `top` has two Sub children: A and B.
    subs = [top ->:Sub:->];
    assert len(subs) == 2, f"expected 2 subs from top, got {len(subs)}";
    labels = sorted([s.label for s in subs]);
    assert labels == ["A", "B"], f"unexpected sub labels: {labels}";

    # End-to-end walker still works (no cycle).
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=16);
    }
    out = buf.getvalue();
    assert "CYCLE detected" not in out, f"false cycle: {out}";
    assert "collect Literal A" in out, f"missing A collection: {out}";
    assert "collect Literal B" in out, f"missing B collection: {out}";
}

