"""Tests for the knowledge-graph evaluation walker."""

import io;
import from contextlib { redirect_stdout }

test "tenant isolation blocks cross-tenant traversal" {
    buf = io.StringIO();
    acme = Tenant(tenant_id="acme");
    globex = Tenant(tenant_id="globex");

    acme_item = Concept(kind="concept", title="acme-only", summary="s", definition="d");
    globex_item = Concept(kind="concept", title="globex-secret", summary="s", definition="d");

    acme ++> acme_item;
    globex ++> globex_item;
    root ++> acme;
    root ++> globex;

    # Wrong tenant: walker tenant_id="acme" but spawned on globex -> must disengage immediately
    with redirect_stdout(buf) {
        res = globex spawn Evaluator(tenant_id="acme");
    }
    out = buf.getvalue();
    assert "tenant mismatch" in out, f"expected mismatch msg, got: {out}";
    assert "globex-secret" not in res.visited, f"leaked: {res.visited}";
    assert "acme-only" not in res.visited, f"wrong direction: {res.visited}";
}

test "correct tenant scopes and visits owned nodes" {
    buf = io.StringIO();
    acme = Tenant(tenant_id="acme");
    globex = Tenant(tenant_id="globex");

    acme_item = Concept(kind="concept", title="acme-thing", summary="s", definition="d");
    globex_item = Concept(kind="concept", title="globex-thing", summary="s", definition="d");

    acme ++> acme_item;
    globex ++> globex_item;
    root ++> acme;
    root ++> globex;

    with redirect_stdout(buf) {
        res = acme spawn Evaluator(tenant_id="acme", depth_cap=4);
    }
    out = buf.getvalue();
    assert "TENANT" in out, f"missing tenant scope msg: {out}";
    assert "TRUSTED" in out, f"missing trusted label: {out}";
    assert "acme-thing" in res.visited, f"not visited: {res.visited}";
    assert "globex-thing" not in res.visited, f"cross-tenant leak: {res.visited}";
}

test "stale knowledge halts further descent" {
    buf = io.StringIO();
    acme = Tenant(tenant_id="acme");

    fresh_item = Concept(kind="concept", title="fresh-node",
                         summary="s", definition="d");
    stale_item = Concept(kind="concept", title="stale-node",
                         summary="s", definition="d", fresh=False);
    downstream = Concept(kind="concept", title="downstream-node",
                         summary="s", definition="d");

    acme ++> fresh_item;
    fresh_item +>:Related(weight=0.5, source="x", version="1",
                          confidence=0.5, fresh=True, trustworthy=True):+> stale_item;
    stale_item +>:Related(weight=0.5, source="x", version="1",
                          confidence=0.5, fresh=True, trustworthy=True):+> downstream;
    root ++> acme;

    with redirect_stdout(buf) {
        res = acme spawn Evaluator(tenant_id="acme", depth_cap=10);
    }
    out = buf.getvalue();
    assert "fresh-node" in res.visited, f"start missed: {res.visited}";
    assert "stale-node" in res.visited, f"stale should be visited but halt: {res.visited}";
    assert "downstream-node" not in res.visited, f"descent not halted: {res.visited}";
    assert "STALE" in out, f"missing stale label: {out}";
    assert "halting descent" in out, f"missing halt msg: {out}";
}

test "depth cap stops deep traversal" {
    buf = io.StringIO();
    acme = Tenant(tenant_id="acme");

    n0 = Concept(kind="concept", title="n0", summary="s", definition="d");
    n1 = Concept(kind="concept", title="n1", summary="s", definition="d");
    n2 = Concept(kind="concept", title="n2", summary="s", definition="d");
    n3 = Concept(kind="concept", title="n3", summary="s", definition="d");
    n4 = Concept(kind="concept", title="n4", summary="s", definition="d");
    n5 = Concept(kind="concept", title="n5", summary="s", definition="d");

    acme ++> n0;
    n0 +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                  fresh=True, trustworthy=True):+> n1;
    n1 +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                  fresh=True, trustworthy=True):+> n2;
    n2 +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                  fresh=True, trustworthy=True):+> n3;
    n3 +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                  fresh=True, trustworthy=True):+> n4;
    n4 +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                  fresh=True, trustworthy=True):+> n5;
    root ++> acme;

    with redirect_stdout(buf) {
        res = acme spawn Evaluator(tenant_id="acme", depth_cap=2);
    }
    out = buf.getvalue();
    assert "n0" in res.visited, f"start missed: {res.visited}";
    assert "n1" in res.visited, f"depth-1 missed: {res.visited}";
    assert "n2" in res.visited, f"depth-2 missed: {res.visited}";
    # With cap=2, deeper nodes must be cut off
    assert "n4" not in res.visited, f"depth cap failed (n4): {res.visited}";
    assert "n5" not in res.visited, f"depth cap failed (n5): {res.visited}";
}

test "mixed knowledge kinds all scored uniformly" {
    buf = io.StringIO();
    acme = Tenant(tenant_id="acme");

    pre = Prerequisite(kind="prerequisite", title="pre-thing",
                       summary="s", skill_level=1);
    con = Concept(kind="concept", title="con-thing",
                  summary="s", definition="d");
    cst = Constraint(kind="constraint", title="cst-thing",
                     rule="the rule");
    src = Source(kind="source", title="src-thing",
                 uri="https://example.org", authority=0.8);

    acme ++> pre;
    pre +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                   fresh=True, trustworthy=True):+> con;
    con +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                   fresh=True, trustworthy=True):+> cst;
    cst +>:Related(weight=0.5, source="x", version="1", confidence=0.5,
                   fresh=True, trustworthy=True):+> src;
    root ++> acme;

    with redirect_stdout(buf) {
        res = acme spawn Evaluator(tenant_id="acme", depth_cap=10);
    }
    out = buf.getvalue();
    for t in ["pre-thing", "con-thing", "cst-thing", "src-thing"] {
        assert t in res.visited, f"missing {t} in {res.visited}";
    }
    for k in ["prerequisite", "concept", "constraint", "source"] {
        assert k in out, f"missing kind label {k} in: {out}";
