    a = EnvVar(name="A", raw_value="${B}");
    b = EnvVar(name="B", raw_value="${C}");
    cc = EnvVar(name="C", raw_value="${D}");
    dd = EnvVar(name="D", raw_value="${E}");
    ee = EnvVar(name="E", raw_value="${F}");
