        "A": "${B}", "B": "${C}", "C": "${D}", "D": "${E}",
        "E": "${F}", "F": "${G}", "G": "leaf",
    };

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Resolver(env_map=env, max_depth=3);
    }
    out = buf.getvalue();

    # With max_depth=3 the recursion exceeds it and the walker reports the error.
    assert "CircularReferenceError" in out, f"expected depth-limit failure, got: {out}";
}

test "literal variable resolves normally without error" {
    root ++> EnvVar(name="D", raw_value="literal-value");

    env: dict[str, str] = {"D": "literal-value"};

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Resolver(env_map=env, max_depth=32);
    }
    out = buf.getvalue();

    assert "CircularReferenceError" not in out, f"literal should not error, got: {out}";
    assert "D -> literal-value" in out, f"expected resolved literal line, got: {out}";
}

