"""Test annex for the XSD schema graph program.

We test the BEHAVIOUR the program promises:
  1. strip_ns removes "xs:" / "xs:" prefixes from any string field.
  2. The Resolver walker builds a name->kind index for every TypeDef and
     Group it visits, with the right labels.
  3. Element type_refs are normalised in place when the walker visits them.
  4. Following an ElementTypeRef back into a TypeDef (or ElementGroupRef
     into a Group) lands on the right target node.
  5. Cycles in TypeDerivation chains are reported via cycle_found and the
     walker disengages instead of looping forever.
"""

import io;
import from contextlib { redirect_stdout }

# ── test 1: strip_ns + deep_strip_ns_on mutate schema fields in place ───────
test "strip_ns removes xs prefix on schema fields" {
    schema = Schema(schema_name="xs:orderSchema", target_namespace="xs:urn:example");
    deep_strip_ns_on(schema);
    assert schema.schema_name == "orderSchema", f"got {schema.schema_name}";
    assert schema.target_namespace == "urn:example", f"got {schema.target_namespace}";

    # strip_ns on its own
    assert strip_ns("xs:PartInfo") == "PartInfo", "strip_ns failed";
    assert strip_ns("no_prefix") == "no_prefix", "strip_ns pass-through failed";
    assert strip_ns("") == "", "strip_ns empty failed";
}

# ── test 2: Resolver builds a complete name index for types + groups ─────────
test "resolver indexes every TypeDef and Group" {
    schema = Schema(schema_name="xs:orderSchema", target_namespace="xs:urn:example");
    part_info = TypeDef(declared_name="xs:PartInfo", kind="complexType");
    part_base = TypeDef(declared_name="xs:PartBase", kind="complexType");
    code_type = TypeDef(declared_name="xs:CodeType", kind="simpleType");
    id_group = Group(declared_name="xs:CommonIdAttrs", group_kind="attributeGroup");

    schema ++> part_info;
    schema ++> part_base;
    schema ++> code_type;
    schema ++> id_group;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = schema spawn Resolver();
    }
    out = buf.getvalue();

    # Index must contain all four names, with correct kind labels.
    assert "PartInfo" in res.index, f"missing PartInfo: {res.index}";
    assert res.index["PartInfo"] == "type", f"PartInfo kind: {res.index.get('PartInfo')}";
    assert "PartBase" in res.index, f"missing PartBase: {res.index}";
    assert res.index["PartBase"] == "type", f"PartBase kind: {res.index.get('PartBase')}";
    assert "CodeType" in res.index, f"missing CodeType: {res.index}";
    assert res.index["CodeType"] == "type", f"CodeType kind: {res.index.get('CodeType')}";
    assert "CommonIdAttrs" in res.index, f"missing CommonIdAttrs: {res.index}";
    assert res.index["CommonIdAttrs"] == "group", f"group kind: {res.index.get('CommonIdAttrs')}";
    assert len(res.index) == 4, f"index size: {len(res.index)}";

    # The walker must have printed a registration line per name.
    assert "index[PartInfo]" in out, f"missing PartInfo log: {out}";
    assert "index[CommonIdAttrs]" in out, f"missing group log: {out}";

    # No cycle in this acyclic graph.
    assert len(res.cycle_found) == 0, f"unexpected cycles: {res.cycle_found}";
}

# ── test 3: Element type_refs are stripped and the typed edge resolves ───────
test "element references are stripped and traversable" {
    schema = Schema(schema_name="xs:orderSchema", target_namespace="xs:urn:example");
    part_info = TypeDef(declared_name="xs:PartInfo", kind="complexType");
    code_type = TypeDef(declared_name="xs:CodeType", kind="simpleType");
    part_el = Element(element_name="xs:part", type_ref="xs:PartInfo");
    code_el = Element(element_name="xs:code", type_ref="xs:CodeType");

    schema ++> part_info;
    schema ++> code_type;
    schema ++> part_el;
    schema ++> code_el;
    part_el +>:ElementTypeRef:+> part_info;
    code_el +>:ElementTypeRef:+> code_type;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = schema spawn Resolver();
    }
    out = buf.getvalue();

    # In-place normalisation of element refs.
    assert part_el.type_ref == "PartInfo", f"got {part_el.type_ref}";
    assert code_el.type_ref == "CodeType", f"got {code_el.type_ref}";

    # The walker should have logged both refs as resolved.
    assert "refs PartInfo (resolved)" in out, f"missing PartInfo resolve: {out}";
    assert "refs CodeType (resolved)" in out, f"missing CodeType resolve: {out}";

    # The ElementTypeRef edge from part_el should lead to part_info.
    targets = [part_el ->:ElementTypeRef:->];
    assert part_info in targets, f"typed edge missing: {targets}";

    # Element with an unresolvable ref should be logged as UNRESOLVED.
    orphan = Element(element_name="xs:ghost", type_ref="xs:Missing");
    schema ++> orphan;
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        res2 = schema spawn Resolver();
    }
    out2 = buf2.getvalue();
    assert "refs Missing (UNRESOLVED)" in out2, f"missing UNRESOLVED log: {out2}";
}

# ── test 4: TypeDerivation cycle is detected and walker disengages ───────────
test "derivation cycle is detected" {
    schema = Schema(schema_name="xs:orderSchema", target_namespace="xs:urn:example");
    a = TypeDef(declared_name="xs:A", kind="complexType", derived_from="xs:B");
    b = TypeDef(declared_name="xs:B", kind="complexType", derived_from="xs:A");

    schema ++> a;
    schema ++> b;
    a +>:TypeDerivation(base_kind="extension"):+> b;
    b +>:TypeDerivation(base_kind="restriction"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = schema spawn Resolver();
    }
    out = buf.getvalue();

    # Both types still land in the index; the cycle is reported, not silently
    # swallowed.
    assert "A" in res.index, f"A missing: {res.index}";
    assert "B" in res.index, f"B missing: {res.index}";
    assert len(res.cycle_found) >= 1, f"no cycle reported: {res.cycle_found}";
    assert "cycle detected" in out, f"missing cycle log: {out}";
}

