test "budgeted recompute respects document disable" {
    doc = Document(name="Doc5", global_recompute=False);
    job = Job(label="J5");
    op = Operation(label="OpZ", last_exec_ms=2000);

    doc +>:Owns:+> job;
    job +>:Owns:+> op;

    buf = io.StringIO();
