"""Test annex for the recursive wrap / path-access demo.

Exercises the behaviors the issue promises:
- RecursiveWrap marks every reachable MappingNode as wrapped.
- RecursiveWrap is cycle-safe (visited guard).
- PathReader resolves tuple-style paths down a Child chain.
- PathReader returns the leaf value, not a wrapper.

Uses fresh sub-graphs per test to keep workers isolated.
"""

import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------

def make_store_and_tree {
    a = MappingNode(key="a");
    b = MappingNode(key="b");
    c = MappingNode(key="c", value=42);
    s = MappingStore(name="s");
    root ++> s
              +>:Child(label="root->a"):+> a
              +>:Child(label="a->b"):+> b
              +>:Child(label="b->c"):+> c;
    return (s, a, b, c);
}

def make_cycle_store {
    a2 = MappingNode(key="a2");
    b2 = MappingNode(key="b2");
    s2 = MappingStore(name="s2");
    root ++> s2 +>:Child:+> a2 +>:Child:+> b2 +>:Child:+> a2;
    return (s2, a2, b2);
}

# ---------- tests ----------

test "recursive wrap reaches every level and marks them" {
    (s, a, b, c) = make_store_and_tree();

    assert not a.wrapped, f"a should start unwrapped, got {a.wrapped}";
    assert not b.wrapped, f"b should start unwrapped, got {b.wrapped}";
    assert not c.wrapped, f"c should start unwrapped, got {c.wrapped}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = s spawn RecursiveWrap(store_name="s");
    }
    out = buf.getvalue();

    assert a.wrapped, f"a not wrapped after walk: {a.wrapped}";
    assert b.wrapped, f"b not wrapped after walk: {b.wrapped}";
    assert c.wrapped, f"c (leaf) not wrapped after walk: {c.wrapped}";
    assert "wrap: a -> add_path_access applied" in out, f"missing a wrap: {out}";
    assert "wrap: b -> add_path_access applied" in out, f"missing b wrap: {out}";
    assert "wrap: c -> add_path_access applied" in out, f"missing c wrap: {out}";
}

test "path reader resolves tuple-style path to leaf value" {
    (s, a, b, c) = make_store_and_tree();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        reader = PathReader(path=["a", "b", "c"]);
        res = s spawn reader;
    }
    out = buf.getvalue();

    assert res.result == 42, f"PathReader should resolve to 42, got {res.result}";
    assert "resolved: c = 42" in out, f"missing resolution line: {out}";
}

test "path reader returns leaf when path is empty after descent" {
    (s, a, b, c) = make_store_and_tree();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        reader = PathReader(path=["a", "b", "c"]);
        res = s spawn reader;
    }
    out = buf.getvalue();

    assert res.result is not None, "PathReader must produce a non-None result";
    assert res.result == c.value, f"PathReader result should equal leaf value, got {res.result}";
    assert res.result != b.value, "PathReader must not stop at an intermediate level";
}

test "recursive wrap is cycle-safe with back-edge" {
    (s2, a2, b2) = make_cycle_store();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = s2 spawn RecursiveWrap(store_name="s2");
    }
    out = buf.getvalue();

    assert "skip (cycle): a2" in out, f"cycle should be reported via skip: {out}";
    assert a2.wrapped, f"a2 should be wrapped even with cycle, got {a2.wrapped}";
    assert b2.wrapped, f"b2 should be wrapped even with cycle, got {b2.wrapped}";

    visited = res.visited_keys;
    count_a2 = 0;
    for k in visited {
        if k == "a2" {
            count_a2 = count_a2 + 1;
        }
    }
    assert count_a2 == 1, f"a2 should be visited exactly once, got {count_a2}";
}

