"""Test annex for the conversation tracker demo.

Validates the behavior the issue spec promises:
  - RangeProbe walks every message exactly once per spawned run.
  - Stable templates do NOT print the full-recompute marker.
  - Qwen-family templates DO print the full-recompute marker.
  - tokens_seen accumulates every message's token_count across both sessions.
"""

import io;
import from contextlib { redirect_stdout }

test "full graph walk hits every message exactly once" {
    chat = Session(session_id="chat-001", template="chatml", reanchors_on_user=False);
    qwen = Session(session_id="qwen-001", template="qwen3.6", reanchors_on_user=True);

    m0 = Message(role="user", content="hi", token_count=12);
    m1 = Message(role="assistant", content="hello", token_count=14);
    chat +>:Next(seq=0):+> m0 +>:Next(seq=1):+> m1;

    q0 = Message(role="user", content="task", token_count=30);
    q1 = Message(role="assistant", content="step 1", token_count=80);
    q2 = Message(role="tool", content="obs", token_count=350);
    qwen +>:Next(seq=0):+> q0 +>:Next(seq=1):+> q1 +>:Next(seq=2):+> q2;

    root +>:Owns:+> chat;
    root +>:Owns:+> qwen;

    buf = io.StringIO();
    probe = RangeProbe();
    with redirect_stdout(buf) {
        root spawn probe;
    }
    # 2 messages in chat + 3 messages in qwen = 5 probes total
    assert probe.probes == 5, f"expected 5 probes, got {probe.probes}";
}

test "stable template does not trigger the full-recompute marker" {
    chat = Session(session_id="chat-stable", template="chatml", reanchors_on_user=False);

    m0 = Message(role="user", content="hi", token_count=12);
    m1 = Message(role="assistant", content="hello", token_count=14);
    m2 = Message(role="user", content="how are you", token_count=22);
    chat +>:Next(seq=0):+> m0 +>:Next(seq=1):+> m1 +>:Next(seq=2):+> m2;

    root +>:Owns:+> chat;

    buf = io.StringIO();
    probe = RangeProbe();
    with redirect_stdout(buf) {
        root spawn probe;
    }
    out = buf.getvalue();
    assert "[OUT_STABLE]" not in out, f"stable template must not print full-recompute marker: {out}";
    assert "mode=APPEND" in out, f"stable session should report APPEND mode: {out}";
    assert "mode=REANCHOR" not in out, f"stable session must not report REANCHOR: {out}";
}

test "qwen template forces the full-recompute marker" {
    qwen = Session(session_id="qwen-trace", template="qwen3.6", reanchors_on_user=True);

    q0 = Message(role="user", content="task", token_count=30);
    q1 = Message(role="assistant", content="step 1", token_count=80);
    q2 = Message(role="tool", content="obs", token_count=350);
    q3 = Message(role="assistant", content="step 2", token_count=120);
    q4 = Message(role="user", content="continue", token_count=10);
    qwen +>:Next(seq=0):+> q0 +>:Next(seq=1):+> q1 +>:Next(seq=2):+> q2
        +>:Next(seq=3):+> q3 +>:Next(seq=4):+> q4;

    root +>:Owns:+> qwen;

    buf = io.StringIO();
    probe = RangeProbe();
    with redirect_stdout(buf) {
        root spawn probe;
    }
    out = buf.getvalue();
    assert "[OUT_QWEN]" not in out, f"qwen template must print full-recompute marker: {out}";
    assert "mode=REANCHOR" in out, f"qwen session must report REANCHOR mode: {out}";
    assert "mode=APPEND" not in out, f"qwen session must not report APPEND: {out}";
}

test "tokens_seen accumulates every message's token_count" {
    chat = Session(session_id="chat-001", template="chatml", reanchors_on_user=False);
    qwen = Session(session_id="qwen-001", template="qwen3.6", reanchors_on_user=True);

    m0 = Message(role="user", content="hi", token_count=12);
    m1 = Message(role="assistant", content="hello", token_count=14);
    m2 = Message(role="user", content="how are you", token_count=22);
    m3 = Message(role="assistant", content="doing well", token_count=18);
    chat +>:Next(seq=0):+> m0 +>:Next(seq=1):+> m1 +>:Next(seq=2):+> m2
        +>:Next(seq=3):+> m3;

    q0 = Message(role="user", content="task", token_count=30);
    q1 = Message(role="assistant", content="step 1", token_count=80);
    q2 = Message(role="tool", content="obs", token_count=350);
    qwen +>:Next(seq=0):+> q0 +>:Next(seq=1):+> q1 +>:Next(seq=2):+> q2;

    root +>:Owns:+> chat;
    root +>:Owns:+> qwen;

    buf = io.StringIO();
    probe = RangeProbe();
    with redirect_stdout(buf) {
        root spawn probe;
    }
    # chat: 12+14+22+18 = 66; qwen: 30+80+350 = 460; total = 526
    expected = 12 + 14 + 22 + 18 + 30 + 80 + 350;
    assert probe.tokens_seen == expected, f"expected {expected} tokens, got {probe.tokens_seen}";
    assert probe.probes == 7, f"expected 7 probes (4 chat + 3 qwen), got {probe.probes}";
}

