"""Tests for the backlog triage graph: typed blocking edges, tier-aware
triage traversal, cycle detection on dependency walks, and shared-root-cause
groupings surface adjacent issues."""

import io;
import from contextlib { redirect_stdout }

test "triage walks root children and emits per-tier ordering" {
    root ++> Issue(title="seed-a", severity=10, corrupt=True)
         ++> Issue(title="seed-b", severity=9);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Triage(current_tier=1);
    }
    out = buf.getvalue();
    assert "Backlog triage order (tier 1)" in out, f"missing header: {out}";
    assert "seed-a" in out, f"missing first child: {out}";
    assert "seed-b" in out, f"missing second child: {out}";
    assert "[CORRUPT]" in out, f"corrupt flag missing: {out}";
}

test "Blocks edge carries tier field and orders downstream issues" {
    head = Issue(title="head", severity=10, corrupt=True);
    middle = Issue(title="middle", severity=9);
    tail = Issue(title="tail", severity=8);
    root ++> head;
    head +>:Blocks(tier=1):+> middle;
    middle +>:Blocks(tier=1):+> tail;

    blocks_from_head = [head ->:Blocks:->];
    assert len(blocks_from_head) == 1, f"expected one Blocks edge from head, got {len(blocks_from_head)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = head spawn FollowBlocking();
    }
    out = buf.getvalue();
    assert "blocks -> head" in out, f"missing head emission: {out}";
    assert "blocks -> middle" in out, f"missing middle emission: {out}";
    assert "blocks -> tail" in out, f"missing tail emission: {out}";
    # head should appear before middle, middle before tail in the report.
    assert out.index("blocks -> head") < out.index("blocks -> middle"), "head must precede middle";
    assert out.index("blocks -> middle") < out.index("blocks -> tail"), "middle must precede tail";
}

test "FollowBlocking detects cycle and disengages cleanly" {
    a = Issue(title="cyc-a", severity=9);
    b = Issue(title="cyc-b", severity=9);
    c = Issue(title="cyc-c", severity=8);
    root ++> a;
    a +>:Blocks(tier=1):+> b;
    b +>:Blocks(tier=1):+> c;
    c +>:Blocks(tier=1):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = a spawn FollowBlocking();
    }
    out = buf.getvalue();
    assert "cycle detected at: cyc-a" in out, f"cycle marker missing: {out}";
    assert "blocks -> cyc-b" in out, f"b must be visited before cycle closes: {out}";
    assert "blocks -> cyc-c" in out, f"c must be visited before cycle closes: {out}";
}

test "triage dedupes revisits and counts issues walked once" {
    a = Issue(title="rev-a", severity=10, corrupt=True);
    b = Issue(title="rev-b", severity=9);
    root ++> a ++> b;
    a +>:Blocks(tier=1):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Triage(current_tier=1);
    }
    out = buf.getvalue();
    # rev-b should appear exactly once even though it's both a child and
    # a Blocks target — the visited guard dedupes it.
    assert out.count("rev-b") == 1, f"rev-b walked {out.count('rev-b')} times: {out}";
    assert out.count("rev-a") == 1, f"rev-a walked {out.count('rev-a')} times: {out}";
}

test "SharesRootCause groups adjacent issues via typed edge" {
    a = Issue(title="src-a", severity=10, corrupt=True);
    b = Issue(title="src-b", severity=10, corrupt=True);
    root ++> a ++> b;
    a +>:SharesRootCause(note="same hazard"):+> b;

    src_edges = [a ->:SharesRootCause:->];
    assert len(src_edges) == 1, f"expected one SharesRootCause edge, got {len(src_edges)}";
    targets = [a ->:SharesRootCause:->][0];
    assert targets.title == "src-b", f"wrong target: {targets.title}";
    # The Blocks graph still wires ordering independently of the grouping.
    assert [a ->:Blocks:->] == [], "Blocks edge must not be polluted by SharesRootCause";
}

