test "identity-neutral report reaches archive without cycle" {
    # Build a graph where the report's lineage/binding match the current
    # authority and binding. The auditor must treat the report as
    # identity-neutral, follow the Clears edge to archive, and NOT
    # detect a cycle.
    stale_report = VerifyReport(
