        evidence_hash="sha256:2952d353df99704b6bbc2dc2824b31a6df0832de6b8d85d127e3f11869723c32",
    );
    approved = ReviewAuthority(
        lineage="review-unit2-verify-refresh-recovery-1050c6f4",
        approved=True,
    );
    bound = SDDBinding(
        revision="sha256:d944d9efc3e38e8e625bd1fcb3ec3b3d5780859e658d935384db1dba19d8d73e",
    );
    archive = Archive(ready=True);

    root ++> stale_report;
    stale_report +>:Binds:+> bound;
    stale_report +>:Binds:+> approved;
    approved +>:Clears:+> archive;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = LifecycleAuditor(
            target_lineage="review-unit2-verify-refresh-recovery-1050c6f4",
            target_binding="sha256:d944d9efc3e38e8e625bd1fcb3ec3b3d5780859e658d935384db1dba19d8d73e",
        );
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.cycle_detected == False, f"cycle wrongly flagged on identity-neutral report: {out}";
    assert auditor.steps == 1, f"expected 1 audit step, got {auditor.steps}";
    assert "[OK]" in out, f"identity-neutral report not recognized: {out}";
    assert "[ARCHIVE]" in out, f"archive not reached: {out}";
    assert "[CYCLE]" not in out, f"false cycle detected: {out}";
}

test "stale-chain two-node loop is detected as cycle" {
    # Two VerifyReports that Stales each other form a deterministic cycle.
    # The auditor's seen-set or step budget must trip and flag the cycle.
    stale_report = VerifyReport(
        title="report-A",
        candidate_ref="candidate-A",
        lineage_ref="lineage-A",
        binding_ref="binding-A",
    );
    refreshed_report = VerifyReport(
        title="report-B",
        candidate_ref="candidate-B",
        lineage_ref="lineage-B",
        binding_ref="binding-B",
    );

    root ++> stale_report;
    stale_report +>:Stales(kind="predecessor-candidate"):+> refreshed_report;
    refreshed_report +>:Stales(kind="predecessor-candidate"):+> stale_report;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = LifecycleAuditor(
            target_lineage="lineage-A",
            target_binding="binding-A",
        );
        root spawn auditor;
