    out = buf.getvalue();

    assert auditor.cycle_detected == True, f"cycle not detected on 2-node stale loop: steps={auditor.steps} out={out}";
    assert "[CYCLE]" in out or "[ABORT]" in out, f"no cycle/abort marker in output: {out}";
}

test "unapproved authority does not short-circuit to archive" {
    # Report lineage matches an authority node but the authority is NOT
    # approved. The report must be treated as stale; archive must NOT be
    # reached via a Clears path that requires approved authority.
    stale_report = VerifyReport(
        title="report-pending",
        candidate_ref="candidate-X",
        lineage_ref="lineage-X",
        binding_ref="binding-X",
