    stale_report +>:Binds:+> pending;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = LifecycleAuditor(
            target_lineage="lineage-X",
            target_binding="binding-X",
        );
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[OK]" not in out, f"unapproved authority should not yield identity-neutral OK: {out}";
    assert "[STALE]" in out, f"expected stale marker, got: {out}";
