test "binding mismatch keeps report stale" {
    # Report's binding_ref differs from the SDDBinding revision it points
    # at. Authority matches but binding doesn't — report is stale, cycle
    # follows Stales edges (none here so it just records stale state).
    stale_report = VerifyReport(
