"""Tests for LilySdkError-style serialization (issue #60).

Verifies the toJSON() walker records shape, the toString() walker prints code
and status, the cause chain is followed recursively, and the cycle guard
prevents infinite traversal.
"""

import io;
import from contextlib { redirect_stdout }

test "toJSON records include all SDK fields and follow cause chain" {
    # Linear cause chain: top -> mid -> low.
    low = SLDNetworkError(
        name="SLDNetworkError",
        message="connection refused",
        code="NET_CONN_REFUSED",
        status_code=0,
        details={"host": "api.example.com", "port": 443},
    );
    mid = SLDApiError(
        name="SLDApiError",
        message="upstream timeout",
        code="API_TIMEOUT",
        status_code=504,
        details={"endpoint": "/v1/orders", "timeout_ms": 30000},
    );
    top = SLDApiError(
        name="SLDApiError",
        message="failed to place order",
        code="ORDER_REJECTED",
        status_code=422,
        details={"order_id": "ord_42", "reason": "inventory"},
    );

    top +>:CausedBy:+> mid;
    mid +>:CausedBy:+> low;

    root ++> top;
    ser = ErrorSerializer();
    res = root spawn ser;

    # Spawn returns the walker; .out holds (depth, record) tuples in order.
    assert len(res.out) == 3, f"expected 3 cause records, got {len(res.out)}";

    # Depth grows by 1 per level (top=0, mid=1, low=2).
    depths = [r[0] for r in res.out];
    assert depths == [0, 1, 2], f"depths should be 0,1,2, got {depths}";

    # First record: top-level API error.
    (lvl0, rec0) = res.out[0];
    assert rec0["name"] == "SLDApiError", f"top name: {rec0['name']}";
    assert rec0["code"] == "ORDER_REJECTED", f"top code: {rec0['code']}";
    assert rec0["statusCode"] == 422, f"top statusCode: {rec0['statusCode']}";
    assert rec0["message"] == "failed to place order", f"top message: {rec0['message']}";
    assert rec0["details"] == {"order_id": "ord_42", "reason": "inventory"},
        f"top details: {rec0['details']}";
    # 'cause' key is reserved for the next record by the walker, set to None.
    assert "cause" in rec0, "toJSON record must include a 'cause' key";
    assert rec0["cause"] is None, f"top cause should be None, got {rec0['cause']}";

    # Middle record: API error with status 504.
    (lvl1, rec1) = res.out[1];
    assert rec1["name"] == "SLDApiError", f"mid name: {rec1['name']}";
    assert rec1["code"] == "API_TIMEOUT", f"mid code: {rec1['code']}";
    assert rec1["statusCode"] == 504, f"mid statusCode: {rec1['statusCode']}";

    # Lowest record: network error with status_code 0 (the default).
    (lvl2, rec2) = res.out[2];
    assert rec2["name"] == "SLDNetworkError", f"low name: {rec2['name']}";
    assert rec2["code"] == "NET_CONN_REFUSED", f"low code: {rec2['code']}";
    assert rec2["statusCode"] == 0, f"low statusCode: {rec2['statusCode']}";
    assert rec2["details"] == {"host": "api.example.com", "port": 443},
        f"low details: {rec2['details']}";
}

test "toString walker emits code and statusCode suffixes when set" {
    a = SLDApiError(
        name="SLDApiError",
        message="upstream timeout",
        code="API_TIMEOUT",
        status_code=504,
        details={"endpoint": "/v1/orders"},
    );
    b = SLDNetworkError(
        name="SLDNetworkError",
        message="connection refused",
        code="NET_CONN_REFUSED",
        status_code=0,
        details={"host": "api.example.com"},
    );
    a +>:CausedBy:+> b;

    root ++> a;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ErrorPrinter();
    }
    out = buf.getvalue();

    # First line: name, message, code suffix, status suffix, details.
    assert "SLDApiError" in out, f"missing api error name: {out}";
    assert "upstream timeout" in out, f"missing api message: {out}";
    assert "[code=API_TIMEOUT]" in out, f"missing code suffix: {out}";
    assert "[status=504]" in out, f"missing status suffix: {out}";

    # Cause chain is followed, so the network error is also printed.
    assert "SLDNetworkError" in out, f"missing nested network error: {out}";
    assert "[code=NET_CONN_REFUSED]" in out, f"missing network code: {out}";
    # status_code==0 is the default, so the walker must NOT print [status=0].
    assert "[status=0]" not in out, f"status=0 should be omitted, got: {out}";
}

test "single-node error with no cause edge serializes cleanly" {
    # An error with no outgoing CausedBy edge must produce one record and
    # not blow up when the walker tries to follow a missing edge.
    solo = SLDApiError(
        name="SLDApiError",
        message="standalone failure",
        code="BOOM",
        status_code=500,
        details={"k": "v"},
    );
    root ++> solo;

    ser = ErrorSerializer();
    res = root spawn ser;
    assert len(res.out) == 1, f"expected 1 record, got {len(res.out)}";

    (lvl, rec) = res.out[0];
    assert lvl == 0, f"depth should be 0, got {lvl}";
    assert rec["name"] == "SLDApiError", f"name: {rec['name']}";
    assert rec["code"] == "BOOM", f"code: {rec['code']}";
    assert rec["statusCode"] == 500, f"statusCode: {rec['statusCode']}";
    assert rec["details"] == {"k": "v"}, f"details: {rec['details']}";
    assert rec["cause"] is None, f"cause should be None, got {rec['cause']}";
}

test "cycle guard prevents infinite traversal on back-edge" {
    a = SLDApiError(
        name="SLDApiError",
        message="a",
        code="A",
        status_code=400,
        details={},
    );
    b = SLDApiError(
        name="SLDApiError",
        message="b",
        code="B",
        status_code=400,
        details={},
    );
    # a -> b -> a (cycle).
    a +>:CausedBy:+> b;
    b +>:CausedBy:+> a;

    root ++> a;
    ser = ErrorSerializer();
    res = root spawn ser;

    # Each of the 2 nodes should appear exactly once despite the cycle.
    assert len(res.out) == 2, f"cycle must not duplicate records, got {len(res.out)}";

    names = [r[1]["name"] for r in res.out];
    codes = [r[1]["code"] for r in res.out];
    assert "A" in codes, f"missing A in {codes}";
    assert "B" in codes, f"missing B in {codes}";
    assert len(set(codes)) == 2, f"codes should be unique, got {codes}";
}

