    assert len(auditor.hits) == 0, f"expected no hits on clean dep, got {auditor.hits}";
    assert "CVE-2022-39353" not in out, f"unrelated CVE leaked into output: {out}";
    assert "Release @xmldom/xmldom@0.8.4 -- checking CVEs" in out, f"expected release inspection line: {out}";
}

test "depends_on edge direction and affects edge direction are correct" {
    root ++> Project(name="SRM-Test-DEV/test-56");
    app = [root -->][?:Project][0];

    r1 = Release(version="0.6.0", package="xmldom");
    r2 = Release(version="0.8.4", package="@xmldom/xmldom");
    app +>:DependsOn:+> r1;
    app +>:DependsOn:+> r2;

    cve1 = Vulnerability(
        cve_id="CVE-2021-32796", severity="MEDIUM", score=5.3,
        summary="escape flaw", alert_id="15daa12a-21fb-42e7-9b19-ee8490e8c788"
