        summary="multi-root parser", alert_id="fb6e2875-4db3-4092-89f6-1f0c23ec4399"
    );
    r1 +>:Affects:+> cve1;
    r2 +>:Affects:+> cve2;

    # Direction sanity: project points AT releases, releases point AT vulns.
    assert r1 in [app ->:DependsOn:->], "DependsOn edge must point Project -> Release";
    assert r2 in [app ->:DependsOn:->], "DependsOn edge must point Project -> Release";
    assert cve1 in [r1 ->:Affects:->], "Affects edge must point Release -> Vulnerability";
    assert cve2 in [r2 ->:Affects:->], "Affects edge must point Release -> Vulnerability";

