"""Regression tests for the MCP cold-start deadline race demo."""

import io;
import from contextlib { redirect_stdout }

test "server inside deadline reports backend-ready" {
    root ++> Desktop(host_name="ClaudeDesktop", init_deadline_s=60);
    d = [root -->][0];
    s = McpServer(title="weather", launcher_cmd="uvx weather-mcp", deps="httpx");
    d +>:Configured(config_key="weather"):+> s;
    l = Launcher(runner="uvx", cold_start_s=20, downloaded=True);
    s +>:RunsVia:+> l;
    b = Backend(process_name="weather-mcp", tools_exposed=4, reachable=True);
    l +>:Spawns(pid=4101):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        d spawn DeadlineRacer(deadline_s=60);
    }
    out = buf.getvalue();
    assert "[weather] backend ready in 20s" in out, f"expected warm-start line, got: {out}";
    assert s.deadline_hit is False, f"warm server should not be marked deadline_hit, got {s.deadline_hit}";
    assert s.stage_reached == "backend-ready", f"expected backend-ready, got {s.stage_reached}";
}

test "server over budget is cancelled during download and orphaned" {
    root ++> Desktop(host_name="ClaudeDesktop", init_deadline_s=60);
    d = [root -->][0];
    s = McpServer(title="opensearch", launcher_cmd="uvx opensearch-mcp-server-py", deps="botocore,boto3");
    d +>:Configured(config_key="opensearch"):+> s;
    l = Launcher(runner="uvx", cold_start_s=110, downloaded=True);
    s +>:RunsVia:+> l;
    b = Backend(process_name="opensearch-mcp-server-py", tools_exposed=7, reachable=True);
    l +>:Spawns(pid=4102):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        d spawn DeadlineRacer(deadline_s=60);
    }
    out = buf.getvalue();
    assert "cancelled at 60s while uvx was resolving botocore,boto3" in out, f"expected cancellation line, got: {out}";
    assert s.deadline_hit is True, f"over-budget server must be flagged, got {s.deadline_hit}";
    assert s.stage_reached == "downloading", f"expected stage=downloading, got {s.stage_reached}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        d spawn LateAttacher();
    }
    out2 = buf2.getvalue();
    assert "[orphan] opensearch" in out2, f"expected orphan line, got: {out2}";
    assert "7 tools but unreachable" in out2, f"expected tool count + unreachable, got: {out2}";
    assert b.reachable is False, f"LateAttacher must mark backend unreachable, got {b.reachable}";
}

test "configured server with no launcher fails closed" {
    root ++> Desktop(host_name="ClaudeDesktop", init_deadline_s=60);
    d = [root -->][0];
    s = McpServer(title="metrics", launcher_cmd="uvx metrics-mcp", deps="numpy,scipy");
    d +>:Configured(config_key="metrics"):+> s;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        d spawn DeadlineRacer(deadline_s=60);
    }
    out = buf.getvalue();
    assert "[metrics] no launcher configured" in out, f"expected no-launcher line, got: {out}";
    assert s.deadline_hit is True, f"missing launcher must fail closed, got {s.deadline_hit}";
    assert s.stage_reached == "no-launcher", f"expected no-launcher stage, got {s.stage_reached}";
    assert len([s->:RunsVia:->]) == 0, "no RunsVia edge should exist when launcher absent";
}

test "configurable deadline rescues an over-budget cold start" {
    root ++> Desktop(host_name="ClaudeDesktop", init_deadline_s=60);
    d = [root -->][0];
    s = McpServer(title="opensearch", launcher_cmd="uvx opensearch-mcp-server-py", deps="botocore,boto3");
    d +>:Configured(config_key="opensearch"):+> s;
    l = Launcher(runner="uvx", cold_start_s=110, downloaded=True);
    s +>:RunsVia:+> l;
    b = Backend(process_name="opensearch-mcp-server-py", tools_exposed=7, reachable=True);
    l +>:Spawns(pid=4102):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        d spawn DeadlineRacer(deadline_s=120);
    }
    out = buf.getvalue();
    assert "backend ready in 110s" in out, f"raised deadline should rescue server, got: {out}";
    assert s.deadline_hit is False, f"raised deadline must clear deadline_hit, got {s.deadline_hit}";
    assert s.stage_reached == "backend-ready", f"expected backend-ready under raised deadline, got {s.stage_reached}";
}

