"""Gw1n2 chipdb pipeline: vendor .fse data feeds a chipdb builder, which feeds
gowin_unpack, which feeds pluribus analysis. A walker audits which checklist
milestones are cleared given the current chipdb + decode state."""

node VendorFile {
    has name: str = "";
    has kind: str = "";
    has complete: bool = False;
}

node Chipdb {
    has part: str = "";
    has idcode: str = "";
    has tiles: int = 0;
    has luts: int = 0;
    has ffs: int = 0;
    has bsram: int = 0;
    has io_mapping_done: bool = False;
    has parser_complete: bool = False;
}

node Bitstream {
    has name: str = "";
    has crc_ok: bool = False;
    has unpacked: bool = False;
}

node Milestone {
    has label: str = "";
    has cleared: bool = False;
    has notes: str = "";
}

edge Feeds { }
edge UnpacksTo { }
edge Advances { }

walker PipelineAuditor {
    can start with Root entry {
        print(f"Auditing GW1N-2 pipeline status...");
        visit [-->];
    }

    can inspect with VendorFile | Chipdb | Bitstream | Milestone entry {
        cleared_count = 0;
        visit [-->];
    }

    can count_vendor with VendorFile entry {
        tag = "COMPLETE" if here.complete else "PARTIAL";
        print(f"  vendor file {here.name} ({here.kind}): {tag}");
        visit [-->];
    }

    can count_chip with Chipdb entry {
        parser_tag = "parser-ok" if here.parser_complete else "parser-WIP";
        io_tag = "io-mapped" if here.io_mapping_done else "io-unmapped";
        print(f"  chipdb {here.part} idcode={here.idcode} "
              f"tiles={here.tiles} lut4={here.luts} ff={here.ffs} "
              f"bsram={here.bsram} [{io_tag}, {parser_tag}]");
        visit [-->];
    }

    can count_bits with Bitstream entry {
        crc_tag = "crc-ok" if here.crc_ok else "crc-bad";
        up_tag = "unpacked" if here.unpacked else "blocked";
        print(f"  bitstream {here.name}: {crc_tag}, {up_tag}");
        visit [-->];
    }

    can count_miles with Milestone entry {
        ms_tag = "CLEARED" if here.cleared else "OPEN";
        print(f"  milestone [{ms_tag}] {here.label} -- {here.notes}");
        visit [-->];
    }
}

walker CascadeClear {
    has cleared_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with Milestone entry {
        if here.cleared {
            self.cleared_count += 1;
        }
        visit [-->];
    }
}

with entry {
    fse = VendorFile(name="GW1N-2.fse", kind="config-bit-db", complete=True);
    dat = VendorFile(name="GW1N-2.dat", kind="io-config", complete=True);
    tm = VendorFile(name="GW1N-2.tm", kind="tile-map", complete=True);

    chip = Chipdb(
        part="GW1N-2",
        idcode="0x0120681B",
        tiles=317,
        luts=847,
        ffs=1416,
        bsram=4,
        io_mapping_done=True,
        parser_complete=False
    );

    scope = Bitstream(name="scope.fs", crc_ok=True, unpacked=True);

    m1 = Milestone(label="grid/IO", cleared=True, notes="vendor .dat diffed against GW1N-9C");
    m2 = Milestone(label="LUT/DFF", cleared=True, notes="847 LUT4 / 1416 FF recovered");
    m3 = Milestone(label="BRAM/PLL", cleared=True, notes="4 BSRAM, CRC verified");
    m4 = Milestone(label="gowin_unpack on validation bitstream", cleared=True, notes="scope.fs decoded");
    m6 = Milestone(label="parser-complete", cleared=False, notes="apicula still parsing IO codes");

    fse +>:Feeds:+> chip;
    dat +>:Feeds:+> chip;
    tm +>:Feeds:+> chip;
    chip +>:UnpacksTo:+> scope;

    root ++> fse;
    root ++> dat;
    root ++> tm;
    root ++> chip;
    root ++> scope;
    root ++> m1;
    root ++> m2;
    root ++> m3;
    root ++> m4;
    root ++> m6;

    root spawn PipelineAuditor();

    cascade = CascadeClear();
    root spawn cascade;
    print(f"\nCleared milestones: {cascade.cleared_count} of 5");
}
```

