"""Tests for the V9 bench gate demo: per-run ontology, multi-renderer
rendering of one latent state, recursive query-program descent, and
cycle detection on repeated program visits."""

import io;
import from contextlib { redirect_stdout }

test "multi-renderer projection covers all renderer kinds" {
    root ++> LatentState(world_id="run-A", description="latent A");
    bench = [root -->][?:LatentState][0];
    onto = OntologyDef(name="ont-A", entity_types="user,device,session,plan", depth=3);
    conv = RenderRecord(text="hey i switched plans", renderer_kind="chat", is_critical=True);
    doc = RenderRecord(text="account ledger row 7", renderer_kind="ledger", is_critical=False);
    email = RenderRecord(text="from support: confirm device swap", renderer_kind="email", is_critical=True);
    bench +>:RenderedAs(renderer="chat"):+> conv;
    bench +>:RenderedAs(renderer="ledger"):+> doc;
    bench +>:RenderedAs(renderer="email"):+> email;
    bench +>:HasOntology(version="v9"):+> onto;

    records = [bench ->:RenderedAs:->];
    assert len(records) == 3, f"expected 3 renderers, got {len(records)}";

    kinds = sorted([r.renderer_kind for r in records]);
    assert kinds == ["chat", "email", "ledger"], f"renderer kinds: {kinds}";

    critical = [r for r in records if r.is_critical];
    assert len(critical) == 2, f"expected 2 critical records, got {len(critical)}";

    assert onto in [bench ->:HasOntology:->], "ontology edge must point from latent state to OntologyDef";
    assert onto.depth == 3, f"ontology depth: {onto.depth}";
}

test "audit walker reports latent, ontology, and critical records in order" {
    root ++> LatentState(world_id="run-B", description="user owns device");
    bench = [root -->][?:LatentState][0];
    onto = OntologyDef(name="ont-B", entity_types="acct,device", depth=2);
    conv = RenderRecord(text="chat line", renderer_kind="chat", is_critical=True);
    info = RenderRecord(text="ledger note", renderer_kind="ledger", is_critical=False);
    bench +>:RenderedAs(renderer="chat"):+> conv;
    bench +>:RenderedAs(renderer="ledger"):+> info;
    bench +>:HasOntology(version="v9"):+> onto;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
    }
    out = buf.getvalue();

    assert "[latent] run-B" in out, f"missing latent line: {out}";
    assert "[ontology] ont-B" in out, f"missing ontology line: {out}";
    assert "CRIT" in out, f"missing CRIT marker: {out}";
    assert "renderer=chat" in out, f"missing chat renderer: {out}";
    assert "renderer=ledger" in out, f"missing ledger renderer: {out}";

    assert res.cycle_detected is False, "no cycle on a tree-shaped query program";
}

test "query program recursion reports each depth and respects parent label" {
    root ++> LatentState(world_id="run-C", description="x");
    bench = [root -->][?:LatentState][0];
    q1 = QueryProgram(operations="join", depth=1, parent_op="root");
    q2 = QueryProgram(operations="time", depth=2, parent_op="join");
    q3 = QueryProgram(operations="aggregate", depth=3, parent_op="time");
    q1 +>:Decomposes(label="then"):+> q2;
    q2 +>:Decomposes(label="then"):+> q3;
    root ++> q1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
    }
    out = buf.getvalue();

    assert "[query] join@1" in out, f"missing join@1: {out}";
    assert "[query] time@2" in out, f"missing time@2: {out}";
    assert "[query] aggregate@3" in out, f"missing aggregate@3: {out}";
    assert "parent=root" in out, f"missing parent=root: {out}";
    assert "parent=join" in out, f"missing parent=join: {out}";
    assert "parent=time" in out, f"missing parent=time: {out}";

    visited = sorted(res.visited_programs);
    assert visited == ["aggregate@3", "join@1", "time@2"], f"visited order: {visited}";
    assert res.cycle_detected is False, f"unexpected cycle: {visited}";

    children = [q1 ->:Decomposes:->];
    assert len(children) == 1, f"expected one child of q1, got {len(children)}";
    assert children[0] is q2, "Decomposes edge from q1 must target q2";
}

test "cycle in query program is detected and traversal halts" {
    root ++> LatentState(world_id="run-D", description="cycle");
    q1 = QueryProgram(operations="join", depth=1, parent_op="root");
    q2 = QueryProgram(operations="time", depth=2, parent_op="join");
    q1 +>:Decomposes(label="then"):+> q2;
    q2 +>:Decomposes(label="loop"):+> q1;
    root ++> q1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
    }
    out = buf.getvalue();

    assert res.cycle_detected is True, f"cycle_detected should be True, got {res.cycle_detected}; visited={res.visited_programs}";
    assert "[cycle]" in out, f"missing cycle marker: {out}";
    assert "join@1" in res.visited_programs, f"join@1 must be visited first: {res.visited_programs}";

    q1_seen = sum(1 for p in res.visited_programs if p == "join@1");
    assert q1_seen == 1, f"join@1 should appear once before disengage, got {q1_seen}: {res.visited_programs}";
}

test "ontology cascade does not affect unrelated latent state nodes" {
    a = LatentState(world_id="run-E1", description="state one");
    b = LatentState(world_id="run-E2", description="state two");
    onto_a = OntologyDef(name="ont-E1", entity_types="user,device", depth=2);
    onto_b = OntologyDef(name="ont-E2", entity_types="account,plan,line", depth=4);
    a +>:HasOntology(version="v9"):+> onto_a;
    b +>:HasOntology(version="v9"):+> onto_b;
    root ++> a;
    root ++> b;

    assert onto_a.depth == 2, f"onto_a depth: {onto_a.depth}";
    assert onto_b.depth == 4, f"onto_b depth: {onto_b.depth}";

    onto_for_a = [a ->:HasOntology:->];
    onto_for_b = [b ->:HasOntology:->];
    assert len(onto_for_a) == 1 and onto_for_a[0] is onto_a, "a must point to onto_a";
    assert len(onto_for_b) == 1 and onto_for_b[0] is onto_b, "b must point to onto_b";

    latent_nodes = [root -->][?:LatentState];
    assert len(latent_nodes) == 2, f"expected 2 latent nodes, got {len(latent_nodes)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
    }
    out = buf.getvalue();

    assert "ont-E1 types=user,device depth=2" in out, f"missing ont-E1 line: {out}";
    assert "ont-E2 types=account,plan,line depth=4" in out, f"missing ont-E2 line: {out}";
    assert res.cycle_detected is False, "no cycles in this graph";
}

