"""Test annex for comment-moderation graph program (issue #317).

Spawns the program's AuditTrail and Moderator walkers against freshly built
graphs (per-test isolation) and asserts the behaviors the issue specifies:
immutable original body, append-only moderation history, role-hierarchy
authorization, stale-version conflict detection, and reason requirement for
delete (but not restore).
"""

import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------

def fresh_comment_pair() -> tuple {
    a = Author(display_name="alice", role="User");
    c = Comment(body="Original immutable body.", created_at="t0", is_deleted=False);
    a +>:Authored:+> c;
    return (a, c);
}

# ---------- tests ----------

test "delete with correct version appends event and flips state" {
    (a, c) = fresh_comment_pair();
    mod = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    c spawn mod;
    assert mod.applied, f"delete should apply, got conflict={mod.conflict}";
    assert mod.conflict == "", f"unexpected conflict: {mod.conflict}";
    assert c.is_deleted == True, "Comment.is_deleted must be True after delete";

    events = [c ->:Moderated:->];
    assert len(events) == 1, f"expected 1 moderation event, got {len(events)}";
    e = events[0];
    assert e.action == "delete", f"event action={e.action}";
    assert e.actor == "bob", f"event actor={e.actor}";
    assert e.reason == "spam", f"delete reason must be preserved, got {e.reason!r}";
    assert e.expected_version == 0, f"event expected_version={e.expected_version}";
}

test "restore does not require a reason and reactivates comment" {
    (a, c) = fresh_comment_pair();
    # first delete it so we have a baseline
    first = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    c spawn first;
    assert first.applied, "baseline delete must succeed";

    # restore with empty reason and version=1 (one prior event)
    rest = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="restore",
        reason="",
        expected_version=1,
        target_author_role="User"
    );
    c spawn rest;
    assert rest.applied, f"restore must succeed, conflict={rest.conflict}";
    assert rest.conflict == "", f"unexpected conflict: {rest.conflict}";
    assert c.is_deleted == False, "restored comment must be active again";

    events = [c ->:Moderated:->];
    assert len(events) == 2, f"expected 2 events (delete + restore), got {len(events)}";
    last = events[-1];
    assert last.action == "restore", f"last action={last.action}";
    assert last.actor == "bob", f"restoring actor={last.actor}";
    assert last.reason == "", f"restore must not carry a reason, got {last.reason!r}";
}

test "delete without reason is rejected and produces no event" {
    (a, c) = fresh_comment_pair();
    mod = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="",
        expected_version=0,
        target_author_role="User"
    );
    c spawn mod;
    assert mod.applied == False, "delete without reason must not apply";
    assert mod.conflict == "reason_required", f"got conflict={mod.conflict!r}";
    assert c.is_deleted == False, "comment must remain active when delete rejected";
    events = [c ->:Moderated:->];
    assert len(events) == 0, f"no event may be appended on rejection, got {len(events)}";
}

test "stale expected version yields typed conflict and no new event" {
    (a, c) = fresh_comment_pair();
    # baseline: one successful delete -> version moves to 1
    base = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    c spawn base;
    assert base.applied, "baseline delete must succeed";

    # second delete still claims expected_version=0 -> stale
    stale = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="dup",
        expected_version=0,
        target_author_role="User"
    );
    c spawn stale;
    assert stale.applied == False, "stale-version delete must not apply";
    assert stale.conflict == "stale_version", f"got conflict={stale.conflict!r}";
    events = [c ->:Moderated:->];
    assert len(events) == 1, f"stale action must NOT append a new event, got {len(events)}";
}

test "admin cannot moderate super-admin comment; super-admin can" {
    carol = Author(display_name="carol", role="SuperAdmin");
    super_post = Comment(body="super-only content", created_at="t2", is_deleted=False);
    carol +>:Authored:+> super_post;

    # admin -> super-admin: forbidden, no event, no state change
    forbidden = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="x",
        expected_version=0,
        target_author_role="SuperAdmin"
    );
    super_post spawn forbidden;
    assert forbidden.applied == False, "admin must not moderate super-admin";
    assert forbidden.conflict == "forbidden", f"got {forbidden.conflict!r}";
    assert super_post.is_deleted == False, "comment must remain untouched";
    events = [super_post ->:Moderated:->];
    assert len(events) == 0, "forbidden action must not append any event";

    # super-admin -> super-admin: allowed (highest role)
    allowed = Moderator(
        actor_name="carol",
        actor_role="SuperAdmin",
        action="delete",
        reason="self-moderation",
        expected_version=0,
        target_author_role="SuperAdmin"
    );
    super_post spawn allowed;
    assert allowed.applied, f"super-admin must be able to moderate super-admin, conflict={allowed.conflict}";
    assert super_post.is_deleted == True, "comment must be deleted after super-admin action";
}

test "AuditTrail preserves original body and derives final state from history" {
    (a, c) = fresh_comment_pair();
    # delete then restore -> derived state should end "active"
    d = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    c spawn d;
    assert d.applied, "baseline delete must succeed";

    r = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="restore",
        reason="",
        expected_version=1,
        target_author_role="User"
    );
    c spawn r;
    assert r.applied, "restore must succeed";

    audit = AuditTrail();
    c spawn audit;
    assert audit.comment_body == "Original immutable body.", (
        f"audit must surface ORIGINAL body immutably, got {audit.comment_body!r}"
    );
    assert audit.current_state == "active", (
        f"derived state after delete+restore must be active, got {audit.current_state!r}"
    );
    assert audit.version == 2, f"audit must count 2 events, got {audit.version}";
}

test "deleting a parent never touches its descendants (no cascade)" {
    parent_author = Author(display_name="alice", role="User");
    parent = Comment(body="parent body", created_at="t0", is_deleted=False);
    child  = Comment(body="child body",  created_at="t1", is_deleted=False);
    parent_author +>:Authored:+> parent;
    parent +>:RepliedTo:+> child;

    mod = Moderator(
        actor_name="bob",
        actor_role="Admin",
        action="delete",
        reason="spam",
        expected_version=0,
        target_author_role="User"
    );
    parent spawn mod;
    assert mod.applied, "parent delete must succeed";
    assert parent.is_deleted == True, "parent must be marked deleted";
    assert child.is_deleted == False, "child must NOT cascade-delete";
    # child node must still exist in the graph
    children = [parent ->:RepliedTo:->];
    assert len(children) == 1, "reply edge must be preserved on parent delete";
    assert children[0] == child, "child identity must be preserved";
}

