"""Tests for the sandbox runaway Bash chain model."""

import io;
import from contextlib { redirect_stdout }

test "cap stops traversal when depth reaches limit" {
    root ++> ShellInvocation(command="render_hostname", env_stripped=True);
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(scope_path="/s.slice/x.scope", pids_max=32, current_tasks=2, frozen=False);
    inv +>:RanIn(start_ts=1):+> scope;

    scope +>:Spawned(at_depth=0):+> BashProcess(pid=2001, cmdline="bash -c 'x'", depth=0, exited_normally=False);
    scope +>:Spawned(at_depth=1):+> BashProcess(pid=2002, cmdline="bash -c 'x'", depth=1, exited_normally=False);
    scope +>:Spawned(at_depth=2):+> BashProcess(pid=2003, cmdline="bash -c 'x'", depth=2, exited_normally=False);
    scope +>:Spawned(at_depth=3):+> BashProcess(pid=2004, cmdline="bash -c 'x'", depth=3, exited_normally=False);

    res = inv spawn Sandbox(cap=2);
    assert res.chain_length == 3, f"expected chain_length=3, got {res.chain_length}";
    assert res.runaway_detected is True, f"runaway should be detected when depth>=cap, got {res.runaway_detected}";
}

test "runaway is flagged for any non-exited bash process" {
    root ++> ShellInvocation(command="render_hostname", env_stripped=True);
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(scope_path="/s.slice/y.scope", pids_max=32, current_tasks=1, frozen=False);
    inv +>:RanIn(start_ts=1):+> scope;

    scope +>:Spawned(at_depth=0):+> BashProcess(pid=3001, cmdline="bash -c 'render_hostname'", depth=0, exited_normally=False);

    res = inv spawn Sandbox(cap=16);
    assert res.runaway_detected is True, f"single non-exited bash must flag runaway, got {res.runaway_detected}";
    assert res.chain_length == 1, f"expected chain_length=1, got {res.chain_length}";
}

test "healthy exit with single normally-exited bash reports no runaway" {
    root ++> ShellInvocation(command="echo ok", env_stripped=False, expected_output="ok");
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(scope_path="/s.slice/z.scope", pids_max=32, current_tasks=1, frozen=False);
    inv +>:RanIn(start_ts=2):+> scope;

    scope +>:Spawned(at_depth=0):+> BashProcess(pid=4001, cmdline="bash -c 'echo ok'", depth=0, exited_normally=True);

    res = inv spawn Sandbox(cap=16);
    assert res.runaway_detected is False, f"healthy exit must not flag runaway, got {res.runaway_detected}";
    assert res.chain_length == 1, f"expected chain_length=1, got {res.chain_length}";
    assert "frozen_scope" not in res.summary, f"frozen_scope should be absent, got {res.summary}";
    assert "over_cap_scope" not in res.summary, f"over_cap_scope should be absent, got {res.summary}";
}

test "frozen cgroup scope is detected and named in summary" {
    root ++> ShellInvocation(command="render_hostname", env_stripped=True);
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(
        scope_path="/user.slice/.../app-org.chromium.Chromium-9.scope",
        pids_max=32, current_tasks=6144, frozen=True
    );
    inv +>:RanIn(start_ts=3):+> scope;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = inv spawn Sandbox(cap=32);
    }
    out = buf.getvalue();
    assert res.summary.get("frozen_scope") == scope.scope_path, f"expected frozen_scope marker, got {res.summary}";
    assert res.runaway_detected is True, f"frozen scope must trip runaway flag, got {res.runaway_detected}";
    assert "[SCOPE]" in out and "frozen=True" in out, f"missing SCOPE print: {out}";
    assert "[INVOKE]" in out, f"missing INVOKE print: {out}";
}

test "over-cap scope trips runaway even if not frozen" {
    root ++> ShellInvocation(command="render_hostname", env_stripped=True);
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(
        scope_path="/s.slice/over.scope", pids_max=32, current_tasks=64, frozen=False
    );
    inv +>:RanIn(start_ts=4):+> scope;

    res = inv spawn Sandbox(cap=16);
    assert res.summary.get("over_cap_scope") == scope.scope_path, f"expected over_cap_scope, got {res.summary}";
    assert res.runaway_detected is True, f"over-cap must trip runaway, got {res.runaway_detected}";
    assert res.chain_length == 0, f"no bash procs in this graph, got chain_length={res.chain_length}";
}

