"""Root Vex Operations: Windows-VexLife scope walker traversing the capability lineage."""

node Capability {
    has title: str = "";
    has acceptance_state: str = "";
}

node CompletionGroup {
    has code: str = "";
    has description: str = "";
}

node Scope {
    has name: str = "";
    has completion_state: str = "";
    has target: str = "";
}

edge GroupContains { }
edge DependsOn { }
edge Supervises { }

walker CapabilityAuditor {
    has visited_titles: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Scope entry {
        print(f"Scope: {here.name}");
        print(f"  state = {here.completion_state}");
        print(f"  target = {here.target}");
        visit [->:GroupContains:->];
    }

    can audit_group with CompletionGroup entry {
        print(f"  Group {here.code}: {here.description}");
        visit [->:GroupContains:->];
    }

    can audit_cap with Capability entry {
        if here.title in self.visited_titles {
            self.cycle_detected = True;
            print(f"  [CYCLE] already saw {here.title}");
            disengage;
        }
        self.visited_titles.append(here.title);
        status_label = "ACCEPTED" if here.acceptance_state == "accepted" else "PENDING";
        print(f"    [{status_label}] {here.title}");
        visit [->:DependsOn:->];
    }
}

with entry {
    blueprint = Capability(title="universal Blueprint foundation", acceptance_state="accepted");
    intent = Capability(title="Intent and Workgraph contracts", acceptance_state="accepted");
    scheduler = Capability(title="single-worker scheduler and lease admission", acceptance_state="accepted");
    recovery = Capability(title="Runtime Failure and Recovery", acceptance_state="accepted");
    continuity = Capability(title="Continuity Evolution and Burden Release", acceptance_state="accepted");
    concern = Capability(title="ConcernWatch", acceptance_state="accepted");
    admission = Capability(title="Build Admission Coverage", acceptance_state="accepted");

    dream = Capability(title="Daily Memory-only Dream", acceptance_state="pending");
    rhythm = Capability(title="Evaluated Rhythm Learning", acceptance_state="pending");
    autonomy = Capability(title="Scheduled Daily Autonomy and Bounded Sync", acceptance_state="pending");

    dream +>:DependsOn:+> recovery;
    dream +>:DependsOn:+> continuity;
    rhythm +>:DependsOn:+> dream;
    autonomy +>:DependsOn:+> rhythm;
    autonomy +>:DependsOn:+> concern;

    g01 = CompletionGroup(code="G01", description="LIVED_COMPANION_BASELINE");
    g02 = CompletionGroup(code="G02", description="SCORE_AND_CONTEXT_CONTINUITY");
