"""Test annex for the SearchIndex symlink-cycle fix (issue #259)."""

import io;
import from contextlib { redirect_stdout }

test "symlink cycle is detected and skipped" {
    root_dir = Dir(name="/workspace", canonical="/workspace", depth=0);
    src = Dir(name="src", canonical="/workspace/src", depth=1);
    loop = Dir(name="loop", canonical="/workspace/src/loop", depth=2);
    # back-edge: loop -> /workspace (canonical already seen as root_dir)
    root ++> root_dir;
    root_dir ++> src;
    src ++> loop;
    loop ++> root_dir;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        builder = IndexBuilder();
        root spawn builder;
    }
    out = buf.getvalue();

    # The cycle back-edge from `loop` to root_dir is hit on the second pass;
    # the visited guard must print a skip-cycle marker instead of re-indexing.
    assert "[skip cycle]" in out, f"no cycle-skip marker printed: {out}";
    assert "/workspace" in out, f"root_dir should be flagged as cycle target: {out}";

    # root_dir must appear in indexed output exactly once — not twice.
    assert out.count("[index] /workspace") == 1, (
        f"root_dir re-indexed under symlink cycle: {out}"
    );
}

test "deep nesting is bounded by the max_depth cap" {
    root_dir = Dir(name="/workspace", canonical="/workspace", depth=0);
    # build a 40-deep linear chain; max_depth defaults to 32
    cur = root_dir;
    parent = root;
    parent ++> cur;
    for i in range(1, 41) {
        child = Dir(name=f"d{i}", canonical=f"/workspace/d{i}", depth=i);
        cur ++> child;
        cur = child;
    }

    buf = io.StringIO();
    with redirect_stdout(buf) {
        builder = IndexBuilder();
        root spawn builder;
    }
    out = buf.getvalue();

    # The depth cap must fire on at least one node past depth 32.
    assert "[depth cap]" in out, f"depth cap never triggered: {out}";
    # d40 is depth 40, well past the cap; it must not be indexed.
    assert "[index] d40" not in out, f"d40 should be depth-capped: {out}";
    # d32 sits exactly at the cap and must still be indexed (cap is strict >).
    assert "[index] d32" in out, f"d32 (depth==cap) should be indexed: {out}";
}

test "dag with no cycles indexes every dir exactly once" {
    root_dir = Dir(name="/workspace", canonical="/workspace", depth=0);
    src = Dir(name="src", canonical="/workspace/src", depth=1);
    docs = Dir(name="docs", canonical="/workspace/docs", depth=1);
    loop = Dir(name="loop", canonical="/workspace/src/loop", depth=2);

    root ++> root_dir;
    root_dir ++> src;
    root_dir ++> docs;
    src ++> loop;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        builder = IndexBuilder();
        root spawn builder;
    }
    out = buf.getvalue();

    # No cycles here — no skip markers, no depth caps.
    assert "[skip cycle]" not in out, f"false cycle skip on a DAG: {out}";
    assert "[depth cap]" not in out, f"false depth cap on a shallow DAG: {out}";
    # Every node is indexed exactly once.
    for nm in ["/workspace", "src", "docs", "loop"] {
        assert out.count(f"[index] {nm}") == 1, (
            f"{nm} should be indexed exactly once; output:\n{out}"
        );
    }
    assert len(builder.indexed) == 4, (
        f"expected 4 dirs indexed, got {len(builder.indexed)}"
    );
    assert len(builder.visited) == 4, (
        f"expected 4 canonical paths tracked, got {len(builder.visited)}"
    );
}

test "visited guard also rejects siblings sharing canonical path" {
    # Two distinct Dir nodes with the SAME canonical path model a symlink
    # that points into an already-indexed directory. The visited guard keys
    # on `canonical`, not on object identity, so the second one must skip.
    root_dir = Dir(name="/workspace", canonical="/workspace", depth=0);
    alias = Dir(name="alias", canonical="/workspace", depth=1);
    root ++> root_dir;
    root_dir ++> alias;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        builder = IndexBuilder();
        root spawn builder;
    }
    out = buf.getvalue();

    assert "[skip cycle]" in out, f"alias not skipped on shared canonical: {out}";
    assert out.count("[index] /workspace") == 1, (
        f"shared canonical path re-indexed: {out}"
    );
    # visited must record the canonical path only once even though two Dir
    # nodes pointed at it.
    assert builder.visited.count("/workspace") == 1, (
        f"canonical path recorded twice: {builder.visited}"
    );
}

