import io;
import from contextlib { redirect_stdout }

test "is_a closure excludes foreign ontology by default" {
    anchor = Term(id="GO:0005575", label="cellular_component", ontology="GO");
    go_child = Term(id="GO:0005737", label="cytoplasm", ontology="GO");
    foreign = Term(id="MRO:0000001", label="MHC class I region", ontology="MRO");
    root ++> anchor;
    anchor +>:IsA:+> go_child;
    anchor +>:IsA:+> foreign;
    res = root spawn DescendantClosure(
        anchor_id="GO:0005575",
        follow_part_of=False,
        allow_foreign=False,
    );
    assert len(res.guard) == 2, f"expected anchor+GO child, got {res.guard}";
    assert "MRO:0000001" not in res.guard, f"foreign term leaked: {res.guard}";
}

test "allow_foreign includes cross-ontology is_a descendants" {
    anchor = Term(id="GO:0005575", label="cellular_component", ontology="GO");
    go_child = Term(id="GO:0005737", label="cytoplasm", ontology="GO");
    foreign = Term(id="MRO:0000001", label="MHC class I region", ontology="MRO");
    root ++> anchor;
    anchor +>:IsA:+> go_child;
    anchor +>:IsA:+> foreign;
    res = root spawn DescendantClosure(
        anchor_id="GO:0005575",
        follow_part_of=False,
        allow_foreign=True,
