    anchor = Term(id="GO:0005575", label="cellular_component", ontology="GO");
    mid = Term(id="GO:0005737", label="cytoplasm", ontology="GO");
    part = Term(id="GO:0005829", label="cytosol", ontology="GO");
    root ++> anchor;
    anchor +>:IsA:+> mid;
    mid +>:PartOf:+> part;
    isa_only = root spawn DescendantClosure(
        anchor_id="GO:0005575",
