    assert len(isa_only.guard) == 2, f"is_a only expected 2, got {isa_only.guard}";
    assert len(with_part.guard) == 3, f"is_a+part_of expected 3, got {with_part.guard}";
    assert "GO:0005829" not in isa_only.guard, f"part_of term leaked without flag: {isa_only.guard}";
    assert "GO:0005829" in with_part.guard, f"part_of term missing with flag: {with_part.guard}";
}

test "missing anchor disengages with not found message" {
    other = Term(id="GO:0005737", label="cytoplasm", ontology="GO");
    root ++> other;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DescendantClosure(anchor_id="GO:0005575");
    }
    out = buf.getvalue();
    assert "not found" in out, f"missing error message: {out}";
    assert len(res.tally) == 0, f"expected empty tally, got {res.tally}";
    assert len(res.guard) == 0, f"expected empty guard, got {res.guard}";
}

test "repeated closure traversal yields same reachable set" {
    anchor = Term(id="GO:0005575", label="cellular_component", ontology="GO");
    child = Term(id="GO:0005737", label="cytoplasm", ontology="GO");
    root ++> anchor;
    anchor +>:IsA:+> child;
    cold = root spawn DescendantClosure(anchor_id="GO:0005575", follow_part_of=False);
    warm = root spawn DescendantClosure(anchor_id="GO:0005575", follow_part_of=False);
