"""ADWF Foundation traceability graph: walk Owner-Intent -> Requirement -> Decision
and prove every requirement is grounded in a live decision and a live intent,
mirroring the fail-closed semantics the programme demands.

Entities are node archetypes; the durable links between them are typed edges;
a walker performs the cascade verification that the issue's hand-rolled
machinery used to do with parent_id recursion and id-keyed registries.
"""

node Intent {
    has title: str = "";
    has status: str = "DRAFT";
}

node Requirement {
    has title: str = "";
    has priority: int = 0;
    has verified: bool = False;
}

node Decision {
    has title: str = "";
    has rationale: str = "";
    has adopted: bool = False;
}

edge Drives {
    has weight: int = 1;
}

edge Satisfies {
    has confidence: float = 1.0;
}

edge Invalidates {
    has reason: str = "";
}

walker TraceAuditor {
    has findings: list[str] = [];
    has visited: list[str] = [];
    has broken: bool = False;

    can start with Root entry {
        print("ADWF Foundation trace audit begins");
        visit [-->];
    }

    can audit_intent with Intent entry {
        tag = f"I[{here.title}/{here.status}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        self.findings.append(f"intent '{here.title}' status={here.status}");
        if here.status != "LIVE" {
            self.broken = True;
            self.findings.append(f"  -> intent '{here.title}' is not LIVE");
        }
        visit [->:Drives:->] else { disengage; }
    }

    can audit_requirement with Requirement entry {
        tag = f"R[{here.title}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        line = f"requirement '{here.title}' pri={here.priority} verified={here.verified}";
        self.findings.append(line);
        if not here.verified {
            self.broken = True;
            self.findings.append(f"  -> requirement '{here.title}' not verified");
        }
        visit [->:Satisfies:->] else { disengage; }
    }

    can audit_decision with Decision entry {
        tag = f"D[{here.title}]";
        if tag in self.visited {
            visit [-->] else { disengage; }
            return;
        }
        self.visited.append(tag);
        self.findings.append(f"decision '{here.title}' adopted={here.adopted}");
        if not here.adopted {
            self.broken = True;
            self.findings.append(f"  -> decision '{here.title}' not adopted");
        }
        visit [->:Invalidates:->] else { disengage; }
    }
}

with entry {
    i_lifecycle = Intent(title="ConsumerLifecycle", status="LIVE");
    i_trace = Intent(title="DecisionTraceability", status="LIVE");
    i_stale = Intent(title="StaleDiscovery", status="DRAFT");

    r_lifecycle = Requirement(title="RecoverOrDetach", priority=1, verified=True);
    r_evidence = Requirement(title="RealConsumerEvidence", priority=2, verified=True);
    r_trace = Requirement(title="GraphAppendOnly", priority=1, verified=True);
    r_unverified = Requirement(title="AdversarialAudit", priority=0, verified=False);

    d_merge = Decision(title="AdoptFailClosed", rationale="no live evidence -> no claim", adopted=True);
    d_skip = Decision(title="SkipAdversarialGate", rationale="premature", adopted=False);
    d_invalidate = Decision(title="InvalidateStaleDiscovery", rationale="superseded by v1.8", adopted=True);

    root ++> i_lifecycle
        ++> i_trace
        ++> i_stale
        ++> r_lifecycle
        ++> r_evidence
        ++> r_trace
        ++> r_unverified
        ++> d_merge
        ++> d_skip
        ++> d_invalidate;

    i_lifecycle +>:Drives(weight=3):+> r_lifecycle;
    i_lifecycle +>:Drives(weight=2):+> r_evidence;
    i_trace +>:Drives(weight=4):+> r_trace;
    i_stale +>:Drives(weight=1):+> r_unverified;

    r_lifecycle +>:Satisfies(confidence=0.95):+> d_merge;
    r_evidence +>:Satisfies(confidence=0.80):+> d_merge;
    r_trace +>:Satisfies(confidence=0.90):+> d_merge;
    r_unverified +>:Satisfies(confidence=0.10):+> d_skip;

    d_merge +>:Invalidates(reason="dethroned by later audit policy"):+> d_skip;
    d_merge +>:Invalidates(reason="stale draft, no owner intent LIVE"):+> d_invalidate;

    auditor = TraceAuditor();
    root spawn auditor;

    print("--- trace report ---");
    for line in auditor.findings {
        print(line);
    }
    print("--- summary ---");
    verdict = "FAIL_CLOSED" if auditor.broken else "PASS";
    print(f"trace audit verdict: {verdict}");
    print(f"nodes inspected: {len(auditor.visited)}");
}
```

jac_tests:
"""Tests for the ADWF Foundation TraceAuditor walker.

Each test builds its own graph and asserts the fail-closed semantics
the programme specifies: a requirement without `verified=True`, an
intent without `status="LIVE"`, or a decision without `adopted=True`
must flip the audit verdict to FAIL_CLOSED via the cascade walk
(Intent -> Requirement -> Decision and the Invalidates chain).
"""

import io;
import from contextlib { redirect_stdout }

def run_audit(rt) {
    auditor = TraceAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn auditor;
    }
    return (auditor, buf.getvalue(), res);
}

test "fully grounded chain yields PASS verdict" {
    rt = root;
    i = Intent(title="LiveIntent", status="LIVE");
    r = Requirement(title="GroundedReq", priority=2, verified=True);
    d = Decision(title="AdoptedDecision", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=3):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == False, f"expected PASS, got findings={auditor.findings}";
    assert "intent 'LiveIntent' status=LIVE" in auditor.findings;
    assert "requirement 'GroundedReq' pri=2 verified=True" in auditor.findings;
    assert "decision 'AdoptedDecision' adopted=True" in auditor.findings;
}

test "unverified requirement trips fail-closed verdict" {
    rt = root;
    i = Intent(title="LiveIntent", status="LIVE");
    r = Requirement(title="UnverifiedReq", priority=1, verified=False);
    d = Decision(title="AdoptedDecision", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=3):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == True, f"expected fail-closed, got findings={auditor.findings}";
    assert "  -> requirement 'UnverifiedReq' not verified" in auditor.findings;
}

test "draft intent propagates failure to dependent requirement" {
    rt = root;
    i = Intent(title="DraftIntent", status="DRAFT");
    r = Requirement(title="DepReq", priority=2, verified=True);
    d = Decision(title="AdoptedDecision", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=2):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == True, f"expected fail-closed, got findings={auditor.findings}";
    assert "intent 'DraftIntent' status=DRAFT" in auditor.findings;
    assert "  -> intent 'DraftIntent' is not LIVE" in auditor.findings;
}

test "unadopted decision is reported via Invalidates chain from adopted one" {
    rt = root;
    d_kept = Decision(title="Adopted", rationale="ok", adopted=True);
    d_killed = Decision(title="SkipGate", rationale="premature", adopted=False);

    rt ++> d_kept ++> d_killed;
    d_kept +>:Invalidates(reason="dethroned"):+> d_killed;

    (auditor, _out, res) = run_audit(rt);
    assert res.broken == True, f"expected fail-closed, got findings={auditor.findings}";
    assert "decision 'Adopted' adopted=True" in auditor.findings;
    assert "decision 'SkipGate' adopted=False" in auditor.findings;
    assert "  -> decision 'SkipGate' not adopted" in auditor.findings;
}

test "auditor visits each node exactly once per title tag" {
    rt = root;
    i = Intent(title="LiveIntent", status="LIVE");
    r = Requirement(title="Req", priority=1, verified=True);
    d = Decision(title="Adopted", rationale="ok", adopted=True);

    rt ++> i ++> r ++> d;
    i +>:Drives(weight=3):+> r;
    r +>:Satisfies(confidence=0.9):+> d;

    (auditor, _out, _res) = run_audit(rt);
    tags = auditor.visited;
    assert len(tags) == 3, f"expected 3 unique tags, got {tags}";
    assert "I[LiveIntent/LIVE]" in tags;
    assert "R[Req]" in tags;
    assert "D[Adopted]" in tags;
}

