        res = root spawn Safe(depth_cap=32);
    }
    out = buf.getvalue();

    assert "safe entry: bun-entry" in out, f"missing safe entry banner: {out!r}";
    assert "cycle short-circuit at" not in out, (
        f"acyclic graph must not produce cycle short-circuit: {out!r}"
    );
    assert "depth cap (32) reached, disengaging" not in out, (
        f"acyclic chain under cap must not hit cap: {out!r}"
    );
    assert res.frames_visited == 4, (
        f"safe walker should visit exactly the 4 chain frames, got {res.frames_visited}"
    );
    assert len(res.visited) == 4, (
        f"visited set should hold all 4 frame offsets, got {res.visited}"
    );
}

