    tag = AcceptanceTag(tag_name="acceptance-v0.8");
    t4 = Task(task_id="TASK-OPS-002", state="ready", required=True);
    t5 = Task(task_id="TASK-DOC-002", state="done", required=True);
    root +>:Governs:+> gate;
    gate +>:DependsOn:+> t4;
    t4 +>:DependsOn:+> t5;
    root ++> tag;
    assert t5 in [t4 ->:DependsOn:->], f"dependency chain t4->t5 missing";
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TagEnforcer();
    }
    out = buf.getvalue();
    assert "Final R0 verdict: DENY" in out, f"incomplete required task should DENY: {out}";
    assert "[BLOCK] required task TASK-OPS-002 not done" in out, f"missing task block: {out}";
    assert "NOT created" in out, f"tag must not be created: {out}";
    assert res.reports[0]["created"] == False, f"report created flag {res.reports[0]}";
