```jac
"""Program-aware support, reporting, and comms demo.

Models the core scenario from issue #1651: a Program node owns Mentee/Mentor
participants via typed edges, a SupportTicket is filed against a program and
carries priority/category/SLA fields, and a Newsletter issue freezes an
audience snapshot resolved over the program graph at send time. Walkers
traverse the graph natively instead of hand-rolled recursion.
"""

node Program {
    has name: str = "";
    has cohort: str = "";
}

node Mentee {
    has title: str = "";
    has stage: str = "applied";
    has tags: list[str] = [];
}

node Mentor {
    has title: str = "";
    has company: str = "";
}

node SupportTicket {
    has subject: str = "";
    has priority: str = "normal";
    has category: str = "general";
    has status: str = "open";
    has sla_minutes: int = 240;
    has search_terms: list[str] = [];
}

edge BelongsTo {
    has joined: str = "2026-01";
}

edge AssignedTo {
    has role: str = "requester";
}

edge FiledAgainst {
    has opened_at: str = "2026-03-01";
}

walker ProgramReporter {
    has program_name: str = "";
    has mentee_count: int = 0;
    has mentor_count: int = 0;
    has open_tickets: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can count_members with Program entry {
        self.program_name = here.name;
        visit [->:BelongsTo:->];
    }

    can tally with Mentee entry {
        self.mentee_count += 1;
        visit [-->];
    }

    can tally_m with Mentor entry {
        self.mentor_count += 1;
        visit [-->];
    }

    can count_tickets with SupportTicket entry {
        if here.status != "closed" {
            self.open_tickets += 1;
        }
        visit [-->];
    }
}

walker SupportQueueFilter {
    has program_name: str = "";
    has min_priority: str = "low";
    has category: str = "any";
    has search: str = "";
    has kept: list[SupportTicket] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_programs with Program entry {
        self.program_name = here.name;
        visit [->:FiledAgainst:->];
    }

    can scan_tickets with SupportTicket entry {
        rank = {"low": 0, "normal": 1, "high": 2, "urgent": 3};
        here_rank = rank.get(here.priority, 0);
        cutoff = rank.get(self.min_priority, 0);
        cat_ok = (self.category == "any") or (here.category == self.category);
        search_ok = (self.search == "");
        if not search_ok {
            for term in here.search_terms {
                if term == self.search {
                    search_ok = True;
                }
            }
        }
        if (here_rank >= cutoff) and cat_ok and search_ok {
            self.kept.append(here);
        }
        visit [-->];
    }
}

walker NewsletterSend {
    has program_name: str = "";
    has audience: str = "MENTEE";
    has frozen: list[str] = [];
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pick_program with Program entry {
        self.program_name = here.name;
        visit [->:BelongsTo:->];
    }

    can snapshot with Mentee entry {
        if (self.audience == "MENTEE") or (self.audience == "BOTH") {
            self.frozen.append(here.title);
            self.count += 1;
        }
        visit [-->];
    }

    can snapshot_mentor with Mentor entry {
        if (self.audience == "MENTOR") or (self.audience == "BOTH") {
            self.frozen.append(here.title);
            self.count += 1;
        }
        visit [-->];
    }
}

with entry {
    spring = Program(name="Spring Intake", cohort="2026-S");
    fall = Program(name="Fall Bootcamp", cohort="2026-F");

    m1 = Mentee(title="Ada", stage="onboarding", tags=["ml", "remote"]);
    m2 = Mentee(title="Ben", stage="applied", tags=["web"]);
    m3 = Mentee(title="Cleo", stage="placed", tags=["ml", "onsite"]);
    mentor_a = Mentor(title="Dr. Rao", company="Acme");
    mentor_b = Mentor(title="Ms. Lin", company="Globex");

    spring +>:BelongsTo:+> m1;
    spring +>:BelongsTo:+> m2;
    spring +>:BelongsTo:+> mentor_a;
    fall +>:BelongsTo:+> m3;
    fall +>:BelongsTo:+> mentor_b;

    t1 = SupportTicket(
        subject="Login broken",
        priority="urgent",
        category="auth",
        status="open",
        sla_minutes=60,
        search_terms=["login", "auth"]
    );
    t2 = SupportTicket(
        subject="Stipend question",
        priority="normal",
        category="finance",
        status="open",
        sla_minutes=240,
        search_terms=["stipend", "pay"]
    );
    t3 = SupportTicket(
        subject="Match request",
        priority="low",
        category="matching",
        status="closed",
        sla_minutes=480,
        search_terms=["match"]
    );

    spring +>:FiledAgainst:+> t1;
    spring +>:FiledAgainst:+> t2;
    fall +>:FiledAgainst:+> t3;

    m1 +>:AssignedTo(role="requester"):+> t1;
    m2 +>:AssignedTo(role="requester"):+> t2;

    root ++> spring ++> fall;

    reporter = ProgramReporter();
    root spawn reporter;
    print(
        f"[report] {reporter.program_name}: "
        f"{reporter.mentee_count} mentees, "
        f"{reporter.mentor_count} mentors, "
        f"{reporter.open_tickets} open tickets"
    );

    queue = SupportQueueFilter(min_priority="high", category="auth", search="login");
    root spawn queue;
    print(f"[queue] high/critical auth tickets matching 'login': {len(queue.kept)}");

    blast = NewsletterSend(audience="MENTEE");
    root spawn blast;
    print(f"[blast] {blast.program_name} audience={blast.audience} frozen_count={blast.count}");
}
