    assert spec.original_args["cwd"] == "/home/wpcom/public_html",
        f"got original cwd {spec.original_args}";
    assert spec.resolved_args["cwd"] ==
        "/tmp/wp-codebox-inputs/home/wpcom/public_html",
        f"got resolved cwd {spec.resolved_args}";
    assert spec.resolved_args["autoload-file"] ==
        "/tmp/wp-codebox-inputs/home/wpcom/public_html/vendor/autoload.php",
        f"got resolved autoload path {spec.resolved_args}";
    assert spec.has_unresolved == True,
        f"guard did not flag original args: {spec.has_unresolved}";
    assert step.cmd == "wordpress.phpunit", f"got command {step.cmd}";
    assert step.args["cwd"] ==
        "/tmp/wp-codebox-inputs/home/wpcom/public_html",
        f"runtime received {step.args}";
    assert step.args["autoload-file"] ==
        "/tmp/wp-codebox-inputs/home/wpcom/public_html/vendor/autoload.php",
        f"runtime received {step.args}";
}

