    two = ObjectInstance(kind="Task", label="two");
    three = ObjectInstance(kind="Task", label="three");
    four = ObjectInstance(kind="Task", label="four");
    five = ObjectInstance(kind="Task", label="five");
    six = ObjectInstance(kind="Task", label="six");
    seven = ObjectInstance(kind="Task", label="seven");

    root +>:HoldsRole(granted_at="2024-01-01"):+> alice;
    alice +>:Authorizes(via="role:editor"):+> task_type;
    task_type +>:GrantsObjectAccess(depth_cap=3):+> one;
    one +>:ParentOf(weight=1):+> two;
    two +>:ParentOf(weight=1):+> three;
    three +>:ParentOf(weight=1):+> four;
    four +>:ParentOf(weight=1):+> five;
    five +>:ParentOf(weight=1):+> six;
    six +>:ParentOf(weight=1):+> seven;
    seven +>:ParentOf(weight=1):+> one;

    res = root spawn ObjectAccessAuditor();

    assert len(res.reachable) == 6, f"got {res.reachable}";
    assert "one" in res.reachable, f"got {res.reachable}";
    assert "six" in res.reachable, f"got {res.reachable}";
    assert "seven" not in res.reachable, f"got {res.reachable}";
    assert len(res.visited) == 6, f"got {res.visited}";
}

