    root ++> lint;
    root ++> build;
    root ++> orphan;

    res = root spawn OrphanScanner();
    assert len(res.candidates) == 3, f"expected 3 scripts, got {len(res.candidates)}";
    assert "scripts/lint.sh" in res.candidates, f"missing lint.sh: {res.candidates}";
    assert "scripts/build.sh" in res.candidates, f"missing build.sh: {res.candidates}";
    assert "scripts/check-todos.sh" in res.candidates, f"missing orphan: {res.candidates}";
}

test "orphan is scanned but never marked guarded when only wired scripts are invoked" {
    orphan = Script(name="scripts/check-todos.sh", executable=True);
    wired = Script(name="scripts/lint.sh", executable=True);
    ci = Workflow(name="ci.yml");
    root ++> orphan;
    root +>:Invokes(via="step:lint"):+> ci;
    ci +>:Invokes(via="run:lint"):+> wired;

    root spawn OrphanHunter();
    scan = root spawn OrphanScanner();

    assert "scripts/check-todos.sh" in scan.candidates, f"orphan missing from scan pool: {scan.candidates}";
    assert orphan.guard == False, f"orphan must remain unguarded, got {orphan.guard}";
    assert wired.guard == True, f"invoked script must be guarded, got {wired.guard}";
}

