    protected = Commit(sha="fe1be17f4ab202b1b1be9850f5d0e2316a15834a",
                       expected_sha="fe1be17f4ab202b1b1be9850f5d0e2316a15834a");
    receipt = Receipt(kind="PROTECTED",
                      namespace="config/operator/v03-vertical-policy/");
