        canonical_sha256="deadbeef"
    );

    root +>:Anchors:+> repo;
    repo +>:Parents:+> protected;
    protected +>:Contains:+> escaped;

    m = Materializer();
    root spawn m;

    assert m.fail_reason == "namespace escape", f"got {m.fail_reason}";
}

test "rejects conflicting duplicate paths" {
    repo = Repo(name="dream-xin/ai-sdlc");
    protected = Commit(sha="actual");
    first = PolicyFile(
        path="config/operator/v03-vertical-policy/writer-fence.json",
        canonical_sha256="one"
    );
    second = PolicyFile(
        path="config/operator/v03-vertical-policy/writer-fence.json",
        canonical_sha256="two"
    );

    root +>:Anchors:+> repo;
    repo +>:Parents:+> protected;
    protected +>:Contains:+> first;
    protected +>:Contains:+> second;

    m = Materializer();
    root spawn m;

    assert m.fail_reason == "duplicate path rejected", f"got {m.fail_reason}";
}

