import io;
import from contextlib { redirect_stdout }

test "compiler traverses composition to runtime" {
    sys = WidgetSystem(name="dashboard", plugin_count=2);
    p1 = WidgetPlugin(name="Counter", version=1, interfaces="state");
    p2 = WidgetPlugin(name="Chart", version=2, interfaces="props");
    bp = WidgetSystemBlueprint(
        blueprint_id="bp-001",
        valid=True,
        compiled_from="nested"
    );
    rt = WidgetSystemRuntime(
        runtime_id="rt-001",
        derived_from="bp-001"
    );

    root +>:Composes(slot="system"):+> sys;
    sys +>:Composes(slot="primary"):+> p1;
    sys +>:Composes(slot="secondary"):+> p2;
    sys +>:CompilesTo(at_step=1):+> bp;
    bp +>:DerivesRuntime(valid_at="compile"):+> rt;

    assert len([sys ->:Composes:->]) == 2, f"wrong plugin count";
    assert p1 in [sys ->:Composes:->], f"Counter plugin missing";
    assert p2 in [sys ->:Composes:->], f"Chart plugin missing";
    assert bp.valid == True, f"blueprint should be valid";
    assert rt.derived_from == "bp-001", f"runtime provenance lost";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn BlueprintCompiler();
    }
    out = buf.getvalue();

    assert "composing plugin: Counter v1" in out, f"Counter was not traversed: {out}";
    assert "composing plugin: Chart v2" in out, f"Chart was not traversed: {out}";
    assert "Blueprint bp-001 compiled" in out, f"blueprint was not reached: {out}";
    assert "Runtime rt-001 derived from 'bp-001'" in out, f"runtime was not reached: {out}";
}

test "patch applier updates one document atomically" {
    doc = WidgetDocument(
        doc_id="doc-001",
        source_path="source.nested",
        commit_count=0
    );
    src = WidgetSource(path="source.nested", kind="nested");

    root +>:HoldsSnapshot(accepted_at="root"):+> doc;
    doc +>:HoldsSnapshot(accepted_at="init"):+> src;

    applier = PatchApplier(
        pending_ops=["replace", "add", "remove"],
        target_path="/widgets/0"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn applier;
    }
    out = buf.getvalue();

    assert len([doc ->:HoldsSnapshot:->]) == 1, f"snapshot edge missing";
    assert src in [doc ->:HoldsSnapshot:->], f"source snapshot missing";
    assert doc.commit_count == 3, f"expected 3 commits, got {doc.commit_count}";
    assert res.applied_count == 3, f"expected 3 applied ops, got {res.applied_count}";
    assert "atomic commit complete: 3 op(s)" in out, f"atomic commit was not reported: {out}";
}

test "document inspector reaches the accepted source document" {
    doc = WidgetDocument(
        doc_id="doc-002",
        source_path="source.nested",
        commit_count=2
    );
    src = WidgetSource(path="source.nested", kind="nested");

    root +>:HoldsSnapshot(accepted_at="root"):+> doc;
    doc +>:HoldsSnapshot(accepted_at="init"):+> src;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DocumentInspector();
    }
    out = buf.getvalue();

    assert doc in [root ->:HoldsSnapshot:->], f"document is not reachable from root";
    assert src in [doc ->:HoldsSnapshot:->], f"accepted source is not held by document";
    assert "Document doc-002 holds source 'source.nested', commits=2" in out,
        f"document inspection failed: {out}";
}

