    assert "[OPEN (owner=bob)] pds-bl-future-work:" in out, f"missing OPEN verdict: {out}";
}


test "triage walker traverses parents and visits every row once" {
    buf = io.StringIO();
    t = Triage();
    with redirect_stdout(buf) {
        exemplar = Row(
            title="pds-bl-template-park",
