```jac
"""Rolling four-day inactivity window for authentication sessions.

Models a session-graph: each Student owns one or more AuthSessions; each
session has a refresh Activity chain. A Refresh walker walks the activity
graph, applies the four-day rolling expiry policy on every successful
refresh, and cascades an Invalidate traversal when the inactivity deadline
has been breached.
"""

# Window exactly four days in milliseconds (acceptance criterion).
glob FOUR_DAY_MS: int = 345600000;

# Access token validity stays at 12 hours, expressed here as milliseconds.
glob ACCESS_TOKEN_MS: int = 43200000;

# Pre-deployment grandfather window: seven days, preserved for sessions
# issued before the rolling policy was deployed.
glob SEVEN_DAY_MS: int = 604800000;

node Student {
    has username: str = "";
}

node AuthSession {
    has session_id: str = "";
    has issued_at_ms: int = 0;
    has refreshed_at_ms: int = 0;
    has expires_at_ms: int = 0;
    has revoked: bool = False;
    has grandfathered: bool = False;
}

node RefreshEvent {
    has occurred_at_ms: int = 0;
    has success: bool = False;
    has note: str = "";
}

edge Owns {
    has since_ms: int = 0;
}

edge RefreshedBy {
    has order: int = 0;
}

walker Refresh {
    has now_ms: int = 0;
    has deadline_ms: int = 0;
    has issued_token: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can pick_session with Student entry {
        for sess in [-->][?:AuthSession] {
            visit sess;
        }
    }

    can validate with AuthSession entry {
        if here.revoked {
            print(f"session {here.session_id}: revoked, refresh rejected");
            return;
        }
        if self.now_ms >= here.expires_at_ms {
            print(
                f"session {here.session_id}: past inactivity deadline "
                f"({here.expires_at_ms} <= {self.now_ms}), refresh rejected"
            );
            return;
        }
        self.deadline_ms = self.now_ms + FOUR_DAY_MS;
        here.refreshed_at_ms = self.now_ms;
        here.expires_at_ms = self.deadline_ms;
        self.issued_token = True;
        print(
            f"session {here.session_id}: refresh OK, new deadline = "
            f"{self.deadline_ms} ms ({FOUR_DAY_MS} ms = 4 days from now)"
        );
        visit [-->];
    }
}

walker ExpireSweep {
    has now_ms: int = 0;
    has swept: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep_session with Student entry {
        for sess in [-->][?:AuthSession] {
            if not sess.revoked and self.now_ms >= sess.expires_at_ms {
                sess.revoked = True;
                self.swept += 1;
                print(
                    f"sweep: session {sess.session_id} expired and "
                    f"revoked at {self.now_ms}"
                );
            }
        }
    }
}

with entry {
    # Monday 10:00 base — 700000000 ms is a placeholder "now" for the demo.
    now_ms = 700000000;

    alice = Student(username="alice");

    # Session A: new four-day policy. Issued Monday 10:00, deadline Friday 10:00.
    sess_new = AuthSession(
        session_id="S-new",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms + FOUR_DAY_MS
    );

    # Session B: grandfathered seven-day policy. First successful refresh
    # adopts the four-day rolling window.
    sess_old = AuthSession(
        session_id="S-old-grandfathered",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms + SEVEN_DAY_MS,
        grandfathered=True
    );

    # Session C: already past the four-day deadline, should be swept.
    sess_stale = AuthSession(
        session_id="S-stale",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms - 1
    );

    root ++> alice;

    alice +>:Owns(since_ms=now_ms):+> sess_new;
    alice +>:Owns(since_ms=now_ms):+> sess_old;
    alice +>:Owns(since_ms=now_ms):+> sess_stale;

    evt_new_1 = RefreshEvent(occurred_at_ms=now_ms + 1000, success=True);
    evt_new_2 = RefreshEvent(occurred_at_ms=now_ms + 2000, success=True);
    sess_new +>:RefreshedBy(order=1):+> evt_new_1;
    sess_new +>:RefreshedBy(order=2):+> evt_new_2;

    # Demo 1: Thursday 09:00 — three days after Monday 10:00.
    # sess_new refreshes; deadline rolls forward to Monday 09:00.
    thursday_ms = now_ms + FOUR_DAY_MS - 1;
    print("--- Demo 1: rolling refresh on Thursday ---");
    r1 = Refresh(now_ms=thursday_ms);
    alice spawn r1;

    # Demo 2: grandfathered session, its first successful refresh
    # adopts the four-day rolling window.
    print("--- Demo 2: grandfathered seven-day session, first refresh ---");
    r2 = Refresh(now_ms=now_ms + 1000);
    alice spawn r2;

    # Demo 3: stale session, refresh is rejected, deadline not extended.
    print("--- Demo 3: stale session, refresh rejected ---");
    r3 = Refresh(now_ms=now_ms);
    alice spawn r3;

    # Demo 4: cleanup sweep removes sessions past their inactivity deadline.
    print("--- Demo 4: expire sweep ---");
    sweeper = ExpireSweep(now_ms=now_ms);
    root spawn sweeper;
    print(f"swept {sweeper.swept} expired session(s)");
}
```

jac_tests:
test "new sessions roll forward without an absolute cap" {
    now_ms = 700000000;
    alice = Student(username="alice");
    sess = AuthSession(
        session_id="S-new",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms + FOUR_DAY_MS
    );

    root ++> alice;
    alice +>:Owns(since_ms=now_ms):+> sess;

    assert sess.expires_at_ms == now_ms + FOUR_DAY_MS, f"initial deadline: {sess.expires_at_ms}";

    first = Refresh(now_ms=now_ms + 1000);
    alice spawn first;
    first_deadline = now_ms + 1000 + FOUR_DAY_MS;

    assert first.issued_token == True, f"first refresh failed: {first.issued_token}";
    assert sess.refreshed_at_ms == now_ms + 1000, f"refresh time: {sess.refreshed_at_ms}";
    assert sess.expires_at_ms == first_deadline, f"first deadline: {sess.expires_at_ms}";

    second_time = first_deadline - 1;
    second = Refresh(now_ms=second_time);
    alice spawn second;

    assert second.issued_token == True, f"second refresh failed: {second.issued_token}";
    assert sess.expires_at_ms == second_time + FOUR_DAY_MS, f"rolling deadline: {sess.expires_at_ms}";
    assert sess.expires_at_ms > now_ms + FOUR_DAY_MS, f"session hit an absolute cap: {sess.expires_at_ms}";
}

test "grandfathered sessions adopt four-day expiry on first refresh" {
    now_ms = 800000000;
    alice = Student(username="legacy");
    sess = AuthSession(
        session_id="S-grandfathered",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms + SEVEN_DAY_MS,
        grandfathered=True
    );

    root ++> alice;
    alice +>:Owns(since_ms=now_ms):+> sess;

    assert sess.expires_at_ms == now_ms + SEVEN_DAY_MS, f"legacy deadline changed early: {sess.expires_at_ms}";

    refresh = Refresh(now_ms=now_ms + 2000);
    alice spawn refresh;

    assert refresh.issued_token == True, f"legacy refresh failed: {refresh.issued_token}";
    assert sess.expires_at_ms == now_ms + 2000 + FOUR_DAY_MS, f"adopted deadline: {sess.expires_at_ms}";
}

test "expired and revoked refreshes fail closed" {
    now_ms = 900000000;
    alice = Student(username="student");
    stale = AuthSession(
        session_id="S-stale",
        issued_at_ms=now_ms - FOUR_DAY_MS,
        refreshed_at_ms=now_ms - FOUR_DAY_MS,
        expires_at_ms=now_ms - 1
    );
    revoked = AuthSession(
        session_id="S-revoked",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms + FOUR_DAY_MS,
        revoked=True
    );

    root ++> alice;
    alice +>:Owns(since_ms=now_ms):+> stale;
    alice +>:Owns(since_ms=now_ms):+> revoked;

    stale_deadline = stale.expires_at_ms;
    revoked_deadline = revoked.expires_at_ms;

    refresh = Refresh(now_ms=now_ms);
    alice spawn refresh;

    assert refresh.issued_token == False, f"rejected refresh issued a token: {refresh.issued_token}";
    assert stale.expires_at_ms == stale_deadline, f"expired deadline extended: {stale.expires_at_ms}";
    assert stale.refreshed_at_ms == now_ms - FOUR_DAY_MS, f"expired session was updated: {stale.refreshed_at_ms}";
    assert revoked.expires_at_ms == revoked_deadline, f"revoked deadline extended: {revoked.expires_at_ms}";
    assert revoked.refreshed_at_ms == now_ms, f"revoked session was updated: {revoked.refreshed_at_ms}";
}

test "expiry sweep revokes only sessions past their deadline" {
    now_ms = 1000000000;
    alice = Student(username="student");
    active = AuthSession(
        session_id="S-active",
        issued_at_ms=now_ms,
        refreshed_at_ms=now_ms,
        expires_at_ms=now_ms + FOUR_DAY_MS
    );
    stale = AuthSession(
        session_id="S-expired",
        issued_at_ms=now_ms - FOUR_DAY_MS,
        refreshed_at_ms=now_ms - FOUR_DAY_MS,
        expires_at_ms=now_ms - 1
    );

    root ++> alice;
    alice +>:Owns(since_ms=now_ms):+> active;
    alice +>:Owns(since_ms=now_ms):+> stale;

    sweeper = ExpireSweep(now_ms=now_ms);
    root spawn sweeper;

    assert sweeper.swept == 1, f"swept count: {sweeper.swept}";
    assert stale.revoked == True, f"expired session not revoked: {stale.revoked}";
    assert active.revoked == False, f"active session revoked: {active.revoked}";
    assert ACCESS_TOKEN_MS == 43200000, f"access token window changed: {ACCESS_TOKEN_MS}";
}

