"""Tests for JINGO handoff audit walker."""

import io;
import from contextlib { redirect_stdout }

test "complete handoff with RUNNING and evidence passes" {
    root ++> Task(
        title="Draft concept brief",
        status="RUNNING",
        reviewer="DJANGO",
        source="approved-spec-v1",
        authority="STUDIO_AGENT",
        result_evidence=True,
        current_status_recorded=True
    );
    root ++> HandoffPacket(
        task_ref="Draft concept brief",
        authority=True,
        source=True,
        status=True,
        locks=True,
        reviewer=True,
        expected_output=True
    );
    [t] = [root -->][?:Task];
    [p] = [root -->][?:HandoffPacket];
    root +>:AssignedTo:+> t;
    t +>:HandoffFrom:+> p;
    auditor = HandoffAudator_safe();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HandoffAuditor();
    }
    assert "Draft concept brief" in res.passes, f"should pass: {res.passes}";
    assert "Draft concept brief" not in res.holds, f"unexpected hold: {res.holds}";
    assert "Draft concept brief" not in res.conflicts, f"unexpected conflict: {res.conflicts}";
}

test "incomplete handoff packet triggers HOLD" {
    t = Task(title="Incomplete task", status="ASSIGNED", reviewer="DJANGO");
    p = HandoffPacket(task_ref="Incomplete task", authority=True, source=True, status=True, locks=False, reviewer=True, expected_output=True);
    root +>:AssignedTo:+> t;
    t +>:HandoffFrom:+> p;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HandoffAuditor();
    }
    assert "Incomplete task" in res.holds, f"expected HOLD: {res.holds}";
    assert "Incomplete task" not in res.passes, f"unexpected pass: {res.passes}";
    out = buf.getvalue();
    assert "[HOLD] Incomplete task" in out, f"missing HOLD print: {out}";
}

test "RESULT_READY without evidence is a CONFLICT" {
    t = Task(title="Final render", status="RESULT_READY", reviewer="DJANGO", source="spec", authority="DOMAIN_AGENT", result_evidence=False);
    p = HandoffPacket(task_ref="Final render", authority=True, source=True, status=True, locks=True, reviewer=True, expected_output=True);
    root +>:AssignedTo:+> t;
    t +>:HandoffFrom:+> p;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HandoffAuditor();
    }
    assert "Final render" in res.conflicts, f"expected conflict: {res.conflicts}";
    assert "Final render" not in res.passes, f"unexpected pass: {res.passes}";
    out = buf.getvalue();
    assert "[CONFLICT] Final render" in out, f"missing conflict print: {out}";
}

test "ASSIGNED with full packet is PASS not RUNNING conflict" {
    t = Task(title="Visual mock", status="ASSIGNED", reviewer="DJANGO", source="approved-spec-v1", authority="DOMAIN_AGENT");
    p = HandoffPacket(task_ref="Visual mock", authority=True, source=True, status=True, locks=True, reviewer=True, expected_output=True);
    root +>:AssignedTo:+> t;
    t +>:HandoffFrom:+> p;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HandoffAuditor();
    }
    assert "Visual mock" in res.passes, f"ASSIGNED + complete packet should PASS: {res.passes}";
    assert "Visual mock" not in res.conflicts, f"ASSIGNED must not trigger conflict: {res.conflicts}";
}

test "dependency traversal audits downstream tasks in chain" {
    t1 = Task(title="Alpha", status="RUNNING", reviewer="DJANGO", source="spec", authority="STUDIO_AGENT", result_evidence=True, current_status_recorded=True);
    t2 = Task(title="Beta", status="ASSIGNED", reviewer="DJANGO", source="spec", authority="DOMAIN_AGENT");
    t3 = Task(title="Gamma", status="RESULT_READY", reviewer="DJANGO", source="spec", authority="DOMAIN_AGENT", result_evidence=False);
    p1 = HandoffPacket(task_ref="Alpha", authority=True, source=True, status=True, locks=True, reviewer=True, expected_output=True);
    p2 = HandoffPacket(task_ref="Beta", authority=True, source=True, status=True, locks=True, reviewer=True, expected_output=True);
    p3 = HandoffPacket(task_ref="Gamma", authority=True, source=True, status=True, locks=True, reviewer=True, expected_output=True);
    root +>:AssignedTo:+> t1;
    root +>:AssignedTo:+> t2;
    root +>:AssignedTo:+> t3;
    t1 +>:HandoffFrom:+> p1;
    t2 +>:HandoffFrom:+> p2;
    t3 +>:HandoffFrom:+> p3;
    t1 +>:DependsOn:+> t2;
    t2 +>:DependsOn:+> t3;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HandoffAuditor();
    }
    assert "Alpha" in res.passes, f"Alpha should pass: {res.passes}";
    assert "Beta" in res.passes, f"Beta should pass: {res.passes}";
    assert "Gamma" in res.conflicts, f"Gamma RESULT_READY no evidence should conflict: {res.conflicts}";
    assert len(res.tasks_seen) == 3, f"auditor should traverse all 3 tasks: {res.tasks_seen}";
}

walker HandoffAudator_safe {
    has tasks_seen: list = [];
