    assert len(evidence_nodes) == 1, f"got {len(evidence_nodes)} evidence nodes";
    assert len(res.compiled) == 1, f"got {len(res.compiled)} compiled fragments";
    assert compiled_node.purpose == "determine_worker_failure", f"got {compiled_node.purpose}";
    assert compiled_node.fragment == "assembled(determine_worker_failure)", f"got {compiled_node.fragment}";
    assert len(compiled_edges) == 1, f"got {len(compiled_edges)} compiled edges";
