test "compiled context is stored and reused from governed memory" {
    context = ContextFragment(
        purpose="determine_worker_failure",
        fragment="assembled(worker failure)",
    );

    context spawn IngestOutcome(
        purpose="ignored",
        fragment="ignored",
        tick=42,
    );

    memory_edges = [context ->:RememberedFrom:->];
    stored = memory_edges[0];

    assert len(memory_edges) == 1, f"got {len(memory_edges)} memory edges";
    assert stored.purpose == "determine_worker_failure", f"got {stored.purpose}";
    assert stored.fragment == "assembled(worker failure)", f"got {stored.fragment}";
    assert stored.remembered_at == 42, f"got {stored.remembered_at}";

    root ++> stored;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn MemoryReuser();
    }
    out = buf.getvalue();

    assert "--- memory reuse pass ---" in out, f"missing reuse marker: {out}";
    assert "reused memory: determine_worker_failure (assembled(worker failure))" in out, f"missing memory output: {out}";
}

