test "active teams resolve memberships while deleted teams do not" {
    active = Team(name="Platform");
    deleted = Team(name="OldProject", deleted_at="2024-06-01T00:00:00Z");
    alice = User(name="alive-alice", role="owner", hierarchy=4);
    carol = User(name="dead-carol", role="owner", hierarchy=4);

    root ++> active;
    root ++> deleted;
    active +>:HasMembership(permissions="manage,write"):+> alice;
    deleted +>:HasMembership(permissions="manage,write"):+> carol;

    assert len([deleted ->:HasMembership:->]) == 1,
        f"deleted membership edge missing";
    alive_res = root spawn MembershipResolver(target_user="alive-alice");
    dead_res = root spawn MembershipResolver(target_user="dead-carol");

    assert alive_res.found_role == "owner",
        f"got {alive_res.found_role}";
    assert alive_res.found_perms == "--resolved-via-active-team--",
        f"got {alive_res.found_perms}";
    assert dead_res.found_role == "",
        f"deleted team resolved role {dead_res.found_role}";
    assert dead_res.found_perms == "",
        f"deleted team resolved perms {dead_res.found_perms}";
}

test "integrity audit counts active and soft-deleted teams" {
    active = Team(name="Platform");
    deleted = Team(name="OldProject", deleted_at="2024-06-01T00:00:00Z");
    alice = User(name="alive-alice", role="editor", hierarchy=2);
    carol = User(name="dead-carol", role="owner", hierarchy=4);

    root ++> active;
    root ++> deleted;
    active +>:HasMembership(permissions="write"):+> alice;
    deleted +>:HasMembership(permissions="manage,write"):+> carol;

    audit = root spawn IntegrityAudit();

    assert audit.active_hits == 1,
        f"got active hits {audit.active_hits}";
    assert audit.pruned_hits == 1,
        f"got pruned hits {audit.pruned_hits}";
    assert len([active ->:HasMembership:->]) == 1,
        f"active membership count changed";
    assert len([deleted ->:HasMembership:->]) == 1,
        f"deleted membership row was removed";
}

test "unfiltered traversal exposes the stale deleted-team role" {
    active = Team(name="Platform");
    deleted = Team(name="OldProject", deleted_at="2024-06-01T00:00:00Z");
    alice = User(name="alive-alice", role="owner", hierarchy=4);
    carol = User(name="dead-carol", role="owner", hierarchy=4);

    root ++> active;
    root ++> deleted;
    active +>:HasMembership(permissions="manage,write"):+> alice;
    deleted +>:HasMembership(permissions="manage,write"):+> carol;

    show = root spawn ShowBug();

