    assert g1.passed == False, f"Security passed flag: {g1.passed}";
    assert g2.passed == False, f"Release passed flag: {g2.passed}";
    assert len(g1.evidence_keys) == 0, f"Security evidence: {g1.evidence_keys}";
    assert len(g2.evidence_keys) == 0, f"Release evidence: {g2.evidence_keys}";
