test "nested UAX views count one canonical span once" {
    span = Span(text="a", media="NFC");
    g = Grapheme();
    w = Word();
    s = Sentence();

    g +>:Children(order=0):+> span;
    w +>:Children(order=0):+> g;
    s +>:Children(order=0):+> w;
    root ++> s;

    res = root spawn CanonicalCensus();
    assert res.unique_count == 1, f"got {res.unique_count}";
    assert res.cycles == 0, f"got {res.cycles}";
}

test "canonical child cycles are detected" {
    span = Span(text="loop", media="NFC");
    span +>:Children(order=0):+> span;
    root ++> span;

    res = root spawn CanonicalCensus();
    assert res.unique_count == 1, f"got {res.unique_count}";
    assert res.cycles == 1, f"got {res.cycles}";
}

test "provider witnesses remain separate from canonical spans" {
    span = Span(text="a", media="NFC");
    tree = Parser(name="tree-sitter");
    regex = Parser(name="pcre");

    span +>:Witness(
        kind="grapheme",
        byte_start=10,
        byte_end=11,
        depth=1
    ):+> tree;
    span +>:Witness(
        kind="grapheme",
        byte_start=20,
        byte_end=21,
        depth=1
    ):+> regex;
    root ++> span;

    witnesses = [span ->:Witness:->];
    assert len(witnesses) == 2, f"got {len(witnesses)}";
    assert tree in witnesses, f"missing tree-sitter witness";
    assert regex in witnesses, f"missing pcre witness";

    res = root spawn CanonicalCensus();
    assert res.unique_count == 1, f"got {res.unique_count}";
    assert len([root-->]) == 1, f"got {len([root-->])}";
}

