    desktop +>:RestoresFrom(since="v0.18.2"):+> old;

    assert len([fresh -->]) == 0, f"fresh session is not empty";
    assert old in [desktop ->:RestoresFrom:->], f"stale restore target missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        probe = index spawn FreshnessProbe();
        resume = desktop spawn StaleResume();
    }
    out = buf.getvalue();

    assert "[probe] session s-new cleared=False" in out, f"fresh session missing: {out}";
    assert "[probe] session s-old cleared=True" in out, f"old session missing: {out}";
    assert "[restore] DesktopState pulls session s-old" in out, f"stale restore missing: {out}";
    assert "[STALE] user: stale question" in out, f"stale content missing: {out}";
