"""Vimshottari cache idempotency model.

Models the engine's cache-key contract (contract + engine + algorithm +
source versions) and walks the cache registry to detect stale entries
that must be invalidated when a source version moves.
"""

node SourceVersion {
    has contract: str = "";
    has engine: str = "";
    has algorithm: str = "";
    has version: str = "";
}

node CacheEntry {
    has contract: str = "";
    has engine: str = "";
    has algorithm: str = "";
    has source_version: str = "";
    has mahadasha: str = "";
    has antardasha: str = "";
    has starting_balance: float = 0.0;
    has stale: bool = False;
}

node Registry {
    has name: str = "";
}

edge KeyedBy {
    has contract: str = "";
    has engine: str = "";
    has algorithm: str = "";
    has source_version: str = "";
}

edge Stale {
}

walker CacheAuditor {
    can start with Root entry {
        visit [-->];
    }

    can enter_registry with Registry entry {
        print(f"Auditing registry: {here.name}");
        visit [-->];
    }

    can audit_entry with CacheEntry entry {
        canonical = self.lookup(here.contract, here.engine, here.algorithm, here.source_version);
        if canonical is None {
            here.stale = True;
            print(f"[STALE] {here.contract}/{here.engine}/{here.algorithm} @ {here.source_version} -> no source");
            visit [-->];
            return;
        }
        if here.mahadasha != canonical.mahadasha or here.antardasha != canonical.antardasha
            or here.starting_balance != canonical.starting_balance {
            here.stale = True;
            print(f"[STALE] {here.contract}/{here.engine}/{here.algorithm} @ {here.source_version} mismatch");
        } else {
            print(f"[FRESH] {here.contract}/{here.engine}/{here.algorithm} @ {here.source_version}");
        }
        visit [-->];
    }

    def lookup(contract: str, engine: str, algorithm: str, version: str) -> CacheEntry | None {
        return self.canonical.get((contract, engine, algorithm, version));
    }

    has canonical: dict[tuple[str, str, str, str], CacheEntry] = {};
}

with entry {
    reg = Registry(name="vimshottari-cache");
    root ++> reg;

    sv = SourceVersion(contract="v1", engine="vimshottari", algorithm="dasha-tree", version="1.2.0");
    reg +>:KeyedBy(contract="v1", engine="vimshottari", algorithm="dasha-tree", source_version="1.2.0"):+> sv;

    fresh_entry = CacheEntry(
        contract="v1", engine="vimshottari", algorithm="dasha-tree",
        source_version="1.2.0", mahadasha="Venus", antardasha="Sun", starting_balance=0.42
    );
    stale_entry = CacheEntry(
        contract="v1", engine="vimshottari", algorithm="dasha-tree",
        source_version="1.2.0", mahadasha="Mars", antardasha="Sun", starting_balance=0.42
    );
    orphan_entry = CacheEntry(
        contract="v1", engine="vimshottari", algorithm="dasha-tree",
        source_version="9.9.9", mahadasha="Rahu", antardasha="Moon", starting_balance=0.0
    );

    reg ++> fresh_entry;
    reg ++> stale_entry;
    reg ++> orphan_entry;

    auditor = CacheAuditor();
    auditor.canonical[(sv.contract, sv.engine, sv.algorithm, sv.version)] = fresh_entry;

    root spawn auditor;
}
