test "recursive assembler respects the simulated stack budget" {
    head = Value(label="v1", depth=1);
    root ++> head;
    prev = head;
    for i in range(2, 206) {
        cur = Value(label=f"v{i}", depth=i);
        prev +>:Child(slot=i):+> cur;
        prev = cur;
    }

    rec = root spawn RecursiveAssembler();

    assert rec.failed, f"recursive walker did not fail: {rec.seen}";
    assert len(rec.seen) == RECURSION_BUDGET - 1,
