    assert len(it.seen) == 2, f"seen coordinates: {it.seen}";
    assert it.seen[0] == "a", f"first coordinate: {it.seen}";
    assert it.seen[1] == "b", f"second coordinate: {it.seen}";
    assert len(it.cycles) == 1, f"cycles: {it.cycles}";
    assert it.cycles[0] == "a", f"cycle coordinate: {it.cycles}";
