    review_branch = Branch(name="needs-review", merged=False, active=False);
    active_ruleset = Ruleset(name="active-ruleset", active=True);
    inactive_ruleset = Ruleset(name="inactive-ruleset", active=False);
    evidence_item = Evidence(note="slice candidate");

    root ++> protected_branch;
    root ++> retained_branch;
    root ++> review_branch;
    root ++> active_ruleset;
    root ++> inactive_ruleset;
    root ++> evidence_item;

    res = root spawn Auditor();

    assert len(res.audit_log) == 6, f"got {res.audit_log}";
    assert "BRANCH protected-history -> KEEP_PROTECTED_CURRENT" in res.audit_log, f"got {res.audit_log}";
    assert "BRANCH retained-history -> KEEP_EVIDENCE" in res.audit_log, f"got {res.audit_log}";
    assert "BRANCH needs-review -> HUMAN_REVIEW" in res.audit_log, f"got {res.audit_log}";
    assert "RULESET active-ruleset -> KEEP_PROTECTED_CURRENT" in res.audit_log, f"got {res.audit_log}";
    assert "RULESET inactive-ruleset -> SAFE_DELETE" in res.audit_log, f"got {res.audit_log}";
    assert "EVIDENCE slice candidate -> KEEP_EVIDENCE" in res.audit_log, f"got {res.audit_log}";
}

