    assert node_a.status == "dispatched", f"A status: {node_a.status}";
    assert node_b.status == "dispatched", f"B status: {node_b.status}";
    assert node_c.status == "dispatched", f"C status: {node_c.status}";
    assert "attempt=7, fence=7" in buf.getvalue(), f"output: {buf.getvalue()}";
}

test "fails closed when no execution plan is bound" {
