test "traverses a two-hop call path" {
    root_contract = Contract(name="Vault", state_finalized=False, guarded=False);
    middle = Contract(name="Strategy", state_finalized=False, guarded=False);
    target = Contract(name="Accounting", state_finalized=True, guarded=False);

    root ++> root_contract;
    root_contract +>:Calls(from_fn="withdraw", to_fn="deposit"):+> middle;
    middle +>:Calls(from_fn="deposit", to_fn="record"):+> target;

    assert len([root_contract ->:Calls:->]) == 1, "expected one outgoing call";
    assert middle in [root_contract ->:Calls:->], "missing Strategy call edge";
    assert target in [middle ->:Calls:->], "missing Accounting call edge";

    hunter = ReentrancyHunter();
    root spawn hunter;
    assert len(hunter.findings) == 0, f"unexpected finding count: {len(hunter.findings)}";
    assert len(hunter.current_chain) == 0, f"chain not unwound: {hunter.current_chain}";
}

test "guarded entry short-circuits the chain" {
    guarded = Contract(name="GuardedVault", state_finalized=False, guarded=True);
    strategy = Contract(name="Strategy", state_finalized=False, guarded=False);
    sink = Contract(name="Sink", state_finalized=False, guarded=False);

    root ++> guarded;
    guarded +>:Calls(from_fn="withdraw", to_fn="deposit"):+> strategy;
    strategy +>:Calls(from_fn="deposit", to_fn="settle"):+> sink;

    hunter = ReentrancyHunter(max_depth=3);
    root spawn hunter;
    assert len(hunter.findings) == 0, f"guarded chain was reported: {hunter.findings}";
    assert guarded.guarded, f"guard flag was not preserved: {guarded.guarded}";
}

test "maximum depth bounds forward traversal" {
    first = Contract(name="A", state_finalized=False, guarded=False);
    second = Contract(name="B", state_finalized=False, guarded=False);
    third = Contract(name="C", state_finalized=False, guarded=False);
    fourth = Contract(name="D", state_finalized=False, guarded=False);

    root ++> first;
    first +>:Calls(from_fn="f", to_fn="g"):+> second;
    second +>:Calls(from_fn="g", to_fn="h"):+> third;
    third +>:Calls(from_fn="h", to_fn="i"):+> fourth;

    hunter = ReentrancyHunter(max_depth=2);
    root spawn hunter;
    assert len(hunter.findings) == 0, f"depth-limited path was reported: {hunter.findings}";
    assert len([first ->:Calls:->]) == 1, "expected one first-hop edge";
    assert third in [second ->:Calls:->], "second hop was not built";
}

