"""Test annex for the krolik cleanup demo."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: happy path — runner is deregistered, dir deleted, unit disabled.
# ---------------------------------------------------------------------------
test "runner deregistered and unit disabled on self-hosted host" {
    root ++> LinuxHost(hostname="krolik", is_self_hosted=True);
    krolik = [root -->][0];
    unit = SystemdUnit(
        unit_name="actions-runner-landing-kit.service",
        enabled=True,
        active=False
    );
    runner = RunnerInstall(
        install_path="~/actions-runner-landing-kit",
        registered=True
    );
    krolik +>:LivesOn(since="2024-01-15"):+> unit;
    unit +>:SupervisedBy(since="2024-01-15"):+> runner;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Decommissioner();
    }
    out = buf.getvalue();

    assert "deregistered runner at ~/actions-runner-landing-kit" in out, (
        f"missing deregister log: {out}"
    );
    assert "deleted install directory ~/actions-runner-landing-kit" in out, (
        f"missing delete-dir log: {out}"
    );
    assert "disabled --now actions-runner-landing-kit.service" in out, (
        f"missing unit teardown log: {out}"
    );

    assert runner.registered == False, "runner must be deregistered";
    assert unit.enabled == False, "unit must be disabled";
    assert unit.active == False, "unit must be stopped (active=False)";

    assert "~/actions-runner-landing-kit" in res.decommissioned, (
        f"decommissioned list missing path: {res.decommissioned}"
    );
}

# ---------------------------------------------------------------------------
# Test 2: fail-closed semantics — non-self-hosted hosts are left alone.
# ---------------------------------------------------------------------------
test "non-self-hosted host is skipped entirely" {
    root ++> Host(hostname="ci-vm-02", is_self_hosted=False);
    host = [root -->][0];
    orphan_unit = SystemdUnit(
        unit_name="actions-runner-orphan.service",
        enabled=False,
        active=False
    );
    orphan_runner = RunnerInstall(
        install_path="~/orphan-runner",
        registered=True
    );
    host ++> orphan_unit;
    orphan_unit +>:SupervisedBy:+> orphan_runner;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Decommissioner();
    }
    out = buf.getvalue();

    # Walker's at_host early-exits via `visit [<--]` when not self-hosted,
    # so nothing must be touched.
    assert orphan_runner.registered == True, (
        "non-self-hosted runner must remain registered"
    );
    assert orphan_unit.enabled == False, (
        "non-self-hosted unit must remain as-declared"
    );
    assert "~/orphan-runner" not in out, (
        f"non-self-hosted runner should not be touched, got: {out}"
    );
    assert len(res.decommissioned) == 0, (
        f"nothing must be decommissioned, got: {res.decommissioned}"
    );
}

# ---------------------------------------------------------------------------
# Test 3: cycle guard — repeating hostnames do not cause an infinite loop.
# ---------------------------------------------------------------------------
test "cycle guard prevents re-visiting a host" {
    root ++> LinuxHost(hostname="krolik", is_self_hosted=True);
    krolik = [root -->][0];
    unit = SystemdUnit(
        unit_name="actions-runner-landing-kit.service",
        enabled=True,
        active=False
    );
    runner = RunnerInstall(
        install_path="~/actions-runner-landing-kit",
        registered=True
    );
    krolik +>:LivesOn:+> unit;
    unit +>:SupervisedBy:+> runner;
    # Wire a second LivesOn edge back to the same unit from krolik:
    # this forms a cycle on the host's LivesOn view and would loop the
    # walker if the guard set were missing.
    krolik +>:LivesOn(since="2024-02-01"):+> unit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Decommissioner();
    }
    out = buf.getvalue();

    # Termination guard: the run completed (we got a result).
    assert res is not None, "walker must terminate despite cycle";
    # Unit is disabled exactly once — disabled --now log appears once.
    assert out.count("disabled --now actions-runner-landing-kit.service") == 1, (
        f"unit must be disabled exactly once, got: {out}"
    );
    # Hostname was recorded in the guard set after the first visit.
    assert "krolik" in res.visited_hosts, (
        f"krolik must be tracked as visited, got: {res.visited_hosts}"
    );
}

# ---------------------------------------------------------------------------
# Test 4: graph shape — typed edges carry the declared relationships.
# ---------------------------------------------------------------------------
test "typed edges link host -> unit -> runner" {
    root ++> LinuxHost(hostname="krolik", is_self_hosted=True);
    krolik = [root -->][0];
    unit = SystemdUnit(
        unit_name="actions-runner-landing-kit.service",
        enabled=True,
        active=False
    );
    runner = RunnerInstall(
        install_path="~/actions-runner-landing-kit",
        registered=True
    );
    krolik +>:LivesOn(since="2024-01-15"):+> unit;
    unit +>:SupervisedBy(since="2024-01-15"):+> runner;

    # krolik must have exactly one typed LivesOn edge to the unit.
    assert unit in [krolik ->:LivesOn:->], (
        "expected LivesOn edge from krolik to unit"
    );
    # Unit must have exactly one SupervisedBy edge to the runner.
    assert runner in [unit ->:SupervisedBy:->], (
        "expected SupervisedBy edge from unit to runner"
    );
    # The runner has no outgoing typed edges in this scenario.
    assert len([runner ->:SupervisedBy:->]) == 0, (
        "runner must not point at further SupervisedBy edges"
    );
    # Decommissioner.walker must declare the expected `has` fields.
    assert hasattr(Decommissioner(), "visited_hosts"), (
        "Decommissioner must expose visited_hosts"
    );
    assert hasattr(Decommissioner(), "decommissioned"), (
        "Decommissioner must expose decommissioned"
    );
}

