"""Test annex for the tool-process lifecycle demo."""

import io;
import from contextlib { redirect_stdout }

# --- ProcessAuditor: reaps a stale child and disengages ---------------------
test "ProcessAuditor reaps stale child and disengages" {
    # Build a minimal graph: parent -> worktree -> one stale child, one fresh.
    rt = root ++> Worktree(path="scripts", has_node_modules=False);
    parent = root ++> ClaudeParent(label="claude.exe", active_action="edit file");
    stale = ToolChild(
        name="pwsh.exe#1",
        command="Get-ChildItem -Recurse -Path scripts",
        cpu_seconds=5.72,
        superseded=True,
    );
    fresh = ToolChild(
        name="pwsh.exe#2",
        command="git status",
        cpu_seconds=0.0,
        superseded=False,
    );
    parent +>:Spawned(started_at="T0"):+> rt;
    rt +>:Scans:+> stale;
    rt +>:Scans:+> fresh;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = ProcessAuditor();
        parent spawn auditor;
    }
    out = buf.getvalue();

    # The auditor hits stale first via visit [-->], reaps it, then disengages.
    assert stale.reaped, f"stale child should be reaped, got reaped={stale.reaped}";
    assert not fresh.reaped, f"fresh child must NOT be reaped by auditor, got reaped={fresh.reaped}";
    assert "reaping stale child" in out, f"missing reap print: {out}";
    assert "edit file" in out, f"missing parent active-action print: {out}";
    # Disengagement means the worktree's child was reaped before worktree print
    # was necessarily reached via that branch — auditor output for the fresh
    # child should also be absent because disengage happens at stale.
    assert "git status" not in out, f"auditor should disengage after reaping stale; got: {out}";
}

# --- ProcessAuditor: reports worktree node_modules marker -------------------
test "ProcessAuditor reports worktree node_modules marker" {
    parent = root ++> ClaudeParent(label="claude.exe", active_action="audit");
    wt_a = Worktree(path="scripts", has_node_modules=False);
    wt_b = Worktree(path=".claude/worktrees", has_node_modules=True);
    fresh = ToolChild(name="pwsh.exe#3", command="git status", cpu_seconds=0.0, superseded=False);
    parent +>:Spawned(started_at="T0"):+> wt_a;
    parent +>:Spawned(started_at="T0"):+> wt_b;
    wt_a +>:Scans:+> fresh;
    wt_b +>:Scans:+> fresh;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = ProcessAuditor();
        parent spawn auditor;
    }
    out = buf.getvalue();

    # No superseded children here, so no reaping — auditor should reach the
    # worktree visit and print the node_modules marker.
    assert "scripts (without node_modules)" in out, f"missing scripts marker: {out}";
    assert ".claude/worktrees (with node_modules)" in out, f"missing .claude marker: {out}";
    assert "reaping stale child" not in out, f"should not reap anything: {out}";
    assert "audit" in out, f"missing active_action line: {out}";
}

# --- StaleScanner: follows Spawned -> Scans -> reaps only superseded -------
test "StaleScanner follows Spawned then Scans edges and reaps stale only" {
    parent = root ++> ClaudeParent(label="claude.exe", active_action="next action");
    wt_a = Worktree(path="scripts", has_node_modules=False);
    wt_b = Worktree(path=".claude/worktrees", has_node_modules=True);
    stale_a = ToolChild(
        name="pwsh.exe#1",
        command="Get-ChildItem -Recurse -Path scripts",
        cpu_seconds=5.72,
        superseded=True,
    );
    stale_b = ToolChild(
        name="pwsh.exe#2",
        command="Get-ChildItem -Recurse -Path .claude,scripts",
        cpu_seconds=1.66,
        superseded=True,
    );
    fresh = ToolChild(name="pwsh.exe#3", command="git status --porcelain", cpu_seconds=0.02, superseded=False);
    parent +>:Spawned(started_at="T0"):+> wt_a;
    parent +>:Spawned(started_at="T0"):+> wt_b;
    wt_a +>:Scans:+> stale_a;
    wt_b +>:Scans:+> stale_b;
    wt_a +>:Scans:+> fresh;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        scanner = StaleScanner();
        parent spawn scanner;
    }
    out = buf.getvalue();

    # Both superseded children must be reaped; the fresh one must not.
    assert stale_a.reaped, f"stale_a should be reaped, got reaped={stale_a.reaped}";
    assert stale_b.reaped, f"stale_b should be reaped, got reaped={stale_b.reaped}";
    assert not fresh.reaped, f"fresh must not be reaped, got reaped={fresh.reaped}";
    # CPU seconds for stale children should be zeroed out by the reaper.
    assert stale_a.cpu_seconds == 0.0, f"stale_a cpu_seconds not zeroed: {stale_a.cpu_seconds}";
    assert stale_b.cpu_seconds == 0.0, f"stale_b cpu_seconds not zeroed: {stale_b.cpu_seconds}";
    assert "reaped superseded child pwsh.exe#1" in out, f"missing stale_a reap line: {out}";
    assert "reaped superseded child pwsh.exe#2" in out, f"missing stale_b reap line: {out}";
}

# --- stale_children counter: matches post-walk reality ----------------------
test "stale_children counter matches post-walk reality" {
    parent = root ++> ClaudeParent(label="claude.exe", active_action="reconcile");
    wt = Worktree(path="scripts", has_node_modules=False);
    stale = ToolChild(
        name="pwsh.exe#1",
        command="Get-ChildItem -Recurse -Path scripts",
        cpu_seconds=5.72,
        superseded=True,
    );
    fresh = ToolChild(name="pwsh.exe#3", command="git status", cpu_seconds=0.0, superseded=False);
    parent +>:Spawned(started_at="T0"):+> wt;
    wt +>:Scans:+> stale;
    wt +>:Scans:+> fresh;

    # Run the dedicated stale scanner (not the auditor, which disengages early).
    buf = io.StringIO();
    with redirect_stdout(buf) {
        scanner = StaleScanner();
        parent spawn scanner;
    }

    # Recompute the same counter logic the demo's with entry uses.
    remaining = 0;
    for c in [stale, fresh] {
        if c.superseded and not c.reaped {
            remaining += 1;
        }
    }
    parent.stale_children = remaining;
    assert parent.stale_children == 0, f"after reaping, stale_children should be 0, got {parent.stale_children}";

    # Now add a still-superseded, not-yet-reaped child and re-check.
    stale2 = ToolChild(
        name="pwsh.exe#2",
        command="Get-ChildItem -Recurse -Path .claude",
        cpu_seconds=1.66,
        superseded=True,
    );
    wt +>:Scans:+> stale2;

    remaining = 0;
    for c in [stale, fresh, stale2] {
        if c.superseded and not c.reaped {
            remaining += 1;
        }
    }
    parent.stale_children = remaining;
    assert parent.stale_children == 1, f"one unreaped superseded child should remain, got {parent.stale_children}";
}

