```jac
"""ConsumeQueue / ConsumeQueueExt truncation model.

Demonstrates the orphaned CQExt bug: a ConsumeQueue holds tagged entries
that reference units in a ConsumeQueueExt store. Truncating the CQ should
also truncate the extension store, but the buggy early-return path leaves
orphaned extension units behind. The walker ``Truncator`` performs the
fixed scan: it walks through CQ files, truncates entries beyond the
target offset, and ALWAYS routes through the extension-truncation tail.
"""

node ConsumeQueue {
    has name: str = "";
    has entries: list[tuple[int, int]] = [];   # (cq_offset, ext_addr) pairs
}

node ConsumeQueueExt {
    has name: str = "";
    # Mapping from extension address -> tag code. Address 0 is reserved.
    has units: dict[int, int] = {};
    has max_referenced_addr: int = 1;          # 1 == "no ext referenced"
}

edge MappedTo {
    has slot: int = 0;
}

walker Truncator {
    has target_offset: int = 0;
    has max_ext_addr: int = 1;

    can start with Root entry {
        visit [-->];
    }

    # Walk into the ConsumeQueue and do the truncation scan.
    can scan with ConsumeQueue entry {
        print(f"[scan] {here.name}: entries before = {here.entries}");
        retained: list[tuple[int, int]] = [];
        last_ext_addr: int = 1;
        for (off, ext_addr) in here.entries {
            if off >= self.target_offset {
                break;
            }
            retained.append((off, ext_addr));
            if ext_addr > last_ext_addr {
                last_ext_addr = ext_addr;
            }
        }
        here.entries = retained;
        print(f"[scan] {here.name}: entries after  = {here.entries}");

        # Now ALWAYS truncate the extension store (the fix): traverse the
        # typed MappedTo edge to the matching ConsumeQueueExt.
        self.max_ext_addr = last_ext_addr;
        visit [here ->:MappedTo:->];
    }

    # Truncate the extension store to the last retained address.
    can truncate_ext with ConsumeQueueExt entry {
        cutoff: int = self.max_ext_addr;
        kept: dict[int, int] = {};
        for (addr, tag) in here.units.items() {
            if addr <= cutoff {
                kept[addr] = tag;
            }
        }
        removed: list[int] = [];
        for addr in here.units.keys() {
            if addr > cutoff {
                removed.append(addr);
            }
        }
        here.units = kept;
        here.max_referenced_addr = cutoff;
        print(f"[ext-truncate] {here.name}: dropped {removed}, "
              f"max_referenced_addr={here.max_referenced_addr}");
    }
}

with entry {
    cq = ConsumeQueue(name="queue-0");
    cq_ext = ConsumeQueueExt(name="queue-0-ext");
    cq_ext.units = {
        100: 102,
        200: 202,
        300: 302,
    };
    cq_ext.max_referenced_addr = 300;
    cq.entries = [
        (0, 0),
        (100, 100),
        (200, 200),
        (300, 300),
    ];
    root ++> cq;
    cq +>:MappedTo(slot=0):+> cq_ext;

    # Buggy path: truncate CQ to offset 200, but DON'T touch CQExt.
    print("--- buggy path (CQ only) ---");
    cq.entries = [(0, 0), (100, 100)];
    print(f"after buggy CQ-only truncate: CQ={cq.entries}, "
          f"CQExt={cq_ext.units}");

    # Fixed path: spawn Truncator walker which routes through the ext tail.
    print("--- fixed path (walker) ---");
    cq.entries = [(0, 0), (100, 100), (200, 200), (300, 300)];
    cq_ext.units = {100: 102, 200: 202, 300: 302};
    cq_ext.max_referenced_addr = 300;
    root spawn Truncator(target_offset=200);

    # Show the surviving state: orphan tag 202 is gone, address 200 reusable.
    print(f"final CQ={cq.entries}");
    print(f"final CQExt={cq_ext.units}");
}
```

