    other = Port(name="Remote.other", kind="port");

    root +>:Contains:+> blk;
    root +>:Contains:+> dst;
    root +>:Contains:+> other;
    blk +>:Contains:+> src;
    src +>:ConnectsTo:+> dst;
    other +>:ConnectsTo:+> dst;

    res = src spawn ImpactAnalyzer(query_name="Host.src");

    assert "query: Host.src" in res.findings,
        f"missing query marker: {res.findings}";
    assert "connects: Host.src -> Remote.dst" in res.findings,
        f"missing src outgoing wiring: {res.findings}";
    assert "connects: Remote.other -> Remote.dst" not in res.findings,
        f"sibling port wiring must not be collected: {res.findings}";
    assert len(res.findings) == 2,
        f"expected query plus one connection, got {res.findings}";
}

