    assert res.healthy_count == 0, f"healthy count: {res.healthy_count}";
    assert res.ghost_count == 0, f"ghost count: {res.ghost_count}";
    leaks = len([child ->:LeakedAs:->]);
    assert leaks == 0, f"leak edges: {leaks}";
