"""Migrate codex config: a guard walker that should NOT unconditionally rewrite
the v2 subagent cap.

Models the issue from code-yeongyu/lazycodex#130: the subagent-limit-guard
unconditionally overwrites ``[features.multi_agent_v2] max_concurrent_threads_per_session = 1000``
on every run, with no equivalent of the "hand-removed key stays removed" behavior
that the same guard already implements for the legacy ``agents.max_threads`` path.
"""

node ConfigFile {
    has path: str = "";
    has disabled: bool = False;
}

node ConfigSection {
    has section_name: str = "";
}

node ConfigKey {
    has key_name: str = "";
    has value: str = "";
    has user_overrode: bool = False;
    has hand_removed: bool = False;
}

edge BelongsTo {
    has order: int = 0;
}

edge HoldsKey {
}

walker MigrateSubagentLimits {
    has legacy_cap: str = "4";
    has v2_cap: str = "1000";
    has writes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can consider with ConfigFile entry {
        print(f"considering config file: {here.path} (disabled={here.disabled})");
        if here.disabled {
            print("  migration disabled by env, skipping");
            disengage;
        }
        visit [-->];
    }

    can inspect with ConfigSection entry {
        print(f"  section: [{here.section_name}]");
        visit [->:HoldsKey:->];
    }

    # The bug in v4.17.0: this ability unconditionally writes the v2 cap.
    # The walker models the offending traversal so we can see the side effect.
    can guard_subagent_cap with ConfigKey entry {
        section_name = "features.multi_agent_v2";
        if here.key_name == "max_concurrent_threads_per_session" {
            print(f"    v2 cap key found, current value = {here.value!r}");
        }
        if here.user_overrode {
            note = f"preserved user override on {here.key_name} = {here.value}";
            print(f"    {note}");
            self.writes.append(note);
        } elif here.hand_removed {
            note = f"hand-removed key {here.key_name} stays removed";
            print(f"    {note}");
            self.writes.append(note);
        } else {
            note = f"UNCONDITIONAL WRITE: {section_name} {here.key_name} = {self.v2_cap}";
            print(f"    {note}");
            self.writes.append(note);
        }
    }
}

with entry {
    # A small config graph: one file, two sections, several keys.
    cfg = ConfigFile(path="/home/user/.codex/config.toml", disabled=False);
    root ++> cfg;

    ma_section = ConfigSection(section_name="agents");
    v2_section = ConfigSection(section_name="features.multi_agent_v2");
    cfg +>:BelongsTo(order=1):+> ma_section;
    cfg +>:BelongsTo(order=2):+> v2_section;

    # Legacy cap: user has set a hand-tuned value, must be preserved.
    ma_section +>:HoldsKey:+> ConfigKey(
        key_name="max_threads",
        value="8",
        user_overrode=True,
        hand_removed=False
    );

    # V2 cap: user has DELETED this key to opt out — current code re-writes it.
    v2_section +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="",
        user_overrode=False,
        hand_removed=True
    );

    # V2 cap on a different model: absent entirely, never written by user.
    v2_section +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="",
        user_overrode=False,
        hand_removed=False
    );

    # Run the offending guard walker.
    guard = MigrateSubagentLimits();
    cfg spawn guard;

    print("\nmigration writes performed:");
    for w in guard.writes {
        print(f"  - {w}");
    }
}
```

jac_tests:
"""Tests for the subagent-limit-guard migration walker.

Issue #130: the guard unconditionally rewrites
[features.multi_agent_v2] max_concurrent_threads_per_session = 1000,
overriding user opt-outs (hand_removed) and silently re-injecting the
key even when the user explicitly deleted it.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. Hand-removed v2 cap must STAY removed (the core #130 complaint).
# ---------------------------------------------------------------------------
test "hand-removed v2 cap is preserved, not rewritten" {
    cfg = ConfigFile(path="/u/.codex/config.toml", disabled=False);
    root ++> cfg;

    v2 = ConfigSection(section_name="features.multi_agent_v2");
    cfg +>:BelongsTo(order=1):+> v2;

    v2 +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="",
        user_overrode=False,
        hand_removed=True
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        guard = MigrateSubagentLimits();
        cfg spawn guard;
    }

    joined = "\n".join(guard.writes);
    assert "stays removed" in joined, f"hand-removed key not preserved: writes={guard.writes}";
    # The buggy behavior we're guarding against: a hard UNCONDITIONAL WRITE.
    assert "UNCONDITIONAL WRITE" not in joined, (
        f"v2 cap was unconditionally rewritten despite user opt-out: writes={guard.writes}"
    );
    # The constant "1000" must not appear as a write target for this key.
    assert "= 1000" not in joined, (
        f"v2 cap value 1000 was re-injected: writes={guard.writes}"
    );
}

# ---------------------------------------------------------------------------
# 2. Existing user override on the v2 cap is honored, never clobbered.
# ---------------------------------------------------------------------------
test "user override on v2 cap is not overwritten" {
    cfg = ConfigFile(path="/u/.codex/config.toml", disabled=False);
    root ++> cfg;

    v2 = ConfigSection(section_name="features.multi_agent_v2");
    cfg +>:BelongsTo(order=1):+> v2;

    # User explicitly chose cap=4 (Codex stock default they want to keep).
    v2 +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="4",
        user_overrode=True,
        hand_removed=False
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        guard = MigrateSubagentLimits();
        cfg spawn guard;
    }

    joined = "\n".join(guard.writes);
    assert "preserved user override" in joined, (
        f"user override not respected: writes={guard.writes}"
    );
    assert "UNCONDITIONAL WRITE" not in joined, (
        f"user value was clobbered by unconditional write: writes={guard.writes}"
    );
    # The user's chosen value must survive verbatim in the log.
    assert "= 4" in joined, f"user's value 4 not surfaced: writes={guard.writes}";
    assert "= 1000" not in joined, (
        f"override was overwritten with 1000: writes={guard.writes}"
    );
}

# ---------------------------------------------------------------------------
# 3. Disabled config skips ALL writes, including the offending v2 write.
# ---------------------------------------------------------------------------
test "disabled config produces no writes at all" {
    cfg = ConfigFile(path="/u/.codex/config.toml", disabled=True);
    root ++> cfg;

    v2 = ConfigSection(section_name="features.multi_agent_v2");
    cfg +>:BelongsTo(order=1):+> v2;

    v2 +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session",
        value="",
        user_overrode=False,
        hand_removed=False
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        guard = MigrateSubagentLimits();
        cfg spawn guard;
    }

    out = buf.getvalue();
    assert "migration disabled" in out, (
        f"disabled-flag not honored, stdout={out!r}"
    );
    assert len(guard.writes) == 0, (
        f"disabled config still produced writes: {guard.writes}"
    );
}

# ---------------------------------------------------------------------------
# 4. Legacy agents.max_threads override is preserved too (regression guard
#    so a fix to v2 doesn't break the v1 path).
# ---------------------------------------------------------------------------
test "legacy agents.max_threads override is also preserved" {
    cfg = ConfigFile(path="/u/.codex/config.toml", disabled=False);
    root ++> cfg;

    ma = ConfigSection(section_name="agents");
    cfg +>:BelongsTo(order=1):+> ma;

    ma +>:HoldsKey:+> ConfigKey(
        key_name="max_threads",
        value="8",
        user_overrode=True,
        hand_removed=False
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        guard = MigrateSubagentLimits();
        cfg spawn guard;
    }

    joined = "\n".join(guard.writes);
    assert "preserved user override on max_threads = 8" in joined, (
        f"legacy override not preserved: writes={guard.writes}"
    );
    assert "UNCONDITIONAL WRITE" not in joined, (
        f"legacy key got an unconditional write: writes={guard.writes}"
    );
}

# ---------------------------------------------------------------------------
# 5. Mixed graph: multiple v2 keys + legacy key — every opt-out is honored.
# ---------------------------------------------------------------------------
test "mixed graph honors every user opt-out" {
    cfg = ConfigFile(path="/u/.codex/config.toml", disabled=False);
    root ++> cfg;

    ma = ConfigSection(section_name="agents");
    v2 = ConfigSection(section_name="features.multi_agent_v2");
    cfg +>:BelongsTo(order=1):+> ma;
    cfg +>:BelongsTo(order=2):+> v2;

    ma +>:HoldsKey:+> ConfigKey(
        key_name="max_threads", value="8",
        user_overrode=True, hand_removed=False
    );
    v2 +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session", value="",
        user_overrode=False, hand_removed=True
    );
    v2 +>:HoldsKey:+> ConfigKey(
        key_name="max_concurrent_threads_per_session", value="",
        user_overrode=False, hand_removed=False
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        guard = MigrateSubagentLimits();
        cfg spawn guard;
    }

    # Three writes expected: one preserved override + one stays-removed + one
    # unconditional write for the truly-absent key. The bug is that the
    # *hand_removed* one ALSO gets an unconditional write — verify it doesn't.
    assert len(guard.writes) == 3, (
        f"expected 3 writes (override, stays-removed, unconditional), "
        f"got {len(guard.writes)}: {guard.writes}"
    );

    hand_removed_notes = [w for w in guard.writes if "stays removed" in w];
    override_notes = [w for w in guard.writes if "preserved user override" in w];
    unconditional = [w for w in guard.writes if "UNCONDITIONAL WRITE" in w];

    assert len(hand_removed_notes) == 1, (
        f"hand-removed key not honored: {guard.writes}"
    );
    assert len(override_notes) == 1, (
        f"user override not honored: {guard.writes}"
    );
    assert len(unconditional) == 1, (
        f"absent key should still get the default write: {guard.writes}"
    );

    # Cross-check: the hand-removed write must NOT be the unconditional one.
    assert "UNCONDITIONAL WRITE" not in hand_removed_notes[0], (
        f"hand-removed key was unconditionally rewritten: {guard.writes}"
    );
    assert "max_concurrent_threads_per_session = 1000" in unconditional[0], (
        f"absent-key default write missing or wrong value: {guard.writes}"
    );
}

