        outputs_intact=True
    );
    eval_stage = Stage(
        name="eval",
        input_hash="h_eval_in",
        recorded_hash="h_eval_in",
        outputs_intact=True
    );
    root +>:StageLink:+> features +>:StageLink:+> train +>:StageLink:+> eval_stage;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IntegrityAudit();
    }
