    fp = ForkPoint(label="at-c2");
    c2 +>:Parent:+> fp +>:Parent:+> Commit(title="c2b", seq=21);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HistoryReplay();
    }
