    assert res.transcript_seen == "session-1", f"got {res.transcript_seen}";
    assert res.path[-1][0] == "assistant", f"got {res.path}";
    assert res.path[-1][1] == True, f"got {res.path}";
}

test "approval walks transcript messages in order" {
    t = Transcript(name="ordered", approved=True);
    first = Message(role="system", content="context", persisted=True);
    second = Message(role="user", content="request", persisted=True);
    final = Message(role="assistant", content="answer", persisted=True);

    root +>:OwnedBy:+> t;
    t +>:Follows:+> first;
    t +>:Follows:+> second;
    t +>:Follows:+> final;

    res = root spawn ApprovalWalk();

    assert len(res.path) == 3, f"got {res.path}";
    assert res.path[0][0] == "system", f"got {res.path}";
    assert res.path[1][0] == "user", f"got {res.path}";
    assert res.path[2][0] == "assistant", f"got {res.path}";
}

test "cost ceiling clamps expensive plan step" {
    t = Transcript(name="budgeted", approved=True, over_budget=True);
    expensive = PlanStep(title="ship", est_cost=620.0);
    t +>:StepOf:+> expensive;

    res = expensive spawn ApprovalWalk();

    assert expensive.est_cost == 500.0, f"got {expensive.est_cost}";
    assert res.path[0][0] == "step", f"got {res.path}";
    assert res.path[0][1] == "ship", f"got {res.path}";
}

