import io;
import from contextlib { redirect_stdout }

test "superseded source files are invalidated" {
    src = Directory(path="src/");
    foo = SourceFile(path="src/foo.py", sha256="abc123", durable=True);
    root ++> src;
    src +>:Contains:+> foo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InvalidationCascade(superseded_sha="abc123");
    }
    out = buf.getvalue();
    assert not foo.durable, f"expected durable=False got {foo.durable}";
    assert foo.sha256 == "PENDING_RECOMPUTE", f"got sha={foo.sha256}";
    assert "src/foo.py" in res.invalidated, f"got invalidated={res.invalidated}";
    assert "superseding src/foo.py" in out, f"missing supersede marker: {out}";
}

test "non-superseded source files are kept" {
    src = Directory(path="src/");
    baz = SourceFile(path="src/baz.py", sha256="def456", durable=True);
    root ++> src;
    src +>:Contains:+> baz;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InvalidationCascade(superseded_sha="abc123");
    }
    out = buf.getvalue();
    assert baz.durable, f"expected durable=True got {baz.durable}";
    assert baz.sha256 == "def456", f"got sha={baz.sha256}";
    assert "src/baz.py" not in res.invalidated, f"got invalidated={res.invalidated}";
    assert "kept src/baz.py" in out, f"missing kept marker: {out}";
}

test "cycle guard skips guarded paths" {
    src = Directory(path="src/");
    tests = Directory(path="src/tests/");
    foo = SourceFile(path="src/foo.py", sha256="abc123", durable=True);
    bar = SourceFile(path="src/tests/bar.py", sha256="abc123", durable=True);
    root ++> src ++> tests;
    src +>:Contains:+> foo;
    tests +>:Contains:+> bar;
    foo +>:Admits(admitted_at="2026-01-15T00:00:00Z", bundle_v2=True):+> bar;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InvalidationCascade(
            superseded_sha="abc123",
            guard=["src/tests/bar.py"]
        );
    }
    out = buf.getvalue();
    assert not foo.durable, f"foo should be invalidated got durable={foo.durable}";
    assert foo.sha256 == "PENDING_RECOMPUTE", f"foo sha should be pending got {foo.sha256}";
    assert bar.durable, f"guarded bar should stay durable got {bar.durable}";
    assert bar.sha256 == "abc123", f"guarded bar sha should be unchanged got {bar.sha256}";
    assert "src/foo.py" in res.invalidated, f"got invalidated={res.invalidated}";
    assert "src/tests/bar.py" not in res.invalidated, f"got invalidated={res.invalidated}";
    assert "cycle guard hit on src/tests/bar.py" in out, f"missing guard marker: {out}";
}

test "manifest metadata is source-semantic-inert" {
    src = Directory(path="src/");
    manifest = Manifest(
        path="manifest.yaml",
        distribution_channel="nightly",
        version="0.1.0"
    );
    root ++> src;
    src +>:Describes:+> manifest;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn InvalidationCascade(superseded_sha="abc123");
    }
    out = buf.getvalue();
    assert "source-semantic-inert" in out, f"missing inert marker: {out}";
    assert "manifest.yaml" in out, f"missing manifest path in output: {out}";
    assert manifest.distribution_channel == "nightly", f"channel mutated: {manifest.distribution_channel}";
    assert manifest.version == "0.1.0", f"version mutated: {manifest.version}";
}

test "invalidation cascades through directory trie subtrees" {
    src_dir = Directory(path="src/", owner="core");
    tests_dir = Directory(path="src/tests/", owner="core");
    dist_dir = Directory(path="dist/", owner="release");
    foo = SourceFile(path="src/foo.py", sha256="abc123", durable=True);
    bar = SourceFile(path="src/tests/bar.py", sha256="abc123", durable=True);
    baz = SourceFile(path="src/baz.py", sha256="def456", durable=True);

    root ++> src_dir ++> tests_dir ++> dist_dir;
    src_dir +>:Contains:+> foo;
    src_dir +>:Contains:+> baz;
    tests_dir +>:Contains:+> bar;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InvalidationCascade(
            superseded_sha="abc123",
            guard=["src/tests/bar.py"]
        );
    }
    out = buf.getvalue();
    assert len([root-->]) == 1, f"root should have one direct child got {len([root-->])}";
    assert "walking subtree src/" in out, f"missing src subtree walk: {out}";
    assert "walking subtree src/tests/" in out, f"missing tests subtree walk: {out}";
    assert "walking subtree dist/" in out, f"missing dist subtree walk: {out}";
    assert "src/foo.py" in res.invalidated, f"foo should be invalidated got {res.invalidated}";
    assert "src/tests/bar.py" not in res.invalidated, f"bar should be guarded got {res.invalidated}";
    assert "src/baz.py" not in res.invalidated, f"baz should be kept got {res.invalidated}";
    assert baz.durable, f"baz durable should remain True got {baz.durable}";
    assert baz.sha256 == "def456", f"baz sha should be unchanged got {baz.sha256}";
}

