    p2 = WindowsProfile(profile_id="win-cfg-002", name="Defender Policy");
    r +>:OwnsProfile:+> h;
    h +>:OwnsProfile:+> p1;
    h +>:OwnsProfile:+> p2;

    f1 = FailedRemoval(detail="Failed to remove: timeout from MDM channel", status="failed");
    f2 = FailedRemoval(detail="Failed to remove: access denied (0x80070005)", status="failed");
    f3 = FailedRemoval(detail="Failed to remove: bad signature", status="failed", dismissed=True);
    p1 +>:Removes(attempted_at="2025-03-14T10:22:00Z"):+> f1;
    p1 +>:Removes(attempted_at="2025-03-15T08:05:00Z"):+> f2;
    p2 +>:Removes(attempted_at="2025-03-16T09:00:00Z"):+> f3;

    clearer = DismissFailed(target_detail="");
    r spawn clearer;
    assert clearer.cleared == 2, f"expected 2 dismissed, got {clearer.cleared}";
    assert f1.dismissed, "f1 should be dismissed";
    assert f2.dismissed, "f2 should be dismissed";
    assert f3.dismissed, "f3 was already dismissed; must stay dismissed";

