import io;
import from contextlib { redirect_stdout }

test "typed resource edges preserve graph shape" {
    position = Resource(name="Position");
    movement = System(name="movement");
    root ++> position;
    movement +>:Reads:+> position;
    movement +>:Writes:+> position;
    assert len([root-->]) == 1, f"got {len([root-->])}";
    assert position in [root-->], f"missing position child";
    reads = [movement ->:Reads:->];
    writes = [movement ->:Writes:->];
