test "scheduler follows run-after edges and records safe groups" {
    first = System(name="first", parallel_safe=True);
    second = System(name="second", parallel_safe=False);
    root ++> first;
    root ++> second;
    first +>:RunsAfter:+> second;
    run_after = [first ->:RunsAfter:->];
    assert len(run_after) == 1, f"got {len(run_after)}";
    assert second in run_after, f"missing run-after target";
    sched = Scheduler();
    root spawn sched;
    assert sched.order == ["first", "second"], f"got {sched.order}";
    assert sched.parallel_groups == [["first"]], f"got {sched.parallel_groups}";
    assert len(sched.cycle_path) == 0, f"got {sched.cycle_path}";
}

test "resource and system defaults are honored" {
    resource = Resource();
    system = System();
    root ++> resource;
    root ++> system;
    assert resource.name == "", f"got {resource.name}";
    assert resource.mutable == True, f"got {resource.mutable}";
    assert system.name == "", f"got {system.name}";
    assert system.parallel_safe == True, f"got {system.parallel_safe}";
}

test "cascade walker prints each reachable system" {
    source = System(name="source");
    sink = System(name="sink");
    root ++> source;
    root ++> sink;
    dependency = Resource(name="State");
    source +>:Reads:+> dependency;
