test "retains schema and family counts without dependencies" {
    cli = CommandFamily(
        name="cli", library_name="ark_cli", is_cli_assembly=True
    );
    export = CommandFamily(name="export", library_name="ark_export");
    root +>:Owns(since="v1"):+> cli;
    root +>:Owns(since="v1"):+> export;

    cli_root = Command(name="ark", is_schema_generated=True, owner_family="cli");
    export_run = Command(name="export.run", owner_family="export");
    cli +>:Owns(since="v1"):+> cli_root;
    export +>:Owns(since="v1"):+> export_run;

    res = root spawn BuildAuditor();

    assert len(res.visited_families) == 2, f"families: {len(res.visited_families)}";
    assert res.schema_hits == 1, f"schema hits: {res.schema_hits}";
    assert res.within_family_edges == 0, f"within edges: {res.within_family_edges}";
    assert res.cross_family_edges == 0, f"cross edges: {res.cross_family_edges}";
}

