"""Regression tests for the CVE-2026-22745 vulnerable dependency graph."""

import io;
import from contextlib { redirect_stdout }

test "VulnerabilityScanner flags only vulnerable artifacts" {
    root ++> Artifact(gav="org.springframework.boot:spring-boot-starter-web",
                      version="3.0.3");
    webmvc = Artifact(gav="org.springframework:spring-webmvc",
                      version="6.0.5",
                      vulnerable=True);
    safe = Artifact(gav="org.springframework:spring-context",
                    version="6.0.5",
                    vulnerable=False);
    root +>:DependsOn:+> webmvc;
    root +>:DependsOn:+> safe;

    scanner = VulnerabilityScanner();
    res = root spawn scanner;

    assert len(res.findings) == 1, f"expected exactly 1 vulnerable hit, got {len(res.findings)}";
    assert res.findings[0].gav == "org.springframework:spring-webmvc", f"unexpected gav: {res.findings[0].gav}";
    assert res.findings[0].version == "6.0.5", f"unexpected version: {res.findings[0].version}";
    assert res.findings[0].vulnerable is True, "flagged node must be marked vulnerable";
}

test "VulnerabilityScanner follows DependsOn chain transitively" {
    root ++> Artifact(gav="root-app", version="1.0.0");
    a = Artifact(gav="a", version="1.0", vulnerable=True);
    b = Artifact(gav="b", version="1.0", vulnerable=True);
    c = Artifact(gav="c", version="1.0", vulnerable=False);
    d = Artifact(gav="d", version="1.0", vulnerable=False);
    root +>:DependsOn:+> a;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;
    c +>:DependsOn:+> d;

    scanner = VulnerabilityScanner();
    res = root spawn scanner;

    gavs = sorted([f.gav for f in res.findings]);
    assert gavs == ["a", "b"], f"transitive scan must visit vulnerable descendants, got {gavs}";
}

test "VulnerabilityScanner returns empty findings on clean graph" {
    root ++> Artifact(gav="root", version="1.0");
    a = Artifact(gav="a", version="1.0");
    b = Artifact(gav="b", version="1.0");
    root +>:DependsOn:+> a;
    a +>:DependsOn:+> b;

    scanner = VulnerabilityScanner();
    res = root spawn scanner;

    assert len(res.findings) == 0, f"clean graph must yield zero findings, got {len(res.findings)}";
}

test "DependencyReport prints vuln markers and visits every artifact" {
    root ++> Artifact(gav="org.springframework.boot:spring-boot-starter-web",
                      version="3.0.3");
    webmvc = Artifact(gav="org.springframework:spring-webmvc",
                      version="6.0.5",
                      vulnerable=True);
    context = Artifact(gav="org.springframework:spring-context",
                       version="6.0.5");
    root +>:DependsOn:+> webmvc;
    webmvc +>:DependsOn:+> context;

    buf = io.StringIO();
    reporter = DependencyReport();
    with redirect_stdout(buf) {
        res = root spawn reporter;
    }
    out = buf.getvalue();

    assert "[VULN]" in out, f"VULN marker missing from report: {out}";
    assert "[ok]" in out, f"ok marker missing from report: {out}";
    assert "spring-webmvc:6.0.5" in out, f"webmvc row missing: {out}";
    assert "spring-context:6.0.5" in out, f"context row missing: {out}";
    assert len(res.scanned) == 3, f"expected 3 artifacts scanned (root + 2), got {len(res.scanned)}";
}

test "Artifact defaults: vulnerable False and empty gav/version" {
    n = Artifact();
    assert n.vulnerable is False, f"default vulnerable must be False, got {n.vulnerable}";
    assert n.gav == "", f"default gav must be empty, got {n.gav}";
    assert n.version == "", f"default version must be empty, got {n.version}";
}

