        version="6.0.4",
    );
    root +>:DependsOn:+> parent;
    parent +>:DependsOn:+> leaf;
    parent +>:DependsOn:+> safe;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();
    assert "[VULN]" in out, f"missing vuln in transitive walk: {out}";
    assert len(res.findings) == 1, f"expected 1 finding, got {len(res.findings)}";
    (g, a, v, c) = res.findings[0];
    assert a == "spring-webmvc", f"wrong vulnerable artifact: {a}";
    assert c == "CVE-2026-22745", f"wrong CVE on finding: {c}";
    assert "spring-jdbc" in out, f"safe sibling should be audited: {out}";
}

