import io;
import from contextlib { redirect_stdout }

test "reparent leaf updates path and depth" {
    a = Collection(title="A", path="/A", depth=1);
    root ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Reparentor(new_parent_path="/B", new_parent_depth=1);
    }

    assert res.failed_reason == "", f"reparent failed: {res.failed_reason}";
    assert a.path == "/B", f"unexpected path: {a.path}";
    assert a.depth == 1, f"unexpected depth: {a.depth}";
}

test "reparent rejects a descendant target cycle" {
    a = Collection(title="A", path="/A", depth=1);
    a1 = Collection(title="A1", path="/A/A1", depth=2);
    root ++> a;
    a +>:Child(order=1):+> a1;

    res = root spawn Reparentor(
        new_parent_path="/A/A1",
        new_parent_depth=2
    );

    assert res.failed_reason == "cycle: target is within subtree",
        f"unexpected cycle result: {res.failed_reason}";
    assert a.path == "/A", f"source path changed: {a.path}";
    assert a1.path == "/A/A1", f"descendant path changed: {a1.path}";
}

test "reparent rejects depth beyond ten" {
    a = Collection(title="A", path="/A", depth=1);
    root ++> a;

    res = root spawn Reparentor(
        new_parent_path="/TOO-DEEP",
        new_parent_depth=11
    );

    assert res.failed_reason == "depth cap exceeded",
        f"unexpected depth result: {res.failed_reason}";
    assert a.path == "/A", f"path changed after rejection: {a.path}";
    assert a.depth == 1, f"depth changed after rejection: {a.depth}";
}

test "cascade tombstones only the selected subtree" {
    a = Collection(title="A", path="/A", depth=1);
    a1 = Collection(title="A1", path="/A/A1", depth=2);
    a2 = Collection(title="A2", path="/A/A2", depth=2);
    b = Collection(title="B", path="/B", depth=1);

    root ++> a;
    root ++> b;
    a +>:Child(order=1):+> a1;
    a +>:Child(order=2):+> a2;

    marker = "2026-08-27T00:00:00Z";
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CascadeDelete(
            marker=marker,
            subtree_root_path="/A"
        );
