    assert len(res.tombstoned) == 3, f"tombstones: {res.tombstoned}";
    assert "A" in res.tombstoned, f"missing A: {res.tombstoned}";
    assert "A1" in res.tombstoned, f"missing A1: {res.tombstoned}";
    assert "A2" in res.tombstoned, f"missing A2: {res.tombstoned}";
    assert a.deleted_at == marker, f"A tombstone: {a.deleted_at}";
    assert a1.deleted_at == marker, f"A1 tombstone: {a1.deleted_at}";
    assert a2.deleted_at == marker, f"A2 tombstone: {a2.deleted_at}";
    assert b.deleted_at == "", f"outside collection deleted: {b.deleted_at}";
    assert res.days_in_trash == 30, f"trash retention: {res.days_in_trash}";
