"""Awkward-schema catalog validator.

Models the v2 catalog API as a graph of tables, columns, keys, and
references. A walker performs the cascade-delete / invalidation /
dependency-ordering traversal that the issue describes, but expressed
in idiomatic Jac with typed edges instead of hand-rolled recursion
over id-keyed registries.
"""

node Column {
    has col_name: str = "";
    has col_type: str = "";
    has nullable: bool = True;
    has is_blob: bool = False;
}

node Table {
    has table_name: str = "";
    has arity: int = 0;
    has is_view: bool = False;
}

node Key {
    has key_name: str = "";
    has is_compound: bool = False;
}

node Schema {
    has schema_name: str = "";
}

edge HasColumn { }
edge HasKey { }
edge References { has on_delete: str = "RESTRICT"; }
edge OwnsTable { }

walker CatalogAuditor {
    has seen: list[str] = [];
    has cycle_detected: bool = False;
    has deleted_count: int = 0;
    has orphan_count: int = 0;
    has dead_ref_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Schema entry {
        print(f"[schema] {here.schema_name}");
        visit [->:OwnsTable:->];
    }

    can audit_table with Table entry {
        if here.table_name in self.seen {
            self.cycle_detected = True;
            print(f"  [cycle] table revisited: {here.table_name}");
            disengage;
        }
        self.seen.append(here.table_name);
        status = "VIEW" if here.is_view else "TABLE";
        print(f"  [{status}] {here.table_name} (arity={here.arity})");
        visit [->:HasColumn:->] else {
            visit [->:References:->];
        }
    }

    can audit_column with Column entry {
        kind = "BLOB" if here.is_blob else here.col_type;
        null_mark = "?" if here.nullable else "!";
        print(f"    - {here.col_name}: {kind}{null_mark}");
        visit [->:References:->] else {
            disengage;
        }
    }

    can chase_ref with Column | Table entry {
        target = [-->];
        if not target {
            self.dead_ref_count += 1;
            print(f"    [dead-ref] dangling reference from {here}");
            disengage;
        }
        visit target;
    }

    can catalog_key with Key entry {
        flag = "compound" if here.is_compound else "simple";
        print(f"  [key:{flag}] {here.key_name}");
        visit [-->] else { disengage; }
    }

    can purge with Schema entry {
        self.deleted_count = len([-->]);
        print(f"[purge] marking {self.deleted_count} owned tables invalid");
        for t in [->:OwnsTable:->] {
            del t;
            self.orphan_count += 1;
        }
        print(f"[purge] orphaned {self.orphan_count} table nodes");
    }
}

with entry {
    northwind = Schema(schema_name="northwind");
    awkward = Schema(schema_name="awkward");

    t_unicode = Table(table_name="Ünïcödé", arity=3);
    t_reserved = Table(table_name="select", arity=2);
    t_selfref = Table(table_name="employee", arity=5);
    t_mutual_a = Table(table_name="order_a", arity=4);
    t_mutual_b = Table(table_name="order_b", arity=4);
    t_blob = Table(table_name="blobs", arity=2);
    t_view = Table(table_name="v_summary", arity=2, is_view=True);
    t_high = Table(table_name="wide", arity=120);

    northwind +>:OwnsTable:+> t_unicode;
    northwind +>:OwnsTable:+> t_reserved;
    northwind +>:OwnsTable:+> t_selfref;
    northwind +>:OwnsTable:+> t_mutual_a;
    northwind +>:OwnsTable:+> t_mutual_b;
    northwind +>:OwnsTable:+> t_blob;
    northwind +>:OwnsTable:+> t_view;
    awkward +>:OwnsTable:+> t_high;

    c_unicode = Column(col_name="naïve", col_type="TEXT");
    c_reserved = Column(col_name="from", col_type="INT", nullable=False);
    c_blob = Column(col_name="payload", col_type="BLOB", nullable=False, is_blob=True);
    c_blob_opt = Column(col_name="thumb", col_type="BLOB");
    c_view_a = Column(col_name="total", col_type="NUMERIC");
    c_view_b = Column(col_name="label", col_type="TEXT");
    c_high_a = Column(col_name="col_000", col_type="INT", nullable=False);

    t_unicode +>:HasColumn:+> c_unicode;
    t_reserved +>:HasColumn:+> c_reserved;
    t_blob +>:HasColumn:+> c_blob;
    t_blob +>:HasColumn:+> c_blob_opt;
    t_view +>:HasColumn:+> c_view_a;
    t_view +>:HasColumn:+> c_view_b;
    t_high +>:HasColumn:+> c_high_a;

    k_emp = Key(key_name="pk_employee", is_compound=False);
    k_order = Key(key_name="pk_order", is_compound=True);
    t_selfref +>:HasKey:+> k_emp;
    t_mutual_a +>:HasKey:+> k_order;

    c_reserved +>:References(on_delete="RESTRICT"):+> c_unicode;
    c_unicode +>:References:+> c_reserved;
    c_blob +>:References:+> c_blob_opt;
    c_view_a +>:References:+> c_view_b;

    root ++> northwind ++> awkward;

    auditor = CatalogAuditor();
    root spawn auditor;
    print(
        f"audit done — seen={len(auditor.seen)} "
        f"cycle={auditor.cycle_detected} "
        f"dead_refs={auditor.dead_ref_count}"
    );

    purger = CatalogAuditor();
    northwind spawn purger;
    print(
        f"purge done — deleted={purger.deleted_count} "
        f"orphaned={purger.orphan_count}"
    );
}
