import io;
import from contextlib { redirect_stdout }

test "unresolved lists only unavailable arm64 blockers" {
    plat = Platform(arch="win-arm64", env_file="environment-dev-win-arm64.yml");
    root ++> plat;
    missing = Package(name="cryptography", category="noarch-blocked", available_on_arm64=False);
    ready_pkg = Package(name="pytest-xprocess", category="ready", available_on_arm64=True);
    plat +>:Blocks(reason="no win-arm64 build"):+> missing;
    plat +>:Blocks(reason="already solvable"):+> ready_pkg;

    res = root spawn ReleaseHunter();
    assert "cryptography" in res.unresolved, f"missing blocker: {res.unresolved}";
    assert "pytest-xprocess" not in res.unresolved, f"ready package should not block: {res.unresolved}";
    assert len(res.unresolved) == 1, f"expected one unresolved package: {res.unresolved}";
}

test "walker collects still-skipped tests via TestDependsOn" {
    plat = Platform(arch="win-arm64", env_file="environment-dev-win-arm64.yml");
    root ++> plat;
    mitm = Package(name="mitmproxy", category="noarch-blocked", available_on_arm64=False);
    skipped = Test(
        name="micromamba/tests/test_proxy.py",
        skip_mechanism="pytest.skip",
        still_skipped=True,
    );
    plat +>:Blocks(reason="mitmproxy unsolvable without cryptography"):+> mitm;
    mitm +>:TestDependsOn:+> skipped;

    res = root spawn ReleaseHunter();
    assert skipped.name in res.blocked_tests, f"expected skipped proxy test: {res.blocked_tests}";
    assert len(res.blocked_tests) == 1, f"expected one blocked test: {res.blocked_tests}";
}

test "ready_to_unify false while blockers remain" {
    arm_env = EnvFile(filename="environment-dev-win-arm64.yml", unified=False);
    plat = Platform(arch="win-arm64", env_file="environment-dev-win-arm64.yml");
    root ++> plat;
    blocker = Package(name="binutils", category="compiled", available_on_arm64=False);
    plat +>:Blocks(reason="no win-arm64 build"):+> blocker;
    plat +>:UsesEnv:+> arm_env;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseHunter();
    }
    assert not res.ready_to_unify, f"should wait on blockers: unresolved={res.unresolved}";
    assert len(res.unresolved) == 1, f"expected binutils unresolved: {res.unresolved}";
    out = buf.getvalue();
    assert "[WAIT]" in out, f"missing WAIT marker: {out}";
}

test "ready_to_unify true when packages resolve and main env unified" {
    main_env = EnvFile(filename="environment-dev.yml", unified=True);
    plat = Platform(arch="win-arm64", env_file="environment-dev.yml");
    root ++> plat;
    solved = Package(name="mypy", category="compiled", available_on_arm64=True);
    plat +>:Blocks(reason="now published on conda-forge"):+> solved;
    plat +>:UsesEnv:+> main_env;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReleaseHunter();
    }
    assert res.ready_to_unify, f"expected unify ready: unresolved={res.unresolved}";
    assert len(res.unresolved) == 0, f"expected no unresolved packages: {res.unresolved}";
    out = buf.getvalue();
    assert "[OK]" in out, f"missing OK marker: {out}";
}

test "unified env still waits while compiled packages missing" {
    main_env = EnvFile(filename="environment-dev.yml", unified=True);
    plat = Platform(arch="win-arm64", env_file="environment-dev.yml");
    root ++> plat;
    blocker = Package(name="doxygen", category="compiled", available_on_arm64=False);
    plat +>:Blocks(reason="no win-arm64 build"):+> blocker;
    plat +>:UsesEnv:+> main_env;

    res = root spawn ReleaseHunter();
    assert not res.ready_to_unify, f"unified env must still wait: {res.unresolved}";
    assert "doxygen" in res.unresolved, f"expected doxygen blocker: {res.unresolved}";
}

