test "stops safely when attachment relationships contain a cycle" {
    first = Attachment(name="First", bytes_per_pixel=4.0, frames_in_flight=2);
    second = Attachment(name="Second", bytes_per_pixel=4.0, frames_in_flight=2);
    row = GBufferDocRow(label="Cyclic G-buffer", claimed_mb_1080p=1.0,
                        claimed_mb_4k=1.0);

    row +>:Sized:+> first;
    first +>:Sized:+> second;
    second +>:Sized:+> first;

    res = row spawn VramAuditor();

    assert len(res.visited) == 2, f"visited {res.visited}";
