"""GPU timer bracket coverage: model the four per-frame GPU work items that
sit outside every `gpu_timers` bracket and walk them with a CoverageAudit
walker to surface the missing instrumentation.

Entities (nodes):
  * GpuBracket — a named timer bracket that wraps some GPU work.
  * GpuWork    — a per-frame GPU work item (dispatch, copy, render pass).
Edges:
  * BracketCovers — a bracket wraps a work item (typed edge, payload = start_line).
Walkers:
  * CoverageAudit — walks BracketCovers edges from each bracket to report
    which work items are covered.
  * FindUnbracketed — walks every node from Root and flags work items that
    are NOT reachable via any BracketCovers edge (the bug).
"""

node GpuBracket {
    has name: str = "";
    has slot: int = 0;
}

node GpuWork {
    has label: str = "";
    has work_kind: str = "";
    has file: str = "";
    has line: int = 0;
}

edge BracketCovers {
    has start_line: int = 0;
}

walker CoverageAudit {
    has bracketed: list = [];
    has visited: list = [];

    can start with Root entry {
        self.visited = [];
        visit [-->];
    }

    can audit_brackets with GpuBracket entry {
        here_id = str(here);
        if here_id not in self.visited {
            self.visited.append(here_id);
        }
        print(f"bracket[{here.slot}] {here.name}");
        visit [->:BracketCovers:->];
    }

    can audit_work with GpuWork entry {
        record = {
            "label": here.label,
            "kind": here.work_kind,
            "file": here.file,
            "line": here.line,
        };
        self.bracketed.append(record);
        print(f"  covered: {here.label} ({here.work_kind}) @ {here.file}:{here.line}");
    }
}

walker FindUnbracketed {
    has unbracketed: list = [];
    has bracketed: list = [];
    has visited: list = [];

    can start with Root entry {
        self.visited = [];
        visit [-->];
    }

    can scan with GpuWork entry {
        here_id = str(here);
        if here_id not in self.visited {
            self.visited.append(here_id);
        }
        record = {
            "label": here.label,
            "kind": here.work_kind,
            "file": here.file,
            "line": here.line,
        };
        self.unbracketed.append(record);
        print(f"  UNBRACKETED: {here.label} ({here.work_kind}) @ {here.file}:{here.line}");
    }

    can pass_bracket with GpuBracket entry {
        here_id = str(here);
        if here_id not in self.visited {
            self.visited.append(here_id);
        }
    }
}

with entry {
    skin_dispatch_bracket = GpuBracket(name="skin_dispatch_ms", slot=0);
    copy_depth_bracket    = GpuBracket(name="copy_depth_to_history", slot=2);

    skin_vertices_loop = GpuWork(
        label="skin_vertices.comp dispatch loop",
        work_kind="skin_dispatch_loop",
        file="crates/renderer/src/vulkan/context/skinned_blas_refit.rs",
        line=379,
    );
    copy_depth_work = GpuWork(
        label="copy_depth_to_history",
        work_kind="transfer_copy",
        file="crates/renderer/src/vulkan/context/draw.rs",
        line=2536,
    );

    bone_world_copy = GpuWork(
        label="bone_world SSBO copy",
        work_kind="transfer_copy",
        file="crates/renderer/src/vulkan/context/draw.rs",
        line=2496,
    );
    bind_inverse_copies = GpuWork(
        label="bind_inverse SSBO copies",
        work_kind="transfer_copy",
        file="crates/renderer/src/vulkan/context/draw.rs",
        line=2520,
    );
    skin_palette_dispatch = GpuWork(
        label="skin_palette.comp dispatch (full bone range)",
        work_kind="palette_dispatch",
        file="crates/renderer/src/vulkan/context/draw.rs",
