    skin_dispatch_bracket +>:BracketCovers(start_line=379):+> skin_vertices_loop;
    copy_depth_bracket +>:BracketCovers(start_line=2536):+> copy_depth_work;

    root ++> skin_dispatch_bracket
        ++> copy_depth_bracket
        ++> bone_world_copy
        ++> bind_inverse_copies
        ++> skin_palette_dispatch
        ++> egui_overlay;

    print("=== CoverageAudit: walks BracketCovers edges only ===");
    root spawn CoverageAudit();
    print("");

    print("=== FindUnbracketed: every GpuWork reachable from Root ===");
    audit = FindUnbracketed();
