test "auditor admits validated parts and rejects unsafe parts" {
    dag_a = SubDAG(name="A", frozen=True, validated=True, depends_on=["B"]);
    dag_b = SubDAG(name="B", frozen=True, validated=True, depends_on=[]);
    dag_c = SubDAG(name="C", frozen=False, validated=True, depends_on=[]);
    dag_d = SubDAG(name="D", frozen=True, validated=False, depends_on=[]);
    validator = Validator(gate_name="AS-2");
    composer = Composer(requested_shape="compose-at-runtime");
    registry = Registry(capacity=16);

    root ++> registry;
    registry +>:PartOf:+> validator;
    validator +>:Validates:+> dag_a;
    validator +>:Validates:+> dag_b;
    validator +>:Validates:+> dag_c;
    validator +>:Validates:+> dag_d;

    dag_a +>:GapSingleTarget:+> composer;
    dag_a +>:GapScalarResolver:+> composer;
    dag_a +>:GapFrozenDAG:+> composer;
    dag_b +>:GapSingleTarget:+> composer;
    dag_b +>:GapScalarResolver:+> composer;
    dag_b +>:GapFrozenDAG:+> composer;

    auditor = Auditor();
    res = root spawn auditor;

    assert "registry capacity=16" in res.findings, f"findings={res.findings}";
    assert "validator AS-2 active" in res.findings, f"findings={res.findings}";
    assert "A: frozen=True validated=True" in res.findings, f"findings={res.findings}";
    assert "B: frozen=True validated=True" in res.findings, f"findings={res.findings}";
    assert "REJECT C: DAG not frozen at parse" in res.findings, f"findings={res.findings}";
    assert "REJECT D: fails AS-2 validate-before-load" in res.findings, f"findings={res.findings}";
    assert "  gap: A exposes single-target dispatch" in res.findings, f"findings={res.findings}";
    assert "  gap: B exposes scalar-only resolver" in res.findings, f"findings={res.findings}";
    assert "  gap: C exposes single-target dispatch" not in res.findings, f"findings={res.findings}";
    assert "  gap: D exposes parse-time frozen DAG" not in res.findings, f"findings={res.findings}";
    assert "composer requested: compose-at-runtime" in res.findings, f"findings={res.findings}";
}

test "typed edges preserve dependency direction and gap shape" {
    dag = SubDAG(name="Core", frozen=True, validated=True, depends_on=[]);
    validator = Validator();
    composer = Composer(requested_shape="single-target");
    registry = Registry(capacity=4);

    root ++> registry;
    registry +>:PartOf:+> validator;
    validator +>:Validates:+> dag;
    dag +>:GapSingleTarget:+> composer;
    dag +>:GapScalarResolver:+> composer;
    dag +>:GapFrozenDAG:+> composer;

    assert len([root-->]) == 1, "root must have one direct registry child";
    assert validator in [registry ->:PartOf:->], "registry must point to validator";
    assert dag in [validator ->:Validates:->], "validator must point to the sub-DAG";
    assert composer in [dag ->:GapSingleTarget:->], "sub-DAG must expose single-target gap";
    assert composer in [dag ->:GapScalarResolver:->], "sub-DAG must expose resolver gap";
    assert composer in [dag ->:GapFrozenDAG:->], "sub-DAG must expose frozen-DAG gap";
    assert len([dag ->:GapSingleTarget:->]) == 1, "single-target edge must have one target";
    assert len([dag ->:GapScalarResolver:->]) == 1, "resolver edge must have one target";
    assert len([dag ->:GapFrozenDAG:->]) == 1, "frozen-DAG edge must have one target";

    auditor = Auditor();
    res = root spawn auditor;

    assert "Core: frozen=True validated=True" in res.findings, f"findings={res.findings}";
    assert "composer requested: single-target" in res.findings, f"findings={res.findings}";
}

test "unvalidated parts fail closed without composer edges" {
    dag = SubDAG(name="Untrusted", frozen=True, validated=False, depends_on=[]);
    composer = Composer(requested_shape="untrusted-shape");
    validator = Validator();
    registry = Registry();

    root ++> registry;
    registry +>:PartOf:+> validator;
    validator +>:Validates:+> dag;

    assert len([dag ->:GapSingleTarget:->]) == 0, "unvalidated DAG must not expose dispatch";
    assert len([dag ->:GapScalarResolver:->]) == 0, "unvalidated DAG must not expose resolver";
    assert len([dag ->:GapFrozenDAG:->]) == 0, "unvalidated DAG must not expose frozen-DAG gap";
    assert composer not in [dag -->], "unvalidated DAG must not reach composer";

    auditor = Auditor();
    res = root spawn auditor;

    assert "REJECT Untrusted: fails AS-2 validate-before-load" in res.findings, f"findings={res.findings}";
    assert "composer requested: untrusted-shape" not in res.findings, f"findings={res.findings}";
}

