        entry_id="pref-tea",
        version_id="pref-tea-v1",
        searchable_text=tampered,
    );

    root +>:RevisionOf(manifest_hash=canonical_hash, committed_revision=1):+> m;
    m +>:RevisionOf(manifest_hash=canonical_hash, committed_revision=1):+> v1;
    m +>:BindsProjection:+> bad_proj;
    bad_proj +>:BindsProjection:+> v1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn MemoryAuditor(
            expected_manifest_hash=canonical_hash,
            canonical_text=canonical,
            known_predecessor=predecessor,
        );
    }
    out = buf.getvalue();

    assert res.violations >= 1, f"projection drift should violate, got {res.violations}";
    assert "[VIOLATION]" in out, f"missing VIOLATION marker: {out}";
    assert "Projection(pref-tea@pref-tea-v1)" in out, f"should flag projection: {out}";
}

test "invalid predecessor on version greater than one is rejected" {
