    assert res.violations >= 1, f"fake predecessor on v2 should violate, got {res.violations}";
    assert "[VIOLATION]" in out, f"missing VIOLATION marker: {out}";
    assert "EntryVersion(pref-tea-v2)" in out, f"should audit bad predecessor entry: {out}";
}

test "memory manifest hash drift is rejected" {
    canonical = "User prefers black tea.";
    canonical_hash = "h-canonical-black-tea";
