test "exact lookup finds zero-edge virtual symbols" {
    repo = Repo(name="django");
    auth = SourceFile(path="src/auth.py", language="python");
    imported = Symbol(name="hashlib", kind="module");
    helper = Symbol(name="authenticate", kind="function");
    search_index = TraversalRoot(label="search-index");
    translation = VirtualSymbol(
        key="auth.login.button",
        provenance="gettext/babel-lsp"
    );
    plaintext = VirtualSymbol(
        key="welcome.banner",
        provenance="plaintext/cohort"
    );

    root +>:Owns:+> repo;
    repo +>:Owns:+> auth;
    auth +>:Imports:+> imported;
    imported +>:Calls:+> helper;
    root +>:Holds:+> search_index;
    search_index +>:Holds:+> translation;
    search_index +>:Holds:+> plaintext;

    res = root spawn ExactLookup(query="auth.login.button");

    assert "VirtualSymbol:auth.login.button" in res.matches,
        f"matches: {res.matches}";
