    called = Symbol(name="connect", kind="function");
    search_index = TraversalRoot(label="search-index");
    translation = VirtualSymbol(
        key="auth.login.button",
        provenance="gettext/babel-lsp"
    );

    root +>:Owns:+> code_root;
    code_root +>:Owns:+> auth;
    auth +>:Imports:+> imported;
    imported +>:Calls:+> called;
    root +>:Holds:+> search_index;
    search_index +>:Holds:+> translation;

    res = code_root spawn CodeGraphTraversal();

    assert len(res.visited_symbols) == 2,
        f"visited symbols: {res.visited_symbols}";
    assert "database" in res.visited_symbols,
        f"visited symbols: {res.visited_symbols}";
    assert "connect" in res.visited_symbols,
        f"visited symbols: {res.visited_symbols}";
    assert res.hydrated_virtual_count == 0,
        f"hydrated virtual nodes: {res.hydrated_virtual_count}";
}

test "structural traversal rejects an accidentally linked virtual node" {
    code_root = TraversalRoot(label="bad-projection");
    leaked = VirtualSymbol(
        key="auth.login.button",
        provenance="gettext/babel-lsp"
    );

    root +>:Owns:+> code_root;
    code_root +>:Owns:+> leaked;

    res = code_root spawn CodeGraphTraversal();

    assert res.hydrated_virtual_count == 1,
        f"hydrated virtual nodes: {res.hydrated_virtual_count}";
}

