"""Test annex for forge env up GitSource frontend resolution.

Covers the three behaviors the issue promises:
  1. `up` without resolve sees an empty Path on a GitSource frontend (bug).
  2. Resolver materializes GitSource frontends into a SourceDir via ResolvedInto.
  3. `up` after resolve sees the materialized Path (fix).
"""

import io;
import from contextlib { redirect_stdout }

def make_graph() {
    reliant_web = Frontend(
        name="reliant-web",
        kind="git",
        repo="github.com/reliant-labs/reliant",
        ref="v1.7.9",
        subdir="web"
    );
    admin_ui = Frontend(
        name="admin-ui",
        kind="path",
        path="./apps/admin"
    );
    marketing = Frontend(
        name="marketing",
        kind="git",
        repo="github.com/reliant-labs/marketing",
        ref="main",
        subdir="site"
    );
    root +>:Declared(lane="up"):+> reliant_web;
    root +>:Declared(lane="up"):+> admin_ui;
    root +>:Declared(lane="up"):+> marketing;
    return [reliant_web, admin_ui, marketing];
}

test "up without resolver sees empty path for git frontend (the bug)" {
    [reliant_web, admin_ui, marketing] = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn UpLane(target="reliant-web");
    }
    out = buf.getvalue();

    assert res.served_dir == "", f"expected empty served_dir pre-resolve, got {res.served_dir!r}";
    assert "BUG" in out, f"expected BUG marker in up output, got: {out}";
    assert "reliant-web" in out, f"expected target name in output, got: {out}";
}

test "resolver materializes git frontends and leaves path-frontends alone" {
    [reliant_web, admin_ui, marketing] = make_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Resolver();
    }
    out = buf.getvalue();

    # Only the two git frontends were resolved.
    assert res.resolved_count == 2, f"expected 2 resolved, got {res.resolved_count}";

    # The git frontends now have a materialized path.
    assert reliant_web.path != "", f"reliant-web path should be set, got {reliant_web.path!r}";
    assert "github.com-reliant-labs-reliant-v1.7.9" in reliant_web.path, f"unexpected path: {reliant_web.path}";
    assert reliant_web.path.endswith("/web"), f"path should end with subdir /web, got {reliant_web.path}";
    assert marketing.path.endswith("/site"), f"marketing path should end with /site, got {marketing.path}";

    # path-kind frontend untouched.
    assert admin_ui.path == "./apps/admin", f"admin_ui path mutated to {admin_ui.path!r}";

    # Output announces both.
    assert "resolved reliant-web" in out, f"missing reliant-web resolve log: {out}";
    assert "resolved marketing" in out, f"missing marketing resolve log: {out}";
    assert "skipped admin-ui" in out, f"missing admin-ui skip log: {out}";
}

test "resolver creates a ResolvedInto source-dir edge per git frontend" {
    [reliant_web, admin_ui, marketing] = make_graph();

    root spawn Resolver();

    src_dirs = [reliant_web ->:ResolvedInto:->];
    assert len(src_dirs) == 1, f"reliant-web should have 1 SourceDir, got {len(src_dirs)}";
    assert src_dirs[0].materialized == True, "SourceDir should be marked materialized";
    assert src_dirs[0].location == reliant_web.path, "SourceDir location must mirror frontend path";

    mkt_dirs = [marketing ->:ResolvedInto:->];
    assert len(mkt_dirs) == 1, f"marketing should have 1 SourceDir, got {len(mkt_dirs)}";

    # path-kind frontends must not gain a ResolvedInto edge.
    admin_dirs = [admin_ui ->:ResolvedInto:->];
    assert len(admin_dirs) == 0, f"admin_ui should not be resolved, got {len(admin_dirs)} edges";
}

test "up after resolver serves from materialized path (the fix)" {
    [reliant_web, _admin_ui, _marketing] = make_graph();

    root spawn Resolver();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn UpLane(target="reliant-web");
    }
    out = buf.getvalue();

    assert res.served_dir == reliant_web.path, (
        f"served_dir {res.served_dir!r} != materialized path {reliant_web.path!r}"
    );
    assert res.served_dir != "", "served_dir should be the materialized source dir, not empty";
    assert "BUG" not in out, f"BUG should NOT appear after resolve; got: {out}";
    assert "serving" in out, f"expected serving line in up output, got: {out}";
    assert "reliant-web" in out, f"expected target name in output, got: {out}";
}

