test "policy change invalidates every descendant assessment" {
    p = Policy(name="trust-policy", version=2);
    root ++> p;

    s1 = Subject(label="alpha");
    s2 = Subject(label="beta");
    p +>:Governs:+> s1;
    p +>:Governs:+> s2;

    a1 = Assessment(score=0.42, cached=True);
    a2 = Assessment(score=0.77, cached=True);
    a3 = Assessment(score=0.10, cached=True);
    s1 +>:AssessedBy:+> a1;
    s1 +>:AssessedBy:+> a2;
    s2 +>:AssessedBy:+> a3;

    res = root spawn Invalidator();

    assert res.invalidated_count == 3, f"invalidated {res.invalidated_count}";
    assert a1.cached == False, f"a1.cached = {a1.cached}";
    assert a2.cached == False, f"a2.cached = {a2.cached}";
    assert a3.cached == False, f"a3.cached = {a3.cached}";
}

test "async evidence writes become durable and count pending records" {
    s1 = Subject(label="alpha");
    s2 = Subject(label="beta");
    root ++> s1;
    root ++> s2;

    ev1 = EvidenceRecord(note="alpha: source=A", durable=False);
    ev2 = EvidenceRecord(note="beta: source=B", durable=True);
    s1 +>:AuditedBy:+> ev1;
    s2 +>:AuditedBy:+> ev2;

    res = root spawn AsyncAuditor();

    assert res.pending_count == 1, f"pending {res.pending_count}";
    assert res.durable_count == 2, f"durable {res.durable_count}";
    assert ev1.durable == True, f"ev1.durable = {ev1.durable}";
    assert ev2.durable == True, f"ev2.durable = {ev2.durable}";
}

test "re-analysis bypasses the assessment cache" {
    s1 = Subject(label="alpha");
    root ++> s1;

    old = Assessment(score=0.42, cached=True);
    s1 +>:AssessedBy:+> old;

    assert old.cached == True, f"old.cached = {old.cached}";
    res = root spawn ReAnalyze(subject_label="alpha", fresh_score=0.99);

    assessments = [s1 ->:AssessedBy:->];
    fresh = assessments[1];
    assert old.cached == False, f"old.cached after re-analysis = {old.cached}";
    assert len(assessments) == 2, f"assessment count = {len(assessments)}";
    assert fresh.score == 0.99, f"fresh.score = {fresh.score}";
    assert fresh.cached == False, f"fresh.cached = {fresh.cached}";
}

