import io;
import from contextlib { redirect_stdout }

test "stale mtime skip when cached output is newer than backdated input" {
    bs = BuildScript(name="build.rs", declares_rerun=True);
    sf = SourceFile(path="inputs/data.txt", content_hash="VERSION_TWO", mtime=2020);
    go = GeneratedOut(path="OUT_DIR/baked.txt", baked_hash="VERSION_ONE", out_mtime=2024, src_mtime=2020);
    root ++> bs;
    bs +>:Declares:+> sf;
    sf +>:Freshness:+> go;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FreshnessAudit();
    }
    out = buf.getvalue();
    assert "STALE-SKIP" in out, f"expected stale-skip verdict in output: {out}";
    assert "OUT_DIR/baked.txt:STALE-SKIP" in res.findings, f"findings missing stale-skip: {res.findings}";
}

test "fresh verdict when output mtime is not newer than source" {
    bs = BuildScript(name="build.rs", declares_rerun=True);
    sf = SourceFile(path="inputs/data.txt", content_hash="VERSION_TWO", mtime=2020);
    go = GeneratedOut(path="OUT_DIR/baked.txt", baked_hash="VERSION_TWO", out_mtime=2020, src_mtime=2020);
    root ++> bs;
    bs +>:Declares:+> sf;
    sf +>:Freshness:+> go;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FreshnessAudit();
    }
    out = buf.getvalue();
    assert "-> FRESH" in out, f"expected fresh verdict in output: {out}";
    assert "OUT_DIR/baked.txt:FRESH" in res.findings, f"findings missing fresh: {res.findings}";
}

test "audit reports rerun-if-changed declaration on build scripts" {
    bs = BuildScript(name="rene/build.rs", declares_rerun=True);
    root ++> bs;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn FreshnessAudit();
