    root ++> analyzer_a;
    root ++> analyzer_b;
    analyzer_a +>:DerivedFrom(role="primary"):+> shared_item;
    analyzer_b +>:DerivedFrom(role="primary"):+> shared_item;

    assert shared_item in [analyzer_a ->:DerivedFrom:->], f"analyzer A missing shared item";
