}

test "invalidator cascades through typed format edges" {
    schema = CompiledSchema(label="Order", attribute_count=2, nested_count=1);
    address = SubModel(label="address", fields=["city", "zip"]);
    item = ReadItem(label="row-2");

    item +>:Format(role="shapes"):+> schema;
    schema +>:Format(role="owns"):+> address;

    inv = CascadeInvalidator();
    res = item spawn inv;

    assert res.invalidated == 3, f"got {res.invalidated} invalidated entries";
    assert address in [schema->:Format:->], "nested schema shape is not linked";
}

