import io;
import from contextlib { redirect_stdout }

test "startup classifies clean directories as recursive" {
    src = Directory(name="src");
    vendor = Directory(name="vendor");
    root ++> src;
    root ++> vendor;

    assert len([root-->]) == 2, f"got {len([root-->])}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Planner();
    }
    out = buf.getvalue();

    assert "[plan] startup pass (re-entry=False)" in out, f"got {out}";
    assert "src: 0 ignored dirs < 4 -> Recursive watch installed" in out, f"got {out}";
    assert "vendor: 0 ignored dirs < 4 -> Recursive watch installed" in out, f"got {out}";
}

test "auditor detects ignored growth under a recursive watch" {
    src = Directory(name="vendor");
    late_tree = Directory(name="node_modules");
    root ++> src;
    src +>:Recursive(installed_at="startup"):+> late_tree;
    src.ignored_child_count = 5;

    rec_targets = [src ->:Recursive:->];
    assert len(rec_targets) == 1, f"got {len(rec_targets)}";
    assert late_tree in rec_targets, f"got {rec_targets}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert "[audit] EXPOSURE:" in out, f"got {out}";
    assert "vendor has a recursive watch" in out, f"got {out}";
    assert "5 ignored children now exist" in out, f"got {out}";
}

test "replan uses the split threshold and reentry marker" {
    boundary = Directory(name="src");
    clean = Directory(name="docs");
    boundary.ignored_child_count = 4;
    clean.ignored_child_count = 3;
    root ++> boundary;
    root ++> clean;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Planner(reentry=True);
    }
    out = buf.getvalue();

    assert "[plan] startup pass (re-entry=True)" in out, f"got {out}";
    assert "src: 4 ignored dirs >= 4 -> Shallow watch installed" in out, f"got {out}";
    assert "docs: 3 ignored dirs < 4 -> Recursive watch installed (stale-recursive)" in out, f"got {out}";
}

