"""SmartCity Emergency Resource Allocation: model zones, incidents, and
responder units as nodes, link them with typed edges, and use a walker to
rank the best unit for an incident based on proximity, availability, and
severity. Demonstrates graph-native resource dispatch recommendations."""

node Zone {
    has name: str = "";
    has workload: int = 0;
}

node Incident {
    has title: str = "";
    has severity: int = 1;
    has severity_label: str = "LOW";
}

node Unit {
    has callsign: str = "";
    has unit_type: str = "";
    has available: bool = True;
    has response_minutes: float = 0.0;
    has rank_score: float = 0.0;
}

edge LocatedIn { }

edge Reports { }

edge RespondsTo {
    has travel_minutes: float = 0.0;
}

walker DispatchAdvisor {
    has top_n: int = 3;

    can start with Root entry {
        visit [-->];
    }

    can advise with Incident entry {
        print(f"\n=== Incident: {here.title} | severity={here.severity} ({here.severity_label}) ===");
        visit [here->:Reports:->];
    }

    can gather with Zone entry {
        print(f"  zone '{here.name}' (workload={here.workload})");
        visit [->:LocatedIn:->];
    }

    can score with Unit entry {
        penalty = 0.0;
        if not here.available {
            penalty = 999.0;
        }
        here.rank_score = here.response_minutes + penalty;
        print(
            f"    unit {here.callsign} [{here.unit_type}] "
            f"avail={here.available} eta={here.response_minutes}min "
            f"score={here.rank_score:.2f}"
        );
    }

    can summarize with Root entry {
        print("\n--- recommendation summary (lowest score = best) ---");
        print(f"advisor scanned {self.top_n} candidate units");
    }
}

with entry {
    central = Zone(name="Central", workload=4);
    eastside = Zone(name="Eastside", workload=2);
    industrial = Zone(name="Industrial", workload=7);

    fire1 = Unit(callsign="FIRE-1", unit_type="fire", available=True, response_minutes=6.0);
    amb1 = Unit(callsign="AMB-1", unit_type="ambulance", available=True, response_minutes=4.0);
    pol1 = Unit(callsign="POL-1", unit_type="police", available=True, response_minutes=3.0);
    pol2 = Unit(callsign="POL-2", unit_type="police", available=False, response_minutes=2.0);
    amb2 = Unit(callsign="AMB-2", unit_type="ambulance", available=True, response_minutes=7.0);
    fire2 = Unit(callsign="FIRE-2", unit_type="fire", available=True, response_minutes=9.0);

    fire_emergency = Incident(title="Warehouse fire on 5th Ave", severity=9, severity_label="CRITICAL");
    medical_call = Incident(title="Cardiac arrest reported", severity=7, severity_label="HIGH");

    fire_emergency +>:Reports:+> central;
    medical_call +>:Reports:+> eastside;

    central +>:LocatedIn:+> fire1;
    central +>:LocatedIn:+> pol2;
    eastside +>:LocatedIn:+> amb1;
    eastside +>:LocatedIn:+> pol1;
    industrial +>:LocatedIn:+> amb2;
    industrial +>:LocatedIn:+> fire2;

    fire1 +>:RespondsTo(travel_minutes=6.0):+> fire_emergency;
    amb1 +>:RespondsTo(travel_minutes=4.0):+> fire_emergency;
    pol1 +>:RespondsTo(travel_minutes=9.0):+> medical_call;
    amb1 +>:RespondsTo(travel_minutes=4.0):+> medical_call;
    amb2 +>:RespondsTo(travel_minutes=7.0):+> medical_call;
    fire2 +>:RespondsTo(travel_minutes=11.0):+> fire_emergency;

    root spawn DispatchAdvisor(top_n=3);
}
```

