"""Tests for the messageDeliveryTimeout callback dispatch model."""

import io;
import from contextlib { redirect_stdout }

test "valid messageDeliveryTimeout envelope dispatches and acknowledges" {
    root ++> ReservationStore(store_name="test-store");

    store = [root -->][?:ReservationStore];

    op_a = Operation(correlation_id="corr-001", summary="path A still building");
    op_b = Operation(correlation_id="corr-002", summary="path B still building");

    store +>:OfOperation:+> op_a;
    store +>:OfOperation:+> op_b;

    good_env = SoapEnvelope(
        operation="messageDeliveryTimeout",
        correlation_id="corr-002",
        reason="P2P child segment unreachable after 30s",
    );

    root +>:Carries:+> good_env +>:Ack:+> op_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Deliver();
    }
    out = buf.getvalue();

    assert "envelope: timeout notification corr=corr-002" in out, f"missing inspect line: {out}";
    assert "[op corr-002] TIMEOUT delivered: path B still building" in out, f"op_b not notified: {out}";
    assert "SOAP 200 OK: messageDeliveryTimeout acknowledged" in out, f"missing SOAP ack: {out}";
    assert op_b.notified == True, f"op_b.notified should be True, got {op_b.notified}";
    assert op_a.notified == False, f"op_a.notified must stay False, got {op_a.notified}";
}

test "unknown NSI operation falls through to fallback (no dispatch, no ack)" {
    root ++> ReservationStore(store_name="store");

    store = [root -->][?:ReservationStore];

    op = Operation(correlation_id="corr-007", summary="untouched");
    store +>:OfOperation:+> op;

    bogus_env = SoapEnvelope(
        operation="unicornGreeting",
        correlation_id="corr-xxx",
        reason="",
    );

    root +>:Carries:+> bogus_env;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Deliver();
    }
    out = buf.getvalue();

    assert "envelope: unknown NSI operation: 'unicornGreeting'" in out, f"fallback not taken: {out}";
    assert "TIMEOUT delivered" not in out, f"unknown op must NOT trigger timeout: {out}";
    assert "SOAP 200 OK: messageDeliveryTimeout acknowledged" not in out, f"unknown op must NOT be acknowledged: {out}";
    assert op.notified == False, f"op.notified must stay False, got {op.notified}";
}

test "correlation ID and reason are preserved on the envelope node" {
    env = SoapEnvelope(
        operation="messageDeliveryTimeout",
        correlation_id="corr-42",
        reason="peer did not respond within timeout window",
    );
    root +>:Carries:+> env;

    found = [root -->][?:SoapEnvelope];
    assert len(found) == 1, f"expected exactly one envelope, got {len(found)}";
    e = found[0];
    assert e.operation == "messageDeliveryTimeout", f"op name lost: {e.operation}";
    assert e.correlation_id == "corr-42", f"corr id lost: {e.correlation_id}";
    assert e.reason == "peer did not respond within timeout window", f"reason lost: {e.reason}";
}

test "typed edges wire envelope -> ack -> matching operation" {
    root ++> ReservationStore(store_name="store");

    store = [root -->][?:ReservationStore];

    target = Operation(correlation_id="corr-99", summary="target reservation");
    store +>:OfOperation:+> target;

    env = SoapEnvelope(
        operation="messageDeliveryTimeout",
        correlation_id="corr-99",
        reason="resv timeout",
    );

    root +>:Carries:+> env +>:Ack:+> target;

    carries_edges = [root ->:Carries:->];
    assert len(carries_edges) == 1, f"expected 1 Carries edge, got {len(carries_edges)}";

    ack_edges = [env ->:Ack:->];
    assert len(ack_edges) == 1, f"expected 1 Ack edge from env, got {len(ack_edges)}";

    linked = ack_edges[0];
    assert linked == target, f"Ack edge must point at target op, got {linked}";
}

