"""PWA shell: model the responsive app frame, its navigation routes, and the
capture/accessibility subsystems as a graph and walk it to verify that every
top-level route is reachable, capture degrades when the microphone is missing,
and the offline shell can serve its content without the network."""

node Section {
    has title: str = "";
    has width_min: int = 320;
    has installed: bool = False;
}

node Route {
    has title: str = "";
    has priority: int = 0;
    has persistent: bool = False;
}

node CaptureSurface {
    has kind: str = "";
    has mic_supported: bool = True;
    has pwa_supported: bool = True;
}

node AuthSurface {
    has kind: str = "";
}

node ShellState {
    has online: bool = True;
    has stale: bool = False;
    has has_error: bool = False;
    has reduced_motion: bool = False;
    has contrast_ok: bool = True;
    has target_px: int = 44;
}

edge NavLink { has order: int = 0; }
edge Contains { }
edge CapturesVia { }
edge Authenticates { }
edge Renders { }

walker ShellAuditor {
    can start with Root entry {
        print("[shell] auditing responsive PWA shell");
        visit [-->];
    }

    can scan_shell with Section entry {
        print(f"[section] {here.title} (min-width={here.width_min}px, "
              f"installed={here.installed})");
        visit [-->];
    }

    can audit_route with Route entry {
        marker = "persistent" if here.persistent else "route";
        print(f"[route:{marker}] {here.title} (priority={here.priority})");
        visit [-->];
    }

    can inspect_capture with CaptureSurface entry {
        degraded = (not here.mic_supported) or (not here.pwa_supported);
        mode = "typed-only" if degraded else "voice+pwa";
        print(f"[capture] {here.kind} -> {mode} (mic={here.mic_supported}, "
              f"pwa={here.pwa_supported})");
        visit [-->];
    }

    can check_auth with AuthSurface entry {
        print(f"[auth] {here.kind}");
        visit [-->];
    }

    can report_shell with ShellState entry {
        ok_targets = here.target_px >= 44;
        ok_contrast = here.contrast_ok;
        offline_ok = (not here.online) and (not here.has_error);
        print(f"[state] online={here.online} stale={here.stale} "
              f"error={here.has_error} reduced_motion={here.reduced_motion} "
              f"44px_targets={ok_targets} contrast={ok_contrast} "
              f"offline_serves={offline_ok}");
    }
}

with entry {
    shell = Section(title="PWA Shell", width_min=320, installed=True);
    nav = Section(title="Navigation", width_min=320, installed=True);

    today = Route(title="Today", priority=1, persistent=False);
    review = Route(title="Review", priority=2, persistent=False);
    tasks = Route(title="Tasks", priority=3, persistent=False);
    projects = Route(title="Projects", priority=4, persistent=False);
    people = Route(title="People", priority=5, persistent=False);
    notes = Route(title="Notes", priority=6, persistent=False);
    search = Route(title="Search", priority=7, persistent=False);
    settings = Route(title="Settings", priority=8, persistent=False);
    capture = Route(title="Capture", priority=0, persistent=True);

    typed_capture = CaptureSurface(kind="typed", mic_supported=False, pwa_supported=False);
    voice_capture = CaptureSurface(kind="voice+pwa", mic_supported=True, pwa_supported=True);

    auth = AuthSurface(kind="oauth+session");

    state = ShellState(online=False, stale=True, has_error=False,
                       reduced_motion=True, contrast_ok=True, target_px=44);

    root ++> shell;
    root ++> state;

    shell +>:Contains:+> nav;

    nav +>:NavLink(order=1):+> today;
    nav +>:NavLink(order=2):+> review;
    nav +>:NavLink(order=3):+> tasks;
    nav +>:NavLink(order=4):+> projects;
    nav +>:NavLink(order=5):+> people;
    nav +>:NavLink(order=6):+> notes;
    nav +>:NavLink(order=7):+> search;
    nav +>:NavLink(order=8):+> settings;
    nav +>:NavLink(order=9):+> capture;

    shell +>:CapturesVia:+> typed_capture;
    shell +>:CapturesVia:+> voice_capture;

    capture +>:Authenticates:+> auth;

    state +>:Renders:+> shell;

    root spawn ShellAuditor();
}
