```jac
"""Breadth-sidecar lineage: model CoinGecko Top-100 constituent snapshots
retained per accepted DATA PING so that the exact constituents can be replayed.

A Lineage walker walks parent -> child relationships through the breadcrumb
chain (Ping -> Sidecar -> Page -> Row), accumulating replay evidence on a
typed `report` field. A separate Replay walker re-derives the aggregate
breadth ratio and membership hash from the retained sidecar, proving the
lineage is self-sufficient without re-fetching."""

node DataPing {
    has label: str = "";
    has accepted: bool = True;
    has breadcrumb_id: str = "";
}

node Sidecar {
    has artifact_bytes: int = 0;
    has row_count: int = 0;
    has content_sha256: str = "";
    has path: str = "";
    has retrieved_at: str = "";
    has frozen_at: str = "";
    has replayability: str = "PASS";
}

node CoinPage {
    has page_label: str = "";
    has page_timestamp: str = "";
    has method_id: str = "";
    has filter_id: str = "";
    has raw_count: int = 0;
    has deduped_count: int = 0;
    has included_count: int = 0;
    has excluded_count: int = 0;
    has advancers: int = 0;
    has decliners: int = 0;
    has unchanged: int = 0;
    has median_return: float = 0.0;
    has membership_sha256: str = "";
    has breadth_ratio: float = 0.0;
}

node ConstituentRow {
    has coin_id: str = "";
    has symbol: str = "";
    has rank: int = 0;
    has market_cap: float = 0.0;
    has price: float = 0.0;
    has return_24h: float = 0.0;
    has included: bool = True;
    has reason_code: str = "";
}

edge Retains {
    has slot: str = "";
}

with entry {
    ping = DataPing(
        label="DATA PING 2026-07-29T00:00Z",
        breadcrumb_id="BP-20260729-0001"
    );

    sidecar = Sidecar(
        artifact_bytes=4096,
        row_count=2,
        content_sha256="deadbeef" + "0" * 56,
        path="lineage/2026-07-29/sidecar.json",
        retrieved_at="2026-07-29T00:00:01Z",
        frozen_at="2026-07-29T00:00:02Z"
    );

    page1 = CoinPage(
        page_label="page-1",
        page_timestamp="2026-07-28T23:59:30Z",
        method_id="coingecko_top100_v3",
        filter_id="min_mcap_usd_1e6",
        raw_count=100,
        deduped_count=98,
        included_count=80,
        excluded_count=20,
        advancers=42,
        decliners=36,
        unchanged=2,
        median_return=0.012,
        membership_sha256="a1" + "0" * 62,
        breadth_ratio=0.525
    );

    page2 = CoinPage(
        page_label="page-2",
        page_timestamp="2026-07-29T00:00:00Z",
        method_id="coingecko_top100_v3",
        filter_id="min_mcap_usd_1e6",
        raw_count=100,
        deduped_count=99,
        included_count=80,
        excluded_count=20,
        advancers=44,
        decliners=34,
        unchanged=2,
        median_return=0.014,
        membership_sha256="b2" + "0" * 62,
        breadth_ratio=0.55
    );

    row1 = ConstituentRow(
        coin_id="bitcoin",
        symbol="BTC",
        rank=1,
        market_cap=1.2e12,
        price=62000.0,
        return_24h=0.015
    );
    row2 = ConstituentRow(
        coin_id="ethereum",
        symbol="ETH",
        rank=2,
        market_cap=4.5e11,
        price=3100.0,
        return_24h=0.022
    );
    row_excluded = ConstituentRow(
        coin_id="tinycoin",
        symbol="TINY",
        rank=87,
        market_cap=9.5e5,
        price=0.001,
        return_24h=-0.04,
        included=False,
        reason_code="BELOW_MIN_MCAP"
    );

    ping +>:Retains(slot="sidecar"):+> sidecar;
    sidecar +>:Retains(slot="page-1"):+> page1;
    sidecar +>:Retains(slot="page-2"):+> page2;
    page1 +>:Retains(slot="included"):+> row1;
    page1 +>:Retains(slot="included"):+> row2;
    page2 +>:Retains(slot="excluded"):+> row_excluded;

    walker LineageWalker {
        has hops: int = 0;
        has rows_seen: int = 0;
        has pages_seen: int = 0;
        has membership_hashes: list[str] = [];
        has breadth_ratios: list[float] = [];
        has fail_closed: bool = False;

        can start with Root entry {
            visit [->:Retains:->];
        }

        can traverse_ping with DataPing entry {
            if not here.accepted {
                self.fail_closed = True;
                disengage;
            }
            visit [->:Retains:->];
        }

        can traverse_sidecar with Sidecar entry {
            if here.replayability != "PASS" or here.artifact_bytes == 0 or here.row_count == 0 {
                self.fail_closed = True;
                disengage;
            }
            visit [->:Retains:->];
        }

        can record_page with CoinPage entry {
            self.pages_seen += 1;
            self.membership_hashes.append(here.membership_sha256);
            self.breadth_ratios.append(here.breadth_ratio);
            self.hops += 1;
            visit [->:Retains:->];
        }

        can record_row with ConstituentRow entry {
            self.rows_seen += 1;
            self.hops += 1;
            visit [->:Retains:->];
        }
    }

    walker ReplayWalker {
        has expected_breadth: float = 0.0;
        has expected_hash: str = "";
        has recovered_breadth: float = 0.0;
        has recovered_hash: str = "";
        can start with Root entry {
            visit [->:Retains:->];
        }
        can walk_to_page with DataPing | Sidecar entry {
            visit [->:Retains:->];
        }
        can replay_page with CoinPage entry {
            self.recovered_breadth = here.breadth_ratio;
            self.recovered_hash = here.membership_sha256;
            visit [->:Retains:->];
        }
    }

    lineage_walker = LineageWalker();
    root spawn lineage_walker;

    print("Lineage hops:", lineage_walker.hops);
    print("Rows seen:", lineage_walker.rows_seen);
    print("Pages seen:", lineage_walker.pages_seen);
    print("Membership hashes collected:", lineage_walker.membership_hashes);
    print("Breadth ratios collected:", lineage_walker.breadth_ratios);
    print("Fail-closed triggered:", lineage_walker.fail_closed);

    replay_walker = ReplayWalker(expected_breadth=0.55, expected_hash="b2" + "0" * 62);
    ping spawn replay_walker;
    print("Replay breadth match:",
        replay_walker.recovered_breadth == replay_walker.expected_breadth);
    print("Replay hash match:",
        replay_walker.recovered_hash == replay_walker.expected_hash);
}
