and walk it to detect orphans, cycles, or invalidation cascades."""

node StudioNode {
    has name: str = "";
}

node Skill {
    has name: str = "";
    has agent_md: bool = True;
}

node Kit {
    has name: str = "";
    has thin_skill: bool = False;
}

node Snapshot {
    has label: str = "";
    has name: str = "";
}

edge DependsOn {}
edge ContainsSkill {}

walker Auditor {
    has visited: list = [];
    has errors: list = [];

    can start with Root entry {
        self.visited = [];
        visit [-->];
    }

    can audit_kit with Kit entry {
        kit = here;
        if kit.name in self.visited {
            msg = f"CYCLE detected at {kit.name}";
            print(msg);
            self.errors.append(msg);
            disengage;
        }
        self.visited.append(kit.name);
        print(f"[KIT] {kit.name} thin_skill={kit.thin_skill}");
        visit [->:ContainsSkill:->] else { disengage; }
    }

    can audit_skill with Skill entry {
        sk = here;
        if sk.name in self.visited {
            msg = f"CYCLE detected at {sk.name}";
            print(msg);
            self.errors.append(msg);
            disengage;
        }
        self.visited.append(sk.name);
        print(f"  [SKILL] {sk.name} agent_md={sk.agent_md}");
        visit [->:DependsOn:->] else { disengage; }
    }

    can audit_snapshot with Snapshot entry {
        sn = here;
        if sn.name in self.visited {
            msg = f"CYCLE detected at {sn.label}";
            print(msg);
            self.errors.append(msg);
            disengage;
        }
        self.visited.append(sn.name);
        print(f"  [SNAP] {sn.label}");
        visit [->:DependsOn:->] else { disengage; }
    }
}

with entry {
    studio = Kit(name="agent-flow-studio");
    skill_a = Skill(name="orchestration/agent-flow-studio");
    skill_b = Skill(name="studio-fixture");
    snap = Snapshot(label="thin-mirror", name="thin-mirror");

    root ++> studio;
    studio +>:ContainsSkill:+> skill_a;
    studio +>:ContainsSkill:+> skill_b;
    studio +>:DependsOn:+> snap;
