"""Tests for recursive module resolution walker."""

import io;
import from contextlib { redirect_stdout }


test "walker records the trace of visited shared roots" {
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");
    sr_a = SharedRoot(directory_name="shared/components");
    sr_b = SharedRoot(directory_name="shared/utils");
    sr_c = SharedRoot(directory_name="shared/legacy", drained=True);
    proj +>:OwnedBy:+> sr_a;
    proj +>:OwnedBy:+> sr_b;
    proj +>:OwnedBy:+> sr_c;
    proj +>:SearchedAt:+> sr_a;
    proj +>:SearchedAt:+> sr_b;
    proj +>:SearchedAt:+> sr_c;

    req = ImportRequest(specifier="components/Button", status="pending");
    root ++> req;
    req +>:Requests:+> proj;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = ResolveRequest();
        req spawn resolver;
    }
    out = buf.getvalue();
    assert "shared/components" in resolver.trace, f"trace={resolver.trace}, out={out}";
    assert "shared/utils" in resolver.trace, f"trace={resolver.trace}, out={out}";
    assert "shared/legacy" not in resolver.trace, (
        f"drained root must be skipped, trace={resolver.trace}, out={out}"
    );
    assert len(resolver.trace) == 2, f"expected 2 roots, got {resolver.trace}";
}


test "first matching module wins among resolved candidates" {
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");
    sr_a = SharedRoot(directory_name="shared/near");
    sr_b = SharedRoot(directory_name="shared/far");
    proj +>:OwnedBy:+> sr_a;
    proj +>:OwnedBy:+> sr_b;
    proj +>:SearchedAt:+> sr_a;
    proj +>:SearchedAt:+> sr_b;

    mod_a = Module(path="/near/Button.tsx", resolved=True);
    mod_b = Module(path="/far/Button.tsx", resolved=True);
    sr_a +>:HostsModule:+> mod_a;
    sr_b +>:HostsModule:+> mod_b;

    req = ImportRequest(specifier="Button", status="pending");
    root ++> req;
    req +>:Requests:+> proj;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = ResolveRequest();
        req spawn resolver;
    }
    out = buf.getvalue();
    assert resolver.hit == "/near/Button.tsx", (
        f"first resolved module should win, got {resolver.hit}, out={out}"
    );
    assert "/near/Button.tsx" in out, f"missing near resolution: {out}";
    assert "/far/Button.tsx" in out, f"far module should still be scanned: {out}";
}


test "drained shared roots are mutated and skipped on subsequent walks" {
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");
    sr = SharedRoot(directory_name="shared/components");
    proj +>:OwnedBy:+> sr;
    proj +>:SearchedAt:+> sr;

    mod = Module(path="/x/Button.tsx", resolved=True);
    sr +>:HostsModule:+> mod;

    req1 = ImportRequest(specifier="Button", status="pending");
    root ++> req1;
    req1 +>:Requests:+> proj;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver1 = ResolveRequest();
        req1 spawn resolver1;
    }
    assert sr.drained, "walker must drain the root on first visit";
    assert "shared/components" in resolver1.trace, f"trace={resolver1.trace}";

    req2 = ImportRequest(specifier="Button", status="pending");
    root ++> req2;
    req2 +>:Requests:+> proj;

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        resolver2 = ResolveRequest();
        req2 spawn resolver2;
    }
    assert resolver2.trace == [], (
        f"drained root must be skipped entirely, got trace={resolver2.trace}"
    );
}


test "non-pending import request is ignored without traversal" {
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");
    sr = SharedRoot(directory_name="shared/components");
    proj +>:OwnedBy:+> sr;
    proj +>:SearchedAt:+> sr;
    mod = Module(path="/x/Button.tsx", resolved=True);
    sr +>:HostsModule:+> mod;

    req = ImportRequest(specifier="Button", status="resolved",
                        resolved_path="/x/Button.tsx");
    root ++> req;
    req +>:Requests:+> proj;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = ResolveRequest();
        req spawn resolver;
    }
    out = buf.getvalue();
    assert resolver.trace == [], (
        f"non-pending request must not traverse, got trace={resolver.trace}"
    );
    assert resolver.hit == "", (
        f"non-pending request must not hit, got {resolver.hit}"
    );
    assert "project: webapp" not in out, (
        f"walker should bail before project traversal, out={out}"
    );
}


test "unresolved import yields empty hit and full trace" {
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");
    sr_a = SharedRoot(directory_name="shared/components");
    sr_b = SharedRoot(directory_name="shared/utils");
    proj +>:OwnedBy:+> sr_a;
    proj +>:OwnedBy:+> sr_b;
    proj +>:SearchedAt:+> sr_a;
    proj +>:SearchedAt:+> sr_b;

    missing_a = Module(path="/near/Button.tsx", resolved=False);
    missing_b = Module(path="/far/Button.tsx", resolved=False);
    sr_a +>:HostsModule:+> missing_a;
    sr_b +>:HostsModule:+> missing_b;

    req = ImportRequest(specifier="components/Button", status="pending");
    root ++> req;
    req +>:Requests:+> proj;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = ResolveRequest();
        req spawn resolver;
    }
    out = buf.getvalue();
    assert resolver.hit == "", (
        f"no resolved module means no hit, got {resolver.hit}"
    );
    assert "skipped" in out, f"unresolved modules should be skipped: {out}";
    assert "RESOLVED" not in out, (
        f"no RESOLVED marker expected when nothing matches: {out}"
    );
    assert len(resolver.trace) == 2, (
        f"both roots should be probed even if unresolved, trace={resolver.trace}"
    );
}

