    second = TracerBullet(title="second");
    third = TracerBullet(title="third");

    first +>:DependsOn:+> second;
    first +>:DependsOn(kind="soft"):+> third;

    links = [edge first ->:DependsOn:->];
    targets = [first ->:DependsOn:->];
    kinds = [link.kind for link in links];
    reverse_links = [second ->:DependsOn:->];

    assert len(links) == 2, f"got {len(links)}";
    assert "hard" in kinds, f"got {kinds}";
    assert "soft" in kinds, f"got {kinds}";
    assert second in targets, f"targets were {targets}";
    assert third in targets, f"targets were {targets}";
