    second = TracerBullet(title="second", sequence=2);
    third = TracerBullet(title="third", sequence=3);

    first +>:DependsOn:+> second;
    second +>:DependsOn:+> third;
    root ++> first;

    res = root spawn SpecWalker();

    assert res.cycle == "", f"got {res.cycle}";
    assert len(res.order) == 3, f"got {len(res.order)}";
    assert res.order[0] == str(first), f"got {res.order}";
    assert res.order[1] == str(second), f"got {res.order}";
    assert res.order[2] == str(third), f"got {res.order}";
}

test "dependency cycle is detected" {
    first = TracerBullet(title="first");
    second = TracerBullet(title="second");

    first +>:DependsOn:+> second;
    second +>:DependsOn:+> first;
    root ++> first;

    res = root spawn SpecWalker();

    assert res.cycle == str(first), f"got {res.cycle}";
    assert len(res.order) == 2, f"got {len(res.order)}";
}

