```jac
"""Financial QA knowledge-graph demo: KG-RAG vs vector-RAG, hop-stratified.

Models the scenario from Shah et al. (2024): a knowledge graph built from
10-K filings, traversed by hop count to answer multi-hop questions about
cross-subsidiary ownership and company comparisons. The walker explicitly
stratifies questions by hop count and reports where KG traversal pays off.
"""

node Company {
    has name: str = "";
    has ticker: str = "";
    has sector: str = "";
}

node Subsidiary {
    has name: str = "";
    has ownership_pct: float = 0.0;
}

node Question {
    has text: str = "";
    has hops: int = 0;
    has qtype: str = "";
}

edge Owns {
    has since: str = "";
    has filed_period: str = "";
}

edge Compares {
    has metric: str = "";
}

walker KgRag {
    has answered: int = 0;
    has by_hop: dict[int, int] = {};
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_questions with Question entry {
        q = here;
        self.visited = self.visited + [q.text];
        self.answered = self.answered + 1;
        bucket = self.by_hop.get(q.hops, 0);
        self.by_hop[q.hops] = bucket + 1;
        print(f"[KG-RAG qtype={q.qtype} hops={q.hops}] {q.text}");
        visit [-->];
    }

    can walk_owns with Company entry {
        print(f"  parent: {here.name} ({here.ticker})");
        visit [->:Owns:->];
    }

    can reach_subsidiary with Subsidiary entry {
        print(f"  -> subsidiary: {here.name} ({here.ownership_pct}%)");
    }

    can reach_compare with Company entry {
        visit [->:Compares:->];
    }
}

walker VectorRag {
    has answered: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan_questions with Question entry {
        self.answered = self.answered + 1;
        if here.hops == 1 {
            print(f"[Vector-RAG single-hop OK] {here.text}");
        } elif here.hops == 2 {
            print(f"[Vector-RAG struggles] {here.text}");
        } else {
            print(f"[Vector-RAG fails] {here.text}");
        }
        visit [-->];
    }
}

with entry {
    a = Company(name="Acme Holdings", ticker="ACM", sector="Conglomerate");
    b = Company(name="Beacon Capital", ticker="BCN", sector="Conglomerate");
    root ++> a ++> b;

    s1 = Subsidiary(name="Acme Foods LLC", ownership_pct=100.0);
    s2 = Subsidiary(name="Acme Energy GmbH", ownership_pct=80.0);
    s3 = Subsidiary(name="Beacon Logistics Inc", ownership_pct=100.0);
    a +>:Owns(since="2018", filed_period="FY2023"):+> s1;
    a +>:Owns(since="2020", filed_period="FY2023"):+> s2;
    b +>:Owns(since="2015", filed_period="FY2023"):+> s3;
    a +>:Compares(metric="revenue"):+> b;

    q1 = Question(text="What sector is Acme in?", hops=1, qtype="single-hop");
    q2 = Question(text="Which entity owns Acme Foods?", hops=2, qtype="two-hop");
    q3 = Question(text="Compare Acme vs Beacon revenue.", hops=2, qtype="comparison");
    q4 = Question(text="Trace ownership chain Acme -> Foods -> brand X?", hops=3, qtype="multi-hop");
    root ++> q1 ++> q2 ++> q3 ++> q4;

    print("=== KG-RAG traversal (hop-stratified) ===");
    kg = KgRag();
    root spawn kg;
    print(f"KG-RAG answered {kg.answered} questions, by_hop={kg.by_hop}");

    print("=== Vector-RAG (no graph) ===");
    vr = VectorRag();
    root spawn vr;
    print(f"Vector-RAG answered {vr.answered} questions");
}
