    grammar = GrammarProvider(name="grammar");

    g1 = UaxGrapheme();
    w1 = UaxWord();
    s1 = UaxSentence();
    g2 = UaxGrapheme();
    w2 = UaxWord();
    s2 = UaxSentence();

    delimited +>:Selects:+> first;
    grammar +>:Selects:+> second;

    first +>:Witnesses:+> g1;
    first +>:Witnesses:+> w1;
    first +>:Witnesses:+> s1;
    second +>:Witnesses:+> g2;
    second +>:Witnesses:+> w2;
    second +>:Witnesses:+> s2;

    g1 +>:Witnesses:+> UaxOutput(kind="grapheme", value="H");
    g1 +>:Witnesses:+> UaxOutput(kind="grapheme", value="e");
    w1 +>:Witnesses:+> UaxOutput(kind="word", value="Hello");
    s1 +>:Witnesses:+> UaxOutput(kind="sentence", value="Hello.");

    g2 +>:Witnesses:+> UaxOutput(kind="grapheme", value="W");
    w2 +>:Witnesses:+> UaxOutput(kind="word", value="World");
    s2 +>:Witnesses:+> UaxOutput(kind="sentence", value="World.");

    root ++> delimited;
    root ++> grammar;

    dispatcher = UaxDispatcher();
    res = root spawn dispatcher;

    assert res.dispatches == 2, f"dispatches={res.dispatches}";
    assert res.grapheme_passes == 2, f"grapheme_passes={res.grapheme_passes}";
    assert res.word_passes == 2, f"word_passes={res.word_passes}";
    assert res.sentence_passes == 2, f"sentence_passes={res.sentence_passes}";
    assert len([root-->]) == 2, "root must connect to both providers";
    assert len([first ->:Witnesses:->]) == 3, "first boundary witness count is wrong";
    assert len([second ->:Witnesses:->]) == 3, "second boundary witness count is wrong";
    assert len([g1 ->:Witnesses:->]) == 2, "grapheme terminal outputs are wrong";
}

