    assert source_order.is_valid == False, f"source valid: {source_order.is_valid}";
    assert "dine-in@marina" in res.invalidated, f"invalidated: {res.invalidated}";
    assert "delivery@marina" in res.invalidated, f"invalidated: {res.invalidated}";
    assert "order:O-2001" in res.invalidated, f"invalidated: {res.invalidated}";
