    assert res.trace[1] == "[OPEN] core@2.3.0", f"trace: {res.trace}";
    assert res.trace[2] == "[OPEN] util@0.9.1", f"trace: {res.trace}";
    assert res.trace[3] == "[CYCLE] core already visited", f"trace: {res.trace}";
}

test "discovery stops at the configured depth limit" {
