    assert len(res.trace) == 2, f"trace: {res.trace}";
    assert res.trace[0] == "[OPEN] app@1.0.0", f"trace: {res.trace}";
    assert res.trace[1] == "[OPEN] ghost@?", f"trace: {res.trace}";
}

