    fifth +>:OverrideOf(since="initial"):+> baseline;

    res = root spawn Reconciler();
    assert len(res.reports) == 1, f"got {res.reports}";
    assert res.reports[0]["tighten_or_invert"] == 2, f"got {res.reports[0]}";
    assert res.reports[0]["relax"] == 0, f"got {res.reports[0]}";
    assert res.reports[0]["extend_or_other"] == 3, f"got {res.reports[0]}";
    assert "layer=hca_validation_tools baseline=1.0.0" in res.reports[0]["traversal"], f"got {res.reports[0]}";
}

test "keeps override and inherited relationships typed" {
    ovr = Override(number=2, title="HCA fields added", layer="yaml", commit="2af5e2e", issue="#177", direction="extend");
    upstream = SchemaLayer(name="cellxgene_schema_7.0.0");
    hca = SchemaLayer(name="hca_validation_tools", baseline_version="1.0.0");
    tissue = Override(number=0, title="tissue_type vocabulary + cell-line cascade", layer="default", direction="adopt upstream");
    assays = Override(number=0, title="suspension_type assay list", layer="default", direction="adopt upstream");

    root +>:OverrideOf(since="2af5e2e"):+> ovr;
    hca +>:InheritedFrom(reason="never overridden"):+> tissue;
    hca +>:InheritedFrom(reason="never overridden"):+> assays;
    root ++> upstream;
    root ++> hca;

    assert len([root-->]) == 3, f"got {len([root-->])}";
    assert ovr in [root-->], f"missing override edge";
    assert len([hca-->]) == 2, f"got {len([hca-->])}";
    assert tissue in [hca-->], f"missing tissue inheritance";
    assert assays in [hca-->], f"missing assay inheritance";
    assert upstream in [root-->], f"missing upstream layer";
    assert upstream.baseline_version == "7.0.0", f"got {upstream.baseline_version}";
    assert hca in [root-->], f"missing HCA layer";
}

test "prints reachable overrides and inherited baseline" {
    ovr = Override(number=1, title="organism stays in obs", direction="reject CXG relocation");
    inherited_layer = SchemaLayer(name="hca_validation_tools", baseline_version="1.0.0");
    tissue = Override(number=0, title="tissue_type vocabulary + cell-line cascade", direction="adopt upstream");
    assays = Override(number=0, title="suspension_type assay list", direction="adopt upstream");

    root +>:OverrideOf(since="3dd9f6b"):+> ovr;
    ovr +>:OverrideOf(since="baseline"):+> inherited_layer;
    inherited_layer +>:InheritedFrom(reason="never overridden"):+> tissue;
    inherited_layer +>:InheritedFrom(reason="never overridden"):+> assays;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CascadeAuditor();
    }
    out = buf.getvalue();
    assert "Reachable overrides + inherited baseline fields:" in out, f"missing header: {out}";
    assert "override #1: organism stays in obs -> reject CXG relocation" in out, f"missing override: {out}";
    assert "inherited from hca_validation_tools baseline 1.0.0" in out, f"missing layer: {out}";
    assert "override #0: tissue_type vocabulary + cell-line cascade -> adopt upstream" in out, f"missing tissue: {out}";
    assert "override #0: suspension_type assay list -> adopt upstream" in out, f"missing assays: {out}";
}

