test "dead transport invalidates dependent tracks" {
    broker = Transport(transport_name="broker", alive=False);
    t1 = Track(track_id=1, status="active");
    t2 = Track(track_id=2, status="active");

    root +>:DependsOn:+> broker;
    broker +>:DependsOn:+> t1;
    broker +>:DependsOn:+> t2;

    res = root spawn Tracker(max_lost_frames=3);

    assert t1.status == "invalidated", f"track 1 status: {t1.status}";
    assert t2.status == "invalidated", f"track 2 status: {t2.status}";
    assert len(res.invalidated) == 2, f"invalidated ids: {res.invalidated}";
    assert res.invalidated[0] == 1, f"first invalidated id: {res.invalidated}";
    assert res.invalidated[1] == 2, f"second invalidated id: {res.invalidated}";
}

test "person auditor reports only active tracks as reachable" {
    alice = Person(person_name="alice", last_seen="t=0");
    bob = Person(person_name="bob", last_seen="t=1");
    active_track = Track(track_id=10, status="active");
    lost_track = Track(track_id=11, status="invalidated");

    root ++> alice;
    root ++> bob;
    alice +>:Represents:+> active_track;
    bob +>:Represents:+> lost_track;

