test "typed graph relationships preserve tracker data" {
    frame = Frame(frame_id=1001, captured_at="t=0.0");
    detection = Detection(class_name="person", confidence=0.91, bbox_area=0.21);
    track = Track(track_id=7, status="active", lost_frames=1);
    person = Person(person_name="casey", last_seen="t=0");

    root ++> person;
    person +>:Represents:+> track;
    track +>:AssociatedTo(score=0.91):+> detection;
    detection +>:FromFrame:+> frame;

    assert len([root-->]) == 1, f"root children: {len([root-->])}";
    assert track in [person ->:Represents:->], f"represented tracks: [person ->:Represents:->]";
    assert detection in [track ->:AssociatedTo:->], f"associated detections: [track ->:AssociatedTo:->]";
    assert frame in [detection ->:FromFrame:->], f"source frames: [detection ->:FromFrame:->]";
    assert detection.class_name == "person", f"class name: {detection.class_name}";
    assert detection.confidence == 0.91, f"confidence: {detection.confidence}";
}

