"""KubeMetal Upgrade Impact Analysis: model an upgrade bundle, its components, and
the dependency/breaking-change graph between them, then walk the graph with an
analyst walker that orders affected components, detects cycles, and emits a
rollout summary."""

node Component {
    has name: str = "";
    has current_version: str = "";
    has target_version: str = "";
    has workload_count: int = 0;
    has critical: bool = False;
    has breaking_notes: str = "";
}

node Risk {
    has severity: str = "";
    has rationale: str = "";
    has evidence_ref: str = "";
}

node ChecklistItem {
    has title: str = "";
    has step: str = "";
    has requires_confidence: bool = True;
}

edge DependsOn {
    has required_min_version: str = "";
}

edge AffectsWorkload {
    has replica_count: int = 0;
    has pdb_min_available: int = 0;
}

edge RaisesRisk {
    has confidence: float = 0.0;
}

walker UpgradeAnalyst {
    has visited: list[str] = [];
    has cycle_flag: bool = False;

    can start with Root entry {
        print("=== KubeMetal Upgrade Impact Analysis (offline / air-gap) ===");
        visit [-->];
    }

    can traverse_component with Component entry {
        if here.name in self.visited {
            self.cycle_flag = True;
            disengage;
        }
        self.visited.append(here.name);

        marker = "[!] " if here.critical else "    ";
        verdict = "BREAK" if here.breaking_notes else "ok  ";
        print(
            f"{marker}{here.name}: {here.current_version} -> {here.target_version}"
            f" | workloads={here.workload_count} | {verdict}"
        );

        visit [->:DependsOn:->];
        visit [->:RaisesRisk:->];
    }

    can inspect_risk with Risk entry {
        print(
            f"    risk[{here.severity}] {here.rationale}"
            f"  (evidence: {here.evidence_ref})"
        );
        visit [-->];
    }

    can inspect_checklist with ChecklistItem entry {
        print(f"    checklist: {here.title}");
        visit [-->];
    }
}

walker RolloutOrderer {
    has order: list[str] = [];
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [->:DependsOn:->];
    }

    can order_component with Component entry {
        if here.name in self.order {
            self.cycle_detected = True;
            print(f"  cycle detected touching {here.name}");
            disengage;
        }
        self.order.append(here.name);
        visit [->:DependsOn:->];
    }
}

with entry {
    api = Component(
        name="kube-apiserver",
        current_version="1.28.4",
        target_version="1.29.1",
        workload_count=12,
        critical=True,
        breaking_notes="PodDisruptionBudget field renamed in v1.29"
    );
    ccm = Component(
        name="cloud-controller-manager",
        current_version="1.28.4",
        target_version="1.29.1",
        workload_count=3,
        critical=True
    );
    cni = Component(
        name="cilium",
        current_version="1.14.2",
        target_version="1.15.1",
        workload_count=1,
        critical=True
    );
    ingress = Component(
        name="ingress-nginx",
        current_version="1.9.4",
        target_version="1.10.0",
        workload_count=40,
        critical=False,
        breaking_notes="annotation v1 -> v1beta1"
    );
    monitor = Component(
        name="prometheus",
        current_version="2.48.0",
        target_version="2.49.0",
        workload_count=5,
        critical=False
    );

    root ++> api
        +>:DependsOn:+> ccm
        +>:DependsOn:+> cni
        +>:DependsOn:+> ingress
        +>:DependsOn:+> monitor;

    api +>:DependsOn(required_min_version="1.29"):+> ingress;

    risk_pdb = Risk(
        severity="HIGH",
        rationale="PDB schema change in apiserver may invalidate existing policies",
        evidence_ref="evidence/pdb-diff.yaml"
    );
    risk_ingress = Risk(
        severity="MEDIUM",
        rationale="ingress annotations deprecation requires manifest rewrite",
        evidence_ref="evidence/ingress-annotations.md"
    );

    api +>:RaisesRisk(confidence=0.92):+> risk_pdb;
    ingress +>:RaisesRisk(confidence=0.71):+> risk_ingress;

    api +>:AffectsWorkload(replica_count=3, pdb_min_available=2):+> ingress;
    cni +>:AffectsWorkload(replica_count=2, pdb_min_available=1):+> ingress;

    root spawn UpgradeAnalyst();

    print("--- dependency-ordered rollout attempt ---");
    orderer = RolloutOrderer();
    root spawn orderer;
    if orderer.cycle_detected {
        print("  aborting: dependency cycle must be resolved before upgrade");
    } else {
        print("  rollout chain: " + ", ".join(orderer.order));
    }
}
