test "lean export traverses every source file independently" {
    g = Group(name="Batch", slug="batch");
    af1 = AuditFile(title="first.jsonl");
    af2 = AuditFile(title="second.jsonl");
    ev = AuditEvent(label="login");

    root +>:BelongsToGroup:+> g;
    g +>:BelongsToGroup(role="source"):+> af1;
    g +>:BelongsToGroup(role="source"):+> af2;
    af1 +>:MentionedIn(role="evidence"):+> ev;

    assert len([g ->:BelongsToGroup:->]) == 2, f"expected two source files";
    assert af1 in [g ->:BelongsToGroup:->], f"first source file missing";
    assert af2 in [g ->:BelongsToGroup:->], f"second source file missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LeanExporter();
    }
    out = buf.getvalue();

    assert "[lean]   AuditFile meta=first.jsonl (0) available=True heavy=DEFERRED" in out, f"first file missing: {out}";
    assert "[lean]   AuditFile meta=second.jsonl (0) available=True heavy=DEFERRED" in out, f"second file missing: {out}";
    assert "[lean]   AuditEvent login heavy=DEFERRED" in out, f"evidence event missing: {out}";
}

