    root +>:ResidentIn(since="init"):+> epoch_node;

    first = ReconcileFrame(frame=0, last_residency_epoch=-1);
    first spawn root;
    assert first.recomputed, f"initial frame did not recompute: {first.last_coverage}";
    assert first.last_residency_epoch == 0, f"wrong sampled epoch: {first.last_residency_epoch}";
    assert first.last_coverage == "computed", f"wrong coverage state: {first.last_coverage}";
    assert first.last_seam == "computed", f"wrong seam state: {first.last_seam}";

    second = ReconcileFrame(
        frame=1,
        last_residency_epoch=first.last_residency_epoch
    );
    second spawn root;
    assert not second.recomputed, f"unchanged frame recomputed: {second.last_coverage}";
    assert second.last_coverage == "unchanged", f"coverage was not skipped: {second.last_coverage}";
