    binSub_callee = Callee(name="tSub", kind="arithmetic");
    binSub +>:CarriesCall:+> binSub_callee;

    binMul = CallSite(label="binMul", raw_callee_kind="multiplicative_expression");
    binMul_callee = Callee(name="tMul", kind="arithmetic");
    binMul +>:CarriesCall:+> binMul_callee;

    binDiv = CallSite(label="binDiv", raw_callee_kind="multiplicative_expression");
    binDiv_callee = Callee(name="tDiv", kind="arithmetic");
    binDiv +>:CarriesCall:+> binDiv_callee;

    binMod = CallSite(label="binMod", raw_callee_kind="multiplicative_expression");
    binMod_callee = Callee(name="tMod", kind="arithmetic");
    binMod +>:CarriesCall:+> binMod_callee;

