test "invalidation revokes a targeted execution" {
    exec_a = RuntimeExecution(
        name="exec-A",
        snapshot="snap-001",
        lease="lease-A",
        evidence="ev-A"
    );
    binding = ProviderBinding(
        provider="codex",
        adapter_version="0.149.0",
        opaque_ref="thread/opaque-a",
        coverage="guest"
    );

    root ++> exec_a;
    exec_a +>:BoundTo(epoch=1):+> binding;

    invalidator = StaleInvalidator(target_name="exec-A");
    root spawn invalidator;

    assert exec_a.revoked == True,
        f"execution was not revoked: {exec_a.revoked}";

    res = root spawn BindingAuditor();

    assert "[FAIL-CLOSED] exec-A: stale or revoked authority" in res.findings,
        f"missing post-invalidation failure: {res.findings}";
    assert "[supported] provider=codex v0.149.0 ref=thread/opaque-a" not in res.findings,
        f"stale binding remained reachable to audit: {res.findings}";
}

