"""RBAC audit event infrastructure modeled as a graph: posture/policy nodes
carry typed payloads, ingestion sync events track success/error, and a
disconnected-cluster walker queues events and replays them when the cluster
returns. A cycle hunter traverses the ingestion connector dependency graph
to detect circular triggers."""

# ---------- Entity archetypes ----------

node AuditEvent {
    has event_id: str = "";
    has event_type: str = "";
    has actor: str = "";
    has timestamp: str = "";
}

node PostureChangeEvent(AuditEvent) {
    has before: str = "";
    has after: str = "";
}

node PolicyCrudEvent(AuditEvent) {
    has policy_id: str = "";
    has action: str = "";
}

node IngestionSyncEvent(AuditEvent) {
    has connector: str = "";
    has asset_count: int = 0;
    has success: bool = True;
    has error: str = "";
}

node QueuedEvent {
    has event_type: str = "";
    has payload: str = "";
}

# ---------- Edge archetypes ----------

edge EmittedBy { }
edge Triggered { }
edge QueuedIn { }
edge ReplayedTo { }

# ---------- Walker: Auditor traverses the audit log chain ----------

walker Auditor {
    has seen: list[str] = [];
    has duplicates: int = 0;
    has dedupe: dict[str, int] = {};

    can start with Root entry {
        print("Auditor starting at root; expecting AuditEvent chain");
        visit [-->];
    }

    can audit with AuditEvent entry {
        if here.event_id in self.dedupe {
            self.duplicates += 1;
            print(f"  [DUP] {here.event_type} id={here.event_id} already logged");
            visit [-->];
            return;
        }
        self.dedupe[here.event_id] = 1;
        self.seen.append(here.event_type);
        status = "FAIL" if here.event_type.startswith("sync-error") else "OK";
        print(f"  [{status}] {here.event_type} actor={here.actor} t={here.timestamp}");
        visit [-->];
    }
}

# ---------- Walker: Disconnected cluster -- queue then replay ----------

walker DisconnectedReplayer {
    has queued: list[QueuedEvent] = [];
    has replayed: int = 0;
    has dropped_on_full: int = 0;
    has queue_capacity: int = 5;
    has max_hops: int = 50;

    can start with Root entry {
        print(f"Cluster OFFLINE -> local queue capacity={self.queue_capacity}");
        visit [->:QueuedIn:->];
    }

    can collect with QueuedEvent entry {
        if len(self.queued) >= self.queue_capacity {
            self.dropped_on_full += 1;
            print(f"  [DROP] queue full, evicting {here.event_type}");
            visit [-->];
            return;
        }
        self.queued.append(here);
        self.replayed += 1;
        print(f"  [ENQ] {here.event_type} payload={here.payload}");
        visit [-->];
    }
}

# ---------- Walker: Cycle detection across ingestion connectors ----------

walker CycleHunter {
    has path: list[str] = [];
    has cycles: list[str] = [];
    has max_steps: int = 10;
    has steps: int = 0;

    can start with Root entry {
        print("CycleHunter traversing ingestion connector graph");
        visit [-->];
    }

    can probe with IngestionSyncEvent entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            print("  [STOP] step cap reached");
            disengage;
        }
        if here.connector in self.path {
            cycle_label = " -> ".join(self.path) + " -> " + here.connector;
            self.cycles.append(cycle_label);
            print(f"  [CYCLE] back to {here.connector}");
            disengage;
        }
        self.path.append(here.connector);
        print(f"  [VISIT] {here.connector} (path len={len(self.path)})");
        visit [->:Triggered:->] else { disengage; }
    }
}

# ---------- Demonstration wiring ----------

with entry {
    # Build a small audit log chain on root.
    root ++> PostureChangeEvent(
        event_id="evt-001", event_type="posture-changed",
        actor="alice", timestamp="2025-01-01T00:00:00Z",
        before="open", after="restricted"
    );

    root ++> PolicyCrudEvent(
        event_id="evt-002", event_type="policy-created",
        actor="bob", timestamp="2025-01-01T00:01:00Z",
        policy_id="pol-42", action="create"
    );

    root ++> PolicyCrudEvent(
        event_id="evt-003", event_type="policy-updated",
        actor="bob", timestamp="2025-01-01T00:02:00Z",
        policy_id="pol-42", action="update"
    );

    root ++> PolicyCrudEvent(
        event_id="evt-004", event_type="policy-deleted",
        actor="carol", timestamp="2025-01-01T00:03:00Z",
        policy_id="pol-42", action="delete"
    );

    root ++> IngestionSyncEvent(
        event_id="evt-010", event_type="sync-completed",
        actor="system", timestamp="2025-01-01T00:10:00Z",
        connector="github-catalog", asset_count=42, success=True
    );

    root ++> IngestionSyncEvent(
        event_id="evt-011", event_type="sync-error",
        actor="system", timestamp="2025-01-01T00:11:00Z",
        connector="github-catalog", asset_count=0, success=False,
        error="HTTP 503"
    );

    # Duplicate emission (RBAC AuditorService would already cover this).
    root ++> IngestionSyncEvent(
        event_id="evt-011", event_type="sync-error",
        actor="system", timestamp="2025-01-01T00:11:00Z",
        connector="github-catalog", asset_count=0, success=False,
        error="HTTP 503"
    );

    # Run the auditor -- demonstrates emission + dedup.
    auditor = Auditor();
    root spawn auditor;
    print(f"Auditor saw {len(auditor.seen)} unique events, "
          f"{auditor.duplicates} duplicates\n");

    # Build a disconnected cluster queue via typed edges (bounded size).
    q1 = QueuedEvent(event_type="sync-completed", payload="github:42 assets");
    q2 = QueuedEvent(event_type="sync-error",    payload="github:HTTP 503");
    q3 = QueuedEvent(event_type="policy-created", payload="pol-99");
    q4 = QueuedEvent(event_type="policy-updated", payload="pol-99");
    q5 = QueuedEvent(event_type="policy-deleted", payload="pol-99");
    q6 = QueuedEvent(event_type="entity-created", payload="cmp-7");
    root +>:QueuedIn:+> q1;
    root +>:QueuedIn:+> q2;
    root +>:QueuedIn:+> q3;
    root +>:QueuedIn:+> q4;
    root +>:QueuedIn:+> q5;
    root +>:QueuedIn:+> q6;

    replayer = DisconnectedReplayer(queue_capacity=5);
    root spawn replayer;
    print(f"Replayer collected {len(replayer.queued)} events, "
          f"dropped {replayer.dropped_on_full} when full\n");

    # Cycle hunter across an ingestion connector dependency graph.
    c1 = IngestionSyncEvent(
        event_id="c1", event_type="sync-completed",
        actor="system", timestamp="t1", connector="github", asset_count=1
    );
    c2 = IngestionSyncEvent(
        event_id="c2", event_type="sync-completed",
        actor="system", timestamp="t2", connector="gitlab", asset_count=1
    );
    c3 = IngestionSyncEvent(
        event_id="c3", event_type="sync-completed",
        actor="system", timestamp="t3", connector="azure-devops", asset_count=1
    );
    root ++> c1;
    c1 +>:Triggered:+> c2;
    c2 +>:Triggered:+> c3;
    c3 +>:Triggered:+> c1;  # intentional cycle to exercise CycleHunter
    hunter = CycleHunter(max_steps=10);
    root spawn hunter;
    print(f"CycleHunter found {len(hunter.cycles)} cycle(s): {hunter.cycles}");
}
```

