import io;
import from contextlib { redirect_stdout }

test "all in-scope writes pass" {
    root ++> ScopedItem(
        title="all in scope",
        declared_writes=["src/a.ts", "src/b.ts"]
    );
    si = [root -->][0];
    f1 = File(path="src/a.ts", in_scope=False);
    f2 = File(path="src/b.ts", in_scope=False);
    si +>:AttemptedOn:+> f1;
    si +>:AttemptedOn:+> f2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        si spawn WriteGuard();
    }

    assert not si.blocked, f"should not be blocked; refused={si.refused_writes}";
    assert len(si.refused_writes) == 0, f"got {si.refused_writes}";
    assert f1.in_scope and f2.in_scope, f"a.in_scope={f1.in_scope} b.in_scope={f2.in_scope}";
}

test "out-of-scope writes are refused" {
    root ++> ScopedItem(
        title="probe attempt",
        declared_writes=["src/parser.ts"]
    );
    si = [root -->][0];
    good = File(path="src/parser.ts", in_scope=False);
    bad = File(path="dependency-integrity.ts", in_scope=False);
    si +>:AttemptedOn:+> good;
    si +>:AttemptedOn:+> bad;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        si spawn WriteGuard();
    }
    out = buf.getvalue();

    assert si.blocked, "must block when out-of-scope write attempted";
    assert "dependency-integrity.ts" in si.refused_writes, f"got {si.refused_writes}";
    assert good.in_scope, "declared file should be marked in scope";
    assert not bad.in_scope, "prohibited file must remain out of scope";
    assert "refused write to dependency-integrity.ts" in out, f"missing OUT marker: {out}";
}

test "harness-managed paths always permitted" {
    root ++> ScopedItem(
        title="escape hatch",
        declared_writes=["src/only.ts"]
    );
    si = [root -->][0];
    only = File(path="src/only.ts", in_scope=False);
    dl = File(path="docs/decision-log/7.md", in_scope=False);
    ck = File(path="checkpoints", in_scope=False);
    si +>:AttemptedOn:+> only;
    si +>:AttemptedOn:+> dl;
    si +>:AttemptedOn:+> ck;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        si spawn WriteGuard();
    }

    assert not si.blocked, f"harness paths must not trigger block; refused={si.refused_writes}";
    assert len(si.refused_writes) == 0, f"got {si.refused_writes}";
    assert dl.in_scope, "docs/decision-log/ must be in scope";
    assert ck.in_scope, "checkpoints must be in scope";
    assert only.in_scope, "declared file must be in scope";
}

test "prohibited work from #548 is blocked" {
    root ++> ScopedItem(
        title="#548 message-only patch",
        declared_writes=["src/parser.ts", "src/format.ts"]
    );
    si = [root -->][0];
    f1 = File(path="src/parser.ts", in_scope=True);
    f2 = File(path="src/format.ts", in_scope=True);
    f3 = File(path="dependency-integrity.ts", in_scope=False);
    f4 = File(path="seat-isolation.ts", in_scope=False);
    f5 = File(path="worktree-deps.ts", in_scope=False);
    si +>:AttemptedOn:+> f1;
    si +>:AttemptedOn:+> f2;
    si +>:AttemptedOn:+> f3;
    si +>:AttemptedOn:+> f4;
    si +>:AttemptedOn:+> f5;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        si spawn WriteGuard();
    }
    out = buf.getvalue();

    assert si.blocked, "must block when prohibited work attempted";
    assert len(si.refused_writes) == 3, f"expected 3 refused, got {si.refused_writes}";
    assert "dependency-integrity.ts" in si.refused_writes, f"got {si.refused_writes}";
    assert "seat-isolation.ts" in si.refused_writes, f"got {si.refused_writes}";
    assert "worktree-deps.ts" in si.refused_writes, f"got {si.refused_writes}";
    assert f1.in_scope and f2.in_scope, "declared files must remain in scope";
    assert not (f3.in_scope or f4.in_scope or f5.in_scope), "all prohibited files must stay out of scope";
    assert "refused write to" in out, f"missing OUT marker: {out}";
}

