"""Migration tracker: nine service nodes ordered by dependency, walked in
phase sequence with cycle-safe traversal and reachability reporting."""

node Service {
    has name: str = "";
    has issue: str = "";
    has migrated: bool = False;
    has critical: bool = False;
}

node DatabaseTime {
    has name: str = "";
    has issue: str = "";
    has migrated: bool = False;
}

node Prerequisite {
    has title: str = "";
    has issue: str = "";
    has blocking: bool = True;
}

edge DependsOn { has weight: int = 1; }
edge Blocks { has severity: int = 1; }

walker MigrationPlanner {
    has visited: list[str] = [];
    has order: list[str] = [];
    has pending: list[str] = [];

    can start with Root entry {
        print("=== Migration Planner: phase 0 -> phase 4 ===");
        visit [->:DependsOn:->];
    }

    can plan with Service | DatabaseTime entry {
        label = here.name if here.name else "(unnamed)";
        if label in self.visited {
            disengage;
        }
        self.visited.append(label);
        if not here.migrated {
            self.order.append(label);
            print(f"  -> migrate {label} ({here.issue})");
        } else {
            print(f"  skip {label} (already migrated)");
        }
        visit [->:DependsOn:->];
    }

    can audit with Prerequisite entry {
        status = "BLOCKING" if here.blocking else "optional";
        print(f"[{status}] {here.title} ({here.issue})");
        if here.blocking {
            self.pending.append(here.issue);
        }
        visit [->:Blocks:->];
    }

    can finish with Root entry {
        print("--- planned order ---");
        for (i, name) in enumerate(self.order) {
            print(f"  {i + 1}. {name}");
        }
        if self.pending {
            print("--- unresolved prerequisites ---");
            for issue in self.pending {
                print(f"  ! {issue}");
            }
        } else {
            print("no unresolved prerequisites");
        }
    }
}

with entry {
    db_time = DatabaseTime(name="database-time", issue="#308", migrated=False);
    rooms = Service(name="rooms-service", issue="#302", migrated=False);
    equipment = Service(name="equipment-service", issue="#305", migrated=False);
    tables = Service(name="tables-service", issue="#333", migrated=False, critical=True);
    reservations = Service(name="reservations-service", issue="#300", migrated=False, critical=True);
    events = Service(name="events-service", issue="#303", migrated=False);
    club_events = Service(name="club-events-service", issue="#304", migrated=False);
    saved_games = Service(name="saved-games-service", issue="#301", migrated=False);
    library_games = Service(name="library-games-service", issue="#306", migrated=False);
    partners = Service(name="partners-service", issue="#307", migrated=False);

    root +>:DependsOn:+> db_time;
    db_time +>:DependsOn:+> rooms;
    rooms +>:DependsOn:+> equipment;
    equipment +>:DependsOn:+> tables;
    tables +>:DependsOn:+> reservations;
    events +>:DependsOn:+> reservations;
    db_time +>:DependsOn:+> events;
    rooms +>:DependsOn:+> reservations;

    mock_helper = Prerequisite(title="shared raw-SQL mock helper", issue="#332", blocking=True);
    schema_fix = Prerequisite(title="apply-neon-schema no-op fix", issue="#328", blocking=True);
    middleware = Prerequisite(title="middleware deny-by-default", issue="#330", blocking=True);
    homepage = Prerequisite(title="homepage SSR fix", issue="#323", blocking=False);

    root +>:Blocks(severity=2):+> mock_helper;
    root +>:Blocks(severity=3):+> schema_fix;
    root +>:Blocks(severity=3):+> middleware;
    root +>:Blocks(severity=1):+> homepage;

    root spawn MigrationPlanner();
}
