import io;
import from contextlib { redirect_stdout }

test "orders dependencies and skips migrated services" {
    db_time = DatabaseTime(name="order-database-time", issue="#308", migrated=False);
    rooms = Service(name="order-rooms", issue="#302", migrated=False);
    equipment = Service(name="order-equipment", issue="#305", migrated=True);
    reservations = Service(name="order-reservations", issue="#300", migrated=False);

    root +>:DependsOn:+> db_time;
    db_time +>:DependsOn:+> rooms;
    rooms +>:DependsOn:+> equipment;
    equipment +>:DependsOn:+> reservations;

    buf = io.StringIO();
    with redirect_stdout(buf) {
