    out = buf.getvalue();

    selected = [name for name in res.order if name in ["order-database-time", "order-rooms", "order-reservations"]];
    assert selected == ["order-database-time", "order-rooms", "order-reservations"], f"got {selected}";
    assert "skip order-equipment" in out, f"missing skip output: {out}";
