    second = Service(name="cycle-second", issue="#second", migrated=False);

    root +>:DependsOn:+> first;
    first +>:DependsOn:+> second;
    second +>:DependsOn:+> first;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn MigrationPlanner();
    }
    out = buf.getvalue();

    selected = [name for name in res.order if name in ["cycle-first", "cycle-second"]];
    assert selected == ["cycle-first", "cycle-second"], f"got {selected}";
    assert "cycle-first" in out, f"missing first cycle node: {out}";
    assert "cycle-second" in out, f"missing second cycle node: {out}";
}

test "audit collects blocking prerequisites and follows block edges" {
    raw_sql = Prerequisite(title="audit-raw-sql", issue="#332", blocking=True);
    schema = Prerequisite(title="audit-schema", issue="#328", blocking=True);
    homepage = Prerequisite(title="audit-homepage", issue="#323", blocking=False);

    raw_sql +>:Blocks:+> schema;
    schema +>:Blocks:+> homepage;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = raw_sql spawn MigrationPlanner();
    }
    out = buf.getvalue();

    assert len(res.pending) == 2, f"got {res.pending}";
    assert res.pending[0] == "#332", f"got {res.pending}";
    assert res.pending[1] == "#328", f"got {res.pending}";
    assert "[BLOCKING] audit-raw-sql" in out, f"missing blocking output: {out}";
    assert "[optional] audit-homepage" in out, f"missing optional output: {out}";
}

