    h10 = Checkpoint(title="h10", horizon=10,
                     cumulative_regret=1.2, violations=0,
                     lineage_id="S-10");
    h20 = Checkpoint(title="h20", horizon=20,
                     cumulative_regret=6.5, violations=2,
