test "disengages safely on cyclic lineage" {
    policy = Policy(name="cycle-policy");

    first = Checkpoint(title="cycle-h10", horizon=10,
                       cumulative_regret=1.0, lineage_id="C-1");
    second = Checkpoint(title="cycle-h20", horizon=20,
                        cumulative_regret=2.0, lineage_id="C-2");

    root ++> policy;
    policy +>:AdoptedBy(policy="stateless"):+> first;
    first +>:NextHorizon(step=1):+> second;
    second +>:NextHorizon(step=99):+> first;

