    assert result.visited_count == 2, f"got {result.visited_count}";
    assert len(result.guard) == 2, f"got {result.guard}";
    assert result.total_regret == 3.0, f"got {result.total_regret}";
    assert result.unsafe_rollbacks == 0, f"got {result.unsafe_rollbacks}";
    assert result.frontier == [(10, 1.0), (20, 2.0)],
        f"got {result.frontier}";
}

test "state-aware policy improves the deployment frontier" {
    stateless = Policy(name="stateless-v1", state_aware=False);
    aware = Policy(name="state-aware-v1", state_aware=True);

    s10 = Checkpoint(title="stateless-h10", horizon=10,
                     cumulative_regret=1.0, violations=1,
                     lineage_id="S-10");
    s20 = Checkpoint(title="stateless-h20", horizon=20,
                     cumulative_regret=6.0, violations=2,
                     lineage_id="S-20");
    s50 = Checkpoint(title="stateless-h50", horizon=50,
                     cumulative_regret=8.0, violations=1,
                     invalidated=True, lineage_id="S-50");

    a10 = Checkpoint(title="aware-h10", horizon=10,
                     cumulative_regret=0.4, violations=0,
                     lineage_id="A-10");
    a20 = Checkpoint(title="aware-h20", horizon=20,
                     cumulative_regret=0.9, violations=0,
                     lineage_id="A-20");
    a50 = Checkpoint(title="aware-h50", horizon=50,
                     cumulative_regret=1.7, violations=0,
                     lineage_id="A-50");

    root ++> stateless;
    root ++> aware;

    stateless +>:AdoptedBy(policy="stateless"):+> s10;
    s10 +>:NextHorizon(step=1):+> s20;
    s20 +>:NextHorizon(step=2):+> s50;

    aware +>:AdoptedBy(policy="state-aware"):+> a10;
    a10 +>:NextHorizon(step=1):+> a20;
    a20 +>:NextHorizon(step=2):+> a50;

    stat_result = stateless spawn SequenceAuditor();
    aware_result = aware spawn SequenceAuditor();

    assert stat_result.visited_count == 3, f"got {stat_result.visited_count}";
    assert aware_result.visited_count == 3, f"got {aware_result.visited_count}";
    assert stat_result.total_regret == 15.0, f"got {stat_result.total_regret}";
    assert aware_result.total_regret == 3.0, f"got {aware_result.total_regret}";
    assert stat_result.total_violations == 4, f"got {stat_result.total_violations}";
    assert aware_result.total_violations == 0, f"got {aware_result.total_violations}";
    assert stat_result.unsafe_rollbacks == 1, f"got {stat_result.unsafe_rollbacks}";
    assert aware_result.unsafe_rollbacks == 0, f"got {aware_result.unsafe_rollbacks}";
    assert aware_result.total_regret < stat_result.total_regret,
        f"aware={aware_result.total_regret}, stateless={stat_result.total_regret}";
}

