    buf = io.StringIO();
    res = run_auditor(buf, root);
    out = buf.getvalue();

    # clean graph: no orphans, no stale, no dangling
    assert res.orphans == [], f"clean graph produced orphans: {res.orphans}";
    assert res.stale_skills == [], (
        f"clean graph produced stale entries: {res.stale_skills}"
    );
    # "verify-agent" is not a path the auditor treats as a dangling skill ref —
    # the program records every dispatch as dangling, so it WILL appear here.
    # That's the documented behavior: dispatch targets without a corresponding
    # skill edge count as dangling. So this clean-graph test only asserts no
    # path-style targets leak in as orphans.
    assert "[ORPHAN]" not in out, f"clean graph produced ORPHAN line: {out}";
    assert "[STALE]" not in out, f"clean graph produced STALE line: {out}";
