    wf ++> retry;
    retry +>:StructuralDep:+> charge;
    charge +>:TimingDep(weight=4.0):+> retry;

    res = root spawn CriticalPath();

    assert res.path == ["ChargeCard"], f"got {res.path}";
    assert res.path_weight == 4.0, f"got {res.path_weight}";
    assert res.visited == ["ChargeCard"], f"got {res.visited}";
}

