    policy +>:RunOf:+> advisory;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Audit();
    }
    out = buf.getvalue();
    assert res.bypass == 1, f"expected one bypass, got bypass={res.bypass}";
    assert res.blocked == 0, f"bypassable gate should not block, got blocked={res.blocked}";
    assert "[BYPASS] DualDAG-Advisory: bypassable execution gate" in out, f"missing bypass marker: {out}";
}

test "stale admissible witness is counted separately from blocking" {
    stale_wit = Witness(label="advisory-wit", admissible=True, stale=True);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = stale_wit spawn Audit();
    }
    out = buf.getvalue();
    assert res.stale == 1, f"expected stale=1, got stale={res.stale}";
    assert res.blocked == 0, f"stale admissible witness must not block, got blocked={res.blocked}";
    assert "stale-witness advisory-wit: ADMIT" in out, f"missing stale admit marker: {out}";
}

test "frozen support policy identity is pinned before condition sweep" {
    policy = SupportPolicy(
        policy_id="eac-primary",
        version="1.0.0",
        fingerprint="sha256:eac-primary-v1"
    );
    baseline = Condition(label="Baseline", bypassable=True);
    root +>:PolicyOf:+> policy;
    policy +>:RunOf:+> baseline;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Audit();
    }
    out = buf.getvalue();
    assert "policy pinned: eac-primary v1.0.0" in out, f"missing policy pin: {out}";
    assert baseline.runs == 1, f"condition should be swept once, got runs={baseline.runs}";
}

test "evaluator oracle stays unobserved during authority audit walk" {
    policy = SupportPolicy(policy_id="p", version="1", fingerprint="fp");
    authority = Condition(label="DualDAG-Authority", bypassable=False);
    auth_wit = Witness(label="authority-wit", admissible=False, stale=False);
    oracle = GroundTruth(label="evaluator-only", observed=False);
    root +>:PolicyOf:+> policy;
    root +>:OracleOf:+> oracle;
    policy +>:RunOf:+> authority;
    authority +>:WitnessOf:+> auth_wit;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Audit();
    }
    out = buf.getvalue();
    assert oracle.observed == False, f"oracle must stay hidden, observed={oracle.observed}";
    assert "oracle observed:" not in out, f"audit should not reach oracle: {out}";
    assert res.blocked == 1, f"authority enforcement still applies, got blocked={res.blocked}";
}

