import io;
import from contextlib { redirect_stdout }

test "audits typed artifact profiles in dependency order" {
    identity = Artifact(
        name="identity",
        integrity="content-addressed",
        staleness_bound="1h",
        pacelc="PC/EL",
        governance="self",
    );
    policy = Artifact(
        name="policy",
        integrity="location-bound",
        staleness_bound="24h",
        pacelc="PA/EC",
        governance="publisher",
    );
    revocation = Artifact(
        name="revocation",
        integrity="content-addressed",
        staleness_bound="7d",
        pacelc="PC/EC",
        governance="registry",
    );

    root ++> identity;
    identity +>:Resolves(pacelc="PC/EL", governance="self"):+> policy;
    policy +>:Resolves(pacelc="PA/EC", governance="publisher"):+> revocation;

    assert len([root-->]) == 1, f"unexpected root children: {len([root-->])}";
    assert len([identity ->:Resolves:->]) == 1, "identity dependency edge missing";
    assert len([policy ->:Resolves:->]) == 1, "policy dependency edge missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
    }
    out = buf.getvalue();

    assert len(res.seen) == 3, f"unexpected visited artifacts: {res.seen}";
    assert "[identity] integrity=content-addressed staleness<=1h pacelc=PC/EL gov=self depth=0" in out, f"identity audit missing: {out}";
    assert "[policy] integrity=location-bound staleness<=24h pacelc=PA/EC gov=publisher depth=1" in out, f"policy audit missing: {out}";
    assert "[revocation] integrity=content-addressed staleness<=7d pacelc=PC/EC gov=registry depth=2" in out, f"revocation audit missing: {out}";
}

test "detects a resolution cycle without recurring forever" {
    first = Artifact(name="first", pacelc="PC/EC", governance="self");
    second = Artifact(name="second", pacelc="PA/EL", governance="publisher");
    third = Artifact(name="third", pacelc="PC/EL", governance="registry");

    root ++> first;
    first +>:Resolves:+> second;
    second +>:Resolves:+> third;
    third +>:Resolves:+> first;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
    }
    out = buf.getvalue();

    assert len(res.seen) == 3, f"cycle traversal visited unexpected nodes: {res.seen}";
    assert "cycle at first" in res.cycles, f"cycle was not recorded: {res.cycles}";
    assert "[first]" in out, f"first artifact was not audited: {out}";
    assert "[second]" in out, f"second artifact was not audited: {out}";
    assert "[third]" in out, f"third artifact was not audited: {out}";
}

test "keeps supersession relationships typed and out of resolution traversal" {
    policy = Artifact(
        name="policy",
        integrity="location-bound",
        staleness_bound="24h",
        pacelc="PA/EC",
        governance="publisher",
    );
    revocation = Artifact(name="revocation", staleness_bound="7d");
    newer = Artifact(name="newer");

    root ++> policy;
    policy +>:Resolves:+> revocation;
    policy +>:Supersedes(staleness_bound="24h"):+> newer;

    assert len([policy ->:Resolves:->]) == 1, "resolution relationship missing";
    assert revocation in [policy ->:Resolves:->], "revocation is not a resolution target";
    assert len([policy ->:Supersedes:->]) == 1, "supersession relationship missing";
    assert newer in [policy ->:Supersedes:->], "newer artifact is not a supersession target";
    assert newer.integrity == "content-addressed", f"unexpected default integrity: {newer.integrity}";
    assert newer.staleness_bound == "T", f"unexpected default staleness bound: {newer.staleness_bound}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
    }
    out = buf.getvalue();

    assert "[policy]" in out, f"policy was not audited: {out}";
    assert "[revocation]" in out, f"resolution target was not audited: {out}";
    assert "[newer]" not in out, f"superseded artifact was incorrectly resolved: {out}";
}

test "stops auditing after the configured depth cap" {
    first = Artifact(name="first");
    second = Artifact(name="second");
    third = Artifact(name="third");

    root ++> first;
    first +>:Resolves:+> second;
    second +>:Resolves:+> third;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor(max_depth=2);
    }
    out = buf.getvalue();

    assert res.depth == 2, f"unexpected final depth: {res.depth}";
    assert "[first]" in out, f"first artifact was not audited: {out}";
    assert "[second]" in out, f"second artifact was not audited: {out}";
    assert "[third]" not in out, f"depth cap was ignored: {out}";
}

