import io;
import from contextlib { redirect_stdout }

test "fork provenance preserved via ForkSource edges" {
    main = Session(title="main-session", status="running");
    root ++> main;
    fork = ForkedSession(title="design-sketch", status="idle");
    main +>:ForkSource(forked_from_label="main-session"):+> fork;

    assert fork in [main ->:ForkSource:->], "ForkSource edge missing from source to fork";
    assert not (fork in [main ->:SpawnedBy:->]), "fork must not carry SpawnedBy ownership";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageProbe();
    }
