}

test "sidebar ignores ForkSource and does not nest forks" {
    main = Session(title="main-session", status="running");
    root ++> main;
    fork = ForkedSession(title="design-sketch", status="idle");
    main +>:ForkSource(forked_from_label="main-session"):+> fork;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SidebarRenderer();
    }
    out = buf.getvalue();
    assert "[sidebar] session: main-session (running)" in out, f"missing main session row: {out}";
    assert "design-sketch" not in out, f"fork must not appear via ownership traversal: {out}";
    assert "[sidebar] forked:" not in out, f"fork must not render as nested sidebar child: {out}";
}

test "spawned subagent stays in ownership hierarchy" {
    main = Session(title="main-session", status="running");
    root ++> main;
    sub = SubagentSession(title="research-subagent", status="running");
    main +>:SpawnedBy(spawned_by_label="main-session"):+> sub;

    assert sub in [main ->:SpawnedBy:->], "SpawnedBy edge missing from session to subagent";
    assert len([root-->]) == 1, f"expected one direct root child, got {len([root-->])}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SidebarRenderer();
    }
    out = buf.getvalue();
    assert "[sidebar] session: main-session (running)" in out, f"missing parent session row: {out}";
    assert "[sidebar] subagent: research-subagent (running)" in out, f"missing nested subagent row: {out}";
    main_pos = out.find("main-session");
    sub_pos = out.find("research-subagent");
    assert main_pos >= 0 and sub_pos > main_pos, f"subagent should follow source in walk order: {out}";
}

test "channel thread containment preserved in sidebar" {
    main = Session(title="main-session", status="running");
    root ++> main;
    thread = ChannelThread(title="design-thread", status="running");
    main +>:ChannelChild(channel_label="design"):+> thread;
    child = ChildSession(title="thread-note-1", status="idle");
    thread +>:ChannelChild(channel_label="design"):+> child;

    assert thread in [main ->:ChannelChild:->], "ChannelChild edge missing from session to thread";
    assert child in [thread ->:ChannelChild:->], "ChannelChild edge missing from thread to child";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SidebarRenderer();
    }
    out = buf.getvalue();
    assert "[sidebar] session: main-session (running)" in out, f"missing session row: {out}";
    assert "[sidebar] thread: design-thread (running)" in out, f"missing thread row: {out}";
    assert "[sidebar] child: thread-note-1 (idle)" in out, f"missing contained child row: {out}";
    thread_pos = out.find("design-thread");
    child_pos = out.find("thread-note-1");
    assert thread_pos >= 0 and child_pos > thread_pos, f"child should follow thread in walk order: {out}";
}

test "top-level fork renders as peer without ownership descent" {
    main = Session(title="main-session", status="running");
    root ++> main;
    fork = ForkedSession(title="alt-approach", status="idle");
    root ++> fork;
    main +>:ForkSource(forked_from_label="main-session"):+> fork;

    assert len([root-->]) == 2, f"fork should be a direct root peer, got {len([root-->])} children";
    assert fork in [main ->:ForkSource:->], "ForkSource provenance must remain on fork";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SidebarRenderer();
    }
    out = buf.getvalue();
    assert "[sidebar] session: main-session (running)" in out, f"missing session row: {out}";
    assert "[sidebar] forked: alt-approach (idle)" in out, f"missing top-level fork row: {out}";
    assert "research-subagent" not in out, f"fork render must not imply spawned ownership: {out}";
}

