"""NYC official-source catalog demo.

Models the BORG inventory of alternate official NYC APIs as nodes
(Source, ConflictAssertion, Observation) connected by typed edges
(SourceDeclares, AssertsCompeting, PreservesRaw). A walker traverses
the registry, collecting conflicts without overwriting competing
assertions and reporting circuit-breaker freshness status.
"""

node Source {
    has source_id: str = "";
    has authority_class: str = "";
    has jurisdiction: str = "";
    has endpoint: str = "";
    has cadence: str = "";
    has schema_fingerprint: str = "";
    has license_notes: str = "";
    has consumer_status: str = "candidate";
    has circuit_open: bool = False;
}

node Observation {
    has source_native_id: str = "";
    has raw_preserved: bool = True;
    has record_kind: str = "";
}

node ConflictAssertion {
    has field_name: str = "";
    has field_value: str = "";
    has selected_reason: str = "";
}

edge SourceDeclares {
    has registered_at: str = "";
}

edge AssertsCompeting {
    has assertion_role: str = "candidate";
}

edge PreservesRaw {
    has ingestion_phase: str = "pre-normalization";
}

walker BorgRegistrar {
    has catalog: list = [];
    has conflicts: list = [];
    has open_circuits: list = [];

    can start with Root entry {
        visit [-->];
    }

    can ingest with Source entry {
        self.catalog.append(here.source_id);
        if here.circuit_open {
            self.open_circuits.append(here.source_id);
        }
        status = "ACTIVE" if here.consumer_status == "active" else "CANDIDATE";
        print(f"[{status}] registered source {here.source_id} "
              f"({here.authority_class}, {here.jurisdiction})");
        visit [-->];
    }

    can observe with Observation entry {
        print(f"  raw observation preserved: {here.source_native_id} "
              f"kind={here.record_kind}");
        visit [-->];
    }

    can reconcile with ConflictAssertion entry {
        label = "SELECTED" if here.selected_reason else "COMPETING";
        self.conflicts.append(here.field_name);
        print(f"  conflict on {here.field_name}={here.field_value} "
              f"-> {label}: {here.selected_reason}");
        visit [-->];
    }
}

with entry {
    nyc_calendar = Source(
        source_id="nyc-calendar-v1",
        authority_class="official-event",
        jurisdiction="NYC-Citywide",
        endpoint="api.nyc.gov/calendar/search",
        cadence="hourly",
        schema_fingerprint="sha256:cal-001",
        license_notes="NYC Open Data Terms",
        consumer_status="active"
    );

    socrata_events = Source(
        source_id="nyc-open-data-socrata-events",
        authority_class="official-event",
        jurisdiction="NYC-Citywide",
        endpoint="data.cityofnewyork.us/resource/8end-uv8i.json",
        cadence="daily",
        schema_fingerprint="sha256:soc-114",
        license_notes="CC0",
        consumer_status="active"
    );

    geoclient = Source(
        source_id="nyc-geoclient-v2",
        authority_class="location-evidence",
        jurisdiction="NYC-Citywide",
        endpoint="api.nyc.gov/geoclient/v2",
        cadence="on-demand",
        schema_fingerprint="sha256:geo-002",
        license_notes="NYC App Token",
        consumer_status="candidate"
    );

    dot_traffic = Source(
        source_id="nyc-dot-traffic",
        authority_class="traffic-advisory",
        jurisdiction="NYC-Citywide",
        endpoint="webcams.nyctmc.org/api.json",
        cadence="realtime",
        schema_fingerprint="sha256:dot-707",
        license_notes="NYC Public",
        consumer_status="candidate",
        circuit_open=True
    );

    obs_a = Observation(source_native_id="cal#421", record_kind="event");
    obs_b = Observation(source_native_id="soc#8end-uv8i-row-9", record_kind="event");
    obs_c = Observation(source_native_id="geo#blockface-77", record_kind="location-evidence");
    obs_d = Observation(source_native_id="dot#cam-A5", record_kind="traffic-advisory");

    title_conflict = ConflictAssertion(
        field_name="title",
        field_value="SummerStage: Jazz at Bryant Park",
        selected_reason="calendar has authority_class=official-event"
    );

    location_conflict = ConflictAssertion(
        field_name="location",
        field_value="Bryant Park, Manhattan",
        selected_reason="geoclient resolves blockface"
    );

    traffic_conflict = ConflictAssertion(
        field_name="route",
        field_value="6th Ave @ 42nd St closure",
        selected_reason="traffic never merged into standalone event"
    );

    root +>:SourceDeclares(registered_at="2026-01-15T00:00Z"):+> nyc_calendar;
    root +>:SourceDeclares(registered_at="2026-01-15T00:00Z"):+> socrata_events;
    root +>:SourceDeclares(registered_at="2026-01-15T00:00Z"):+> geoclient;
    root +>:SourceDeclares(registered_at="2026-01-15T00:00Z"):+> dot_traffic;

    nyc_calendar +>:PreservesRaw:+> obs_a;
    socrata_events +>:PreservesRaw:+> obs_b;
    geoclient +>:PreservesRaw:+> obs_c;
    dot_traffic +>:PreservesRaw:+> obs_d;

    obs_a +>:AssertsCompeting:+> title_conflict;
    obs_b +>:AssertsCompeting:+> title_conflict;

    obs_a +>:AssertsCompeting:+> location_conflict;
    obs_c +>:AssertsCompeting:+> location_conflict;

    obs_d +>:AssertsCompeting:+> traffic_conflict;

    registrar = BorgRegistrar();
    root spawn registrar;

    print(f"\ncatalog entries: {len(registrar.catalog)}");
    print(f"competing assertions preserved: {len(registrar.conflicts)}");
    print(f"open circuits (no silent drop): {registrar.open_circuits}");
}
