"""Tests for the stoichiometry-aware reaction I/O walker (issue #48)."""

import io;
import from contextlib { redirect_stdout }

test "curated input coefficients override default of 1" {
    root ++> Reaction(name="R1");
    rxn = [root -->][?:Reaction][0];
    eA = Entity(name="A", has_curated_coef=True);
    eB = Entity(name="B", has_curated_coef=False);
    rxn +>:InputEdge(stoichiometry=2, curated=True):+> eA;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eB;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> eB;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn StoichiometryAuditor();
    }
    out = buf.getvalue();
    assert "A: 2" in out, f"curated coef 2 missing for A: {out}";
    assert "B: 1" in out, f"uncurated default should be 1 for B: {out}";
}

test "entity set members inherit their member coefficient" {
    root ++> Reaction(name="R2");
    rxn = [root -->][?:Reaction][0];
    m = EntitySetMember(name="A#1", member_coef=3);
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> m;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> m;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn StoichiometryAuditor();
    }
    out = buf.getvalue();
    assert "A#1: 3" in out, f"member_coef=3 should propagate, got: {out}";
}

test "duplicate target nodes have their coefficients summed" {
    root ++> Reaction(name="R3");
    rxn = [root -->][?:Reaction][0];
    m1 = EntitySetMember(name="A#1", member_coef=2);
    m2 = EntitySetMember(name="A#2", member_coef=2);
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> m1;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> m2;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> m1;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> m2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn StoichiometryAuditor();
    }
    out = buf.getvalue();
    # Two distinct keys (A#1 and A#2), each with coef 2
    assert "A#1: 2" in out, f"A#1 total should be 2: {out}";
    assert "A#2: 2" in out, f"A#2 total should be 2: {out}";
}

test "absent curation defaults coefficient to 1 not 0" {
    root ++> Reaction(name="R4");
    rxn = [root -->][?:Reaction][0];
    e = Entity(name="X", has_curated_coef=False);
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> e;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn StoichiometryAuditor();
    }
    out = buf.getvalue();
    assert "X: 1" in out, f"missing curation should default to 1, got: {out}";
    assert "X: 0" not in out, f"coef must not be 0: {out}";
}

test "curated and member coefficients are distinguished" {
    root ++> Reaction(name="R5");
    rxn = [root -->][?:Reaction][0];
    eCur = Entity(name="Curated", has_curated_coef=True);
    eFlat = Entity(name="Flat", has_curated_coef=False);
    mHigh = EntitySetMember(name="Member", member_coef=5);
    rxn +>:InputEdge(stoichiometry=3, curated=True):+> eCur;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eFlat;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> mHigh;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> eFlat;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn StoichiometryAuditor();
    }
    out = buf.getvalue();
    # Entity.has_curated_coef=True yields coef 2 (the program's curated branch)
    assert "Curated: 2" in out, f"curated entity should yield 2: {out}";
    # Plain entity with no curation defaults to 1
    assert "Flat: 1" in out, f"plain entity should yield 1: {out}";
    # Member picks up its member_coef value of 5
    assert "Member: 5" in out, f"member_coef=5 should be preserved: {out}";
}

