import io;
import from contextlib { redirect_stdout }

test "audit invalidates illumos-broken dependency" {
    app = Package(name="cargo-mutants", version="0.5.0", illumos_ok=True);
    bad = Package(name="fs2", version="0.4.3", illumos_ok=False);
    root ++> app;
    app +>:Depends(depth=1):+> bad;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
