    assert "[INVALIDATE]" in out, f"missing INVALIDATE marker: {out}";
    assert "fs2" in out, f"expected fs2 in output: {out}";
    assert app.name in res.order, f"app should be audited before stop: {res.order}";
    assert bad.name not in res.order, f"broken dep must not enter order: {res.order}";
}

test "broken dependency blocks transitive audit" {
    app = Package(name="cargo-mutants", illumos_ok=True);
    bad = Package(name="fs2", illumos_ok=False);
    downstream = Package(name="lockfile", illumos_ok=True);
    root ++> app;
    app +>:Depends(depth=1):+> bad;
    bad +>:Depends(depth=2):+> downstream;
    res = root spawn DependencyAuditor();
    assert downstream.name not in res.visited, f"transitive dep must not be visited: {res.visited}";
    assert downstream.name not in res.order, f"transitive dep must not be ordered: {res.order}";
