# ---------- Test 4: CycleProbe traverses Weighted edges in acyclic topology ----------
test "CycleProbe visits each NodeGraph node exactly along Weighted edges" {
    # Build a DAG: A -> B -> C, A -> C
    a = NodeGraph(label="A", community=0);
    b = NodeGraph(label="B", community=0);
    c = NodeGraph(label="C", community=0);
    a +>:Weighted(weight=1.0):+> b;
    b +>:Weighted(weight=1.0):+> c;
    a +>:Weighted(weight=1.0):+> c;
    root ++> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CycleProbe();
    }
    out = buf.getvalue();

    assert "[cycle-probe]" in out, f"expected cycle-probe marker; got: {out}";
    # Each node should be visited at least once
    assert "visiting 'A'" in out, f"expected visit to A; got: {out}";
    assert "visiting 'B'" in out, f"expected visit to B; got: {out}";
    assert "visiting 'C'" in out, f"expected visit to C; got: {out}";
