import io;
import from contextlib { redirect_stdout }

test "same logical name reuses stale package cache" {
    s1 = Sandbox(
        name="worker-A",
        instance_id="container-001",
        installed_packages=["requests", "mcp"]
    );
    s2 = Sandbox(
        name="worker-A",
        instance_id="container-002",
        installed_packages=[]
    );
    t1 = Tool(title="initial-tool", requires=["mcp", "requests"]);
    t2 = Tool(title="replacement-tool", requires=["mcp"]);

    root ++> s1;
    root ++> s2;
    s1 +>:DependsOn:+> t1;
    s2 +>:DependsOn:+> t2;

    assert len([root-->]) == 2, f"expected two sandboxes, got {len([root-->])}";
    assert len([s1 ->:DependsOn:->]) == 1, f"expected one dependency from s1";
    assert len([s2 ->:DependsOn:->]) == 1, f"expected one dependency from s2";
    assert len(s2.installed_packages) == 0, f"replacement filesystem was not fresh";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyInstaller();
    }
    out = buf.getvalue();

    assert len(res.installed_cache["worker-A"]) == 2, f"got {res.installed_cache}";
    assert "mcp" in res.installed_cache["worker-A"], f"got {res.installed_cache}";
    assert "container-002" in out, f"replacement was not visited: {out}";
    assert "cache hit" in out, f"stale cache was not observed: {out}";
}

test "different logical names do not share dependency cache" {
    s1 = Sandbox(
        name="worker-A",
        instance_id="container-101",
        installed_packages=["mcp"]
