    s2 +>:DependsOn:+> t2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyInstaller();
    }
    out = buf.getvalue();

    assert "mcp" in res.installed_cache["worker-A"], f"got {res.installed_cache}";
    assert len(res.installed_cache["worker-B"]) == 0, f"got {res.installed_cache}";
    assert "fresh-tool" in out, f"fresh tool was not checked: {out}";
    assert "MISSING" in out, f"cache leaked across names: {out}";
}

