test "declared count can exceed cap while materialized graph stays small" {
    c = Composite(title="pathological", inner_event_count=210000, max_inner_allowed=50000);
    a = InboxRow(title="giant-0", ordinal=0);
    b = InboxRow(title="giant-1", ordinal=1);
