test "FanoutWalker stops draining once max_inner_allowed budget is exhausted" {
    c = Composite(title="budgeted", inner_event_count=2, max_inner_allowed=2);
    r0 = InboxRow(title="r0", ordinal=0);
    r1 = InboxRow(title="r1", ordinal=1);
    r2 = InboxRow(title="r2", ordinal=2);
    r3 = InboxRow(title="r3", ordinal=3);
    r4 = InboxRow(title="r4", ordinal=4);
    root ++> c;
    c +>:Carries(ordinal=0):+> r0;
    c +>:Carries(ordinal=1):+> r1;
    c +>:Carries(ordinal=2):+> r2;
    c +>:Carries(ordinal=3):+> r3;
    c +>:Carries(ordinal=4):+> r4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = c spawn FanoutWalker();
    }
    out = buf.getvalue();
    assert "STOP: budget exhausted" in out, f"drain should halt at cap: {out}";
    assert res.processed_count == 2, f"only cap rows may be processed: {res.processed_count}";
    assert r0.processed == True, f"first row should be processed: {r0.processed}";
    assert r1.processed == True, f"second row should be processed: {r1.processed}";
    assert r2.processed == False, f"third row must remain queued: {r2.processed}";
    assert r3.processed == False, f"fourth row must remain queued: {r3.processed}";
    assert r4.processed == False, f"fifth row must remain queued: {r4.processed}";
}

