import io;
import from contextlib { redirect_stdout }

test "required blockers mark the project at risk" {
    app = Project(name="Vahdam Marketing Automation");
    root ++> app;
    blocked = Vertical(title="CI/CD", state="MISSING", blocks_release=True);
    app +>:Owns:+> blocked;
    gate = ReleaseGate(title="locked dependency CI", satisfied=False, required=True);
    app +>:Governs:+> gate;

    assert len([root-->]) == 1, f"got {len([root-->])} root children";
    assert len([app ->:Owns:->]) == 1, "wrong owned vertical count";
    assert blocked in [app ->:Owns:->], "blocked vertical is not owned by project";
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReadinessAuditor();
    }
    out = buf.getvalue();
    assert res.at_risk == True, f"got {res.at_risk}";
    assert res.verticals_checked == 1, f"got {res.verticals_checked} verticals";
    assert res.gates_checked == 1, f"got {res.gates_checked} gates";
    assert "[BLOCKED] CI/CD: MISSING" in out, f"missing blocked vertical: {out}";
    assert "[FAIL] gate: locked dependency CI" in out, f"missing failed gate: {out}";
    assert "=== Baseline audit: Vahdam Marketing Automation ===" in out, f"missing baseline audit: {out}";
}

test "optional unsatisfied gates do not block release" {
    app = Project(name="ready app");
    root ++> app;
    frontend = Vertical(title="Frontend", state="UNVERIFIED", blocks_release=False);
    app +>:Owns:+> frontend;
    optional_gate = ReleaseGate(title="optional preview check", satisfied=False, required=False);
    app +>:Governs:+> optional_gate;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReadinessAuditor();
    }
    out = buf.getvalue();
    assert res.at_risk == False, f"got {res.at_risk}";
    assert res.verticals_checked == 1, f"got {res.verticals_checked} verticals";
    assert res.gates_checked == 1, f"got {res.gates_checked} gates";
    assert "[OK] Frontend: UNVERIFIED" in out, f"missing healthy vertical: {out}";
    assert "[PASS] gate: optional preview check" in out, f"missing optional pass: {out}";
    assert "=== Baseline audit: ready app ===" in out, f"missing baseline audit: {out}";
}

test "dependency traversal audits prerequisites before dependents" {
    app = Project(name="dependency app");
    root ++> app;
    deploy = Vertical(title="Deployment", state="NOT EVIDENCED", blocks_release=True);
    backend = Vertical(title="Backend & APIs", state="PRESENT", blocks_release=False);
    app +>:Owns:+> deploy;
    deploy +>:DependsOn:+> backend;
    gate = ReleaseGate(title="journeys", satisfied=True, required=True);
    app +>:Governs:+> gate;

    assert backend in [deploy ->:DependsOn:->], "dependency edge points the wrong way";
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReadinessAuditor();
    }
    out = buf.getvalue();
    assert res.at_risk == True, f"got {res.at_risk}";
    assert res.verticals_checked >= 2, f"got {res.verticals_checked} vertical checks";
    assert res.gates_checked == 1, f"got {res.gates_checked} gates";
    assert "[OK] Backend & APIs: PRESENT" in out, f"missing reachable dependency: {out}";
    assert "[BLOCKED] Deployment: NOT EVIDENCED" in out, f"missing dependent vertical: {out}";
    assert "=== Baseline audit: dependency app ===" in out, f"missing baseline audit: {out}";
}

