"""QuickPlay v0: prompt-to-playable-to-revise-to-keep household game pipeline."""

node GamePrompt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has description: str = "";
    has child_name: str = "";
}

node PlayableGame {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gate_passed: bool = False;
    has launched: bool = False;
}

node GameRevision {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: int = 1;
    has immutable: bool = True;
}

node OfflineCartridge {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has frozen: bool = False;
    has portable: bool = True;
}

edge Generates { has builder: str = ""; }
edge NeedsRevision { has note: str = ""; }
edge Keeps { has frozen_at: str = ""; }

walker QuickPlayRunner {
    has steps: int = 0;
    has kept: bool = False;

    can start with Root entry {
        print("QuickPlay v0: prompt -> playable -> revise -> keep");
        visit [-->];
    }

    can on_prompt with GamePrompt entry {
        print(f"PROMPT from {here.child_name}: {here.description}");
        self.steps += 1;
        visit [->:Generates:->] else { disengage; }
    }

    can on_playable with PlayableGame entry {
        gate_txt = "PASS" if here.gate_passed else "FAIL";
        rodoh_txt = "LIVE" if here.launched else "BUILD";
        print(f"PLAYABLE {here.title} gate:{gate_txt} rodoh:{rodoh_txt}");
        self.steps += 1;
        if here.gate_passed == False {
            print("  blocked: playability gate failed - downstream revoked");
            disengage;
        } else {
            visit [->:NeedsRevision:->] else { disengage; }
        }
    }

    can on_revision with GameRevision entry {
        imm_txt = "IMMUTABLE" if here.immutable else "DRAFT";
        print(f"REVISION v{here.version} {here.title} [{imm_txt}]");
        self.steps += 1;
        visit [->:Keeps:->] else { disengage; }
    }

    can on_cartridge with OfflineCartridge entry {
        state_txt = "FROZEN" if here.frozen else "OPEN";
        print(f"CARTRIDGE {here.title} [{state_txt}] offline:{here.portable}");
        self.steps += 1;
        self.kept = here.frozen;
        disengage;
    }
}

with entry {
    prompt = GamePrompt(
        title="Tiny Planet",
        description="spherical voxel planet, collectibles, hazard loop, win/loss/restart",
        child_name="scout"
    );
    playable = PlayableGame(title="Tiny Planet v0", gate_passed=True, launched=True);
    revision = GameRevision(title="Tiny Planet v0.1", version=2, immutable=True);
    cartridge = OfflineCartridge(title="Tiny Planet KEEP", frozen=True, portable=True);

    root ++> prompt;
    prompt +>:Generates:builder="OpenGame sidecar":+> playable;
    playable +>:NeedsRevision:note="brighter collectibles":+> revision;
    revision +>:Keeps:frozen_at="T+48h":+> cartridge;

    runner = QuickPlayRunner();
    root spawn runner;
    print(f"pipeline steps:{runner.steps}, cartridge kept:{runner.kept}");
}
