    assert res.kept == False, f"got {res.kept}";
    assert "blocked: playability gate failed" in out, f"output was {out}";
    assert "REVISION" not in out, f"unexpected revision output: {out}";
    assert "CARTRIDGE" not in out, f"unexpected cartridge output: {out}";
