    assert "Visited B" in out, f"missing B visit: {out}";
    assert "Cycle detected at A; audit stopped safely" in out, f"missing cycle stop: {out}";
}

test "acyclic hierarchy visits every location without cycle warning" {
    a = Location(location_id="A", name="A");
    c = Location(location_id="C", name="C");
    b = Location(location_id="B", name="B");
    d = Location(location_id="D", name="D");

    root +>:ParentOf:+> a;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> b;
    b +>:ParentOf:+> d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LocationAuditor();
    }
    out = buf.getvalue();

    assert "Visited A" in out, f"missing A visit: {out}";
    assert "Visited C" in out, f"missing C visit: {out}";
    assert "Visited B" in out, f"missing B visit: {out}";
    assert "Visited D" in out, f"missing D visit: {out}";
    assert "Cycle detected" not in out, f"unexpected cycle warning: {out}";
