```jac
"""Roll up inventory through nested locations with typed-edge traversal."""

node Location {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Item {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sku: str = "";
}

node StockEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has quantity: int = 0;
}

edge Contains { }
edge ForItem { }

walker InventoryRollup {
    has item_count: int = 0;
    has unit_count: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can descend with Location entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with StockEntry entry {
        self.item_count += 1;
        self.unit_count += here.quantity;
        visit [->:ForItem:->] else {
            disengage;
        }
    }

    can summarize with Root exit {
        print(f"Nested inventory: {self.item_count} item(s), {self.unit_count} unit(s)");
    }
}

with entry {
    parent = Location(title="Warehouse");
    child = Location(title="Shelf B");
    stock = StockEntry(title="Shelf B stock", quantity=4);
    item = Item(title="Widget", sku="W-104");

    root +>:Contains:+> parent;
    parent +>:Contains:+> child;
    child +>:Contains:+> stock;
    stock +>:ForItem:+> item;

    root spawn InventoryRollup();
}
```

jac_tests:
import io;
import from contextlib { redirect_stdout }

test "parent includes stock in a nested location" {
    parent = Location(title="Warehouse");
    child = Location(title="Shelf B");
    stock = StockEntry(title="Shelf B stock", quantity=4);
    item = Item(title="Widget", sku="W-104");

    root +>:Contains:+> parent;
    parent +>:Contains:+> child;
    child +>:Contains:+> stock;
    stock +>:ForItem:+> item;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InventoryRollup();
    }
    out = buf.getvalue();

    assert res.item_count == 1, "nested stock entry should be counted";
    assert res.unit_count == 4, "nested stock quantity should be included";
    assert "Nested inventory: 1 item(s), 4 unit(s)" in out, "rollup summary should report nested stock";
}

test "parent aggregates stock across multiple nested locations" {
    parent = Location(title="Warehouse");
    left = Location(title="Shelf A");
    right = Location(title="Shelf B");
    left_stock = StockEntry(title="Shelf A stock", quantity=3);
    right_stock = StockEntry(title="Shelf B stock", quantity=5);
    left_item = Item(title="Left widget", sku="L-1");
    right_item = Item(title="Right widget", sku="R-1");

    root +>:Contains:+> parent;
    parent +>:Contains:+> left;
    parent +>:Contains:+> right;
    left +>:Contains:+> left_stock;
    right +>:Contains:+> right_stock;
    left_stock +>:ForItem:+> left_item;
    right_stock +>:ForItem:+> right_item;

    assert len([parent ->:Contains:->]) == 2, "parent should have two nested locations";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InventoryRollup();
    }
    out = buf.getvalue();

    assert res.item_count == 2, "stock entries in both nested locations should be counted";
    assert res.unit_count == 8, "quantities from all nested locations should be summed";
    assert "Nested inventory: 2 item(s), 8 unit(s)" in out, "summary should include all nested stock";
}

test "rollup traverses locations at arbitrary depth" {
    warehouse = Location(title="Warehouse");
    aisle = Location(title="Aisle 1");
    shelf = Location(title="Shelf C");
    stock = StockEntry(title="Shelf C stock", quantity=2);
    item = Item(title="Deep widget", sku="D-1");

    root +>:Contains:+> warehouse;
    warehouse +>:Contains:+> aisle;
    aisle +>:Contains:+> shelf;
    shelf +>:Contains:+> stock;
    stock +>:ForItem:+> item;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn InventoryRollup();
    }
    out = buf.getvalue();

    assert res.item_count == 1, "deeply nested stock entry should be found";
    assert res.unit_count == 2, "deeply nested quantity should be included";
    assert "Nested inventory: 1 item(s), 2 unit(s)" in out, "summary should include deeply nested stock";
}

