import io;
import from contextlib { redirect_stdout }

test "planner detects dependency cycle" {
    pipeline = Pipeline(title="linux-release");
    app = Repository(title="app", revision="abc123");
    build = Repository(title="build-tools", revision="def456");

    root +>:Targets:+> pipeline;
    pipeline +>:Runs:+> app;
    app +>:DependsOn(reason="build tooling"):+> build;
    build +>:DependsOn(reason="cycle"):+> app;

    assert len([root-->]) == 1, f"root children: {len([root-->])}";
    assert build in [app ->:DependsOn:->], "build dependency edge is missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn DependencyPlanner();
    }
    out = buf.getvalue();

    assert result.cycle_found == True, f"cycle flag: {result.cycle_found}";
    assert "cycle detected at repository app" in out, f"missing cycle output: {out}";
}

test "auditor invalidates revision mismatches" {
    pipeline = Pipeline(title="linux-release", max_parallel=2);
    app = Repository(title="app", revision="abc123");
    build = Repository(title="build-tools", revision="def456");

    stale = Attempt(
        title="attempt-app-1",
        state="running",
        revision="old999",
        repository_revision="abc123"
    );
    current = Attempt(
        title="attempt-build-1",
        state="queued",
        revision="def456",
        repository_revision="def456"
    );

    root +>:Targets:+> pipeline;
    pipeline +>:Runs:+> app;
    pipeline +>:Runs:+> build;
    app +>:HasAttempt(slot=1):+> stale;
    build +>:HasAttempt(slot=2):+> current;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn AttemptAuditor();
    }
    out = buf.getvalue();

    assert stale.state == "invalidated", f"stale state: {stale.state}";
    assert stale.available == False, f"stale availability: {stale.available}";
    assert current.state == "queued", f"current state: {current.state}";
    assert current.available == True, f"current availability: {current.available}";
    assert "invalidated attempt-app-1" in out, f"missing invalidation output: {out}";
    assert "ready attempt-build-1" in out, f"missing ready output: {out}";
    assert result != None, "auditor did not return a walker";
}

test "planner traverses dependencies in order without a cycle" {
    pipeline = Pipeline(title="linux-release");
    app = Repository(title="app", revision="abc123");
    build = Repository(title="build-tools", revision="def456");
    release = Repository(title="release-config", revision="ghi789");

    root +>:Targets:+> pipeline;
    pipeline +>:Runs:+> app;
    app +>:DependsOn(reason="build tooling"):+> build;
    build +>:DependsOn(reason="release metadata"):+> release;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn DependencyPlanner();
    }
    out = buf.getvalue();

    app_pos = out.find("repository: app");
    build_pos = out.find("repository: build-tools");
    release_pos = out.find("repository: release-config");

    assert result.cycle_found == False, f"cycle flag: {result.cycle_found}";
    assert app_pos >= 0, f"app was not visited: {out}";
    assert build_pos >= 0, f"build-tools was not visited: {out}";
    assert release_pos >= 0, f"release-config was not visited: {out}";
    assert app_pos < build_pos, f"dependency order is wrong: {out}";
    assert build_pos < release_pos, f"dependency order is wrong: {out}";
}

