import io;
import from contextlib { redirect_stdout }

test "exact callable composition" {
    main = Routine(name="main", version=1, summary="returns scalar");
    helper = Routine(name="helper", version=2, summary="may throw");
    call = CallSite(
        name="main -> helper",
        context="scalar",
        observed_version=2,
        callee_version=2,
        depth=1
    );

    root ++> main;
    main +>:Owns(ordinal=1):+> call;
    call +>:Calls(context="scalar"):+> helper;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SemanticComposer(max_depth=2);
    }
    out = buf.getvalue();

    assert call.exact == True, f"call was not exact: {call.exact}";
    assert call.bounded == True, f"call was not bounded: {call.bounded}";
    assert "exact scalar result at main -> helper" in out, f"missing exact result: {out}";
    assert "summary helper v2" in out, f"missing callee summary: {out}";
}

test "stale callee facts require caller refresh" {
    main = Routine(name="main", version=1, summary="returns scalar");
    helper = Routine(name="helper", version=3, summary="changed result");
    call = CallSite(
        name="main -> helper",
        context="scalar",
        observed_version=2,
        callee_version=3,
        depth=1
    );

    root ++> main;
    main +>:Owns(ordinal=1):+> call;
    call +>:Calls(context="scalar"):+> helper;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SemanticComposer(max_depth=2);
    }
    out = buf.getvalue();

    assert call.exact == False, f"stale call remained exact: {call.exact}";
    assert call.bounded == True, f"stale call was unexpectedly unbounded: {call.bounded}";
    assert "stale callee fact at main -> helper" in out, f"missing stale marker: {out}";
}

test "depth limit produces bounded refusal" {
    main = Routine(name="main", version=1, summary="returns scalar");
    call = CallSite(
        name="deep call",
        context="scalar",
        observed_version=1,
        callee_version=1,
        depth=3
    );

    root ++> main;
    main +>:Owns(ordinal=1):+> call;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SemanticComposer(max_depth=2);
    }
    out = buf.getvalue();

    assert call.bounded == False, f"deep call remained bounded: {call.bounded}";
    assert call.exact == False, f"bounded refusal remained exact: {call.exact}";
    assert "bounded refusal at deep call" in out, f"missing refusal marker: {out}";
}

test "invalidation propagates through cycles once" {
    helper = Routine(name="helper", version=2, summary="callee changed");
    main = Routine(name="main", version=1, summary="composed caller");

    helper +>:Invalidates(reason="callee version changed"):+> main;
    main +>:Invalidates(reason="recursive component"):+> helper;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = helper spawn InvalidationAuditor();
    }
    out = buf.getvalue();

    assert helper.invalidated == True, f"helper was not invalidated: {helper.invalidated}";
    assert main.invalidated == True, f"caller was not invalidated: {main.invalidated}";
    assert "invalidated helper and its composed facts" in out, f"missing helper invalidation: {out}";
    assert "invalidated main and its composed facts" in out, f"missing caller invalidation: {out}";
    assert "invalidation cycle guard stopped at helper" in out, f"missing cycle guard: {out}";
}

