node Change {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has changed: bool = False;
}

node RouteRow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has selected: bool = False;
    has current: bool = True;
