"""Semantic extraction graph with document-to-code reachability."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
}

node Document(GraphItem) {
    has source_file: str = "";
}

node Concept(GraphItem) {
    has rationale: str = "";
}

node CodeSymbol(GraphItem) {
    has source_file: str = "";
    has symbol_id: str = "";
}

edge Mentions {
    has confidence: float = 0.0;
}

edge Implements {
    has relation: str = "";
}

edge References {
    has reason: str = "";
}

edge CyclesTo {
    has note: str = "";
}

walker ReachabilityAudit {
    has seen: list[str] = [];
    has reached: int = 0;

    can start with Root entry {
        print("Starting semantic reachability audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Document | Concept | CodeSymbol entry {
        if here.key in self.seen {
            print(f"cycle blocked at {here.key}");
            disengage;
        } else {
            self.seen.append(here.key);
            self.reached += 1;
            print(f"reached {here.key}: {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
