"""Frontier ancestry audit with typed edges and an explicit depth guard."""

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Frontier {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has member_count: int = 0;
    has checked: bool = False;
    has divergent: bool = False;
}

node Member {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
}

edge Contains {
    has label: str = "";
}

edge Predecessor {
    has relation: str = "";
}

edge Includes {
    has position: int = 0;
}

walker FrontierAuditor {
    has depth: int = 0;
    has max_depth: int = 5;
    has visited_frontiers: int = 0;

    can start with Root entry {
        print("Starting frontier ancestry audit");
        visit [-->] else {
            disengage;
        }
    }

    can open_session with Session entry {
        print(f"Session: {here.title} ({here.year})");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can audit_frontier with Frontier entry {
        if (self.depth >= self.max_depth) {
            print(f"Depth guard stopped ancestry walk at {here.title}");
            disengage;
        }

        self.visited_frontiers = self.visited_frontiers + 1;
        status = "divergent" if here.divergent else "consistent";
        print(f"Frontier {here.title}: {here.member_count} members, {status}");

        self.depth = self.depth + 1;
        visit [->:Predecessor:->] else {
            disengage;
        }
    }
}

with entry {
    session = Session(title="Signalbox validation", year=2026);
    root ++> session;

    latest = Frontier(
