    dependent +>:BlockedBy(reason="requires logical recovery"):+> abandoned;
    abandoned +>:Supersedes(contract_version=1, validated=True):+> replacement;

    assert len([plane ->:Contains:->]) == 1, f"unexpected contained task count";
