        self.expected_record_id = here.record_id;
        self.expected_proposition_id = here.proposition_id;
        self.expected_scientific_use_id = here.scientific_use_id;
        self.expected_view_id = here.view_id;
        self.expected_view_head = here.view_head_generation;
        self.expected_label = here.primary_label;
        self.expected_reason = here.reason_topology;
        self.expected_trace = here.policy_trace;
        self.expected_policy = here.policy_profile;
        self.expected_evaluator = here.evaluator_profile;
        self.expected_cutoff = here.historical_cutoff;
        self.seen_evidence = 0;
        self.failed = False;

        if here.evidence_count == 0 {
            print(f"[REPLAY FAIL] {here.record_id}: missing candidate evidence");
            disengage;
        } else {
            visit [->:ContainsEvidence:->];
        }
    }

    can inspect_evidence with EvidenceSnapshot entry {
        self.seen_evidence += 1;

        if self.seen_evidence != 1
            or here.record_id != self.expected_record_id
            or here.proposition_id != self.expected_proposition_id
            or here.scientific_use_id != self.expected_scientific_use_id
            or here.view_id != self.expected_view_id
            or here.view_head_generation != self.expected_view_head
            or here.reason_topology != self.expected_reason
            or here.policy_trace != self.expected_trace
            or here.policy_profile != self.expected_policy
            or here.evaluator_profile != self.expected_evaluator
            or here.historical_cutoff != self.expected_cutoff
            or not here.admitted {
            self.failed = True;
            print(f"[REPLAY FAIL] {self.expected_record_id}: complete result mismatch");
            disengage;
        } else {
            visit [->:DeclaredView:->];
        }
    }

    can mint with ScientificView entry {
        if self.failed {
            disengage;
        } else {
            witness = ReplayVerifiedDisposition(
                record_id=self.expected_record_id,
                view_id=self.expected_view_id,
                view_head_generation=self.expected_view_head,
                primary_label=self.expected_label,
                reason_topology=self.expected_reason,
                policy_trace=self.expected_trace,
                policy_profile=self.expected_policy,
                evaluator_profile=self.expected_evaluator
            );

            here +>:ReplayProduces:+> witness;
            witness +>:LiveView:+> here;

            print(f"[REPLAY PASS] {self.expected_record_id}: witness created by verifier");
            visit [->:NextCandidate:->];
        }
    }
}

walker CurrentnessChecker {
    has bound_record_id: str = "";
    has bound_view_id: str = "";
    has bound_head: int = 0;
    has returned_to_view: bool = False;

    can begin with Root entry {
        visit [->:Candidate:->];
    }

    can follow_record with ScientificDispositionRecord entry {
        visit [->:ContainsEvidence:->];
    }

    can follow_evidence with EvidenceSnapshot entry {
        visit [->:DeclaredView:->];
    }

    can inspect_view with ScientificView entry {
        if self.returned_to_view {
            if self.bound_view_id == here.view_id
                and self.bound_head == here.head_generation {
                print(f"[CURRENT] {here.namespace}: {self.bound_record_id} is current at H{here.head_generation}");
            } else {
                print(f"[STALE] {here.namespace}: {self.bound_record_id} was verified at H{self.bound_head}, live H{here.head_generation}");
            }
            disengage;
        } else {
            visit [->:ReplayProduces:->];
        }
    }

    can inspect_witness with ReplayVerifiedDisposition entry {
        self.bound_record_id = here.record_id;
        self.bound_view_id = here.view_id;
        self.bound_head = here.view_head_generation;
        self.returned_to_view = True;
        visit [->:LiveView:->];
    }
}

