"""Resolve a dashboard session through genuine continuation children only."""

node Dashboard {
    has name: str = "";
}

node Session {
    has session_id: str = "";
    has source: str = "chat";
    has delegate_from: str = "";
    has branched_from: str = "";
    has started_at: int = 0;
}

edge Opens {
    has label: str = "";
}

edge Continuation {
    has reason: str = "model-continuation";
}

edge Delegation {
    has reason: str = "delegated sub-agent";
}

edge UserBranch {
    has reason: str = "user branch";
}

edge ToolSidecar {
    has reason: str = "tool sidecar";
}

walker SessionResolver {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can resolve with Dashboard entry {
        visit [->:Opens:->] else {
            disengage;
        }
    }

    can inspect with Session entry {
        if here.session_id in self.seen {
            print(f"cycle blocked at {here.session_id}");
            disengage;
        }

        self.seen.append(here.session_id);
        print(f"dashboard stays on {here.session_id} (source={here.source})");

        visit [->:Continuation:->] else {
            disengage;
        }
    }
}

with entry {
    dashboard = Dashboard(name="Hermes Dashboard");

    main = Session(session_id="main", started_at=100);
    continuation = Session(
        session_id="continuation-1",
        started_at=110
    );
    sub_agent = Session(
        session_id="delegate-1",
        delegate_from="main",
        started_at=120
    );
    branch = Session(
        session_id="branch-1",
        branched_from="main",
        started_at=130
    );
    tool = Session(
        session_id="tool-1",
        source="tool",
        started_at=140
    );

    root ++> dashboard;
    dashboard +>:Opens(label="resume"):+> main;

    main +>:Continuation(reason="/model resume"):+> continuation;
    main +>:Delegation:+> sub_agent;
    main +>:UserBranch:+> branch;
    main +>:ToolSidecar:+> tool;

    root spawn SessionResolver();
}
