"""Restore an older topology as a fresh immutable revision in the same workspace."""

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has expected_head: int = 0;
    has current_head: int = 0;
}

node Revision {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision_no: int = 0;
    has immutable: bool = True;
    has origin_revision: int = 0;
    has action: str = "";
    has status: str = "";
    has same_workspace: bool = True;
}

node TopologyNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has marked: bool = False;
}

edge Head {
    has expected_revision: int = 0;
}

edge History { }

edge Next {
    has sequence: int = 0;
}

edge Snapshot {
    has purpose: str = "";
}

edge Origin {
    has reason: str = "";
}

edge Child {
    has order: int = 0;
}

walker HistoryAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_workspace with Workspace entry {
        print(f"history for {here.name}");
        visit [->:History:->] else { disengage; }
    }

    can inspect_revision with Revision entry {
        print(f"revision {here.revision_no}: {here.action}, immutable={here.immutable}");
        visit [->:Next:->] else { disengage; }
    }
}

walker TopologyAuditor {
    has cycle_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_workspace with Workspace entry {
        head_result = "CAS accepted"
            if here.current_head == here.expected_head + 1
            else "CAS conflict";
        print(f"{here.name}: {head_result}, current head={here.current_head}");
        visit [->:Head:->] else { disengage; }
    }

    can inspect_revision with Revision entry {
        print(f"carrying topology from fresh revision {here.revision_no}");
        visit [->:Snapshot:->] else { disengage; }
    }

    can inspect_topology with TopologyNode entry {
        if here.marked {
            self.cycle_count += 1;
            print(f"cycle detected at topology node {here.key}");
            disengage;
        } else {
            here.marked = True;
            print(f"topology node {here.key}");
            visit [->:Child:->] else { disengage; }
        }
    }
}

walker ProvenanceAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_workspace with Workspace entry {
        visit [->:Head:->] else { disengage; }
    }

    can inspect_revision with Revision entry {
        if here.origin_revision > 0 {
            print(f"revision {here.revision_no} explicitly originates from revision {here.origin_revision}");
            visit [->:Origin:->] else { disengage; }
        } else {
            print(f"selected source revision {here.revision_no}");
            visit [->:Snapshot:->] else { disengage; }
        }
    }

    can inspect_topology with TopologyNode entry {
        if here.marked {
            print(f"source topology cycle detected at {here.key}");
            disengage;
        } else {
            here.marked = True;
            print(f"source topology node {here.key}");
            visit [->:Child:->] else { disengage; }
        }
    }
}

with entry {
    workspace = Workspace(
        name="control-plane",
        expected_head=3,
        current_head=4
    );

    source = Revision(
        revision_no=1,
        title="saved topology",
        action="author",
        status="immutable"
    );
    middle = Revision(
        revision_no=2,
        title="intermediate edit",
        action="edit",
        status="immutable"
    );
    current = Revision(
        revision_no=3,
        title="current draft head",
        action="edit",
        status="immutable"
    );
    restored = Revision(
        revision_no=4,
        title="restored topology",
        action="restore revision 1",
        status="authored",
        origin_revision=1,
        same_workspace=True
    );

    old_root = TopologyNode(key="api");
    old_child = TopologyNode(key="database");
    copied_root = TopologyNode(key="api-copy");
    copied_child = TopologyNode(key="database-copy");
    current_root = TopologyNode(key="current-api");

    root ++> workspace;

    workspace +>:History:+> source;
    source +>:Next(sequence=2):+> middle;
    middle +>:Next(sequence=3):+> current;
    current +>:Next(sequence=4):+> restored;

    workspace +>:Head(expected_revision=3):+> restored;
    source +>:Snapshot(purpose="original topology"):+> old_root;
    current +>:Snapshot(purpose="current topology"):+> current_root;
    restored +>:Snapshot(purpose="copied topology only"):+> copied_root;
    restored +>:Origin(reason="same-draft explicit source reference"):+> source;

    old_root +>:Child(order=1):+> old_child;
    copied_root +>:Child(order=1):+> copied_child;
    copied_child +>:Child(order=2):+> copied_root;

    root spawn HistoryAuditor();
    root spawn TopologyAuditor();
    root spawn ProvenanceAuditor();
}
