    ):+> operation;
    operation +>:ProducesReceipt:+> receipt;
    root +>:Admits:+> carrier;

    res = root spawn AuthorityGate(max_hops=8);

    assert res.last_authorized == False, f"authorized={res.last_authorized}";
    assert operation.applied == False, f"applied={operation.applied}";
    assert receipt.accepted == False, f"accepted={receipt.accepted}";
    assert receipt.reason == "refused: proof scope is narrower than operation", f"reason={receipt.reason}";
}

