"""Weekly issue discovery modeled as a typed issue graph with cycle-safe traversal."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Issue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains { }

edge DependsOn {
    has reason: str = "";
}

walker IssueReport {
    has seen_titles: list[str] = [];
    has open_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can scan_repository with Repository entry {
        print(f"Repository: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can scan_issue with Issue entry {
        if here.title in self.seen_titles {
            print(f"[cycle] {here.title}");
        } else {
            self.seen_titles.append(here.title);

            if here.available {
                self.open_count += 1;
            }

            status = "open" if here.available else "closed";
            print(f"[{status}] {here.title} ({here.year})");

            visit [->:DependsOn:->] else {
                print(f"No dependencies for {here.title}");
            }
        }
    }

    can summarize with Root exit {
        print(f"Unique open issues: {self.open_count}");
    }
}

with entry {
    repository = Repository(title="today-code", year=2026);

    issue_a = Issue(title="Normalize issue dependencies", year=2026);
    issue_b = Issue(title="Improve weekly report", year=2026);
    issue_c = Issue(
        title="Add graph traversal guard",
        year=2026,
        available=False
    );

    root ++> repository;
    repository +>:Contains:+> issue_a;
    repository +>:Contains:+> issue_b;
    repository +>:Contains:+> issue_c;

    issue_a +>:DependsOn(reason="requires report model"):+> issue_b;
    issue_b +>:DependsOn(reason="requires traversal guard"):+> issue_c;
    issue_c +>:DependsOn(reason="demonstrates a dependency cycle"):+> issue_a;

    root spawn IssueReport();
}
