"""Release-grade V3 lineage with typed links and explicit cycle detection."""

node LineageItem {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Release(LineageItem) {
    has signed: bool = False;
}

