"""XML document audit demo with typed child edges and malformed-root detection."""

node XmlDocument {
    has title: str = "";
    has root_count: int = 0;
    has well_formed: bool = True;
}

node XmlElement {
    has tag: str = "";
    has level: int = 0;
    has detached: bool = False;
    has serialized_safe: bool = True;
}

node XmlText {
    has value: str = "";
    has level: int = 0;
}

edge XmlChild {
    has ordinal: int = 0;
}

walker XmlAuditor {
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit_document with XmlDocument entry {
        if here.root_count != 1 {
            print(f"REJECT: {here.title} has {here.root_count} top-level roots");
        } else {
            print(f"ACCEPT: {here.title} has one top-level root");
        }
        visit [->:XmlChild:->] else {
            disengage;
        }
    }

    can audit_element with XmlElement entry {
        print(f"element <{here.tag}> at depth {here.level}");
        if here.detached {
            if here.serialized_safe == False {
                print(f"ALERT: detached <{here.tag}> is unsafe to serialize");
            }
        }
        if here.level >= self.max_depth {
            print(f"STOP: depth limit reached at <{here.tag}>");
            disengage;
        }
        visit [->:XmlChild:->] else {
            disengage;
        }
    }

    can audit_text with XmlText entry {
        print(f"text: {here.value}");
    }
}

with entry {
    document = XmlDocument(
        title="supplier.xml",
        root_count=2,
        well_formed=False
    );
    first = XmlElement(tag="catalog", level=0);
    rogue = XmlElement(
        tag="rogue",
        level=0,
        detached=True,
        serialized_safe=False
    );
    name = XmlText(value="safe item", level=1);
    payload = XmlText(value="<script>unexpected</script>", level=1);

    root ++> document;
    document +>:XmlChild(ordinal=1):+> first;
    document +>:XmlChild(ordinal=2):+> rogue;
    first +>:XmlChild(ordinal=1):+> name;
    rogue +>:XmlChild(ordinal=1):+> payload;

    root spawn XmlAuditor(max_depth=8);
}
