    assert asset.can_receive_assignment() == False, "disposed asset accepts assignment";
    assert asset.can_transfer() == False, "disposed asset transfers as active";
    assert res.audit_ok == True, f"audit status: {res.audit_ok}";
    assert "asset: Scanner A-17 status=disposed" in out, f"missing asset detail: {out}";
    assert "new assignment allowed: False" in out, f"missing assignment restriction: {out}";
    assert "active transfer allowed: False" in out, f"missing transfer restriction: {out}";
    assert "disposal: battery failure via recycle, actor=operator-17" in out, f"missing disposal detail: {out}";
    assert "audit evidence complete: True" in out, f"missing audit detail: {out}";
