import io;
import from contextlib { redirect_stdout }

test "mutually indirect locks deny at maximum depth" {
    mutual_a = LockObject(title="Object #1", lock_expression="@#2");
    mutual_b = LockObject(title="Object #2", lock_expression="@#1");
    mutual_a +>:IndirectLock(lock_type="Basic"):+> mutual_b;
    mutual_b +>:IndirectLock(lock_type="Basic"):+> mutual_a;
    root +>:StartsAudit:+> mutual_a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LockAudit(max_depth=3);
    }
    out = buf.getvalue();

    assert res.denied, f"mutual cycle was not denied: {out}";
    assert res.depth == 3, f"unexpected traversal depth: {res.depth}";
    assert "maximum lock depth reached" in out, f"missing denial output: {out}";
}

test "self-referential lock denies at maximum depth" {
    self_reference = LockObject(
        title="Self-referential object",
