    assert res.depth == 2, f"unexpected self-reference depth: {res.depth}";
    assert "maximum lock depth reached" in out, f"missing denial output: {out}";
}

test "nested lock chain below maximum depth is allowed" {
    chain_start = LockObject(
        title="Nested chain start",
        lock_expression="@#middle"
    );
    chain_middle = LockObject(
        title="Nested chain middle",
        lock_expression="@#end"
    );
    chain_end = LockObject(
        title="Nested chain end",
        lock_expression="#TRUE"
    );
    chain_start +>:IndirectLock(lock_type="Basic"):+> chain_middle;
    chain_middle +>:IndirectLock(lock_type="Basic"):+> chain_end;
    root +>:StartsAudit:+> chain_start;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LockAudit(max_depth=4);
    }
    out = buf.getvalue();

    assert not res.denied, f"valid chain was denied: {out}";
    assert res.depth == 3, f"unexpected valid-chain depth: {res.depth}";
    assert "ALLOW Nested chain end" in out, f"missing allow output: {out}";
}

