"""Native OSP model of an owned Git-provider run and dependency audit."""

node ProviderRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_key: str = "";
    has state: str = "planned";
}

node FixtureRepository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repository_key: str = "";
    has branch: str = "main";
    has object_format: str = "sha1";
}

node Worktree {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has worktree_key: str = "";
    has path_label: str = "";
    has registered: bool = False;
}

node Operation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operation_key: str = "";
    has state: str = "planned";
}

edge OwnsRepository { }
edge Materializes { }
edge Schedules { }
edge DependsOn { }

walker TopologyAuditor {
    can start with Root entry {
        print("auditing owned provider topology");
        visit [-->] else {
            disengage;
        }
