    has impacted: bool = False;
}

node ExternalDependency {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has fingerprint: str = "";
}

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sha: str = "";
    has cache_key: str = "";
    has dependency_fingerprint: str = "";
    has valid: bool = True;
}

edge Affects { }

edge CapturedBy {
    has target_hash: str = "";
}

walker DependencyInvalidator {
    has current_fingerprint: str = "";
    has invalidated_count: int = 0;

    can start with Root entry {
        print("Checking the live external dependency state");
        visit [-->] else { disengage; }
    }

    can find_dependents with ExternalDependency entry {
        self.current_fingerprint = here.fingerprint;
        print(f"{here.title} resolved as {here.version} ({here.fingerprint})");
        visit [->:Affects:->] else { disengage; }
    }

    can invalidate_targets with Target entry {
        here.impacted = True;
        print(f"Invalidating target {here.title}");
        visit [->:CapturedBy:->] else { disengage; }
    }

    can invalidate_snapshots with Snapshot entry {
        if here.dependency_fingerprint != self.current_fingerprint {
            here.valid = False;
            self.invalidated_count += 1;
            print(f"Stale cache entry {here.cache_key} for {here.sha} invalidated");
        }
    }
}

with entry {
    dependency = ExternalDependency(
        title="rules_python + pip lock",
        version="v2",
        fingerprint="dep-v2"
    );
    app = Target(title="//:app");
    unrelated = Target(title="//:unrelated");

    snapshot_a = Snapshot(
        title="app hash at A",
        sha="A",
        cache_key="A.server-config-7",
        dependency_fingerprint="dep-v1"
    );
    snapshot_b = Snapshot(
        title="app hash at B",
        sha="B",
        cache_key="B.server-config-7",
        dependency_fingerprint="dep-v1"
    );
    snapshot_unrelated = Snapshot(
        title="unrelated hash at A",
        sha="A",
        cache_key="A.server-config-7/unrelated",
        dependency_fingerprint="dep-v1"
    );

    root ++> dependency;
    dependency +>:Affects:+> app;
    app +>:CapturedBy(target_hash="app-v1"):+> snapshot_a;
    app +>:CapturedBy(target_hash="app-v1"):+> snapshot_b;
    unrelated +>:CapturedBy(target_hash="unrelated-v1"):+> snapshot_unrelated;

    print("External dependency changed from dep-v1 to dep-v2 without a SHA change");
    root spawn DependencyInvalidator();
}
