import io;
import from contextlib { redirect_stdout }

test "dependency traversal detects cycles" {
    workspace = Workspace(title="workspace", year=2026);
    engine = BuildUnit(title="engine", year=2026, build_seconds=23);
    schema = BuildUnit(title="schema", year=2026, build_seconds=22);
    native = BuildUnit(
        title="native",
        year=2026,
        build_seconds=158,
        available=False
    );

    root +>:Contains:+> workspace;
    workspace +>:Contains:+> engine;
    workspace +>:Contains:+> schema;
    workspace +>:Contains:+> native;
    engine +>:DependsOn(reason="schema"):+> schema;
    schema +>:DependsOn(reason="native"):+> native;
    native +>:DependsOn(reason="engine"):+> engine;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyWalker();
    }
    out = buf.getvalue();

    assert res.inspected_units == 3, f"got {res.inspected_units}";
    assert engine.state == "seen", f"engine state was {engine.state}";
    assert schema.state == "seen", f"schema state was {schema.state}";
    assert native.state == "seen", f"native state was {native.state}";
    assert "[cycle-guard] revisited engine" in out, f"missing cycle guard: {out}";
}

test "typed edges preserve dependency topology" {
    workspace = Workspace(title="topology", year=2026);
    engine = BuildUnit(title="engine", year=2026);
    schema = BuildUnit(title="schema", year=2026);
    native = BuildUnit(title="native", year=2026, available=False);

    root +>:Contains:+> workspace;
    workspace +>:Contains:+> engine;
    workspace +>:Contains:+> schema;
    workspace +>:Contains:+> native;
    engine +>:DependsOn(reason="local validation"):+> schema;
    schema +>:DependsOn(reason="native support"):+> native;

    assert len([workspace ->:Contains:->]) == 3, f"wrong child count";
    assert engine in [workspace ->:Contains:->], f"engine is not contained";
    assert schema in [engine ->:DependsOn:->], f"schema dependency missing";
    assert native in [schema ->:DependsOn:->], f"native dependency missing";
    assert len([native ->:DependsOn:->]) == 0, f"native has unexpected dependency";
    assert native.available == False, f"native availability was {native.available}";
}

test "walker reports blocked units and applies defaults" {
    workspace = Workspace(title="defaults");
    unit = BuildUnit(title="default-unit", available=False);

    root +>:Contains:+> workspace;
    workspace +>:Contains:+> unit;

    buf = io.StringIO();
