    assert workspace.available == True, f"workspace availability was {workspace.available}";
    assert unit.build_seconds == 0, f"default build time was {unit.build_seconds}";
    assert unit.state == "seen", f"unit state was {unit.state}";
    assert res.inspected_units == 1, f"got {res.inspected_units}";
    assert "[blocked] default-unit: 0s" in out, f"missing blocked output: {out}";
