"""A graph-native general council stance audit."""

node Council {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has label: str = "";
}

node Position {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has topic: str = "";
    has paragraph: str = "";
    has concession_target: str = "";
    has concession_valid: bool = False;

    def parsed_stance() -> str {
        if self.paragraph.startswith("SUPPORT:") {
            return "SUPPORT";
        }
        if self.paragraph.startswith("OPPOSE:") {
            return "OPPOSE";
        }
        if self.paragraph.startswith("MAINTAIN:") {
            return "MAINTAIN";
        }
        if self.paragraph.startswith("CONCEDE:") {
            return "CONCEDE";
        }
        return "UNRELATED";
    }

    def effective_stance() -> str {
        parsed = self.parsed_stance();
        if parsed == "CONCEDE" {
            if self.concession_valid {
                return self.concession_target;
            }
            return "MAINTAIN";
        }
        return parsed;
    }
}

edge Convenes { }

edge Presents {
    has order: int = 0;
}

walker StanceAuditor {
    has visited_titles: list[str] = [];
    has previous_topic: str = "";
    has previous_stance: str = "";
    has consensus_count: int = 0;
    has disagreement_count: int = 0;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_council with Council entry {
        print(f"Auditing {here.label}");
        visit [->:Presents:->] else { disengage; }
    }

    can inspect_position with Position entry {
        if here.title in self.visited_titles {
            print(f"Cycle guard ignored duplicate {here.title}");
            disengage;
        }

        self.visited_titles.append(here.title);
        stance = here.effective_stance();

        if stance == "UNRELATED" {
            print(f"{here.title}: unrelated, not consensus");
        } else {
            if self.previous_topic == "" {
                self.previous_topic = here.topic;
                self.previous_stance = stance;
                print(f"{here.title}: {stance}");
            } else {
                if here.topic != self.previous_topic {
                    print(f"{here.title}: unrelated topic, not consensus");
                } else {
                    if stance == self.previous_stance {
                        if stance == "MAINTAIN" {
                            if here.concession_valid {
                                self.consensus_count += 1;
                                print(f"{here.title}: valid concession, consensus ({stance})");
                            } else {
                                self.disagreement_count += 1;
                                print(f"{here.title}: maintained disagreement");
                            }
                        } else {
                            self.consensus_count += 1;
                            print(f"{here.title}: consensus ({stance})");
                        }
                    } else {
                        self.disagreement_count += 1;
                        print(f"{here.title}: disagreement ({self.previous_stance} vs {stance})");
                    }

                    self.previous_stance = stance;
                }
            }
        }
    }
}

with entry {
    council = Council(
        title="General Council",
        year=2026,
        label="Policy review"
    );

    support_a = Position(
        title="Support caching",
        topic="caching",
        paragraph="SUPPORT: caching reduces repeated work."
    );

    support_b = Position(
        title="Support caching again",
        topic="caching",
        paragraph="SUPPORT: caching improves throughput."
    );

    oppose = Position(
        title="Oppose caching",
        topic="caching",
        paragraph="OPPOSE: caching risks stale results."
    );

    maintain = Position(
        title="Maintain objection",
        topic="caching",
        paragraph="MAINTAIN: I do not concede the objection."
    );

    concede = Position(
        title="Concede objection",
        topic="caching",
        paragraph="CONCEDE: the maintained objection is sound.",
        concession_target="MAINTAIN",
        concession_valid=True
    );

    unrelated = Position(
        title="Support documentation",
        topic="documentation",
        paragraph="SUPPORT: documentation needs examples."
    );

    root +>:Convenes:+> council;
    council +>:Presents(order=1):+> support_a;
    council +>:Presents(order=2):+> support_b;
    council +>:Presents(order=3):+> oppose;
    council +>:Presents(order=4):+> maintain;
    council +>:Presents(order=5):+> concede;
    council +>:Presents(order=6):+> unrelated;

    root spawn StanceAuditor();
}
