"""Registry identity audit: walk organization membership to scoped publishers and packages."""

node Principal {
    has subject: str = "";
    has kind: str = "human";
    has role: str = "publisher";
    has active: bool = True;
}

node Organization {
    has registry_id: str = "";
    has slug: str = "";
    has display_name: str = "";
}

node Package {
    has name: str = "";
    has owner_id: str = "";
    has publisher_mode: str = "self";
    has visibility: str = "public";
    has invalidated: bool = False;
}

edge Membership: Organization --> Principal {
    has role: str = "publisher";
}

edge Publishes: Principal --> Package {
    has scope: str = "";
}

walker AuthorityAudit {
    has published_count: int = 0;
    has reports: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_org with Organization entry {
        print(f"org {here.display_name} [{here.registry_id}]");
        visit [here ->:Membership:->] else { disengage; }
    }

    can inspect_principal with Principal entry {
        if here.active and (here.role == "publisher" or here.role == "admin") {
            print(f"active {here.kind} {here.subject} as {here.role}");
            visit [here ->:Publishes:->] else { disengage; }
        } else {
            print(f"revoked {here.kind} {here.subject}; no package traversal");
        }
    }

    can inspect_package with Package entry {
        if here.invalidated {
            print(f"invalidated {here.name} owned by {here.owner_id}");
        } else {
            self.published_count += 1;
            print(f"publishable {here.name} owner={here.owner_id} mode={here.publisher_mode} visibility={here.visibility}");
        }
    }

    can finish with Root exit {
        report self.published_count;
    }
}

with entry {
    org = Organization(
        registry_id="org_7f31",
        slug="acme",
        display_name="Acme Tools"
    );
    ci = Principal(
        subject="acme-release",
        kind="ci",
        role="publisher",
        active=True
    );
    former = Principal(
        subject="former-employee",
        kind="human",
        role="publisher",
        active=False
    );
    alice = Principal(
        subject="alice",
        kind="human",
        role="admin",
        active=True
    );

    org_pkg = Package(
        name="acme/cli",
        owner_id="org_7f31",
        publisher_mode="org",
        visibility="private"
    );
    blocked_pkg = Package(
        name="acme/retired-cli",
        owner_id="org_7f31",
        publisher_mode="org",
        visibility="public",
        invalidated=True
    );
    old_pkg = Package(
        name="acme/old-cli",
        owner_id="org_7f31",
        publisher_mode="org",
        visibility="public"
    );
    personal_pkg = Package(
        name="alice/tool",
        owner_id="user_alice",
        publisher_mode="self",
        visibility="public"
    );

    root ++> org;
    root ++> alice;
    org +>:Membership(role="publisher"):+> ci;
    org +>:Membership(role="publisher"):+> former;
    ci +>:Publishes(scope="org:org_7f31:publish"):+> org_pkg;
    ci +>:Publishes(scope="org:org_7f31:publish"):+> blocked_pkg;
    former +>:Publishes(scope="org:org_7f31:publish"):+> old_pkg;
    alice +>:Publishes(scope="user:user_alice:publish"):+> personal_pkg;

    result = root spawn AuthorityAudit();
    print(f"active publish paths: {result.reports[0]}");
}
