        supports_cancel=True
    );

    retryable_job = Job(
        title="retryable job",
        job_id="job-8",
        pipeline_id="pipe-41",
        supports_cancel=False
    );

    protected_job = Job(
        title="protected job",
        job_id="job-9",
        pipeline_id="pipe-41",
        supports_cancel=False
    );

    accepted_cancel = MutationRequest(
        title="approved cancel",
        operation="cancel",
        session_repository="andre-motta/tongs",
        target_repository="andre-motta/tongs",
        session_pipeline_id="pipe-41",
        target_pipeline_id="pipe-41",
        target_job_id="job-7",
        capability_granted=True,
        identity_valid=True,
        supports_cancel=True
    );

    timeout_retry = MutationRequest(
        title="timed out retry",
        operation="retry",
        session_repository="andre-motta/tongs",
        target_repository="andre-motta/tongs",
        session_pipeline_id="pipe-41",
        target_pipeline_id="pipe-41",
        target_job_id="job-8",
        capability_granted=True,
        identity_valid=True,
        supports_retry=True,
        remote_result="TIMEOUT"
    );

    wrong_repository = MutationRequest(
