        operation="retry",
        session_repository="evil/fork",
        target_repository="andre-motta/tongs",
        session_pipeline_id="pipe-41",
        target_pipeline_id="pipe-41",
        target_job_id="job-8",
        capability_granted=True,
        identity_valid=True,
        supports_retry=True
    );

    unsupported_cancel = MutationRequest(
        title="unsupported cancel",
        operation="cancel",
        session_repository="andre-motta/tongs",
        target_repository="andre-motta/tongs",
        session_pipeline_id="pipe-41",
        target_pipeline_id="pipe-41",
        target_job_id="job-9",
        capability_granted=True,
        identity_valid=True,
        supports_cancel=False
    );

    root +>:Contains:+> repository;
    repository +>:Contains:+> pipeline;
    pipeline +>:Contains:+> cancelable_job;
    pipeline +>:Contains:+> retryable_job;
    pipeline +>:Contains:+> protected_job;
