"""Cycle-safe traversal of nested message view storage policies."""

node Envelope {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has view_storage: str = "Inline";
    has scalar_fields: int = 0;
}

node PayloadPart {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has view_storage: str = "Inline";
    has repeated_fields: int = 0;
}

node MetadataPart {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has view_storage: str = "Inline";
    has map_entries: int = 0;
}

edge NestedField {
    has field_name: str = "";
    has owned_storage: str = "Inline";
    has view_storage: str = "Inline";
}

walker ViewDecoder {
    has seen: list[str] = [];
    has visited_count: int = 0;
    has boxed_allocations: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Envelope | PayloadPart | MetadataPart entry {
        if here.title in self.seen {
            disengage;
        } else {
            self.seen.append(here.title);
            self.visited_count += 1;

            if here.view_storage == "Boxed" {
                self.boxed_allocations += 1;
            }

            print(f"decoded {here.title} with {here.view_storage} view storage");

            visit [->:NestedField:->] else {
                disengage;
            }
        }
    }
}

with entry {
    request = Envelope(
        title="BenchRequest",
        view_storage="Inline",
        scalar_fields=15
    );
    payload = PayloadPart(
        title="Payload",
        view_storage="Boxed",
        repeated_fields=2
    );
    metadata = MetadataPart(
        title="Metadata",
        view_storage="Boxed",
        map_entries=4
    );

    root ++> request;
    request +>:NestedField(
        field_name="payload",
        owned_storage="Inline",
        view_storage="Boxed"
    ):+> payload;
    payload +>:NestedField(
        field_name="metadata",
        owned_storage="Inline",
        view_storage="Boxed"
    ):+> metadata;
    metadata +>:NestedField(
        field_name="parent",
        owned_storage="Boxed",
        view_storage="Boxed"
    ):+> request;

    decoder = ViewDecoder();
    root spawn decoder;

    print(f"visited {decoder.visited_count} messages and boxed {decoder.boxed_allocations} view values");
}
