"""Family identity graph with cycle-safe ancestry and provider traversal."""

node Person {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has person_id: str = "";
    has walk_seen: bool = False;
}

node Identity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has canonical_id: str = "";
    has external_id: str = "";
}

node Provider {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provider_name: str = "";
}

edge ParentOf {
    has role: str = "";
}

edge HasIdentity {
    has canonical: bool = False;
}

edge ProvidedBy {
    has provider_key: str = "";
}

walker FamilyNavigator {
    can start with Root entry {
        print("Starting ancestry traversal");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Person entry {
        if here.walk_seen {
            print(f"Cycle detected at {here.person_id}");
            disengage;
        } else {
            here.walk_seen = True;
            print(f"Visiting {here.title} ({here.person_id})");
            visit [->:ParentOf:->] else {
                disengage;
            }
        }
    }
}

walker IdentityResolver {
    can start with Root entry {
        print("Starting identity traversal");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_person with Person entry {
        print(f"Checking identities for {here.person_id}");
        visit [->:HasIdentity:->] else {
            disengage;
        }
    }

    can inspect_identity with Identity entry {
        print(f"Identity {here.canonical_id} / external {here.external_id}");
        visit [->:ProvidedBy:->] else {
            disengage;
        }
    }

    can inspect_provider with Provider entry {
        print(f"Provider mapping: {here.provider_name}");
    }
}

with entry {
    alice = Person(title="Alice", person_id="p-1");
    bob = Person(title="Bob", person_id="p-2");
    cara = Person(title="Cara", person_id="p-3");

    canonical = Identity(
        title="Canonical Alice",
        canonical_id="canon-1",
        external_id="alice@example.com"
    );
    provider = Provider(title="Family Registry", provider_name="registry");

    root ++> alice;
    alice +>:ParentOf(role="parent"):+> bob;
    bob +>:ParentOf(role="parent"):+> cara;
    cara +>:ParentOf(role="parent"):+> alice;

    alice +>:HasIdentity(canonical=True):+> canonical;
    canonical +>:ProvidedBy(provider_key="registry-1"):+> provider;

    root spawn FamilyNavigator();
    root spawn IdentityResolver();
}
