import io;
import from contextlib { redirect_stdout }

test "family traversal terminates on a parent cycle" {
    alice = Person(title="Alice", person_id="p-1");
    bob = Person(title="Bob", person_id="p-2");
    cara = Person(title="Cara", person_id="p-3");

    root ++> alice;
    alice +>:ParentOf(role="parent"):+> bob;
    bob +>:ParentOf(role="parent"):+> cara;
    cara +>:ParentOf(role="parent"):+> alice;

    assert len([root-->]) == 1, f"unexpected root children: {[root-->]}";
    assert bob in [alice ->:ParentOf:->], "missing Alice to Bob parent link";
    assert cara in [bob ->:ParentOf:->], "missing Bob to Cara parent link";
    assert alice in [cara ->:ParentOf:->], "missing cycle-closing parent link";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn FamilyNavigator();
    }
    out = buf.getvalue();

    assert "Visiting Alice (p-1)" in out, f"missing Alice visit: {out}";
    assert "Visiting Bob (p-2)" in out, f"missing Bob visit: {out}";
    assert "Visiting Cara (p-3)" in out, f"missing Cara visit: {out}";
    assert "Cycle detected at p-1" in out, f"cycle was not detected: {out}";
    assert alice.walk_seen, "Alice was not marked visited";
    assert bob.walk_seen, "Bob was not marked visited";
    assert cara.walk_seen, "Cara was not marked visited";
}

test "identity traversal preserves canonical links and multiple providers" {
    alice = Person(title="Alice", person_id="p-1");
    identity = Identity(
        title="Canonical Alice",
        canonical_id="canon-1",
        external_id="alice@example.com"
    );
    registry = Provider(title="Family Registry", provider_name="registry");
    archive = Provider(title="Family Archive", provider_name="archive");

    root ++> alice;
    alice +>:HasIdentity(canonical=True):+> identity;
    identity +>:ProvidedBy(provider_key="registry-1"):+> registry;
    identity +>:ProvidedBy(provider_key="archive-1"):+> archive;

    assert len([alice ->:HasIdentity:->]) == 1, "expected one identity link";
    assert len([identity ->:ProvidedBy:->]) == 2, "expected two provider links";
    assert identity.canonical_id == "canon-1", "canonical ID was not preserved";
    assert identity.external_id == "alice@example.com", "external ID was not preserved";

    buf = io.StringIO();
