    out = buf.getvalue();

    assert "Checking identities for p-1" in out, f"person was not inspected: {out}";
    assert "Identity canon-1 / external alice@example.com" in out, f"identity was not resolved: {out}";
    assert "Provider mapping: registry" in out, f"registry mapping was not visited: {out}";
    assert "Provider mapping: archive" in out, f"archive mapping was not visited: {out}";
}

test "identity traversal fails closed when a person has no identity" {
