    assert len(res.steps) == 1, f"custom proof should have one step, got {len(res.steps)}";
    assert res.steps[0].verb == "endorsed", f"custom verb ignored: {res.steps[0].verb}";
    assert "Author endorsed Post" in res.description, f"description: {res.description}";
