import io;
import from contextlib { redirect_stdout }

test "ready only when all distinct inputs are available" {
    src = Artifact(output_id="src");
    t1 = Transform(name="t1", declared_inputs=1, distinct_inputs=1, available_inputs=1);
    t2 = Transform(name="t2", declared_inputs=2, distinct_inputs=2, available_inputs=2);

    root ++> t1;
    root ++> t2;
    t1 +>:DependsOn(input_id="src"):+> src;
    t2 +>:DependsOn(input_id="src"):+> src;
    t2 +>:DependsOn(input_id="t1"):+> t1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver();
    }
    out = buf.getvalue();

    assert t1.state == "ready", f"t1 state was {t1.state}";
    assert t2.state == "ready", f"t2 state was {t2.state}";
    assert "t1 is ready: 1/1 distinct inputs from 1 declarations" in out, f"missing t1 readiness: {out}";
    assert "t2 is ready: 2/2 distinct inputs from 2 declarations" in out, f"missing t2 readiness: {out}";
}

test "partial inputs remain unresolved" {
    src = Artifact(output_id="src");
    partial = Transform(name="partial", declared_inputs=2, distinct_inputs=2, available_inputs=1, missing_input="t1");

    root ++> partial;
