    assert partial.state == "blocked", f"partial state was {partial.state}";
    assert "partial is unresolved: 1/2 distinct inputs available; missing t1" in out, f"missing unresolved report: {out}";
}

test "duplicate inputs and empty fallback remain compatible" {
    src = Artifact(output_id="src");
