    assert empty.state == "ready", f"empty state was {empty.state}";
    assert "duplicate is ready: 1/1 distinct inputs from 2 declarations" in out, f"missing duplicate readiness: {out}";
    assert "empty is ready: 0/0 distinct inputs from 0 declarations" in out, f"missing empty readiness: {out}";
    assert "empty uses the empty-input fallback" in out, f"missing empty fallback: {out}";
}

test "cycle detection reports the concrete cycle path" {
    c1 = Transform(name="c1");
    c2 = Transform(name="c2");

    c1 +>:DependsOn(input_id="c2"):+> c2;
    c2 +>:DependsOn(input_id="c1"):+> c1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = c1 spawn CycleDetector();
    }
    out = buf.getvalue();

    assert "cycle detected: c1 -> c2 -> c1" in out, f"missing cycle path: {out}";
    assert c1.state == "visiting", f"c1 state was {c1.state}";
    assert c2.state == "visiting", f"c2 state was {c2.state}";
}

