    with redirect_stdout(buf) {
        res = root spawn FederationDispatcher();
    }
    out = buf.getvalue();

    assert event.stage == "queued", f"got {event.stage}";
    assert event.attempts == 1, f"got {event.attempts}";
    assert peer.delivery_state == "pending", f"got {peer.delivery_state}";
    assert peer.remote_storage == "not-stored", f"got {peer.remote_storage}";
