    assert first.delivery_state == "radio-sent", f"got {first.delivery_state}";
    assert second.delivery_state == "radio-sent", f"got {second.delivery_state}";
    assert res.delivered_peers == 2, f"got {res.delivered_peers}";
    assert "cycle guard stopped at peer Relay A" in out, f"missing cycle output: {out}";
