import io;
import from contextlib { redirect_stdout }

test "nominal implementations take precedence" {
    nominal_receiver = ReceiverType(
        type_name="string",
        contract_name="IComparable<string>",
        nominal_match=True
    );
    root ++> nominal_receiver;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WitnessResolver();
    }
    out = buf.getvalue();

    assert "string satisfies IComparable<string> nominally" in out, f"got {out}";
    assert res.candidates_seen == 0, f"got {res.candidates_seen}";
    assert res.resolved == False, f"got {res.resolved}";
}

test "valid witness resolves the contract" {
    extension_receiver = ReceiverType(
        type_name="List<int>",
        contract_name="IDeepEqual<List<int>>"
    );
    witness = Witness(
        witness_name="ListDeepEqualityWitness",
        valid=True
    );
    contract = Contract(
        interface_name="IDeepEqual<List<int>>",
        requires_witness=True
    );

    root ++> extension_receiver;
    extension_receiver +>:Candidate(owner="DeepEqualityExtensions"):+> witness;
    witness +>:Implements(method_count=1):+> contract;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WitnessResolver();
    }
    out = buf.getvalue();

    assert "List<int> needs a witness for IDeepEqual<List<int>>" in out, f"got {out}";
    assert "Candidate witness: ListDeepEqualityWitness" in out, f"got {out}";
    assert "Resolved contract: IDeepEqual<List<int>>" in out, f"got {out}";
    assert res.candidates_seen == 1, f"got {res.candidates_seen}";
    assert res.resolved == True, f"got {res.resolved}";
}

test "invalid witness fails closed" {
    extension_receiver = ReceiverType(
        type_name="List<float>",
        contract_name="IDeepEqual<List<float>>"
    );
    witness = Witness(
        witness_name="InvalidWitness",
        valid=False
    );

    root ++> extension_receiver;
    extension_receiver +>:Candidate(owner="BrokenExtensions"):+> witness;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn WitnessResolver();
    }
    out = buf.getvalue();

    assert "List<float> needs a witness for IDeepEqual<List<float>>" in out, f"got {out}";
    assert "Rejected invalid witness: InvalidWitness" in out, f"got {out}";
    assert res.candidates_seen == 1, f"got {res.candidates_seen}";
    assert res.resolved == False, f"got {res.resolved}";
}

