    );
    first_last = SyllabusTopic(title="First and Last Position", year=2024);
    rotated = SyllabusTopic(title="Search in Rotated Sorted Array", year=2024);

    section +>:Contains(order=1):+> binary_search;
    binary_search +>:Prerequisite(note="boundary invariant"):+> first_last;
    first_last +>:Prerequisite(note="reuses boundary search"):+> rotated;

    direct_children = [root-->];
