        transition_warranted=False
    );

    root ++> observation;
    observation +>:InterpretedAs(basis="provenance-preserving observation"):+> interpretation;
    interpretation +>:AssessedBy(gate="diagnostic qualification"):+> diagnosis;
    diagnosis +>:AssessedBy(gate="separate assessment gate"):+> assessment;
    assessment +>:RecursAt(reason="monitor recurrence across representational levels"):+> diagnosis;

