    assert observation in [root-->], f"observation is not rooted";
    assert interpretation in [observation ->:InterpretedAs:->], f"interpretation edge missing";
    assert diagnosis in [interpretation ->:AssessedBy:->], f"diagnosis edge missing";
    assert assessment in [diagnosis ->:AssessedBy:->], f"assessment edge missing";
    assert diagnosis in [assessment ->:RecursAt:->], f"recursive edge missing";
    assert assessment.transition_warranted == False, f"got {assessment.transition_warranted}";
}

test "traverses the episode and stops recursive vigilance" {
    observation = Observation(
        domain="OOD classification",
        residual="persistent structured errors"
    );
    interpretation = Interpretation(
        explanation="errors remain after local correction",
        alternatives_examined="label noise and calibration drift"
    );
    diagnosis = Diagnosis(
        signal="representational_alert",
        manifestation="generalization",
        regime="representationally_resolutive"
    );
    assessment = Assessment(
        qualification="suspected_explanatory_insufficiency",
        uncertainty="latent representation was not directly observed",
        transition_warranted=False
    );

    root ++> observation;
    observation +>:InterpretedAs(basis="observed residual"):+> interpretation;
    interpretation +>:AssessedBy(gate="diagnostic qualification"):+> diagnosis;
    diagnosis +>:AssessedBy(gate="separate assessment gate"):+> assessment;
    assessment +>:RecursAt(reason="recursive monitoring"):+> diagnosis;

    buf = io.StringIO();
    with redirect_stdout(buf) {
