"""Recursive Flux diff demo: expand stale Kustomizations into cascade deletions."""

node Kustomization {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has namespace: str = "";
    has prune: bool = True;
    has scanned: bool = False;
}

node HelmRelease {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has namespace: str = "";
    has scanned: bool = False;
}

edge Inventory {
    has source: str = "status.inventory";
}

walker CascadeDiff {
    has deleted_count: int = 0;

    can start with Root entry {
        print("Recursive diff of the local build against live inventory:");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_kustomization with Kustomization entry {
        if here.scanned == False {
            here.scanned = True;

            if here.available == False {
                print(f"► Kustomization/{here.namespace}/{here.title} deleted (cascade)");
                self.deleted_count = self.deleted_count + 1;
            }

            if here.prune {
                visit [->:Inventory:->] else {
                    disengage;
                }
            }
        }
    }

    can inspect_release with HelmRelease entry {
        if here.scanned == False {
            here.scanned = True;

            if here.available == False {
                print(f"  ► HelmRelease/{here.namespace}/{here.title} deleted");
                self.deleted_count = self.deleted_count + 1;
            }
        }
    }

    can summarize with Root exit {
        print(f"Total cascade deletions: {self.deleted_count}");
    }
}

with entry {
    flux = Kustomization(
        title="flux-system",
        namespace="flux-system",
        available=True,
        prune=True
    );
    infra = Kustomization(
        title="infra",
        namespace="flux-system",
        available=False,
        prune=True
    );
    monitoring = Kustomization(
        title="monitoring",
        namespace="flux-system",
        available=False,
        prune=True
    );

    loki = HelmRelease(
        title="loki",
        namespace="flux-system",
        available=False
    );
    grafana = HelmRelease(
        title="grafana",
        namespace="flux-system",
        available=False
    );
    prometheus = HelmRelease(
        title="prometheus",
        namespace="flux-system",
        available=False
    );

    root ++> flux;
    flux +>:Inventory:+> infra;
    infra +>:Inventory:+> loki;
    infra +>:Inventory:+> grafana;
    infra +>:Inventory:+> monitoring;
    monitoring +>:Inventory:+> prometheus;

    root spawn CascadeDiff();
}
