"""Read-only DNA workflow graph with staged mutations and cycle detection."""

node DnaEntity {
    has identifier: str = "";
    has label: str = "";
    has state: str = "";
    has visited: bool = False;
}

node Task(DnaEntity) {
    has intent: str = "";
}

node Attempt(DnaEntity) {
    has model_hash: str = "";
}

node Mutation(DnaEntity) {
    has stage: str = "staged";
    has applied: bool = False;
}

edge Contains {
    has relation: str = "contains";
}

edge WorkflowStep {
    has sequence: int = 0;
}

edge Produces {
    has digest: str = "";
}

edge Invalidates {
    has reason: str = "";
}

walker GovernanceAudit {
    has visits: int = 0;
    has cycle_hits: int = 0;

    can begin with Root entry {
        print("Auditing read-only DNA workflow");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Task | Attempt | Mutation entry {
        if here.visited {
            self.cycle_hits += 1;
            print(f"cycle detected at {here.label}");
        } else {
            here.visited = True;
            self.visits += 1;
            print(f"visited {here.label}: {here.state}");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    task = Task(
        identifier="task-001",
        label="Review organism purpose",
        state="active",
        intent="Ratify the declared purpose"
    );
    attempt = Attempt(
        identifier="attempt-001",
        label="Local model attempt",
        state="completed",
        model_hash="model-local-v1"
    );
    mutation = Mutation(
        identifier="mutation-001",
        label="Genome update",
        state="staged",
        stage="staged",
        applied=False
    );

    root +>:Contains(relation="organism task"):+> task;
    task +>:WorkflowStep(sequence=1):+> attempt;
    attempt +>:Produces(digest="evidence-001"):+> mutation;
    mutation +>:Invalidates(reason="review required before deployment"):+> task;

    root spawn GovernanceAudit();
}
