"""Cold carapace cache recursion modeled as a typed dependency graph."""

node Startup {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FishWrapper {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has injects_init: bool = True;
}

node CarapaceBridge {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cache_ready: bool = False;
}

node Cache {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has populated: bool = False;
}

edge Dependency {
    has relation: str = "";
}

walker CacheAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        print("Auditing fish startup dependency graph");
        visit [->:Dependency:->] else {
            disengage;
        }
    }

    can inspect_startup with Startup entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping recursion");
            disengage;
        } else {
            self.seen.append(here.title);
            print(f"start: {here.title}");
            visit [->:Dependency:->] else {
                disengage;
            }
        }
    }

    can inspect_wrapper with FishWrapper entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping recursion");
            disengage;
        } else {
            self.seen.append(here.title);
            print(f"wrapper injects init command: {here.injects_init}");
            visit [->:Dependency:->] else {
                disengage;
            }
        }
    }

    can inspect_bridge with CarapaceBridge entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping recursion");
            disengage;
        } else {
            self.seen.append(here.title);
            print(f"bridge cache ready: {here.cache_ready}");
            visit [->:Dependency:->] else {
                disengage;
            }
        }
    }

    can inspect_cache with Cache entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping recursion");
            disengage;
        } else {
            self.seen.append(here.title);
            print(f"cache populated: {here.populated}");
            visit [->:Dependency:->] else {
                disengage;
            }
        }
    }
}

with entry {
    startup = Startup(title="interactive fish startup");
    wrapper = FishWrapper(title="wrapped fish", injects_init=True);
    bridge = CarapaceBridge(title="carapace fish bridge", cache_ready=False);
    cache = Cache(title="cold bridges-fish.json", populated=False);

    root +>:Dependency(relation="launch"):+> startup;
    startup +>:Dependency(relation="executes wrapper"):+> wrapper;
    wrapper +>:Dependency(relation="runs carapace"):+> bridge;
    bridge +>:Dependency(relation="reads cache"):+> cache;
    cache +>:Dependency(relation="restarts fish from PATH"):+> wrapper;

