"""Terminal attachment graph with safe nesting and explicit cycle detection."""

node Server {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has incarnation_id: str = "";
}

node Terminal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has server_incarnation_id: str = "";
    has terminal_id: str = "";
    has socket_name: str = "";

    def identity() -> str {
        return f"{self.server_incarnation_id}/{self.terminal_id}";
    }
}

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
    has name: str = "";
}

edge Hosts { }
edge Attaches { }
edge Displays {
    has hop: int = 0;
}
edge CycleStart { }
edge SelfStart { }
edge SafeStart { }

walker CycleGuard {
    has seen_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:CycleStart:->] else {
            disengage;
        }
    }

    can follow with Session entry {
        print(f"checking session {here.name}");
        visit [->:Attaches:->] else {
            disengage;
        }
    }

    can inspect with Terminal entry {
        identity = here.identity();
        if identity in self.seen_ids {
            self.cycle_found = True;
            print(f"REJECTED cyclic display at {identity}");
            disengage;
        } else {
            self.seen_ids = self.seen_ids + [identity];
            print(f"displaying {here.socket_name} on {identity}");
            visit [->:Displays:->] else {
                disengage;
            }
        }
    }
}

walker SelfViewGuard {
    has seen_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:SelfStart:->] else {
            disengage;
        }
    }

    can follow with Session entry {
        print(f"checking session {here.name}");
        visit [->:Attaches:->] else {
            disengage;
        }
    }

    can inspect with Terminal entry {
        identity = here.identity();
        if identity in self.seen_ids {
            self.cycle_found = True;
            print(f"REJECTED direct self-view at {identity}");
            disengage;
        } else {
            self.seen_ids = self.seen_ids + [identity];
            visit [->:Displays:->] else {
                disengage;
            }
        }
    }
}

walker SafePathAudit {
    has seen_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:SafeStart:->] else {
            disengage;
        }
    }

    can follow with Session entry {
        print(f"checking safe session {here.name}");
        visit [->:Attaches:->] else {
            disengage;
        }
    }

    can inspect with Terminal entry {
        identity = here.identity();
        if identity in self.seen_ids {
            self.cycle_found = True;
            print(f"REJECTED unexpected cycle at {identity}");
            disengage;
        } else {
            self.seen_ids = self.seen_ids + [identity];
            print(f"safe target {here.socket_name} on {identity}");
            visit [->:Displays:->] else {
                disengage;
            }
        }
    }
}

with entry {
    server_a = Server(title="local host", incarnation_id="srv-a");
    server_b = Server(title="remote host", incarnation_id="srv-b");
    server_c = Server(title="relay host", incarnation_id="srv-c");

    cycle_a = Terminal(
        title="cycle origin",
        server_incarnation_id="srv-a",
        terminal_id="tty-main",
        socket_name="/tmp/huterm-a"
    );
    cycle_b = Terminal(
        title="cycle middle",
        server_incarnation_id="srv-b",
        terminal_id="tty-main",
        socket_name="/tmp/huterm-b"
    );
    cycle_c = Terminal(
        title="cycle end",
        server_incarnation_id="srv-c",
        terminal_id="tty-main",
        socket_name="/tmp/huterm-c"
    );

    server_a +>:Hosts:+> cycle_a;
    server_b +>:Hosts:+> cycle_b;
    server_c +>:Hosts:+> cycle_c;

    cycle_a +>:Displays(hop=1):+> cycle_b;
    cycle_b +>:Displays(hop=2):+> cycle_c;
