import from contextlib { redirect_stdout }

test "audits cached and uncached DFA states through cycles" {
    mode = LexerMode(
        title="default mode",
        mode_number=0,
        mode_name="DEFAULT_MODE"
    );
    start = DfaState(
        title="start",
        state_number=0,
        accepting_rule=0,
        accepting_length=0,
        cached=True
    );
    accepting = DfaState(
        title="accepting",
        state_number=1,
        accepting_rule=2,
        accepting_length=4,
        cached=True
    );
    fallback = DfaState(
        title="fallback",
        state_number=2,
        accepting_rule=3,
        accepting_length=1,
        cached=False
    );

    root +>:Owns(relation="mode"):+> mode;
    mode +>:Owns(relation="start"):+> start;
    mode +>:Owns(relation="accepting"):+> accepting;
    mode +>:Owns(relation="fallback"):+> fallback;

    start +>:CachedTransition(symbol="a-z", cache_hit=True):+> accepting;
    accepting +>:CachedTransition(symbol="a-z0-9", cache_hit=True):+> fallback;
    fallback +>:CachedTransition(symbol="a-z0-9", cache_hit=False):+> accepting;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DfaCacheAuditor();
