"""ACL-aware graph visualizer demo with raw and filtered walks."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner: str = "";
    has details: str = "";
    has visible_to_all: bool = False;

    def readable_to(viewer: str) -> bool {
        if self.visible_to_all {
            return True;
        }
        if self.owner == viewer {
            return True;
        }
        return False;
    }
}

node SharedSpace(GraphItem) {
    has label: str = "";
}

node Account(GraphItem) {
    has email: str = "";
}

node Secret(GraphItem) {
    has value: str = "";
}

edge Contains { }

walker RawGraphDump {
    can start with Root entry {
        print("[raw graph dump]");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with SharedSpace | Account | Secret entry {
        print(f"RAW {here.title}: {here.details}");
        visit [->:Contains:->] else {
            disengage;
        }
    }
}

walker AuthorizedGraphDump {
    has viewer: str = "";

    can start with Root entry {
        print(f"[ACL graph dump for {self.viewer}]");
        visit [->:Contains:->] else {
            disengage;
        }
