test "audit detects drift and impacted records" {
    requirement = Requirement(
        record_id="REQ-42",
        title="Incremental update requirement",
        impacted=True
    );
    component = Component(
        record_id="COMP-42",
        title="Incremental update engine",
        impacted=True,
        reference="src/update-engine.ts"
    );
    design = DesignDocument(
        record_id="DOC-42",
        title="Enhancement design",
        drifted=True,
        reference="docs/design.md:18"
    );
    acceptance = AcceptanceTest(
        record_id="TEST-42",
        title="Incremental update acceptance",
        reference="tests/incremental-update.test.ts"
    );

    root +>:Contains:+> requirement;
    requirement +>:Impacts:+> component;
    requirement +>:DescribedBy:+> design;
    component +>:CoveredBy:+> acceptance;

