"""Belief lineage demo: a retired belief is linked to its replacement."""

node Person {
    has name: str = "";
}

node Belief {
    has record_id: str = "";
    has title: str = "";
    has valid_until: str = "";
    has retired: bool = False;
}

edge Owns { }
edge Holds { }
edge Supersedes {
    has reason: str = "";
}

walker LineageReviewer {
    has seen_record_ids: list[str] = [];

    can start with Root entry {
        print("Reviewing durable belief lineage");
        visit [->:Owns:->] else { disengage; }
    }

    can enter with Person entry {
        print(f"Subject: {here.name}");
        visit [->:Holds:->] else { disengage; }
    }

    can inspect with Belief entry {
        if here.record_id in self.seen_record_ids {
            print(f"Cycle detected at belief record {here.record_id}");
            disengage;
        } else {
            self.seen_record_ids.append(here.record_id);
            status = "retired" if here.retired else "current";
            print(f"{status}: {here.title} (valid until {here.valid_until})");
            visit [->:Supersedes:->] else { disengage; }
        }
    }
}

with entry {
    person = Person(name="Mira");
    current = Belief(
        record_id="belief-002",
        title="Mira prefers tea",
        valid_until="open"
    );
    retired = Belief(
        record_id="belief-001",
        title="Mira prefers coffee",
        valid_until="2024-06-01",
        retired=True
    );

    root +>:Owns:+> person;
    person +>:Holds:+> current;
    current +>:Supersedes(reason="New conversation evidence"):+> retired;

    root spawn LineageReviewer();
}
