import io;
import from contextlib { redirect_stdout }

test "reviews current belief and its retired predecessor" {
    person = Person(name="Mira");
    current = Belief(
        record_id="belief-002",
        title="Mira prefers tea",
        valid_until="open"
    );
    retired = Belief(
        record_id="belief-001",
        title="Mira prefers coffee",
        valid_until="2024-06-01",
        retired=True
    );

    root +>:Owns:+> person;
    person +>:Holds:+> current;
    current +>:Supersedes(reason="New conversation evidence"):+> retired;

    assert len([root ->:Owns:->]) == 1, "expected one owned person";
    assert person in [root ->:Owns:->], "root must own Mira";
    assert current in [person ->:Holds:->], "Mira must hold the current belief";
    assert retired in [current ->:Supersedes:->], "current belief must link to retired belief";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageReviewer();
    }
    out = buf.getvalue();

    assert "Reviewing durable belief lineage" in out, f"missing review marker: {out}";
    assert "Subject: Mira" in out, f"missing subject: {out}";
    assert "current: Mira prefers tea" in out, f"missing current belief: {out}";
    assert "retired: Mira prefers coffee" in out, f"missing retired belief: {out}";
}

test "detects a supersession cycle by record id" {
    person = Person(name="Alex");
    current = Belief(
        record_id="belief-010",
        title="Alex likes hiking",
        valid_until="open"
    );
    retired = Belief(
        record_id="belief-009",
        title="Alex likes running",
        valid_until="2025-01-01",
        retired=True
    );

    root +>:Owns:+> person;
    person +>:Holds:+> current;
    current +>:Supersedes(reason="Updated preference"):+> retired;
    retired +>:Supersedes(reason="Contradictory correction"):+> current;

    assert retired in [current ->:Supersedes:->], "current belief must point to predecessor";
    assert current in [retired ->:Supersedes:->], "cycle must point back to current belief";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageReviewer();
    }
    out = buf.getvalue();

    assert "current: Alex likes hiking" in out, f"missing current belief: {out}";
    assert "retired: Alex likes running" in out, f"missing retired belief: {out}";
    assert "Cycle detected at belief record belief-010" in out, f"missing cycle detection: {out}";
}

test "stops when a person has no held belief" {
    person = Person(name="Sam");
    root +>:Owns:+> person;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LineageReviewer();
    }
    out = buf.getvalue();

    assert "Reviewing durable belief lineage" in out, f"missing review marker: {out}";
    assert "Subject: Sam" in out, f"missing subject: {out}";
    assert "current:" not in out, f"unexpected belief traversal: {out}";
    assert "retired:" not in out, f"unexpected retired traversal: {out}";
}

