import io;
import from contextlib { redirect_stdout }

test "handles client health exception as unhealthy" {
    tool = AllotMintHealthTool();
    client = AllotMintClient(
        endpoint="https://api.allotmint.example",
        health_throws=True
    );
    response = HealthResponse();

    root ++> tool;
    tool +>:UsesClient:+> client;
    client +>:ReturnsHealth:+> response;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HealthCheck();
    }
    out = buf.getvalue();

    assert res.status == "unhealthy", f"got {res.status}";
    assert "health check failed" in res.structured_content, f"got {res.structured_content}";
    assert "unhealthy" in res.text_output, f"got {res.text_output}";
    assert response.status == "unhealthy", f"got {response.status}";
    assert response.structured_content == res.structured_content, f"got {response.structured_content}";
    assert response.text_output == res.text_output, f"got {response.text_output}";
    assert "structuredContent:" in out, f"missing structured output: {out}";
    assert "client.health() threw an exception" in out, f"missing error output: {out}";
}

test "reports healthy client response" {
    tool = AllotMintHealthTool();
    client = AllotMintClient(
        endpoint="https://api.allotmint.example",
        health_throws=False
    );
    response = HealthResponse();

    root ++> tool;
    tool +>:UsesClient:+> client;
    client +>:ReturnsHealth:+> response;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HealthCheck();
    }
    out = buf.getvalue();

    assert res.status == "healthy", f"got {res.status}";
    assert res.structured_content == "{\"status\":\"healthy\"}", f"got {res.structured_content}";
    assert res.text_output == "AllotMint backend is healthy", f"got {res.text_output}";
    assert response.status == "healthy", f"got {response.status}";
    assert "healthy" in out, f"missing healthy output: {out}";
}

