"""A native graph demo for generic document indexing, invalidation, and cycle safety."""

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stable_id: str = "";
    has location: str = "";
    has parser: str = "";
    has invalidated: bool = False;
    has visit_count: int = 0;
}

node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stable_id: str = "";
    has checksum: str = "";
    has whole_document: bool = True;
    has invalidated: bool = False;
    has visit_count: int = 0;
}

node Chunk {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stable_id: str = "";
    has ordinal: int = 0;
    has embedding_kind: str = "";
    has invalidated: bool = False;
    has visit_count: int = 0;
}

edge IndexLink {
    has relation: str = "";
    has ordinal: int = 0;
}

walker IndexAuditor {
    has max_hops: int = 12;
    has hops: int = 0;

    can start with Root entry {
        print("Beginning index graph audit");
        visit [->:IndexLink:->] else {
            disengage;
        }
    }

    can inspect with Source | Document | Chunk entry {
        if here.visit_count > 0 {
            print(f"Cycle or duplicate detected at {here.title}");
            disengage;
        }

        if self.hops >= self.max_hops {
            print(f"Traversal depth limit reached at {here.title}");
            disengage;
        }

        here.visit_count = here.visit_count + 1;
        self.hops = self.hops + 1;

        if here.available == False {
            here.invalidated = True;
            print(f"Invalidated stale record: {here.title}");
        } else {
            print(f"Indexed record: {here.title}");
        }

        visit [->:IndexLink:->] else {
            disengage;
        }
    }
}

with entry {
    source = Source(
        title="Knowledge Sources",
        stable_id="source-1",
        location="~/notes",
        parser="org"
    );

    document = Document(
        title="Retrieval Architecture",
        stable_id="doc-1",
        checksum="checksum-v2",
        whole_document=True
    );

    chunk = Chunk(
        title="Retrieval Architecture: backend strategy",
        stable_id="chunk-1",
        ordinal=0,
        embedding_kind="chunk",
        available=False
    );

    root +>:IndexLink(relation="configured-source"):+> source;
    source +>:IndexLink(relation="contains-document"):+> document;
    document +>:IndexLink(relation="contains-chunk", ordinal=0):+> chunk;
    chunk +>:IndexLink(relation="cycle-demo"):+> document;

    root spawn IndexAuditor(max_hops=12);
}
