import io;
import from contextlib { redirect_stdout }

test "cancelled queued chapter cannot be claimed" {
    manga = Manga(title="Kira Manga", year=2025);
    chapter = Chapter(title="queued", year=2025);
    root ++> manga;
    manga +>:Contains(chapter_number=1):+> chapter;

    chapter.request_cancel();
    claimed = chapter.claim_queued();

    assert not claimed, f"claim returned {claimed}";
    assert chapter.state == "QUEUED", f"state changed to {chapter.state}";
    assert chapter.active == False, f"active changed to {chapter.active}";
    assert chapter.generation == 0, f"generation changed to {chapter.generation}";
}

test "cancellation invalidates the claimed worker generation" {
    manga = Manga(title="Kira Manga", year=2025);
    chapter = Chapter(title="active", year=2025);
    root ++> manga;
    manga +>:Contains(chapter_number=2):+> chapter;

    claimed = chapter.claim_queued();
    worker_generation = chapter.generation;
    before_cancel = chapter.accept_page(worker_generation);
    chapter.request_cancel();
    cancelled = chapter.cancel_if_requested();
    after_cancel = chapter.accept_page(worker_generation);
    completed = chapter.publish_success(worker_generation);

    assert claimed, f"claim returned {claimed}";
    assert before_cancel, f"page before cancel was {before_cancel}";
    assert cancelled, f"cancel returned {cancelled}";
    assert not after_cancel, f"page after cancel was {after_cancel}";
    assert not completed, f"success publication returned {completed}";
    assert chapter.pages_written == 1, f"pages written was {chapter.pages_written}";
    assert chapter.state == "CANCELLED", f"state was {chapter.state}";
    assert chapter.active == False, f"active was {chapter.active}";
    assert chapter.generation == worker_generation + 1, f"generation was {chapter.generation}";
}

test "worker drain rejects a cancelled chapter through ownership edges" {
    chapter = Chapter(title="owned", year=2025);
    worker = DownloadWorker(title="worker", worker_name="W-1");
    root +>:WorkerRoot:+> worker;
    worker +>:Owns(generation=0):+> chapter;
    chapter.request_cancel();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn WorkerDrain();
    }

    assert chapter.state == "QUEUED", f"state was {chapter.state}";
    assert chapter.active == False, f"active was {chapter.active}";
    assert chapter.pages_written == 0, f"pages written was {chapter.pages_written}";
    assert "claim rejected" in buf.getvalue(), f"output was {buf.getvalue()}";
}

