test "healthy listeners complete their assigned one-job generations" {
    fleet = Fleet(
        title="pc-ci trusted fleet",
        year=2026,
        classification="LISTENER_RESTART_FAILED",
        queued_jobs=2
    );
    ci1 = Listener(title="pc-ci-1", year=2026);
    ci2 = Listener(title="pc-ci-2", year=2026);
    job0 = Job(title="trusted-executor-pack-0", year=2026);
    job1 = Job(title="trusted-executor-pack-1", year=2026);

    root ++> fleet;
    fleet +>:Hosts(role="ci-linux"):+> ci1;
    fleet +>:Hosts(role="ci-linux"):+> ci2;
    ci1 +>:Assigned(queue="trusted-executor-pack-0", attempt=1):+> job0;
    ci2 +>:Assigned(queue="trusted-executor-pack-1", attempt=1):+> job1;

    root_children = len([root-->]);
    host_count = len([fleet ->:Hosts:->]);
    assert root_children == 1, f"root children: {root_children}";
    assert host_count == 2, f"hosts: {host_count}";
    assert job0 in [ci1 ->:Assigned:->], "job0 is not assigned from ci1";
    assert job1 in [ci2 ->:Assigned:->], "job1 is not assigned from ci2";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res1 = ci1 spawn LivenessAudit();
        res2 = ci2 spawn LivenessAudit();
    }
