    assert fleet.classification == "LISTENER_RESTART_FAILED", f"classification: {fleet.classification}";
    assert ci1.online == True, f"ci1 online: {ci1.online}";
    assert ci2.online == True, f"ci2 online: {ci2.online}";
    assert ci1.jobs_completed == 1, f"ci1 jobs: {ci1.jobs_completed}";
    assert ci2.jobs_completed == 1, f"ci2 jobs: {ci2.jobs_completed}";
    assert job0.queued == False, f"job0 queued: {job0.queued}";
    assert job1.queued == False, f"job1 queued: {job1.queued}";
    assert job0.completed == True, f"job0 completed: {job0.completed}";
    assert job1.completed == True, f"job1 completed: {job1.completed}";
    assert job0.runner_id == 1, f"job0 runner: {job0.runner_id}";
    assert job1.runner_id == 1, f"job1 runner: {job1.runner_id}";
    assert res1.restored_runner == 1, f"restored runner: {res1.restored_runner}";
    assert res2.restored_runner == 1, f"restored runner: {res2.restored_runner}";
    assert "pc-ci-1: one-job restart returned online/idle" in out, f"output: {out}";
    assert "pc-ci-2: one-job restart returned online/idle" in out, f"output: {out}";
}

test "an unavailable listener fails closed without processing its queued job" {
    fleet = Fleet(title="pc-ci guarded fleet", classification="RESOURCE_GUARD_REFUSAL", queued_jobs=1);
    ci3 = Listener(title="pc-ci-3", available=False, online=False);
    job = Job(title="trusted-executor-pack-0");

    root ++> fleet;
    fleet +>:Hosts(role="ci-linux"):+> ci3;
    ci3 +>:Assigned(queue="trusted-executor-pack-0", attempt=1):+> job;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = ci3 spawn LivenessAudit();
