"""Mautic asset regression demo: detect an AssetMapper cycle and report a forbidden CSS artifact."""

node Asset {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has visited: bool = False;
}

node BuildArtifact {
