    has available: bool = True;
    has path: str = "";
    has http_status: int = 200;
}

node WebRoute {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
}

edge DependsOn {
    has reason: str = "";
}

edge Serves {
    has content_path: str = "";
}

walker AssetAuditor {
    has cycle_found: bool = False;

    can start with Root entry {
        print("Auditing Mautic asset graph");
        visit [-->] else {
            disengage;
