    can inspect_asset with Asset entry {
        if here.visited {
            self.cycle_found = True;
            print(f"CYCLE: {here.title} was reached twice");
            disengage;
        } else {
            here.visited = True;
            print(f"Asset: {here.title} ({here.kind})");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect_artifact with BuildArtifact entry {
        status = "READY" if here.available else "FORBIDDEN";
        print(f"{status}: {here.path} returned HTTP {here.http_status}");
    }
}

with entry {
