"""Executive-app static fences modeled as a typed package census."""

node Entity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node AppPackage(Entity) {
    has package_path: str = "";
    has allowed_paths: list[str] = [];
}

node SourceModule(Entity) {
    has path: str = "";
    has extension: str = ".py";
}

node ImportSpec(Entity) {
    has module_name: str = "";
    has member: str = "";
    has star: bool = False;

    def normalized() -> str {
        candidate = self.module_name;
        if self.member != "" {
            if self.member != "*" {
                candidate = f"{self.module_name}.{self.member}";
            }
        }
        return candidate;
    }

    def is_forbidden() -> bool {
        candidate = self.normalized();
        if candidate == "integrations.executive_mcp.server" {
            return True;
        }
        if candidate == "control_plane.executive_service" {
            return True;
        }
        if candidate == "control_plane.ceo_intent" {
            return True;
        }
        return False;
    }
}

edge Contains {
    has relation: str = "contains";
}

edge Declares {
    has relation: str = "declares";
}

edge AuditNext {
    has relation: str = "next audit record";
}

walker FenceAuditor {
    has allowed_paths: list[str] = [];
    has checked_paths: list[str] = [];
    has forbidden_imports: int = 0;
    has refused_paths: int = 0;

    can start with Root entry {
        print("Starting recursive package census");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter_package with AppPackage entry {
        if here.package_path == "integrations/mastermind_executive_app" {
            self.allowed_paths = here.allowed_paths;
            print(f"census package: {here.package_path}");
            visit [->:AuditNext:->] else {
                disengage;
            }
        } else {
            print(f"census nested package: {here.package_path}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can census_module with SourceModule entry {
        if here.extension == ".py" {
            if here.path in self.checked_paths {
                disengage;
            }
            self.checked_paths.append(here.path);

            if here.path not in self.allowed_paths {
                self.refused_paths += 1;
                print(f"refused unreviewed source: {here.path}");
            } else {
                print(f"accepted source: {here.path}");
            }

            if here.path == "integrations/mastermind_executive_app/executive_app.py" {
                visit [->:Declares:->] else {
                    disengage;
                }
            } else {
                visit [->:AuditNext:->] else {
                    disengage;
                }
            }
        }
    }

    can inspect_import with ImportSpec entry {
        candidate = here.normalized();
        if here.is_forbidden() {
            self.forbidden_imports += 1;
            print(f"forbidden import detected: {candidate}");
        } else {
            print(f"accepted import: {candidate}");
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    app = AppPackage(
        package_path="integrations/mastermind_executive_app",
        allowed_paths=[
            "integrations/mastermind_executive_app/__init__.py",
            "integrations/mastermind_executive_app/executive_app.py",
            "integrations/mastermind_executive_app/schema.py",
            "integrations/mastermind_executive_app/workflow.py"
        ]
    );

    init_module = SourceModule(
        path="integrations/mastermind_executive_app/__init__.py"
    );
    app_module = SourceModule(
        path="integrations/mastermind_executive_app/executive_app.py"
    );
    schema_module = SourceModule(
        path="integrations/mastermind_executive_app/schema.py"
    );
    workflow_module = SourceModule(
        path="integrations/mastermind_executive_app/workflow.py"
    );

    nested = AppPackage(
        package_path="integrations/mastermind_executive_app/subpackage"
    );
    hidden_module = SourceModule(
        path="integrations/mastermind_executive_app/subpackage/hidden_ingress.py"
    );

    hostile_server = ImportSpec(
        module_name="integrations.executive_mcp",
        member="server"
    );
    hostile_service = ImportSpec(
        module_name="control_plane",
        member="executive_service"
    );
    hostile_intent = ImportSpec(
        module_name="control_plane",
        member="ceo_intent"
    );
    legal_request = ImportSpec(
        module_name="control_plane",
        member="ceo_request"
    );

    root +>:Contains:+> app;
    app +>:AuditNext:+> init_module;
    init_module +>:AuditNext:+> app_module;
    app_module +>:Declares:+> hostile_server;
    hostile_server +>:AuditNext:+> hostile_service;
    hostile_service +>:AuditNext:+> hostile_intent;
    hostile_intent +>:AuditNext:+> legal_request;
    legal_request +>:AuditNext:+> schema_module;
    schema_module +>:AuditNext:+> workflow_module;
    workflow_module +>:AuditNext:+> nested;
    nested +>:Contains:+> hidden_module;

    audit = FenceAuditor();
    root spawn audit;
    print(f"summary: {audit.forbidden_imports} forbidden imports, {audit.refused_paths} refused paths");
}
