import io;
import from contextlib { redirect_stdout }

test "dependency audit detects typed-edge cycles" {
    c1 = Case(
        case_id="C-001",
        subsystem="preprocessing"
    );
    c2 = Case(
        case_id="C-002",
        subsystem="diagnostics",
        valid_program=False
    );
    c3 = Case(
        case_id="C-003",
        subsystem="codegen"
    );

    root ++> c1;
    c1 +>:DependsOn(reason="preprocess before diagnostics"):+> c2;
    c2 +>:DependsOn(reason="diagnostics before code generation"):+> c3;
    c3 +>:DependsOn(reason="cycle probe"):+> c1;

    assert len([root -->]) == 1, f"unexpected root children: {len([root -->])}";
    assert c2 in [c1 ->:DependsOn:->], f"missing C-001 dependency";
    assert c3 in [c2 ->:DependsOn:->], f"missing C-002 dependency";
    assert c1 in [c3 ->:DependsOn:->], f"missing cycle edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
    }
    out = buf.getvalue();

    assert len(res.seen) == 3, f"audited cases: {res.seen}";
    assert "checking C-001 in preprocessing" in out, f"missing first audit: {out}";
    assert "checking C-002 in diagnostics" in out, f"missing second audit: {out}";
    assert "checking C-003 in codegen" in out, f"missing third audit: {out}";
    assert "cycle detected at case C-001" in out, f"missing cycle report: {out}";
}

test "fidelity audit reports invalid cases and artifact mismatches" {
    c1 = Case(
        case_id="C-001",
        subsystem="preprocessing",
        valid_program=True
    );
    c2 = Case(
        case_id="C-002",
        subsystem="diagnostics",
        valid_program=False
    );

    o1 = Observation(
        owner="preprocessing",
        normalized_match=True,
        authoritative=True
    );
    o2 = Observation(
        owner="diagnostics",
        normalized_match=False,
        authoritative=True
    );

    a1 = Artifact(
        artifact_kind="preprocessed",
        fingerprint="pp-c001",
        bytes_match=True,
        structure_match=True
    );
    a2 = Artifact(
        artifact_kind="object",
        fingerprint="obj-c002",
        bytes_match=False,
        structure_match=True
    );

    root ++> c1;
    root ++> c2;
    c1 +>:ObservedBy(channel="stdout/stderr"):+> o1;
    c2 +>:ObservedBy(channel="stdout/stderr"):+> o2;
    o1 +>:Captures(artifact_role="preprocessed output"):+> a1;
    o2 +>:Captures(artifact_role="emitted object"):+> a2;

    assert c2 in [root -->], f"invalid case is not reachable";
    assert o2 in [c2 ->:ObservedBy:->], f"diagnostic observation is missing";
    assert a2 in [o2 ->:Captures:->], f"object artifact is missing";
    assert a2.bytes_match == False, f"artifact mismatch was lost";
    assert a2.structure_match == True, f"artifact structure mismatch changed";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn FidelityAuditor();
    }
    out = buf.getvalue();

    assert "Fidelity audit started" in out, f"missing audit start: {out}";
    assert "case C-001: valid=True" in out, f"missing valid case: {out}";
    assert "case C-002: valid=False" in out, f"missing invalid case: {out}";
    assert "owner=diagnostics, normalized_match=False" in out, f"missing normalization mismatch: {out}";
    assert "object: bytes_match=False, structure_match=True" in out, f"missing artifact mismatch: {out}";
}

test "default fidelity fields remain matching and directed" {
    c1 = Case(case_id="C-010", subsystem="preprocessing");
    c2 = Case(case_id="C-011", subsystem="codegen");
    obs = Observation(owner="codegen");
    art = Artifact(artifact_kind="object");

    root ++> c1;
    c1 +>:DependsOn(reason="ordered compilation"):+> c2;
    c1 +>:ObservedBy(channel="artifact"):+> obs;
    obs +>:Captures(artifact_role="emitted object"):+> art;

    assert c2 in [c1 ->:DependsOn:->], f"forward dependency missing";
    assert c1 not in [c2 ->:DependsOn:->], f"dependency direction reversed";
    assert obs in [c1 ->:ObservedBy:->], f"observation edge missing";
    assert art in [obs ->:Captures:->], f"capture edge missing";

    assert c1.valid_program == True, f"default validity changed";
    assert c1.available == True, f"default availability changed";
    assert obs.normalized_match == True, f"default normalization changed";
    assert obs.authoritative == True, f"default authority changed";
    assert art.bytes_match == True, f"default byte match changed";
    assert art.structure_match == True, f"default structure match changed";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn FidelityAuditor();
    }
    out = buf.getvalue();

    assert "case C-010: valid=True" in out, f"missing default-valid case: {out}";
    assert "owner=codegen, normalized_match=True" in out, f"missing default observation: {out}";
    assert "object: bytes_match=True, structure_match=True" in out, f"missing default artifact: {out}";
}

