"""Provenance-aware observation graph with an honest unspecified default."""

node Observation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has content: str = "";
    has observation_source: str = "unspecified";
}

node FileAsset {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has original_filename: str = "";
    has content_hash: str = "";
}

node EmailMessage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gmail_message_id: str = "";
    has gmail_thread_id: str = "";
}

node Note {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
}

edge CatalogEntry {
}

edge EvidenceFor {
    has evidence_kind: str = "";
}

walker ProvenanceAudit {
    has records_seen: int = 0;

    can start with Root entry {
        print("Auditing observation provenance");
        visit [->:CatalogEntry:->] else {
            disengage;
        }
    }

    can inspect_file with FileAsset entry {
        self.records_seen += 1;
        print(f"[FILE] {here.title}: {here.original_filename}");
        print(f"       SHA-256: {here.content_hash}");
        visit [->:EvidenceFor:->] else {
            disengage;
        }
    }

    can inspect_email with EmailMessage entry {
        self.records_seen += 1;
        print(f"[EMAIL] {here.title}: {here.gmail_message_id}");
        print(f"        thread: {here.gmail_thread_id}");
        visit [->:EvidenceFor:->] else {
            disengage;
        }
    }

    can inspect_note with Note entry {
        self.records_seen += 1;
        print(f"[NOTE] {here.title}: {here.source}");
        visit [->:EvidenceFor:->] else {
            disengage;
        }
    }

    can inspect_observation with Observation entry {
        self.records_seen += 1;
        if here.observation_source == "unspecified" {
            print(f"[OBSERVATION] {here.title}: source unspecified");
        } else {
            print(f"[OBSERVATION] {here.title}: source={here.observation_source}");
        }
    }
}

