"""Model the plugin router move and expose the basename collision as a false cycle."""

node CodeModule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has basename: str = "";
    has route_prefix: str = "";
}

node BackendRouter(CodeModule) {
    has router_kind: str = "FastAPI";
}

node SdkPackage(CodeModule) {
    has import_style: str = "relative";
}

node SdkManager(CodeModule) {
    has manager_kind: str = "SDK";
}

edge Contains { }
edge Imports {
    has relation: str = "";
}

walker DependencyAuditor {
    has seen_paths: list[str] = [];
    has seen_basenames: list[str] = [];
    has collision_count: int = 0;

    can start with Root entry {
        print("Auditing the one-way backend-to-SDK dependency graph");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with CodeModule entry {
        if here.path in self.seen_paths {
            print(f"cycle guard stopped a repeat visit to {here.path}");
            disengage;
        }

        self.seen_paths.append(here.path);

        if here.basename in self.seen_basenames {
            self.collision_count += 1;
            print(f"basename collision only: {here.basename} at {here.path}");
        } else {
            self.seen_basenames.append(here.basename);
        }

        if here.route_prefix == "/plugins" {
            print(f"preserved route prefix /plugins in {here.path}");
        }

        print(f"visiting {here.path}");
        visit [->:Imports:->] else {
            print(f"no further imports from {here.path}");
            disengage;
        }
    }
}

with entry {
    backend_router = BackendRouter(
        title="plugin_manager",
        path="autobot-backend/api/plugin_manager_routes.py",
        basename="plugin_manager",
        route_prefix="/plugins"
    );
    sdk_package = SdkPackage(
        title="plugin_sdk",
        path="autobot_shared/plugin_sdk/__init__.py",
        basename="__init__",
        import_style="relative"
    );
    sdk_manager = SdkManager(
        title="plugin_manager",
        path="autobot_shared/plugin_sdk/plugin_manager.py",
        basename="plugin_manager"
    );

    root +>:Contains:+> backend_router;
    backend_router +>:Imports(relation="backend imports SDK package"):+> sdk_package;
    sdk_package +>:Imports(relation="relative sibling import"):+> sdk_manager;

    root spawn DependencyAuditor();
}
