"""A change entry reopens a task and cascades that state to completed ancestors."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has completed: bool = False;
    has completed_at: str = "";
}

node Actor {
    has name: str = "";
}

node ChangeEntry {
    has action: str = "";
    has note: str = "";
}

edge ParentOf { }
edge AuthoredBy { }
edge Affects { }

walker CascadingReopener {
    has seen_titles: list[str] = [];
    has reopened_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can reopen with Task entry {
        if here.title in self.seen_titles {
            print(f"cycle guard stopped at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            if here.completed {
                here.completed = False;
                here.completed_at = "";
                self.reopened_count += 1;
                print(f"reopened {here.title}");
            }
            visit [->:ParentOf:->] else { disengage; }
        }
    }
}

with entry {
    actor = Actor(name="reviewer");
    project = Task(title="Project", year=2025, completed=True, completed_at="2025-01-10");
    feature = Task(title="Feature", year=2025, completed=True, completed_at="2025-01-11");
    history_item = ChangeEntry(action="reopen", note="Subtask review");

    root ++> feature;
    feature +>:ParentOf:+> project;
    history_item +>:AuthoredBy:+> actor;
    history_item +>:Affects:+> feature;

    root spawn CascadingReopener();
    print(f"one history entry: {history_item.action} by {actor.name}");
    print(f"project completed: {project.completed}; feature completed: {feature.completed}");
}
