test "reopens completed task ancestors" {
    actor = Actor(name="reviewer");
    project = Task(title="Project", year=2025, completed=True, completed_at="2025-01-10");
    feature = Task(title="Feature", year=2025, completed=True, completed_at="2025-01-11");
    history_item = ChangeEntry(action="reopen", note="Subtask review");

    root ++> feature;
    feature +>:ParentOf:+> project;
    history_item +>:AuthoredBy:+> actor;
    history_item +>:Affects:+> feature;

    res = root spawn CascadingReopener();

    assert res.reopened_count == 2, f"got {res.reopened_count}";
    assert feature.completed == False, f"feature completed: {feature.completed}";
    assert feature.completed_at == "", f"feature timestamp: {feature.completed_at}";
    assert project.completed == False, f"project completed: {project.completed}";
    assert project.completed_at == "", f"project timestamp: {project.completed_at}";
    assert feature in [root-->], f"feature is not linked from root";
    assert project in [feature ->:ParentOf:->], f"project is not a parent";
}

test "reopens completed ancestors of an open task" {
    actor = Actor(name="maintainer");
    project = Task(title="Project", year=2025, completed=True, completed_at="2025-02-10");
    task = Task(title="New Task", year=2025, completed=False);
    history_item = ChangeEntry(action="add", note="Added open task");

    root ++> task;
    task +>:ParentOf:+> project;
    history_item +>:AuthoredBy:+> actor;
    history_item +>:Affects:+> task;

    res = root spawn CascadingReopener();

    assert res.reopened_count == 1, f"got {res.reopened_count}";
    assert task.completed == False, f"open task changed: {task.completed}";
    assert project.completed == False, f"project completed: {project.completed}";
    assert project.completed_at == "", f"project timestamp: {project.completed_at}";
    assert task in [history_item ->:Affects:->], f"history entry does not affect task";
}

test "stops safely on cyclic ancestry" {
    first = Task(title="First", year=2025, completed=True, completed_at="2025-03-10");
    second = Task(title="Second", year=2025, completed=True, completed_at="2025-03-11");
    history_item = ChangeEntry(action="reopen", note="Cyclic review");

    root ++> first;
    first +>:ParentOf:+> second;
    second +>:ParentOf:+> first;
    history_item +>:Affects:+> first;

    res = root spawn CascadingReopener();

    assert res.reopened_count == 2, f"got {res.reopened_count}";
    assert first.completed == False, f"first completed: {first.completed}";
    assert second.completed == False, f"second completed: {second.completed}";
    assert first in [second ->:ParentOf:->], f"cycle edge is missing";
}

