"""API-to-UI reachability audit using native Jac graph traversal."""

edge Contains { }
edge WiredTo { }

node AuditGroup {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ApiEndpoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has purpose: str = "";
    has ui_connected: bool = False;
}

node UiElement {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has action: str = "";
    has wired: bool = False;
}

walker ApiGapAuditor {
    has inspected: list[str] = [];
    has gaps: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can scan_group with AuditGroup entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_api with ApiEndpoint entry {
        if here.title in self.inspected {
            print(f"Cycle or duplicate ignored: {here.path}");
            disengage;
        } else {
            self.inspected = self.inspected + [here.title];

            if here.ui_connected {
                print(f"UI reachable: {here.path}");
                visit [->:WiredTo:->] else {
                    disengage;
                }
            } else {
                self.gaps = self.gaps + 1;
                print(f"UI GAP: {here.path} - {here.purpose}");
            }
        }
    }

    can confirm_ui with UiElement entry {
        if here.wired {
            print(f"  wired action: {here.action}");
        }
    }

    can summarize with Root exit {
        print(f"Audit complete: {self.gaps} API endpoints lack a reachable UI");
        report self.gaps;
    }
}

with entry {
    tms = AuditGroup(title="TMS API/UI audit", year=2024);
    root +>:Contains:+> tms;

    rfq = ApiEndpoint(
        title="Quote RFQ",
        year=2024,
        path="/api/quotes/rfq",
        purpose="price a shipment before tendering",
        ui_connected=False
    );
    dispatch = ApiEndpoint(
        title="Auto-dispatch",
        year=2024,
        path="/api/tenders/auto-dispatch",
        purpose="dispatch a batch tender",
        ui_connected=True
    );
    dispatch_button = UiElement(
        title="Dispatch Batch Tender",
        year=2024,
        action="Dispatch Batch Tender",
        wired=True
    );

    tms +>:Contains:+> rfq;
    tms +>:Contains:+> dispatch;
    dispatch +>:WiredTo:+> dispatch_button;

    root spawn ApiGapAuditor();
}
