"""Bounded LLC authorization over line managers and live project leads."""

node Company {
    has company_id: str = "";
    has name: str = "";
}

node Person {
    has user_id: str = "";
    has name: str = "";
    has company_id: str = "";
    has hop: int = -1;
    has processed_token: str = "";
}

node Project {
    has project_id: str = "";
    has name: str = "";
    has company_id: str = "";
    has active: bool = True;
    has hop: int = -1;
    has processed_token: str = "";
}

node Card {
    has card_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has company_id: str = "";
    has creator_id: str = "";
}

edge CreatedBy {}
edge LineManager {}
edge ReportsOn {}
edge ProjectLead {}

walker Authorization {
    has actor_id: str = "";
    has company_id: str = "";
    has target_card_id: str = "";
    has token: str = "";
    has granted: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can open with Company entry {
        visit [-->] else {
            disengage;
        }
    }

    can check with Card entry {
        if here.card_id == self.target_card_id
            and here.company_id == self.company_id {
            if here.creator_id != "" {
                for creator in [->:CreatedBy:->] {
                    if creator.user_id == here.creator_id
                        and creator.company_id == here.company_id {
                        creator.hop = 0;
                        creator.processed_token = "";
                        visit creator;
                    }
                }
            }
        }
    }

    can climb with Person entry {
        if here.processed_token != self.token {
            here.processed_token = self.token;

            if here.company_id == self.company_id {
                if here.user_id == self.actor_id {
                    self.granted = True;
                }

                if here.hop < 2 {
                    for manager in [->:LineManager:->] {
                        if manager.company_id == here.company_id {
                            manager_hop = here.hop + 1;
                            if manager.processed_token != self.token
                                or manager.hop > manager_hop {
                                manager.hop = manager_hop;
                                manager.processed_token = "";
                                visit manager;
                            }
                        }
                    }

                    for project in [->:ReportsOn:->] {
                        if project.company_id == here.company_id
                            and project.active {
                            project_hop = here.hop + 1;
                            if project_hop <= 2 {
                                project.hop = project_hop;
                                project.processed_token = "";
                                visit project;
                            }
                        }
                    }
                }
            }
        }
    }

    can follow with Project entry {
        if here.processed_token != self.token {
            here.processed_token = self.token;

            if here.active
                and here.company_id == self.company_id
                and here.hop < 2 {
                for lead in [->:ProjectLead:->] {
                    if lead.company_id == self.company_id {
                        lead_hop = here.hop + 1;
                        if lead_hop <= 2
                            and (lead.processed_token != self.token
                                or lead.hop > lead_hop) {
                            lead.hop = lead_hop;
                            lead.processed_token = "";
                            visit lead;
                        }
                    }
                }
            }
        }
    }
}

with entry {
    company = Company(company_id="acme", name="Acme");
    other_company = Company(company_id="other", name="Other");

    alice = Person(user_id="alice", name="Alice", company_id="acme");
    bob = Person(user_id="bob", name="Bob", company_id="acme");
    dana = Person(user_id="dana", name="Dana", company_id="acme");
    gina = Person(user_id="gina", name="Gina", company_id="acme");
    carol = Person(user_id="carol", name="Carol", company_id="acme");
    erin = Person(user_id="erin", name="Erin", company_id="acme");
    xavier = Person(user_id="xavier", name="Xavier", company_id="other");

    apollo = Project(
        project_id="apollo",
        name="Apollo",
        company_id="acme"
    );
    beacon = Project(
        project_id="beacon",
        name="Beacon",
        company_id="acme"
    );

    card = Card(
        card_id="card-1",
        title="Launch plan",
        year=2025,
        company_id="acme",
        creator_id="alice"
    );
    manager_card = Card(
        card_id="card-2",
        title="Manager plan",
