        year=2020,
        company_id="acme"
    );

    root ++> company;
    company ++> card;
    company ++> manager_card;
    company ++> legacy_card;

    card +>:CreatedBy:+> alice;
    manager_card +>:CreatedBy:+> bob;

    alice +>:LineManager:+> bob;
    bob +>:LineManager:+> dana;
    dana +>:LineManager:+> gina;
