"""Platform verification graph with explicit dependency traversal and cycle guard."""

node PlatformHandle {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has rule_count: int = 0;
}

node LocalHarness {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fake_dispatch: bool = False;
}

node VerificationSuite {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has assertion_count: int = 0;
}

edge Dependency {
    has reason: str = "";
}

walker CycleAuditor {
    has depth: int = 0;
