"""Model a Codex shell tool call and bound recursive process growth."""

node ToolCall {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tool_name: str = "";
    has request: str = "";
}

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has command: str = "";
    has shell: bool = False;
    has suspicious: bool = False;
}

edge BeginsCall { }

edge Executes {
    has mode: str = "";
}

edge Spawned {
    has reason: str = "";
}

walker ProcessAudit {
    has visited_count: int = 0;
    has depth: int = 0;
    has max_depth: int = 2;

    can start with Root entry {
        print("audit: following one tool call into its process tree");
        visit [->:BeginsCall:->] else { disengage; }
    }

    can inspect_call with ToolCall entry {
        print(f"tool={here.tool_name} request={here.request}");
        visit [->:Executes:->] else { disengage; }
    }

    can inspect_process with Process entry {
        self.visited_count += 1;
        print(f"pid={here.pid} command={here.command}");

        if here.suspicious {
            print("warning: recursive shell growth detected");
        }

        if self.depth >= self.max_depth {
            print("depth guard stopped further spawning");
            disengage;
        } else {
            self.depth += 1;
            visit [->:Spawned:->] else { disengage; }
        }
    }
}

with entry {
    call = ToolCall(
        title="shell tool call",
        request="run git status",
        tool_name="bash"
    );
