    has status: str = "open";
}

node ApprovalDecision {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has actor: str = "";
    has decided_at: str = "";
    has comments: str = "";
    has target_hash: str = "";
    has outcome: str = "";
}

node WorkOrder {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has order_id: str = "";
    has art_gate: str = "open";
    has evidence_locked: bool = False;
    has revision_task: str = "none";
}

edge Contains { }
edge Presents {
    has issued_at: str = "";
    has expires_at: str = "";
}
edge Records { }
edge Controls {
    has relation: str = "";
}
edge Revises { }

walker ProofAuditor {
    has presented_hash: str = "";
    has presented_locked: bool = False;
    has exact_approval: bool = False;

    can begin with Root entry {
        print("Auditing proof targets and revision history");
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_request with ProofRequest entry {
        print(f"{here.request_id} targets {here.target_hash}");
        visit [->:Presents:->] else { disengage; }
    }

    can inspect_mockup with MockupVersion entry {
        self.presented_hash = here.render_hash;
        self.presented_locked = here.locked;
        print(f"{here.version_label} rendered as {here.render_hash}");
        visit [->:Records:->] else { disengage; }
    }

    can inspect_decision with ApprovalDecision entry {
        self.exact_approval = False;
        if here.target_hash == self.presented_hash {
            if self.presented_locked {
                if here.outcome == "approve" {
                    self.exact_approval = True;
                }
            }
        }
        if self.exact_approval {
            print(f"{here.actor} approved exact version at {here.decided_at}");
        } else {
            print(f"{here.actor} requested changes; history kept: {here.comments}");
        }
        visit [->:Controls:->] else { disengage; }
    }

    can update_order with WorkOrder entry {
        if self.exact_approval {
            here.art_gate = "cleared";
            here.evidence_locked = True;
            here.revision_task = "none";
            print(f"{here.order_id}: art gate cleared and evidence locked");
        } else {
            here.art_gate = "open";
            here.evidence_locked = False;
            here.revision_task = "draft revision";
            print(f"{here.order_id}: draft revision task created");
        }
        visit [-->] else { disengage; }
    }
}

