"""Asset catalog demo with typed dependencies, invalidation, and cycle detection."""

node Asset {
    has asset_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has invalidated: bool = False;
    has change_generation: int = 0;
    has visit_mark: int = 0;
}

node Mesh(Asset) {
    has vertex_count: int = 0;
}

node Material(Asset) {
    has shader_name: str = "";
}

node Texture(Asset) {
    has width: int = 0;
    has height: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker AssetInvalidator {
    has run_id: int = 1;
    has visited_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Starting asset invalidation walk");
        visit [-->] else {
            disengage;
        }
    }

    can invalidate with Mesh | Material | Texture entry {
        if here.visit_mark == self.run_id {
            print(f"Cycle detected at {here.asset_id}");
            self.cycle_found = True;
            disengage;
        } else {
            here.visit_mark = self.run_id;
            here.invalidated = True;
            here.change_generation = here.change_generation + 1;
            self.visited_count = self.visited_count + 1;
            print(f"Invalidated {here.asset_id}: {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can summarize with Root exit {
        print(f"Visited assets: {self.visited_count}");
        print(f"Cycle found: {self.cycle_found}");
    }
}

with entry {
    mesh = Mesh(
        asset_id="mesh.hero",
        title="Hero Mesh",
        year=2024,
        vertex_count=12000
    );
    material = Material(
        asset_id="material.hero",
        title="Hero Material",
        year=2024,
        shader_name="lit"
    );
    texture = Texture(
        asset_id="texture.hero",
        title="Hero Albedo",
        year=2024,
        width=2048,
        height=2048
    );

    root ++> mesh;
    mesh +>:DependsOn(reason="render material"):+> material;
    material +>:DependsOn(reason="base color texture"):+> texture;
    texture +>:DependsOn(reason="preview feedback cycle"):+> material;

    root spawn AssetInvalidator(run_id=7);
}
