    has available: bool = True;
    has source: str = "";
}

node Runner {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has timeout_ms: int = 0;
    has output_limit: int = 0;
}

node Context {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cache_key: str = "";
    has stale: bool = False;
}

edge Contains {
    has slot: str = "";
}

edge Executes {
    has timeout_ms: int = 0;
    has output_limit: int = 0;
}

edge Projects {
    has source_path: str = "";
}

edge Invalidates {
    has reason: str = "";
}

walker ContextAuditor {
    has seen: list[str] = [];
    has steps: int = 0;
    has step_limit: int = 12;

    can start with Root entry {
        print("auditing repository context dependencies");
        visit [-->] else {
            disengage;
        }
