"""Audit dispatch board with typed relationships and cycle-safe traversal."""

node WorkItem {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Lane(WorkItem) {
    has owner: str = "";
}

node Issue(WorkItem) {
    has state: str = "";
}

node Evidence(WorkItem) {
    has kind: str = "";
}

edge Dispatch {
    has owner: str = "";
}

edge Dependency {
    has reason: str = "";
}

edge EvidenceLink {
    has kind: str = "";
}

walker AuditBoard {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Auditing the current-main dispatch board");
        visit [->:Dispatch:->] else { disengage; }
    }

    can inspect_lane with Lane entry {
        print(f"lane {here.title} owned by {here.owner}");
        visit [->:Dispatch:->] else { disengage; }
    }

    can inspect_issue with Issue entry {
        if here.key in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at {here.key}");
        } else {
            self.seen.append(here.key);
            print(f"issue {here.key}: {here.title} [{here.state}]");
            visit [->:Dependency:->] else {
                print(f"no dependencies for {here.key}");
            }
            visit [->:EvidenceLink:->] else {
                print(f"no evidence attached to {here.key}");
            }
        }
    }

    can inspect_evidence with Evidence entry {
        print(f"evidence {here.key}: {here.kind}");
    }
}

with entry {
    lane_a = Lane(key="A", title="Evidence integrity", year=2026, owner="C");
    lane_b = Lane(key="B", title="Semantic launch", year=2026, owner="B");

    issue_c = Issue(
        key="#179",
        title="Synthetic UNKNOWN evidence",
        year=2026,
        state="blocked"
    );

    issue_b = Issue(
        key="#178",
        title="Machine-model launch mapping",
        year=2026,
        state="ready"
    );

    evidence_c = Evidence(
        key="smoke-179",
        title="paired smoke",
        year=2026,
        kind="smoke record"
    );

    evidence_b = Evidence(
        key="resume-178",
        title="resume semantics",
        year=2026,
        kind="launch trace"
    );

    root +>:Dispatch(owner="evidence lane"):+> lane_a;
    root +>:Dispatch(owner="semantic lane"):+> lane_b;
    lane_a +>:Dispatch(owner="evidence owner"):+> issue_c;
    lane_b +>:Dispatch(owner="semantic owner"):+> issue_b;

    issue_b +>:Dependency(reason="launch evidence is needed"):+> issue_c;
    issue_c +>:Dependency(reason="audit result feeds launch review"):+> issue_b;

    issue_b +>:EvidenceLink(kind="paired trace"):+> evidence_b;
    issue_c +>:EvidenceLink(kind="smoke record"):+> evidence_c;

    root spawn AuditBoard();
}
