"""Canonical host-native delegation lineage with explicit cycle-safe re-entry."""

node Assignment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has assignment_id: str = "";
    has subject_id: str = "";
    has target: str = "";
    has scope: str = "";
