"""Native object-level authorization audit with deny precedence and default deny."""

node Request {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has method: str = "GET";
    has path: str = "";
    has target_type: str = "object";
    has seen: bool = False;
}

node Principal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has active: bool = True;
    has seen: bool = False;
}

node Statement {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has effect: str = "";
    has target_type: str = "";
    has method: str = "";
    has path: str = "";
    has condition_ok: bool = True;
    has seen: bool = False;
}

node Resource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has seen: bool = False;
}

edge Carries { }
edge PolicyOf { }
edge Protects { }

walker AuthorizationAuditor {
    has request_method: str = "";
    has request_path: str = "";
    has request_target: str = "";
    has allow_hits: int = 0;
    has deny_hits: int = 0;
    has object_matches: int = 0;
    has decision: str = "DENY";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_request with Request entry {
        if here.seen {
            disengage;
        } else {
            here.seen = True;
            self.request_method = here.method;
            self.request_path = here.path;
            self.request_target = here.target_type;
            visit [->:Carries:->] else {
                disengage;
            }
        }
    }

    can inspect_principal with Principal entry {
        if here.seen {
            disengage;
        } else {
            here.seen = True;
            if here.active {
                visit [-->] else {
                    disengage;
                }
            } else {
                disengage;
            }
        }
    }

    can inspect_statement with Statement entry {
        if here.seen {
            disengage;
        } else {
            here.seen = True;
            valid_effect = here.effect == "allow" or here.effect == "deny";
            valid_target = here.target_type == self.request_target;
            method_matches = here.method == "*" or here.method == self.request_method;
            path_matches = here.path == self.request_path;

            if valid_effect and valid_target and method_matches and path_matches and here.condition_ok {
                if here.effect == "deny" {
                    self.deny_hits += 1;
                } else {
                    self.allow_hits += 1;
                }
            }
        }
    }

    can inspect_resource with Resource entry {
        if here.seen {
            disengage;
        } else {
            here.seen = True;
            if here.path == self.request_path {
                self.object_matches += 1;
            }
        }
    }

    can summarize with Root exit {
        if self.deny_hits > 0 {
            self.decision = "DENY";
        } else {
            if self.allow_hits > 0 {
                self.decision = "ALLOW";
            } else {
                self.decision = "DENY";
            }
        }

        print(f"request {self.request_method} {self.request_path}: {self.decision}");
        print(f"matching allows={self.allow_hits}, denies={self.deny_hits}");
        if self.decision == "ALLOW" and self.object_matches > 0 {
            print("object is visible");
        } else {
            print("object is hidden; authorization failed closed");
        }
    }
}

with entry {
    request = Request(
        title="Read quarterly report",
        method="GET",
        path="/reports/42",
        target_type="object"
    );
    principal = Principal(title="Analyst", name="sam");
    allow_policy = Statement(
        title="Report reader",
        effect="allow",
        target_type="object",
        method="GET",
        path="/reports/42"
    );
    deny_policy = Statement(
        title="Suspended report access",
        effect="deny",
        target_type="object",
        method="GET",
        path="/reports/42"
    );
    malformed_policy = Statement(
        title="Malformed policy",
        effect="ALLOW",
        target_type="object",
        method="GET",
        path="/reports/42"
    );
    resource = Resource(title="Quarterly report", path="/reports/42");

    root +>:Carries:+> request;
    request +>:Carries:+> principal;
    principal +>:PolicyOf:+> allow_policy;
    principal +>:PolicyOf:+> deny_policy;
    principal +>:PolicyOf:+> malformed_policy;
    principal +>:Protects:+> resource;

    root spawn AuthorizationAuditor();
}
