import io;
import from contextlib { redirect_stdout }

test "classifies an impossible queue timeout" {
    lock = GatewayLock(lock_name="GatewayTestSuiteLock", held=True);
    holder = TestRun(
        run_name="healthy-holder",
        expected_duration_minutes=48.88,
        tests_executed=3235,
        acquired=True
    );
    queued = TestRun(
        run_name="second-run",
        max_wait_minutes=45.0,
        expected_duration_minutes=48.88,
        tests_executed=0,
        acquired=False
    );
    suite = TestSuite(
        assembly_name="CcDirector.Gateway.Tests",
        planned_tests=3235
    );

    root ++> lock;
    lock ++> holder;
    lock +>:Queues(position=1):+> queued;
    holder +>:Executes:+> suite;
    queued +>:Targets:+> suite;

    assert len([root-->]) == 1, f"root children: {len([root-->])}";
    assert queued in [lock ->:Queues:->], f"queued run missing from queue";
    assert holder in [lock-->], f"holder missing from lock graph";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LockAuditor();
    }
    out = buf.getvalue();

    assert res.observed_runs == 2, f"observed runs: {res.observed_runs}";
    assert queued.diagnostic == "QUEUE_TIMEOUT",
        f"diagnostic: {queued.diagnostic}";
    assert "second-run: zero tests" in out, f"missing queue output: {out}";
    assert "QUEUE_TIMEOUT" in out, f"missing timeout classification: {out}";
}

test "treats nonzero execution as a real result" {
    lock = GatewayLock(lock_name="GatewayTestSuiteLock", held=True);
    failed = TestRun(
        run_name="failed-run",
        max_wait_minutes=45.0,
        expected_duration_minutes=48.88,
        tests_executed=7,
        acquired=False
    );

