    lock ++> failed;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LockAuditor();
    }
    out = buf.getvalue();

    assert res.observed_runs == 1, f"observed runs: {res.observed_runs}";
    assert failed.diagnostic == "REAL_TEST_RESULT",
        f"diagnostic: {failed.diagnostic}";
    assert "failed-run: 7 tests executed" in out,
        f"missing result output: {out}";
    assert "inspect named failures" in out,
        f"missing failure guidance: {out}";
}

test "keeps a queue open when the wait covers the run" {
    lock = GatewayLock(lock_name="GatewayTestSuiteLock", held=True);
    waiting = TestRun(
        run_name="long-wait-run",
        max_wait_minutes=60.0,
        expected_duration_minutes=48.88,
        tests_executed=0,
        acquired=False
    );

    root ++> lock;
    lock +>:Queues(position=1):+> waiting;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LockAuditor();
    }
    out = buf.getvalue();

    assert res.observed_runs == 1, f"observed runs: {res.observed_runs}";
    assert waiting.diagnostic == "QUEUE_WAIT",
        f"diagnostic: {waiting.diagnostic}";
    assert "still waiting for the lock" in out,
        f"missing waiting output: {out}";
}

