"""Native package dependency walk with cycle-safe reachability analysis."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has checked: bool = False;
}

edge DependsOn {
    has label: str = "";
}

walker DependencyAuditor {
    has package_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Package entry {
        if here.checked {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            here.checked = True;
            self.package_count += 1;
            print(f"auditing {here.title} ({here.year})");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
