    metrics = Package(title="modulegraph metrics", year=2024);
    schema = Package(title="JSON schema", year=2024);
    cli = Package(title="analyze CLI", year=2024);

    root ++> app;
    app +>:DependsOn(label="computes"):+> metrics;
    metrics +>:DependsOn(label="validates"):+> schema;
    schema +>:DependsOn(label="documents"):+> cli;
    cli +>:DependsOn(label="reports"):+> metrics;

    root spawn DependencyAuditor();
}
