"""Native dependency-graph demo with typed edges and cycle detection."""

node Cell {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sheet: str = "Sheet1";
    has a1: str = "";
    has formula: str = "";
}

edge Contains {
    has scope: str = "formula";
}

edge DependsOn {
    has relationship: str = "precedent";
}

walker CycleScanner {
    has path: list[str] = [];
    has cycle_cells: list[str] = [];
    has max_nodes: int = 10;
    has truncated: bool = False;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Cell entry {
        if here.a1 in self.path {
            for cell_name in self.path {
                if len(self.cycle_cells) < self.max_nodes {
                    self.cycle_cells = self.cycle_cells + [cell_name];
                } else {
                    self.truncated = True;
                }
            }
            print(f"cycle detected at {here.sheet}!{here.a1}");
            disengage;
        }

        self.path = self.path + [here.a1];
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    first = Cell(
        title="Revenue",
        a1="A1",
        formula="=B1",
    );
    second = Cell(
        title="Cost",
        a1="B1",
        formula="=C1",
    );
    third = Cell(
        title="Margin",
        a1="C1",
        formula="=A1",
    );

    root +>:Contains(scope="formula"):+> first;
    first +>:DependsOn(relationship="precedent"):+> second;
    second +>:DependsOn(relationship="precedent"):+> third;
    third +>:DependsOn(relationship="precedent"):+> first;

    scanner = CycleScanner(max_nodes=10);
    root spawn scanner;

    print(f"cycleCells: {scanner.cycle_cells}");
    print(f"truncated: {scanner.truncated}");
}
```

