test "detects all cells in a dependency cycle" {
    first = Cell(title="Revenue", a1="A1", formula="=B1");
    second = Cell(title="Cost", a1="B1", formula="=C1");
    third = Cell(title="Margin", a1="C1", formula="=A1");

    root +>:Contains(scope="formula"):+> first;
    first +>:DependsOn(relationship="precedent"):+> second;
    second +>:DependsOn(relationship="precedent"):+> third;
    third +>:DependsOn(relationship="precedent"):+> first;

    assert len([root-->]) == 1, f"got {len([root-->])}";
    assert first in [root ->:Contains:->], f"missing root containment edge";
    assert second in [first ->:DependsOn:->], f"missing A1 dependency";
    assert third in [second ->:DependsOn:->], f"missing B1 dependency";
    assert first in [third ->:DependsOn:->], f"missing C1 dependency";

    res = root spawn CycleScanner(max_nodes=10);

    assert res.cycle_cells == ["A1", "B1", "C1"], f"got {res.cycle_cells}";
    assert res.truncated == False, f"got {res.truncated}";
}

